(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("appian-civil-wars-2-e", [{"sp": "HDR", "t": "Ῥωμαϊκῶν Ἐμφυλίων Γʹ–Εʹ"}, {"sp": "HDR", "t": "Ἐμφυλίων Γʹ", "st": "3"}, {"sp": "N", "t": "οὕτω μὲν δὴ Γάιος Καῖσαρ πλείστου Ῥωμαίοις ἄξιος ἐς τὴν ἡγεμονίαν γενόμενος ὑπὸ τῶν ἐχθρῶν ἀνῄρητο καὶ ὑπὸ τοῦ δήμου τέθαπτο· ἁπάντων δὲ αὐτοῦ τῶν σφαγέων δίκην δόντων, ὅπως οἱ περιφανέστατοι μάλιστα ἔδοσαν, ἥδε ἡ βίβλος καὶ ἡ μετὰ τήνδε ἐπιδείξουσιν, ἐπιλαμβάνουσαι καὶ ὅσα ἄλλα Ῥωμαίοις ἐμφύλια ἐς ἀλλήλους ἐγίγνετο ὁμοῦ.", "st": "3.1"}, {"sp": "N", "t": "Ἀντώνιον μὲν ἡ βουλὴ δι’ αἰτίας εἶχεν ἐπὶ τοῖς ἐπιταφίοις τοῦ Καίσαρος, ὑφ’ ὧν δὴ μάλιστα ὁ δῆμος ἐρεθισθεὶς ὑπερεῖδε τῆς ἄρτι ἐπεψηφισμένης ἀμνηστίας καὶ ἐπὶ τὰς οἰκίας τῶν σφαγέων σὺν πυρὶ ἔδραμον· ὁ δὲ αὐτὴν χαλεπαίνουσαν ἑνὶ τοιῷδε πολιτεύματι ἐς εὔνοιαν ἑαυτοῦ μετέβαλεν. Ἀμάτιος ἦν ὁ Ψευδομάριος· Μαρίου γὰρ ὑπεκρίνετο υἱωνὸς εἶναι καὶ διὰ Μάριον ὑπερήρεσκε τῷ δήμῳ. γιγνόμενος οὖν κατὰ τήνδε τὴν ὑπόκρισιν συγγενὴς τῷ Καίσαρι, ὑπερήλγει μάλιστα αὐτοῦ τεθνεῶτος καὶ βωμὸν ἐπῳκοδόμει τῇ πυρᾷ καὶ χεῖρα θρασυτέρων ἀνδρῶν εἶχε καὶ φοβερὸς ἦν ἀεὶ τοῖς σφαγεῦσιν· ὧν οἱ μὲν ἄλλοι διεπεφεύγεσαν ἐκ τῆς πόλεως καὶ ὅσοι παρ’ αὐτοῦ Καίσαρος εἰλήφεσαν ἡγεμονίας ἐθνῶν, ἀπεληλύθεσαν ἐπὶ τὰς ἡγεμονίας, Βροῦτος μὲν ὁ Δέκμος ἐς τὴν ὅμορον τῆς Ἰταλίας Κελτικήν, Τρεβώνιος δὲ ἐς τὴν Ἀσίαν τὴν περὶ Ἰωνίαν, Τίλλιος δὲ Κίμβερ ἐς Βιβυνίαν· Κάσσιος δὲ καὶ Βροῦτος ὁ Μᾶρκος, ὧν δὴ καὶ μάλιστα τῇ βουλῇ διέφερεν, ᾕρηντο μὲν καὶ οἵδε ὑπὸ τοῦ Καίσαρος ἐς τὸ μέλλον ἔτος ἡγεμονεύειν, Συρίας μὲν ὁ Κάσσιος καὶ Μακεδονίας ὁ Βροῦτος, ἔτι δὲ ὄντες ἀστικοὶ στρατηγοὶ … ὑπ’ ἀνάγκης καὶ διατάγμασιν οἷα στρατηγοὶ τοὺς κληρούχους ἐθεράπευον, ὅσοις τε ἄλλοις ἐπενόουν, καὶ τὰ κληρουχήματα συγχωροῦντες αὐτοῖς πιπράσκειν, τοῦ νόμου κωλύοντος ἐντὸς εἴκοσιν ἐτῶν ἀποδίδοσθαι.", "st": "3.2"}, {"sp": "N", "t": "τούτοις δὲ αὐτοῖς ὁ Ἀμάτιος, ὅτε συντύχοι, καὶ ἐνεδρεύσειν ἐλέγετο. τῷδε οὖν τῷ λόγῳ τῆς ἐνέδρας ὁ Ἀντώνιος ἐπιβαίνων οἷα ὕπατος συλλαμβάνει καὶ κτείνει τὸν Ἀμάτιον χωρὶς δίκης, μάλα θρασέως· καὶ ἡ βουλὴ τὸ μὲν ἔργον ἐθαύμαζεν ὡς μέγα καὶ παράνομον, τὴν δὲ χρείαν αὐτοῦ προσεποιοῦντο ἥδιστα· οὐ γὰρ αὐτοῖς ἐδόκει ποτὲ χωρὶς τοιᾶσδε τόλμης ἀσφαλῆ τὰ κατὰ Βροῦτον καὶ Κάσσιον ἔσεσθαι. οἱ δὲ τοῦ Ἀματίου στασιῶται καὶ ὁ ἄλλος δῆμος ἐπ’ ἐκείνοις πόθῳ τε τοῦ Ἀματίου καὶ ἀγανακτήσει τοῦ γεγονότος, ὅτι μάλιστα αὐτὸ ὁ Ἀντώνιος ἐπεπράχει ὑπὸ τοῦ δήμου τιμώμενος, οὐκ ἠξίουν σφῶν καταφρονεῖν· τὴν ἀγορὰν οὖν καταλαβόντες ἐβόων καὶ τὸν Ἀντώνιον ἐβλασφήμουν καὶ τὰς ἀρχὰς ἐκέλευον ἀντὶ Ἀματίου τὸν βωμὸν ἐκθεοῦν καὶ θύειν ἐπ’ αὐτοῦ Καίσαρι πρώτους. ἐξελαυνόμενοι δ’ ἐκ τῆς ἀγορᾶς ὑπὸ στρατιωτῶν ἐπιπεμφθέντων ὑπὸ Ἀντωνίου μᾶλλόν τε ἠγανάκτουν καὶ ἐκεκράγεσαν καὶ ἕδρας ἔνιοι τῶν Καίσαρος ἀνδριάντων ἐπεδείκνυον ἀνῃρημένων. ὡς δέ τις αὐτοῖς ἔφη καὶ τὸ ἐργαστήριον, ἔνθα οἱ ἀνδριάντες ἀνεσκευάζοντο, δείξειν, εὐθὺς εἵποντο καὶ ἰδόντες ἐνεπίμπρασαν, ἕως ἑτέρων ἐπιπεμφθέντων ἐξ Ἀντωνίου ἀμυνόμενοί τε ἀνῃρέθησαν ἔνιοι καὶ συλληφθέντες ἕτεροι ἐκρεμάσθησαν, ὅσοι θεράποντες ἦσαν, οἱ δὲ ἐλεύθεροι κατὰ τοῦ κρημνοῦ κατερρίφησαν.", "st": "3.3"}, {"sp": "N", "t": "καὶ ὁ μὲν τάραχος ἐπέπαυτο, μῖσος δὲ ἄρρητον ἐξ ἀρρήτου εὐνοίας τοῦ δήμου πρὸς τὸν Ἀντώνιον ἐγήγερτο. ἡ βουλὴ δ’ ἔχαιρον ὡς οὐκ ἂν ἑτέρως ἐν ἀδεεῖ περὶ τῶν ἀμφὶ τὸν Βροῦτον γενόμενοι. ὡς δὲ καὶ Σέξστον Πομπήιον ὁ Ἀντώνιος, τὸν Πομπηίου Μάγνου περιποθήτου πᾶσιν ἔτι ὄντος, εἰσηγήσατο καλεῖν ἐξ Ἰβηρίας, πολεμούμενον ἔτι πρὸς τῶν Καίσαρος στρατηγῶν, ἀντί τε τῆς πατρῴας οὐσίας δεδημευμένης ἐκ τῶν κοινῶν αὐτῷ δοθῆναι μυριάδας Ἀττικῶν δραχμῶν πεντακισχιλίας, εἶναι δὲ καὶ στρατηγὸν ἤδη τῆς θαλάσσης, καθὼς ἦν καὶ ὁ πατὴρ αὐτοῦ, καὶ ταῖς Ῥωμαίων ναυσὶν αὐτίκα ταῖς πανταχοῦ χρῆσθαι εἰς τὰ ἐπείγοντα, θαυμάζουσα ἕκαστα ἡ βουλὴ μετὰ προθυμίας ἐξεδέχετο καὶ τὸν Ἀντώνιον ἐπὶ ὅλην εὐφήμουν ἡμέραν· οὐ γάρ τις αὐτοῖς ἐδόκει Μάγνου γενέσθαι δημοκρατικώτερος, ὅθεν οὐδὲ περιποθητότερος ἦν. ὅ τε Κάσσιος καὶ ὁ Βροῦτος, ἐκ τῆς στάσεως ὄντε τῆς Μάγνου καὶ πᾶσι τότε τιμιωτάτω, τὴν σωτηρίαν ἐδόκουν ἕξειν ἀσφαλῆ καὶ τὴν γνώμην ὧν ἐπεπράχεσαν ἐγκρατῆ, καὶ τὴν δημοκρατίαν ἐς τέλος ἐπάξεσθαι, τῆς μοίρας σφῶν ἀνισχούσης. ἃ καὶ Κικέρων συνεχῶς ἐπῄνει τὸν Ἀντώνιον· καὶ ἡ βουλὴ συγγινώσκουσα αὐτῷ διὰ σφᾶς ἐπιβουλεύοντα τὸν δῆμον ἔδωκε φρουρὰν περιστήσασθαι περὶ τὸ σῶμα, ἐκ τῶν ἐστρατευμένων καὶ ἐπιδημούντων ἑαυτῷ καταλέγοντα.", "st": "3.4"}, {"sp": "N", "t": "ὁ δέ, εἴτε εἰς τοῦτο αὐτὸ πάντα πεπραχὼς εἴτε τὴν συντυχίαν ὡς εὔχρηστον ἀσπασάμενος τὴν φρουρὰν κατέλεγεν, αἰεὶ προστιθεὶς μέχρι ἐς ἑξακισχιλίους, οὐκ ἐκ τῶν γινομένων ὁπλιτῶν, οὓς εὐμαρῶς ἂν ἐν ταῖς χρείαις ᾤετο ἕξειν καὶ ἑτέρωθεν, ἀλλὰ πάντας λοχαγοὺς ὡς ἡγεμονικούς τε καὶ ἐμπειροπολέμους καί οἱ γνωρίμους ἐκ τῆς στρατείας τῆς ὑπὸ Καίσαρι· ταξιάρχους δ’ αὐτοῖς ἐς τὸν πρέποντα κόσμον ἐξ αὐτῶν ἐκείνων ἐπιστήσας ἦγεν ἐν τιμῇ καὶ κοινωνοὺς ἐποιεῖτο τῶν φανερῶν βουλευμάτων. ἡ δὲ βουλὴ τό τε πλῆθος αὐτῶν καὶ τὴν ἐπίλεξιν ἐν ὑπονοίᾳ τιθέμενοι συνεβούλευον τὴν φρουρὰν ὡς ἐπίφθονον ἐς τὸ ἀρκοῦν ἐπαναγαγεῖν. ὁ δὲ ὑπισχνεῖτο ποιήσειν, ὅταν σβέσῃ τοῦ δήμου τὸ ταραχῶδες. ἐψηφισμένον δ’ εἶναι κύρια, ὅσα Καίσαρι πέπρακτό τε καὶ γενέσθαι βεβούλευτο, τὰ ὑπομνήματα τῶν βεβουλευμένων ὁ Ἀντώνιος ἔχων καὶ τὸν γραμματέα τοῦ Καίσαρος Φαβέριον ἐς πάντα οἱ πειθόμενον, διότι καὶ ὁ Καῖσαρ τὰ τοιάδε αἰτήματα ἐς τὸν Ἀντώνιον ἐξιὼν ἀνετίθετο, πολλὰ ἐς πολλῶν χάριν προσετίθει καὶ ἐδωρεῖτο πόλεσι καὶ δυνάσταις καὶ τοῖσδε τοῖς ἑαυτοῦ φρουροῖς· καὶ ἐπεγράφετο μὲν πᾶσι τὰ Καίσαρος ὑπομνήματα, τὴν δὲ χάριν οἱ λαβόντες ᾔδεσαν Ἀντωνίῳ. τῷ δὲ αὐτῷ τρόπῳ καὶ ἐς τὸ βουλευτήριον πολλοὺς κατέλεγε καὶ ἄλλα τῇ βουλῇ δι’ ἀρεσκείας ἔπρασσεν, ἵνα μὴ φθονοῖεν ἔτι τῆς φρουρᾶς.", "st": "3.5"}, {"sp": "N", "t": "καὶ Ἀντώνιος μὲν ἀμφὶ ταῦτα ἦν, ὁ δὲ Βροῦτος καὶ ὁ Κάσσιος, οὔτε τινὸς παρὰ τοῦ δήμου σφίσιν ἢ παρὰ τῶν ἐξεστρατευμένων εἰρηναίου φανέντος, οὔτε τὴν ἐνέδραν Ἀματίου καὶ παρ’ ἑτέρου ἂν αὑτοῖς ἀδύνατον ἡγούμενοι γενέσθαι, οὔτε τὸ ποικίλον Ἀντωνίου φέροντες ἀφόβως, ἤδη καὶ στρατιὰν ἔχοντος, οὔτε τὴν δημοκρατίαν βεβαιουμένην ἔργοις ὁρῶντες, ἀλλὰ καὶ ἐς τοῦτο ὑφορώμενοι τὸν Ἀντώνιον, Δέκμῳ μάλιστα ἐπεποίθεσαν, ἔχοντι ἐν πλευραῖς τρία τέλη στρατοῦ, καὶ πρὸς Τρεβώνιον ἐς τὴν Ἀσίαν καὶ πρὸς Τίλλιον ἐς Βιθυνίαν κρύφα ἔπεμπον χρήματα ἀγείρειν ἀφανῶς καὶ στρατὸν περιβλέπεσθαι. αὐτοί τε ἠπείγοντο τῶν δεδομένων σφίσιν ὑπὸ τοῦ Καίσαρος ἐθνῶν λαβέσθαι. τοῦ χρόνου δὲ οὔπω συγχωροῦντος αὐτοῖς, ἀπρεπὲς ἡγούμενοι, τὴν ἐν ἄστει στρατηγίαν προλιπόντες ἀτελῆ, δόξαν ὕποπτον φιλαρχίας ἐθνῶν ἐνέγκασθαι, ᾑροῦντο ὅμως ὑπὸ ἀνάγκης τὸ ἐν μέσῳ διάστημα διατρῖψαί ποι μᾶλλον ἰδιωτεύοντες ἢ ἐν ἄστει στρατηγεῖν, οὔτε ἀφόβως ἔχοντες οὔτε τὰ εἰκότα ἐφ’ οἷς ὑπὲρ τῆς πατρίδος ἐπεπράχεσαν τιμώμενοι. οὕτω δ’ αὐτοῖς ἔχουσιν ἡ βουλὴ συνειδυῖα τὴν γνώμην ἔδωκε σίτου τῇ πόλει φροντίσαι, ἐξ ὅσης δύναιντο γῆς, μέχρις αὐτοὺς ὁ χρόνος τῶν ἐθνῶν τῆς στρατηγίας καταλάβοι.", "st": "3.6"}, {"sp": "N", "t": "καὶ ἡ μὲν οὕτως ἔπραξεν, ἵνα μή ποτε Βροῦτος ἢ Κάσσιος φεύγειν δοκοῖεν· τοσήδε αὐτῶν φροντὶς ἦν ἅμα καὶ αἰδώς, ἐπεὶ καὶ τοῖς ἄλλοις σφαγεῦσι διὰ τούσδε μάλιστα συνελάμβανον· ἐξελθόντων δὲ τῆς πόλεως τῶν ἀμφὶ τὸν Βροῦτον, ἐπὶ δυναστείας ὢν ὁ Ἀντώνιος ἤδη μοναρχικῆς ἀρχὴν ἔθνους καὶ στρατιᾶς αὑτῷ περιέβλεπε· καὶ Συρίας μὲν ἐπεθύμει μάλιστα, οὐκ ἠγνόει δὲ ὢν δι’ ὑπονοίας καὶ μᾶλλον ἐσόμενος, εἴ τι αἰτοίη· καὶ γὰρ αὐτῷ κρύφα Δολοβέλλαν τὸν ἕτερον ὕπατον ἐπήλειφεν εἰς ἐναντίωσιν ἡ βουλή, διάφορον αἰεὶ τῷ Ἀντωνίῳ γενόμενον. αὐτὸν οὖν τὸν Δολοβέλλαν ὁ Ἀντώνιος, νέον τε καὶ φιλότιμον εἰδώς, ἔπεισεν αἰτεῖν Συρίαν ἀντὶ Κασσίου καὶ τὸν ἐς Παρθυαίους κατειλεγμένον στρατὸν ἐπὶ τοὺς Παρθυαίους, αἰτεῖν δὲ οὐ παρὰ τῆς βουλῆς (οὐ γὰρ ἐξῆν), ἀλλὰ παρὰ τοῦ δήμου νόμῳ. καὶ ὁ μὲν ἡσθεὶς αὐτίκα προυτίθει τὸν νόμον, καὶ τῆς βουλῆς αἰτιωμένης αὐτὸν παραλύειν τὰ δόξαντα τῷ Καίσαρι τὸν μὲν ἐπὶ Παρθυαίους πόλεμον οὐδενὶ ἔφη ὑπὸ Καίσαρος ἐπιτετράφθαι, Κάσσιον δὲ τὸν Συρίας ἀξιωθέντα αὐτόν τι τῶν Καίσαρος πρότερον ἀλλάξαι, δόντα πωλεῖν τὰ κληρουχήματα τοῖς λαβοῦσι πρὸ τῶν νενομισμένων εἴκοσιν ἐτῶν· καὶ αὐτὸς δὲ αἰδεῖσθαι Συρίας οὐκ ἀξιούμενος, Δολοβέλλας ὤν, πρὸ Κασσίου. οἱ μὲν δὴ τῶν δημάρχων τινὰ Ἀσπρήναν ἔπεισαν ἐν τῇ χειροτονίᾳ ψεύσασθαι περὶ διοσημείας, ἐλπίσαντές τι καὶ Ἀντώνιον συμπράξειν, ὕπατόν τε ὄντα καὶ τῶν σημείων ἱερέα καὶ διάφορον ἔτι νομιζόμενον εἶναι τῷ Δολοβέλλᾳ· ὁ δ’ Ἀντώνιος, ἐπεὶ τῆς χειροτονίας οὔσης ὁ Ἀσπρήνας ἔφη διοσημείαν ἀπαίσιον γεγονέναι, ἔθους ὄντος ἑτέρους ἐπὶ τοῦτο πέμπεσθαι, πάνυ χαλεψάμενος τῷ Ἀσπρήνᾳ τοῦ ψεύσματος τᾲς φυλὰς ἐκέλευε χειροτονεῖν περὶ τοῦ Δολοβέλλα.", "st": "3.7"}, {"sp": "N", "t": "καὶ γίνεται μὲν οὕτω Συρίας ἡγεμὼν Δολοβέλλας καὶ στρατηγὸς τοῦ πολέμου τοῦ πρὸς Παρθυαίους καὶ στρατιᾶς τῆς ἐς αὐτὸν ὑπὸ Καίσαρος κατειλεγμένης, ὅση τε περὶ Μακεδονίαν προεληλύθει, καὶ ὁ Ἀντώνιος τότε πρῶτον ἔγνωστο συμπράσσων τῷ Δολοβέλλᾳ. γεγενημένων δὲ τῶνδε ἐν τῷ δήμῳ τὴν βουλὴν ὁ Ἀντώνιος ᾔτει Μακεδονίαν, εὖ εἰδώς, ὅτι αἰδέσονται, μετὰ Συρίαν δοθεῖσαν Δολοβέλλᾳ, ἀντειπεῖν περὶ Μακεδονίας Ἀντωνίῳ, καὶ ταῦτα γυμνῆς στρατοῦ γενομένης. καὶ ἔδοσαν μὲν ἄκοντες καὶ ἐν θαύματι ἔχοντες, ὅπως τὸν ἐν αὐτῇ στρατὸν προμεθῆκεν ὁ Ἀντώνιος τῷ Δολοβέλλᾳ, ἠγάπων δὲ ὅμως Δολοβέλλαν ἔχειν τὸν στρατὸν Ἀντωνίου μᾶλλον. ἐν καιρῷ δὲ αὐτοὶ τὸν Ἀντώνιον τοῖς ἀμφὶ τὸν Κάσσιον ἀντῄτουν ἕτερα ἔθνη, καὶ ἐδόθη Κυρήνη τε καὶ Κρήτη, ὡς δ’ ἑτέροις δοκεῖ, τάδε μὲν ἀμφότερα Κασσίῳ, Βιθυνία δὲ Βρούτῳ.", "st": "3.8"}, {"sp": "N", "t": "τὰ μὲν δὴ γινόμενα ἐν Ῥώμῃ τοιάδε ἦν· Ὀκτάουιος δὲ ὁ τῆς ἀδελφῆς τοῦ Καίσαρος θυγατριδοῦς ἵππαρχος μὲν αὐτοῦ Καίσαρος γεγένητο πρὸς ἓν ἔτος, ἐξ οὗ τήνδε τὴν τιμὴν ὁ Καῖσαρ ἐς τοὺς φίλους περιφέρων ἐτήσιον ἔσθ’ ὅτε ἐποιεῖτο εἶναι, μειράκιον δὲ ἔτι ὢν ἐς Ἀπολλωνίαν τὴν ἐπὶ τοῦ Ἰονίου παιδεύεσθαί τε καὶ ἀσκεῖσθαι τὰ πολέμια ἐπέμπετο ὑπὸ τοῦ Καίσαρος ὡς ἐς τοὺς πολεμίους ἑψόμενος αὐτῷ. καὶ αὐτὸν ἐν τῇ Ἀπολλωνίᾳ ἱππέων ἶλαι παραλλὰξ ἐκ Μακεδονίας ἐπιοῦσαι συνεγύμναζον καὶ τῶν ἡγεμόνων τοῦ στρατοῦ τινες ὡς συγγενεῖ Καίσαρος θαμινὰ ἐπεφοίτων. γνῶσίς τε ἐκ τούτων αὐτῷ καὶ εὔνοια παρὰ τοῦ στρατοῦ τις ἐνεγίγνετο, σὺν χάριτι δεξιουμένῳ πάντας. ἕκτον δ’ ἔχοντι μῆνα ἐν τῇ Ἀπολλωνίᾳ ἀγγέλλεται περὶ ἑσπέραν ὁ Καῖσαρ ἀνῃρημένος ἐν τῷ βουλευτηρίῳ πρὸς τῶν φιλτάτων καὶ παρ’ αὐτῷ δυνατωτάτων τότε μάλιστα. τῶν δὲ λοιπῶν οὐδενὸς ἀπαγγελθέντος πω δέος αὐτὸν ἐπεῖχε καὶ ἄγνοια, εἴτε κοινὸν εἴη τῆς βουλῆς τὸ ἔργον εἴτε καὶ τῶν ἐργασαμένων ἴδιον, καὶ εἰ δίκην ἤδη τοῖς πλείοσι δεδώκοιεν ἢ καὶ τοῦδε εἶεν, ἢ καὶ τὸ πλῆθος αὐτοῖς συνήδοιτο.", "st": "3.9"}, {"sp": "N", "t": "ἐφ’ οἷς οἱ φίλοι ἐκ Ῥώμης ὑπετίθεντο ταῦτα, ὥστε οἱ μὲν ἐς φυλακὴν τοῦ σώματος αὐτὸν ἠξίουν ἐπὶ τὸν ἐν Μακεδονίᾳ στρατὸν καταφυγεῖν καί, ὅτε μάθοι μὴ κοινὸν εἶναι τὸ ἔργον, ἐπιθαρρήσαντα τοῖς ἐχθροῖς ἀμύνειν τῷ Καίσαρι· καὶ ἦσαν οἳ καὶ τῶν ἡγεμόνων αὐτὸν ἐλθόντα φυλάξειν ὑπεδέχοντο· ἡ δὲ μήτηρ καὶ Φίλιππος, ὃς εἶχεν αὐτήν, ἀπὸ Ῥώμης ἔγραφον μήτε ἐπαίρεσθαι μήτε θαρρεῖν πω μεμνημένον, οἷα Καῖσαρ ὁ παντὸς ἐχθροῦ κρατήσας ὑπὸ τῶν φιλτάτων μάλιστα πάθοι, τὰ δὲ ἰδιωτικώτερα ὡς ἐν τοῖς παροῦσιν ἀκινδυνότερα αἱρεῖσθαι μᾶλλον καὶ πρὸς σφᾶς ἐς Ῥώμην ἐπείγεσθαι φυλασσόμενον. οἷς Ὀκτάουιος ἐνδοὺς διὰ τὴν ἔτι ἄγνοιαν τῶν ἐπὶ τῷ θανάτῳ γενομένων, τοὺς ἡγεμόνας τοῦ στρατοῦ δεξιωσάμενος διέπλει τὸν Ἰόνιον, οὐκ ἐς τὸ Βρεντέσιον (οὔπω γάρ τινα τοῦ ἐκεῖθι στρατοῦ πεῖραν εἰληφὼς πάντα ἐφυλάσσετο), ἀλλ’ ἐς ἑτέραν οὐ μακρὰν ἀπὸ τοῦ Βρεντεσίου πόλιν, ἐκτὸς οὖσαν ὁδοῦ, ᾗ ὄνομα Λουπίαι. ἐνταῦθα οὖν ἐνηυλίσατο διατρίβων.", "st": "3.10"}, {"sp": "N", "t": "ὡς δέ οἱ τά τε ἀκριβέστερα περὶ τοῦ φόνου καὶ τοῦ δημοσίου πάθους τῶν τε διαθηκῶν καὶ τῶν ἐψηφισμένων ἦλθε τὰ ἀντίγραφα, οἱ μὲν ἔτι μᾶλλον αὐτὸν ἠξίουν τοὺς ἐχθροὺς Καίσαρος δεδιέναι, υἱόν τε αὐτοῦ καὶ κληρονόμον ὄντα, καὶ παρῄνουν ἅμα τῷ κλήρῳ τὴν θέσιν ἀπείπασθαι· ὁ δὲ καὶ ταῦτά οἱ καὶ τὸ μὴ τιμωρεῖν αὐτὸν Καίσαρι αἰσχρὸν ἡγούμενος ἐς τὸ Βρεντέσιον ᾔει, προπέμψας καὶ διερευνησάμενος, μή τις ἐκ τῶν φονέων ἐγκαθέζοιτο ἐνέδρα. ὡς δὲ αὐτῷ καὶ ὁ ἐνθάδε στρατὸς οἷα Καίσαρος υἱὸν δεξιούμενος ἀπήντα, θαρρήσας ἔθυε καὶ εὐθὺς ὠνομάζετο Καῖσαρ. ἔθος γάρ τι Ῥωμαίοις τοὺς θετοὺς τὰ τῶν θεμένων ὀνόματα ἐπιλαμβάνειν. ὁ δὲ οὐκ ἐπέλαβεν, ἀλλὰ καὶ τὸ αὑτοῦ καὶ τὸ πατρῷον ὅλως ἐνήλλαξεν, ἀντὶ Ὀκταουίου παιδὸς Ὀκταουίου Καῖσαρ εἶναι καὶ Καίσαρος υἱός, καὶ διετέλεσεν οὕτω χρώμενος. εὐθύς τε ἐς αὐτὸν ἄθρουν καὶ πανταχόθεν ὡς ἐς Καίσαρος υἱὸν πλῆθος ἀνθρώπων συνέθεον, οἱ μὲν ἐκ φιλίας Καίσαρος, οἱ δὲ ἐξελεύθεροι καὶ θεράποντες αὐτοῦ, καὶ ἕτεροι στρατιῶται σὺν αὐτοῖς, οἱ μὲν ἀποσκευὰς ἢ χρήματα φέροντες ἐς τὴν Μακεδονίαν, οἱ δὲ ἕτερα χρήματα καὶ φόρους ἐξ ἐθνῶν ἄλλων ἐς τὸ Βρεντέσιον.", "st": "3.11"}, {"sp": "N", "t": "ὁ δὲ καὶ τῷ πλήθει τῶν εἰς αὐτὸν ἀφικνουμένων καὶ τῇ Καίσαρος αὐτοῦ δόξῃ τε καὶ τῇ πάντων εἰς ἐκεῖνον εὐνοία θαρρῶν ὥδευεν ἐς Ῥώμην σὺν ἀξιολόγῳ πλήθει, αὐξομένῳ μᾶλλον ἑκάστης ἡμέρας οἷα χειμάρρῳ, φανερᾶς μὲν ἐπιβουλῆς ὢν ἀμείνων διὰ τὸ πλῆθος, ἐνέδρας δὲ δι’ αὐτὸ καὶ μάλιστα ὑφορώμενος, ἀρτιγνώστων οἱ τῶν συνόντων σχεδὸν ὄντων ἁπάντων. τὰ δὲ τῶν πόλεων τῶν μὲν ἄλλων οὐ πάντῃ πρὸς αὐτὸν ἦν ὁμαλά· οἱ δὲ τῷ Καίσαρι στρατευσάμενοί τε καὶ ἐς κληρουχίας διῃρημένοι συνέτρεχον ἐκ τῶν ἀποικιῶν ἐπὶ χάριτι τοῦ μειρακίου καὶ τὸν Καίσαρα ὠλοφύροντο καὶ τὸν Ἀντώνιον ἐβλασφήμουν οὐκ ἐπεξιόντα τηλικούτῳ μύσει καὶ σφᾶς ἔλεγον, εἴ τις ἡγοῖτο, ἀμυνεῖν. οὓς ὁ Καῖσαρ ἐπαινῶν καὶ ἀνατιθέμενος ἐν τῷ παρόντι ἀπέπεμπεν. ὄντι δ’ αὐτῷ περὶ Ταρρακίνας, ἀπὸ τετρακοσίων που Ῥώμης σταδίων, ἀγγέλλεται Κάσσιός τε καὶ Βροῦτος ἀφῃρημένοι πρὸς τῶν ὑπάτων Συρίαν καὶ Μακεδονίαν καὶ ἐς παρηγορίαν βραχύτερα ἔτερα Κυρήνην καὶ Κρήτην ἀντειληφότες, φυγάδων τέ τινων κάθοδοι καὶ Πομπηίου μετάκλησις καὶ ἀπὸ τῶν Καίσαρος ὑπομνημάτων ἔς τε τὴν βουλὴν ἐγγραφαί τινων καὶ ἕτερα πολλὰ γιγνόμενα.", "st": "3.12"}, {"sp": "N", "t": "ὡς δ’ ἐς τὴν πόλιν ἀφίκετο, ἡ μὲν μήτηρ αὖθις καὶ Φίλιππος ὅσοι τε ἄλλοι κηδεμόνες ἦσαν αὐτοῦ, ἐδεδοίκεσαν τήν τε τῆς βουλῆς ἐς τὸν Καίσαρα ἀλλοτρίωσιν καὶ τὸ δόγμα, μὴ εἶναι δίκας ἐπὶ Καίσαρι φόνου, καὶ τὴν Ἀντωνίου τότε δυναστεύοντος ἐς αὐτὸν ὑπεροψίαν, οὔτε ἀφικομένου πρὸς τὸν Καίσαρος υἱὸν ἐλθόντα οὔτε προσπέμψαντος αὐτῷ· ὁ δὲ καὶ ταῦτ’ ἐπράυνεν, αὐτὸς ἀπαντήσειν ἐς τὸν Ἀντώνιον εἰπὼν οἷα νεώτερος ἐς πρεσβύτερον καὶ ἰδιώτης ἐς ὕπατον καὶ τὴν βουλὴν θεραπεύσειν τὰ εἰκότα. καὶ τὸ δόγμα ἔφη γενέσθαι μηδενός πω τοὺς ἀνδροφόνους διώκοντος· ἀλλ’ ὁπότε θαρρήσας τις διώκοι, καὶ τὸν δῆμον ἐπικουρήσειν καὶ τὴν βουλὴν ὡς ἐννόμῳ καὶ τοὺς θεοὺς ὡς δικαίῳ καὶ τὸν Ἀντώνιον ἴσως. εἰ δὲ καὶ τοῦ κλήρου καὶ τῆς θέσεως ὑπερίδοι, ἔς τε τὸν Καίσαρα ἁμαρτήσεσθαι καὶ τὸν δῆμον ἀδικήσειν εἰς τὴν διανομήν.", "st": "3.13"}, {"sp": "N", "t": "Ἀπερρήγνυ τε λήγων τοῦ λόγου, ὅτι μὴ κινδυνεύειν οἱ καλὸν εἴη μόνον, ἀλλὰ καὶ θνῄσκειν, εἰ προκριθεὶς ἐκ πάντων ἐς τοσαῦτα ὑπὸ τοῦ Καίσαρος ἀντάξιος αὐτοῦ φαίνοιτο φιλοκινδυνοτάτου γεγονότος. τά τε τοῦ Ἀχιλλέως, ὑπόγυά οἱ τότε ὄντα μάλιστα, ἐς τὴν μητέρα ὥσπερ ἐς τὴν Θέτιν ἐπιστρεφόμενος ἔλεγεν· αὐτίκα τεθναίην, ἐπεὶ οὐκ ἄρ’ ἔμελλον ἑταίρῳ κτεινομένῳ ἐπαμύνειν.", "st": "3.13"}, {"sp": "N", "t": "καὶ τόδε εἰπὼν Ἀχιλλεῖ μὲν ἔφη κόσμον ἀθάνατον ἐκ πάντων εἶναι τοῦτο τὸ ἔπος, καὶ τὸ ἔργον αὐτοῦ μάλιστα· αὐτὸς δ’ ἀνεκάλει τὸν Καίσαρα οὐχ ἑταῖρον, ἀλλὰ πατέρα, οὐδὲ συστρατιώτην, ἀλλ’ αὐτοκράτορα, οὐδὲ πολέμου νόμῳ πεσόντα, ἀλλ’ ἀθεμίστως ἐν βουλευτηρίῳ κατωκοπέντα.", "st": "3.13"}, {"sp": "N", "t": "ἐφ’ οἷς αὐτὸν ἡ μήτηρ, ἐς ἡδονὴν ἐκ τοῦ δέους ὑπαχθεῖσα, ἠσπάζετο ὡς μόνον ἄξιον Καίσαρος καὶ λέγειν ἔτι ἐπισχοῦσα ἐπέσπερχεν ἐς τὰ ἐγνωσμένα σὺν τῇ τύχῃ. παρῄνει γε μὴν ἔτι τέχνῃ καὶ ἀνεξικακίᾳ μᾶλλον ἢ φανερᾷ θρασύτητί πω χρῆσθαι. καὶ ὁ Καῖσαρ ἐπαινέσας καὶ πράξειν ὑποσχόμενος οὕτως, αὐτίκα τῆς ἑσπέρας ἐς τοὺς φίλους περιέπεμπεν, ἐς ἕω συγκαλῶν ἕκαστον ἐς τὴν ἀγορὰν μετὰ πλήθους. ἔνθα Γάιον Ἀντώνιον τὸν ἀδελφὸν Ἀντωνίου, στρατηγοῦντα τῆς πόλεως, ὑπαντιάσας ἔφη δέχεσθαι τὴν θέσιν τοῦ Καίσαρος· ἔθος γάρ τι Ῥωμαίοις τοὺς θετοὺς ἐπὶ μάρτυσι γίγνεσθαι τοῖς στρατηγοῖς. ἀπογραψαμένων δὲ τῶν δημοσίων τὸ ῥῆμα, εὐθὺς ἐκ τῆν ἀγορᾶς ἐς τὸν Ἀντώνιον ἐχώρει. ὁ δὲ ἦν ἐς κήποις, οὓς ὁ Καῖσαρ αὐτῷ δεδώρητο Πομπηίου γενομένους. διατριβῆς δὲ ἀμφὶ τὰς θύρας πλείονος γενομένης ὁ μὲν Καῖσαρ καὶ τάδε ἐς ὑποψίαν Ἀντωνίου τῆς ἀλλοτριώσεως ἐτίθετο, εἰσκληθέντος δέ ποτε ἦσαν προσαγορεύσεις τε καὶ περὶ ἀλλήλων πύσματα εἰκότα.", "st": "3.14"}, {"sp": "N", "t": "ὡς δὲ ἤδη λέγειν ἔδει περὶ ὧν ἦσαν ἐν χρείᾳ, ὁ Καῖσαρ εἶπεν·", "st": "3.15"}, {"sp": "N", "t": "“ἐγὼ δέ, πάτερ Ἀντώνιε (πατέρα γὰρ εἶναι σέ μοι δικαιοῦσιν αἵ τε Καίσαρος ἐς σὲ εὐεργεσίαι καὶ ἡ σὴ πρὸς ἐκεῖνον χάρις), τῶν σοι πεπραγμένων ἐπ’ ἐκείνῳ τὰ μὲν ἐπαινῶ καὶ χάριν αὐτῶν ὀφλήσω, τὰ δ’ ἐπιμέμφομαι, καὶ λελέξεται μετὰ παρρησίας, ἐς ἣν ἡ λύπη με προάγει. κτεινομένῳ μὲν οὐ παρῆς, τῶν φονέων σε περισπασάντων περὶ θύρας, ἐπεὶ περιέσῳζες ἂν αὐτὸν ἢ συνεκινδύνευες ὅμοια παθεῖν· ὧν εἰ θάτερον ἔμελλεν ἔσεσθαι, καλῶς, ὅτι μὴ παρῆς. ψηφιζομένων δέ τινων αὐτοῖς ὡς ἐπὶ τυράννῳ γέρα ἀντεῖπας ἐγκρατῶς· καὶ τοῦδέ σοι χάριν οἶδα λαμπράν, εἰ καὶ τοὺς ἄνδρας ἔγνως συνανελεῖν σε βεβουλευμένους, οὐχ, ὡς ἡμεῖς ἡγούμεθα, τιμωρὸν ἐσόμενον Καίσαρι, ἀλλ’, ὡς αὐτοὶ λέγουσι, τῆς τυραννίδος διάδοχον. ἅμα δ’ οὐκ ἦσαν ἐκεῖνοι τυραννοκτόνοι, εἰ μὴ καὶ φονεῖς ἦσαν· διὸ καὶ ἐς τὸ Καπιτώλιον συνέφυγον ὡς ἐς ἱερὸν ἁμαρτόντες ἱκέται ἢ ὡς ἐς ἀκρόπολιν ἐχθροί. πόθεν οὖν αὐτοῖς ἀμνηστία καὶ τὸ ἀνεύθυνον τοῦ φόνου, ἢ τῆς βουλῆς καὶ τοῦ δήμου ει τινες ἐφθάρατο ὑπ’ ἐκείνων; καὶ σὲ τὸ τῶν πλεόνων ὁρᾶν ἐχρῆν, ὕπατον ὄντα. ἀλλὰ καὶ θάτερα βουλομένῳ σοι ἡ ἀρχὴ συνελάμβανε, τιμωρουμένῳ τηλικοῦτον ἄγος καὶ τοὺς πλανωμένους μεταδιδάσκοντι. σὺ δὲ καὶ ὅμηρα τῆς ἀδείας, οἰκεῖα αὐτοῦ σοῦ, τοῖς ἀνδροφόνοις ἔπεμψας ἐς τὸ Καπιτώλιον.", "st": "3.15"}, {"sp": "N", "t": "“ἀλλ’ ἔστω καὶ ταῦτα τοὺς διεφθαρμένους σε βιάσασθαι. ὅτε μέντοι τῶν διαθηκῶν ἀναγνωσθεισῶν καὶ αὐτοῦ σοῦ δίκαιον ἐπιτάφιον εἰπόντος ὁ δῆμος ἐν ἀκριβεῖ Καίσαρος μνήμῃ γενόμενοι πῦρ ἐπ’ αὐτοὺς ἔφερον, καὶ φεισάμενοι χάριν τῶν γειτόνων ἐς τὴν ἐπιοῦσαν ἥξειν ἐπὶ ὅπλα συνέθεντο, πῶς οὐχὶ τῷ δήμῳ συνέπραξας καὶ ἐστρατήγησας τοῦ πυρὸς ἢ τῶν ὅπλων ἢ δίκην γε τοῖς ἀνδροφόνοις ἐπέγραψας, εἰ δίκης ἔδει κατὰ αὐτοφώρων, καὶ φίλος ὢν Καίσαρι καὶ ὕπατος καὶ Ἀντώνιος;", "st": "3.15"}, {"sp": "N", "t": "“ἀλλὰ Μάριος μὲν ἐξ ἐπιτάγματος ἀνῃρέθη κατὰ τὸ τῆς ἀρχῆς μέγεθος, ἀνδροφόνους δὲ ἐκφυγεῖν ὑπερεῖδες καὶ ἐς ἡγεμονίας ἐνίους διαδραμεῖν, ἃς ἀθεμίστως ἔχουσι τὸν δόντα ἀνελόντες. Συρίαν μὲν δὴ καὶ Μακεδονίαν εὖ ποιοῦντες οἱ ὕπατοι, σὺ καὶ Δολοβέλλας, καθισταμένων ἄρτι τῶν πραγμάτων περιεσπάσατε ἐς ἑαυτούς. καὶ τοῦδέ σοι χάριν ᾔδειν ἄν, εἰ μὴ αὐτίκα Κυρήνην καὶ Κρήτην αὐτοῖς ἐψηφίσασθε καὶ φυγάδας ἠξιώσατε ἡγεμονίαις αἰεὶ κατ’ ἐμοῦ δορυφορεῖσθαι· Δέκμον τε τὴν ἐγγὺς Κελτικὴν ὑπερορᾶτε ἔχοντα, καὶ τόνδε τοῖς ἄλλοις ὁμοίως αὐθέντην τοὐμοῦ πατρὸς γενόμενον. ἀλλὰ καὶ τάδε τὴν βουλὴν ἐρεῖ τις ἐγνωκέναι. σὺ δ’ ἐπεψήφιζες καὶ προυκάθησο τῆς βουλῆς, ᾧ μάλιστα πάντων ἥρμοζε διὰ σαυτὸν ἀντειπεῖν· τὸ γὰρ ἀμνηστίαν δοῦναι τὴν σωτηρίαν ἦν ἐκείνοις χαριζομένων μόνον, τὸ δὲ ἡγεμονίας αὖθις ψηφίζεσθαι καὶ γέρα ὑβριζόντων Καίσαρα καὶ τὴν σὴν γνώμην ἀκυρούντων.", "st": "3.16"}, {"sp": "N", "t": "“ἐπὶ τάδε με δὴ τὸ πάθος ἐξήνεγκε παρὰ τὸ ἁρμόζον ἴσως ἐμοὶ τῆς τε ἡλικίας καὶ τῆς πρὸς σὲ αἰδοῦς. εἴρηται δ’ ὅμως ὡς ἐς ἀκριβέστερον φίλον Καίσαρι καὶ πλείστης ὑπ’ ἐκείνου τιμῆς καὶ δυνάμεως ἠξιωμένον καὶ τάχα ἂν αὐτῷ καὶ θετὸν γενόμενον, εἰ ᾔδει σε δεξόμενον Αἰνεάδην ἀντὶ Ἡρακλείδου γενέσθαι· τοῦτο γὰρ αὐτὸν … ἐνδοιάσαι, πολὺν τῆς διαδοχῆς λόγον ποιούμενον.", "st": "3.16"}, {"sp": "N", "t": "“ἐς δὲ τὸ μέλλον, ὦ Ἀντώνιε, πρὸς θεῶν τε φιλίων καὶ πρὸς αὐτοῦ σοι Καίσαρος, εἰ μέν τι καὶ τῶν γεγονότων μεταθέσθαι θέλεις (δύνασαι γάρ, εἰ θέλεις)· εἰ δὲ μή, τά γε λοιπὰ τοὺς φονέας ἀμυνομένῳ μοι μετὰ τοῦ δήμου καὶ τῶνδε τῶν ἔτι μοι πατρικῶν φίλων συνίστασθαι καὶ συνεργεῖν· εἰ δέ σε τῶν ἀνδρῶν τις ἢ τῆς βουλῆς αἰδὼς ἔχει, μὴ ἐπιβαρεῖν. καὶ τάδε μὲν ἀμφὶ τούτων· οἶσθα δ’, ὅπως ἔχει μοι καὶ τὰ οἴκοι, δαπάνης τε ἐς τὴν διανομήν, ἣν ὁ πατὴρ ἐκέλευσε τῷ δήμῳ δοθῆναι, καὶ ἐπείξεως ἐς αὐτήν, ἵνα μὴ βραδύνων ἀχάριστος εἶναι δοκοίην μηδ’ ὅσοι καταλεχθέντες εἰς τὰς ἀποικίας ἐπιμένουσι τῇ πόλει, δι’ ἐμὲ τρίβοιντο. ὅσα δὴ τῶν Καίσαρος εὐθέως ἐπὶ τῷ φόνῳ πρὸς σὲ μετενήνεκται ὡς ἐπ’ ἀσφαλὲς ἐξ ἐπικινδύνου τότε οἰκίας, τὰ μὲν κειμήλια αὐτῶν καὶ τὸν ἄλλον ἅπαντα κόσμον ἔχειν ἀξιῶ σε καὶ ὅσα ἂν ἐθέλῃς ἄλλα παρ’ ἡμῶν ἐπιλαβεῖν, ἐς δὲ τὴν διανομὴν ἀποδοῦναί μοι τὸ χρυσίον τὸ ἐπίσημον, ὃ συνηθροίκει μὲν ἐς τοὺς πολέμους ἐκεῖνος, οὓς ἐπενόει, ἀρκέσει δ’ ἐμοὶ νῦν ἐς τριάκοντα μυριάδας ἀνδρῶν μεριζόμενον. τὰ δὲ λοιπὰ τῆς δαπάνης, εἰ μὲν θαρρήσαιμί σοι, παρὰ σοῦ ἂν ἴσως ἢ διὰ σοῦ δανεισαίμην ἐκ τῶν δημοσίων χρημάτων, ἂν διδῷς· διαπεπράσεται δὲ αὐτίκα καὶ ἡ οὐσία.”", "st": "3.17"}, {"sp": "N", "t": "τοιαῦτα τοῦ Καίσαρος εἰπόντος ο Ἀντώνιος κατεπλάγη, τῆς τε παρρησίας καὶ τῆς εὐτολμίας παρὰ δόξαν οἱ πολλῆς καὶ παρ’ ἡλικίαν φανείσης· χαλεψάμενος δὲ τοῖς τε λόγοις οὐχ ὅσον ἔδει τὸ πρέπον ἐς αὐτὸν ἐσχηκόσι καὶ μάλιστα τῶν χρημάτων τῇ ἀπαιτήσει, αὐστηρότερον αὐτὸν ὧδε ἠμείψατο·", "st": "3.18"}, {"sp": "N", "t": "“εἰ μὲν ὁ Καῖσάρ σοι μετὰ κλήρου καὶ τῆς ἐπωνυμίας, ὦ παῖ, καὶ τὴν ἡγεμονίαν κατέλιπεν, εἰκὸς σὲ τῶν κοινῶν τοὺς λογισμοὺς αἰτεῖν κἀμὲ ὑπέχειν. εἰ δὲ οὐδενί πω Ῥωμαῖοι τὴν ἡγεμονίαν ἔδοσαν ἐκ διαδοχῆς, οὐδὲ τῶν βασιλέων, οὓς ἐκβαλόντες ἐπώμοσαν μηδ’ ἄλλων ἔτι ἀνέξεσθαι, (ὃ καὶ τῷ πατρί σου μάλιστα οἱ φονεῖς ἐπιλέγοντες φασὶν ἀνελεῖν αὐτὸν βασιλιζόμενον, οὐχ ἡγούμενον ἔτι), ἐμοὶ μὲν οὐδ’ ἀποκρίσεως δεῖ πρὸς σὲ περὶ τῶν κοινῶν, τῷ δ’ αὐτῷ λόγῳ καὶ σὲ κουφίζω, μὴ χάριν ὀφείλειν ἡμῖν ἐπ’ αὐτοῖς. ἐπράσσετο γὰρ οὐ σοῦ χάριν, ἀλλὰ τοῦ δήμου, πλὴν ἑνὸς τοῦ μεγίστου δὴ μάλιστα πάντων ἔς τε Καίσαρα καὶ σὲ ἔργου. εἰ γὰρ τοῦ κατ’ ἐμαυτὸν ἕνεκα ἀδεοῦς καὶ ἀνεπιφθόνου περιεῖδον ἐγὼ τιμὰς ψηφιζομένας τοῖς φονεῦσιν ὡς τυραννοκτόνοις, τύραννος ὁ Καῖσαρ ἐγίγνετο, ᾧ μήτε δόξης μήτε τιμῆς τινος ἢ τῶν ἐγνωσμένων βεβαιώσεως ἔτι μετῆν. οὐ διαθήκας εἶχεν ἄν, οὐ παῖδα, οὐκ οὐσίαν, οὐκ αὐτὸ τὸ σῶμα ταφῆς ἀξιούμενον, οὐδὲ ἰδιώτου· ἄταφα γὰρ οἱ νόμοι τὰ σώματα τῶν τυράννων ὑπερορίζουσι καὶ τὴν μνήμην ἀτιμοῦσι καὶ δημεύουσι τὴν περιουσίαν.", "st": "3.18"}, {"sp": "N", "t": "“ὧν ἐγὼ δεδιὼς ἕκαστον ὑπερηγωνιζόμην Καίσαρος, ἀθανάτου τε δόξης καὶ δημοσίας ταφῆς, οὐκ ἀκινδύνως οὐδ’ ἀνεπιφθόνως ἐμαυτῷ, τυχεῖν, πρός τε ἄνδρας ταχυεργεῖς καὶ φόνου πλήρεις καί, ὡς ἔμαθες, ἤδη καὶ ἐπ’ ἐμὲ συνομωμοσμένους πρός τε τὴν βουλὴν ἀχθομένην σου τῷ πατρὶ τῆς ἀρχῆς. ἀλλὰ καὶ ταῦτα κινδυνεύειν καὶ παθεῖν ὁτιοῦν ᾑρούμην ἑκὼν μᾶλλον ἢ ἄταφον καὶ ἄτιμον γιγνόμενον περιιδεῖν Καίσαρα, ἄριστον ἀνδρῶν τῶν ἐφ’ ἑαυτοῦ καὶ εὐτυχέστατον ἐς τὰ πλεῖστα καὶ ἀξιοτιμότατον ἐκ πάντων ἐμοὶ γενόμενον. τοῖς δ’ αὐτοῖς μου τοῖσδε κινδύνοις καὶ σὺ τὰ νῦν σοι παρόντα πάντα λαμπρὰ τῶν Καίσαρος ἔχεις, γένος, ὄνομα, ἀξίωμα, περιουσίαν. ὧν σε δικαιότερον ἦν ἐμοὶ χάριν εἰδέναι μᾶλλον ἢ τὰ ἐκλειφθέντα εἰς τὴν τῆς βουλῆς παρηγορίαν ἢ ἐς ἀντίδοσιν τῶνδε, ὧν ἔχρῃζον, ἢ κατ’ ἄλλας χρείας ἢ λογισμοὺς ἐπιμέμφεσθαι πρεσβυτέρῳ νεώτερον ὄντα.", "st": "3.19"}, {"sp": "N", "t": "“καὶ τάδε μὲν ἀρκέσει σοι περὶ τῶνδε εἰρῆσθαι· ἐνσημαίνῃ δὲ καὶ τῆς ἡγεμονίας με ἐπιθυμεῖν, οὐκ ἐπιθυμοῦντα μέν, οὐκ ἀπάξιον δὲ ἡγούμενον εἶναι, καὶ ἄχθεσθαι μὴ τυχόντα τῶν διαθηκῶν τῶν Καίσαρος, ὁμολογῶν μοι καὶ τὸ τῶν Ἡρακλειδῶν γένος ἀρκεῖν.", "st": "3.19"}, {"sp": "N", "t": "“περὶ δὲ τῶν σῶν χρειῶν, ἐθέλοντα μέν σε ἐκ τῶν δημοσίων δανείσασθαι ἡγούμην ἂν εἰρωνείαν λέγειν, εἰ μὴ πιθανὸν ἦν ἔτι ἀγνοεῖν σε κενὰ πρὸς τοῦ πατρὸς ἀπολελεῖφθαι τὰ κοινὰ ταμιεῖα, τῶν προσόδων, ἐξ οὗ παρῆλθεν ἐπὶ τὴν ἀρχήν, ἐς αὐτὸν ἀντὶ τοῦ ταμιείου συμφερομένων καὶ εὑρεθησομένων αὐτίκα ἐν τῇ Καίσαρος περιουσίᾳ, ὅταν αὐτὰ ζητεῖν ψηφισώμεθα. ἄδικον γὰρ οὐδὲν τοῦτο ἐς τὸν Καίσαρα ἔσται, τεθνεῶτά τε ἤδη καὶ οὐκ ἂν εἰπόντα ἄδικον εἶναι, εἰ καὶ ζῶν ᾐτεῖτο τοὺς λογισμούς, ἐπεὶ καὶ τῶν ἰδιωτῶν πολλοῖς ἀμφισβητοῦσί σοι καθ’ ἕνα τῆς οὐσίας οὐκ ἀδήριτον αὐτὴν ἔχων γνώσῃ. τῶν δὲ μετενεχθέντων πρός με χρημάτων οὔτε τὸ πλῆθός ἐστιν, ὅσον εἰκάζεις, οὔτε τι νῦν ἔστι παρ’ ἐμοί, πάντα τῶν ἐν ἀρχαῖς καὶ δυνάμει, πλὴν Δολοβέλλα καὶ τῶν ἐμῶν ἀδελφῶν νειμαμένων μὲν εὐθὺς ὡς τυράννου, δι’ ἐμὲ δὲ μετατεθέντων ἐς χάριν τῶν ὑπὲρ Καίσαρος ἐψηφισμένων, ἐπεὶ καὶ σὺ τὰ λοιπὰ φέρων οἴσεις ἀντὶ τοῦ δήμου τοῖς δυσχεραίνουσιν, ἂν σωφρονῇς. οἱ μὲν γὰρ ἐκπέμψουσιν, ἂν συμφρονῶσι, τὸν δῆμον ἐπὶ τὰς ἀποικίας· ὁ δὲ δῆμός ἐστιν, ὥσπερ καὶ σὺ τῶν Ἑλληνικῶν ἀρτιδίδακτος ὢν ἔμαθες, ἀστάθμητον ὥσπερ ἐν θαλάσσῃ κῦμα κινούμενον· ὁ μὲν ἦλθεν, ὁ δ’ ἀπῆλθεν. ᾧ λόγῳ καὶ τῶν ἡμετέρων αἰεὶ τοὺς δημοκόπους ὁ δῆμος ἐπὶ πλεῖστον ἐξάρας ἐς γόνυ ἔρριψε.”", "st": "3.20"}, {"sp": "N", "t": "τούτων τοῖς πολλοῖς δυσχεράνας ὁ Καῖσαρ ἐς ὕβριν εἰρημένοις ἀπεχώρει, τὸν πατέρα ἀνακαλῶν θαμινὰ ἐξ ὀνόματος, καὶ τὴν οὐσίαν ἐς πρᾶσιν αὐτίκα προυτίθει πᾶσαν, ὅση κατὰ τὸν κλῆρον ἐγίγνετο αὐτοῦ, προτρέπων ἐπικουρεῖν οἱ τὸν δῆμον ἐκ τῆσδε τῆς σπουδῆς· φανερᾶς δὲ τῆς Ἀντωνίου πρὸς αὐτὸν ἔχθρας γενομένης καὶ τῆς βουλῆς ζήτησιν εὐθὺς εἶναι τῶν δημοσίων χρημάτων ψηφισαμένης, οἱ πολλοὶ ἔδεισαν ἐπὶ τῷ νέῳ Καίσαρι τῆς πατρῴας ἐς τοὺς στρατιώτας καὶ τὸν δῆμον εὐνοίας οὕνεκα καὶ τῆς νῦν ἐπὶ τῇ χορηγίᾳ δημοκοπίας καὶ περιουσίας, ἣ δὴ πάνυ αὐτῷ πολλὴ προσελθοῦσα οὐκ ἐδόκει τοῖς πλείοσιν αὐτὸν ἐν ἰδιώτου μέτρῳ καθέξειν, ἐπὶ δὲ Ἀντωνίῳ μάλιστα, μὴ τὸν Καίσαρα, νέον ἄνδρα καὶ ἔνδοξον καὶ πλούσιον, ἑταιρισάμενος ὑφ’ ἑαυτὸν εἶναι πρότερος ἅψαιτο τῆς Καίσαρος δυναστείας. οἱ δὲ καὶ τοῖς τότε γιγνομένοις ἐφήδοντο, ὡς καὶ τῶν ἀνδρῶν ἀλλήλοις ἐμποδὼν ἐσομένων καὶ τοῦ Καίσαρος πλούτου τῇ ζητήσει τῶν χρημάτων αὐτίκα διαλυθησομένου καὶ σφίσι τοῦ ταμιείου περιουσίας πλήρους ἐξ αὐτῆς ἐσομένου· τὰ γὰρ πολλὰ τῶν κοινῶν εὑρήσειν παρὰ Καίσαρι.", "st": "3.21"}, {"sp": "N", "t": "πολλοί τε αὐτῶν ἐς δίκας τὸν Καίσαρα ὑπῆγον περὶ χωρίων, ἕτερος ἑτέρῳ ἐπιλέγοντες ἄλλα τε ἕκαστοι καὶ τὸ κοινὸν ἐπὶ τοῖς πλείστοις, ἐκ προγραφῆς εἶναι τῶν δημευθέντων ἢ φυγόντων ἢ ἀναιρεθέντων. ἦγόν τε τὰς δίκας ἐπὶ τὸν Ἀντώνιον αὐτὸν ἢ τὸν ἕτερον ὕπατον Δολοβέλλαν. εἰ δέ τις καὶ ἐφ’ ἑτέρας ἀρχῆς ἐδικάζετο, πανταχοῦ τὰ πολλὰ ὁμοίως ὁ Καῖσαρ εἰς χάριν Ἀντωνίου ἡττᾶτο, τά τε ὠνήματα τῷ πατρὶ ἐκ τοῦ δημοσίου γενόμενα ἐπιδεικνὺς καὶ τὸ τελευταῖον ψήφισμα τὸ βεβαιοῦν τὰ Καίσαρι πεπραγμένα πάντα. ὕβρεις τε πολλαὶ παρὰ τὰς δίκας ἦσαν αὐτῷ, καὶ τὸ τῆς ζημίας προύκοπτεν ἐς ἄπειρον, ἔστε Πέδιον καὶ Πινάριον (οὗτοι γὰρ τὴν ἐκ τῶν Καίσαρος διαθηκῶν τοῦ κλήρου μοῖραν εἶχον) μέμψασθαι τῷ Ἀντωνίῳ περί τε σφῶν αὐτῶν καὶ περὶ τοῦ Καίσαρος ὡς ἄδικα πασχόντων παρὰ τὸ ψήφισμα τῆς βουλῆς. ᾤοντό τε αὐτὸν τὰ ἐς ὕβριν ἐκλύειν δεῖν μόνον, τὰ ἄλλα δὲ πάντα κυροῦν, ὅσα τῷ Καίσαρι πέπρακται.", "st": "3.22"}, {"sp": "N", "t": "ὁ δὲ ὡμολόγει μὲν τὰ πρασσόμενα ἴσως ἐναντίον ἔχειν τι τοῖς συνεψηφισμένοις, καὶ τὰ ἐψηφισμένα δ’ ἔφη τοῖς τότε δόξασιν ἐναντίως γεγράφθαι. μόνης γὰρ τῆς ἀμνηστίας ἐπειγούσης, τὸ ’μηδὲν ἀνατρέπειν τῶν προδιῳκημένων,’ οὐ τοῦδ’ αὐτοῦ γε χάριν οὐδὲ ἐφ’ ἅπασιν ἁπλῶς μᾶλλον ἢ ἐς εὐπρέπειαν καὶ παρηγορίαν τοῦ δήμου θορυβουμένου τούτοις, ἐπιγραφῆναι. εἶναι δὲ δικαιότερον τῇ γνώμῃ τοῦ ψηφίσματος μᾶλλον ἢ τῷ ῥήματι χρωμένους μὴ παρὰ τὸ εἰκὸς ἀντιπράττειν ἀνδράσι τοσοῖσδε ἰδίων ἢ προγονικῶν κτήσεων κατὰ στάσιν ἐκπεσοῦσιν ὑπὲρ νεανίσκου τοσόνδε πλοῦτον ἀλλότριόν τε καὶ οὐκ ἰδιωτικὸν παρ’ ἐλπίδα λαβόντος καὶ οὐκ ἐπιδεξίως, ἀλλ’ ἐς θρασύτητα τῇ τύχῃ χρωμένου. σφῶν μέντοι φείσεσθαι τὸ μέρος νειμαμένων πρὸς Καίσαρα. ὧδε μὲν ὁ Ἀντώνιος τοῖς ἀμφὶ τὸν Πινάριον ἀπεκρίνατο. καὶ εὐθὺς ἐνέμοντο, ἵνα μὴ καὶ τὸ μέρος ἐν ταῖς δίκαις προσαπόλοιτο, οὐ σφῶν ἕνεκα αὐτῶν, ἀλλὰ καὶ τόδε τοῦ Καίσαρος· ἔμελλον γὰρ αὐτῷ μετ’ οὐ πολὺ πάντα χαριεῖσθαι.", "st": "3.22"}, {"sp": "N", "t": "θέας δὲ πλησιαζούσης, ἣν ἔμελλεν ὑπὲρ Βρούτου στρατηγοῦντος ἐπιδώσειν Γάιος Ἀντώνιος ὁ ἀδελφὸς Ἀντωνίου, καὶ τἆλλα τοῦ Βρούτου τῆς στρατηγίας ἐπιτροπεύων ἀπόντος, παρασκευή τε ἦν ἐς αὐτὴν δαψιλὴς καὶ ἐλπὶς ἐν τῇ θέᾳ τὸν δῆμον ἐπικλασθέντα καλέσειν τοὺς ἀμφὶ τὸν Βροῦτον. ὁ δὲ Καῖσαρ ἀντιθεραπεύων τὸ πλῆθος, ὅσον ἀργύριον ἐκ τῆς πράσεως ἐγίγνετο, αἰεὶ κατὰ μέρος τοῖς φυλάρχοις ἀνεδίδου νέμειν τοῖς φθάνουσι λαβεῖν· καὶ ἐς τὰ πωλητήρια περιιὼν ἀποκηρύσσειν ἔλεγεν ὅσου δύναιντο πάντα τοὺς πιπράσκοντας ὀλιγίστου, διά τε δίκας ἀμφίβολα ἢ ἐπίφοβα ἔτι ὄντα καὶ διὰ τὴν Καίσαρος σπουδήν. ἅπερ αὐτῷ πάντα τὸν δῆμον εἰς εὔνοιαν ἤγειρεν καὶ ἐς ἔλεον, ὡς ἀναξίῳ τοιάδε πάσχειν. ὡς δ’ ἐπὶ τῇ κληρονομίᾳ καὶ τὴν ἴδιον αὑτοῦ περιουσίαν ὅση τε παρὰ Ὀκταουίου τοῦ πατρὸς ἢ ἑτέρωθεν ἦν αὐτῷ, καὶ τὰ τῆς μητρὸς πάντα καὶ τὰ Φιλίππου, καὶ τὸ μέρος τοῦ κλήρου Πινάριον καὶ Πέδιον αἰτήσας, προύθηκεν ἐς τὴν διανέμησιν πιπράσκεσθαι, ὡς τῆς Καίσαρος περιουσίας οὐδ’ ἐς τοῦτο μόνον ἀρκούσης διὰ τὰς ἐπηρείας, ὁ δῆμος οὐκέτι παρὰ τοῦ πρώτου Καίσαρος, ἀλλὰ παρὰ τοῦδε αὐτοῦ τὴν ἐπίδοσιν λογιζόμενος εἶναι ἐκπαθῶς αὐτὸν ἠλέει καὶ ἐπῄνουν ὧδε πάσχοντα καὶ ὧδε φιλοτιμούμενον δῆλοί τε ἦσαν οὐκ ἐς πολὺ τὴν ἐς αὐτὸν Ἀντωνίου ὕβριν ὑπεροψόμενοι.", "st": "3.23"}, {"sp": "N", "t": "Διέδειξαν δὲ παρὰ τὰς Βρούτου θέας, πολυτελεστάτας δὴ γενομένας· ἐμμίσθων γάρ τινων ἀνακραγόντων κατακαλεῖν Βροῦτόν τε καὶ Κάσσιον, ἐπεὶ τὸ λοιπὸν αὐτοῖς θέατρον συνεδημαγωγεῖτο ἐς τὸν ἔλεον, ἐσέδραμον ἀθρόοι καὶ τὰς θέας ἐπέσχον, μέχρι τὴν ἀξίωσιν αὐτῶν σβέσαι.", "st": "3.24"}, {"sp": "N", "t": "Βροῦτος δὲ καὶ Κάσσιος, ἐπεὶ σφῶν τὰς ἐλπίδας τὰς ἐν ταῖς θέαις ὁ Καῖσαρ διέχεεν, ἔγνωσαν εἰς Συρίαν καὶ Μακεδονίαν, ὡς πρὸ Ἀντωνίου καὶ Δολοβέλλα σφίσιν ἐψηφισμένας, χωρεῖν καὶ βιάζεσθαι. καὶ τῶνδε φανερῶν γενομένων ἠπείγετο καὶ Δολοβέλλας εἰς τὴν Συρίαν, καὶ πρὸ Συρίας ἐς τὴν Ἀσίαν, ὡς χρηματιούμενος ἀπ’ αὐτῆς. ὁ δ’ Ἀντώνιος ἡγούμενος ἐς τὰ μέλλοντά οἱ δεήσειν δυνάμεως, τὴν ἐν Μακεδονίᾳ στρατιάν, ἀρετῇ τε οὖσαν ἀρίστην καὶ πλήθει μεγίστην, — ἓξ γὰρ ἦν τέλη (καὶ ὅσον ἄλλο πλῆθος αὐτοῖς τοξοτῶν καὶ ψιλῶν ἢ γυμνητῶν συνεζεύγνυτο, ἵππος τε πολλὴ καὶ παρασκευὴ κατὰ λόγον ἐντελής) δοκοῦντα προσήκειν Δολοβέλλᾳ, Συρίαν καὶ τὰ ἐς Παρθυαίους ἐπιτετραμμένῳ, διότι καὶ ὁ Καῖσαρ αὐτοῖς ἐς Παρθυαίους ἔμελλε χρῆσθαι—πρὸς ἑαυτὸν ἐπενόει μετενεγκεῖν, ὅτι καὶ μάλιστα ἦν ἀγχοῦ, ὡς τὸν Ἰόνιον περάσαντα εὐθὺς ἐν τῇ Ἰταλίᾳ εἶναι.", "st": "3.24"}, {"sp": "N", "t": "ἄφνω δὴ φήμη κατέσκηψε, Γέτας τὸν θάνατον τὸν Καίσαρος πυθομένους Μακεδονίαν πορθεῖν ἐπιτρέχοντας, καὶ ὁ Ἀντώνιος τὴν βουλὴν ᾔτει τὸν στρατὸν ὡς Γέταις ἐπιθήσων δίκην· ἔς τε γὰρ Γέτας αὐτὸν πρὸ Παρθυαίων Καίσαρι παρεσκευάσθαι καὶ τὰ Παρθυαίων ἠρεμεῖν ἐν τῷ παρόντι. ἡ μὲν οὖν βουλὴ τὴν φήμην ὑπενόει καὶ τοὺς ἐπισκεψομένους ἔπεμψεν· ὁ δὲ Ἀντώνιος τὸν φόβον αὐτῶν καὶ τὴν ὑπόνοιαν ἐκλύων ἐψηφίσατο μὴ ἐξεῖναί πω κατὰ μηδεμίαν αἰτίαν περὶ δικτάτορος ἀρχῆς μήτε εἰπεῖν μήτ’ ἐπιψηφίζειν μήτε λαβεῖν διδομένην, ἢ τὸν ἐκ τῶνδέ τινος ὑπεριδόντα νηποινεὶ πρὸς τῶν ἐντυχόντων ἀναιρεῖσθαι. καὶ τῷδε μάλιστα ἑλὼν τοὺς ἀκούοντας καὶ τοῖς ὑπὲρ Δολοβέλλα πράττουσι συνθέμενος ἓν τέλος δώσειν, ᾑρέθη τῆς ἐν Μακεδονίᾳ δυνάμεως εἶναι στρατηγὸς αὐτοκράτωρ. καὶ ὁ μὲν ἔχων, ἃ ἐβούλετο, Γάιον τὸν ἀδελφὸν αὐτίκα σὺν ἐπείξει τὸ δόγμα φέροντα τῷ στρατῷ διεπέμπετο· οἱ δὲ ἐπισκέπται τῆς φήμης ἐπανελθόντες Γέτας ἔλεγον οὐκ ἰδεῖν ἐν Μακεδονίᾳ, προσέθεσαν δέ, εἴτε ἀληθὲς εἴτε ὑπ’ Ἀντωνίου διδαχθέντες, ὅτι δέος ἦν, μὴ τῆς στρατιᾶς ποι μετελθούσης οἱ Γέται τὴν Μακεδονίαν ἐπιδράμοιεν.", "st": "3.25"}, {"sp": "N", "t": "ὧδε μὲν εἶχε τὰ ἐν Ῥώμῃ, Κάσσιος δὲ καὶ Βροῦτος χρήματα καὶ στρατιὰν συνέλεγον, καὶ Τρεβώνιος ὁ τῆς Ἀσίας ἡγούμενος τὰς πόλεις αὐτοῖς ἐτείχιζε καὶ Δολοβέλλαν ἐλθόντα οὐκ ἐδέχετο οὔτε Περγάμῳ οὔτε Σμύρνῃ, ἀλλὰ μόνην ἀγορὰν ἔξω τείχους ὡς ὑπάτῳ προυτίθει. ἐπιχειροῦντος δ’ ἐκείνου σὺν ὀργῇ τοῖς τείχεσι καὶ οὐδὲν ἀνύοντος, ὁ Τρεβώνιος αὐτὸν ἔφη δέξεσθαι Ἐφέσῳ καὶ ἐς τὴν Ἔφεσον εὐθὺς ἀπιόντι τοὺς ἐφεψομένους ἐκ διαστήματος ἔπεμπεν, οἳ νυκτὸς ἐπιγενομένης ἀπιόντα τὸν Δολοβέλλαν ὁρῶντες καὶ οὐδὲν ἔτι ὑπονοοῦντες, ὀλίγους σφῶν ὑπολιπόντες ἕπεσθαι αὐτῷ, ἐς τὴν Σμύρναν ἐπανῆλθον. καὶ τοὺς ὀλίγους ὁ Δολοβέλλας ἐνεδρεύσας τε καὶ περιλαβὼν ἔκτεινε καὶ ἦλθε τῆς αὐτῆς ἔτι νυκτὸς ἐς Σμύρναν καὶ αὐτὴν ἀφύλακτον εὑρὼν εἷλε διὰ κλιμάκων.", "st": "3.26"}, {"sp": "N", "t": "Τρεβώνιος δὲ τοῖς συλλαμβάνουσιν αὐτὸν ἔτι εὐναζόμενον ἡγεῖσθαι πρὸς Δολοβέλλαν ἐκέλευεν· ἕψεσθαι γὰρ αὐτοῖς ἑκών. καί τις τῶν λοχαγῶν αὐτὸν ἐπισκώπτων ἠμείψατο· “ἴθι σύ, δεῦρο τὴν κεφαλὴν καταλιπών· ἡμῖν γὰρ οὐ σέ, ἀλλὰ τὴν κεφαλὴν ἄγειν προστέτακται.” καὶ τόδε εἰπὼν εὐθὺς ἀπέτεμε τὴν κεφαλήν. ἅμα δὲ ἡμέρᾳ Δολοβέλλας μὲν αὐτὴν προσέταξεν ἐπὶ τοῦ στρατηγικοῦ βήματος, ἔνθα ὁ Τρεβώνιος ἐχρημάτιζε, προτεθῆναι· ἡ στρατιὰ δὲ σὺν ὀργῇ καὶ ὁ οἰκετικὸς ἄλλος ὅμιλος αὐτῆς, ἐπεὶ τοῦ φόνου Καίσαρος ὁ Τρεβώνιος μετεσχήκει καὶ κτεινομένου τὸν Ἀντώνιον ἐν ὁμιλίᾳ περὶ θύρας τοῦ βουλευτηρίου περιεσπάκει, εἰς τε τὸ ἄλλο σῶμα αὐτοῦ ποικίλως ἐνύβριζον καὶ τὴν κεφαλὴν οἷα σφαῖραν ἐν λιθοστρώτῳ πόλει διαβάλλοντες ἐς ἀλλήλους ἐπὶ γέλωτι συνέχεάν τε καὶ συνέτριψαν. καὶ πρῶτος ὅδε τῶν φονέων δίκην τήνδε ἐδεδώκει.", "st": "3.26"}, {"sp": "N", "t": "ὁ δ’ Ἀντώνιος ἐς τὴν Ἰταλίαν τὸν στρατὸν ἐκ τῆς Μακεδονίας διενεγκεῖν ἐπενόει, καὶ προφάσεως ἄλλης ἐς τοῦτο ἀπορῶν ἠξίου τὴν βουλὴν ἀντὶ τῆς Μακεδονίας ἐναλλάξαι οἱ τὴν ἐντὸς Ἄλπεων Κελτικήν, ἧς ἡγεῖτο Δέκμος Βροῦτος Ἀλβῖνος, εἰδὼς μέν, ὅτι καὶ ὁ Καῖσαρ ἐκ τῆσδε τῆς Κελτικῆς ὁρμώμενος ἐκράτησε Πομπηίου, ὡς δὲ τὸν στρατὸν δόξων οὐκ ἐς τὴν Ἰταλίαν, ἀλλ’ ἐς τὴν Κελτικὴν μετακαλεῖν. ἡ δὲ βουλὴ τήνδε τὴν Κελτικὴν ἀκρόπολιν ἐπὶ σφίσιν ἡγουμένη ἐδυσχέραινέ τε καὶ τῆς ἐνέδρας τότε πρῶτον ᾔσθοντο καὶ τὴν Μακεδονίαν δόντες αὐτῷ μετενόουν. ἰδίᾳ τε αὐτῶν οἱ δυνατοὶ ἐπέστελλον τῷ Δέκμῳ τῆς ἀρχῆς ἐγκρατῶς ἔχεσθαι καὶ στρατὸν ἄλλον καὶ χρηματα ἀγείρειν, εἰ πρὸς Ἀντωνίου βιάζοιτο· οὕτως ἐδεδοίκεσάν τε καὶ ἐν ὀργῇ τὸν Ἀντώνιον εἶχον. ὁ δὲ ἀντὶ μὲν τῆς βουλῆς ἐπενόει τὸν δῆμον αἰτῆσαι νόμῳ τὴν Κελτικήν, ᾧ τρόπῳ καὶ ὁ Καῖσαρ αὐτὴν πρότερον εἰλήφει καὶ Συρίαν Δολοβέλλας ὑπογύως, ἐς δὲ φόβον τῆς βουλῆς τὴν στρατιὰν ἐς τὸ Βρεντέσιον ἐκέλευε Γαΐῳ τὸν Ἰόνιον περᾶν αὐτίκα.", "st": "3.27"}, {"sp": "N", "t": "καὶ ὁ μὲν ἔμελλε ποιήσειν, ὡς προσετέτακτο· θέαι δ’ ἦσαν, ἃς Κριτώνιος ἀγορανομῶν ἔμελλε τελέσειν· καὶ ὁ Καῖσαρ ἐς τὰς θέας τῷ πατρὶ τόν τε χρύσεον θρόνον καὶ στέφανον παρεσκεύαζεν, ἅπερ αὐτῷ κατὰ πάσας θέας ἐψηφίσαντο προτίθεσθαι. τοῦ Κριτωνίου δὲ εἰπόντος οὐκ ἀνέξεσθαι τιμωμένου Καίσαρος ἐν ταῖς αὑτοῦ δαπάναις, ὁ Καῖσαρ αὐτὸν ἐς τὸν Ἀντώνιον ἦγεν ὡς ὕπατον. Ἀντωνίου δὲ εἰπόντος ἐς τὴν βουλὴν ἐπανοίσειν, χαλεπήνας ὁ Καῖσαρ, “ἀνάφερε,” εἶπεν, “ἐγὼ δὲ τὸν θρόνον, ἕως ἂν ᾖ τὸ δόγμα, προθήσω.” καὶ ὁ Ἀντώνιος χαλεπήνας ἐκώλυσεν. ἐκώλυσε δὲ καὶ ἐν ταῖς ἑξῆς θέαις ἔτι παραλογώτερον, ἃς αὐτὸς ὁ Καῖσαρ ἐτέλει, ἀνακειμένας ἐκ τοῦ πατρὸς Ἀφροδίτῃ Γενετείρᾳ, ὅτε περ αὐτῇ καὶ τὸν νεὼν ὁ πατὴρ τὸν ἐν ἀγορᾷ ἅμα αὐτῇ ἀγορᾷ ἀνετίθει. τότε δὴ καὶ μάλιστα μῖσος ἤδη σαφὲς ἐκ πάντων ἐς τὸν Ἀντώνιον ἐγίγνετο, ὡς οὐκ ἐς τὸν νῦν Καίσαρα φιλονικοῦντα μᾶλλον ἢ ἐς τὸν πρότερον ὑβρίζοντα ἀχαρίστως.", "st": "3.28"}, {"sp": "N", "t": "αὐτός τε ὁ Καῖσαρ μετὰ πλήθους οἷα φρουρᾶς τὸν δῆμον καὶ τοὺς εὖ τι παθόντας ὑπὸ τοῦ πατρὸς καὶ τοὺς ἐκείνῳ στρατευσαμένους περιθέων ἐπιφθόνως ἱκέτευεν οὗ μὲν αὐτοῦ τοιάδε καὶ τοσάδε πάσχοντος ὑπερορᾶν καὶ ἀμελεῖν ἑκόντος, Καίσαρι δὲ τῷ σφῶν αὐτοκράτορι καὶ εὐεργέτῃ ἀμύνειν, ἀτιμουμένῳ πρὸς Ἀντωνίου· ἀμυνεῖν δὲ καὶ σφίσιν αὐτοῖς, οὐδὲν ἕξουσι βέβαιον ὧν εἰλήφασι παρὰ Καίσαρος, εἰ μηδὲ αὐτῷ Καίσαρι μενεῖ τὰ ἐψηφισμένα βέβαια. Ἀντωνίου τε πανταχοῦ τῆς πόλεως ἐς τὰ ὑψηλὰ ἀναπηδῶν κατεβόα· “Καίσαρι μὲν δι’ ἐμὲ μήτε ὀργίζεσθαι μήτε ἐνυβρίζειν, εὐεργέτῃ σοῦ μάλιστα, ὦ Ἀντώνιε, ἐς τὰ μάλιστα γεγενημένῳ· ἐμοὶ δὲ τῶν μὲν ὕβρεων, ἐς ὅσον θέλεις, ἐμφορεῖσθαι, τὴν δὲ τῆς οὐσίας ἁρπαγὴν ἐπισχεῖν, μέχρι τοὺς πολίτας κομίσασθαι τὴν διανέμησιν καὶ τὰ λοιπὰ πάντα ἔχειν· ἀρκέσειν γὰρ ἐμοὶ πενομένῳ τήν τε τοῦ πατρὸς δόξαν, ἂν διαμένῃ, καὶ τὴν τοῦ δήμου διανέμησιν, ἐὰν ἐάσῃς δοθῆναι.”", "st": "3.28"}, {"sp": "N", "t": "ἐφ’ οἷς ἤδη παρὰ πάντων συνεχεῖς ἐγίγνοντο καὶ φανεραὶ κατὰ τοῦ Ἀντωνίου βοαί. ἀπειλησαμένου δὲ αὐτοῦ τῷ Καίσαρι πικρότερον καὶ τῆς ἀπειλῆς ἐξενεχθείσης ἐς τὸ φανερόν, ἔτι μᾶλλον ἅπαντες ὥρμηντο· καὶ οἱ τῆς φρουρᾶς Ἀντωνίου ταξίαρχοι, ἐστρατευμένοι τε Καίσαρι τῷ προτέρῳ καὶ ἐς τὰ μέγιστα ὑπ’ Ἀντωνίου τότε προτιμώμενοι, τὴν ὕβριν αὐτὸν ἐπισχεῖν ἠξίουν καὶ διὰ σφᾶς καὶ δι’ ἑαυτόν, ὑπὸ Καίσαρι στρατευσάμενον καὶ τῶνδε τῶν οἱ παρόντων ἀγαθῶν παρ’ ἐκείνου τυχόντα. συγγιγνώσκων οὖν ὁ Ἀντώνιος ἀληθέσιν οὖσιν τούτοις καὶ τοὺς προφέροντας αὐτὰ αἰδούμενος, ἤδη δέ τι καὶ τοῦ Καίσαρος αὐτοῦ διὰ τὸν δῆμον ἐς τὴν ἀλλαγὴν τῆς Κελτικῆς δεόμενος, ὡμολόγει τοῖς λεγομένοις καὶ ἐπώμνυεν αὐτὰ καὶ οἷ πάνυ ἀβούλητα εἶναι, τῆς δὲ γνώμης τοῦ νεανίσκου ἕνεκεν μετατίθεσθαι, ἐπηρμένου τε ἐπαχθῶς ἔτι τηλικοῦδε ὄντος καὶ οὐδὲν ἔχοντος αἰδέσιμον ἢ τίμιον ἐς πρεσβυτέρους τε καὶ ἐς ἄρχοντας· ἅπερ αὐτοῦ μὲν χάριν τοῦ νεανίσκου χρῄζειν ἔτι νουθεσίας, σφῶν δὲ τῶν ταῦτα ἀξιούντων ἕνεκα αὐτὸς καθέξειν τῆς ὀργῆς καὶ ἐς τὴν προτέραν ἑαυτοῦ φύσιν τε καὶ γνώμην ἐπανήξειν, ἢν κἀκεῖνος ἀπέχηται τῆς ἀμετρίας.", "st": "3.29"}, {"sp": "N", "t": "ταῦτα οἱ ταξίαρχοι ἀσπασάμενοι συνῆγον ἀμφοτέρους. οἱ δὲ ἐπεμέμφοντο ἀλλήλοις καὶ συνέβαινον ἐς φιλίαν. ὅ τε νόμος ὁ περὶ τῆς Κελτικῆς προυγράφετο αὐτίκα, ὀρρωδούσης πάνυ τῆς βουλῆς καὶ ἐπινοούσης, εἰ μὲν ὁ Ἀντώνιος αὐτὸν προβουλεύοι, κωλύειν προβουλευόμενον, εἰ δὲ ἀπροβούλευτον ἐς τὸν ο͂ῆμον ἐσφέροι, τοὺς δημάρχους ἐς κώλυσιν ἐπιπέμπειν. ἦσαν δ’ οἳ καὶ τὸ ἔθνος ὅλως ἐλευθεροῦν ἡγεμονίας ἠξίουν· οὕτως ἐδεδοίκεσαν ἀγχοῦ τὴν Κελτικὴν οὖσαν. ὁ δὲ Ἀντώνιος αὐτοῖς ἀντενεκάλει, εἰ Δέκμῳ μὲν αὐτὴν πιστεύουσιν, ὅτι Καίσαρα ἀπέκτεινεν, αὑτῷ δ’ ἀπιστοῦσιν, ὅτι οὐκ ἀπέκτεινε τὸν καταστρεψάμενον αὐτὴν καὶ κλίναντα ἐς γόνυ, ἀπορρίπτων ἤδη ταῦτα φανερῶς ἐς ἅπαντας ὡς ἐφηδομένους τοῖς γεγονόσιν. ἐλθούσης δὲ τῆς κυρίας ἡμέρας ἡ μὲν βουλὴ τὴν λοχῖτιν ἐνόμιζεν ἐκκλησίαν συλλεγήσεσθαι, οἱ δὲ νυκτὸς ἔτι τὴν ἀγορὰν περισχοινισάμενοι τὴν φυλέτιν ἐκάλουν, ἀπὸ συνθήματος ἐληλυθυῖαν. καὶ ὁ δημότης λεώς, ἀχθόμενος τῷ Ἀντωνίῳ, συνέπρασσεν ὅμως διὰ τὸν Καίσαρα ἐφεστῶτα τοῖς περισχοινίσμασι καὶ δεόμενον. ἐδεῖτο δὲ μάλιστα μέν, ἵνα μὴ Δέκμος ἄρχοι χώρας τε ἐπικαίρου καὶ στρατιᾶς ἀνδροφόνος ὢν τοῦ πατρός, ἐπὶ δὲ τούτῳ καὶ ἐς χάριν Ἀντωνίου συνηλλαγμένου. προσεδόκα δὲ ἄρα τι καὶ αὐτὸς ἀντιλήψεσθαι παρὰ Ἀντωνίου. διαφθαρέντων δὲ χρήμασι τῶν δημάρχων ὑπ’ Ἀντωνίου καὶ κατασιωπώντων ὁ νόμος ἐκυροῦτο, καὶ ὁ στρατὸς Ἀντωνίῳ μετ’ αἰτίας εὐπρεποῦς ἤδη τὸν Ἰόνιον ἐπέρα.", "st": "3.30"}, {"sp": "N", "t": "τῶν δὲ δημάρχων τινὸς ἀποθανόντος, ἐς τὴν ἀντ’ αὐτοῦ χειροτονίαν ὁ Καῖσαρ συνέπρασσεν Φλαμινίῳ· καὶ ὁ δῆμος οἰόμενος αὐτὸν ἐπιθυμοῦντα τῆς ἀρχῆς διὰ τὸ νεώτερον τῆς ἡλικίας οὐ παραγγέλλειν, ἐπενόουν ἐν ταῖς χειροτονίαις δήμαρχον ἀποφῆναι τὸν Καίσαρα. ἡ δὲ βουλὴ τῆς αὐξήσεως ἐφθόνει καὶ ἐδεδοίκει, μὴ δημαρχῶν τοὺς φονέας τοῦ πατρὸς ἐπὶ τὸν δῆμον ἐς δίκην ἀπαγάγοι· Ἀντώνιός τε τῆς ἄρτι συγκειμένης πρὸς τὸν Καίσαρα φιλίας ὑπεριδών, εἴτε ἐς χάριν τῆς βουλῆς ἢ παρηγορίαν, ἀχθομένης τῷ περὶ τῆς Κελτικῆς νόμῳ, εἴτε ἀπ’ οἰκείας γνώμης, προύγραφεν ὡς ὕπατος μηδενὶ Καίσαρα ἐγχειρεῖν παρανόμως, ἢ χρήσεσθαι κατ’ αὐτοῦ παντὶ μέτρῳ τῆς ἐξουσίας. ἀχαρίστου δ’ ἐς τὸν Καίσαρα καὶ ὑβριστικῆς ἅμα ἐς αὐτὸν καὶ τὸν δῆμον τῆς προγραφῆς γενομένης, ὁ μὲν δῆμος διώργιστο καὶ φιλονικήσειν ἔμελλον ἐν ταῖς χειροτονίαις, ὥστε δεῖσαι τὸν Ἀντώνιον καὶ ἀνελεῖν τὴν χειροτονίαν, τοῖς ὑπολοίποις τῶν δημάρχων ἀρκούμενον· ὁ δὲ Καῖσαρ, ὡς σαφῶς ἐπιβουλευόμενος ἤδη, πολλοὺς περιέπεμπεν ἔς τε τὰς τοῦ πατρὸς ἀποικίδας πόλεις ἐξαγγέλλειν, ἃ πάσχοι, καὶ τὴν ἑκάστων γνώμην καταμανθάνειν· ἔπεμπε δὲ καὶ ἐς τὰ Ἀντωνίου στρατόπεδα ἐπιμίγνυσθαί τινας ἀγορὰν φέροντας καὶ ἐντυγχάνειν τοῖς θαρροῦσι μάλιστα καὶ ἐς τὸ πλῆθος διαρριπτεῖν ἀφανῶς βιβλία.", "st": "3.31"}, {"sp": "N", "t": "καὶ ὁ μὲν ἀμφὶ ταῦτα ἦν· οἱ ταξίαρχοι δὲ αὖθις παρὰ Ἀντωνίου καιρὸν αἰτήσαντες ἔλεγον·", "st": "3.32"}, {"sp": "N", "t": "“ἡμεῖς, ὦ Ἀντώνιε, καὶ ὅσοι ἄλλοι μετὰ σοῦ Καίσαρι στρατευσάμενοι τήν τε ἡγεμονίαν αὐτῷ συνεστησάμεθα καὶ ἐς τὰ καθ’ ἡμέραν αὐτῆς ὑπηρέται γιγνόμενοι διετελοῦμεν, ἔχθει μὲν ἴσῳ καὶ ἐπιβουλῇ τοὺς φονέας αὐτοῦ γιγνώσκομεν εἰς ἡμᾶς χρωμένους καὶ τὴν βουλὴν ἐκείνοις ἐπιρρέπουσαν, τοῦ δήμου δ’ ἐξελάσαντος αὐτοὺς ἀνεθαρρήσαμεν, οὐ πάντῃ τὰ Καίσαρος ὁρῶντες ἄφιλα οὐδὲ ἀμνήμονα οὐδὲ ἀχάριστα. τὴν δ’ ἐς τὸ μέλλον ἀσφάλειαν εἴχομεν ἐν σοί, φίλῳ τε Καίσαρος ὄντι καὶ ἡγεμονικωτάτῳ μετ’ ἐκεῖνον ἐκ πάντων καὶ ἄρχοντι νῦν ἡμῶν καὶ ἐς τὰ μάλιστα ἐπιτηδείῳ. ἀναφυομένων δὲ τῶν ἐχθρῶν καὶ θρασέως ἔς τε Συρίαν καὶ Μακεδονίαν βιαζομένων καὶ χρήματα καὶ στρατιὰν ἐφ’ ἡμᾶς συνιστάντων, καὶ τῆς βουλῆς σοι Δέκμον ἐπαλειφούσης, καὶ σοῦ τὰς φροντίδας ἐς τὴν Καίσαρος τοῦ νέου διαφορὰν δαπανῶντος, δέδιμεν εἰκότως, μὴ ἐς τὸν μέλλοντα καὶ ὅσον οὔπω παρόντα πόλεμον ἡ στάσις ὑμῶν τῷ πολέμῳ συνεπιθῆται καὶ διαπραχθῇ τοῖς ἐχθροῖς καθ’ ἡμῶν, ἃ βούλονται. ὧν ἐνθυμηθέντα σε ἀξιοῦμεν, ὁσίας τε χάριν ἐς τὸν Καίσαρα καὶ φειδοῦς ὑπὲρ ἡμῶν οὐδὲν ἐπιμέμπτων σοι γενομένων καὶ πρὸ ἡμῶν αὐτοῦ σοῦ τῶν συμφερόντων οὕνεκα, ἕως ἔτι δύνασαι, Καίσαρι μέν, ὅπερ ἀρκέσει, μόνον συνεπαμῦναι τοὺς φονέας τιμωρουμένῳ, σὲ δὲ αὐτίκα δυναστεύειν, ἐν ἀμερίμνῳ γενόμενόν τε καὶ ἡμᾶς γενέσθαι παρασκευάσαντα τοὺς ὑπέρ τε σφῶν αὐτῶν καὶ ὑπὲρ σοῦ δεδιότας.”", "st": "3.32"}, {"sp": "N", "t": "τοσαῦτα τοὺς ταξιάρχους εἰπόντας ὁ Ἀντώνιος ὧδε ἠμείψατο·", "st": "3.33"}, {"sp": "N", "t": "“ὅσῃ μὲν εὐνοίᾳ καὶ σπουδῇ πρὸς Καίσαρα περιόντα ἐχρώμην, φιλοκινδυνότατος ἐκ πάντων ἐς τὰς ἐκείνου χρείας γενόμενος, ἴστε σαφῶς, συστρατευσάμενοί τε καὶ τοῖς γιγνομένοις παρατυχόντες· ὅσῃ δ’ αὖ κἀκεῖνος εἰς ἐμὲ χάριτι καὶ προτιμήσει χρώμενος διετέλει, οὐ μαρτυρεῖν ἐμὲ δίκαιον. ἄμφω δὲ ταῦτα καὶ οἱ φονεῖς εἰδότες συνετίθεντο κἀμὲ Καίσαρι συνανελεῖν, ὡς ἐμοῦ περιόντος οὐ καθέξοντες ὧν ἐπενόουν. καὶ ὅστις αὐτοὺς μετέπεισε τῆς γνώμης, οὐκ εὐνοίᾳ τῆς ἐμῆς σωτηρίας ἔπεισεν, ἀλλ’ εὐπρεπείᾳ τῆς τυραννοκτονίας, ὡς μὴ δοκῶσι πολλοὺς ὥσπερ ἐχθρούς, ἀλλ’ ἕνα ἀνελεῖν ὡς τύραννον. τίς ἂν οὖν πιστεύσειεν ἐμὲ Καίσαρός τε ἀμελεῖν εὐεργέτου μοι γεγενημένου καὶ προτιμᾶν τοὺς ἐχθροὺς ἐκείνου καὶ τὸν φόνον ἑκόντα χαρίζεσθαι τοῖς ἐμοῖς ἐπιβούλοις, ὡς οἴεται Καῖσαρ ὁ νέος; πόθεν οὖν αὐτοῖς ἀμνηστία τοῦ φόνου καὶ ἡγεμονίαι; ταῦτα γὰρ ἐπικαλεῖν, ἀντὶ τῆς βουλῆς, ἐμοὶ βούλεται. μάθετε, ὡς ἐγένετο.", "st": "3.33"}, {"sp": "N", "t": "“Καίσαρος ἐν τῷ βουλευτηρίῳ σφαγέντος ἄφνω, δέος ἐπέσχεν ἐκ πάντων δὴ μάλιστα πλεῖστον ἐμὲ φιλίᾳ τε αὐτοῦ Καίσαρος καὶ ἀγνοίᾳ τοῦ ἀκριβοῦς· οὐ γάρ πω τὴν συνθήκην ἑώρων οὐδὲ ἐπὶ ὅσοις. ὁ δὲ δῆμος ἐθορυβεῖτο, καὶ οἱ σφαγεῖς σὺν μονομάχοις τὸ Καπιτώλιον καταλαβόντες ἀπέκλειον, καὶ ἡ βουλὴ σὺν ἐκείνοις ἦν, ᾗ καὶ νῦν ἐστι φανερώτερον, γέρα τε τοῖς ἀνελοῦσιν ὡς τυραννοκτόνοις ἐψηφίζετο. καὶ εἰ τύραννος ὁ Καῖσαρ ἐφάνη, ἡμῖν ὑπῆρχεν ἀπολέσθαι πᾶσιν ὡς τυράννου φίλοις. ὧδε δή με ἔχοντα θορύβου καὶ μερίμνης καὶ δέους, ὅτε οὐκ ἦν γνώμης παράδοξον οὐδὲ ἀπορῆσαι, σκοποῦντες εὑρήσετε, ἔνθα μὲν ἔδει τόλμης, θρασύτατον, ἔνθα δὲ ὑποκρίσεως, εὐμήχανον. τὸ μὲν δὴ πρῶτον ἐκ πάντων καὶ τὰ λοιπὰ συνέχον ἦν ἀναιρεθῆναι τὰ γέρα τὰ ψηφιζόμενα τοῖς ἀνδράσιν· ὅπερ, ἀντιτάξας ἐμαυτὸν ἐγὼ τῇ τε βουλῇ καὶ τοῖς σφαγεῦσιν ἐγκρατῶς, ἔπραττον σὺν θράσει παραβόλῳ καὶ ἐπικινδύνῳ, τότε μόνον ἡγούμενος ἡμᾶς τοὺς Καίσαρος ἀσφαλῶς περιέσεσθαι, ὅταν μὴ Καῖσαρ εἶναι δόξῃ τύραννος. τῷ δ’ αὐτῷ δέει τῶν ἐχθρῶν καὶ τῆς βουλῆς αὐτῆς ἐχομένων, ὅτε μὴ Καῖσαρ εἴη τύραννος, ἀνδροφονίας αὐτοὺς ἁλώσεσθαι, καὶ διὰ τοῦτο φιλονικούντων, εἶξα τῆς ἀμνηστίας διδομένης ἀντὶ τῶν γερῶν, ἵν’ ὅσων ἔχρῃζον ἀντιλάβοιμι. τὰ δὲ ἦν πόσα καὶ πηλίκα; μήτε τὴν ἐπωνυμίαν τοῦ Καίσαρος ἀπηλεῖφθαι τὴν ἐμοὶ μάλιστα πάντων ἡδίστην μήτε τὴν περιουσίαν δεδημεῦσθαι μήτε τὴν θέσιν, ἐφ’ ᾗ νῦν οὗτος γαυριᾷ, διαλελύσθαι μήτε τὰς διαθήκας ἀκύρους γενέσθαι τό τε σῶμα τεθάφθαι βασιλικῶς καὶ τιμὰς αὐτῷ τὰς πάλαι δεδομένας ἀθανάτους διαμένειν καὶ τὰ πεπραγμένα πάντα κύρια εἶναι καὶ τὸν ἐκείνου παῖδα καὶ τοὺς φίλους ἡμᾶς, καὶ στρατηγοὺς καὶ στρατιώτας, ἐν ἀσφαλεῖ γενέσθαι σωτηρίᾳ καὶ ἐνδόξῳ βίῳ ἀντὶ ἐπονειδίστου.", "st": "3.34"}, {"sp": "N", "t": "“ἆρ’ ὑμῖν ὀλίγα ἢ σμικρὰ τῆς ἀμνηστίας τὴν βουλὴν ἀνταιτῆσαι δοκῶ; ἢ δοῦναι ἂν αὐτὰ ἡ βουλὴ χωρὶς τῆς ἀμνηστίας; ἦν μὲν δὴ καὶ καθαρῶς ἀντιδοῦναι τάδε τ́ῶνδε ἄξιον καὶ φείσασθαι σὺν ἀληθεῖ γνώμῃ φονέων ἀνδρῶν ὑπὲρ ἀθανάτου Καίσαρος δόξης καὶ ἡμῶν ἀσφαλοῦς σωτηρίας· οὐ μὴν ἐγὼ μετὰ τῆσδε τῆς γνώμης ἐποίουν, ἀλλ’ ἀνατιθέμενος τὴν δίκην. ἐπεί γέ τοι τῆς βουλῆς ἐς ἃ πρῶτα ἔχρῃζον ἐκράτησα καὶ οἱ σφαγεῖς ὡς ἐν ἀμερίμνῳ μεθεῖντο, ἀνεθάρρησα καὶ τὴν ἀμνηστίαν παρέλυον, οὐ ψηφίσμασιν ἢ δόγμασιν (οὐ γὰρ ἦν), ἀλλ’ ἀσήμῳ δημοκοπίᾳ, τὸ σῶμα τοῦ Καίσαρος ἐπὶ προφάσει τῆς ταφῆς ἐς τὴν ἀγορὰν ἐκφέρων καὶ τὰ τραύματα ἀπογυμνῶν καὶ τὸ πλῆθος αὐτῶν καὶ τὴν ἐσθῆτα ἐπιδεικνὺς ᾑμαγμένην τε καὶ κατακεκομμένην καὶ τὴν ἀρετὴν καὶ τὸ φιλόδημον αὐτοῦ παλιλλογῶν, ἐκπαθῶς ἐν μέσῳ καὶ ὀδυρόμενος μὲν ὡς ἀνῃρημένον, κατακαλῶν δ’ ὡς θεόν. τάδε γάρ μου τὰ ἔργα καὶ ῥήματα ἠρέθισε τὸν δῆμον, καὶ τὸ πῦρ ἧψε μετὰ τὴν ἀμνηστίαν, καὶ ἐς τὰς οἰκίας τῶν ἐχθρῶν ἔπεμψε καὶ τοὺς ἄνδρας ἐξέβαλε τῆς πόλεως. τοῦτο δ’ ὅπως ἀντιπραττούσης καὶ λυπουμένης τῆς βουλῆς ἐγένετο, αὐτίκα ἔδειξαν, ἐμὲ μὲν αἰτιώμενοι τῆς δημοκοπίας, τοὺς δὲ φονέας ἐκπέμψαντες ἐπὶ τὰς τῶν ἐθνῶν ἡγεμονίας, Βροῦτον δὲ καὶ Κάσσιον ἐς Συρίαν καὶ Μακεδονίαν, αἳ μεσταὶ μεγάλων στρατῶν ἦσαν, ἐπείγεσθαι καὶ πρὸ τοῦ δεδομένου χρόνου διδάξαντες ἐπὶ προφάσει φροντίδος σίτου. ἕτερον δή με δέος ἔτι μεῖζον ἐπελάμβανεν, οὐκ ἔχοντά πω στρατὸν ἴδιον οὐδένα, μὴ πρὸς ἐνόπλους τοσούσδε ἄνοπλοι καθιστώμεθα. καὶ ὁ σύναρχος ὕποπτος ἦν, ἐμοί τε διάφορος ὢν αἰεὶ καὶ ὑποκρινόμενος ἐπιβουλεῦσαι τῷ Καίσαρι καὶ τὴν ἡμέραν τοῦ φόνου γενέθλιον τῇ πόλει τιθέμενος.", "st": "3.35"}, {"sp": "N", "t": "“ὧδε δὲ ἀπορῶν καὶ ἐπειγόμενος ἐξοπλίσαι τοὺς πολεμίους καὶ ἐς ἡμᾶς ἀντ’ ἐκείνων τὰ ὅπλα μετενεγκεῖν, Ἀμάτιον ἔκτεινα καὶ κατεκάλεσα Πομπήιον, ἵνα τοῖσδε αὖθις ἁλοῦσα ἡ βουλὴ πρός με μεταθοῖτο. καὶ οὐδ’ ὣς αὐτῇ πιστεύων ἔπεισα Συρίαν αἰτεῖν Δολοβέλλαν, οὐ παρὰ τῆς βουλῆς, ἀλλὰ παρὰ τοῦ δήμου νόμῳ, καὶ συνέπραξα αἰτοῦντι, ἵνα τοῖς τε σφαγεῦσι Δολοβέλλας ἐχθρὸς ἀντὶ φίλου γένοιτο καὶ τοῖς βουλευταῖς αἰσχρὸν ᾖ μετὰ Δολοβέλλαν ἀντειπεῖν ἐμοὶ περὶ Μακεδονίας. οὐ μέντ’ ἂν οὐδ’ ὥς μοι Μακεδονίαν ἔδοσαν, οὐδ’ ἐπὶ Δολοβέλλᾳ, διὰ τὴν ἐν αὐτῇ στρατιάν, εἰ μὴ τὴν στρατιὰν προμεθῆκα τῷ Δολοβέλλᾳ ὡς Συρίαν καὶ τὰ ἐς Πάρθους διαλαχόντι. τοὺς δ’ αὖ περὶ τὸν Κάσσιον οὔτε Μακεδονίαν ἀφείλοντο ἂν οὔτε Συρίαν, μὴ ἕτερα αὐτοῖς ἐς ἀσφάλειαν ἀντιλαβόντες ἔθνη. δεῆσαν οὖν ἀντιδοῦναι θεάσασθε, οἷα ἀνθ’ οἵων καὶ ὡς στρατοῦ γυμνὰ ἐδόθη, Κυρήνη τε καὶ Κρήτη· ὧν καὶ οἱ ἐχθροὶ καταφρονοῦσιν οὐκ ἀσφαλῶν σφίσιν ὄντων καὶ ἐς τὰ ἀφῃρημένα βιάζονται. οὕτω μὲν δὴ καὶ ὁ στρατὸς ἐς Δολοβέλλαν μετενήνεκτο ἀπὸ τῶν ἐχθρῶν τέχναις καὶ μηχαναῖς καὶ ἀντιδόσεσιν ἑτέρων· οὐ γάρ πω τῶν ὅπλων φανέντων ὑπὸ τοῖς νόμοις ἔδει πράσσειν.", "st": "3.36"}, {"sp": "N", "t": "“γεγενημένων δὲ τῶνδε καὶ τῶν ἐχθρῶν ἕτερον στρατὸν ἀγειράντων, ἔδει μοι τοῦ περὶ τὴν Μακεδονίαν στρατοῦ καὶ προφάσεως ἠπόρουν. φήμη δὲ κατέσκηψε Γέτας Μακεδονίαν πορθεῖν. ἀπιστουμένης δὲ καὶ ταύτης καὶ τῶν ἐπισκεψομένων ἀπεσταλμένων, εἰσηγησάμην ἐγὼ περὶ τῆς δικτάτορος ἀρχῆς μὴ ἐξεῖναι μήτε εἰπεῖν μήτε ἐπιψηφίσαι μήτε λαβεῖν διδομένην· ᾧ δὴ μάλιστα ὑπαχθέντες ἔδοσάν μοι τὸν στρατόν. καὶ ἐγὼ τότε πρῶτον ἐμαυτὸν ἡγησάμην ἰσόπαλον εἶναι τοῖς ἐχθροῖς, οὐ τοῖσδε τοῖς φανεροῖς, ὡς οἴεται Καῖσαρ, ἀλλὰ τοῖς πλέοσί τε καὶ δυνατωτέροις καὶ ἀφανέσιν ἔτι εἶναι θέλουσι. ταῦτα δ’ ἐργασαμένῳ μοι ἕτερος τῶν σφαγέων ἔλειπεν ἐν πλευραῖς, Βροῦτος ὁ Δέκμος, ἡγούμενος καὶ ὅδε χώρας ἐπικαίρου καὶ στρατοῦ πολλοῦ· ὃν ἐγὼ καὶ θρασύτερον εἰδὼς τὴν Κελτικὴν ἀφῃρούμην, ἐς εὐπρέπειαν ἔτι τῆς βουλῆς Μακεδονίαν ὑπισχνούμενος ἀντιδώσειν, γυμνὴν στρατοῦ γενομένην. ἀγανακτούσης δὲ τῆς βουλῆς καὶ τὴν ἐνέδραν ἤδη καθορώσης καὶ ἴστε οἷα καὶ ὅσα Δέκμῳ πολλῶν γραφόντων καὶ ἐπαλειφόντων ἤδη τοὺς μετ’ ἐμὲ ὑπάτους, ἐγὼ θρασύτερον ἔτι τὸ μὲν ἔθνος, ἀντὶ τῆς βουλῆς, νόμῳ παρὰ τοῦ δήμου λαβεῖν ἐπενόησα, τὸν δὲ στρατὸν ἀπὸ τῆς Μακεδονίας ἐς τὸ Βρεντέσιον ἐπέρων ὡς χρησόμενος δὴ ἐς τὰ ἐπείγοντα. καὶ σὺν θεοῖς εἰπεῖν, χρησόμεθα, ὡς ἂν αἱ χρεῖαι καλῶσιν.", "st": "3.37"}, {"sp": "N", "t": "“οὕτως ἐκ πολλοῦ δέους τοῦ πρὶν ἡμᾶς ἐπισχόντος μετεβάλομεν ἔς τε ἀσφάλειαν ὑπὲρ ἡμῶν αὐτῶν ἐγκρατῆ καὶ ἐς θάρσος ἐπὶ τοὺς ἐχθρούς· ὧν ἐκφανέντων ἀνεφάνη καὶ ἡ τῶν πλεόνων ἐς τοὺς πολεμίους σπουδή. ὁρᾶτε γάρ, ὅση μὲν αὐτοῖς ἐστι μεταμέλεια τῶν ἐψηφισμένων, ὅσος δὲ ἀγὼν ἀφελέσθαι με τὴν Κελτικὴν ἤδη δεδομένην. ἴστε, ἃ γράφουσι Δέκμῳ καὶ ὅσα τοὺς ὑπάτους τοὺς μετ’ ἐμὲ πείθουσι περὶ τῆς Κελτικῆς μεταψηφίσασθαι. ἀλλὰ σὺν θεοῖς τε πατρῴοις καὶ σὺν εὐσεβεῖ γνώμῃ καὶ σὺν ταῖς ὑμετέραις ἀνδραγαθίαις, μεθ’ ὧν καὶ ὁ Καῖσαρ ἐκράτει, ἀμυνοῦμεν αὐτῷ, τῷ τε σώματι ἐπεξιόντες καὶ τῇ γνώμῃ βοηθοῦντες.", "st": "3.38"}, {"sp": "N", "t": "“ταῦτά μοι γιγνόμενα μέν, ὦ συστρατιῶται, ἔτι ἔχρῃζον ἀπόρρητα εἶναι, γενόμενα δὲ ἐξενήνεκται πρὸς ὑμᾶς, οὓς ἐγὼ καὶ ἔργου καὶ λόγου κοινωνοὺς ἐς ἅπαντα τίθεμαι. καὶ τοῖς ἄλλοις, εἴ τινες αὐτὰ οὐ συνορῶσι, μεταφέρετε, πλὴν μόνου Καίσαρος ἀχαρίστως ἐς ἡμᾶς ἔχοντος.”", "st": "3.38"}, {"sp": "N", "t": "τοιαῦτα τοῦ Ἀντωνίου διεξιόντος, παρέστη τοῖς ταξιάρχαις αὐτὸν ἅπαντα μετ’ ἔχθρας ἀκριβοῦς ἐς τοὺς ἀνδροφόνους, ἐπιτεχνάζοντα τῇ βουλῇ, πεποιηκέναι. ἠξίουν δὲ καὶ ὣς τῷ Καίσαρι συναλλαγῆναι καὶ πείσαντες αὐτοὺς συνήλλασσον αὖθις ἐν τῷ Καπιτωλίῳ. οὐ πολὺ δὲ ὕστερον ὁ Ἀντώνιος τῶν σωματοφυλάκων τινὰς ἐς τοὺς φίλους παρήγαγεν ὡς ὑπηρέτας γενομένους ἐπιβουλεύοντος αὑτῷ τοῦ Καίσαρος, εἴτε συκοφαντῶν εἴτε τῷ ὄντι νομίσας εἴτε περὶ τῶν εἰς τὰ στρατόπεδα περιπεμφθέντων πυθόμενος καὶ τὴν ἐς τὸ ἔργον ἐπιβουλὴν μεταφέρωι ἐς τὸ σῶμα. ὅ τε λόγος ἐκδραμὼν αὐτίκα θόρυβον ἤγειρε πάνδημον, καὶ ἀγανάκτησις ἦν. ὀλίγοι μὲν γάρ, οἷς τι λογισμοῦ βαθέος ἦν, ᾔδεσαν Καίσαρι συμφέρειν Ἀντώνιον καὶ βλάπτοντα ὅμως περιεῖναι, ἐπίφοβον ὄντα τοῖς φονεῦσιν· ἀποθανόντος γὰρ ἀδεέστερον ἐκείνους ἅπασιν ἐπιτολμήσειν, βοηθουμένους μάλιστα ὑπὸ τῆς βουλῆς. ὧδε μὲν εἴκαζον οἱ συνετώτεροι· τὸ δὲ πλέον, ὁρῶντες, οἷα καθ’ ἑκάστην ἡμέραν ὁ Καίσαρ ὑβριζόμενός τε καὶ ζημιούμενος πάσχοι, οὐκ ἄπιστον ἐτίθεντο τὴν διαβολὴν οὐδὲ ὅσιον ἢ ἀνεκτὸν ἐνόμιζον Ἀντώνιον ὑπατεύοντα ἐς τὸ σῶμα ἐπιβεβουλεῦσθαι.", "st": "3.39"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ καὶ πρὸς οὕτως ἔχοντας ἐξέτρεχε σὺν ὀργῇ μανιώδει καὶ ἐβόα αὐτὸς ἐπιβουλεύεσθαι πρὸς Ἀντωνίου ἐς τὴν παρὰ τῷ δήμῳ φιλίαν ἔτι οἱ μόνην οὖσαν· ἐπί τε τὰς θύρας τοῦ Ἀντωνίου δραμὼν τὰ αὐτὰ ἐβόα καὶ θεοὺς ἐμαρτύρετο καὶ ἀρὰς ἠρᾶτο πάσας καὶ ἐς δίκην ἐλθεῖν προυκαλεῖτο. οὐδενὸς δὲ προϊόντος, “ἐν τοῖς φίλοις,” ἔφη, “δέχομαι τοῖς σοῖς κριθῆναι,” καὶ εἰπὼν ἐπέτρεχεν ἔσω. κωλυθεὶς δὲ αὖθις ᾤμωζε καὶ ἐλοιδορεῖτο αὐτῷ καὶ τοῖς περὶ θύρας ἠγανάκτει κωλύουσι τὸν Ἀντώνιον ἐλεγχθῆναι. ἀπιών τε τὸν δῆμον ἐμαρτύρετο, εἴ τι πάθοι, πρὸς Ἀντωνίου δολοφονεῖσθαι. λεγομένων δὲ τῶνδε σὺν πάθει πολλῷ μετέπιπτε τὸ πλῆθος, καί τις αὐτοῖς τῆς πρὶν δόξης μετάνοια ἐνεγίγνετο. εἰσὶ δὲ οἳ καὶ τότε ἀπιστοῦντες ὤκνουν ἑκατέρῳ τὸ πιστὸν νέμειν, καί τινες ὑπόκρισιν ἀμφοῖν τὰ γιγνόμενα διέβαλλον εἶναι, συνθεμένων μὲν ἄρτι ἐν ἱερῷ, μηχανωμένων δὲ ταῦτα ἐπὶ τοὺς ἐχθρούς. οἱ δὲ αὐτὰ τὸν Ἀντώνιον ἡγοῦντο ἐπινοεῖν εἰς ἀφορμὴν φρουρᾶς πλείονος ἢ ἐς ἀλλοτρίωσιν τῶν κληρουχιῶν Καίσαρι.", "st": "3.39"}, {"sp": "N", "t": "ὡς δὲ τῷ Καίσαρι ὑπὸ τῶν κρύφα ἀπεσταλμένων ἀπηγγέλθη τὸν ἐν Βρεντεσίῳ στρατὸν καὶ τοὺς ἀπῳκισμένους ἐν ὀργῇ τὸν Ἀντώνιον ἔχειν, ἀμελοῦντα τοῦ Καίσαρος φόνου, καὶ σφᾶς ἐπικουρήσειν, ἂν δύνωνται, ὁ μὲν Ἀντώνιος ἐς τὸ Βρεντέσιον ἐξῄει διὰ τάδε. δείσας δὲ ὁ Καῖσαρ, μὴ μετὰ τῆς στρατιᾶς ἐπανελθὼν ἀφρούρητον αὑτὸν λάβοι, χρήματα φέρων εἰς Καμπανίαν ᾔει, πείσων τὰς πόλεις οἱ στρατεύεσθαι, τὰς ὑπὸ τοῦ πατρὸς ᾠκισμένας. καὶ ἔπεισε Καλατίαν πρώτην, ἐπὶ δ’ ἐκείνῃ Κασιλῖνον, δύο τάσδε Καπύης ἑκατέρωθεν· ἐπιδοὺς δ’ ἑκάστῳ δραχμὰς πεντακοσίας ἦγεν ἐς μυρίους ἄνδρας, οὔτε ὡπλισμένους ἐντελῶς οὔτε συντεταγμένους πω κατὰ ἴλας, ἀλλ’ ὡς ἐς μόνην τοῦ σώματος φυλακήν, ὑφ’ ἑνὶ σημείῳ. οἱ δὲ ἐν ἄστει τὸν Ἀντώνιον δεδιότες μετὰ στρατιᾶς ἐπανιόντα, ὡς ἐπύθοντο καὶ τὸν Καίσαρα μεθ’ ἑτέρας προσιέναι, οἱ μὲν διπλασίως ἐδεδοίκεσαν, οἱ δ’ ὡς χρησόμενοι κατ’ Ἀντωνίου Καίσαρι ἠσμένιζον· οἱ δὲ αὐτῶν τὰς ἐν τῷ Καπιτωλίῳ διαλλαγὰς ἑωρακότες ὑπόκρισιν ἐνόμιζον εἶναι τὰ γιγνόμενα καὶ ἀντίδοσιν Ἀντωνίῳ μὲν δυναστείας, Καίσαρι δὲ τῶν φονέων.", "st": "3.40"}, {"sp": "N", "t": "ὧδε δὲ αὐτῶν θορυβουμένων, Καννούτιος ὁ δήμαρχος, ἐχθρὸς ὢν Ἀντωνίῳ καὶ παρ’ αὐτὸ Καίσαρι φίλος, ὑπήντα τῷ Καίσαρι καὶ τὴν γνώμην ἐκμαθὼν ἀπήγγελλε τῷ δήμῳ, μετ’ ἔχθρας Ἀντωνίου σαφοῦς ἐπιέναι τον Καίσαρα καὶ χρῆναι δεδιότας Ἀντώνιον ἐπὶ τυραννίδι τόνδε προσεταιρίσασθαι, στρατὸν ἄλλον οὐκ ἔχοντας ἐν τῷ παρόντι. ταῦτα δ’ εἰπὼν ἐσῆγε τὸν Καίσαρα, αὐλισάμενον πρὸ τοῦ ἄστεος ἀπὸ σταδίων πεντεκαίδεκα ἐν τῷ τοῦ Ἄρεως ἱερῷ. ὡς δὲ εἰσῆλθον, ὁ μὲν εἰς τὸν νεὼν τῶν Διοσκούρων παρῆλθε, καὶ τὸν νεὼν περιέστησαν οἱ στρατευόμενοι ξιφίδια ἀφανῶς περιεζωσμένοι, Καννούτιος δὲ πρότερον ἐδημηγόρει κατὰ τοῦ Ἀντωνίου. ὁ δὲ Καῖσαρ καὶ τοῦ πατρὸς αὐτοὺς ὑπεμίμνησκε καὶ ὧν αὐτὸς ὑπὸ Ἀντωνίου πάθοι, δι’ ἃ καὶ τόνδε τὸν στρατὸν ἐς φυλακὴν εἴη συνειλεγμένος· ἔφη τε ἐς πάντα τῆς πατρίδος ὑπηρέτης καὶ κατήκοος ἔσεσθαι καὶ ἐς τὰ νὺν πρὸς Ἀντώνιον ἕτοιμος.", "st": "3.41"}, {"sp": "N", "t": "ὧδε δ’ εἰπόντος αὐτοῦ καὶ τὴν ἐκκλησίαν διαλύσαντος ἐπὶ τῷδε, ὁ στρατὸς ἡγούμενος ἐς τὸ ἐναντίον ἐπὶ διαλλαγαῖς Ἀντωνίου τε καὶ Καίσαρος ἀφῖχθαι ἢ ἐς μόνην γε φυλακὴν τοῦ Καίσαρος καὶ τῶν φονέων ἄμυναν, ἤχθοντο τῇ κατ’ Ἀντωνίου προαγορεύσει, στρατηγοῦ τε σφῶν γεγονότος καὶ ὄντος ὑπάτου· καὶ οἱ μὲν αὐτῶν ἐπανελθεῖν ᾔτουν εἰς τὰ οἰκεῖα ὡς ὁπλιούμενοι· οὐ γὰρ ἄλλων ἢ τῶν ἰδίων ὅπλων ἀνέξεσθαι· οἱ δὲ καὶ τὸ ἀληθὲς ὑπέφαινον. ὁ δὲ Καῖσαρ ἠπόρητο μὲν ἐς τὸ ἐναντίον ὧν προσεδόκησε μετενεχθείς, ἐλπίσας δ’ αὐτῶν πειθοῖ μᾶλλον ἢ βίᾳ περιέσεσθαι, συνεχώρει ταῖς προφάσεσι καὶ τοὺς μὲν ἐπὶ τὰ ὅπλα ἔπεμπε, τοὺς δὲ ἁπλῶς ἐς τὰ οἰκεῖα. πάντας δ’, ἐπικρύπτων τὴν ἀχθηδόνα, ἐπῄνει τῆς συνόδου καὶ ἐδωρεῖτο ἑτέραις δωρεαῖς καὶ δαψιλέστερον ἔτι ἀμείψεσθαι ἔλεγεν, αἰεὶ χρώμενος ἐς τὰ ἐπείγοντα ὡς πατρικοῖς φίλοις μᾶλλον ἢ στρατιώταις. χιλίους μὲν δὴ μόνους ἢ τρισχιλίους τάδε λέγων ἐπέκλασεν ἐκ μυρίων οἱ παραμεῖναι (διαφέρονται γὰρ περὶ τοῦ ἀριθμοῦ). οἱ δὲ λοιποὶ τότε μὲν ἐξῄεσαν, ἀνεμιμνήσκοντο δ’ αὐτίκα γεωργίας τε πόνων καὶ κερδῶν στρατείας καὶ λόγων τῶν Καίσαρος καὶ εὐπειθείας αὐτοῦ, πρὸς ἃ ἐβούλοντο, καὶ χαρίτων, ὧν τε εἰλήφεσαν καὶ ὧν ἤλπιζον ἔτι λήψεσθαι. οἷόν τε ὄχλος ἀνώμαλος μετενόουν καὶ τῆς προφάσεως ἐς εὐπρέπειαν ἐπιβαίνοντες ὡπλίζοντο καὶ πρὸς αὐτὸν ἐπανῄεσαν. ὁ δὲ ἤδη μετὰ χρημάτων ἄλλων τήν τε Ῥάβενναν καὶ τὰ ἀγχοῦ πάντα περιῄει, στρατεύων ἑτέρους ἐφ’ ἑτέροις· καὶ πάντας ἐς Ἀρρήτιον ἔπεμπεν.", "st": "3.42"}, {"sp": "N", "t": "Ἀντωνίῳ δ’ ἀφῖκτο μέσον ἐς τὸ Βρεντέσιον ἐκ πέντε τῶν ἐν Μακεδονίᾳ τελῶν τέσσαρα· ἐπιμεμφόμενοι δ’ αὐτὸν οὐκ ἐπεξελθόντα τῷ φόνῳ Καίσαρος, χωρὶς εὐφημίας ἐς τὸ βῆμα παρέπεμπον ὡς περὶ τοῦδε σφίσιν ἐκλογιούμενον πρώτου. ὁ δὲ αὐτοῖς χαλεπτόμενος τῆς σιωπῆς οὐ κατέσχεν, ἀλλ’ ὠνείδιζεν ἀχαριστίαν ἐκ Παρθυαίων ὑπὸ οὗ μετενεχθεῖσιν ἐς τὴν Ἰταλίαν καὶ οὐκ ἐπιμαρτυροῦσι τοιᾶσδε χάριτος· ἐμέμφετο δὲ καὶ ὅτι παρὰ μειρακίου προπετοῦς, ὧδε τὸν Καίσαρα καλῶν, ἄνδρας ἐπιπεμπομένους σφίσιν εἰς διαφθορὰν οὐκ αὐτοὶ προσάγουσιν αὑτῷ. ἀλλὰ τούσδε μὲν αὐτὸς εὑρήσειν, τὸν δὲ στρατὸν ἄξειν ἐπὶ τὴν ἐψηφισμένην οἱ χώραν εὐδαίμονα Κελτικήν, καὶ τοῖς παροῦσιν ἑκάστῳ δοθήσεσθαι δραχμὰς ἑκατόν. οἱ δὲ ἐγέλασαν τῆς σμικρολογίας καὶ χαλεπήναντος αὐτοῦ μᾶλλον ἐθορύβουν καὶ διεδίδρασκον. ὁ δὲ ἐξανέστη τοσοῦτον εἰπών· “μαθήσεσθε ἄρχεσθαι.” αἰτήσας δὲ παρὰ τῶν χιλιάρχων τοὺς στασιώδεις (ἀνάγραπτος γάρ ἐστιν ἐν τοῖς Ῥωμαίων στρατοῖς αἰεὶ καθ’ ἕνα ἄνδρα ὁ τρόπος) διεκλήρωσε τῷ στρατιωτικῷ νόμῳ καὶ οὐ τὸ δέκατον ἅπαν, ἀλλὰ μέρος ἔκτεινε τοῦ δεκάτου, νομίζων σφᾶς ὧδε καταπλήξειν δι’ ὀλίγου. οἱ δὲ οὐκ ἐς φόβον μᾶλλον ἢ ἐς ὀργὴν ἀπὸ τοῦδε καὶ μῖσος ἐτρέποντο.", "st": "3.43"}, {"sp": "N", "t": "ταῦτα δ’ ὁρῶντες οὓς ὁ Καῖσαρ ἐπὶ διαφθορᾷ τῶνδε προπεπόμφει, βιβλία πολλὰ τότε μάλιστα διερρίπτουν ἐς τὸ στρατόπεδον, ἀντὶ τῆς Ἀντωνίου μικρολογίας τε καὶ ὠμότητος ἐς τὴν Καίσαρος μνήμην τοῦ προτέρου καὶ βοήθειαν τοῦ νῦν καὶ χορηγίας δαψιλεῖς μετατίθεσθαι. οὓς ὁ Ἀντώνιος μηνύμασι τε μεγάλοις ἐζήτει, καὶ ἀπειλαῖς, εἴ τις ἐπικρύπτοι. οὐδένα δὲ συλλαβὼν ἐχαλέπηνεν ὡς τοῦ στρατοῦ σφᾶς ἐπικρύπτοντος. ἀπαγγελλομένων δὲ καὶ τῶν ἐν ταῖς ἀποικίαις τε καὶ ἐν Ῥώμῃ Καίσαρι πεπραγμένων ἐθορυβεῖτο. καὶ ἐπελθὼν αὖθις ἐπὶ τὸν στρατὸν ἔφη χαλεπῆναι μὲν τῶν γεγονότων ὑπὸ ἀνάγκης στρατιωτικῆς ὀλίγοις ἀντὶ πλεόνων ὧν ἐκόλαζεν ὁ νόμος, αὐτοὺς δὲ εἰδέναι σαφῶς οὔτε ὠμὸν οὔτε μικρολόγον Ἀντώνιον. “ἀλλ’ ὁ μὲν φθόνος οἰχέσθω, κεκορεσμένος,” ἔφη, “καὶ τοῖς ἁμαρτήμασι καὶ ταῖς κολάσεσι· τὰς δὲ ἑκατὸν δραχμὰς ὑμῖν οὐ δωρεάν (οὐ γὰρ τοῦτό γε τῆς Ἀντωνίου τύχης), ἀλλὰ τῆς πρώτης ἐς ὑμᾶς ἐντεύξεως προσαγορευτικὸν μᾶλλον ἢ δωρεὰν ἐκέλευσα δοθῆναι, καὶ χρὴ νόμῳ πατρίῳ τε καὶ στρατιωτικῷ καὶ ἐς τάδε καὶ ἐς πάντα εὐπειθεῖς ὑπάρχειν.” ὁ μὲν οὕτως εἶπεν, οὐδέν τι ἔτι προσθεὶς τῇ δωρεᾷ τοῦ μὴ δοκεῖν ὁ στρατηγὸς ἡσσῆσθαι τοῦ στρατοῦ. οἱ δὲ ἐλάμβανον, εἴτε μεταγνόντες εἴτε καὶ δεδιότες. ὁ δὲ αὐτῶν τοὺς μὲν ταξιάρχους, εἴτε μηνίων ἔτι τῆς στάσεως εἴθ’ ἑτέρως ὑπονοῶν, ἐνήλλασσε, τοὺς δὲ λοιποὺς καὶ τἆλλα ἐν ταῖς χρείαις ἐδεξιοῦτο καὶ προύπεμπεν ἀνὰ μέρος τὴν παραθαλάσσιον ὁδεύειν ἐπὶ Ἀριμίνου.", "st": "3.44"}, {"sp": "N", "t": "αὐτὸς δ’ ἐπιλεξάμενος ἐκ πάντων στρατηγίδα σπεῖραν ἀνδρῶν ἀρίστων τά τε σώματα καὶ τὸν τρόπον ὥδευεν ἐς Ῥώμην ὡς ἐκεῖθεν ἐπὶ τὸ Ἀρίμινον ὁρμήσων. ἐσῄει δὲ ἐς τὴν πόλιν σοβαρῶς, τὴν μὲν ἴλην πρὸ τοῦ ἄστεως στρατοπεδεύσας, τοὺς δ’ ἀμφ’ αὑτὸν ἔχων ὑπεζωσμένους καὶ τὴν οἰκίαν νυκτοφυλακοῦντας ἐνόπλους· συνθήματά τε αὐτοῖς ἐδίδοτο, καὶ αἱ φυλακαὶ παρὰ μέρος ἦσαν ὡς ἐν στρατοπέδῳ. συναγαγὼν δὲ τὴν βουλὴν ὡς μεμψόμενος Καίσαρι περὶ τῶν πεπραγμένων, ἐσιὼν ἤδη μανθάνει τῶν τεσσάρων τελῶν τὸ καλούμενον Ἄρειον κατὰ τὴν ὁδὸν ἐς Καίσαρα μετατεθεῖσθαι. καὶ αὐτῷ τὴν εἴσοδον ἐπισχόντι τε καὶ διαποροῦντι ἀγγέλλεται καὶ τὸ καλούμενον τέταρτον ὁμοίως τοῖς Ἀρείοις ἐς Καίσαρα μετατεθεῖσθαι. διαταραχθεὶς οὖν εἰσῆλθε μὲν ἐς τὸ βουλευτήριον, ὡς δ’ ἐφ’ ἕτερα αὐτοὺς συναγαγὼν μικρὰ διελέχθη καὶ εὐθὺς ἐπὶ τὰς πύλας ἐχώρει καὶ ἀπὸ τῶν πυλῶν ἐπὶ Ἄλβην πόλιν ὡς μεταπείσων τοὺς ἀποστάντας. βαλλόμενος δ’ ἀπὸ τοῦ τείχους ἀνέστρεφε καὶ τοῖς ἄλλοις τέλεσι προσέπεμπεν ἀνὰ πεντακοσίας δραχμὰς ἑκάστῳ, καὶ σὺν οἷς εἶχεν αὐτὸς ἐς Τίβυρον ἐξῄει, σκευὴν ἔχων τὴν συνήθη τοῖς ἐπὶ τοὺς πολέμους ἐξιοῦσι· καὶ γὰρ ἤδη σαφὴς ἦν ὁ πόλεμος, Δέκμου τὴν Κελτικὴν οὐ μεθιέντος.", "st": "3.45"}, {"sp": "N", "t": "δεῦρο δὲ ὄντι ἥ τε βουλὴ σχεδὸν ἅπασα καὶ τῶν ἱππέων τὸ πλεῖστον ἀφίκετο ἐπὶ τιμῇ καὶ ἀπὸ τοῦ δήμου τὸ ἀξιολογώτατον· οἱ καὶ καταλαβόντες αὐτὸν ὁρκοῦντα τοὺς παρόντας οἱ στρατιώτας καὶ τοὺς ἐκ τῶν πάλαι στρατευσαμένων συνδραμόντας (πολὺ γὰρ καὶ τοῦτο ἦν) συνώμνυον ἑκόντες οὐκ ἐκλείψειν τὴν ἐς Ἀντώνιον εὔνοιάν τε καὶ πίστιν, ὡς ἀπορῆσαι, τίνες ἦσαν, οἳ πρὸ ὀλίγου παρὰ τὴν Καίσαρος ἐκκλησίαν τὸν Ἀντώνιον ἐβλασφήμουν.", "st": "3.46"}, {"sp": "N", "t": "ὁ μὲν δὴ λαμπρῶς οὕτως ἐς τὸ Ἀρίμινον προεπέμπετο, ὅθεν ἐστὶν ἡ τῆς Κελτικῆς ἀρχή. καὶ ὁ στρατὸς ἦν αὐτῷ, χωρίς γε τῶν νεολέκτων, τρία τέλη τὰ ἐκ Μακεδονίας μετάπεμπτα (ἤδη γὰρ αὐτῷ καὶ τὸ λοιπὸν ἀφῖκτο), ἐξεστρατευμένων δὲ ἕν, οἳ καὶ γηρῶντες ὅμως ἐδόκουν νεοσυλλόγων ἀμείνους ἐς τὸ διπλάσιον εἶναι. οὕτω μὲν Ἀντωνίῳ τέσσαρα ἐγίγνετο τέλη γεγυμνασμένων ἀνδρῶν καὶ ὅσον ἐξ ἔθους αὐτοῖς ἐπίκουρον ἄλλο ἕπεται, καὶ ἡ τοῦ σώματος φρουρὰ καὶ τὰ νεόλεκτα. Λέπιδός τε ἔχων ἐν Ἰβηρίᾳ τέσσαρα τέλη καὶ Ἀσίνιος Πολλίων δύο καὶ Πλάγκος ἐν τῇ ἑτέρᾳ Κελτικῇ τρία ἐδόκουν αἱρήσεσθαι τὰ Ἀντωνίου.", "st": "3.46"}, {"sp": "N", "t": "Καίσαρι δὲ ἦν δύο ὁμοίως ἀξιολογώτατα, τὰ ἐς αὐτὸν ἀπὸ τοῦ Ἀντωνίου μεταστάντα, ἓν δὲ νεοσυλλόγων, δύο δὲ ἐκ τῶν πρότερον ἐστρατευμένων, οὐκ ἐντελῆ μὲν ταῦτα τοῖς ἀριθμοῖς οὐδὲ ταῖς ὁπλίσεσιν, ὑπὸ δὲ τῶν νεοσυλλόγων καὶ ταῦτα ἀναπληρούμενα. συναγαγὼν δ’ ἅπαντας ἐς Ἄλβην ἐπέστελλε τῇ βουλῇ. ἡ δὲ ἐφήδετο μὲν αὖθις Καίσαρι, ὡς ἀπορεῖν καὶ τότε, τίνες ἦσαν, οἳ προύπεμπον Ἀντώνιον· ἤχθοντο δὲ τοῖς τέλεσιν οὐκ ἐς τὴν βουλήν, ἀλλ’ ἐς τὸν Καίσαρα μετελθοῦσιν. ἐπαινέσαντες δ’ ὅμως αὐτούς τε καὶ τὸν Καίσαρα, ἔφασαν ὀλίγον ὕστερον ὅ τι χρὴ ποιεῖν αὐτοὺς ψηφιεῖσθαι, ὅταν αὐτοῖς αἱ νέαι ἀρχαὶ ἐς τὰ πράγματα παρέλθωσιν. ἦν δὲ σαφές, ὅτι χρήσονται μὲν αὐτοῖς κατὰ Ἀντωνίου· στρατὸν δὲ οὐδένα πω ἔχοντες ἴδιον οὐδὲ καταλέξαι χωρὶς ὑπάτων δυνάμενοι ἐς τὰς νέας ἀρχὰς πάντα ἀνετίθεντο.", "st": "3.47"}, {"sp": "N", "t": "τῷ Καίσαρι δ’ ὁ στρατὸς πελέκεάς τε καὶ ῥαβδοφόρους ἐσκευασμένους προσαγαγόντες, ἠξίουν ἑαυτὸν ἀντιστράτηγον ἀποφῆναι, πολέμου τε ἡγεμονεύοντα καὶ σφῶν αἰεὶ ὑπ’ ἄρχουσι ταχθέντων. ὁ δὲ τὴν μὲν τιμὴν ἐπῄνει, τὸ δὲ ἔργον ἐς τὴν βουλὴν ἀνετίθετο· καὶ βουλομένους ἐπὶ τοῦτο χωρεῖν ἀθρόους ἐκώλυε καὶ πρεσβευομένους ἐπεῖχεν, ὡς καὶ τῆς βουλῆς ψηφιουμένης ταῦτα καθ’ ἑαυτήν, καὶ μᾶλλον, ἢν αἴσθωνται τὴν ὑμετέραν προθυμίαν καὶ τὸν ἐμὸν ὄκνον.", "st": "3.48"}, {"sp": "N", "t": "διαλυθέντων δὲ μόλις οὕτω καὶ τῶν ἡγεμόνων ἐς ὑπεροψίαν αὐτὸν αἰτιωμένων, ἐξελογεῖτο αὐτοῖς τὴν βουλὴν οὐκ εὐνοίᾳ πρὸς αὑτὸν ἀποκλίνειν μᾶλλον ἢ Ἀντωνίου δέει καὶ στρατιᾶς ἀπορίᾳ, “μέχρι καθέλωμεν ἡμεῖς Ἀντώνιον καὶ οἱ σφαγεῖς φίλοι τε τῇ βουλῇ καὶ συγγενεῖς ὄντες δύναμιν αὐτοῖς συναγάγωσιν· ὧν αἰσθανόμενος ὑπηρετεῖν ὑποκρίνομαι. μὴ δὴ πρότεροι τὴν ὑπόκρισιν ἀποκαλύπτωμεν, ὡς προλαβοῦσι μὲν ἡμῖν τὴν ἀρχὴν ἐπικαλέσουσιν ὕβριν ἢ βίαν, αἰδεσθεῖσι δ’ ἴσως ἐπιδώσουσιν αὐτοὶ δέει, μὴ παρ’ ὑμῶν λάβοιμι.” τοιάδε εἰπὼν ἐθεᾶτο γυμνάσια τῶν δύο τελῶν τῶν αὐτομολησάντων ἀπ’ Ἀντωνίου, διαστάντων τε ἐς ἀλλήλους καὶ δρώντων ἀφειδῶς ἔργα πολέμου πάντα πλὴν ἐς μόνον θάνατον. ἡσθεὶς οὖν τῇ θέᾳ καὶ τῆς προφάσεως ἐπιβαίνων ἄσμενος, ἑτέρας αὐτῶν ἑκάστῳ πεντακοσίας δραχμὰς ἐπεδίδου καί, εἴ τις πολέμου χρεία γένοιτο, νικήσασιν ἐπηγγέλλετο πεντακισχιλίας. ὧδε μὲν ὁ Καῖσαρ δαψιλείᾳ δωρεῶν τοὺς μισθοφόρους ἐκρατύνετο.", "st": "3.48"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν ἀνὰ τὴν Ἰταλίαν, ἐν δὲ τῇ Κελτικῇ τὸν Δέκμον ὁ Ἀντώνιος ἐκέλευσεν ἐς Μακεδονίαν μετιέναι, πειθόμενόν τε τῷ δήμῳ καὶ φειδόμενον ἑαυτοῦ. ὁ δὲ ἀντέπεμπεν αὐτῷ τὰ παρὰ τῆς βουλῆς οἱ κεκομισμένα γράμματα, ὡς οὐχὶ διὰ τὸν δῆμον εἴκειν οἷ πρέπον ἢ διὰ τὴν βουλὴν Ἀντωνίῳ μᾶλλον. Ἀντωνίου δ’ αὐτῷ προθεσμίαν ὁρίζοντος, μεθ’ ἣν ὡς πολεμίῳ χρήσεται, μακροτέραν ὁ Δέκμος ἐκέλευεν ὁρίζειν ἑαυτῷ, μὴ θᾶσσον γένοιτο τῇ βουλῇ πολέμιος. καὶ ὁ Ἀντώνιος εὐμαρῶς ἂν αὐτοῦ κρατήσας ἔτι ὄντος ἐν πεδίῳ ἐπὶ τὰς πόλεις ἔκρινε προελθεῖν. αἱ δὲ αὐτὸν ἐδέχοντο. καὶ δείσας ὁ Δέκμος, μὴ οὐδ’ ἐσελθεῖν ἔς τινα αὐτῶν ἔτι δύνηται, πλάσσεται γράμματα τῆς βουλῆς καλούσης αὐτὸν ἐς Ῥώμην σὺν τῷ στρατῷ· καὶ ἀναζεύξας ἐχώρει τὴν ἐπὶ τῆς Ἰταλίας, ὑποδεχομένων αὐτὸν ὡς ἀπιόντα πάντων, μέχρι Μουτίνην παροδεύων, πόλιν εὐδαίμονα, τάς τε πύλας ἀπέκλειε καὶ τὰ τῶν Μουτιναίων ἐς τὰς τροφὰς συνέφερεν, ὑποζύγιά τε ὅσα ἦν κατέθυε καὶ ἐταρίχευε δέει, μὴ χρόνιος ἡ πολιορκία γένοιτο, καὶ τὸν Ἀντώνιον ὑπέμενε. στρατιὰ δ’ ἦν αὐτῷ μονομάχων τε πλῆθος καὶ ὁπλιτῶν τρία τέλη, ὧν ἓν μὲν ἦν ἀρτιστρατεύτων ἀνδρῶν ἔτι ἀπείρων, δύο δέ, ἃ καὶ πρότερον ὑπεστρατευμένα αὐτῷ πιστότατα ἦν. ὁ δ’ Ἀντώνιος ἐπελθὼν αὐτῷ σὺν ὀργῇ τὴν Μουτίνην ἀπετάφρευέ τε καὶ ἀπετείχιζε.", "st": "3.49"}, {"sp": "N", "t": "καὶ Δέκμος μὲν ἐπολιορκεῖτο, ἐν δὲ τῇ Ῥώμῃ κατὰ τὴν ἐτήσιον νουμηνίαν ὕπατοι γενόμενοι Ἵρτιός τε καὶ Πάνσας τὴν βουλὴν εὐθὺς ἐπὶ ταῖς θυσίαις ἐν αὐτῷ τῷ ἱερῷ συνῆγον ἐπὶ Ἀντωνίῳ. Κικέρων μὲν δὴ καὶ οἱ Κικέρωνος φίλοι πολέμιον αὐτὸν ἠξίουν ἤδη ψηφίσασθαι, τὴν Κελτικὴν ἀκούσης τῆς βουλῆς ἐς ἐπιτείχισμα τῆς πατρίδος βιαζόμενον ὅπλοις καὶ τὸν ἐπὶ Θρᾷκας αὐτῷ δεδομένον στρατὸν ἐς τὴν Ἰταλίαν διαγαγόντα· ἐπελέγοντο δὲ καὶ τὴν ἄλλην αὐτοῦ μετὰ Καίσαρα προαίρεσιν, ἔν τε τῇ πόλει φανερῶς δορυφορηθέντος ὑπὸ τοσῶνδε λοχαγῶν καὶ περὶ τὴν οἰκίαν ὥσπερ ἄκραν ὅπλοις καὶ συνθήμασι κεχρημένου καὶ τἆλλα σοβαρωτέρου σφίσι φανέντος ἢ κατὰ τὴν ἐτήσιον ἀρχήν. Λεύκιος δὲ Πείσων, ὁ τῷ Ἀντωνίῳ τὴν ἀποδημίαν ἐπιτροπεύων, ἀνὴρ ἐν τοῖς μάλιστα Ῥωμαίων ἐπιφανής, ὅσοι τε ἄλλοι τῷ Πείσωνι δι’ αὐτὸν ἢ δι’ Ἀντώνιον ἢ κατ’ οἰκείαν γνώμην προσετίθεντο, καλεῖν αὐτὸν ἐς κρίσιν ἠξίουν, ὡς οὐ πάτριον σφίσιν ἀκρίτου καταδικάζειν οὐδ’ εὐπρεπὲς τοῦ χθὲς ὑπάτου τῆς ἐπιούσης ἡμέρας, οὗ γε μάλιστα συνεχεῖς ἐπαίνους ἄλλοι τε καὶ Κικέρων αὐτὸς εἶπε πολλάκις. ἡ δὲ βουλὴ τότε μὲν ἀγχώμαλοι ταῖς γνώμαις ἐς νύκτα περιῆλθον, ἅμα δ’ ἕῳ περὶ τῶν αὐτῶν ἐς τὸ βουλευτήριον συνελέγοντο· ἔνθα τῶν Κικερωνείων ἐπιβαρούντων ἐψήφιστο ἂν ὁ Ἀντώνιος πολέμιος, εἰ μὴ τῶν δημάρχων Σάλουιος ἐς τὴν ἐπιοῦσαν ἐκέλευσεν ἀναθέσθαι. ἔστι δὲ ἐν τοῖς ἄρχουσιν ὁ κωλύων ἀεὶ δυνατώτερος.", "st": "3.50"}, {"sp": "N", "t": "οἱ μὲν δὴ Κικερώνειοι καὶ τούτῳ μάλα φορτικῶς ὠνείδιζόν τε καὶ ἐνύβριζον καὶ τὸν δῆμον ἐκδραμόντες ἠρέθιζον ἐπ’ αὐτὸν καὶ τὸν Σάλουιον ἐς αὐτὸν ἐκάλουν. ὁ δὲ ἀκαταπλήκτως ἐξέτρεχεν, ἕως ἡ βουλὴ κατέσχε δείσασα, μὴ μεταπείσειε τὸν δῆμον ἐς μνήμην ἀγαγὼν Ἀντωνίου. οὐ γὰρ ἠγνόουν καταγινώσκοντες ἀνδρὸς ἐπιφανοῦς πρὸ δίκης οὐδ’ ὅτι τὴν Κελτικὴν ὁ δῆμος αὐτῷ δεδώκει· ἀλλ’ ὑπὲρ τῶν σφαγέων δεδιότες ὠργίζοντο πρώτῳ μετὰ τὴν ἀμνηστίαν ἀνακινήσαντι τὰ κατ’ αὐτούς. διὸ καὶ τῷ Καίσαρι ἐς αὐτὸν προκατεχρῶντο· καὶ ὁ Καῖσαρ οὐκ ἀγνοῶν ᾑρεῖτο καὶ αὐτὸς ὅμως προκαθελεῖν τὸν Ἀντώνιον. τοιᾷδε μὲν ἡ βουλὴ γνώμῃ τὸν Ἀντώνιον εἶχεν ἐν ὀργῇ, ἀναθέμενοι δὲ τὴν ψῆφον, ὡς ὁ δήμαρχος ἐκέλευεν, ἐψηφίσαντο ὅμως Δέκμον τε ἐπαινέσαι οὐκ ἐκστάντα Ἀντωνίῳ τῆς Κελτικῆς, καὶ τοῖς ὑπάτοις Ἱρτίῳ καὶ Πάνσᾳ Καίσαρα συστρατηγεῖν οὗ νῦν ἔχει στρατοῦ, ἐπίχρυσόν τε αὐτοῦ εἰκόνα τεθῆναι καὶ γνώμην αὐτὸν ἐσφέρειν ἐν τοῖς ὑπατικοῖς ἤδη καὶ τὴν ὑπατείαν αὐτὴν μετιέναι τοῦ νόμου θᾶσσον ἔτεσι δέκα, ἔκ τε τοῦ δημοσίου δοθῆναι τοῖς τέλεσι τοῖς ἐς αὐτὸν ἀπὸ Ἀντωνίου μεταστᾶσιν, ὅσον αὐτοῖς ὁ Καῖσαρ ἐπὶ τῇ νίκῃ δώσειν ὑπέσχετο.", "st": "3.51"}, {"sp": "N", "t": "οἱ μὲν δὴ ταῦτα ψηφισάμενοι διελύθησαν, ὡς τὸν Ἀντώνιον ἔργῳ διὰ τῶνδε εἰδέναι πολέμιον ἐψηφισμένον καὶ τὸν δήμαρχον ἐς τὴν ἐπιοῦσαν οὐδὲν ἔτι ἀντεροῦντα· Ἀντωνίου δὲ ἡ μήτηρ καὶ ἡ γυνὴ καὶ παῖς ἔτι μειράκιον οἵ τε ἄλλοι οἰκεῖοι καὶ φίλοι δι’ ὅλης τῆς νυκτὸς ἐς τὰς τῶν δυνατῶν οἰκίας διέθεον ἱκετεύοντες καὶ μεθ’ ἡμέραν ἐς τὸ βουλευτήριον ἰόντας ἠνώχλουν, ῥιπτούμενοί τε πρὸ ποδῶν σὺν οἰμωγῇ καὶ ὀλολυγαῖς καὶ μελαίνῃ στολῇ παρὰ θύραις ἐκβοῶντες. οἱ δὲ ὑπό τε τῆς φωνῆς καὶ τῆς ὄψεως καὶ μεταβολῆς ἐς τοσοῦτον αἰφνιδίου γενομένης ἐκάμπτοντο. δείσας δ’ ὁ Κικέρων ἐβουληγόρησεν ὧδε.", "st": "3.51"}, {"sp": "N", "t": "“ἃ μὲν ἔδει γνῶναι περὶ Ἀντωνίου, ἐχθὲς ἔγνωμεν· οἷς γὰρ αὐτοῦ τοὺς ἐχθροὺς ἐτιμῶμεν, τούτοις ἐψηφιζόμεθα εἶναι πολέμιον. Σάλουιον δὲ τὸν μόνον ἐμποδὼν γινόμενον ἢ πάντων εἶναι χρὴ συνετώτερον ἢ φιλίᾳ τάδε πράσσειν ἢ τῶν ἐνεστώτων ἀμαθίᾳ. ὧν τὸ μὲν αἴσχιστόν ἐστιν ἡμῖν, εἰ δόξομεν ἀσυνετώτεροι πάντες ἑνὸς εἶναι, τὸ δὲ αὐτῷ Σαλουίῳ, εἰ φιλίαν τῶν κοινῶν προτιμῴη· ἀμαθῶς δ’ αὐτὸν ἔχοντα τῶν παρόντων ἔδει πιστεύειν ὑπάτοις ἀνθ’ ἑαυτοῦ καὶ στρατηγοῖς καὶ δημάρχοις τοῖς συνάρχουσιν αὐτῷ καὶ τοῖς ἄλλοις βουλευταῖς, οἳ τοσοίδε τὴν ἀξίωσίν τε καὶ τὸν ἀριθμὸν ὄντες διά τε ἡλικίαν καὶ ἐμπειρίαν ὑπὲρ τὸν Σάλουιον, καταγινώκομεν Ἀντωνίου. ἔστι δ’ ἔν τε χειροτονίαις καὶ δίκαις αἰεὶ τὸ πλέον δικαιότερον. εἰ δὲ καὶ νῦν ἔτι χρῄζει τὰς αἰτίας μαθεῖν, λελέξεται διὰ βραχέος, ὡς ἐν ἀναμνήσει, τὰ μέγιστα αὐτῶν.", "st": "3.52"}, {"sp": "N", "t": "“τὰ χρήματα ἡμῶν Καίσαρος ἀποθανόντος ἐσφετερίσατο Ἀντώνιος. Μακεδονίας ἄρχειν παρ’ ἡμῶν ἐπιτυχὼν ἐπὶ τὴν Κελτικὴν ὥρμησε χωρὶς ἡμῶν. τὸν στρατὸν ἐπὶ Θρᾷκας λαβὼν ἀντὶ Θρᾳκῶν ἐπήγαγεν ἡμῖν ἐς τὴν Ἰταλίαν. ἑκάτερα τούτων αἰτήσας ἡμᾶς ἐπ’ ἐνέδρᾳ καὶ οὐ λαβὼν ἔπραξε δι’ ἑαυτοῦ. σπεῖραν ἐν Βρεντεσίῳ βασιλικὴν συνέταξεν ἀμφ’ αὑτὸν εἶναι, καὶ φανερῶς αὐτὸν ἐν τῇ πόλει σιδηροφοροῦντες ἄνδρες ἐδορυφόρουν τε καὶ ἐνυκτοφυλάκουν ὑπὸ συνθήματι. ἦγεν ἐκ τοῦ Βρεντεσίου καὶ τὸν ἄλλον στρατὸν ἐς τὴν πόλιν ἅπαντα, συντομώτερον ἐφιέμενος ὧν ἐπενόει Καῖσαρ· Καίσαρος δὲ αὐτὸν τοῦ νέου σὺν ἑτέρῳ στρατῷ φθάσαντος ἔδεισε καὶ ἐς τὴν Κελτικὴν ἐτράπετο ὡς εὔκαιρον ἐφ’ ἡμῖν ὁρμητήριον, ὅτι καὶ ὁ Καῖσαρ ἐκεῖθεν ὁρμώμενος ἐδυνάστευσεν ἡμῶν.", "st": "3.52"}, {"sp": "N", "t": "“τὴν στρατιὰν ἐπὶ τοῖσδε καταπλησσόμενος, ἵνα πρὸς μηθὲν αὐτῷ παρανομοῦντι κατοκνῇ, διεκλήρωσεν ἐς θάνατον, οὐ στασιάσαντας ἢ φυλακὴν ἢ τάξιν ἐν πολέμῳ λιπόντας, ἐφ’ ὧν μόνων ὁ στρατιωτικὸς νόμος τὴν οὕτως ὠμὴν ὥρισε τιμωρίαν, καὶ ὅμως αὐτῇ καὶ ἐπὶ τοῖσδε ὀλίγοι μόλις ἐν τοῖς πάνυ κινδύνοις ἐχρήσαντο ὑπ’ ἀνάγκης· ὁ δὲ φωνῆς ἢ γέλωτος ἦγεν ἐς θάνατον τοὺς πολίτας καὶ θάνατον οὐ τῶν ἐλεγχθέντων, ἀλλὰ τῶν διαλαχόντων. τοιγαροῦν οἱ μὲν δυνηθέντες ἀπέστησαν αὐτοῦ, καὶ ὑμεῖς αὐτοῖς ὡς εὖ πράξασι δωρεὰς χθὲς ἐψηφίσασθε· οἱ δὲ οὐ δυνηθέντες ἀποδρᾶναι δεδιότες συναδικοῦσι καὶ χωροῦσιν ἐπὶ χώραν ὑμετέραν πολέμιοι καὶ πολιορκοῦσι στρατὸν ὑμέτερον καὶ στρατηγὸν ὑμέτερον, ᾧ γράφετε μὲν ὑμεῖς ἐμμένειν τῇ Κελτικῇ, Ἀντώνιος δ’ ἐξιέναι κελεύει. πότερον οὖν ἡμεῖς Ἀντώνιον ψηφιζόμεθα εἶναι πολέμιον, ἢ Ἀντώνιος ἡμᾶς ἤδη πολεμεῖ, καὶ ὁ δήμαρχος ἡμῶν ἔτι ἀγνοεῖ, μέχρι ἄρα Δέκμου πεσόντος ἥ τε χώρα τοσήδε οὖσα καὶ ὅμορος ἡμῖν καὶ ἐπὶ τῇ χώρᾳ ὁ Δέκμου στρατὸς ἐς τὰς καθ’ ἡμῶν ἐλπίδας Ἀντωνίῳ προσγένηται. τότε γὰρ αὐτόν, ὡς ἔοικεν, ὁ δήμαρχος ψηφιεῖται πολέμιον, ὅταν ἡμῶν γένηται δυνατώτερος.”", "st": "3.53"}, {"sp": "N", "t": "ταῦτ’ ἔτι τοῦ Κικέρωνος λέγοντος οἱ φίλοι θορυβοῦντες ἀπαύστως οὐδενὶ ἀντειπεῖν ἐπέτρεπον, μέχρι Πείσωνος αὐτοῦ παρελθόντος ἥ τε ἄλλη βουλὴ κατ’ αἰδῶ τοῦ ἀνδρὸς ἡσύχασε καὶ οἱ τοῦ Κικέρωνος ἠνέσχοντο. καὶ ἔλεγεν ὁ Πείσων·", "st": "3.54"}, {"sp": "N", "t": "“ὁ μὲν νόμος, ὦ βουλή, δικαιοῖ τὸν εὐθυνόμενον αὐτὸν ἀκοῦσαί τε τῆς κατηγορίας καὶ ἀπολογησάμενον ὑπὲρ αὑτοῦ κρίνεσθαι· καὶ τὸν δεινότατον εἰπεῖν Κικέρωνα ἐς ταῦτα προκαλοῦμαι. ἐπεὶ δὲ ὀκνεῖ μὲν παρόντος Ἀντωνίου κατηγορεῖν, ἀπόντος δ’ ἐγκλήματά τινα εἶπεν ὡς μέγιστα ἐκ πάντων καὶ ἀναμφίλογα ὄντα, παρῆλθον ἐγὼ δείξων αὐτὰ ψευδῆ βραχυτάταις ἀποκρισεσι. τὰ χρήματά φησιν Ἀντώνιον τὰ κοινὰ μετὰ τὴν Καίσαρος τελευτὴν σφετερίσασθαι, τοῦ μὲν νόμου τὸν κλέπτην οὐ πολέμιον ἀποφαίνοντος, ἀλλὰ ὡρισμένῃ δίκῃ ζημιοῦντος, Βρούτου δὲ τοῦ Καίσαρα κτείναντος ἐν τῷ δήμῳ καὶ τόδε κατηγορήσαντος, ὅτι ὁ Καῖσαρ τὰ χρήματα διεφόρησε καὶ κενὰ καταλέλοιπε τὰ ταμιεῖα, Ἀντωνίου δὲ μετ’ οὐ πολὺ ζητεῖν αὐτὰ ψηφισαμένου καὶ ὑμῶν ἀποδεξαμένων τε τὴν γνώμην καὶ κεκυρωκότων καὶ γέρας τοῖς μηνύουσι δεκάτην ὑπεσχημένων, ἣν διπλασιάσομεν ἡμεῖς, εἴ τις Ἀντώνιον περὶ αὐτῶν ἔχοι τι διελέγχειν.", "st": "3.54"}, {"sp": "N", "t": "“καὶ τάδε μὲν περὶ τῶν χρημάτων· τὴν δὲ Κελτικὴν ἡγεμονίαν οὐκ ἐψηφισάμεθα μὲν ἡμεῖς Ἀντωνίῳ, ἔδωκε δὲ ὁ δῆμος νόμῳ, παρόντος αὐτοῦ Κικέρωνος, ᾧ τρόπῳ καὶ ἕτερα πολλάκις ἔδωκε καὶ τήνδε τὴν ἡγεμονίαν αὐτὴν Καίσαρι πάλαι. μέρος δ’ ἐστὶ τοῦ νόμου τὸν Ἀντώνιον, τὴν δεδομένην οἱ μετιόντα, Δέκμῳ μὴ παραχωροῦντι πολεμεῖν καὶ τὸν στρατὸν ἀντὶ Θρᾳκῶν οὐδὲν ἔτι κινουμένων ἐς τὴν Κελτικὴν ἐπὶ τὸν ἀντιλέγοντα. ἀλλὰ Κικέρων Δέκμον μὲν οὐχ ἡγεῖται πολέμιον, ἐναντία τῷ νόμῳ τιθέμενον ὅπλα, Ἀντώνιον δὲ πολέμιον, τῷ νόμῳ συμμαχοῦντα. εἰ δὲ αὐτὸν αἰτιᾶται τὸν νόμον, τοὺς θεμένους αἰτιᾶται· οὓς ἔδει μεταπείθειν, οὐχὶ συνθέμενον ὑβρίζειν, οὐδὲ τὴν χώραν Δέκμῳ μὲν πιστεύειν, ὃν ὁ δῆμος ἐδίωξεν ἐπὶ τῷ φόνῳ, Ἀντωνίῳ δὲ ἀπιστεῖν, ὅ τι ὁ δῆμος ἔδωκεν. οὐ γὰρ εὖ βουλευομένων ἐστὶ διαστασιάζεσθαι πρὸς τὸν δῆμον ἐν καιροῖς μάλιστα ἐπικινδύνοις οὐδὲ ἀμνημονεῖν, ὅτι καὶ τόδε αὐτὸ τοῦ δήμου πρότερον ἦν, τὸ κρίνειν τὰ φίλια καὶ πολέμια. μόνος γὰρ ἐκ τῶν πάλαι νόμων ὁ δῆμος αὐτοκράτωρ εἰρήνης πέρι καὶ πολέμου σκοπεῖν. ὧν μηδὲν ὁ δῆμος ἐπιστήσειε μηδὲ ἐπιμηνίσειεν ἡμῖν, προστάτου λαβόμενος.", "st": "3.55"}, {"sp": "N", "t": "“ἀλλ’ ἔκτεινέ τινας τῶν στρατιωτῶν ὁ Ἀντώνιος. αὐτοκράτωρ γε ὢν καὶ ἐς τοῦτο ὑφ’ ὑμῶν κεχειροτονημένος. καὶ οὐδείς πω τῶνδε λόγον ὑπέσχεν αὐτοκράτωρ. οὐ γὰρ ἔκριναν οἱ νόμοι λυσιτελήσειν ἡμῖν τὸν ἄρχοντα τοῖς στρατευομένοις ὑπεύθυνον εἶναι· οὐδ’ ἔστιν ἀπειθείας τι χεῖρον ἐν στρατοπέδῳ, δι’ ἣν καὶ νικῶντές τινες ἀνῃρέθησαν, καὶ οὐδεὶς εὔθυνε τοὺς ἀνελόντας. οὐδὲ τῶν νῦν συγγενὴς οὐδείς, ἀλλὰ Κικέρων ἐπιμέμφεται καὶ φόνου κατηγορῶν πολέμιον κοινὸν ἀντὶ τῶν ὡρισμένων ἐπιτιμίων τοῖς φονεῦσι τίθεται. Ἀντωνίῳ δὲ τὸ στρατόπεδον ὅπως τε ἄτακτον ἦν καὶ ὅπως κατεφρόνει, δηλοῖ καὶ τὰ μεταστάντα αὐτοῦ δύο τέλη, ἃ ὑμεῖς μὲν ἐψηφίσασθε Ἀντωνίῳ στρατεύειν, αὐτομολήσαντα δὲ παρὰ τοὺς στρατιωτικοὺς νόμους, οὐ πρὸς ὑμᾶς, ἀλλ’ ἐς Καίσαρα, ὁ Κικέρων ὅμως ἐπῄνεσε καὶ ἐκ τῶν κοινῶν ἐχθὲς ἐμισθοδότησε· καὶ μή ποτε ὑμᾶς λυπήσειε τὸ παράδειγμα. Κικέρωνα δὲ καὶ ἐς ἀνωμαλίαν ἐξέστησεν ἡ ἔχθρα· κατηγορεῖ γὰρ Ἀντωνίου τυραννίδα καὶ κόλασιν στρατιωτῶν, ἀεὶ τῶν ἐπιβουλευόντων τὰ στρατεύματα θεραπευόντων, οὐ κολαζόντων. ἐπεὶ δὲ οὐκ ὤκνησεν οὐδε τὴν ἄλλην Ἀντωνίου μετὰ Καίσαρα ἀρχὴν ὡς τυραννικὴν διαβαλεῖν, φέρε πύθωμαι καθ’ ἕκαστον ὧδε.", "st": "3.56"}, {"sp": "N", "t": "“τίνα ἔκτεινεν ὡς τύραννος ἄκριτον ὁ νῦν κινδυνεύων ἀκρίτως; τίνα δ’ ἐξέβαλε τῆς πόλεως; τίνα δὲ ὑμῖν διέβαλεν; ἢ καθ’ ἕνα μὲν τοιόσδε ἦν, ἐπεβούλευε δὲ πᾶσιν ὁμοῦ; πότε, ὦ Κικέρων; ὅτε τὴν ἀμνηστίαν ἐκύρου τῶν γεγονότων; ἢ ὅτε μηδένα διώκεσθαι φόνου; ἢ ὅτε ζήτησιν εἶναι τῶν κοινῶν χρημάτων; ἢ ὅτε Πομπήιον τὸν Πομπηίου τοῦ ὑμετέρου κατεκάλει καὶ τὴν πατρῴαν ἐκ τῶν δημοσίων αὐτῷ διέλυε περιουσίαν; ἢ ὅτε τὸν Ψευδομάριον λαβὼν ἐπιβουλεύοντα ἀπέκτεινε καὶ ἐπῃνέσατε πάντες καὶ τοῦτο μόνον δι’ ὑμᾶς οὐ διέβαλε Κικέρων; ἢ ὅτε ἐψηφίζετο μὴ εἰσηγεῖσθαι περὶ δικτάτορος μηδένα μήτε ἐπιψηφίζειν, ἢ νηποινεὶ πρὸς τοῦ θέλοντος ἀποθνῄσκειν; ταῦτα γάρ ἐστιν, ἃ ἐπολιτεύσατο ἡμῖν Ἀντώνιος ἐν δύο μησίν, οἷς μόνοις ἐπέμεινε τῇ πόλει μετὰ Καίσαρα, ἄρτι μὲν τοῦ δήμου τοὺς φονέας διώκοντος, ἄρτι δὲ ὑμῶν δεδιότων ἐπὶ τοῖς ἐσομένοις· οὗ τίνα καιρόν, εἰ πονηρὸς ἦν, ἀμείνονα εἶχεν;", "st": "3.57"}, {"sp": "N", "t": "“ἀλλ’ ἐς τὰ ἐναντία· οὐκ ἦρχε. πῶς; οὐ μόνος ἦρχεν ἀποδημήσαντος ἐπὶ Συρίας Δολοβέλλα; οὐ στρατὸν εἶχεν ἕτοιμον ἐν τῇ πόλει τὸν ὑφ’ ἡμῶν αὐτῷ δεδομένον; οὐκ ἐνυκτοφυλάκει τὴν πόλιν; οὐκ ἐνυκτοφυλακεῖτο διὰ τὴν τῶν ἐχθρῶν ἐπιβουλήν; οὐ πρόφασιν εἶχε τὴν σφαγὴν Καίσαρος, φίλου τέ οἱ καὶ εὐεργέτου ὄντος καὶ τῷ δήμῳ μάλιστα ὑπεραρέσκοντος; οὐχ ἑτέραν εἶχεν οἰκείαν, ἐπιβεβουλευμένος ἐς τὸ σῶμα ὑπὸ τῶν ἀνδρῶν; ὧν ἔκτεινε μὲν ἢ ἐφυγάδευσεν οὐδένα, συνέγνω δέ, ὅσον εἶχε μέτρου καλῶς, καὶ διδομένας αὐτοῖς ἡγεμονίας οὐκ ἐφθόνησε δοθῆναι.", "st": "3.57"}, {"sp": "N", "t": "“τὰ μὲν δὴ μέγιστα, ὦ Ῥωμαῖοι, καὶ ἀναμφίλογα Κικέρωνος ἐς τὸν Ἀντώνιον ἐγκλήματα ὁρᾶτε· ἐπεὶ δέ γε ἐπὶ τοῖς ἐγκλήμασι καὶ μαντεύματα ἐπάγουσιν, ὡς ὁ Ἀντώνιος ἔμελλε μὲν τὸν στρατὸν ἄξειν ἐπὶ τὴν πόλιν, δείσειε δὲ προλαβόντος αὐτὴν ἑτέρῳ στρατῷ Καίσαρος, πῶς οὖν, εἰ τὸ μελλῆσαι μόνον ἐστὶν ἀνδρὸς πολεμίου, τὸν ἐλθόντα καὶ παραστρατοπεδεύσαντα ἡμῖν ἀσήμαντον οὐχ ἡγεῖται πολέμιον; πῶς δ’, εἴπερ ἤθελεν ὁ Ἀντώνιος, οὐκ ἀφίκετο; ἢ τρισμυρίους ἔχων συντεταγμένους ἔδεισε τρισχιλίους τοὺς ἀμφὶ τὸν Καίσαρα ὄντας ἀνόπλους, ἀσυντάκτους, ἐς μόνας Καίσαρι διαλλαγὰς συνελθόντας καὶ εὐθύς, ὡς ἔγνωσαν πολεμεῖν αἱρούμενον, καταλιπόντας; εἰ δὲ μετὰ τρισμυρίων ἐλθεῖν ἔδεισε, πῶς ἦλθε μετὰ μόνων χιλίων; μεθ’ ὧν αὐτὸν ἐς τὸ Τίβυρον ἐξιόντα πόσοι προεπέμπομεν καὶ πόσοι συνώμνυμεν οὐχ ὁρκούμενοι; πόσους δὲ Κικέρων ἐπαίνους ἐς τὴν πολιτείαν αὐτοῦ καὶ ἀρετὴν ἀνάλισκε; πῶς δ’ αὐτὸς Ἀντώνιος, εἴ τι τοιοῦτον ἐγίγνωσκε, τὰ ἐνέχυρα τὰ νῦν ὄντα πρὸ τοῦ βουλευτηρίου κατέλιπεν ἡμῖν; μητέρα καὶ γυναῖκα καὶ μειράκιον υἱόν; οἳ κλαίουσι καὶ δεδίασι νῦν οὐ τὴν Ἀντωνίου πολιτείαν, ἀλλὰ τὴν τῶν ἐχθρῶν δυναστείαν.", "st": "3.58"}, {"sp": "N", "t": "“ταῦτα μὲν δὴ πρὸς ὑμᾶς ἐξενήνοχα δεῖγμα τῆς Ἀντωνίου τε ἀπολογίας καὶ Κικέρωνος μεταβολῆς· παραίνεσιν δ’ ἐπιθήσω τοῖς εὖ φρονοῦσι μήτε ἐς τὸν δῆμον μήτε ἐς Ἀντώνιον ἁμαρτάνειν μηδὲ ἔχθρας καὶ κινδύνους ἐπάγειν τοῖς κοινοῖς, νοσούσης ἔτι τῆς πολιτείας καὶ ἀπορούσης τῶν ὀξέως ἀμυνούντων, δύναμιν δ’ ἐν τῇ πόλει συστησαμένους, πρὶν θορυβῆσαί τι τῶν ἔξω, τὴν ἀρκέσουσαν, τότε τοῖς ἑκάστοτε ἐπείγουσιν ἐφεδρεύειν καὶ κρίνειν, οὓς ἂν ἐθέλητε, δυναμένους τὸ κεκριμένον τελεῖν. πῶς οὖν ἔσται ταῦτα; ἐὰν Ἀντώνιον μὲν ἐῶμεν ἐς πρόφασιν ἢ χάριν τοῦ δήμου τὴν Κελτικὴν ἔχειν, Δέκμον δὲ μετὰ τριῶν ὧν ἔχει τελῶν ἐνθάδε καλῶμεν καὶ ἀφικόμενον ἐκπέμπωμεν ἐς Μακεδονίαν, τὰ τέλη κατασχόντες. εἰ δὲ καὶ τὰ ἀπ’ Ἀντωνίου μεταστάντα δύο πρὸς ἡμᾶς μετέστη, καθάπερ φησὶ Κικέρων, καὶ τάδε καλῶμεν ἀπὸ τοῦ Καίσαρος ἐς τὴν πόλιν. οὕτω γὰρ πέντε τελῶν ἡμῖν ὑπαρχόντων ψηφιζοίμεθα ἄν, ὅ τι δοκιμάζοιμεν, ἐγκρατῶς, ἐς οὐδενὸς ἀνδρὸς ἐλπίδας αἰωρούμενοι.", "st": "3.59"}, {"sp": "N", "t": "“καὶ τάδε μὲν εἴρηται τοῖς ἄνευ φθόνου καὶ φιλονικίας ἀκροωμένοις· τοῖς δὲ ἀπερισκέπτως καὶ ἀπαρασκεύως δι’ οἰκείαν ἔχθραν ἢ φιλονικίαν ἐκθορυβοῦσιν ὑμᾶς κριτὰς παραινῶ μὴ ταχεῖς εἶναι μηδὲ προπετεῖς ἐς ἄνδρας μεγίστους τε καὶ στρατιᾶς ἄρχοντας ἱκανῆς μηδὲ ἄκοντας ἐκπολεμοῦν, ἀναμιμνησκομένους Μαρκίου τε τοῦ Κοριολανοῦ καὶ τὰ ἔναγχος δὴ ταῦτα Καίσαρος, ὃν στρατιᾶς ὁμοίως ἡγούμενον καὶ σπονδὰς ἀρίστας ἂν ἡμῖν γενομένας προτείνοντα προπετῶς πολέμιον ψηφισάμενοι τῷ ὄντι πολέμιον ἠναγκάσαμεν γενέσθαι, φείδεσθαι δὲ καὶ τοῦ δήμου πρὸ βραχέος τοῖς φονεῦσι τοῖς Καίσαρος ἐπιδραμόντος, μὴ ἐς ὕβριν αὐτοῦ δοκῶμεν τοῖς μὲν ἡγεμονίας ἐθνῶν διδόναι, Δέκμον δὲ ἐπαινεῖν, ὅτι τοῦ δήμου νόμον ἀκυροῖ, καὶ Ἀντώνιον πολέμιον κρίνειν, ὅτι τὴν Κελτικὴν ἔλαβε παρὰ τοῦ δήμου. ὧν τοὺς μὲν εὖ βουλευομένους ἐνθυμεῖσθαι χρὴ ὑπὲρ τῶν ἔτι πλανωμένων, τοὺς δ’ ὑπάτους καὶ δημάρχους πλείονας κινδυνεύουσι τοῖς κοινοῖς γενέσθαι.”", "st": "3.60"}, {"sp": "N", "t": "ὧδε μὲν ὁ Πείσων ἀπελογεῖτο καὶ ὠνείδιζεν ὁμοῦ καὶ ἐφόβει καὶ σαφῶς αἴτιος ἐγένετο μὴ ψηφισθῆναι πολέμιον Ἀντώνιον. οὐ μὴν ἐκράτησε τῆς Κελτικῆς αὐτὸν ἄρχειν· οἱ γὰρ τῶν σφαγέων φίλοι τε καὶ συγγενεῖς ὑπὸ δέους ἐκώλυσαν, μὴ τοῦ πολέμου λυθέντος ἐπεξέλθοι τὸν φόνον Καίσαρι συναλλαγείς· διὸ καὶ στασιάζειν αἰεὶ παρεσκεύαζον Καίσαρά τε καὶ Ἀντώνιον. ἐψηφίσαντο δ’ Ἀντωνίῳ προαγορεῦσαι Μακεδονίαν ἀντὶ τῆς Κελτικῆς ἔχειν· τὰς δὲ ἄλλας ἐντολάς, εἴτε λαθόντες εἴτ’ ἐξεπίτηδες, Κικέρωνα συγγράψαι τε καὶ δοῦναι τοῖς πρεσβεύουσι προσέταξαν. ὁ δὲ τὴν γνώμην παραφέρων συνέγραφεν ὧδε· Μουτίνης Ἀντώνιον εὐθὺς ἀπανίστασθαι καὶ Δέκμῳ τὴν Κελτικὴν μεθιέναι, ἐντὸς δὲ Ῥουβίκωνος ποταμοῦ, τοῦ τὴν Ἰταλίαν ὁρίζοντος ἀπὸ τῆς Κελτικῆς, ἡμέρᾳ ῥητῇ γενόμενον ἐπιτρέψαι τὰ καθ’ ἑαυτὸν ἅπαντα τῇ βουλῇ. οὕτω μὲν φιλονίκως τε καὶ ψευδῶς τὰς ἐντολὰς ὁ Κικέρων συνέγραφεν, οὐδεμιᾶς ἔχθρας τοσῆσδε ὑπούσης, ἀλλ’, ὡς ἔοικε, τοῦ δαιμονίου τὰ κοινὰ ἐς μεταβολὴν ἐνοχλοῦντος καὶ αὐτῷ Κικέρωνι κακῶς ἐπινοοῦντος. ἄρτι δὲ καὶ τῶν Τρεβωνίου λειψάνων κομισθέντων καὶ τῆς ἐς αὐτὸν ὕβρεως γνωσθείσης ἀκριβέστερον, οὐ δυσχερῶς ἡ βουλὴ τὸν Δολοβέλλαν ἔκρινεν εἶναι πολέμιον.", "st": "3.61"}, {"sp": "N", "t": "οἱ δ’ ἐς τὸν Ἀντώνιον ἀπεσταλμένοι πρέσβεις, αἰδούμενοι τῶν ἐντολῶν τὸ ἀλλόκοτον, οὐδὲν μὲν ἔφασαν, αὐτὰς δ’ ἐπέδοσαν αὐτῷ. καὶ ὁ Ἀντώνιος σὺν ὀργῇ πολλὰ ἔς τε τὴν βουλὴν καὶ τὸν Κικέρωνα ἀπερρίπτει, θαυμάζων, ὅτι Καίσαρα μὲν τὸν τὰ μέγιστα ὠφελήσαντα τὴν ἀρχὴν ἡγοῦνται τύραννον ἢ βασιλέα, Κικέρωνα δὲ οὐ νομίζουσιν, ὃν Καῖσαρ μὲν εἷλε πολέμῳ καὶ οὐκ ἀπέκτεινε, Κικέρων δὲ τοὺς ἐκείνου φονέας προτίθησι τῶν φίλων αὐτοῦ καὶ Δέκμον Καίσαρι μὲν ὄντα φίλον ἐμίσει, ἀνδροφόνον δὲ αὐτοῦ γενόμενον ἀγαπᾷ, καὶ τῷ μὲν παρ’ οὐδενὸς μετὰ Καίσαρα λαβόντι τὴν Κελτικὴν προστίθεται, τῷ δὲ παρὰ τοῦ δήμου λαβόντι πολεμεῖ. “τῶν τε ἐψηφισμένων μοι τελῶν τοῖς μὲν αὐτομολήσασι γέρα δίδωσι, τοῖς δὲ παραμείνασιν οὔ, διαφθείρων οὐκ ἐμοὶ μᾶλλον ἀλλὰ τῇ πόλει τὰ στρατιωτικά. καὶ τοῖς μὲν ἀνδροφόνοις ἀμνηστίαν ἔδωκεν, ᾗ κἀγὼ συνεθέμην διὰ δύο ἄνδρας αἰδεσίμους· Ἀντώνιον δὲ καὶ Δολοβέλλαν ἡγεῖται πολεμίους, ὅτι τῶν δεδομένων ἐχόμεθα. ἥδε γάρ ἐστιν ἡ ἀληθὴς αἰτία· κἂν ἀποστῶ τῆς Κελτικῆς, οὔτε πολέμιος οὔτε μόναρχός εἰμι. ταῦτα μέντοι μαρτύρομαι λύσειν τὴν οὐκ ἀγαπωμένην ἀμνηστίαν.”", "st": "3.62"}, {"sp": "N", "t": "τοιάδε πολλὰ εἰπὼν ὁ Ἀντώνιος ἀντέγραφε τῷ δόγματι τῇ μὲν βουλῇ πεισθῆναι ἂν ἐς ἅπαντα ὡς πατρίδι, Κικέρωνι δὲ τῷ συγγράψαντι τὰς ἐντολὰς ὧδε ἀποκρίνεσθαι· “ὁ δῆμος ἔδωκέ μοι τὴν Κελτικὴν νόμῳ, καὶ Δέκμον ἀπειθοῦντα τῷ νόμῳ μετελεύσομαι καὶ τοῦ φόνου δίκας ἀπαιτήσω μόνον ὑπὲρ ἁπάντων, ἵνα καὶ ἡ βουλὴ καθαρεύσῃ ποτὲ τοῦ μύσους, ἐμπιπλαμένη νῦν διὰ Κικέρωνα Δέκμῳ βοηθοῦντα.” τάδε μὲν ὁ Ἀντώνιος εἶπέ τε καὶ ἀντέγραψε, καὶ ἡ βουλὴ αὐτὸν αὐτίκα ἐψηφίζετο εἶναι πολέμιον καὶ τὸν ὑπ’ αὐτῷ στρατόν, εἰ μὴ ἀποσταῖεν αὐτοῦ· Μακεδονίας δὲ καὶ τῆς Ἰλλυρίδος αὐτῆς καὶ τῶν ἐν ἀμφοτέραις ὑπολοίπων στρατῶν Μᾶρκον Βροῦτον ἄρχειν, μέχρι κατασταίη τὰ κοινά. ὁ δὲ ἴδιόν τε εἶχεν ἤδη στρατὸν καὶ παρὰ Ἀπουληίου τινὰ προσειλήφει καὶ ναῦς εἶχε μακράς τε καὶ ὁλκάδας καὶ χρημάτων ἐς μύρια καὶ ἑξακισχίλια τάλαντα καὶ ὅπλα πολλά, ὅσα ἐν Δημητριάδι Γαΐῳ Καίσαρι ἐκ πολλοῦ γιγνόμενα εὗρεν· οἷς ἅπασιν αὐτὸν ἡ βουλὴ τότε ἐψηφίζετο ἐς τὰ συμφέροντα τῆς πατρίδος χρῆσθαι. ἐψηφίσαντο δὲ καὶ Κάσσιον ἄρχειν τε Συρίας καὶ πολεμεῖν Δολοβέλλᾳ· τούς τε ἄλλους, ὅσοι τινὸς ἔθνους ἢ στρατοῦ Ῥωμαίων ἄρχουσιν ἀπὸ τῆς Ἰονίου θαλάσσης ἐπὶ τὴν ἕω, πάντας ὑπακούειν ἐς ὅ τι προστάσσοι Κάσσιος ἢ Βροῦτος.", "st": "3.63"}, {"sp": "N", "t": "ὧδε μὲν ὀξέως σὺν ἀφορμῇ τοὺς ἀμφὶ τὸν Κάσσιον ἐξελάμπρυνον, καὶ ὁ Καῖσαρ ἕκαστα μαθὼν ἠπόρητο, τὴν μὲν ἀμνηστίαν ἡγούμενος εὐπρέπειαν ἐσχηκέναι φιλανθρωπίας καὶ ἔλεον συγγενῶν ἀνδρῶν καὶ ὁμοτίμων, καὶ τὰς βραχυτέρας ἡγεμονίας ἀσφάλειαν· Δέκμῳ τε τὴν Κελτικὴν βεβαιοῦντας Ἀντωνίῳ δόξαι περὶ τυραννίδος διαφέρεσθαι, ᾧ προσποιήματι καὶ αὑτὸν ὑπάγεσθαι κατ’ Ἀντωνίου· τὸ δὲ καὶ Δολοβέλλαν πολέμιον ψηφίσασθαι δι’ ἕνα τῶν ἀνδροφόνων ἀναιρεθέντα καὶ Βρούτῳ καὶ Κασσίῳ τὰς ἡγεμονίας ἐς τὰ μέγιστα ἔθνη διαλλάξαι στρατόπεδά τε δοῦναι πολλὰ ἀθρόως καὶ χρήματα καὶ ἡγεμόνας ἡγεμονῶν ἀποφῆναι πάντων, ὅσοι πέραν εἰσὶ τῆς Ἰονίου θαλάσσης, σαφῶς εἶναι τὴν μὲν Πομπηίου μοῖραν αὐξόντων, τὴν δὲ Καίσαρος καθαιρούντων. ἐνεθυμεῖτο δὲ καὶ τῆς ἐς αὑτὸν ὡς μειράκιον τέχνης, εἰκόνα μὲν αὑτῷ καὶ προεδρίαν παρασχόντων καὶ ἀντιστράτηγον ἀποφηνάντων, ἔργῳ δὲ ἴδιον αὑτοῦ τὸν στρατὸν ὄντα ἀφαιρουμένων· ὑπάτων γὰρ συστρατηγούντων οὐδὲν εἶναι τὸν ἀντιστράτηγον· τά τε γέρα τοῖς ἀπὸ Ἀντωνίου μόνοις μεταστᾶσιν ἐψηφισμένα τοὺς αὑτῷ στρατευομένους ἀτιμοῦν· καὶ τὸν πόλεμον ὅλως αὑτῷ μὲν αἰσχύνην ἔχειν, ἔργῳ δὲ τὴν βουλὴν ἀποχρῆσθαί οἱ κατὰ Ἀντωνίου, μέχρι καθέλωσιν αὐτόν.", "st": "3.64"}, {"sp": "N", "t": "ταῦτα λογιζόμενος ἐπέκρυπτε καὶ θύων ἐπὶ τῇ δεδομένῃ ἀρχῇ πρὸς τὸν στρατὸν ἔφη·", "st": "3.65"}, {"sp": "N", "t": "“καὶ τάδε μοι παρ’ ὑμῶν, ὦ συστρατιῶται, γέγονεν, οὐ νῦν, ἀλλ’ ἐξ οὗ τὴν ἀρχὴν ἐδίδοτε· καὶ γὰρ ἡ βουλὴ δι’ ὑμᾶς ἔδωκεν. ὥστε ἐμὲ καὶ τούτων ἴστε τὴν χάριν ὑμῖν ὀφλήσοντα καί, ἢν οἱ θεοὶ παρέχωσιν εὐπραγεῖν, ἀποδώσοντα ἀθρόως.”", "st": "3.65"}, {"sp": "N", "t": "ὁ μέν οὑτωσὶ τὸν στρατὸν οἰκειούμενος ὑπήγετο, τῶν δὲ ὑπάτων Πάνσας μὲν ἀνὰ τὴν Ἰταλίαν ἐξενάγει, Ἵρτιος δὲ τῷ Καίσαρι τὸν στρατὸν ἐμερίζετο καί, ὡς αὐτῷ παρὰ τῆς βουλῆς ἐν ἀπορρήτῳ λέλεκτο, ἐς τὸ μέρος ᾔτει τὰ δύο τέλη τὰ παρὰ Ἀντωνίου μεταστάντα, εἰδὼς τάδε ὄντα τοῦ στρατοῦ τὸ ἀξιολογώτατον. καὶ ὁ μὲν Καῖσαρ ἅπαντα συνεχώρει, μερισάμενοι δὲ ἐχείμαζον μετ’ ἀλλήλων· παροδεύοντος δὲ τοῦ χειμῶνος ἤδη Δέκμος μὲν ἔκαμνεν ὑπὸ λιμοῦ, Ἵρτιος δὲ καὶ Καῖσαρ ἐς τὴν Μουτίνην ἐχώρουν, μὴ κάμνοντα τὸν Δέκμου στρατὸν ὁ Ἀντώνιος παραλάβοι. ἀκριβῶς δὲ τῆς Μουτίνης φυλασσομένης ὑπὸ τοῦ Ἀντωνίου, πανσυδὶ μὲν οὐ συνεπλέκοντο αὐτῷ Πάνσαν περιμένοντες, ἱππομαχίαι δ’ ἦσαν πυκναί, πολὺ μὲν πλείους ἱππέας ἔχοντος Ἀντωνίου· τοῦ πεδίου δὲ ἡ δυσχέρεια, διὰ χειμάρρους ἐκτεταφρευμένου, τὴν πλεονεξίαν τὸ πλῆθος ἀπεστέρει.", "st": "3.65"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν ἀμφὶ τῇ Μουτίνῃ, τὰ δ’ ἐν Ῥώμῃ τῶν ὑπάτων οὐ παρόντων ὁ Κικέρων ἦγεν ὑπὸ δημοκοπίας· καὶ συνεχεῖς ἦσαν ἐκκλησίαι, ὅπλα τε εἰργάζετο συναγαγὼν τοὺς δημιουργοὺς ἀμισθὶ καὶ χρήματα συνέλεγε καὶ βαρυτάτας ἐσφορὰς τοῖς Ἀντωνίου φίλοις ἐπετίθει. οἱ δὲ ἑτοίμως ἐσέφερον ἐκλυόμενοι τὴν διαβολήν, μέχρι Πούπλιος Οὐεντίδιος, ἐστρατευμένος τε Γαΐῳ Καίσαρι καὶ Ἀντωνίῳ φίλος ὤν, οὐκ ἤνεγκε τὴν βαρύτητα τοῦ Κικέρωνος, ἀλλ’ ἐς τὰς Καίσαρος ἀποικίας ἐκδραμὼν ὡς γνώριμος δύο ἐς τὸν Ἀντώνιον ἀνεστράτευσε τέλη καὶ ἐς τὴν Ῥώμην συλλαβεῖν Κικέρωνα ἠπείγετο. τότε μὲν δὴ θόρυβός τε ἦν ἄπλετος, καὶ τέκνα καὶ γυναῖκας ὑπεξέφερον οἱ πλείους μετὰ δυσελπιστίας, καὶ ὁ Κικέρων τῆς πόλεως ἀπεδίδρασκε. καὶ ὁ Οὐεντίδιος μαθων ἐς τὸν Ἀντώνιον ἀνέστρεφε. διακλειόμενος δὲ ὑπὸ Καίσαρός τε καὶ Ἱρτίου ἐς τὴν Πικηνίτιδα παρῆλθε καὶ τέλος ἄλλο συλλογίσας ἐφήδρευε τοῖς ἐσομένοις.", "st": "3.66"}, {"sp": "N", "t": "οἱ δὲ ἀμφὶ τὸν Καίσαρα, τοῦ Πάνσα μετὰ στρατιᾶς πλησιάζοντος, Καρσουλήιον αὐτῷ προσέπεμπον ἄγοντα τὴν Καίσαρος στρατηγίδα τάξιν καὶ τὸ Ἄρειον τέλος ἐς βοήθειαν τῆς διόδου τῶν στενῶν. ὁ δὲ Ἀντώνιος τῶν μὲν στενῶν ὑπερεῖδεν ὡς οὐδὲν πλέον ἢ κωλύσων ἐν αὐτοῖς, ἐπιθυμίᾳ δὲ ἀγῶνος, οὐκ ἔχων τοῖς ἱππεῦσιν ἐλλαμπρύνασθαι διὰ τὸ πεδίον ἑλωδέστερον ὂν καὶ τεταφρευμένον, δύο ἐνήδρευσε τέλη τὰ ἄριστα ἐν τῷ ἕλει, τῆς ὁδοῦ, χειροποιήτου καὶ στενῆς οὔσης, ἑκατέρωθεν τῷ δόνακι κρύπτων.", "st": "3.66"}, {"sp": "N", "t": "Καρσουληίου δὲ καὶ Πάνσα τὰ στενὰ νυκτὸς διαδραμόντων, ἅμα δ’ ἡμέρᾳ μόνοις τοῖς Ἀρείοις καὶ πέντε ἄλλαις τάξεσιν ἐς τὴν χειροποίητον ὁδὸν ἐσβαλόντων, ἔτι καθαρευουσαν πολεμίων, καὶ τὸ ἕλος ἑκατέρωθεν ὂν περισκεπτομένων, ὅ τε δόναξ διακινούμενος ὑπωπτεύετο, καὶ ἀσπὶς ἤδη που καὶ κράνος ἐξέλαμπε, καὶ ἡ στρατηγὶς Ἀντωνίου τάξις αὐτοῖς αἰφνίδιον ἐπεφαίνετο ἐκ τοῦ μετώπου. οἱ δ’ Ἄρειοι περιειλημμένοι τε πάντοθεν καὶ οὐδαμόσε διαδραμεῖν ἔχοντες ἐκέλευον τοὺς νεήλυδας εἰ παραγένοιντο, μὴ συνεφάπτεσθαι σφίσι τῶν πόνων, ὡς μὴ συνταράξειαν αὑτοὺς ὑπὸ ἀπειρίας, τῇ στρατηγίδι δὲ Ἀντωνίου τὴν Καίσαρος στρατηγίδα ἀντέταξαν· αὐτοὶ δὲ ἐς δύο διαιρεθέντες ἐνέβαινον ἐς ἑκάτερον ἕλος, καὶ αὐτοῖς ἐπεστάτουν τῇ μὲν ὁ Πάνσας, τῇ δὲ ὁ Καρσουλήιος. δύο δὲ τῶν ἑλῶν ὄντων δύο ἦσαν οἱ πόλεμοι, τῇ διόδῳ εἰργόμενοι μὴ γινώσκειν τὰ ἀλλήλων· καὶ κατὰ τὴν δίοδον αὐτὴν αἱ στρατηγίδες πόλεμον ἄλλον ἐφ’ ἑαυτῶν ἐπολέμουν. γνώμη δὲ ἦν τοῖς μὲν Ἀντωνίου τοὺς Ἀρείους ἀμύνασθαι τῆς αὐτομολίας οἷα προδότας σφῶν γενομένους, τοῖς δ’ Ἀρείοις ἐκείνους τῆς ὑπεροψίας τῶν ἐν Βρεντεσίῳ διεφθαρμένων. συνειδότες τε ἀλλήλοις τὸ κράτιστον ὡς εἴη τῆς ἑκατέρου στρατιᾶς, ἤλπιζον ἐν τῷδε τῷ ἔργῳ μόνῳ τὸν πόλεμον κρινεῖν. καὶ τοῖς μὲν αἰδὼς ἦν τὸ δύο τέλεσιν οὖσιν δι’ ἑνὸς ἡσσᾶσθαι, τοῖς δὲ φιλοτιμία μόνοις τῶν δύο κρατῆσαι.", "st": "3.67"}, {"sp": "N", "t": "οὕτω μὲν ἀλλήλοις ἐπῄεσαν διωργισμένοι τε καὶ φιλοτιμούμενοι, σφίσι μᾶλλον ἢ τοῖς στρατηγοῖς οἰκεῖον ἡγούμενοι τόδε ἔργον· ὑπὸ δὲ ἐμπειρίας οὔτε ἠλάλαξαν ὡς οὐκ ἐκπλήξοντες ἀλλήλους, οὔτε ἐν τῷ πόνῳ τις αὐτῶν ἀφῆκε φωνὴν οὔτε νικῶν οὔτε ἡσσώμενος. περιόδους δὲ οὐκ ἔχοντες οὔτε δρόμους ὡς ἐν ἕλεσι καὶ τάφροις, ἀραρότως συνίσταντο, καὶ οὐδέτεροι τοὺς ἑτέρους ὤσασθαι δυνάμενοι τοῖς ξίφεσιν ὡς ἐν πάλῃ συνεπλέκοντο. πληγή τε οὐδεμία ἦν ἀργός, ἀλλὰ τραύματα καὶ φόνοι καὶ στόνοι μόνον ἀντὶ βοῆς· ὅ τε πίπτων εὐθὺς ὑπεξεφέρετο, καὶ ἄλλος ἀντικαθίστατο. παραινέσεων δὲ ἢ ἐπικελεύσεων οὐκ ἐδέοντο, δι’ ἐμπειρίαν ἕκαστος ἑαυτοῦ στρατηγῶν. ὅτε δὲ καὶ κάμοιεν, ὥσπερ ἐν τοῖς γυμνικοῖς ἐς ἀναπνοὴν ὀλίγον ἀλλήλων διίσταντο καὶ αὖθις συνεπλέκοντο. θάμβος τε ἦν τοῖς νεήλυσιν ἐπελθοῦσι, τοιάδε ἔργα σὺν εὐταξίᾳ καὶ σιωπῇ γιγνόμενα ἐφορῶσι.", "st": "3.68"}, {"sp": "N", "t": "πονουμένων δὲ ὧδε πάντων ὑπὲρ φύσιν ἀνθρωπίνην, ἡ μὲν στρατηγὶς ἡ Καίσαρος ἅπασα διεφθάρη, τῶν δὲ Ἀρείων οἱ μὲν ὑπὸ τῷ Καρσουληίῳ μᾶλλον ἐκράτουν τῶν κατὰ σφᾶς, οὐκ αἰσχρῶς, ἀλλὰ κατ’ ὀλίγον ἐνδιδόντων, οἱ δὲ ὑπὸ τῷ Πάνσᾳ τὸν αὐτὸν τρόπον ἐβαροῦντο, διεκαρτέρουν δ’ ὅμως ἐπ’ ἴσης ἑκάτεροι, μέχρι Πάνσας ὀβελῷ τὴν λαγόνα τρωθεὶς ἐς Βονωνίαν ἐξεφέρετο. τότε γὰρ οἱ κατ’ αὐτὸν ἀνεχώρουν, ἐπὶ πόδα πρῶτον, εἶτα μεταβαλόντες ὀξύτερον ὡς ἐν φυγῇ. καὶ οἱ νεήλυδες ἰδόντες ἔφευγον ἀτάκτως καὶ μετὰ βοῆς ἐς τὸ χαράκωμα, ὅπερ αὐτοῖς ἐξείργαστο ὁ ταμίας Τορκουᾶτος συνεστώσης ἔτι τῆς μάχης, ὑπονοήσας ἐν χρείᾳ γενήσεσθαι. οἱ μὲν δὴ νεήλυδες ἐς αὐτὸ ἀτάκτως συνειλοῦντο, Ἰταλοὶ μὲν ὄντες ὁμοίως τοῖς Ἀρείοις· ἡ δὲ ἄσκησις ἄρα τοῦ γένους ἐς τοσοῦτον ἀρετῇ διαφέρει. οἱ δὲ Ἄρειοι οὐκ ἐσῆλθον μὲν ἐς τὸ χαράκωμα αὐτοὶ ὑπὸ ἀδοξίας, ἀλλὰ παρ’ αὐτὸ ἔστησαν· κατάκοποι δὲ ὄντες ὤργων ὅμως, εἴ τις ἐπίοι, μέχρι τοῦ ἀναγκαίου τέλους διαγωνίσασθαι. Ἀντώνιος δὲ τῶν μὲν Ἀρείων ἀπέσχετο ὡς ἐπιπόνων, τοῖς δὲ νεήλυσιν ἐπιδραμὼν πολὺν εἰργάζετο φόνον.", "st": "3.69"}, {"sp": "N", "t": "Ἵρτιος δὲ ἐν Μουτίνῃ τῆς μάχης πυθόμενος, ἑξήκοντα στάδια ἀπεχούσης, ἵετο δρόμῳ μετὰ τοῦ ἑτέρου τέλους τῶν ἀπὸ Ἀντωνίου μεταστάντων. ἤδη τε ἦν ὀψία δείλη, καὶ οἱ νικήσαντες τῶν Ἀντωνίου παιανίζοντες ἐπανῄεσαν· καὶ αὐτοῖς ὁ Ἵρτιος ἀσυντάκτοις οὖσιν ἐπιφαίνεται συντεταγμένος ὁλοκλήρῳ τέλει καὶ ἀπαθεῖ. οἱ δὲ συνετάχθησαν μὲν αὖθις ὑπ’ ἀνάγκης, καὶ πολλὰ καὶ πρὸς τούσδε ἔργα λαμπρὰ ἐπεδείξαντο· οἷα δὲ ἀκμήτων ἡσσῶντο κεκμηκότες, καὶ τὸ πλεῖστον αὐτῶν μάλιστα τὸ ἔργον Ἱρτίου διέφθειρε, καίπερ οὐ διώκοντος αὐτοὺς ὑπὸ φόβου τῶν ἑλῶν, καὶ τῆς ἑσπέρας ἤδη μελαινομένης διέλυσεν αὐτούς. καὶ τὸ ἕλος ἐπὶ πλεῖστον ἐπεπλήρωτο ὅπλων τε καὶ νεκρῶν καὶ ἀνδρῶν ἡμιθνήτων καὶ τετρωμένων· οἱ δὲ καὶ ἐρρωμένοι σφῶν ὑπὸ τοῦ κόπου κατεφρόνουν. ἱππέες δὲ αὐτοὺς ἐξ Ἀντωνίου περιθέοντες, ὅσοι παρήσπιζον αὐτῷ, δι’ ὅλης τῆς νυκτὸς ἀνελέγοντο καὶ τοὺς μὲν ἀντὶ σφῶν αὐτῶν, τοὺς δὲ σὺν ἑαυτοῖς ἐπὶ τοὺς ἵππους ἀνετίθεντο ἢ τῆς οὐρᾶς ἀντεχομένους παρεκάλουν παρατροχάζειν καὶ βοηθεῖν σφίσιν ἐς τὴν σωτηρίαν. ὧδε μὲν Ἀντωνίῳ καλῶς ἀγωνισαμένῳ διέφθαρτο ἡ ἰσχὺς διὰ Ἵρτιον ἐπελθόντα. καὶ ηὐλίσατο ἐν κώμῃ παρὰ τὸ πεδίον ἀχαρακώτως· ἀγορὰ Κελτῶν ἡ κώμη καλεῖται. ἔπεσον δὲ τῶν μὲν ἄλλων ἀμφὶ τοὺς ἡμίσεας ἑκατέρων, καὶ ἡ στρατηγὶς ἡ Καίσαρος ἅπασα, Ἱρτίου δὲ ὀλίγοι.", "st": "3.70"}, {"sp": "N", "t": "τῆς δ’ ἐπιούσης ἀνεζεύγνυον ἐς τὰ ἐν τῇ Μουτίνῃ στρατόπεδα πάντες. γνώμη δὲ ἦν Ἀντωνίῳ μὲν ἐπὶ τοσῷδε πταίσματι μὴ ἐπιχειρεῖν ἔτι τοῖς ἐχθροῖς μεγάλῃ μάχῃ μηδ’ ἐπιόντων ἀμύνεσθαι, διὰ δὲ τῶν ἱππέων τὰ ἐφήμερα μόνα αὐτοὺς ἐνοχλεῖν, μέχρι παραδῴη Δέκμος αὑτὸν ἐς ἔσχατον ἤδη λιμοῦ τετρυμένος, Ἱρτίῳ δὲ καὶ Καίσαρι διὰ τοῦτο μάλιστα τὰ ἐς τὴν μάχην ἐπείγεσθαι. ἐπεὶ δ’ ἐκτάσσουσιν αὐτοῖς ὁ Ἀντώνιος οὐκ ἐπεξῆγεν, ἐς τὰ ἐπὶ θάτερα τῆς Μουτίνης ἀφυλακτότερα ὄντα διὰ δυσχέρειαν ἐχώρουν ὡς βιασόμενοι βαρεῖ στρατῷ παρεσελθεῖν ἐς αὐτήν. καὶ ὁ Ἀντώνιος αὐτῶν ἐξήπτετο τοῖς ἱππεῦσι καὶ τότε μόνοις. ἀμυνομένων δὲ κἀκείνων αὐτὸν ἱππεῦσι μόνοις καὶ τῆς ἄλλης στρατιᾶς χωρούσης, ἐφ’ ἃ ἐβούλοντο, δείσας ὁ Ἀντώνιος περὶ τῇ Μουτίνῃ ἐξῆγε δύο τέλη· οἱ δὲ ἡσθέντες ἐπέστρεφον καὶ ἐμάχοντο. ἄλλα δὲ Ἀντωνίου τέλη καλοῦντος ἐκ τῶν ἄλλων στρατοπέδων, ὧν βραδέως ὡς ἐν αἰφνιδίῳ τε μετακλήσει καὶ μακρόθεν ἰόντων ἐκράτουν οἱ τοῦ Καίσαρος τῇ μάχῃ. Ἵρτιος δὲ καὶ ἐς τὸ στρατόπεδον ἐσήλατο τοῦ Ἀντωνίου καὶ περὶ τὴν στρατηγίδα σκηνὴν μαχόμενος ἔπεσε. καὶ αὐτοῦ τό τε σῶμα ὁ Καῖσαρ ἐσδραμὼν ἀνείλετο καὶ τοῦ στρατοπέδου κατέσχεν, ἕως μετ’ ὀλίγον ἐξεώσθη πρὸς Ἀντωνίου. διενυκτέρευσαν δὲ καὶ ἐν τοῖς ὅπλοις ἑκάτεροι.", "st": "3.71"}, {"sp": "N", "t": "καὶ ὁ Ἀντώνιος δευτέρᾳ τῇδε συμπεσὼν πληγῇ συνεβουλεύετο τοῖς φίλοις εὐθὺς ἀπὸ τοῦ πόνου. καὶ τοῖς μὲν ἐδόκει τῆς προτέρας αὐτὸν γνώμης ἔχεσθαι, πολιορκοῦντα Μουτίνην καὶ ἐς μάχην οὐκ ἐπεξιόντα· τό τε γὰρ πάθος ὅμοιον ἀμφοῖν γεγονέναι καὶ Ἵρτιον ἀνῃρῆσθαι καὶ Πάνσαν νοσεῖν καὶ σφᾶς τοῖς ἱππεῦσι πλεονεκτεῖν Μουτίνην τε ἐς ἔσχατον ἀφῖχθαι λιμοῦ καὶ εὐθὺς ἐνδώσειν. ὧδε μὲν ἤρεσκε τοῖς φίλοις, καὶ ἦν τὰ ἄριστα· ὁ δὲ Ἀντώνιος, ἤδη θεοῦ βλάπτοντος, ἐδεδοίκει, μὴ ἐς τὴν Μουτίνην ὁ Καῖσαρ, ὥσπερ ἐχθὲς ἐπιχειρήσας, ἐσδράμοι ἢ αὑτὸν ἐπιχειρήσειε περιτειχίζειν, πλέον ἔχων τὸ ἐργάσιμον, “ἐν ᾧ καὶ τῶν ἱππέων,” ἔφη, “γιγνομένων ἡμῖν ἀχρήστων, ὑπερόψεταί με Λέπιδος καὶ Πλάγκος ἡττώμενον. εἰ δὲ Μουτίνης ἐξανασταῖμεν, Οὐεντίδιός τε ἡμῖν αὐτίκα προσέσται, τρία τέλη φέρων ἐκ τῆς Πικηνίτιδος, καὶ Λέπιδος καὶ Πλάγκος ἐρρωμένως οἱ συμμαχήσουσι.” ταῦτα ἔλεγεν, οὐκ ἄτολμος ἐν τοῖς κινδύνοις ἀνήρ, καὶ εἰπὼν εὐθὺς ἀνίστατο καὶ ὥδευεν ἐπὶ τῶν Ἄλπεων.", "st": "3.72"}, {"sp": "N", "t": "Δέκμῳ δὲ ἀπαλλαγέντι τῆς πολιορκίας ὁ φόβος ἐς τὸν Καίσαρα ἐνηλλάσσετο· τῶν γὰρ ὑπάτων ἐκποδὼν γενομένων ὡς ἐχθρὸν ἐδεδοίκει. τάς τε οὖν γεφύρας τοῦ ποταμοῦ διέκοπτε πρὸ ἡμέρας καὶ κελητίῳ τινὰς ἐς τὸν Καίσαρα ἀποστέλλων ἐμαρτύρει μὲν ὡς αἰτίῳ τῆς σωτηρίας, ἠξίου δὲ μέσον ἔχοντα τὸν ποταμὸν ἐς λόγους οἱ συνελθεῖν ἐπὶ μάρτυσι τοῖς πολίταις· πείσειν γάρ, ὅτι δαιμόνιον αὑτὸν ἔβλαψεν, ἐς τὴν Καίσαρος ἐπιβουλὴν ἐπηγμένον ὑφ’ ἑτέρων. Καίσαρος δὲ τοῖς ἥκουσιν ἀποκριναμένου τε πρὸς ὀργὴν καὶ τὴν χάριν, ἣν δίδωσίν οἱ Δέκμος, διωθουμένου (“οὐδὲ γὰρ Δέκμον ἐγὼ πάρειμι περισώσων, ἀλλ’ Ἀντωνίῳ πολεμήσων, ᾧ μοι καὶ συναλλαγῆναί ποτε θέμις· Δέκμῳ δὲ ἡ φύσις οὐδὲ ἐς ὄψιν ἢ λόγους ἐλθεῖν ἐπιτρέπει· σῳζέσθω μέντοι, μέχρι τοῖς ἐν ἄστει δοκεῖ”), πυθόμενος τούτων ὁ Δέκμος ἔστη τε πρὸ τοῦ ποταμοῦ καὶ καλῶν ὀνομαστὶ τὸν Καίσαρα, σὺν βοῇ τὰ γράμματα τῆς βουλῆς ἀνεγίνωσκε, διδούσης οἱ τὴν Κελτικὴν ἡγεμονίαν, ἀπηγόρευέ τε Καίσαρι χωρὶς ὑπάτων μὴ περᾶν τὸν ποταμὸν ἐς ἀλλοτρίαν ἡγεμονίαν μηδὲ ἐπὶ Ἀντώνιον ἔτι χωρεῖν· αὐτὸς γὰρ αὐτὸν διώκων ἀρκέσειν. ὁ δὲ ᾔδει μὲν ὑπὸ τῆς βουλῆς αὐτὸν ἐς τήνδε τὴν θρασύτητα αὐξανόμενον, δυνηθεὶς δ’ ἂν ἐκ προστάγματος ἑλεῖν ἐφείδετο ἔτι καὶ πρὸς τὸν Πάνσαν ἐς Βονωνίαν τραπεὶς ἔγραφε τῇ βουλῇ περὶ ἁπάντων. ἔγραφε δὲ καὶ Πάνσας.", "st": "3.73"}, {"sp": "N", "t": "καὶ Κικέρων ἐν Ῥώμῃ τὰ μὲν ἐς τὸν δῆμον ἀνεγίγνωσκεν ὡς ὑπάτου, τὰ δὲ τοῦ Καίσαρος τῇ βουλῇ μόνον· θυσίας τε ἐπ’ Ἀντωνίῳ πεντήκοντα ἡμερῶν ἱκεσίους ἐψηφίζετο, ὅσας οὔτε ἐπὶ Κελτοῖς οὔτε ἐπὶ ἄλλῳ πολέμῳ ποτὲ ἐψηφίσαντο Ῥωμαῖοι, καὶ τὸν στρατὸν τῶν ὑπάτων ἐδίδου Δέκμῳ καίπερ ἔτι Πάνσα περιόντος (ἤδη γὰρ ἀπεγιγνώσκετο), στρατηγόν τε τὸν Δέκμον ἀπέφηνεν ἐπ’ Ἀντωνίῳ μόνον εἶναι καὶ εὐχὰς δημοσίας ἐποιεῖτο Δέκμον Ἀντωνίου περιγενέσθαι. τοσοῦτος ἦν οἶστρος αὐτῷ κατὰ Ἀντωνίου καὶ ἀπειροκαλία. ἐβεβαίου τε αὖθις τοῖς δύο τέλεσι τοῖς ἀπὸ Ἀντωνίου μεταστᾶσι τὰς ἑκάστῳ προϋπεσχημένας παρὰ τοῦ κοινοῦ Ῥωμαίων ἐπινικίους δραχμὰς πεντακισχιλίας ὡς ἤδη νενικηκόσι καὶ στέφανον αὐτοὺς ἐν ταῖς ἑορταῖς αἰεὶ θαλλοῦ περιτίθεσθαι. περὶ δὲ Καίσαρος οὐδὲν ἦν ἐν τοῖς γραφομένοις, οὐδὲ τοὔνομα ὅλως· οὕτως αὐτίκα κατεφρονεῖτο ὡς Ἀντωνίου καθῃρημένου. ἔγραφον δὲ καὶ Λεπίδῳ καὶ Πλάγκῳ καὶ Ἀσινίῳ πολεμεῖν, ὅπως πλησιάσειαν Ἀντωνίῳ.", "st": "3.74"}, {"sp": "N", "t": "καὶ τάδε μὲν ἦν τὰ ἐν Ῥώμῃ, Πάνσας δ’ ἐκ τοῦ τραύματος ἀποθνῄσκων Καίσαρά οἱ παρεστήσατο καὶ εἶπεν·", "st": "3.75"}, {"sp": "N", "t": "“ἐγὼ τῷ σῷ πατρὶ φίλος ἦν ὡς ἐμαυτῷ, ἀναιρεθέντι δὲ οὐκ εἶχον ἐπαμύνειν οὐδὲ τοῖς πλείοσι μὴ συνίστασθαι, οἷς γε δὴ καὶ σὺ καλῶς ποιῶν ὑπήκουσας, καίτοι στρατὸν ἔχων. δείσαντες δ’ ἐν ἀρχῇ δὲ καὶ Ἀντώνιον, φιλοτιμότατον κἀκεῖνον ἐς τὴν Καίσαρος γνώμην φανέντα, διαφερομένοις ὑμῖν ἐφήσθησαν ὡς ἐς ἀλλήλους συντριβησομένοις. ἐπεὶ δέ σε καὶ στρατοῦ δεσπότην εἶδον, προσεποιοῦντο εὐπρεπέσι καὶ ἀσθενέσι τιμαῖς οἷα μειράκιον. σοβαρωτέρου δέ σου καὶ ἐγκρατεστέρου τιμῆς τότε μάλιστα ὀφθέντος, ὅτε τὴν ἀρχὴν ὑπὸ τοῦ στρατοῦ σοι δεδομένην οὐκ ἐδέξω, διεταράχθησαν καὶ συστρατηγεῖν σε ἡμῖν ἀπέφηναν, ἵνα σου τὰ δύο τέλη τὰ πρακτικώτερα ἀποσπάσωμεν, ἐλπίσαντες ἡττηθέντος ὑμῶν τοῦ ἑτέρου τὸν ἕτερον ἀσθενέστερόν τε καὶ μόνον ἔσεσθαι καὶ μετ’ αὐτὸν ἤδη πᾶσαν τὴν Καίσαρος ἑταιρείαν καθελόντες ἀνάξειν τὴν Πομπηίου· τόδε γάρ ἐστιν αὐτοῖς τῆς γνώμης τὸ κεφάλαιον.", "st": "3.75"}, {"sp": "N", "t": "“ἐγὼ δὲ καὶ Ἵρτιος τὸ προστεταγμένον ἐποιοῦμεν μέχρι συστεῖλαι τὸν Ἀντώνιον ἐπιπολάζοντα ὑπεροψίᾳ· ἡττηθέντα δὲ σοὶ συναλλάσσειν ἐπενοοῦμεν, ὡς τῇ Καίσαρος φιλίᾳ τόδε χαριστήριον ἔχοντες ἀποδοῦναι καὶ μόνον τῇ μοίρᾳ χρησιμώτατον ἐσόμενον ἐς τὰ μέλλοντα. τοῦτο δ’ οὐκ ἦν ἐκφέρειν σοι πρότερον, ἡττημένου δὲ νῦν Ἀντωνίου καὶ Ἱρτίου τεθνεῶτος κἀμὲ τοῦ χρεὼν ἀπάγοντος, ἐν καιρῷ λέλεκται, οὐχ ἵνα μοι γινώσκῃς χάριν ἀποθανόντι, ἀλλ’ ἵνα σὺν δαιμονίᾳ μοίρᾳ γενόμενος, ὡς τὰ ἔργα ὑποδείκνυσι, τά τε σαυτῷ συμφέροντα γινώσκῃς καὶ τὴν ἐμὴν καὶ Ἱρτίου προαίρεσίν τε καὶ ἀνάγκην. τὸν μὲν οὖν στρατόν, ὃν ἡμῖν αὐτὸς ἔδωκας, εὐπροφάσιστον ἀποδοῦναί σοι, καὶ παραδίδωμι· τοὺς δὲ νεήλυδας εἰ μὲν καθέξεις λαβών, καὶ τούσδε σοι παραδώσω, εἰ δὲ τεθήπασι τὴν βουλὴν ἀμέτρως, ὅτι καὶ οἱ ἄρχοντες αὐτῶν φύλακες ἡμῖν ἐπέμφθησαν εἶναι, καὶ τό τε ἔργον ἐπίφθονον ἔσται σοι καὶ πρὸ τοῦ δέοντος ἐξανίστησί σε, ὁ ταμίας παραλήψεται Τορκουᾶτος.”", "st": "3.76"}, {"sp": "N", "t": "ταῦτα εἰπὼν καὶ τῷ ταμίᾳ τοὺς νεήλυδας ἐγχειρίσας ἀπέθανε. καὶ τούσδε μὲν ὁ ταμίας, καθὰ προσέτασσεν ἡ βουλή, Δέκμῳ παρεδίδου, Ἵρτιον δὲ καὶ Πάνσαν ὁ Καῖσαρ ἐπιφανῶς ἔθαπτε καὶ ἐς Ῥώμην ἔπεμπε μετὰ τιμῆς.", "st": "3.76"}, {"sp": "N", "t": "τῷ δ’ αὐτῷ χρόνῳ περί τε Συρίαν καὶ Μακεδονίαν τοιάδε ἐγίγνετο. Γάιος Καῖσαρ ὅτε Συρίαν διώδευε, τέλος ἐν αὐτῇ καταλελοίπει τὰ ἐς Παρθυαίους ἤδη διανοούμενος. τούτου τὴν μὲν ἐπιμέλειαν Καικίλιος Βάσσος εἶχε, τὸ δὲ ἀξίωμα Ἰούλιος Σέξστος, μειράκιον αὐτοῦ Καίσαρος συγγενές, ὅπερ ἐκδιαιτώμενον ἐς τρυφὴν τὸ τέλος ἀσχημόνως ἐπήγετο πανταχοῦ. μεμψαμένῳ δὲ τῷ Βάσσῳ ποτὲ ἐνύβρισε· καὶ καλῶν αὐτὸν ὕστερον, ἐπεὶ βραδέως ὑπήκουσεν, ἄγειν ἐκέλευσεν ἕλκοντας. θορύβου δὲ καὶ πληγῶν γενομένων ἡ στρατιὰ τὴν ὕβριν οὐ φέρουσα τὸν Ἰούλιον κατηκόντισε. καὶ εὐθὺς ἦν μετάνοια καὶ δέος ἐκ τοῦ Καίσαρος. συνομόσαντες οὖν, εἰ μή τις αὑτοῖς συγγνώμη καὶ πίστις γένοιτο, μέχρι θανάτου διαγωνιεῖσθαι καὶ ἐς αὐτὸ Βάσσον ἀναγκάσαντες ἄλλο συνέλεξαν τέλος καὶ συνεγύμνασαν. ὧδε μέν τισι περὶ τοῦ Βάσσου δοκεῖ, Λίβωνι δ’, ὅτι τῆς Πομπηίου στρατιᾶς γενόμενος καὶ μετὰ τὴν ἧτταν ἰδιωτεύων ἐν Τύρῳ, διέφθειρέ τινας τοῦ τέλους, καὶ διεχρήσαντο τὸν Σέξστον καὶ τῷ Βάσσῳ σφᾶς ἐνεχείρισαν. ὁποτέρως δ’ ἐγένετο, Στάιον Μοῦρκον οἵδε, μετὰ τριῶν τελῶν ἐπιπεμφθέντα σφίσιν ὑπὸ τοῦ Καίσαρος, ἐγκρατῶς ἀπεμάχοντο, ἕως ὁ Μοῦρκος ἐπεκαλεῖτο Μάρκιον Κρίσπον ἡγούμενον Βιθυνίας καὶ ἀφίκετο αὐτῷ βοηθῶν ὁ Κρίσπος τέλεσιν ἄλλοις τρισίν.", "st": "3.77"}, {"sp": "N", "t": "ὡς δὲ ὑπὸ τούτων ἐπολιορκοῦντο, ὁ Κάσσιος σὺν ἐπείξει καταλαβὼν τά τε τοῦ Βάσσου δύο τέλη παρελάμβανεν αὐτίκα καὶ τὰ τῶν πολιορκούντων αὐτὸν ἕξ, φιλίᾳ τε παραδόντων καὶ ὡς ἀνθυπάτῳ κατηκόων γενομένων· ἐψήφιστο γάρ, ὥς μοι προείρηται, πάντας ὑπακούειν Κασσίῳ τε καὶ Βρούτῳ. ἄρτι δὲ καὶ Ἀλλιηνός, ὑπὸ Δολοβέλλα πεμφθεὶς ἐς Αἴγυπτον, ἐπανῆγεν ἐξ αὐτῆς τέσσαρα τέλη τῶν ἐκ τῆς ἥσσης Πομπηίου τε καὶ Κράσσου διαρριφέντων ἢ ὑπὸ Καίσαρος Κλεοπάτρᾳ καταλελειμμένων. καὶ αὐτὸν ὁ Κάσσιος οὐδὲν προπεπυσμένον ἐν τῇ Παλαιστίνῃ περιέλαβέ τε καὶ ἠνάγκασεν ἑαυτῷ προσθέσθαι, δείσαντα τοῖς τέσσαρσι μάχεσθαι πρὸς ὀκτώ. ὧδε μὲν δὴ Κάσσιος ἐκ παραδόξου δυώδεκα τελῶν ἀθρόως ἐκράτει καὶ Δολοβέλλαν ἐκ τῆς Ἀσίας σὺν δύο τέλεσιν ἐλθόντα τε καὶ ἐς Λαοδίκειαν ὑπὸ οἰκειότητος ἐσδεχθέντα περικαθήμενος ἐπολιόρκει. καὶ ἡ βουλὴ μαθοῦσα ἐφήδετο.", "st": "3.78"}, {"sp": "N", "t": "Μακεδονίας δὲ πέρι Γάιος Ἀντώνιος, ὁ Ἀντωνίου Μάρκου ἀδελφός, Βρούτῳ διεφέρετο καὶ ἐπολέμει, τέλος ἔχων ἓν ὁπλιτῶν· καὶ τὸν Βροῦτον ἡσσώμενος ἐνήδρευσεν. ὁ δ’ ἐκφυγὼν ἀντενήδρευσε καὶ οὐδὲν εἰργάσατο ἀποληφθέντας, ἀλλὰ ἀσπάσασθαι τῷ ἰδίῳ στρατῷ τοὺς ἐναντίους προσέταξε· τῶν δὲ οὐκ ἀντασπασαμένων οὐδὲ τὴν πεῖραν ἐνδεξαμένων, μεθῆκεν ἀπαθεῖς ἐκ τῆς ἐνέδρας ἀπιέναι. κατὰ δὲ ἄλλας ὁδοὺς περιελθὼν αὖθις ἐν ἀποκρήμνοις κατέστησε καὶ πάλιν οὐκ ἐπεχείρησεν, ἀλλ’ ἠσπάσατο. οἱ δέ, ὡς πολιτῶν τε περιφειδόμενον καὶ τῆς δόξης ἄξιον ἧς εἶχεν ἐπὶ σοφίᾳ τε καὶ πραότητι, ἠγάσαντο καὶ ἀντησπάσαντο καὶ ἐς αὐτὸν μετεβάλοντο. ἐπέτρεψε δὲ καὶ ὁ Γάιος ἑαυτὸν καὶ ἦν ἐν τιμῇ παρὰ Βρούτῳ, μέχρι τὸν στρατὸν πολλάκις διαφθείρων ἐλεγχθεὶς ἀνῃρέθη. οὕτω μὲν δὴ καὶ Βρούτῳ μετὰ τῶν προτέρων στρατῶν ἓξ ἐγίνετο τέλη· καὶ Μακεδόνας ἐπαινῶν δύο τέλη κατέλεξεν ἐξ αὐτῶν, καὶ ἐς τὸν Ἰταλικὸν τρόπον καὶ τάδε ἐγυμνάζετο.", "st": "3.79"}, {"sp": "N", "t": "τοιαῦτα μὲν δὴ καὶ τὰ περὶ Συρίαν καὶ Μακεδονίαν ἦν· ἐν δὲ τῇ Ἰταλίᾳ ὁ Καῖσαρ ἐν ὕβρει θέμενος ἀντὶ οὗ Δέκμον ᾑρῆσθαι στρατηγὸν ἐπὶ Ἀντωνίῳ, τὴν μὲν ὀργὴν ἐπέκρυπτε, θρίαμβον δ’ ἐπὶ τοῖς εἰργασμένοις ᾔτει. καταφρονούμενος δ’ ὑπὸ τῆς βουλῆς ὡς πρεσβύτερα τῆς ἡλικίας ἐπινοῶν, ἔδεισε, μὴ διαφθαρέντος Ἀντωνίου μᾶλλον ἔτι καταφρονηθείη, καὶ τὰς ἐς αὐτὸν συμβάσεις ἐπόθει, καθὰ καὶ Πάνσας αὐτῷ διεσήμαινεν ἀποθνῄσκων. τούς τε οὖν ἀλωμένους ἐκ τῆς ἐκείνου στρατιᾶς ἡγεμόνας ἢ στρατιώτας ἐφιλανθρωπεύετο, καὶ τοῖς ἰδίοις ἐγκατέλεγεν ἢ τοὺς ἐθέλοντας αὐτῶν ἐς τὸν Ἀντώνιον ἔπεμπεν, ὡς οὐ δι’ ἔχθρας ἀνηκέστου πρὸς αὐτὸν ἰόντα· Οὐεντιδίῳ τε τῷ Ἀντωνίου φίλῳ, μετὰ τριῶν τελῶν ὄντι, παραστρατοπεδεύσας καὶ δέος ἐμβαλὼν ἔπραξε μὲν οὐδὲν πολέμιον, ἐδίδου δὲ ὁμοίως συνεῖναί οἱ ἢ ἐς τὸν Ἀντώνιον ἀδεῶς ἀπιέναι μετὰ τοῦ στρατοῦ καὶ μέμφεσθαι τῆς ἐς τὸ κοινὸν συμφέρον ἀγνωσίας. ὧν Οὐεντίδιος συνεὶς ἐς τὸν Ἀντώνιον ἀπῄει. ὁ δὲ Καῖσαρ Δέκιον, τῶν τινα ἡγεμόνων Ἀντωνίου, περὶ Μουτίνην ληφθέντα διὰ τιμῆς ἄγων μεθῆκεν, εἰ θέλοι, πρὸς τὸν Ἀντώνιον ἀπιέναι· καὶ πυνθανομένῳ περὶ τῆς ἐς τὸν Ἀντώνιον γνώμης πολλὰ ἔφη σύμβολα τοῖς εὖ φρονοῦσιν ἐξενηνοχέναι, τοῖς δ’ ἄφροσιν οὐδὲ τὰ πλείονα ἀρκέσειν.", "st": "3.80"}, {"sp": "N", "t": "Ἀντωνίῳ μὲν δὴ τάδε ὁ Καῖσαρ ἐνεσήμαινε, Λεπίδῳ δὲ καὶ Ἀσινίῳ σαφέστερον ἔτι περὶ τῆς ἐς αὑτὸν ὕβρεως καὶ τῆς τῶν σφαγέων ἀθρόας προαγωγῆς ἐπέστελλεν, ἐκφοβῶν αὐτούς, μὴ ἐς χάριν τῆς Πομπηιανῆς ἑταιρείας καθ’ ἕνα τῶν Καίσαρος ἕκαστος ὅμοια Ἀντωνίῳ πάθοι, κἀκείνῳ δι’ ἀφροσύνην καὶ ὑπεροψίαν τοῦδε τοῦ δέους τάδε παθόντι. ἠξίου τε ἐς μὲν εὐπρέπειαν τῆς βουλῆς εἶναι κατηκόους, ἐς δὲ τὸ σφέτερον ἀσφαλὲς συμφρονεῖν, ἕως ἔτι δύνανται, καὶ ὀνειδίζειν ταῦτα Ἀντωνίῳ, μιμεῖσθαί τε τοὺς ὑπὸ σφίσιν ὁπλίτας· οὐ διαλυομένους, οὐδ’ ὅτε παύσαιντο τῶν στρατειῶν, ἵνα μὴ τοῖς ἐχθροῖς εἶεν εὐεπίθετοι, ἀλλ’ ἀθρόους ἐν ἀλλοτρίᾳ συνοικίζεσθαι διὰ τὴν ἰσχὺν μᾶλλον ἐθέλοντας ἢ καθ’ ἕνα τῶν πατρίδων ἀπολαύειν. τάδε μὲν ὁ Καῖσαρ Λεπίδῳ τε ἐπέστελλε καὶ Ἀσινίῳ· Δέκμῳ δὲ ὁ ἀρχαῖος στρατὸς ἐνόσει πιμπλάμενος ἐκ λιμοῦ καὶ τὰς γαστέρας κατερρήγνυντο, ὅ τε νεοστράτευτος ἀγύμναστος ἔτι ἦν. Πλάγκος δὲ προσεγένετο μετὰ τοῦ οἰκείου στρατοῦ, καὶ ὁ Δέκμος ἐπέστελλε τῇ βουλῇ τὸν Ἀντώνιον ἀλώμενον κυνηγετήσειν ναυτικῶν περ ἤδη γεγονότων.", "st": "3.81"}, {"sp": "N", "t": "οἵ τε Πομπηιανοὶ πυθόμενοι θαυμαστοὶ ὅσοι διεφάνησαν, ἐκβοῶντες ἄρτι τὴν πάτριον ἐλευθερίαν ἀπειληφέναι, καὶ θυσίαι καθ’ ἕνα ἦσαν καὶ χειροτονίαι δέκα ἀνδρῶν ἐς εὔθυναν τῆς ἀρχῆς τῆς Ἀντωνίου. πρόσχημα δὲ τοῦτο ἦν ἐς ἀκύρωσιν τῶν ὑπὸ Καίσαρος διατεταγμένων· Ἀντώνιος γὰρ οὐδὲν αὐτὸς ἢ πάνυ σμικρά, πάντα δὲ ἐκ τῶν Καίσαρος ὑπομνημάτων διῳκήκει, καὶ τόδε σαφῶς εἰδυῖα ἡ βουλὴ τὰ μέν τινα αὐτῶν ἐπὶ προφάσεσι διέλυεν, ἀθρόα δὲ οὕτως ἤλπιζε διαλύσειν. οἱ μὲν δὴ δέκα προύγραφον, ὅ τι τις λάβοι παρὰ τὴν ἀρχὴν Ἀντωνίου, πάντας αὐτίκα ἀπογράφεσθαι καὶ διδάσκειν· ἀπειλαί τε τοῖς ἀπειθοῦσιν ἐπετίθεντο. καὶ τὴν ὕπατον ἀρχὴν ἐς τὸ λοιπὸν τοῦ ἔτους οἱ Πομπηιανοὶ μετῄεσαν ἀντὶ Ἱρτίου τε καὶ Πάνσα· μετῄει δὲ καὶ ὁ Καῖσαρ, οὐκ ἐς τὴν βουλὴν ἔτι πέμπων, ἀλλ’ ἐς τὸν Κικέρωνα ἰδίᾳ, καὶ αὐτὸν παρεκάλει καὶ συνάρξαι, ὡς Κικέρωνα μὲν τὴν ἀρχὴν διοικήσοντα πρεσβύτερόν τε καὶ ἐμπειρότερον ὄντα, αὐτὸς δὲ τὴν ἐπωνυμίαν καρπωσόμενος μόνην ἐς ἀπόθεσιν τῶν ὅπλων εὐπρεπῆ, οὗ δὴ καὶ πρῴην ἕνεκα τὸν θρίαμβον αἰτῆσαι. Κικέρων μὲν δὴ τούτοις ἐπαρθεὶς διὰ φιλαρχίαν, ἔλεγεν αἰσθέσθαι σπονδῶν ἐν τοῖς ἔξω στρατηγοῖς ὑπονοουμένων καὶ συνεβούλευε θεραπεῦσαι τὸν ἄνδρα, ὑβρισμένον καὶ στρατοῦ ἔτι ἄρχοντα πολλοῦ, ἀνασχέσθαι τε παρ’ ἡλικίαν ἄρχοντος ἐν τῇ πόλει μᾶλλον ἢ μηνίοντος ἐν ὅπλοις· ὡς δ’ ἄν τι μὴ πράξειε παρὰ τὸ τῇ βουλῇ συμφέρον, ἐκέλευεν αὐτῷ συνελέσθαι τῶν τινα πρεσβυτέρων ἔμφρονα, τῆς ἐκείνου νεότητος ἐγκρατῆ παιδαγωγόν.", "st": "3.82"}, {"sp": "N", "t": "ἀλλὰ Κικέρωνα μὲν ἥ τε βουλὴ τῆς φιλαρχίας ἐγέλασε, καὶ οἱ συγγενεῖς μάλιστα τῶν σφαγέων ἐνέστησαν, δεδιότες μὴ αὐτοὺς ὁ Καῖσαρ τίσαιτο ὑπατεύων· ὑπερθέσεων δὲ ἐπὶ τῇ χειροτονίᾳ γιγνομένων ἐννόμων κατὰ ποικίλας αἰτίας, ὁ Ἀντώνιος ἐν τῷ τέως τὰς Ἄλπεις ὑπερέβαλε, Κουλλεῶνα πείσας τὸν ἐκ Λεπίδου φύλακα αὐτῶν, ἐπί τε ποταμὸν ἦλθεν, ἔνθα ἐστρατοπεδευμένος ἦν ὁ Λέπιδος, καὶ οὔτε χάρακα περιεβάλετο οὔτε τάφρον ὡς δὴ φίλῳ παραστρατοπεδεύων. διαπομπαὶ δὲ ἦσαν ἐς ἀλλήλους πυκναί, Ἀντωνίου μὲν ὑπομιμνήσκοντος φιλίας τε καὶ χαρίτων ποικίλων, καὶ διδάσκοντος, ὅτι μεθ’ αὑτὸν ὅμοια πείσονται καθ’ ἕνα πάντες, οἳ τῆς Καίσαρος ἐγένοντο φιλίας, Λεπίδου δὲ τὴν μὲν βουλὴν δεδιότος πολεμεῖν αὐτῷ κελεύουσαν, ὑπισχνουμένου δ’ ὅμως οὐ πολεμήσειν ἑκόντος. ὁ δὲ στρατὸς ὁ τοῦ Λεπίδου τό τε ἀξίωμα αἰδούμενοι τὸ Ἀντωνίου καὶ τῶν διαπομπῶν αἰσθανόμενοι καὶ τὴν ἀφέλειαν αὐτοῦ τῆς στρατοπεδείας ἀγάμενοι, ἐπεμίγνυντο τοῖς Ἀντωνίου λανθάνοντες, εἶτα φανερῶς οἷα πολίταις τε καὶ συστρατιώταις γενομένοις, τῶν τε χιλιάρχων κωλυόντων ὑπερεώρων καὶ τὸν ποταμὸν ἐς εὐμάρειαν τῆς ἐπιμιξίας ναυσὶν ἐγεφύρουν· τό τε καλούμενον δέκατον τέλος, ἐξεναγημένον ὑπὸ Ἀντωνίου πάλαι, τὰ ἔνδον αὐτῷ παρεσκεύαζεν.", "st": "3.83"}, {"sp": "N", "t": "ὧν αἰσθανόμενος Λατερήσιος, τῶν τις ἐκ τῆς βουλῆς ἐπιφανῶν, προηγόρευε τῷ Λεπίδῳ καὶ ἀπιστοῦντα ἐκέλευε τὴν στρατιὰν ἐς πολλὰ διελόντα ἐκπέμψαι κατὰ δή τινας χρείας, ἐς ἐπίδειξιν ἢ τῆς προδοσίας ἢ τῆς πίστεως. καὶ ὁ Λέπιδος ἐς τρία διελών, ἐκέλευε νυκτὸς ἐξορμᾶν ἐς φρουρὰν ταμιείων πλησιαζόντων. οἱ δὲ ἀμφὶ τὴν ἐσχάτην φυλακήν, ὡς ἐς τὴν ἔξοδον ὁπλισάμενοι, τὰ ἐρυμνὰ τοῦ στρατοπέδου κατέλαβον καὶ τὰς πύλας ἀνεῴγνυον Ἀντωνίῳ. ὁ δ’ ἐπὶ τὴν Λεπίδου σκηνὴν ἵετο δρόμῳ, τοῦ στρατοῦ παντὸς ἤδη τοῦ Λεπίδου παραπέμποντος αὐτὸν καὶ τὸν Λέπιδον αἰτοῦντος εἰρήνην τε καὶ ἔλεον ἐς ἀτυχοῦντας πολίτας. ὁ μὲν δὴ Λέπιδος, ὡς εἶχεν, ἐκ τῆς εὐνῆς ἄζωστος ἐς αὐτοὺς ἐξέθορε καὶ ὑπισχνεῖτο ποιήσειν καὶ τὸν Ἀντώνιον ἠσπάζετο καὶ ἐξελογεῖτο τῆς ἀνάγκης. οἱ δὲ αὐτὸν καὶ προσπεσεῖν Ἀντωνίῳ νομίζουσιν, ἄπρακτον μὲν ὄντα καὶ ἄτολμον, οὐ μὴν ἅπασι τοῖς συγγραφεῦσι πιστὸν οὐδ’ ἐμοὶ πιθανόν· οὐ γάρ πώ τι αὐτῷ πολέμιον ἐς τὸν Ἀντώνιον ἐπέπρακτο, δέους ἄξιον. οὕτω μὲν ὁ Ἀντώνιος ἐς μέγα δυνάμεως αὖθις ἐπῆρτο, καὶ τοῖς ἐχθροῖς ἦν ἐπιφοβώτατος· στρατὸν γὰρ εἶχεν, ὅν τε ἐξανέστησε Μουτίνης καὶ σὺν αὐτῷ λαμπρότατον ἱππικόν, τρία τε αὐτῷ τέλη κατὰ τὴν ὁδὸν προσγεγένητο τὰ Οὐεντιδίου, καὶ Λέπιδος αὐτῷ σύμμαχος ἐγίγνετο ἑπτὰ ἔχων ὁπλιτικὰ τέλη καὶ πολὺν ὅμιλον ἄλλον καὶ παρασκευὴν ἀξιόλογον. καὶ τοῖσδε ὁ μὲν Λέπιδος ἐπωνομάζετο ἔτι, ὁ δὲ Ἀντώνιος ἅπαντα διῴκει.", "st": "3.84"}, {"sp": "N", "t": "Ἐξαγγελθέντων δὲ τῶνδε ἐς Ῥώμην θαυμαστὴ καὶ αἰφνίδιος ἦν αὖθις μεταβολή, τῶν μὲν ἐκ τῆς οὐ πρὸ πολλοῦ καταφρονήσεως ἐς δέος, τῶν δὲ ἐς θάρσος ἀπὸ τοῦ δέους μεθισταμένων. αἵ τε προγραφαὶ τῶν δέκα ἀνδρῶν κατεσπῶντο σὺν ὕβρει, καὶ αἱ χειροτονίαι τῶν ὑπάτων ἐπείχοντο ἔτι μᾶλλον· ἥ τε βουλὴ πάμπαν ἀποροῦσα, καὶ δεδιυῖα, μὴ συνθοῖντο ἀλλήλοις ὅ τε Καῖσαρ καὶ ὁ Ἀντώνιος, ἔπεμπε μὲν ἐς Βροῦτόν τε καὶ Κάσσιον κρύφα ἀπὸ σφῶν Λεύκιον καὶ Πάνσαν, ὡς ἐπὶ θέας εἰς Ἑλλάδα ἐξιόντας, ἀμύνειν αὑτοῖς ἐς ὃ δύναιντο, μετεκάλει δὲ ἐκ Λιβύης ἀπὸ τριῶν τῶν ὑπὸ Σέξτιον δύο τέλη, καὶ τὸ τρίτον ἐκέλευε Κορνιφικίῳ παραδοθῆναι, τῆς ἑτέρας ἄρχοντι Λιβύης καὶ τὰ τῆς βουλῆς φρονοῦντι, εἰδότες μὲν καὶ τούσδε Γαΐῳ Καίσαρι ἐστρατευμένους καὶ τὰ ἐκείνου πάντα ὑπονοοῦντες· ἡ δὲ ἀπορία σφᾶς ὧδε ἤπειγεν, ἐπεὶ καὶ τὸν νέον Καίσαρα, δεδιότες μὴ συνθοῖτο Ἀντωνίῳ, στρατηγὸν αὖθις ἐπὶ Ἀντωνίῳ μάλα ἀπρεπῶς ἐχειροτόνουν ἅμα Δέκμῳ.", "st": "3.85"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ἤδη τὸν στρατὸν εἰς ὀργὴν ὑπέρ τε αὑτοῦ, ὡς συνεχῶς ὑβριζόμενος, ἀνεκίνει καὶ ὑπὲρ σφῶν ἐκείνων, ἐπὶ δευτέραν στρατείαν πεμπομένων, πρὶν ἐπὶ τῇ προτέρᾳ λαβεῖν τὰς πεντακις χιλίας δραχμάς, ὅσας αὐτοῖς ὑπέσχοντο δώσειν· ἐδίδασκέ τε πέμποντας αἰτεῖν. οἱ δ’ ἔπεμπον τοὺς λοχαγούς. καὶ ἡ βουλὴ συνίει μὲν αὐτοὺς ἐς ταῦτα διδασκομένους, ἀποκρινεῖσθαι δὲ αὐτοῖς ἔφη δι’ ἑτέρων πρέσβεων. καὶ ἔπεμπον, οὓς ἐδίδαξαν τοῖς δύο τέλεσι τοῖς ἀπ’ Ἀντωνίου μεθεστηκόσιν ἐντυχεῖν ἄνευ τοῦ Καίσαρος, καὶ διδάσκειν μὴ ἐφ’ ἑνὶ ποιεῖσθαι τὰς ἐλπίδας, ἀλλ’ ἐπὶ τῇ βουλῇ τὸ κράτος ἀθάνατον ἐχούσῃ μόνῃ, χωρεῖν δὲ πρὸς Δέκμον, ἔνθα σφίσι τὰ χρήματα ἀπαντήσειν. ταῦτ’ ἐπισκήψαντες λέγειν ἐσέφερον ἤδη τὸ ἥμισυ τῆς δωρεᾶς καὶ δέκα ἄνδρας ἐς τὴν διανέμησιν ἐχειροτόνουν, οἷς οὐδὲ ἑνδέκατον προσετίθεσαν εἶναι τὸν Καίσαρα. οἱ μὲν δὴ πρέσβεις, οὐκ ἀνασχομένων τῶν δύο τελῶν ἐντυχεῖν σφίσιν ἄνευ τοῦ Καίσαρος, ὑπέστρεφον ἄπρακτοι· ὁ δὲ Καῖσαρ οὐκέτι τοὺς λόγους καθίει δι’ ἑτέρων οὐδὲ μέλλειν ἠξίου, ἀλλ’ αὐτὸς ἐς τὸν στρατὸν συνειλεγμένον ἐπελθών, τά τε ὑβρίσματα, ὅσα ἐς αὐτὸν ἐκ τῆς βουλῆς γεγένητο, κατέλεξε, καὶ τὴν ἐς πάντας τοὺς Γαΐου Καίσαρος ἐπιβουλήν, καθ’ ἕνα καθαιρουμένους, δεδιέναι τε αὐτοῖς περὶ σφῶν διεκελεύσατο, μεταφερομένοις ἔς τε πολέμιον τῆς μοίρας στρατηγὸν καὶ πολέμους ἑτέρους ἀφ’ ἑτέρων, ἵν’ ἢ ἐκφθαρεῖεν ἢ καὶ πρὸς ἀλλήλους στασιάσειαν· ἐπὶ γὰρ τῷδε καὶ τοῦ περὶ Μουτίνην ἔργου κοινοῦ γεγονότος τὰ γέρα τοῖς δύο τέλεσι μόνοις δίδοσθαι, ἵν’ αὐτοὺς ἐς ἔριν καὶ στάσιν ἐμβάλοιεν.", "st": "3.86"}, {"sp": "N", "t": "“Ἴστε δέ,” ἔφη, “καὶ ἐφ’ οἷς ὁ Ἀντώνιος ἔναγχος ἡττήθη οἷά τε τοὺς Πομπηιανοὺς ἐπύθεσθε ἐν ἄστει πεποιηκέναι κατὰ τῶν τινας δωρεὰς παρὰ Καίσαρος εἰληφότων. τί δὴ πιστὸν ἢ ὑμῖν ὧν ἐλάβετε παρ’ ἐκείνου χωρίων τε καὶ χρημάτων ἢ ἐμοὶ τῆς σωτηρίας, ὧδε ἐν τῇ βουλῇ δυναστευόντων τῶν οἰκείων τοῖς σφαγεῦσι; κἀγὼ μὲν ἐκδέξομαι τὸ τέλος, ὅ τι ἂν ἐπιγίγνηταί μοι (καλὸν γάρ τι καὶ παθεῖν πατρὶ ἐπικουροῦντα), ὑπὲρ δὲ ὑμῶν δέδια τοιῶνδε καὶ τοσῶνδε, κινδυνευόντων ἐς ἐμὴν καὶ τοῦ πατρὸς χάριν. ἴστε μὲν δή με καθαρεύοντα φιλοτιμίας, ἐξ οὗ στρατηγεῖν μοι διδόντων ὑμῶν ὑπὸ σημείοις οὐκ ἐδεχόμην· ἓν δὲ μόνον ὁρῶ νῦν ἀμφοτέροις σωτήριον, εἰ δι’ ὑμῶν ὕπατος ἀποδειχθείην. τά τε γὰρ παρὰ τοῦ πατρὸς ὑμῖν δοθέντα πάντα βέβαια ἔσται, ἀποικίαι τε προσέσονται αἱ ἔτι ὀφειλόμεναι, καὶ γέρα πάντα ἐντελῆ· ἐγώ τε τοὺς φονέας ὑπὸ δίκην ἀγαγὼν τοὺς ἄλλους ἂν ὑμῖν καταλύσαιμι πολέμους.”", "st": "3.87"}, {"sp": "N", "t": "ὧν λεγομένων ἥ τε στρατιὰ προθύμως ἐπεβόησε, καὶ τοὺς λοχαγοὺς αὐτίκα ἔπεμπον αἰτήσοντας τὴν ἀρχὴν τῷ Καίσαρι. ὑποκριναμένης δὲ τῆς βουλῆς τὴν ἡλικίαν, ἔλεγον οἱ λοχαγοὶ ἃ ἐδιδάχθησαν, ὅτι καὶ πάλαι Κορουῖνός τε ἄρξειε νεώτερος ὢν ἔτι καὶ Σκιπίων ὕστερον, ὅ τε πρότερος καὶ ὁ δεύτερος, καὶ ἐκ τῆς νεότητος ἑκάστου πολλὰ ὄναιτο ἡ πατρίς. τά τε ἔναγχος ταῦτα καὶ Πομπήιον Μάγνον αὐτοῖς καὶ Δολοβέλλαν προύφερον, αὐτῷ τε Καίσαρι ἤδη δεδόσθαι τὴν ἀρχὴν μετιέναι θᾶσσον ἐτῶν δέκα. ταῦτα τῶν λοχαγῶν σὺν πλέονι παρρησίᾳ λεγόντων, οὐκ ἀνασχόμενοί τινες τῶν βουλευτῶν λοχαγοὺς ὄντας ὧδε παρρησιάζεσθαι, ἐπέπλησσον ὡς θρασυνομένοις ὑπὲρ τὸ στρατιώταις πρέπον. καὶ ὁ στρατὸς πυθόμενος ἔτι μᾶλλον ὠργίζοντο καὶ ἄγειν σφᾶς εὐθὺς ἐκέλευον ἐς τὴν πόλιν, ὡς αὐτοὶ χειροτονήσοντες αὐτὸν ἐξαιρέτῳ χειροτονίᾳ, Καίσαρος υἱὸν ὄντα, πολλά τε τὸν πρότερον Καίσαρα ἀπαύστως εὐφήμουν. ὧδε δὲ αὐτοὺς ὁρμῆς ἔχοντας ὁ Καῖσαρ ἰδὼν ἦγεν εὐθὺς ἀπὸ τῆς συνόδου, ὀκτὼ τέλη πεζῶν καὶ ἵππον ἱκανὴν καὶ ὅσα ἄλλα τοῖς τέλεσι συνετάσσετο. περάσας δὲ τὸν Ῥουβίκωνα ποταμὸν ἐκ τῆς Κελτικῆς ἐς τὴν Ἰταλίαν, ὅν τινα αὐτοῦ καὶ ὁ πατὴρ ὁμοίως ἐπὶ τῷ πολιτικῷ πολέμῳ πρῶτον ἐπέρασεν, ἐς δύο πάντας διῄρει· καὶ τὸ μὲν ἕπεσθαι κατὰ σχολὴν ἐκέλευσε, τὸ δὲ ἄμεινον ἐπιλεξάμενος ἐτρόχαζεν, ἐπειγόμενος ἔτι ἀπαρασκεύους καταλαβεῖν. μέρους τε τῶν χρημάτων ὑπαντῶντος, ἃ ἐς τὰ γέρα τοῖς στρατιώταις ἡ βουλὴ πεπόμφει, δείσας ἐπὶ τοῖς μισθοφόροις ὁ Καῖσαρ προύπεμπε κρύφα τοὺς ἐκφοβήσοντας· καὶ οἱ μὲν ἔφευγον μετὰ τῶν χρημάτων.", "st": "3.88"}, {"sp": "N", "t": "ἐς δὲ τὸ ἄστυ τῆς ἀγγελίας ἀφικομένης θόρυβος ἦν καὶ φόβος ἄπλετος, διαθεόντων τε ἀκόσμως καὶ γύναιά τινων ἢ παῖδας ἢ ὅσα τιμιώτατα ἄλλα ἐς ἀγροὺς ἢ τὰ ἐρυμνὰ τῆς πόλεως μεταφερόντων· οὐ γάρ πω σαφοῦς ὄντος, ὅτι μόνης ὀρέγοιτο ὑπατείας, πολέμιον στρατὸν ἐπιέναι σὺν ὀργῇ πυνθανόμενοι ἐς πάντα ἐδεδοίκεσαν. ἡ βουλὴ δ’ ἐξεπέπληκτο ἀμέτρως, οὐδεμιᾶς αὑτοῖς οὔσης ἑτοίμου δυνάμεως, ἀλλήλους τε, οἷον ἐν τοῖς φόβοις γίγνεται, κατεμέμφοντο, οἱ μὲν ὅτι τὴν στρατιὰν αὐτὸν ἀφέλοιντο τὴν ἐπὶ τὸν Ἀντώνιον ὑβριστικῶς, οἱ δὲ τῆς ἐς τὸν θρίαμβον ὑπεροψίας, οὐκ ἄδικον ὄντα, οἱ δὲ τοῦ φθόνου τῆς διανεμήσεως τῶν χρημάτων, οἱ δὲ οὐδὲ ἑνδέκατον ἐπιγράψαντες· οἱ δὲ αὐτὰ τὰ ἆθλα, οὔτε ὀξέως οὔτε ἐντελῆ διδόμενα, τὴν στρατιὰν σφίσιν ἔλεγον ἐκπολεμῶσαι. τῆς τε φιλονικίας τὸ ἄκαιρον μάλιστα ἐμέμφοντο, Βρούτου μὲν καὶ Κασσίου πορρωτέρω τε ὄντων καὶ συνισταμένων ἔτι, ἐν δὲ πλευραῖς Ἀντωνίου καὶ Λεπίδου πολεμίων· οὓς ὅτε ἐνθυμηθεῖεν Καίσαρι συναλλαγήσεσθαι, πάμπαν ἤκμαζεν ὁ φόβος. Κικέρων τε, ὃς τέως αὐτοῖς ἐπεπόλαζεν, οὐδὲ ἐφαίνετο.", "st": "3.89"}, {"sp": "N", "t": "ἀθρόα δὴ πάντων ἐς πάντα ἦν μετάθεσις, ἀντὶ μὲν δισχιλίων καὶ πεντακοσίων δραχμῶν τὰς πεντακισχιλίας, ἀντὶ δὲ τῶν δύο τελῶν τοῖς ὀκτὼ δοθῆναι, Καίσαρά τε αὐτοῖς ἀντὶ τῶν δέκα ἀνδρῶν διανέμειν καὶ ἐς τὴν ὕπατον ἀρχὴν παραγγέλλειν ἀπόντα. πρέσβεις τε ἐξέτρεχον, οἳ τάδε φράσειν ἔμελλον αὐτῷ κατὰ σπουδήν. ὧν ἄρτι τῆς πόλεως ἐκδραμόντων μετάνοια ἐνέπιπτε τῇ βουλῇ, μὴ δεῖν οὕτως ἀνάνδρως καταπεπλῆχθαι, μηδὲ ἑτέραν ἐνδέξασθαι τυραννίδα ἀναιμωτί, μηδὲ ἐθίσαι τοὺς ἀρχῆς ἐφιεμένους ἐκ βίας τυγχάνειν, μηδὲ τοὺς στρατευομένους ἐξ ἐπιτάγματος ἄρχειν τῆς πατρίδος, ὁπλισαμένους δὲ ἐκ τῶν ἐνόντων τοὺς νόμους τοῖς ἐπιοῦσι προτείνειν· προσδοκᾶν γὰρ οὐδὲ ἐκείνους νόμων προτεινομένων ὅπλα τῇ πατρίδι ἐποίσειν· εἰ δὲ φέροιεν, ἀνέχεσθαί τε πολιορκίας, μέχρι Δέκμος ἢ Πλάγκος ἔλθοι; καὶ ἀμύνεσθαι μέχρι θανάτου μᾶλλον ἢ ἑκόντας ἐνδέξασθαι δουλείαν ἄνωθεν ἀδιόρθωτον· τά τε ἀρχαῖα Ῥωμαίων ἐπὶ ἐλευθερίᾳ φρονήματα καὶ πάθη, πρὸς οὐδὲν ἐνδόντων ὑπὲρ ἐλευθερίας, ἀνελέγοντο.", "st": "3.90"}, {"sp": "N", "t": "ἐπεὶ δὲ αὐτοῖς καὶ τὰ δύο τέλη τὰ ἐκ Λιβύης μετάπεμπτα ἐς τὸν λιμένα αὐτῆς ἡμέρας ἀφίκετο, τοὺς θεοὺς σφᾶς ἔδοξαν ἐπὶ τὴν ἐλευθερίαν ἐποτρύνειν. ἡ μὲν δὴ μετάνοια ἐκεκύρωτο, καὶ μετεψηφίζετο ἅπαντα, Κικέρωνος αὖθις αὐτοῖς ἐπιφανέντος· ἥ τε στρατεύσιμος ἡλικία προεγράφετο πᾶσα, καὶ τὰ δύο τέλη τάδε, τὰ ἐκ Λιβύης, καὶ οἱ σὺν αὐτοῖς ἱππέες χίλιοι καὶ τέλος ἕτερον, ὃ Πάνσας αὐτοῖς ὑπολελοίπει, πάντες οἵδε μερισθέντες οἱ μὲν τὸν λόφον τὸν καλούμενον Ἰάνουκλον, ἔνθα καὶ τὰ χρήματα ἐσώρευσαν, ἐφρούρουν, οἱ δὲ τὴν τοῦ ποταμοῦ γέφυραν, ἐπιδιῃρημένων σφίσι τῶν στρατηγῶν τῶν κατὰ τὴν πόλιν· ἄλλοι δὲ αὐτοῖς τὰ ἐν τῷ λιμένι σκάφη καὶ ναῦς καὶ χρήματα εὐτρέπιζον, εἰ δεήσειεν ἡττωμένους φυγεῖν διὰ θαλάσσης. καὶ τάδε σὺν εὐθαρσείᾳ πράσσοντες οὕτως ὀξέως ἤλπιζον ἀντικαταπλήξειν τὸν Καίσαρα, καὶ ἢ μεταπείσειν παρὰ σφῶν ἀντὶ τοῦ στρατεύματος αἰτεῖν τὴν ἀρχήν, ἢ ἐγκρατῶς ἀμυνεῖσθαι· τούς τε τῆς ἐναντίας μοίρας νῦν γε μεταθήσεσθαι προσεδόκων, μέχρι περὶ τῆς ἐλευθερίας ἐστὶν ὁ ἀγών. τὴν δὲ μητέρα Καίσαρος καὶ τὴν ἀδελφὴν οὔτε φανερῶς οὔτε λάθρᾳ ζητοῦντες εὕρισκον. ἐθορυβοῦντο οὖν αὖθις ὁμήρων μεγάλων ἀφῃρημένοι· καὶ τῶν Καισαριανῶν οὔπω σφίσιν ἐπικλωμένων, ὑπὸ ἐκείνων αὐτὰς ὧδε ἀκριβῶς ἐνόμιζον ἐπικρύπτεσθαι.", "st": "3.91"}, {"sp": "N", "t": "Καίσαρι δὲ ἔτι τῶν πρέσβεων ἐντυγχανόντων τὰ μετεψηφισμένα ἀγγέλλεται· καὶ αὐτὸν οἱ πρέσβεις ἀπολιπόντες ἀνέστρεφον ὑπὸ αἰδοῦς. ὁ δὲ τῷ στρατῷ μᾶλλον ἔτι παρωξυμμένῳ κατὰ σπουδὴν ἐχώρει, σὺν φόβῳ μή τι πάθοιεν αἱ γυναῖκες· ἔς τε τὸν δῆμον τεθορυβημένον ἱππέας ἔπεμψεν ἀτρεμεῖν ἐπικελεύων, καὶ τεθηπότων πάντων τὰ πέραν τοῦ Κυριναλίου λόφου κατέλαβεν, οὐδενὸς ἐς χεῖρας ἐλθεῖν ἢ κωλύειν ὑποστάντος. ἦν τε αὖθις ἑτέρα θαυμάσιος ἄφνω μεταβολή, θεόντων ἐς αὐτὸν τῶν ἐπιφανῶν καὶ προσαγορευόντων· ἔθει δὲ καὶ ὁ δημότης λεὼς καὶ τὴν εὐταξίαν τῶν στρατιωτῶν ὡς εἰρηνικὴν ἀπεδέχοντο. ὁ δὲ τὸν στρατόν, ἔνθαπερ ἦν, ἀπολιπὼν ἐχώρει τῆς ἐπιούσης πρὸς τὸ ἄστυ, φυλακὴν ἔχων ἀμφ’ αὑτὸν ἱκανήν. οἱ δὲ καὶ τότε ὑπήντων δι’ ὅλης τῆς ὁδοῦ κατὰ μέρη καὶ προσηγόρευον, οὐδὲν ἐνδέοντες ἢ φιλοφροσύνης ἢ θεραπείας ἀσθενοῦς. ἡ δὲ μήτηρ αὐτοῦ καὶ ἡ ἀδελφὴ ἐν τῷ τῆς Ἑστίας ἱερῷ μετὰ τῶν ἱερῶν παρθένων ἠσπάσαντο. καὶ τὰ τρία τέλη, τῶν στρατηγῶν ὑπεριδόντα, πρὸς αὐτὸν ἐπρέσβευε καὶ μετετίθετο· καὶ τῶν στρατηγῶν οἳ ἦρχον αὐτῶν, Κορνοῦτος μὲν ἑαυτὸν ἔκτεινεν, οἱ δ’ ἄλλοι σπονδῶν καὶ πίστεων ἔτυχον. Κικέρων τε τῶν σπονδῶν πυθόμενος ἔπραξε διὰ τῶν Καίσαρος φίλων ἐντυχεῖν αὐτῷ, καὶ ἐντυχὼν ἀπελογεῖτο καὶ τὴν εἰσήγησιν τῆς ὑπατείας ὑπερεπῇρεν, ἣν αὐτὸς ἐν τῇ βουλῇ πρότερον εἰσηγήσατο. ὁ δὲ τοσοῦτον ἀπεκρίνατο ἐπισκώπτων ὅτι τῶν φίλων αὑτῷ τελευταῖος ἐντυγχάνοι.", "st": "3.92"}, {"sp": "N", "t": "νυκτὸς δ’ ἄφνω δόξης γενομένης, ὅτι δύο τέλη Καίσαρος, τό τε Ἄρειον καὶ τὸ τέταρτον, μεταθοῖτο ἐς τὴν πόλιν ὡς δι’ ἐνέδρας ἐπὶ τὴν πατρίδα ἐπαχθέντα, οἱ στρατηγοὶ καὶ ἡ βουλὴ πάμπαν ἀταλαιπώρως ἐπίστευσαν, καίπερ ὄντος ἐγγυτάτω τοῦ στρατοῦ· νομίσαντές τε ἀνθέξειν αὐτοῖς οὖσιν ἀρίστοις πρὸς τὰ λοιπὰ τοῦ Καίσαρος, μέχρι τις ἑτέρωθεν αὑτοῖς ἰσχὺς ἐπιγένοιτο, νυκτὸς ἔτι Μάνιον Ἀκύλιον Κράσσον ἐς τὴν Πικηνίτιδα ἐξέπεμπον στρατὸν ἀθροίζειν, καὶ τῶν τινα δημάρχων Ἀπουλήιον ἐς τὸν δῆμον ἐποίουν τὸ εὐαγγέλιον ἐκφέρειν περιθέοντα. ἥ τε βουλὴ νυκτὸς ἐς τὸ βουλευτήριον συνέθεον, Κικέρωνος ἐπὶ ταῖς θύραις αὐτοὺς δεξιουμένου. ψευδοῦς δὲ τῆς δόξης φανείσης ἐν φορείῳ διέφυγεν.", "st": "3.93"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ἐπιγελάσας αὐτοῖς τὸν μὲν στρατὸν ἐγγυτέρω τῆς πόλεως προήγαγεν, ἐς τὸ πεδίον τὸ καλούμενον Ἄρειον, τῶν δὲ στρατηγῶν τότε μὲν οὐδένα ἠμύνατο, οὐδὲ Κράσσον τὸν ἐς Πικήνην ἐκδραμόντα, καίπερ οἱ προσαχθέντα ὡς εἶχε ληφθεὶς ἐν σχήματι οἰκέτου, ἀλλὰ μεθῆκεν ἅπαντας ἐς δόξαν φιλανθρωπίας. οὐ πολὺ δὲ ὕστερον ἐπὶ θανάτῳ προυγράφησαν. τὰ χρήματα δέ, ὅσα τε κοινὰ ἦν ἐν τῷ Ἰανούκλῳ ἢ ἑτέρωθι καὶ ἄλλα συνενεχθῆναι κελεύσας, ὁπόσα Κικέρωνος ἐσηγουμένου πρότερον αὐτοῖς ἐπεγέγραπτο, διένειμεν ἀνὰ δισχιλίας καὶ πεντακοσίας δραχμὰς τῷ στρατῷ, καὶ τὸ ἐπίλοιπον ἐπιδώσειν ὑπέσχετο. καὶ τῆς πόλεως ὑπεξῆλθε, μέχρι χειροτονήσαιεν ὑπάτους αἱρετούς. αἱρεθεὶς δὲ αὐτὸς σὺν ᾧ περ ἐβούλετο Κοΐντῳ Πεδίῳ, ὃς τὸ μέρος αὐτῷ δεδώρητο τῆς Καίσαρος κληρονομίας, ἐς τὴν πόλιιαὖθις ὡς ὕπατος ἐσῄει, καὶ ἔθυε, δώδεκά οἱ γυπῶν φανέντων, ὅσους φασὶ καὶ Ῥωμύλῳ τὴν πόλιν οἰκίζοντι ὀφθῆναι. ἀπὸ δὲ τῶν θυσιῶν ἑαυτὸν εἰσεποιεῖτο τῷ πατρὶ αὖθις κατὰ νόμον κουριάτιον. ἔστι δ’ ἐπὶ τοῦ δήμου γίγνεσθαι τὴν θέσιν· κουρίας γὰρ ἐς μέρη τὰς φυλὰς ἢ τοὺς δήμους διαιροῦντες καλοῦσιν, ὡς Ἕλληνες, εἰκάζοντι φάναι, φατρίας. ἐπινομώτατος δ’ ἐστὶ Ῥωμαίοις ὁ τρόπος οὗτος ἐπὶ τῶν ἀπατόρων· καὶ δύνανται μάλιστα αὐτοὶ ἴσα τοῖς γνησίοις παισὶν ἄγειν τοὺς συγγενεῖς τῶν θεμένων καὶ ἀπελευθέρους. Γαΐῳ δ’ ἦν τά τε ἄλλα λαμπρὰ καὶ ἐξελεύθεροι πολλοί τε καὶ πλούσιοι, καὶ διὰ τόδ’ ἴσως μάλιστα ὁ Καῖσαρ ἐπὶ τῇ προτέρᾳ θέσει, κατὰ διαθήκας οἱ γενομένῃ, καὶ τῆσδε ἐδεήθη.", "st": "3.94"}, {"sp": "N", "t": "νόμῳ δ’ ἑτέρῳ ἀπέλυε μὴ εἶναι πολέμιον Δολοβέλλαν, καὶ εἶναι φόνου δίκας ἐπὶ Καίσαρι. καὶ εὐθὺς ἦσαν γραφαί, τῶν φίλων τοῦ Καίσαρος γραφομένων τοὺς μὲν αὐτόχειρας, τοὺς δὲ συνεγνωκέναι μόνον. καὶ γὰρ τοῦτο ἐνίοις ἐπεγράφη, καί τισιν οὐδ’ ἐπιδημήσασιν, ὅτε ὁ Καῖσαρ ἐκτείνετο. πᾶσι δ’ ὁρισθείσης ὑπὸ κηρύγματι μιᾶς ἡμέρας ἐς κρίσιν, ἐρήμην ἅπαντες ἑάλωσαν, ἐφορῶντος τὰ δικαστήρια τοῦ Καίσαρος καὶ τῶν δικαστῶν οὐδενὸς τὴν ἀπολύουσαν φέροντος πλὴν ἑνὸς ἀνδρὸς τῶν ἐπιφανῶν, ὃς τότε μὲν οὐδ’ αὐτός τι ἔπαθε, μικρὸν δ’ ὕστερον ἐπὶ θανάτῳ μετὰ τῶν ἄλλων καὶ ὅδε προυγράφη. ἔδοξε δὲ ταῖσδε ταῖς ἡμέραις Κόιντος Γάλλιος, ἀδελφὸς Μάρκου Γαλλίου συνόντος Ἀντωνίῳ, τὴν πολιτικὴν στρατηγίαν ἄρχων, αἰτῆσαι παρὰ Καίσαρος τὴν στρατηγίαν τῆς Λιβύης, καὶ οὕτω τυχὼν ἐπιβουλεῦσαι τῷ Καίσαρι· καὶ αὐτοῦ τὴν μὲν στρατηγίαν περιεῖλον οἱ σύναρχοι, τὴν δ’ οἰκίαν διήρπασεν ὁ δῆμος, ἡ δὲ βουλὴ κατεγίνωσκε θάνατον. ὁ δὲ Καῖσαρ ἐς τὸν ἀδελφὸν ἐκέλευσε χωρεῖν, καὶ δοκεῖ νεὼς ἐπιβὰς οὐδαμοῦ ἔτι φανῆναι.", "st": "3.95"}, {"sp": "N", "t": "τοσάδε πράξας ὁ Καῖσαρ ἐπενόει μὲν τὰς ἐς τὸν Ἀντώνιον διαλύσεις, πυνθανόμενος ἤδη τοῖς ἀμφὶ τὸν Βροῦτον εἴκοσι συνῆχθαι τέλη στρατοῦ, καὶ χρῄζων ἐπ’ αὐτὰ Ἀντωνίου, ἐξῄει δὲ τῆς πόλεως ἐπὶ τὸν Ἰόνιον καὶ σχολαίως ἀνεζεύγνυε, τὰ παρὰ τῆς βουλῆς ἐπιμένων· Πέδιος γὰρ αὐτὴν ἀποστάντος τοῦ Καίσαρος ἔπειθε τὰ ἐς ἀλλήλους μὴ δυσίατα ποιουμένους συναλλαγῆναι Λεπίδῳ τε καὶ Ἀντωνίῳ. οἱ δὲ προεώρων μὲν ὅτι μὴ σφίσι μηδ’ ὑπὲρ τῆς πατρίδος εἰσὶν αἱ διαλλαγαί, ἀλλ’ ἐς συμμαχίαν Καίσαρι κατὰ Κασσίου τε καὶ Βρούτου, ἐπῄνουν δ’ ὅμως καὶ συνετίθεντο ὑπ’ ἀνάγκης. καὶ τὰ πολέμια δόγματα Ἀντωνίου τε καὶ Λεπίδου καὶ τῶν ὑπ’ αὐτοῖς στρατῶν κατελύετο, εἰρηναῖα δὲ ἕτερα αὐτοῖς ἐπέμπετο. καὶ ὁ Καῖσαρ αὐτοῖς συνήδετο γράφων, Ἀντωνίῳ δὲ καὶ βοηθὸς ἐπὶ Δέκμου ὑπισχνεῖτο ἥξειν, εἰ δέοιτο. οἱ δὲ ἀντεφιλοφρονοῦντο μὲν αὐτὸν ἄφνω καὶ ἐπῄνουν, ὁ δ’ Ἀντώνιος ἔγραφεν αὐτὸς ἀποτίσεσθαι Δέκμον τε ὑπὲρ Καίσαρος καὶ Πλάγκον ὑπὲρ ἑαυτοῦ καὶ συμμίξειν Καίσαρι.", "st": "3.96"}, {"sp": "N", "t": "τοσάδε μὲν ἀλλήλοις ἐπέστειλαν, διώκοντι δὲ τῷ Ἀντωνίῳ Δέκμον προσγίγνεται Πολλίων Ἀσίνιος ἄγων δύο τέλη. καὶ Πλάγκῳ μὲν Ἀσίνιος ἔπραξε διαλλαγάς, καὶ ὁ Πλάγκος σὺν τρισὶ τέλεσι μεθίστατο ἐς τὸν Ἀτώνιον, ὥστε ἤδη βαρυτάτης δυνάμεως ἦρχεν ὁ Ἀντώνιος· Δέκμῳ δὲ ἦν τέλη δέκα, ὧν τέσσαρα μὲν τὰ ἐμπειροπολεμώτατα ὑπὸ λιμοῦ διέφθαρτο καὶ ἐνόσει ἔτι, τὰ νεοστράτευτα δὲ ἦν ἕξ, ἀταλαίπωρα ἔτι καὶ πόνων ἄπειρα. ἀπογνοὺς οὖν μάχεσθαι, φεύγειν ἔκρινε πρὸς Βροῦτον ἐς Μακεδονίαν. ἔφευγε δ’ οὐκ ἐπὶ τάδε τῶν Ἄλπεων, ἀλλ’ ἐς Ῥάβενναν ἢ Ἀκυληίαν. ἐπεὶ δὲ Καῖσαρ ὥδευε ταύτῃ, ἄλλην μακροτέραν ὁδὸν καὶ δύσπορον ἐπενόει, τόν τε Ῥῆνον περᾶσαι καὶ τὰ ἀγριώτερα τῶν βαρβάρων ὑπερελθεῖν· ὅθεν αὐτὸν ὑπό τε τῆς ἀπορίας καὶ τοῦ καμάτου πρῶτοι μὲν οἱ νεοστράτευτοι καταλιπόντες ἐς Καίσαρα ἐχώρουν, ἐπὶ δὲ ἐκείνοις καὶ τὰ ἀρχαιότερα τέσσαρα ἐς Ἀντώνιον καὶ ὁ ἄλλος ὅμιλος ἤδη χωρὶς τῶν σωματοφυλάκων ἱππέων Κελτῶν. ὁ δὲ καὶ τούτων τοῖς ἐθέλουσιν ἐπιτρέψας ἐς τὰ οἰκεῖα σφῶν ἀφίστασθαι καὶ διαδοὺς ἐκ τοῦ παρόντος ἔτι χρυσίου, μετὰ τριακοσίων τῶν παραμεινάντων μόνων ἐπὶ τὸν Ῥῆνον ἐφέρετο. δυσπόρου δ’ ὄντος αὐτοῦ περᾶν σὺν ὀλίγοις, ἀπελείφθη καὶ ὑπὸ τῶνδε πλὴν δέκα μόνων. ἤλλαξε δὲ τὴν ἐσθῆτα ἐς τὸ Κελτικόν, ἐξεπιστάμενος ἅμα καὶ τὴν φωνήν, καὶ διεδίδρασκε σὺν ἐκείνοις οἷά τις Κελτός, οὐ τὴν μακροτέραν ἔτι περιιών, ἀλλὰ ἐπὶ Ἀκυληίας, λήσεσθαι νομίζων διὰ τὴν ὀλιγότητα.", "st": "3.97"}, {"sp": "N", "t": "ἁλοὺς δὲ ὑπὸ λῃστῶν καὶ δεθείς, ἤρετο μὲν ὅτου Κελτῶν δυνάστου τὸ ἔθνος εἴη, μαθὼν δ’ ὅτι Καμίλου, πολλὰ πεποιηκὼς εὖ τὸν Κάμιλον, ἄγειν αὑτὸν αὐτοῖς ἐς τὸν Κάμιλον ἐκέλευεν. ὁ δὲ ἀχθέντα ἰδὼν ἐφιλοφρονεῖτο μὲν ἐς τὸ φανερὸν καὶ τοῖς δήσασιν ἐπεμέμφετο ὑπ’ ἀγνοίας ἐνυβρίσασιν ἀνδρὶ τοσῷδε, κρύφα δ’ ἐπέστελλεν Ἀντωνίῳ. καὶ ὁ Ἀντώνιός τι παθὼν ἐπὶ τῇ μεταβολῇ οὐχ ὑπέστη τὸν ἄνδρα ἰδεῖν, ἀλλ’ ἐκέλευσε τῷ Καμίλῳ κτείναντα τὴν κεφαλὴν ἐς αὑτὸν ἐκπέμψαι· καὶ τὴν κεφαλὴν ἰδὼν ἐκέλευσε τοῖς παροῦσι θάψαι. τοῦτο Δέκμῳ τέλος ἦν, ἱππάρχῃ τε Καίσαρος γενομένῳ καὶ ἄρξαντι τῆς παλαιᾶς Κελτικῆς ὑπ’ ἐκείνῳ καὶ ἐς τὸ μέλλον ἔτος ὑπατεύειν ὑπ’ αὐτοῦ κεχειροτονημένῳ καὶ τῆς ἑτέρας Κελτικῆς ἄρχειν. καὶ δεύτερος τῶν σφαγέων οὗτος ἐπὶ Τρεβωνίῳ δίκην ἐδίδου μετ’ ἐνιαυτόν που καὶ ἥμισυ τῆς ἀναιρέσεως. τῷ δ’ αὐτῷ χρόνῳ καὶ Μινούκιος Βάσιλος, σφαγεὺς καὶ ὅδε Καίσαρος, ὑπὸ τῶν θεραπόντων ἀνῃρέθη, εὐνουχίζων τινὰς αὐτῶν ἐπὶ τιμωρίᾳ.", "st": "3.98"}, {"sp": "HDR", "t": "Ἐμφυλίων Δʹ", "st": "4"}, {"sp": "N", "t": "δύο μὲν δὴ Γαΐου Καίσαρος φονεῖς οὕτω δίκην, ἐν ταῖς σφετέραις αὐτῶν στρατηγίαις ἐκπολεμηθέντες, ἐδεδώκεσαν, Τρεβώνιος ἐν τῇ Ἀσίᾳ καὶ Δέκμος ἐν τῇ Κελτικῇ· ὅπως δὲ ἔδοσαν Κάσσιός τε καὶ Βροῦτος, οἳ καὶ μάλιστα τῆς ἐπιβουλῆς ἐπὶ τῷ Καίσαρι ἦρξαν, καὶ γῆς ἐκράτουν ἀπὸ Συρίας ἐπὶ Μακεδονίαν ἁπάσης, καὶ στρατὸς ἦν αὐτοῖς πολύς, ἱππικός τε καὶ ναυτικὸς καὶ ὁπλιτῶν ὑπὲρ εἴκοσι τέλη, καὶ νῆες ὁμοῦ καὶ χρήματα, ἡ τετάρτη τῶν ἐμφυλίων ἥδε ὑποδείκνυσιν. ἅμα δὲ τούτοις ἐγίγνοντο αἱ ἐν Ῥώμῃ τῶν ἐπὶ θανάτῳ προγραφέντων ἔρευναί τε καὶ εὑρέσεις καὶ παθήματα πάμπαν ἐπαχθῆ, οἷα οὔτε ἐπὶ Ἑλλήνων ἐν στάσεσιν ἢ πολέμοις οὔτ’ ἐπὶ Ῥωμαίων αὐτῶν ἐμνημονεύετο γενέσθαι, πλὴν ἐπὶ μόνου Σύλλα τοῦ πρώτου τοὺς ἐχθροὺς ἐς θάνατον προγράψαντος. Μάριος μὲν γὰρ ἐζήτει καὶ ἐκόλαζεν, οὓς εὕροι· Σύλλας δὲ ὑπὸ μισθοῖς τε μεγάλοις καὶ κολάσεσι τῶν ἐπικρυψάντων ὁμοίαις τὸν ἐντυχόντα κτείνειν προέγραφεν. καὶ τὰ μὲν ἀμφὶ Μάριόν τε καὶ Σύλλαν ἐν τοῖς περὶ ἐκείνων προείρηται, τὰ δὲ ἑξῆς οὕτως ἐγένετο.", "st": "4.1"}, {"sp": "N", "t": "Καῖσαρ μὲν καὶ Ἀντώνιος ἐς φιλίαν ἀπ’ ἔχθρας συνῄεσαν ἀμφὶ Μουτίνην πόλιν, ἐς νησῖδα τοῦ Λαβινίου ποταμοῦ βραχεῖάν τε καὶ ὑπτίαν, ἔχων ἑκάτερος ὁπλιτῶν τέλη πέντε· καὶ τάδε ἀλλήλοις ἀντικαθιστάντες ἐχώρουν σὺν τριακοσίοις ἑκάτερος ἐπὶ τὰς τοῦ ποταμοῦ γεφύρας. Λέπιδος δ’ αὐτὸς προελθὼν διηρεύνα τὴν νῆσον καὶ τῇ χλαμύδι κατέσειεν ἥκειν ἑκάτερον. οἱ δὲ ἐπὶ τῶν γεφυρῶν τοὺς τριακοσίους μετὰ τῶν φίλων ἀπολιπόντες ἐς τὸ μέσον ᾔεσαν ἐν περιόπτῳ, καὶ συνήδρευον οἱ τρεῖς, Καίσαρος ἐν μέσῳ διὰ τὴν ἀρχὴν προκαθίσαντος. δύο δὲ ἡμέραις ἕωθεν ἐς ἑσπέραν συνιόντες τάδε ἔκριναν· ἀποθέσθαι μὲν τὴν ὕπατον ἀρχὴν Καίσαρα καὶ Οὐεντίδιον αὐτὴν ἐς τὸ λοιπὸν τοῦ ἔτους μεταλαβεῖν, καινὴν δὲ ἀρχὴν ἐς διόρθωσιν τῶν ἐμφυλίων νομοθετηθῆναι Λεπίδῳ τε καὶ Ἀντωνίῳ καὶ Καίσαρι, ἣν ἐπὶ πενταετὲς αὐτοὺς ἄρχειν, ἴσον ἰσχύουσαν ὑπάτοις· ὧδε γὰρ ἔδοξεν ἀντὶ δικτατόρων ὀνομάσαι, διὰ τὸ δόγμα ἴσως τὸ Ἀντωνίου κωλῦον ἔτι γίγνεσθαι δικτάτορα. τοὺς δὲ ἀποφῆναι μὲν αὐτίκα τῆς πόλεως ἄρχοντας ἐς τὰ ἐτήσια ἐπὶ τὴν πενταετίαν, τὰς δὲ ἡγεμονίας τῶν ἐθνῶν νειμαμένους, ἔχειν Ἀντώνιον μὲν τὴν Κελτικὴν ἅπασαν ἄνευ τῆς συναφοῦς τοῖς Πυρηναίοις ὄρεσιν, ἣν παλαιὰν ἐκάλουν Κελτικήν· ταύτης δὲ Λέπιδον ἄρχειν καὶ Ἰβηρίας ἐπὶ ταύτῃ· Καίσαρι δὲ εἶναι Λιβύην καὶ Σαρδὼ καὶ Σικελίαν καὶ εἴ τις ἄλλη νῆσος ἐνταῦθα.", "st": "4.2"}, {"sp": "N", "t": "ὧδε μὲν τὴν Ῥωμαίων ἡγεμονίαν οἱ τρεῖς ἐνείμαντο ἐφ’ ἑαυτοῖς, τὰ πέραν ἄρα τοῦ Ἰονίου μόνα ὑπερθέμενοι διὰ Βροῦτον καὶ Κάσσιον κρατοῦντας ἔτι αὐτῶν, Κασσίῳ δὲ καὶ Βρούτῳ πολεμεῖν Ἀντώνιόν τε καὶ Καίσαρα· Λέπιδον γὰρ ὑπατεύειν ἐς τὸ μέλλον καὶ τῇ πόλει διὰ τὰς ἐν αὐτῇ χρείας ὑπομένειν, ἡγεμονεύοντα τῆς Ἰβηρίας δι’ ἑτέρων· τοῦ δὲ Λεπίδου στρατοῦ τρία μὲν αὐτὸν Λέπιδον ἔχειν ἐς τὰ ἐπὶ Ῥώμης, ἑπτὰ δὲ τέλη νείμασθαι Καίσαρα καὶ Ἀντώνιον, τρία μὲν Καίσαρα, τέσσαρα δὲ Ἀντώνιον, ὡς ἂν ἐς τὸν πόλεμον αὐτῶν ἑκάτερος εἴκοσιν ἄγοι. ἐπελπίσαι δὲ ἤδη τὸν στρατὸν ἐς τὰ νικητήρια τοῦ πολέμου, ἄλλαις τε δωρεαῖς καὶ ἐς κατοικίαν δόσεσι τῶν Ἰταλικῶν πόλεων ὀκτωκαίδεκα, αἳ καὶ περιουσίᾳ καὶ ἐδάφεσι καὶ οἴκοις εἰς κάλλος διαφέρουσαι ἔμελλον αὐτοῖς ἐδάφεσι καὶ οἴκοις αὐτῷ διανεμήσεσθαι, ὥσπερ αὐτοῖς ἀντὶ τῆς πολεμίας δορίληπτοι γενόμεναι. καὶ ἦσαν αἱ πόλεις ἄλλαι τε καὶ αἱ περιφανέσταται μάλιστα αὐτῶν Καπύη καὶ Ῥήγιον καὶ Οὐενουσία καὶ Βενεβεντὸς καὶ Νουκερία καὶ Ἀρίμινον καὶ Ἰππώνιον. οὕτω μὲν τὰ κάλλιστα τῆς Ἰταλίας τῷ στρατῷ διέγραφον, ἔδοξε δὲ σφίσι καὶ τοὺς ἰδίους ἐχθροὺς προανελεῖν, ἵνα μὴ ἐνοχλοῖεν αὑτοῖς τάδε καθισταμένοις καὶ πολεμοῦσι πόλεμον ἔκδημον. ταῦτα μὲν ἔδοξε, καὶ ταῦτα συνεγράψαντο· καὶ αὐτῶν ὁ Καῖσαρ ὡς ὕπατος ἀνέγνω τοῖς στρατοῖς τὰ λοιπὰ χωρὶς τῶν ἀποθανουμένων. οἱ δ’ ἀκούσαντες ἐπαιώνισάν τε καὶ ἠσπάσαντο ἀλλήλους ἐπὶ διαλλαγῇ.", "st": "4.3"}, {"sp": "N", "t": "γιγνομένων δὲ τούτων τέρατα καὶ σημεῖα ἐν Ῥώμῃ πολλὰ καὶ φοβερὰ ἦν. κύνες τε γὰρ ὠρύοντο ὁμαλῶς οἷα λύκοι, σύμβολον ἀηδές, καὶ λύκοι τὴν ἀγορὰν διέθεον, οὐκ ἐπιχωριάζον ἐν πόλει ζῷον, βοῦς τε φωνὴν ἀφῆκεν ἀνθρώπου, καὶ βρέφος ἀρτίτοκον ἐφθέγξατο, καὶ τῶν ξοάνων τὰ μὲν ἵδρου, τὰ δὲ καὶ αἷμα ἵδρου, ἀνδρῶν τε μεγάλαι βοαὶ καὶ κτύπος ὅπλων καὶ δρόμος ἵππων οὐχ ὁρωμένων ἠκούετο. ἀμφί τε τὸν ἥλιον ἀηδῆ σημεῖα πολλά, καὶ λιθώδεις ἐγίγνοντο ὑετοί, καὶ κεραυνοὶ συνεχεῖς ἐς ἱερὰ καὶ ἀγάλματα ἔπιπτον. ἐφ’ οἷς ἡ μὲν βουλὴ θύτας καὶ μάντεις συνῆγεν ἀπὸ Τυρρηνίας· καὶ ὁ πρεσβύτατος αὐτῶν, τὰς πάλαι βασιλείας ἐπανήξειν εἰπών, καὶ δουλεύσειν ἅπαντας χωρὶς ἑαυτοῦ μόνου, τὸ στόμα κατέσχε καὶ τὸ πνεῦμα, ἕως ἀπέθανεν.", "st": "4.4"}, {"sp": "N", "t": "οἱ δὲ τρεῖς ἄνδρες ἐφ’ ἑαυτῶν γενόμενοι τοὺς ἀποθανουμένους συνέγραφον, τούς τε δυνατοὺς ὑφορώμενοι καὶ τοὺς ἰδίους ἐχθροὺς καταλέγοντες, οἰκείους τε σφῶν αὐτῶν ἢ φίλους ἐς τὴν ἀναίρεσιν ἀντιδιδόντες ἀλλήλοις καὶ τότε καὶ ὕστερον. προσκατελέγοντο γὰρ δὴ καὶ ἕτεροι μεθ’ ἑτέρους, οἱ μὲν ἀπ’ ἔχθρας, οἱ δὲ μόνου προσκρούματος ἢ φιλίας ἐχθρῶν ἢ φίλων ἔχθρας ἢ πλούτου διαφέροντος. ἐδέοντο γὰρ ἐς τὸν πόλεμον χρημάτων πολλῶν, Βρούτῳ μὲν καὶ Κασσίῳ τῶν ἀπὸ τῆς Ἀσίας φόρων δεδομένων τε καὶ προσοδευομένων ἔτι καὶ βασιλέων καὶ σατραπῶν συμφερόντων, αὐτοὶ δ’ ἐπὶ τῆς Εὐρώπης καὶ μάλιστα τῆς Ἰταλίας πολέμοις τε καὶ εἰσφοραῖς τετρυμένης ἀποροῦντες· δι’ ἃ καὶ τοῖς δημόταις καὶ ταῖς γυναιξὶ λήγοντες ἐπέγραψαν εἰσφορὰς βαρυτάτας, καὶ τέλη πράσεων καὶ μισθώσεων ἐπενόησαν. ἤδη δέ τις καὶ διὰ κάλλος ἐπαύλεως καὶ οἰκίας προεγράφη. καὶ ἐγένοντο πάντες οἱ θανάτου τε καὶ δημεύσεως κατεγνωσμένοι ἀπὸ μὲν τῆς βουλῆς ἀμφὶ τοὺς τριακοσίους, ἀπὸ δὲ τῶν καλουμένων ἱππέων ἐς δισχιλίους. καὶ ἦσαν ἐν αὐτοῖς ἀδελφοί τε καὶ θεῖοι τῶν προγραφόντων, καὶ τῶν ὑπ’ αὐτοῖς ἡγεμόνων, ὅσοι τι τοῖς ἄρχουσιν ἢ τοῖς ἡγεμόσι προσεκεκρούκεσαν.", "st": "4.5"}, {"sp": "N", "t": "τὸ μὲν δὴ πλῆθος αὐτῶν ἀπὸ τῆς συνόδου διελθόντες ἐς Ῥώμην προγράψειν ἔμελλον, δυώδεκα δὲ ἄνδρας, ἤ, ὡς ἕτεροι λέγουσιν, ἑπτακαίδεκα, τοὺς μάλιστα δυνατούς, ἐν οἷς ἦν καὶ Κικέρων, ἔδοξε προανελεῖν ἐπιπέμψαντας ἄφνω. καὶ τῶνδε μὲν τέσσαρες αὐτίκα ἀνῃρέθησαν ἐν ἑστιάσεσί τε καὶ ὑπαντήσεσι· ζητουμένων δὲ τῶν ἄλλων καὶ ἐρευνωμένων νεών τε καὶ οἰκιῶν, ἄφνω θόρυβος ἀνὰ τὴν νύκτα πᾶσαν ἦν καὶ βοαὶ καὶ διαδρομαὶ μετ’ οἰμωγῆς ὡς ἐν ἁλισκομένῃ πόλει. τῷ γὰρ ἐγνῶσθαι μὲν ἀνδρολήψια γίγνεσθαι, μὴ προγεγράφθαι δὲ μηδένα τῶν προκατεγνωσμένων, πᾶς τις αὐτὸς ἡγεῖτο ζητεῖσθαι πρὸς τῶν περιθεόντων. οὕτω δὲ ἀπογινώσκοντες αὑτῶν, οἱ μὲν τὰ ἴδια, οἱ δὲ τὰ κοινὰ ἐμπρήσειν ἔμελλον, δρᾶσαί τι δεινὸν ἀλόγως αἱρούμενοι πρὶν παθεῖν· καὶ τάχα ἂν ἔδρασαν, εἰ μὴ Πέδιος αὐτοὺς ὁ ὕπατος μετὰ κηρύκων περιθέων ἐπήλπιζε περιμείναντας ἐς ἕω τὰ ἀκριβέστατα μαθεῖν. ἅμα δὲ ἕῳ παρὰ γνώμην τῶν τριῶν ἀνδρῶν προύγραφεν ὁ Πέδιος τοὺς ἑπτακαίδεκα ὡς μόνους τε αἰτίους δόξαντας εἶναι τῶν ἐμφυλίων κακῶν καὶ μόνους κατεγνωσμένους, πίστεις τε τοῖς ἄλλοις δημοσίας ἐποιεῖτο, ἀγνοῶν τὰ ἐγνωσμένα.", "st": "4.6"}, {"sp": "N", "t": "καὶ Πέδιος μὲν ἐκ καμάτου τῆς νυκτὸς ἐτελεύτησεν, ἐσῄεσαν δ’ οἱ τρεῖς τρισὶν ἡμέραις, ἀνὰ μέρος ἕκαστος αὐτῶν, ὁ Καῖσάρ τε καὶ ὁ Ἀντώνιος καὶ ὁ Λέπιδος, σὺν ταῖς στρατηγίσι τάξεσι καὶ ὁπλιτῶν ἕκαστος ἑνὶ τέλει. ὡς δὲ ἐσῆλθον, αὐτίκα μὲν ἡ πόλις ἦν πλήρης ὅπλων τε καὶ σημείων διατεταγμένων ἐς τὰ ἐπίκαιρα, αὐτίκα δὲ ἐν μέσῳ τούτων ἤγετο ἐκκλησία, καὶ δήμαρχος Πούπλιος Τίτιος ἐνομοθέτει καινὴν ἀρχὴν ἐπὶ καταστάσει τῶν παρόντων ἐς πενταετὲς εἶναι τριῶν ἀνδρῶν, Λεπίδου τε καὶ Ἀντωνίου καὶ Καίσαρος, ἴσον ἰσχύουσαν ὑπάτοις, (ἣν ἄν τις Ἑλλήνων ἁρμοστὰς ὀνομάσειεν, ὃ καὶ Λακεδαιμόνιοι τοῖς ἄρτι καθισταμένοις τὰ ὑπήκοα ἐτίθεντο ὄνομα,) οὔτε διαστήματος ἐς δοκιμασίαν οὔτε κυρίας ἐς τὴν χειροτονίαν ἡμέρας προτεθείσης· ἀλλ’ αὐτίκα ἐκυροῦτο ὁ νόμος. καὶ νυκτὸς ἄλλων, ἐπὶ τοῖς ἑπτακαίδεκα, τριάκοντα καὶ ἑκατὸν ἀνδρῶν προγραφαὶ κατὰ πολλὰ τῆς πόλεως προυτίθεντο καὶ μετ’ ὀλίγον ἄλλων πεντήκοντα καὶ ἑκατόν. καί τις προσετίθετο τοῖς πίναξιν αἰεὶ τῶν προσκαταγινωσκομένων ἢ τῶν προανῃρημένων ὑπ’ ἀγνοίας, ἐς δόξαν τοῦ δικαίως ἀνῃρῆσθαι. διετέτακτό τε πάντων τὰς κεφαλὰς ἐς τοὺς τρεῖς ἄνδρας ἐπὶ ῥητῷ κέρδει φέρεσθαι· καὶ ἦν τὸ κέρδος ἐλευθέρῳ μὲν ἀργύριον, θεράποντι δὲ ἐλευθερία τε καὶ ἀργύριον. παρέχειν δὲ ἐς ἔρευναν πάντας τὰ ἴδια. καὶ τὸν ὑποδεξάμενον ἢ κρύψαντα ἢ τὴν ἔρευναν οὐ παρασχόντα τοῖς ἴσοις ἐνέχεσθαι. μηνύειν δὲ ἕκαστα τούτων τὸν ἐθέλοντα ἐπὶ τοῖς ἴσοις κέρδεσι.", "st": "4.7"}, {"sp": "N", "t": "καὶ εἶχεν οὕτως ἡ προγραφή·", "st": "4.8"}, {"sp": "N", "t": "“Μᾶρκος Λέπιδος, Μᾶρκος Ἀντώνιος, Ὀκτάουιος Καῖσαρ, οἱ χειροτονηθέντες ἁρμόσαι καὶ διορθῶσαι τὰ κοινά, οὕτως λέγουσιν· εἰ μὴ δι’ ἀπιστίαν οἱ πονηροὶ δεόμενοι μὲν ἦσαν ἐλεεινοί, τυχόντες δὲ ἐγίγνοντο τῶν εὐεργετῶν ἐχθροί, εἶτα ἐπίβουλοι, οὔτ’ ἂν Γάιον Καίσαρα ἀνῃρήκεσαν, οὓς ἐκεῖνος δορὶ λαβὼν ἔσωσεν ἐλέῳ καὶ φίλους θέμενος ἐπὶ ἀρχὰς καὶ τιμὰς καὶ δωρεὰς προήγαγεν ἀθρόως, οὔτ’ ἂν ἡμεῖς τοῖς ἐνυβρίσασι καὶ πολεμίους ἀναγράψασιν ἡμᾶς ὧδε ἀθρόως ἠναγκαζόμεθα χρῆσθαι. νῦν δέ, ἐξ ὧν ἐπιβεβουλεύμεθα καὶ ἐξ ὧν Γάιος Καῖσαρ ἔπαθεν, ἀτιθάσευτον ὁρῶντες τὴν κακίαν ὑπὸ φιλανθρωπίας, προλαβεῖν τοὺς ἐχθροὺς ἢ παθεῖν αἱρούμεθα. μὴ δή τις τὸ ἔργον ἄδικον ἢ ὠμὸν ἢ ἄμετρον ἡγείσθω, ἔς τε Γάιον καὶ ἐς ἡμᾶς οἷα πεπόνθαμεν ὁρῶν. Γάιον μὲν δὴ καὶ αὐτοκράτορα ὄντα καὶ ἄρχοντα ἱερῶν, καὶ τὰ φοβερώτατα Ῥωμαίοις καθελόντα τε ἔθνη καὶ κτησάμενον, καὶ πρῶτον ἀνδρῶν ὑπὲρ τοὺς Ἡρακλείους ὅρους ἀπλώτου θαλάσσης ἀποπειράσαντα, καὶ Ῥωμαίοις γῆν ἄγνωστον εὑρόντα, ἐν μέσῳ τῷ ἱερῷ λεγομένῳ βουλευτηρίῳ, ὑπὸ ὄψεσι θεῶν, κατέκανον εἴκοσι καὶ τρισὶ σφαγαῖς ἐνυβρίσαντες, οἱ πολέμῳ ληφθέντες ὑπ’ ἐκείνου καὶ περισωθέντες κληρονόμοι τέ τινες αὐτοῦ τῆς οὐσίας ἐγγραφέντες εἶναι· οἱ λοιποὶ δὲ ἐπὶ τῷ μύσει τῷδε τοὺς ἐναγεῖς ἀντὶ κολάσεων ἐπὶ ἀρχὰς καὶ ἡγεμονίας ἐξέπεμψαν, αἷς ἐκεῖνοι χρώμενοι τά τε κοινὰ τῶν χρημάτων ἥρπασαν, καὶ στρατὸν ἐξ αὐτῶν ἀγείρουσι καθ’ ἡμῶν καὶ ἕτερον αἰτοῦσι παρὰ βαρβάρων ἀεὶ τῆς ἀρχῆς πολεμίων, τάς τε ὑπὸ Ῥωμαίοις πόλεις τὰς μὲν οὐ πείθοντες ἐνέπρησαν ἢ κατέσκαψαν ἢ κατήρειψαν, τὰς δὲ καταπλήξαντες ἐπάγουσι τῇ πατρίδι καθ’ ἡμῶν.", "st": "4.8"}, {"sp": "N", "t": "“ἡμεῖς δὲ αὐτῶν τοὺς μὲν ἤδη τετιμωρήμεθα, τοὺς δὲ λοιποὺς θεοῦ συνεπιλαμβάνοντος αὐτίκα δίκην διδόντας ὄψεσθε. τῶν δὲ μεγίστων ἡμῖν ἠνυσμένων καὶ ὑπὸ χερσὶν ὄντων, Ἰβηρίας τε καὶ Κελτικῆς καὶ τῶνδε τῶν οἴκοι, ἕν ἐστι λοιπὸν ἔτι ἔργον, στρατεύειν ἐπὶ τοὺς πέραν θαλάσσης αὐτόχειρας Γαΐου. μέλλουσι δὴ πόλεμον ὑπὲρ ὑμῶν ἔκδημον ἀγωνιεῖσθαι οὐκ ἀσφαλὲς οὔτε ἐς τὰ ἡμέτερα οὔτε ἐς τὰ ὑμέτερα εἶναι δοκεῖ τοὺς ἄλλους ἐχθροὺς ὀπίσω καταλιπεῖν, ἐπιβησομένους ταῖς ἀπουσίαις ἡμῶν καὶ τὰ συμβαίνοντα τοῦ πολέμου καιροφυλακήσοντας, οὐδ’ αὖ βραδύνειν διὰ τούσδε ἐν ἐπείξει τοσῇδε μᾶλλον ἢ ἐκποδὼν αὐτοὺς ἀθρόως ποιήσασθαι, ἄρξαντάς γε τοῦ καθ’ ἡμῶν πολέμου, ὅτε πολεμίους ἡμᾶς τε καὶ τοὺς ὑφ’ ἡμῖν στρατοὺς ἐψηφίζοντο εἶναι.", "st": "4.9"}, {"sp": "N", "t": "“κἀκεῖνοι μὲν τοσάσδε πολιτῶν μυριάδας ἡμῖν συναπώλλυον, οὔτε θεῶν νέμεσιν οὔτε φθόνον ἀνθρώπων ὑφορώμενοι· ἡμεῖς δὲ πλήθει μὲν οὐδενὶ χαλεπανοῦμεν οὐδὲ τοὺς ἐχθροὺς ἐπιλεξόμεθα πάντας, ὅσοι διηνέχθησαν ἡμῖν ἢ ἐπεβούλευσαν, οὐδὲ ἐκ πλούτου πάντως ἢ περιουσίας ἢ ἀξιώσεως οὐδ’ ὅσους ἕτερος πρὸ ἡμῶν αὐτοκράτωρ ἔκτεινε, τὴν πόλιν κἀκεῖνος ἐν ἐμφυλίοις καθιστάμενος, ὃν Εὐτυχῆ προσείπατε δι’ εὐπραξίαν, καίπερ ἀνάγκης οὔσης τρισὶ πλέονας ἐχθροὺς ἢ ἑνὶ εἶναι. ἀλλὰ μόνους δὴ τοὺς φαυλοτάτους τε καὶ πάντων αἰτιωτάτους ἀμυνούμεθα. καὶ τόδε δι’ ὑμᾶς οὐχ ἧσσον ἡμῶν· ἀνάγκη μὲν γὰρ ἡμῶν διαφερομένων ὑμᾶς πάντας ἐν μέσῳ δεινὰ πάσχειν, ἀνάγκη δέ τι καὶ τῷ στρατῷ γενέσθαι παραμύθιον ὑβρισμένῳ τε καὶ παρωξυμμένῳ καὶ πολεμίῳ πρὸς τῶν κοινῶν ἐχθρῶν ἀναγεγραμμένῳ. δυνηθέντες δ’ ἄν, οὓς ἔγνωμεν, ἐξ ἐφόδου συλλαβεῖν, αἱρούμεθα προγράψαι μᾶλλον ἢ ἀγνοοῦντας ἔτι συλλαβεῖν· καὶ τόδε δι’ ὑμᾶς, ἵνα μὴ ἐπὶ τοῖς ὁπλίταις ᾖ διωργισμένοις πλεονάζειν ἐς τοὺς ἀνευθύνους, ἀλλὰ ἀπηριθμημένους καὶ ὡρισμένους ἔχοντες ὀνομαστὶ τῶν ἄλλων κατὰ πρόσταγμα ἀπέχωνται.", "st": "4.10"}, {"sp": "N", "t": "“ἀγαθῇ τύχῃ τοίνυν τῶν ὑπογεγραμμένων τῷδε τῷ διαγράμματι μηδεὶς δεχέσθω μηδένα μηδὲ κρυπτέτω μηδὲ ἐκπεμπέτω ποι μηδὲ πειθέσθω χρήμασι. ὃς δ’ ἂν ἢ σώσας ἢ ἐπικουρήσας ἢ συνειδὼς φανῇ, τοῦτον ἡμεῖς, οὐδεμίαν ὑπολογισάμενοι πρόφασιν ἢ συγγνώμην, ἐν τοῖς προγεγραμμένοις τιθέμεθα. ἀναφερόντων δὲ τὰς κεφαλὰς οἱ κτείναντες ἐφ’ ἡμᾶς, ὁ μὲν ἐλεύθερος ἐπὶ δισμυρίαις δραχμαῖς Ἀττικαῖς καὶ πεντακισχιλίαις ὑπὲρ ἑκάστης, ὁ δὲ δοῦλος ἐπ’ ἐλευθερίᾳ τοῦ σώματος καὶ μυρίαις Ἀττικαῖς καὶ τῇ τοῦ δεσπότου πολιτείᾳ. τὰ δ’ αὐτὰ καὶ τοῖς μηνύουσιν ἔσται. καὶ τῶν λαμβανόντων οὐδεὶς ἐγγεγράψεται τοῖς ὑπομνήμασιν ἡμῶν, ἵνα μὴ κατάδηλος ᾖ.”", "st": "4.11"}, {"sp": "N", "t": "ὧδε μὲν εἶχεν ἡ προγραφὴ τῶν τριῶν ἀνδρῶν, ὅσον ἐς Ἑλλάδα γλῶσσαν ἀπὸ Λατίνης μεταβαλεῖν.", "st": "4.11"}, {"sp": "N", "t": "πρῶτος δ’ ἦν ἐν τοῖς προγράφουσι Λέπιδος, καὶ πρῶτος ἐν τοῖς προγραφομένοις ὁ ἀδελφὸς ὁ Λεπίδου Παῦλος, καὶ δεύτερος ἦν τῶν προγραφόντων Ἀντώνιος καὶ δεύτερος τῶν προγραφομένων ὁ θεῖος ὁ Ἀντωνίου Λεύκιος, οἵδε μέν, ὅτι πρῶτοι πολεμίους αὐτοὺς ἐψηφίσαντο. τρίτος δὲ καὶ τέταρτος ἦν τῶν ἐν ἑτέρῳ πίνακι προκειμένων ἐς τὸ μέλλον ὑπάτων Πλάγκου μὲν ὁ ἀδελφὸς Πλώτιος, Ἀσινίου δὲ ὁ πενθερὸς Κοΐντιος. καὶ οὐ κατ’ ἀξίωσιν ἄρα μόνην οἵδε τῶν ἄλλων προύκειντο μᾶλλον ἢ ἐς θάμβος καὶ δυσελπιστίαν, μηδένα ῥύσεσθαί τινα προσδοκᾶν. ἦν δὲ καὶ Θωράνιος ἐν τοῖς προγεγραμμένοις, λεγόμενος ὑπό τινων ἐπιτροπεῦσαι Καίσαρος. ἅμα δὲ ταῖς προγραφαῖς αἵ τε πύλαι κατείχοντο καὶ ὅσαι ἄλλαι τῆς πόλεως ἔξοδοί τε καὶ λιμένες ἢ ἕλη καὶ τέλματα ἢ εἴ τι ἄλλο ἐς φυγὴν ὕποπτον ἦν ἢ ἐς λαθραίους καταφυγάς· τήν τε χώραν ἐπετέτραπτο τοῖς λοχαγοῖς ἐρευνᾶν περιθέουσι, καὶ ἐγίγνετο πάντα ὁμοῦ.", "st": "4.12"}, {"sp": "N", "t": "εὐθὺς οὖν ἦν ἀνά τε τὴν χώραν καὶ ἀνὰ τὴν πόλιν, ὡς ἕκαστός πῃ συνελαμβάνετο, ἀνδρολήψια αἰφνίδια πολλὰ καὶ τρόποι τῶν φόνων ποικίλοι τῶν τε κεφαλῶν ἀποτομαὶ τοῦ μισθοῦ χάριν ἐς ἐπίδειξιν φυγαί τε ἀπρεπεῖς καὶ σχήματα ἄτοπα ἐκ τοῦ πρὶν περιφανοῦς. κατέδυνον γὰρ οἱ μὲν ἐς φρέατα, οἱ δὲ ἐς τὰς ὑπονόμους τάφρους ἐπὶ τὰ ἀκάθαρτα, οἱ δὲ ἐς καπνώδεις ὑπωροφίας ἢ τῶν τεγῶν ταῖς κεραμίσι βυομέναις ὑπεκάθηντο μετὰ σιγῆς βαθυτάτης. ἐδεδοίκεσαν γὰρ οὐχ ἧσσον τῶν σφαγέων οἱ μὲν γυναῖκας ἢ παῖδας οὐκ εὐμενῶς σφίσιν ἔχοντας, οἱ δὲ ἐξελευθέρους τε καὶ θεράποντας, οἱ δὲ καὶ δανεισμάτων χρήστας ἢ χωρίων γείτονας ἐπιθυμίᾳ τῶν χωρίων. ἐπανάστασις γὰρ δὴ πάντων, ὅσα τέως ὕπουλα ἦν, ἀθρόα τότε ἐγίγνετο καὶ ἀθέμιστος μεταβολὴ βουλευτῶν ἀνδρῶν, ὑπάτων ἢ στρατηγῶν ἢ δημάρχων, ἔτι τάσδε τὰς ἀρχὰς μετιόντων ἢ ἐν αὐταῖς γεγονότων, ἐς πόδας ἰδίου θεράποντος ῥιπτουμένων σὺν ὀλοφύρσεσι καὶ σωτῆρα καὶ κύριον τὸν οἰκέτην τιθεμένων. οἴκτιστον δὲ ἦν, ὅτε καὶ ταῦτα ὑποστάντες οὐκ ἐλεηθεῖεν.", "st": "4.13"}, {"sp": "N", "t": "ἰδέα τε πᾶσα κακῶν ἦν, οὐχ ὡς ἐν στάσεσιν ἢ πολέμου καταλήψεσιν· οὐ γάρ, ὡς ἐν ἐκείνοις, τὸν μὲν ἀντιστασιώτην ἢ πολέμιον ἐδεδοίκεσαν, τοῖς δ’ οἰκείοις σφᾶς ἐπέτρεπον, ἀλλὰ καὶ τούσδε τῶν σφαγέων μᾶλλον ἐδεδοίκεσαν, οὐδὲν μὲν αὐτοὺς ὡς ἐν πολέμῳ καὶ στάσει δεδιότας, σφίσι δὲ αὐτίκα γιγνομένους ἐξ οἰκείων πολεμίους, ἢ δι’ ὕπουλον ἔχθραν ἢ ὑπὸ τῶν ἐπικεκηρυγμένων σφίσι γερῶν ἢ διὰ τὸν ἐν ταῖς οἰκίαις χρυσόν τε καὶ ἄργυρον. ἄπιστος γὰρ δὴ διὰ ταῦτα ἀθρόως ἕκαστος ἐς τὸν οἰκεῖον ἐγίγνετο καὶ τὸ σφέτερον κέρδος τοῦ πρὸς αὐτὸν ἐλέου προυτίθει· ὁ δὲ πιστὸς ἢ εὔνους ἐδεδίει βοηθεῖν ἢ κρύπτειν ἢ συνειδέναι δι’ ὁμοιότητα τῶν ἐπιτιμίων. ἔς τε τὸ ἔμπαλιν αὐτοῖς τοῦ πρώτου τῶν ἑπτακαίδεκα ἀνδρῶν δέους περιέστη. τότε μὲν γὰρ οὐ προγραφέντος οὐδενός, ἀλλά τινων ἄφνω συλλαμβανομένων πάντες ἐδεδοίκεσαν ὅμοια καὶ συνήσπιζον ἀλλήλοις· ἐπὶ δὲ ταῖς προγραφαῖς οἱ μὲν αὐτίκα πᾶσιν ἔκδοτοι γεγένηντο, οἱ δὲ ἐν ἀμερίμνῳ περὶ σφῶν καὶ ἐπὶ κέρδει γενόμενοι τοὺς ἄλλους ἐπὶ μισθῷ τοῖς σφαγεῦσιν ἐκυνηγέτουν. ὁ δὲ λοιπὸς ὅμιλος, οἱ μὲν τὰς οἰκίας τῶν ἀναιρουμένων διήρπαζον, καὶ τὸ κέρδος αὐτοὺς ἀπο τῆς συνέσεως τῶν παρόντων κακῶν ἐψυχαγώγει· οἱ δὲ ἐμφρονέστεροί τε καὶ ἐπιεικεῖς ἐτεθήπεσαν ὑπὸ ἐκπλήξεως, καὶ ἦν αὐτοῖς παραλογώτερον, ὅτε μάλιστα ἐνθυμηθεῖεν, ὅτι τὰς μὲν ἄλλας πόλεις ἐλυμήναντο στάσεις καὶ περιέσωσαν ὁμόνοιαι, τὴν δὲ καὶ αἱ στάσεις τῶν ἀρχόντων προαπώλεσαν καὶ ἡ ὁμόνοια τοιάδε ἐργάζεται.", "st": "4.14"}, {"sp": "N", "t": "ἔθνῃσκον δὲ οἱ μὲν ἀμυνόμενοι τοὺς ἀναιροῦντας, οἱ δ’ οὐκ ἀμυνόμενοι ὡς οὐχ ὑπὸ τῶνδε ἀδικούμενοι, εἰσὶ δ’ οἳ καὶ σφᾶς αὐτοῦς λιμῷ τε ἑκουσίῳ δαπανῶντες καὶ βρόχοις χρώμενοι καὶ τὰ σώματα καταποντοῦντες ἢ ῥιπτοῦντες ἀπὸ τῶν τεγῶν ἢ ἐς πῦρ ἐναλλόμενοι ἢ τοῖς σφαγεῦσιν ὑπίσχοντες ἢ καὶ μεταπεμπόμενοι βραδύνοντας, ἕτεροι δὲ κρυπτόμενοι καὶ λιπαροῦντες ἀπρεπῶς ἢ διωθούμενοι τὸ κακὸν ἢ ὠνούμενοι. οἱ δὲ καὶ παρὰ γνώμην τῶν τριῶν ἀνδρῶν, ὑπ’ ἀγνοίας ἢ κατ’ ἐπιβουλήν, ἀπώλλυντο. καὶ δῆλος ἦν ὁ μὴ προγραφεὶς νέκυς, ὅτε οἱ προσκέοιτο ἡ κεφαλή· τῶν γὰρ δὴ προγεγραμμένων ἐν ἀγορᾷ προυτίθεντο παρὰ τοῖς βήμασιν, ἔνθα ἔδει κομίσαντας ἀντιλαβεῖν τὰ ἀγαθά. ἴση δ’ ἦν ἑτέρων σπουδὴ καὶ ἀρετή, γυναικῶν τε καὶ παιδίων καὶ ἀδελφῶν καὶ θεραπόντων, περισῳζόντων τε καὶ συμμηχανωμένων πολλὰ καὶ συναποθνῃσκόντων, ὅτε μὴ τύχοιεν ὧν ἐπενόουν· οἱ δὲ καὶ ἐπανῄρουν σφᾶς ἀνῃρημένοις. τῶν δὲ ἐκφυγόντων οἱ μὲν ὑπὸ ναυαγίων ἀπώλλυντο, ἐς πάντα σφίσι τῆς τύχης ἐπιβαρούσης, οἱ δὲ ἐπανήχθησαν ἐκ παραλόγων ἐπί τε ἀρχὰς τῆς πόλεως καὶ στρατηγίας πολέμων καὶ θριάμβους. οὕτως ὁ καιρὸς ἦν ἐκεῖνος ἐπίδειξις παραδοξολογίας.", "st": "4.15"}, {"sp": "N", "t": "καὶ τάδε ἐγίγνετο οὐκ ἐν ἰδιώτιδι πόλει οὐδὲ ἐν ἀσθενεῖ καὶ σμικρῷ βασιλείῳ, ἀλλὰ τὴν δυνατωτάτην καὶ τοσούτων ἐθνῶν καὶ γῆς καὶ θαλάσσης ἡγεμονίδα διέσειεν ὁ θεός, ἐκ πολλοῦ ἄρα ἐς τὴν νῦν καθιστάμενος εὐταξίαν. ἐγένετο μὲν οὖν τοιάδε ἕτερα ἐν αὐτῇ κατά τε Σύλλαν καὶ ἔτι πρὸ ἐκείνου Γάιον Μάριον, ὧν ὁμοίως τὰ γνωριμώτατα τῶν κακῶν ἐν τοῖς περὶ ἐκείνων ἀνελεξάμην, καὶ προσῆν ἐκείνοις ἀταφία· ταῦτα δὲ ἀξιώσει τε τῶν τριῶν ἀνδρῶν καὶ τοῦ ἑνὸς αὐτῶν μάλιστα ἀρετῇ καὶ τύχῃ, τὴν ἀρχὴν συστησαμένου τε ἐς ἕδραν ἀσφαλῆ καὶ γένος καὶ ὄνομα τὸ νῦν ἄρχον ἀφ’ ἑαυτοῦ καταλιπόντος, ἐπιφανέστερα. ὧν τὰ λαμπρὰ καὶ τὰ χείρω γενόμενα ἐν μνήμῃ τε μᾶλλον ὄντα, ὅτι καὶ τελευταῖα γέγονεν, ἐπελεύσομαι νῦν, οὐ πάντα (οὐ γὰρ ἀξιαφήγητον ἀναίρεσις ἁπλῆ καὶ φυγὴ ἢ τῶν τριῶν ἀνδρῶν τισι συγγνόντων ὕστερον ἐπάνοδος ἢ ἐπανελθόντων ἀφανὴς καταβίωσις), ἀλλ’ ὅσα παραλογώτατα ὄντα μάλιστα ἂν ἐκπλήξειε καὶ πιστεύειν ποιήσειε τοῖς προλεγομένοις. πολλὰ δέ ἐστι, καὶ πολλοὶ Ῥωμαίων ἐν πολλαῖς βίβλοις αὐτὰ συνέγραψαν ἐφ’ ἑαυτῶν· ὀλίγα δὲ ἐγὼ καθ’ ἑκάστην ἰδέαν, ἐς πίστιν ἑκάστης καὶ ἐς εὐδαιμόνισμα τῶν νῦν παρόντων, ἐπὶ κεφαλαίου διὰ τὸ μῆκος ἀναγράψω.", "st": "4.16"}, {"sp": "N", "t": "Ἠρξατο μὲν δὴ τὸ κακὸν ἐκ συντυχίας ἀπὸ τῶν ἐν ἀρχαῖς ἔτι ὄντων, καὶ πρῶτος ἀνῃρέθη δημαρχῶν Σάλουιος. ἱερὰ δέ ἐστιν ἡ ἀρχὴ καὶ ἄσυλος ἐκ τῶν νόμων καὶ τὰ μέγιστα ἴσχυεν, ὡς καὶ τῶν ὑπάτων τινὰς ἐς τὰς φυλακὰς ἐμβαλεῖν. καὶ ἦν ὅδε ὁ δήμαρχος ὁ τὸν Ἀντώνιον ἐν μὲν ἀρχῇ κεκωλυκὼς εἶναι πολέμιον, ὕστερον δὲ συμπεπραχὼς ἐς πάντα Κικέρωνι. πυθόμενος δὲ τῶν τριῶν ἀνδρῶν τῆς τε συμφρονήσεως καὶ τῆς ἐς τὴν πόλιν ἐπείξεως τοὺς οἰκείους εἱστία ὡς οὐ πολλάκις αὐτοῖς ἔτι συνεσόμενος· ἐσδραμόντων δὲ ἐς τὸ συμπόσιον τῶν ὁπλιτῶν οἱ μὲν ἐξανίσταντο σὺν θορύβῳ καὶ δέει, ὁ δὲ τῶν ὁπλιτῶν λοχαγὸς ἐκέλευεν ἠρεμεῖν κατακλιθέντας, τὸν δὲ Σάλουιον, ὡς εἶχε, τῆς κόμης ἐπισπάσας ὑπὲρ τὴν τράπεζαν, ἐς ὅσον ἔχρῃζε, τὴν κεφαλὴν ἀπέτεμε καὶ τοῖς ἔνδον αὖθις ἐκέλευεν ἀτρεμεῖν, ὡς ἔχουσι, μὴ θορύβου γενομένου πάθοιεν ὅμοια. οἱ μὲν δὴ καὶ οἰχομένου τοῦ λοχαγοῦ τεθηπότες ἄναυδοι μέχρι βαθυτάτης νυκτός, τῷ λοιπῷ τοῦ δημάρχου σώματι συγκατέκειντο. δεύτερος δ’ ἀνὴρ ἔθνῃσκε στρατηγὸς Μινούκιος, ἀρχαιρεσιάζων μὲν ἐν ἀγορᾷ· πυθόμενος δὲ ἐπιέναι τοὺς ὁπλίτας ἀνεπήδησε καὶ περιθέων ἔτι καὶ ἐννοούμενος, ὅποι διαλάθοι, τὴν ἐσθῆτα ἐνήλλασσεν ἔς τι τῶν ἐργαστηρίων ἐσδραμών, τοὺς ὑπηρέτας καὶ τὰ σημεῖα ἀποπέμψας. οἱ δὲ αἰδοῖ καὶ ἐλέῳ παραμένοντες εὐμαρέστερον ἄκοντες ἐποίησαν τοῖς σφαγεῦσι τὸν στρατηγὸν εὑρεῖν.", "st": "4.17"}, {"sp": "N", "t": "Ἀννᾶλιν ἕτερον στρατηγόν, τῷ παιδὶ μετιόντι ταμιείαν συμπεριθέοντα καὶ τοὺς ψηφιουμένους παρακαλοῦντα, οἵ τε συνόντες φίλοι καὶ οἱ τὰ σημεῖα τῆς ἀρχῆς φέροντες ἀπεδίδρασκον, πυθόμενοι προσγεγράφθαι τοῖς πίναξι τὸν Ἀννᾶλιν. ὁ δὲ ἐς πελάτην ἑαυτοῦ τινα φυγών, ᾧ βραχὺ καὶ εὐτελὲς ἦν τέγος ἐν προαστείῳ καὶ διὰ πάντα εὐκαταφρόνητον, ἐκρύπτετο ἀσφαλῶς, μέχρι τοὺς σφαγέας ὁ υἱὸς αὐτοῦ, τὴν φυγὴν ἐς τὸν πελάτην ὑποτοπήσας, ὡδήγησεν ὑπὸ τὸ τέγος, καὶ παρὰ τῶν τριῶν ἀνδρῶν τήν τε οὐσίαν ἔλαβε τοῦ πατρὸς καὶ ἐς ἀγορανομίαν ᾑρέθη. ἀναλύοντα δὲ αὐτὸν ἐκ μέθης στρατιῶταί τι προσκρούσαντες ἔκτειναν, οἳ καὶ τὸν πατέρα ἀνῃρήκεσαν.", "st": "4.18"}, {"sp": "N", "t": "Θουράνιος δὲ οὐ στρατηγῶν μὲν ἔτι, ἀλλ’ ἐστρατηγηκώς, πατὴρ δὲ νεανίου τὰ μὲν ἄλλα ἀκολάστου, δυναστεύοντος δὲ παρ’ Ἀντωνίῳ, τοὺς λοχαγοὺς ἠξίου τὴν σφαγὴν ἐπισχεῖν οἱ πρὸς ὀλίγον, ἔστε αὐτὸν ὁ υἱὸς αἰτήσαιτο παρ’ Ἀντωνίου. οἱ δ’ ἐπιγελάσαντες “ᾔτησεν,” εἶπον, “ἀλλ’ ἐπὶ θάτερα.” καὶ συνεὶς ὁ πρεσβύτης ἕτερον αὐτίκα βραχύτατον ᾔτει διάστημα, μέχρις οὗ τὴν θυγατέρα ἴδοι· ἰδὼν δὲ ἐκέλευε μὴ μετασχεῖν τῶν πατρῴων, μὴ κἀκείνην ὁ ἀδελφὸς αἰτήσαιτο παρὰ Ἀντωνίου. συνέβη δὲ καὶ τῷδε τὴν οὐσίαν ἐς αἰσχρὰ δαπανῆσαι καὶ κλοπῆς ἁλόντι φυγεῖν ἐκ καταδίκης.", "st": "4.18"}, {"sp": "N", "t": "Κικέρων δέ, ὃς μετὰ Γάιον Καίσαρα ἴσχυσεν, ὅση γένοιτο ἂν δημαγωγοῦ μοναρχία, κατέγνωστο μὲν ἅμα τῷ παιδὶ καὶ τῷ ἀδελφῷ καὶ τῷ παιδὶ τοῦ ἀδελφοῦ καὶ πᾶσιν οἰκείοις τε καὶ στασιώταις καὶ φίλοις· φυγὼν δὲ ἐπὶ σκάφους οὐκ ἔφερε τὴν ἀηδίαν τοῦ κλύδωνος, ἀλλὰ εἰς ἴδιον χωρίον, ὃ καθ’ ἱστορίαν τοῦδε τοῦ πάθους εἶδον, ἀμφὶ Καιήτην πόλιν τῆς Ἰταλίας, καταχθεὶς ἠρέμει. πλησιαζόντων δὲ τῶν ἐρευνωμένων (τοῦτον γὰρ δὴ φιλοτιμότατα πάντων Ἀντώνιός τε ἐζήτει καὶ Ἀντωνίῳ πάντες) ἐς τὸ δωμάτιον αὐτοῦ κόρακες ἐσπτάντες ἔκλαζον, ἐπεγείροντες ἀπὸ τοῦ ὕπνου, καὶ τὸ ἱμάτιον ἀπέσυρον ἀπὸ τοῦ σώματος, ἕως οἱ θεράποντες, σημηνάμενοι τὸ γιγνόμενον εἶναι σύμβολον ἔκ του θεῶν, ἐς φορεῖον ἐσθέμενοι τὸν Κικέρωνα αὖθις ἐπὶ τὴν θάλασσαν ἦγον διὰ λόχμης βαθείας λανθάνοντες. πολλῶν δὲ ἀνὰ μέρη διαθεόντων τε καὶ πυνθανομένων, εἴ που Κικέρων ὁραθείη, οἱ μὲν ἄλλοι ἐπ’ εὐνοίᾳ καὶ ἐλέῳ πλεῖν αὐτὸν ἐξαναχθέντα ἔλεγον ἤδη, σκυτοτόμος δὲ πελάτης Κλωδίου, πικροτάτου τῷ Κικέρωνι ἐχθροῦ γεγονότος, Λαίνᾳ τῷ λοχαγῷ σὺν ὀλίγοις ὄντι τὴν ἀτραπὸν ἔδειξεν. ὁ δὲ ἐπέδραμέ τε καὶ θεράποντας ἰδὼν πολὺ πλείους τῶν ἀμφ’ αὑτὸν ὁρμῶντας ἐς ἄμυναν, στρατηγικῶς μάλα ἀνεβόησεν· “ἐσελθέτωσαν ἐς τὸ χωρίον οἱ περὶ οὐρὰν λοχαγοί.”", "st": "4.19"}, {"sp": "N", "t": "τότε γὰρ οἱ μὲν θεράποντες ὡς ἐλευσομένων πλεόνων κατεπλάγησαν, ὁ δὲ Λαίνας, καὶ δίκην τινὰ διὰ τοῦ Κικέρωνός ποτε κατωρθωκώς, ἐκ τοῦ φορείου τὴν κεφαλὴν ἐπισπάσας ἀπέτεμνεν, ἐς τρὶς ἐπιπλήσσων καὶ ἐκδιαπρίζων ὑπὸ ἀπειρίας· ἀπέτεμε δὲ καὶ τὴν χεῖρα, ᾗ τοὺς κατὰ Ἀντωνίου λόγους οἷα τυράννου συγγράφων, ἐς μίμημα τῶν Δημοσθένους, Φιλιππικοὺς ἐπέγραφεν. ἔθεον δὲ οἱ μὲν ἐπὶ ἵππων, οἱ δὲ ἐπὶ νεῶν, αὐτίκα τὸ εὐαγγέλιον Ἀντωνίῳ διαφέροντες· καὶ ὁ Λαίνας ἐν ἀγορᾷ προκαθημένῳ τὴν κεφαλὴν καὶ τὴν χεῖρα μακρόθεν ἀνέσειεν ἐπιδεικνύς. ὁ δὲ ἥσθη μάλιστα καὶ τὸν λοχαγὸν ἐστεφάνωσε καὶ πλέοσι τῶν ἄθλων ἐδωρήσατο πέντε καὶ εἴκοσι μυριάσιν Ἀττικῶν δραχμῶν ὡς μέγιστον δὴ τόνδε πάντων ἐχθρὸν καὶ πολεμιώτατόν οἱ γενόμενον ἀνελόντα. ἡ κεφαλὴ δὲ τοῦ Κικέρωνος καὶ ἡ χεὶρ ἐν ἀγορᾷ τοῦ βήματος ἀπεκρέμαντο ἐπὶ πλεῖστον, ἔνθα πρότερον ὁ Κικέρων ἐδημηγόρει· καὶ πλείους ὀψόμενοι συνέθεον ἢ ἀκροώμενοι. λέγεται δὲ καὶ ἐπὶ τῆς διαίτης ὁ Ἀντώνιος τὴν κεφαλὴν τοῦ Κικέρωνος θέσθαι πρὸ τῆς τραπέζης, μέχρι κόρον ἔσχε τῆς θέας τοῦ κακοῦ.", "st": "4.20"}, {"sp": "N", "t": "ὧδε μὲν δὴ Κικέρων, ἐπί τε λόγοις ἀοίδιμος ἐς ἔτι νῦν ἀνήρ, καὶ ὅτε ἦρχε τὴν ὕπατον ἀρχήν, ἐς τὰ μέγιστα τῇ πατρίδι γεγονὼς χρήσιμος, ἀνῄρητο καὶ ἀνῃρημένος ἐνυβρίζετο· ὁ δὲ παῖς ἐς τὴν Ἑλλάδα προαπέσταλτο ἐς Βροῦτον. Κόιντος δέ, ὁ τοῦ Κικέρωνος ἀδελφός, ἅμα τῷ παιδὶ καταληφθεὶς ἐδεῖτο τῶν σφαγέων πρὸ τοῦ παιδὸς αὑτὸν ἀνελεῖν· τὰ δὲ ἐναντία καὶ τοῦ παιδὸς ἱκετεύοντος, οἱ σφαγεῖς ἔφασαν ἀμφοτέροις διαιτήσειν καὶ διαλαβόντες ἕτερον ἕτεροι κατὰ σύνθημα φονεῖς ἀνεῖλον ὁμοῦ.", "st": "4.20"}, {"sp": "N", "t": "Ἐγνάτιοι δέ, πατὴρ καὶ υἱός, συμφυέντες ἀλλήλοις διὰ μιᾶς πληγῆς ἀπέθανον· καὶ αὐτῶν αἱ κεφαλαὶ μὲν ἀπετέτμηντο, τὰ δὲ λοιπὰ σώματα ἔτι συνεπέπλεκτο. Βάλβος τὸν υἱόν, ἵνα μὴ βαδίζοντες ὁμοῦ φανεροὶ γένοιντο, προύπεμψεν ἐς φυγὴν ἐπὶ θάλασσαν καὶ μετ’ ὀλίγον εἵπετο ἐκ διαστήματος. ἐξαγγείλαντος δέ τινος, εἴτε ἐξ ἐπιβουλῆς εἴθ’ ὑπ’ ἀγνοίας, τὸν υἱὸν συνειλῆφθαι, ἐπανῆλθε καὶ τοὺς σφαγέας μετεπέμψατο. συνέβη δὲ καὶ τὸν παῖδα ἀπολέσθαι ναυαγίῳ· οὕτω ταῖς τότε συμφοραῖς καὶ τὸ δαιμόνιον ἐπέκειτο. Ἀρρούντιος τὸν υἱόν, οὐχ ὑφιστάμενον φεύγειν χωρὶς αὐτοῦ, μόλις ἔπεισεν ὡς νέον περισῴζειν ἑαυτόν. καὶ τόνδε μὲν ἡ μήτηρ ἐπὶ τὰς πύλας προύπεμψε καὶ ὑπέστρεψεν, ἵνα ἀνῃρημένον τὸν ἄνδρα θάψειε· πυθομένη δὲ καὶ τὸν υἱὸν ὑπὸ τῆς θαλάσσης διεφθάρθαι λιμῷ διεχρήσατο ἑαυτήν.", "st": "4.21"}, {"sp": "N", "t": "αἵδε μὲν δὴ παίδων ἀγαθῶν καὶ κακῶν ἔστων εἰκόνες· ἀδελφοὶ δὲ δύο ὁμοῦ προγραφέντες, οἷς ὄνομα ἦν Λιγάριοι, ἐκρύπτοντο ὑπὸ ἰπνῷ, μέχρι τῶν θεραπόντων αὐτοὺς ἀνευρόντων ὁ μὲν αὐτίκα ἀνῃρέθη, ὁ δὲ ἐκφυγών, ἐπεὶ τὸν ἀδελφὸν ἔγνω διεφθαρμένον, ἔρριψεν αὑτὸν ἀπὸ τοῦ ποταμοῦ τῆς γεφύρας ἐς τὸ ῥεῦμα. καὶ αὐτὸν ἁλιέων περισχόντων ὡς οὐκ ἐναλάμενον, ἀλλὰ πεπτωκότα, ἐς πολὺ μὲν ἐφιλονίκει καὶ ἑαυτὸν ἐς τὸ ῥεῦμα ἐώθει, ἡσσώμενος δὲ τῶν ἁλιέων περιεγίγνετο καὶ “οὐκ ἐμέ,” ἔφη, “περισῴζετε, ἀλλ’ ἑαυτοὺς ἐμοὶ προγεγραμμένῳ συναπόλλυτε.” οἱ δὲ καὶ ὣς αὐτὸν οἰκτείραντες περιέσῳζον, μέχρι τινὲς τῶν στρατιωτῶν, οἳ τὴν γέφυραν ἐτήρουν, ἰδόντες ἐπέδραμόν τε καὶ τὴν κεφαλὴν ἀπέτεμον. ἑτέρων δὲ ἀδελφῶν ὁ μὲν αὑτὸν ἔρριψε κατὰ τοῦ ῥεύματος, καὶ θεράπων αὐτοῦ τὸ σῶμα ἀνεζήτει μέχρι πέμπτης ἡμέρας, εὑρὼν δὲ ἔτι γνωρίζεσθαι δυναμένου, τὴν κεφαλὴν διὰ τὸ ἆθλον ἀπέκοψε· τὸν δὲ ἕτερον ἐν κοπρῶνι κρυπτόμενον ἕτερος ἐμήνυσε θεράπων, καὶ οἱ σφαγεῖς εἰσελθεῖν μὲν ἀπηξίωσαν, δόρασι δὲ περικεντοῦντες ἐξήγαγον καί, ὡς εἶχε, τὴν κεφαλὴν οὐδὲ ἀπονίψαντες ἀπέκοψαν. ἕτερος δέ, τοῦ ἀδελφοῦ συλλαμβανομένου, προσδραμὼν ἀγνοίᾳ τοῦ καὶ αὐτὸς ἅμα ἐκείνῳ προγεγράφθαι, “ἐμέ,” ἔφη, “κτείνατε πρὸ τούτου.” καὶ ὁ λοχαγὸς ἔχων τὸ ἀκριβὲς ἀνάγραπτον, “εἰκότα ἀξιοῖς,” ἔφη· “σὺ γὰρ πρὸ τούτου γέγραψαι,” καὶ εἰπὼν κατὰ τὴν τάξιν ἔκτεινεν ἄμφω.", "st": "4.22"}, {"sp": "N", "t": "ταῦτα μὲν δὴ καὶ ἀδελφῶν δείγματα· Λιγάριον δὲ ἡ γυνὴ κρύπτουσα μίαν ἐς τὸ ἀπόρρητον ἐπηγάγετο θεράπαιναν, προδοθεῖσα δὲ ὑπ’ αὐτῆς εἵπετο τῇ κεφαλῇ τοῦ ἀνδρὸς φερομένῃ βοῶσα· “ἐγὼ τοῦτον ὑπεδεξάμην, τὰ δ’ ὅμοια τοῖς ὑποδεξαμένοις ἐστὶν ἐπιτίμια.” καὶ οὐδενὸς αὐτὴν οὔτε ἀναιροῦντος οὔτε μηνύοντος, αὐτάγγελος ἐς τοὺς ἄρχοντας ἦλθε καθ’ ἑαυτῆς, κἀκείνων αὐτὴν διὰ τὴν φιλανδρίαν ὑπεριδόντων, ἑαυτὴν ἀπέκτεινε λιμῷ. καὶ τῆσδε μὲν ἐνθάδε ἐπεμνήσθην, ὅτι τὸν ἄνδρα περισῴζουσα ἀπετύγχανέ τε καὶ συνεξήγαγεν ἑαυτήν· ὅσαι δὲ ἐπέτυχον τῆς φιλανδρίας, ἐν τοῖς περισωθεῖσι τῶν ἀνδρῶν ἀναγράψω. ἕτεραι δὲ ἀθεμίστως ἐπεβούλευσαν τοῖς ἀνδράσιν. καὶ αὐτῶν ἐστιν, ἣ Σεπτιμίῳ μὲν ἐγεγάμητο, ὑπὸ δέ τινος Ἀντωνίῳ φίλου διεφθείρετο· ἐπειγομένη δὲ ἐκ μοιχείας ἐς γάμον ἐδεήθη διὰ τοῦ μοιχεύοντος αὐτὴν Ἀντωνίου, καὶ ὁ Σεπτίμιος αὐτίκα τοῖς πίναξι προσετέθη. καὶ μαθὼν ἐς τῆς γυναικὸς ὑπ’ ἀγνοίας τῶν οἴκοι κακῶν ἔφευγεν. ἡ δὲ ὡς φιλοφρονουμένη τὰς θύρας ἐπέκλεισε καὶ ἐτήρει τὸν ἄνδρα, ἕως οἱ σφαγεῖς παρεγένοντο· καὶ τῆς αὐτῆς ἡμέρας οἱ μὲν ἐκεῖνον ἀνῄρουν, ἡ δὲ ἔθυε γάμους.", "st": "4.23"}, {"sp": "N", "t": "Σάλασσος δὲ ἐκφυγών τε καὶ ἀπορούμενος ἧκε μὲν ἐς πόλιν νυκτός, ὅτε μάλιστα ἔδοξεν ἀμβλύνεσθαι τὸ δεινόν, πεπραμένης δὲ τῆς οἰκίας μόνος αὐτὸν ὁ θυρωρὸς τῇ οἰκίᾳ συμπεπραμένος ἐπέγνω καὶ ἐς τὸ ἑαυτοῦ οἴκημα ὑπεδέχετο καὶ κρύψειν ἐπηγγέλλετο καὶ θρέψειν, ἐξ ὧν ἐδύνατο. ὁ δὲ τὴν γυναῖκά οἱ καλέσαι προσέταξεν ἐκ τῆς ἐκείνης οἰκίας. ἡ δ’ ὑποκριναμένη μὲν ἐλθεῖν ἐπείγεσθαι, δεδιέναι δ’ ὡς ἐν νυκτὶ καὶ θεραπαίναις τὸ ὕποπτον, μεθ’ ἡμέραν ἥξειν ἔφη. καὶ γενομένης ἡμέρας ἡ μὲν τοὺς σφαγέας μετῄει, καὶ ὁ θυρωρὸς αὐτὴν ὡς βραδύνουσαν ἐς τὴν οἰκίαν ἀπέτρεχεν ἐπείξων· ὁ δὲ Σάλασσος, οἰχομένου τοῦ θυρωροῦ δείσας ὡς ἐς ἐνέδραν ἀπιόντος, ἐς τὸ τέγος ἀναδραμὼν ἐκαραδόκει τὸ γιγνόμενον, ἰδὼν δὲ οὐ τὸν θυρωρόν, ἀλλὰ τὴν γυναῖκα τοῖς σφαγεῦσιν ἡγουμένην ἔρριψεν ἑαυτὸν ἀπὸ τοῦ τέγους. Φούλβιον δὲ ἐς θεραπαίνης φυγόντα παλλακευθείσης τε αὐτῷ καὶ ἀπηλευθερωμένης καὶ προῖκα ἐς γάμον ἐπιλαβούσης, ἡ τοσάδε εὖ παθοῦσα προύδωκε ζηλοτυπίᾳ τῆς μεθ’ ἑαυτὴν τῷ Φουλβίῳ γεγαμημένης.", "st": "4.24"}, {"sp": "N", "t": "τοσάδε μὲν δὴ καὶ γυναικῶν πονηρῶν ὑποδείγματα γεγράφθω· Στάτιος δὲ ὁ Σαυνίτης, πολλὰ Σαυνίταις ἐν τῷ συμμαχικῷ πολέμῳ κατειργασμένος, διὰ δὲ περιφάνειαν ἔργων καὶ διὰ πλοῦτον καὶ γένος ἐς τὸ Ῥωμαίων βουλευτήριον ἀνακεκλημένος, ὀγδοηκοντούτης ὢν ἤδη καὶ διὰ πλοῦτον προγεγραμμένος, ἀνεπέτασε τὴν οἰκίαν τῷ τε δήμῳ καὶ τοῖς θεράπουσιν ἐκφορεῖν, ὅσα θέλοιεν, τὰ δὲ καὶ αὐτὸς διερρίπτει, μέχρι κεκενωμένης ἐπικλείσας ἐνέπρησε καὶ ἀπώλετο, καὶ τὸ πῦρ πολλὰ τῆς πόλεως ἄλλα ἐπενείματο. Καπίτων δὲ ἐς πολὺ τὰς θύρας ὑπανοίγων τοὺς ἐσβιαζομένους καθ’ ἕνα ἀνῄρει, ὑπὸ δὲ πολλῶν ἐπιβρισάντων εἷς ἀπέθανε πολλοὺς ἀποκτείνας. Οὐετουλῖνος δὲ χεῖρα ἤθροισε πολλὴν ἀμφὶ τὸ Ῥήγιον αὐτῶν τε τῶν προγεγραμμένων ἀνδρῶν καὶ ὅσοι συνέφευγον αὐτοῖς, καὶ ἀπὸ τῶν ὀκτωκαίδεκα πόλεων, αἳ τοῖς στρατοῖς ἐπινίκια ἐπηγγελμέναι πάνυ ἐδυσχέραινον. τούσδε οὖν ἔχων ὁ Οὐετουλῖνος ἀνῄρει τῶν λοχαγῶν τοὺς διαθέοντας, μέχρι πεμφθέντος ἐπ’ αὐτὸν στρατοῦ πλέονος οὐδ’ ὣς ἔληξεν, ἀλλ’ ἐς Σικελίαν πρὸς Πομπήιον, κρατοῦντά τε αὐτῆς καὶ τοὺς φεύγοντας ὑποδεχόμενον, ἐπέρασεν. εἶτα ἐπολέμει καρτερῶς, μέχρι πολλαῖς μάχαις ἡσσώμενος τὸν μὲν υἱὸν καὶ ὅσοι τῶν προγεγραμμένων ἄλλοι συνῆσαν, ἐπὶ Μεσσήνης ἔπεμψεν, αὐτὸς δέ, ὡς εἶδε πορθμευόμενον ἤδη τὸ σκάφος, ἐμπεσὼν τοῖς πολεμίοις κατεκόπη.", "st": "4.25"}, {"sp": "N", "t": "Νάσων δὲ ὑπὸ ἐξελευθέρου, παιδικῶν οἱ γενομένου, προδοθεὶς ἥρπασε παρά του τῶν στρατιωτῶν ξίφος καὶ τὸν προδότην μόνον ἀποκτείνας ἑαυτὸν τοῖς σφαγεῦσιν ὑπέσχε. φιλοδέσποτος δὲ οἰκέτης τὸν κεκτημένον ἐπὶ λόφου ἐκάθισε καὶ αὐτὸς ἐπὶ θάλασσαν ᾔει μισθωσόμενος αὐτῷ σκάφος. ἐπανιὼν δὲ κτεινόμενόν τε εἶδε τὸν δεσπότην καὶ ἀποψύχοντος ἤδη μέγα βοῶν “ἐπίμεινον ἐς βραχύ, ὦ δέσποτα,” εἶπε καὶ κτείνει τὸν λοχαγὸν ἐμπεσὼν ἄφνω. μετὰ δὲ ἐκεῖνον ἑαυτὸν ἐπαναιρῶν εἶπε τῷ δεσπότῃ· “παραμύθιον ἔχεις.” Λεύκιος δὲ δύο πιστοτάτοις ἀπελευθέροις χρυσίον δοὺς ἐπὶ θάλασσαν ᾔει, διαδράντων δὲ ἐκείνων ὑπέστρεψε καταγινώσκων τοῦ βίου καὶ ἑαυτὸν ἐμήνυσε τοῖς σφαγεῦσι. Λαβιηνὸς δὲ ἐν ταῖς Σύλλα προγραφαῖς πολλοὺς τῶν τότε συλλαβών τε καὶ κτείνας ἠδόξησεν ἄρα, εἰ μὴ τὰ ὅμοια γενναίως ἐνέγκοι, καὶ προελθὼν τῆς οἰκίας ἐκαθέζετο ἐπὶ θρόνου τοὺς σφαγέας περιμένων. Κέστιος δὲ ἐν χωρίοις παρὰ εὐνόοις θεράπουσιν ἐκρύπτετο, λοχαγῶν δ’ αἰεὶ σὺν ὅπλοις ἢ κεφαλαῖς διαθεόντων οὐκ ἔφερε τὸ μῆκος τοῦ φόβου, ἀλλ’ ἔπεισε τοὺς θεράποντας ἅψαι πυράν, ἵνα ἔχοιεν λέγειν, ὅτι Κέστιον ἀποθανόντα θάπτοιεν. καὶ οἱ μὲν ἐνεδρευθέντες ἧψαν, ὁ δὲ ἐσήλατο ἐς αὐτήν. Ἀπώνιος δὲ ἀσφαλῶς ἑαυτὸν ἐπικρύψας οὐκ ἤνεγκε τὴν πονηρίαν τῆς διαίτης, ἀλλὰ προήγαγεν ἑαυτὸν ἐπὶ τὴν σφαγήν. ἄλλος ἐν φανερῷ καθῆστο ἑκὼν καὶ βραδυνόντων τῶν σφαγέων ἀπήγξατο ἐν μέσῳ.", "st": "4.26"}, {"sp": "N", "t": "Λεύκιος δὲ ὁ Ἀσινίου τοῦ ὑπατεύοντος τότε πενθερός, φεύγων διὰ θαλάσσης, οὐ φέρων τοῦ χειμῶνος τὴν ἀηδίαν ἔρριψεν ἑαυτὸν εἰς τὸ πέλαγος. Καισέννιον δὲ οἱ διώκοντες, ὑποφεύγοντά τε καὶ βοῶντα οὐ προγεγράφθαι, ἀλλὰ διὰ τὰ χρήματα ἐπιβουλεύεσθαι πρὸς αὐτῶν, ἐπὶ τὸν πίνακα ἀγαγόντες ἀναγινώσκειν ἑαυτοῦ τὸ ὄνομα ἐκέλευον καὶ ἀναγινώσκοντα ἔκτειναν. Αἰμίλιος δὲ ἀγνοῶν, ὅτι προγέγραπται, διωκόμενον ἄλλον ἰδὼν ἤρετο τὸν λοχαγὸν τὸν διώκοντα, τίς ὁ προγεγραμμένος εἴη· καὶ ὁ λοχαγὸς τὸν Αἰμίλιον γνωρίσας “σὺ κἀκεῖνοσ” εἶπε καὶ τοὺς δύο ἀπέκτεινε. Κίλλων δὲ ἐκ τοῦ βουλευτηρίου προϊὼν καὶ Δέκιος, ἐπεὶ τοῖς πίναξιν ἐπύθοντο σφῶν τὰ ὀνόματα προσγεγράφθαι, οὔπω τινὸς ἐπιόντος αὐτοῖς, ἔφευγον ἀκόσμως διὰ πυλῶν, καὶ αὐτοὺς τοῖς ἀπαντῶσι τῶν λοχαγῶν αὐτὸς ὁ δρόμος ἐμήνυσεν.", "st": "4.27"}, {"sp": "N", "t": "Ἰκέλιος δέ, ὃς ἐπὶ Βρούτῳ τε καὶ Κασσίῳ δικάζων, Καίσαρος τοῖς δικαστηρίοις μετὰ στρατιᾶς ἐφεστῶτος καὶ τῶν ἄλλων δικαστῶν κρύφα τὴν καταδικάζουσαν φερόντων, μόνος τὴν ἀπολύουσαν ἤνεγκε φανερῶς, ἐκλαθόμενος τῆς μεγαλόφρονος ἐλευθεριότητος, νεκρὸν σῶμα ἐκκομιζόμενον ὑποστὰς τοῖς φέρουσι συνεβάσταζε τὸ λέχος. ἰδόντων δὲ τῶν φρουρούντων τὰς πύλας, ὅτι πλεονάζουσιν οἱ νεκροφόροι παρὰ τὸ σύνηθες ἑνὶ ἀνδρί, καὶ τοὺς μὲν φέροντας οὐχ ὑπονοούντων, τὸ δὲ λέχος ἐρευνωμένων, μὴ νεκρόν τις ὑποκρίνοιτο, οἱ νεκροφόροι τὸν Ἰκέλιον ἤλεγχον οὐχ ὁμότεχνον σφίσιν ὄντα, ἐπιγνωσθέντα τε οἱ σφαγεῖς ἀπέκτειναν.", "st": "4.27"}, {"sp": "N", "t": "Οὐᾶρος δ’ ἀπελευθέρου προδιδόντος αὐτὸν ἀπέδρα, καὶ ὄρος ἐξ ὄρους ἀμείβων ἐς τὸ Μιντουρναίων ἕλος ἐνέπεσεν, ἔνθα ἑαυτὸν διαναπαύων ἡσύχαζε. τῶν δὲ Μιντουρναίων ἐπὶ ζητήσει λῃστηρίου τὸ ἕλος περιθεόντων, ἥ τε κόμη τοῦ δόνακος σαλευθεῖσα ἐνέφηνε τὸν Οὐᾶρον, καὶ ληφθεὶς ἔλεγεν εἶναι λῃστὴς καὶ ἐπὶ τῷδε θανάτῳ καταδικαζόμενος ἠνείχετο. ὡς δὲ αὐτὸν ἔμελλον καὶ βασανιεῖν ἐς τοὺς συνεγνωκότας, οὐκ ἐνεγκὼν ἤδη τοῦτο ὡς ἀπρεπέστερον, “ἀπαγορεύω,” φησίν, “ὑμῖν, ὦ Μιντουρναῖοι, ὕπατόν με γεγενημένον, καί, ὃ τοῖς νῦν ἄρχουσι τιμιώτερόν ἐστι, προγεγραμμένον μήτε βασανίζειν μήτε ἀναιρεῖν ἔτι· εἰ γὰρ οὐκ ἔνι μοι διαφυγεῖν, ἄμεινον ὑπὸ τῶν ὁμοτίμων παθεῖν.” ἀπιστούντων δὲ τῶν Μιντουρναίων καὶ τὸν λόγον ὑπονοούντων λοχαγὸς ἐπέγνω διαθέων καὶ τὴν κεφαλὴν ἀπέτεμε, τὸ δὲ λοιπὸν σῶμα τοῖς Μιντουρναίοις κατέλιπε.", "st": "4.28"}, {"sp": "N", "t": "Λάργον ἕτεροι συνελάμβανον ἐν χωρίοις, οὐ Λάργον, ἀλλ’ ἕτερον διώκοντες· οἰκτείραντες δ’, ὅτι μὴ ζητούμενος ἁλοίη, φεύγειν μεθῆκαν ἀνὰ τὴν ὕλην. ὁ δὲ ὑφ’ ἑτέρων διωκόμενος δρόμῳ τοὺς προτέρους κατέλαβε καί “ὑμεῖς,” ἔφη, “με κτείνατε μᾶλλον, οἱ ἐλεήσαντες, ἵνα τὸν μισθὸν ἀντὶ τούτων ὑμεῖς φέρησθε.”", "st": "4.28"}, {"sp": "N", "t": "ὁ μὲν δὴ ταύτην ἔδωκεν ἀμοιβὴν ἀποθνῄσκων φιλανθρωπίας, Ῥοῦφος δὲ ἔχων συνοικίαν περικαλλῆ, γείτονα Φουλβίας τῆς γυναικὸς Ἀντωνίου, πάλαι μὲν ἀξιούσῃ τῇ Φουλβίᾳ πρίασθαι τὴν οἰκίαν οὐ συνεχώρει, τότε δὲ καὶ δωρούμενος προεγράφη. καὶ τὴν κεφαλὴν ὁ μὲν Ἀντώνιός οἱ προσφερομένην οὐχ ἑαυτῷ προσήκειν εἰπὼν ἔπεμψεν ἐς τὴν γυναῖκα, ἡ δὲ ἀντὶ τῆς ἀγορᾶς ἐκέλευσεν ἐπὶ τῆς συνοικίας προτεθῆναι. ἔπαυλιν ἕτερος εἶχε περικαλλῆ καὶ σύσκιον, ἄντρον τε καλὸν ἦν ἐν αὐτῇ καὶ βαθύ, καὶ τάχα διὰ ταῦτα καὶ προυγράφη. ἔτυχε δὲ ἀναψύχων κατὰ τὸ ἄντρον, καὶ αὐτῷ τῶν σφαγέων ἔτι μακρόθεν ἐπιθεόντων θεράπων αὐτὸν ἐς τὸν μυχὸν τοῦ ἄντρου προπέμψας ἐνέδυ τὸν τοῦ δεσπότου χιτωνίσκον καὶ ὑπεκρίνετο ἐκεῖνος εἶναι καὶ δεδιέναι· καὶ τάχα ἂν ἐπέτυχεν ἀναιρεθείς, εἰ μὴ τῶν ὁμοδούλων τις ἐνέφηνε τὴν ἐνέδραν. ἀναιρεθέντος δὲ ὧδε τοῦ δεσπότου, ὁ δῆμος ἀγανακτῶν παρὰ τοῖς ἄρχουσιν οὐκ ἐπαύετο, μέχρι τὸν μὲν ἐνδείξαντα κρεμασθῆναι, τὸν δὲ περισώσαντα ἐλευθερῶσαι ἐποίησεν. Ἁτέριον δὲ κρυπτόμενον θεράπων ἐμήνυσέ τε καὶ ἐλεύθερος αὐτίκα γενόμενος ἀντωνεῖτο τοῖς παισὶν αὐτοῦ τὴν οὐσίαν καὶ ἐνύβριζεν ἐπαχθῶς. οἱ δὲ αὐτῷ πανταχῇ μετὰ σιγῆς εἵποντο κλαίοντες, ἕως ὁ δῆμος ἠγανάκτησε, καὶ οἱ τρεῖς αὐτόν, ὡς πλεονάσαντα τῆς χρείας, ἀνεδούλωσαν τοῖς παισὶ τοῦ προγεγραμμένου.", "st": "4.29"}, {"sp": "N", "t": "περὶ μὲν δὴ τοὺς ἄνδρας τοιάδε ἐγίγνετο, ἥψατο δὲ καὶ ὀρφανῶν διὰ πλοῦτον ἡ τότε τύχη. καὶ ὁ μὲν ἐς διδασκάλου φοιτῶν αὐτῷ παιδαγωγῷ συνανῃρέθη, τὸν παῖδα περισχομένῳ τε καὶ οὐ μεθιέντι· Ἀτίλιος δὲ ἄρτι τὴν τῶν τελείων περιθέμενος στολὴν ᾔει μέν, ὡς ἔθος ἐστί, σὺν πομπῇ φίλων ἐπὶ θυσίας ἐς τὰ ἱερά, ἄφνω δὲ ἐγγραφέντος αὐτοῦ τοῖς πίναξιν οἱ φίλοι καὶ οἱ θεράποντες διεδίδρασκον. ὁ δὲ μόνος καὶ ἔρημος ἐκ δαψιλοῦς παραπομπῆς ἐς τὴν μητέρα ἐχώρει· οὐ δεξαμένης δὲ αὐτὸν οὐδὲ ἐκείνης ὑπὸ δέους, οὐκ ἀξιώσας ἔτι ἐς πεῖραν ἐλθεῖν ἑτέρου μετὰ μητέρα, ἐς ὄρος ἔφυγεν· ὅθεν ὑπὸ λιμοῦ ἐς τὰ πεδινὰ κατελθὼν ἐλήφθη πρὸς ἀνδρὸς λῃστεύειν τοὺς παροδεύοντας καὶ ἐπὶ ἔργῳ καταδεῖν εἰθισμένου. οἷα δὲ παῖς ἐκ τρυφῆς τὸν πόνον οὐκ ἐνεγκὼν ἐς τὴν ἁμαξιτὸν αὐταῖς χοινικίσι διέδρα καὶ παροδεύουσι λοχαγοῖς ἑαυτὸν ἐμήνυσέ τε καὶ ἀνῃρέθη.", "st": "4.30"}, {"sp": "N", "t": "γιγνομένων δὲ τούτων Λέπιδος ἐπὶ Ἴβηρσιν ἐθριάμβευε, καὶ προυτέθη διάγραμμα οὕτως ἔχον· “ἀγαθῇ τύχῃ προειρήσθω πᾶσι καὶ πάσαις θύειν καὶ εὐωχεῖσθαι τὴν ἡμέραν τὴν παροῦσαν· ὃς δ’ ἂν μὴ φαίνηται ταῦτα ποιῶν, ἐν τοῖς προγεγραμμένοις ἔσται.” ὁ μὲν δὴ τὸν θρίαμβον ἐς τὰ ἱερὰ ἀνῆγε, παραπεμπόντων αὐτὸν ἁπάντων μετὰ σχήματος ἱλαροῦ καὶ γνώμης δυσμενοῦς· τῶν δὲ προγεγραμμένων τὰ μὲν ἐν ταῖς οἰκίαις διεφορεῖτο, καὶ οὐ πολὺς ἦν ὁ τὰ χωρία ὠνούμενος, οἱ μὲν ἐπιβαρεῖν τοῖς ἠτυχηκόσιν αἰδούμενοι καὶ οὐκ ἐν αἰσίῳ σφίσι τὰ ἐκείνων ἔσεσθαι νομίζοντες οὐδὲ ἀσφαλὲς ὅλως χρυσίον ἢ ἀργύριον ἔχοντας ὁρᾶσθαι οὐδὲ τὰς ἐπικτήσεις νῦν ἀκινδύνους, πολὺ δὲ μᾶλλον τὰ ὄντα ἐπικίνδυνα. μόνοι δὲ οἱ διὰ θρασύτητα προσιόντες, ἅτε μόνοι, βραχυτάτου πάμπαν ὠνοῦντο. ὅθεν τοῖς ἄρχουσιν, ἐλπίσασιν ἐς τὰς τοῦ πολέμου παρασκευὰς τάδε ἀρκέσειν, ἐνέδει μυριάδων ἔτι δισμυρίων.", "st": "4.31"}, {"sp": "N", "t": "καὶ τοῦτο ἐς τὸν δῆμον εἰπόντες προύγραφον χιλίας καὶ τετρακοσίας γυναῖκας, αἳ μάλιστα πλούτῳ διέφερον· καὶ αὐτὰς ἔδει, τὰ ὄντα τιμωμένας, ἐσφέρειν ἐς τὰς τοῦ πολέμου χρείας, ὅσον ἑκάστην οἱ τρεῖς δοκιμάσειαν. ἐπέκειτό τε ταῖς ἀποκρυψαμέναις τι τῶν ὄντων, ἢ τιμησαμέναις κακῶς ἐπιτίμια καὶ τοῖς ταῦτα μηνύουσιν ἐλευθέροις τε καὶ δούλοις μήνυτρα. αἱ δὲ γυναῖκες ἔκριναν τῶν προσηκουσῶν τοῖς ἄρχουσι γυναικῶν δεηθῆναι. τῆς μὲν δὴ Καίσαρος ἀδελφῆς οὐκ ἀπετύγχανον, οὐδὲ τῆς μητρὸς Ἀντωνίου· Φουλβίας δέ, τῆς γυναικὸς Ἀντωνίου, τῶν θυρῶν ἀπωθούμεναι χαλεπῶς τὴν ὕβριν ἤνεγκαν, καὶ ἐς τὴν ἀγορὰν ἐπὶ τὸ βῆμα τῶν ἀρχόντων ὠσάμεναι, διισταμένων τοῦ τε δήμου καὶ τῶν δορυφόρων, ἔλεγον, Ὁρτησίας ἐς τοῦτο προκεχειρισμένης·", "st": "4.32"}, {"sp": "N", "t": "“ὃ μὲν ἥρμοζε δεομέναις ὑμῶν γυναιξὶ τοιαῖσδε, ἐπὶ τὰς γυναῖκας ὑμῶν κατεφύγομεν· ὃ δὲ οὐχ ἥρμοζεν, ὑπὸ Φουλβίας παθοῦσαι, ἐς τὴν ἀγορὰν συνεώσμεθα ὑπ’ αὐτῆς. ὑμεῖς δ’ ἡμᾶς ἀφείλεσθε μὲν ἤδη γονέας τε καὶ παῖδας καὶ ἄνδρας καὶ ἀδελφοὺς ἐπικαλοῦντες, ὅτι πρὸς αὐτῶν ἠδίκησθε· εἰ δὲ καὶ τὰ χρήματα προσαφέλοισθε, περιστήσετε ἐς ἀπρέπειαν ἀναξίαν γένους καὶ τρόπων καὶ φύσεως γυναικείας. εἰ μὲν δή τι καὶ πρὸς ἡμῶν, οἷον ὑπὸ τῶν ἀνδρῶν, ἠδικῆσθαί φατε, προγράψατε καὶ ἡμᾶς ὡς ἐκείνους. εἰ δὲ οὐδένα ὑμῶν αἱ γυναῖκες οὔτε πολέμιον ἐψηφισάμεθα οὔτε καθείλομεν οἰκίαν ἢ στρατὸν διεφθείραμεν ἢ ἐπηγάγομεν ἕτερον ἢ ἀρχῆς ἢ τιμῆς τυχεῖν ἐκωλύσαμεν, τί κοινωνοῦμεν τῶν κολάσεων αἱ τῶν ἀδικημάτων οὐ μετασχοῦσαι;", "st": "4.32"}, {"sp": "N", "t": "“τί δὲ ἐσφέρωμεν αἱ μήτε ἀρχῆς μήτε τιμῆς μήτε στρατηγίας μήτε τῆς πολιτείας ὅλως, τῆς ὑμῖν ἐς τοσοῦτον ἤδη κακοῦ περιμαχήτου, μετέχουσαι; ὅτι φατὲ πόλεμον εἶναι; καὶ πότε οὐ γεγόνασι πόλεμοι; καὶ πότε γυναῖκες συνεισήνεγκαν; ἃς ἡ μὲν φύσις ἀπολύει παρὰ ἅπασιν ἀνθρώποις, αἱ δὲ μητέρες ἡμῶν ὑπὲρ τὴν φύσιν ἐσήνεγκάν ποτε ἅπαξ, ὅτε ἐκινδυνεύετε περὶ τῇ ἀρχῇ πάσῃ καὶ περὶ αὐτῇ τῇ πόλει, Καρχηδονίων ἐνοχλούντων. καὶ τότε δὲ ἐσήνεγκαν ἑκοῦσαι, καὶ οὐκ ἀπὸ γῆς ἢ χωρίων ἢ προικὸς ἢ οἰκιῶν, ὧν χωρὶς ἀβίωτόν ἐστιν ἐλευθέραις, ἀλλὰ ἀπὸ μόνων τῶν οἴκοι κόσμων, οὐδὲ τούτων τιμωμένων οὐδὲ ὑπὸ μηνυταῖς ἢ κατηγόροις οὐδὲ πρὸς ἀνάγκην ἢ βίαν, ἀλλ’ ὅσον ἐβούλοντο αὐταί. τίς οὖν καὶ νῦν ἐστιν ὑμῖν περὶ τῆς ἀρχῆς ἢ περὶ τῆς πατρίδος φόβος; ἴτω τοίνυν ἢ Κελτῶν πόλεμος ἢ Παρθυαίων, καὶ οὐ χείρους ἐς σωτηρίαν ἐσόμεθα τῶν μητέρων. ἐς δὲ ἐμφυλίους πολέμους μήτε ἐσενέγκαιμέν ποτε μήτε συμπράξαιμεν ὑμῖν κατ’ ἀλλήλων. οὐδὲ γὰρ ἐπὶ Καίσαρος ἢ Πομπηίου συνεφέρομεν, οὐδὲ Μάριος ἡμᾶς οὐδὲ Κίννας ἠνάγκασεν οὐδὲ Σύλλας, ὁ τυραννήσας τῆς πατρίδος· ὑμεῖς δέ φατε καὶ καθίστασθαι τὴν πολιτείαν.”", "st": "4.33"}, {"sp": "N", "t": "τοιαῦτα τῆς Ὁρτησίας λεγούσης, οἱ τρεῖς ἠγανάκτουν, εἰ γυναῖκες ἀνδρῶν ἡσυχαζόντων θρασυνοῦνταί τε καὶ ἐκκλησιάσουσι, καὶ τὰ δρώμενα τοῖς ἄρχουσιν ἐξετάσουσι, καὶ τῶν ἀνδρῶν στρατευομένων αὐταὶ οὐδὲ χρήματα ἐσοίσουσιν· ἐκέλευόν τε τοῖς ὑπηρέταις ἐξωθεῖν αὐτὰς ἀπὸ τοῦ βήματος, μέχρι βοῆς ἔξωθεν ἐκ τοῦ πλήθους γενομένης οἵ τε ὑπηρέται τὸ ἔργον ἐπέσχον καὶ οἱ ἄρχοντες ἔφασαν ἐς τὴν ὑστεραίαν ἀνατίθεσθαι. τῇ δ’ ὑστεραίᾳ τετρακοσίας μὲν ἀντὶ χιλίων καὶ τετρακοσίων προύγραφον ἀποτιμᾶσθαι τὰ ὄντα, τῶν δὲ ἀνδρῶν πάντα τὸν ἔχοντα πλείους δέκα μυριάδων, ἀστὸν ὁμοῦ καὶ ξένον καὶ ἀπελεύθερον καὶ ἱερέα καὶ πανταεθνῆ, μηδενὸς ἀφιεμένου, καὶ τούσδε μεθ’ ὁμοίου φόβου τῶν ἐπιτιμίων καὶ ὑπὸ μηνύμασιν ὁμοίοις, ἵνα πεντηκοστὴν μὲν τῶν ὄντων αὐτίκα δανείσαιεν αὑτοῖς, ἐνιαυτοῦ δὲ φόρον ἐς τὸν πόλεμον ἐσενέγκαιεν.", "st": "4.34"}, {"sp": "N", "t": "ἐκ μὲν δὴ τῶν προσταγμάτων τοιαῦτα Ῥωμαίους ἐπεῖχεν, ὁ δὲ στρατὸς σὺν καταφρονήσει χείρονα ἐποίουν. ὡς γὰρ τῶν ἀρχόντων ἐπὶ τοιοῖσδε ἔργοις ἐν σφίσι μόνον τὸ ἀσφαλὲς ἐχόντων, οἱ μὲν αὐτοὺς ᾐτοῦντο τῶν δεδημευμένων οἰκίαν ἢ ἀγρὸν ἢ ἔπαυλιν ἢ ὅλον κλῆρον, οἱ δ’ αὖ παῖδας ἀνδράσι θετοὺς γενέσθαι· οἱ δὲ ἀφ’ ἑαυτῶν ἕτερα ἔδρων, κτιννύντες τε τοὺς οὐ προγεγραμμένους καὶ οἰκίας οὐδὲν ὑπαιτίων διαφοροῦντες. ὥστε καὶ τοὺς ἄρχοντας προγράψαι τῶν ὑπάτων τὸν ἕτερον ἐπιστροφήν τινα ποιήσασθαι τῶν ὑπὲρ τὸ πρόσταγμα γιγνομένων. ὁ δὲ τῶν μὲν ὁπλιτῶν ἔδεισεν ἅψασθαι, μὴ σφᾶς ἐφ’ ἑαυτὸν παροξύνῃ, τῶν δὲ θεραπόντων τινάς, οἳ σχήματι στρατιωτῶν συνεξημάρτανον ἐκείνοις, λαβὼν ἐκρέμασε.", "st": "4.35"}, {"sp": "N", "t": "καὶ τὰ μὲν ἐς τέλος τῶν συμφορῶν τοῖς προγεγραμμένοις ἀπαντῶντα τοιάδε μάλιστα ἦν· ὅσα δὲ ἐκ παραλόγου τισὶν ἐγίγνετο ἔς τε τὴν σωτηρίαν αὐτίκα καὶ ἐς ἀξίωσιν ὕστερον, ἐμοί τε ἥδιον εἰπεῖν καὶ τοῖς ἀκούουσιν ὠφελιμώτερον ἐς μηδὲν ἀποκάμνοντας ἐλπίζειν περιέσεσθαι. αἱ μὲν οὖν φυγαὶ τοῖς δυναμένοις ἦσαν ἐς Κάσσιον ἢ Βροῦτον ἢ ἐς Λιβύην ἐπὶ Κορνιφίκιον, καὶ τόνδε τῆς δημοκρατίας μεταποιούμενον· ὁ δὲ πολὺς ἐς Σικελίαν ᾔει, γειτονεύουσαν τῆς Ἰταλίας, καὶ Πομπηίου σφᾶς προθύμως ὑποδεχομένου. λαμπροτάτην γὰρ δὴ σπουδὴν ἐς τοὺς ἀτυχοῦντας ὁ Πομπήιος ἐν καιρῷ τότε ἔδειξε, κήρυκάς τε περιπέμπων, οἳ πάντας ἐς αὐτὸν ἐκάλουν, καὶ τοῖς περισῴζουσιν αὐτοὺς ἐλευθέροις τε καὶ θεράπουσι προλέγων διπλάσια τῶν διδομένων τοῖς αἱροῦσι· λέμβοι τε αὐτοῦ καὶ στρογγύλα ὑπήντα τοῖς πλέουσι, καὶ τριήρεις τους αἰγιαλοὺς ἐπέπλεον, σημεῖά τε ἀνίσχουσαι τοῖς ἀλωμένοις, καὶ τὸν ἐντυγχάνοντα περισῳζουσαι. αὐτός τε τοῖς ἀφικνουμένοις ἀπήντα καὶ ἐσθῆτος αὐτίκα καὶ κατασκευῆς ἐμερίζετο· τοῖς δὲ ἀξίοις καὶ ἐς στρατηγίας ἢ ναυαρχίας ἐχρῆτο. σπονδῶν τέ οἱ πρὸς τοὺς τρεῖς γιγνομένων ὕστερον, οὐ συνέθετο, πρὶν καὶ τούσδε τοὺς εἰς αὐτὸν διαφυγόντας ἐς ταύτας περιλαβεῖν. ὁ μὲν δὴ χρησιμώτατος οὕτως ἀτυχούσῃ τῇ πατρίδι ἐγίγνετο, καὶ δόξαν ἐκ τοῦδε ἀγαθήν, ἴδιον ἐπὶ τῇ πατρῴᾳ καὶ οὐχ ἥσσονα τήνδε ἐκείνης, προσελάμβανεν· ἕτεροι δὲ ἑτέρως φυγόντες ἢ κρυπτόμενοι μέχρι τῶν σπονδῶν, οἱ μὲν ἐν χωρίοις ἢ τάφοις, οἱ δὲ ἐν αὐτῷ ἄστει, σὺν ἐπινοίαις οἰκτραῖς διεγένοντο. φιλανδρίαι τε παράδοξοι γυναικῶν ὤφθησαν καὶ παίδων ἐς πατέρας εὔνοιαι καὶ θεραπόντων ὑπὲρ φύσιν ἐς δεσπότας. καὶ τῶνδε ὅσα παραδοξότατα, ἀναγράψω.", "st": "4.36"}, {"sp": "N", "t": "Παῦλος, ὁ ἀδελφὸς Λεπίδου, τῶν λοχαγῶν αὐτὸν ὡς ἀδελφὸν αὐτοκράτορος αἰδουμένων, ἐπὶ ἀδείας ἐξέπλευσεν ἐς Βροῦτον καὶ ἐς Μίλητον μετὰ Βροῦτον· ὅθεν οὐδὲ εἰρήνης ὕστερον γενομένης καλούμενος ἐπανελθεῖν ἠξίωσε. Λεύκιον δέ, τὸν Ἀντωνίου θεῖον, ἡ Ἀντωνίου μήτηρ ἀδελφὸν ὄντα εἶχεν οὐδ’ ἐπικρύπτουσα, αἰδουμένων ἐς πολὺ καὶ τήνδε τῶν λοχαγῶν ὡς μητέρα αὐτοκράτορος. βιαζομένων δ’ ὕστερον ἐξέθορεν ἐς τὴν ἀγορὰν καὶ προκαθημένῳ τῷ Ἀντωνίῳ μετὰ τῶν συνάρχων ἔφη· “ἐμαυτήν, ὦ αὐτοκράτορ, μηνύω σοι Λεύκιον ὑποδεδέχθαι τε καὶ ἔχειν ἔτι καὶ ἕξειν, ἕως ἂν ἡμᾶς ὁμοῦ κατακάνῃς· τὰ γὰρ ὅμοια καὶ τοῖς ὑποδεδεγμένοις ἐπικεκήρυκται.” ὁ δὲ αὐτὴν ἐπιμεμψάμενος ὡς ἀδελφὴν μὲν ἀγαθήν, μητέρα δὲ οὐκ εὐγνώμονα (οὐ γὰρ νῦν χρῆναι περισῴζειν Λεύκιον, ἀλλὰ κωλύειν. ὅτε σου τὸν υἱὸν εἶναι πολέμιον ἐψηφίζετο), παρεσκεύασεν ὅμως Πλάγκον ὑπατεύοντα κάθοδον τῷ Λευκίῳ ψηφίσασθαι.", "st": "4.37"}, {"sp": "N", "t": "Μεσσάλας δὲ ἐπιφανὴς καὶ νέος ἐς Βροῦτον ἔφυγε, καὶ αὐτοῦ δείσαντες οἱ τρεῖς τὸ φρόνημα προύγραψαν οὕτως· “ἐπεὶ Μεσσάλαν ἀπέφηναν ἡμῖν οἱ προσήκοντες αὐτῷ μηδὲ ἐπιδημεῖν, ὅτε Γάιος Καῖσαρ ἀνῃρεῖτο, ἐξῃρήσθω τῶν προγραφέντων ὁ Μεσσάλας.” ὁ δὲ τὴν μὲν συγγνώμην οὐκ ἐδέξατο, Βρούτου δὲ καὶ Κασσίου περὶ Θρᾴκην πεσόντων καὶ τοῦ στρατοῦ πολλοῦ τε ἔτι ὄντος καὶ ναῦς καὶ χρήματα καὶ ἐλπίδας ἔχοντος οὐκ ἀσθενεῖς, ἄρχειν σφῶν τὸν Μεσσάλαν αἱρουμένων οὐκ ἀνασχόμενος, ἔπεισεν αὐτοὺς ἐνδόντας ἐπιβαρούσῃ τῇ τύχῃ μεταστρατεύσασθαι τοῖς ἀμφὶ τὸν Ἀντώνιον. οἰκειότερος δὲ ὢν Ἀντωνίῳ συνῆν, μέχρι κρατούσης Ἀντωνίου Κλεοπάτρας ἐπιμεμψάμενος ἐς Καίσαρα μετῆλθεν. ὁ δὲ αὐτὸν ὕπατόν τε ἀπέφηνεν ἀντὶ αὐτοῦ Ἀντωνίου, ἀποχειροτονηθέντος, ὅτε αὖθις ἐψηφίζετο εἶναι πολέμιος, καὶ περὶ Ἄκτιον ναυαρχήσαντα κατὰ τοῦ Ἀντωνίου στρατηγὸν ἔπεμψεν ἐπὶ Κελτοὺς ἀφισταμένους καὶ νικήσαντι ἔδωκε θριαμβεῦσαι.", "st": "4.38"}, {"sp": "N", "t": "Βύβλος δὲ ἐσπείσατο ἅμα τῷ Μεσσάλᾳ καὶ ἐναυάρχησεν Ἀντωνίῳ διαλλαγάς τε πολλάκις Ἀντωνίῳ καὶ Καίσαρι ἐς ἀλλήλους ἐπόρθμευσε καὶ στρατηγὸς ἀπεδείχθη Συρίας ὑπὸ Ἀντωνίου καὶ στρατηγῶν ἔτι αὐτῆς ἀπέθανεν.", "st": "4.38"}, {"sp": "N", "t": "Ἀκίλιος δὲ ἔφευγε μὲν τῆς πόλεως λαθών, οἰκέτου δ’ αὐτὸν ἐμφήναντος ὁπλίταις, τοὺς ὁπλίτας ἔπεισεν ἐλπίδι χρημάτων πλεόνων πέμψαι τινὰς ἀπὸ σφῶν πρὸς τὴν γυναῖκα μετὰ συμβόλων ὧν αὐτὸς ἐδίδου. ἡ δὲ τοῖς ἐλθοῦσιν τὸν κόσμον αὑτῆς ἅπαντα προθεῖσα ἔφη διδόναι μὲν ὡς ἀντιδώσουσιν, ἃ ὑπέσχοντο, οὐκ εἰδέναι δέ, εἰ ἀντιδώσουσιν. οὐ μὴν ἐψεύσθη τῆς φιλανδρίας· οἱ γὰρ ὁπλῖται καὶ ναῦν ἐμίσθωσαν τῷ Ἀκιλίῳ καὶ προύπεμψαν ἐς Σικελίαν. Λέντλος δέ, ἀξιούσης αὐτῷ συμφεύγειν τῆς γυναικὸς καὶ ἐς τοῦτο αὐτὸν ἐπιτηρούσης, οὐκ ἐθέλων αὐτὴν συγκινδυνεύειν ἑαυτῷ, λαθὼν ἔφυγεν ἐς Σικελίαν, στρατηγὸς δὲ ἀποδειχθεὶς ὑπὸ Πομπηίου ἐσήμηνεν, ὅτι σῴζοιτο καὶ στρατηγοίη. ἡ δ’, ὅποι γῆς ἐστιν ὁ ἀνήρ, ἐπιγνοῦσα τὴν μητέρα φυλάσσουσαν ἐξέφυγε καὶ ἥδε σὺν θεράπουσι δύο· μεθ’ ὧν ὥδευεν ἐπιμόχθως καὶ εὐτελῶς οἷα θεράπαινα, μέχρι διέπλευσεν ἐς Μεσσήνην ἀπὸ Ῥηγίου περὶ ἑσπέραν. καὶ οὐ δυσχερῶς τὴν στρατηγίδα σκηνὴν μαθοῦσα, εὗρε τὸν Λέντλον οὐχ οἷα στρατηγόν, ἀλλ’ ἐν χαμευνίῳ καὶ κόμῃ καὶ διαίτῃ πονηρᾷ πόθῳ τῆς γυναικός.", "st": "4.39"}, {"sp": "N", "t": "Ἀπουληίῳ δὲ ἠπείλησεν ἡ γυνὴ καταμηνύσειν αὐτόν, εἰ μόνος φεύγοι· καὶ ὁ μὲν ἄκων αὐτὴν ἐπήγετο, συνήνεγκε δὲ ἐς τὴν φυγὴν αὐτῷ τὸ ἀνύποπτον, ἅμα γυναικὶ καὶ θεράπουσι καὶ θεραπαίναις ὁδεύοντι φανερῶς. Ἄντιον δὲ ἡ γυνὴ στρωματοδέσμῳ κατείλησε καὶ ἐπέθηκε τοῖς μισθοῦ φέρουσι καὶ διήνεγκεν ἀπὸ τῆς οἰκίας ἐπὶ θάλασσαν, ὅθεν ἔφυγεν ἐς Σικελίαν. Ῥηγῖνον δὲ ἡ γυνὴ νυκτὸς ἐς ὑπόνομον λυμάτων καθῆκεν, ἐς ὃν ἡμέρας οὐχ ὑποστάντων ἐμβῆναι τῶν ὁπλιτῶν διὰ δυσοδμίαν, νυκτὸς ἄλλης εἰς ἀνθρακέα ἐσκεύασε καὶ ὄνον ἄνθρακας φέροντα ἐλαύνειν ἔδωκεν· αὐτὴ δὲ ἐκ βραχέος διαστήματος ἡγεῖτο φορείῳ φερομένη. τῶν δὲ ἀμφὶ τὰς πύλας ὁπλιτῶν τινος τὸ φορεῖον ὑπονοήσαντός τε καὶ ἐρευνωμένου, δείσας ὁ Ῥηγῖνος ἐπέδραμε καὶ ὡς ὁδῷ χρώμενος ἠξίου τὸν ὁπλίτην φείδεσθαι γυναικῶν. ὁ δὲ αὐτὸν ὡς ἀνθρακέα μετ’ ὀργῆς ἀμειβόμενος ἐγνώρισεν (ἐστράτευτο γὰρ ὑπ’ αὐτῷ ποτε ἐν Συρίᾳ) καὶ “ἄπιθι χαίρων,” εἶπεν, “αὐτοκράτορ· τοῦτο γάρ μοι προσήκει καὶ νῦν καλεῖν σε.” Κοπώνιον δὲ τὸ γύναιον ᾔτησε παρὰ Ἀντωνίου, σώφρων μὲν οὖσα τέως, ἀτυχήματι δὲ τὸ ἀτύχημα ἰωμένη.", "st": "4.40"}, {"sp": "N", "t": "Γέταν δὲ ὁ υἱὸς ἐν εὐρυχώρῳ τῆς οἰκίας ἔδοξε καίειν ὡς ἀπαγξάμενον καὶ λαθὼν ἐν ἀγρῷ νεωνήτῳ κατέλιπεν, ἔνθα ὁ πρεσβύτης μεταμορφῶν ἑαυτὸν ἐπεδήσατο διφθέραν ἐς τὸν ἕτερον ὀφθαλμόν. καὶ τῶν σπονδῶν γενομένων ἔλυσε τὴν διφθέραν, καὶ ὁ ὀφθαλμὸς ὑπὸ τῆς ἀργίας δεδαπάνητο. Ὄππιον δὲ ὁ υἱός, ὑπὸ γήρως ἀσθενεστάτου μένειν ἐθέλοντα, ἔφερεν ἐπὶ τοῦ σώματος, ἕως ἐξήγαγέ τε διὰ τῶν πυλῶν καὶ τὸ λοιπὸν μέχρι Σικελίας ἄγων ἢ φέρων ἐκόμισεν, οὐδενὸς ἄρα τὸ σχῆμα ὑπονοήσαντος ἢ ἐνυβρίσαντος, οἷόν που καὶ τὸν Αἰνείαν γράφουσιν αἰδέσιμον τοῖς πολεμίοις γενέσθαι φέροντα τὸν πατέρα. καὶ τὸν νεανίαν ὁ δῆμος ἐπαινῶν ὕστερον ἀπέφηνεν ἀγορανόμον· δεδημευμένης δ’ αὐτῷ τῆς οὐσίας οὐκ ἔχοντι τῆς ἀρχῆς τὸ δαπάνημα οἵ τε χειροτέχναι τὰ ἐς τὴν ἀρχὴν ἀμισθὶ συνειργάσαντο, καὶ τῶν θεωμένων ἕκαστος ἐπὶ τὴν ὀρχήστραν ὅσον ἐβούλετο νόμισμα ἐρρίπτει, ἕως τὸν ἄνδρα κατεπλούτισαν. Ἀρριανοῦ δὲ καὶ ἐν τῇ στήλῃ κεκόλαπτο ἐκ διαθηκῶν· “τὸν ἐνθάδε κείμενον υἱὸς οὐ προγραφεὶς προγραφέντα ἔκρυψέ τε καὶ συνέφυγε καὶ περιέσωσε.”", "st": "4.41"}, {"sp": "N", "t": "Μετέλλω δὲ ἤστην υἱός τε καὶ πατήρ· καὶ αὐτοῖν ὁ μὲν πατὴρ στρατηγῶν Ἀντωνίῳ περὶ Ἄκτιον αἰχμάλωτος ἑάλω καὶ ἠγνοεῖτο, ὁ δὲ υἱὸς τῷ Καίσαρι συνεστρατεύετο καὶ ἐστρατηγήκει καὶ ὅδε περὶ τὸ Ἄκτιον. ἐν δὲ Σάμῳ διακρίνοντι τῷ Καίσαρι τοὺς αἰχμαλώτους ὁ μὲν παῖς συνήδρευεν, ὁ δὲ πρεσβύτης ἤγετο κόμης τε ἔμπλεως καὶ δύης καὶ ῥύπου καὶ τῆς ἐκ τῶνδε μεταμορφώσεως. ὡς δὲ ἐν τῇ τάξει τῶν αἰχμαλώτων ὑπὸ τοῦ κήρυκος ἀνεκλήθη, ἀνέθορεν ὁ υἱὸς ἐκ τοῦ συνεδρίου καὶ μόλις ἐπιγνοὺς τὸν πατέρα ἠσπάζετο σὺν οἰμωγῇ· ἐπισχὼν δέ ποτε τοῦ θρήνου πρὸς τὸν Καίσαρα ἔφη· “οὗτος μέν σοι πολέμιος γέγονεν, ὦ Καῖσαρ, ἐγὼ δὲ σύμμαχος· καὶ χρὴ τοῦτον μέν σοι δοῦναι δίκην, ἐμὲ δὲ γέρας εὑρέσθαι. αἰτῶ δή σε τὸν πατέρα σῴζειν δι’ ἐμὲ ἢ δι’ ἐκεῖνον ἐμὲ συγκατακανεῖν.” οἴκτου δὲ ἐξ ἁπάντων γενομένου μεθῆκε σῴζεσθαι τὸν Μέτελλον ὁ Καῖσαρ, καίτοι πολεμιώτατον αὐτῷ γενόμενον καὶ δωρεῶν πολλῶν, εἰ μεταθοῖτο πρὸς αὐτὸν ἀπ’ Ἀντωνίου, πολλάκις ὑπεριδόντα.", "st": "4.42"}, {"sp": "N", "t": "Μᾶρκον δὲ οἱ θεράποντες σὺν εὐνοίᾳ καὶ τύχῃ πάντα τὸν τῆς προγραφῆς χρόνον διεφύλαξαν ἔνδον ἐπὶ τῆς οἰκίας, μέχρι τῆς ἀδείας δοθείσης ὁ Μᾶρκος ἐξῄει τῆς οἰκίας ὡς ἀπὸ φυγῆς. Ἵρτιος δὲ σὺν τοῖς οἰκέταις ἐκφυγὼν τῆς πόλεως διώδευε τὴν Ἰταλίαν, ἐκλύων τε δεσμώτας καὶ συνάγων τοὺς ἀποδιδράσκοντας καὶ πολίχνια δῃῶν, ὀλίγα πρῶτον, εἶτα καὶ μείζω, μέχρι χειρὸς ἱκανῆς ἐκράτησε καὶ τὸ Βρεττίων ἔθνος ἐχειρώσατο καί, στρατοῦ πεμφθέντος ἐπ’ αὐτόν, ἐς Πομπήιον μεθ’ ὅσων εἶχε διέπλευσε.", "st": "4.43"}, {"sp": "N", "t": "Ῥεστίωνι δὲ οἰομένῳ μόνῳ φεύγειν οἰκέτης εἵπετο λανθάνων, ἀνάθρεπτος μὲν αὐτοῦ Ῥεστίωνος καὶ πολλὰ πρότερον εὖ παθών, διὰ δὲ μοχθηρίαν ὕστερον ἐστιγμένος. ἀναπαυομένῳ δὲ ἐν ἕλει τῷ Ῥεστίωνι ἐπιστὰς ὁ θεράπων ἐξέπληξε μὲν αὐτίκα ὀφθείς, δεδοικότι δὲ ἔφη οὐ τῶν παρόντων στιγμάτων αἰσθάνεσθαι μᾶλλον ἢ μνημονεύειν τῶν πρότερον εὐεργετημάτων. καὶ αὐτὸν εἴς τι σπήλαιον ἀναπαύσας εἰργάζετο καὶ τροφὰς αὐτῷ συνέλεγεν, ὡς ἐδύνατο. ὑπονοίας δέ τινος ἀμφὶ τὸ σπήλαιον τοῖς ἐγγὺς ὁπλίταις περὶ τοῦ Ῥεστίωνος γενομένης καὶ χωρούντων ἐπ’ αὐτόν, ὁ οἰκέτης εἵπετο συνεὶς καί τινα πρεσβύτην προοδεύοντα προδραμὼν ἀπέκτεινε καὶ τὴν κεφαλὴν ἀπέτεμεν. ἐκπλαγέντων δὲ τῶν ὁπλιτῶν καὶ ὡς ἀνδροφόνον ὁδοιπόρου περισχόντων, “Ῥεστίωνα,” ἔφη, “ἔκτεινα, τὸν ἐμαυτοῦ δεσπότην, τάδε μοι τὰ στίγματα ἐγχαράξαντα.” οἱ μὲν δὴ τὴν κεφαλὴν αὐτὸν ἀφελόμενοι διὰ τὸ γέρας, ἠπείγοντο μάτην ἐς τὸ ἄστυ, ὁ δὲ τὸν δεσπότην ἀναστήσας διέπλευσεν ἐς Σικελίαν.", "st": "4.43"}, {"sp": "N", "t": "Ἄππιον δὲ ἀναπαυόμενον ἐν ἐπαύλει, τῶν ὁπλιτῶν ἐπιθεόντων, οἰκέτης τὴν ἑαυτοῦ ἐσθῆτα ἐνέδυσε, καὶ αὐτὸς εἰς τὴν εὐνὴν οἷα δεσπότης ἀνακλιθεὶς ἑκὼν ἀπέθανεν ἀντὶ τοῦ δεσπότου, παρεστῶτος ὡς οἰκέτου. Μενηνίου δὲ τὴν οἰκίαν καταλαβόντων ὁπλιτῶν, θεράπων ἐς τὸ τοῦ δεσπότου φορεῖον ἐνέβη καὶ ὑπὸ τῶν ὁμοδούλων συνεργούντων ἐξεφέρετο, ἕως ὅδε μὲν ὡς Μενήνιος ἑκὼν ἀνῄρητο, Μενήνιος δὲ ἐς Σικελίαν διέφυγεν. Οὐίνιον δὲ ἀπελεύθερος αὐτοῦ Οὐινίου, Φιλήμων, οἰκίαν κεκτημένος λαμπράν, ἐν τῷ μεσαιτάτῳ τῆς οἰκίας ἔκρυψεν ἐν λάρνακι, ἃς ἀπὸ σιδήρου ἐς χρημάτων ἢ βιβλίων ἔχουσι φυλακήν· καὶ νυκτὸς ἔτρεφε μέχρι τῶν σπονδῶν. ἕτερος δὲ ἀπελεύθερος, τάφον δεσπότου φυλάσσων, τὸν δεσπόσυνον προγραφέντα ἐφύλασσεν ἐν τῷ τάφῳ μετὰ τοῦ πατρός.", "st": "4.44"}, {"sp": "N", "t": "Λουκρήτιος ἀλώμενος σὺν δυσὶ θεράπουσιν ἀγαθοῖς ὑπὸ ἀπορίας τῶν τροφῶν ᾔει πρὸς τὴν γυναῖκα, φορείῳ φερόμενος ὑπὸ τῶν οἰκετῶν οἷά τις ἄρρωστος, ἐς τὴν πόλιν. ἑνὸς δὲ τῶν φερόντων τὸ σκέλος συντρίβεντος τῷ ἑτέρῳ τὴν χεῖρα ἐπιθεὶς ᾔει. παρὰ δὲ ταῖς πύλαις γενόμενος, ἔνθα αὐτοῦ καὶ ὁ πατὴρ ὑπὸ Σύλλα προγραφεὶς ἑαλώκει, εἶδε λόχον ὁπλιτῶν ἐκτρέχοντα καὶ πρὸς τὸ συγκύρημα τοῦ τόπου καταπλαγεὶς συνεκρύφθη μετὰ τοῦ θεράποντος ἐν τάφῳ. τυμβωρύχων δὲ τοὺς τάφους ἐρευνωμένων, ὁ θεράπων ἑαυτὸν τοῖς τυμβωρύχοις παρέσχε περιδύειν, μέχρι Λουκρήτιον ἐπὶ τὰς πύλας διαφυγεῖν. ἐκεῖ δὲ αὐτὸν ὁ Λουκρήτιος περιμείνας τε καὶ τῆς ἑαυτοῦ μερισάμενος ἐσθῆτος, ἧκε πρὸς τὴν γυναῖκα καὶ ὑπ’ αὐτῆς ἐκρύπτετο ἐπὶ διπλῆς ὀροφῆς μεταξύ, μέχρι τινὲς αὐτὸν ἐρρύσαντο παρὰ τῶν προγραψάντων καὶ ὕστερον ἐπὶ εἰρήνης ὑπάτευσεν.", "st": "4.44"}, {"sp": "N", "t": "Σέργιος δὲ ἐκρύφθη παρ’ αὐτῷ Ἀντωνίῳ, μέχρι Πλάγκον ὑπατεύοντα ὁ Ἀντώνιος ἔπεισε κάθοδον αὐτῷ ψηφίσασθαι. καὶ ἐπὶ τῷδε ὁ Σέργιος ὕστερον, ἐν τῇ Καίσαρος καὶ Ἀντωνίου στάσει, τῆς βουλῆς ψηφιζομένης εἶναι πολέμιον τὸν Ἀντώνιον, μόνος τὴν ἀπολύουσαν ἔφερε φανερῶς.", "st": "4.45"}, {"sp": "N", "t": "καὶ οἵδε μὲν οὕτως ἐσῴζοντο, Πομπώνιος δὲ εἰς στρατηγοῦ σχῆμα κοσμήσας ἑαυτὸν καὶ τοὺς θεράποντας ἐς ὑπηρέτας σκευάσας τὴν πόλιν ὡς στρατηγὸς ὑπὸ ῥαβδούχοις διῆλθεν, ἐπιθλιβόντων αὐτὸν τῶν ὑπηρετῶν, ἵνα μὴ γνωσθείη πρὸς ἑτέρου, καὶ παρὰ ταῖς πύλαις ὀχημάτων τε δημοσίων ἐπέβη καὶ τὴν Ἰταλίαν διώδευεν, ἀποδεχομένων αὐτὸν καὶ παραπεμπόντων ἁπάντων οἷα στρατηγὸν ὑπὸ τῶν τριῶν ἀνδρῶν ἐπὶ σπονδὰς ἐς Πομπήιον ἀπεσταλμένον, μέχρι καὶ δημοσίᾳ τριήρει διέπλευσε πρὸς ἐκεῖνον.", "st": "4.45"}, {"sp": "N", "t": "Ἀπουλήιος δὲ καὶ Ἀρρούντιος ὑποκριθέντες εἶναι λοχαγοὶ καὶ τοὺς θεράποντας ἐς στρατιώτας σκευάσαντες, τὰς μὲν πύλας διέδραμον ὡς λοχαγοὶ διώκοντες ἑτέρους, τὴν δὲ λοιπὴν ὁδὸν διελόμενοι τοὺς δεσμώτας ἐξέλυον καὶ τοὺς ἀποδράντας συνέλεγον, μέχρι χειρὸς ἱκανῆς ἑκατέρῳ γενομένης σημεῖά τε ἦν ἤδη καὶ ὅπλα καὶ ὄψις στρατοῦ. χωρῶν δὲ ἑκάτερος αὐτῶν ἐπὶ θάλασσαν, ἀμφί τινι λόφῳ σταθμεύουσι, μεγάλῳ δέει καθορῶντες ἀλλήλους. ἅμα δὲ ἕῳ περινεύοντες ἐκ τοῦ λόφου ἔδοξαν ἀλλήλους ἑκάτερος στρατὸν ἐπὶ σφᾶς ἐπιπεμφθέντα εἶναι καὶ συμπλακέντες ἐμάχοντο, μέχρι ποτὲ ἔγνωσαν καὶ τὰ ὅπλα ἀπερρίπτουν καὶ ὠλοφύροντο καὶ τὴν τύχην ὡς ἐπιβαροῦσάν σφισιν ἐς ἅπαντα ἐπεμέμφοντο. διαπλεύσαντες δὲ ὁ μὲν ἐς Βροῦτον, ὁ δ’ ἐς Πομπήιον, ὁ μὲν τῷ Πομπηίῳ συγκατῆλθεν, ὁ δὲ ἐστρατήγησε τῷ Βρούτῳ Βιθυνίας καὶ Βρούτου πεσόντος Ἀντωνίῳ παραδοὺς Βιθυνίαν κατήχθη. Οὐεντίδιον δὲ ἀπελεύθερος εὐθὺς μὲν προγραφέντα κατέδησεν ὡς παραδώσων τοῖς σφαγεῦσι, νυκτὸς δὲ τοὺς θεράποντας ἔπεισε καὶ ἐσκεύασεν ὡς ὁπλίτας καὶ τὸν δεσπότην ὡς λοχαγὸν ἐξήγαγε· τήν τε ἄλλην Ἰταλίαν μέχρι Σικελίας διώδευσαν καὶ συγκατέλυσαν πολλάκις ἑτέροις λοχαγοῖς ζητοῦσιν Οὐεντίδιον.", "st": "4.46"}, {"sp": "N", "t": "ἕτερον ἐν τάφῳ κρύπτων ἀπελεύθερος, οὐ φέροντα φαντασίαν τάφου, μετήγαγεν ἐς φαῦλον οἴκημα μισθωτόν. στρατιώτου δ’ αὐτῷ παρακατοικισθέντος, οὐδὲ τοῦτον φέρων τὸν φόβον ἐς θαυμαστὴν τόλμαν ἐκ δειλίας μετέβαλε καὶ κειράμενος ἡγεῖτο ἐν αὐτῇ Ῥώμῃ διδασκαλείου μέχρι τῶν σπονδῶν. Οὐολούσιος δὲ ἀγορανομῶν προεγράφη καὶ φίλον ὀργιαστὴν τῆς Ἴσιδος ἔχων ᾔτησε τὴν στολὴν καὶ τὰς ὀθόνας ἐνέδυ τὰς ποδήρεις καὶ τὴν τοῦ κυνὸς κεφαλὴν ἐπέθετο καὶ διῆλθεν οὕτως ὀργιάζων αὐτῷ σχήματι ἐς Πομπήιον. Σίττιον δὲ Καληνοί, πολίτην σφῶν ὄντα καὶ πολλὰ ἐς αὐτοὺς ἐκ περιουσίας δαψιλοῦς ἀναλώσαντα, ἐφύλασσον, σιδηροφοροῦντές τε ὑπὲρ αὐτοῦ καὶ τοῖς οἰκέταις ἀπειλοῦντες καὶ τοὺς στρατιώτας ἀπερύκοντες ἀπὸ τῶν τειχῶν, μέχρι μαραινομένου τοῦ κακοῦ καὶ ἐς τοὺς τρεῖς ἐπρέσβευσαν ὑπὲρ αὐτοῦ καὶ ἔτυχον Σίττιον τῆς ἄλλης Ἰταλίας εἰργόμενον ἐν τῇ πατρίδι μένειν. Σίττιος μὲν δὴ πρῶτος ἢ μόνος ἀνδρῶν ὅδε τῆς ξένης ἐφυγαδεύετο ἐν τῇ πατρίδι, Οὐάρρων δὲ ἦν φιλόσοφός τε καὶ ἱστορίας συγγραφεύς, ἐστρατευμένος τε καλῶς καὶ ἐστρατηγηκώς, καὶ ἴσως διὰ ταῦτα ὡς ἐχθρὸς μοναρχίας προυγράφη. φιλοτιμουμένων δὲ αὐτὸν ὑποδέξασθαι τῶν γνωρίμων καὶ διεριζόντων ἐς ἀλλήλους, Καληνὸς ἐξενίκησε καὶ εἶχεν ἐν ἐπαύλει, ἔνθα Ἀντώνιος, ὅτε διοδεύοι, κατήγετο· καὶ τὸν Οὐάρρωνα οὐδεὶς ἔνδον ὄντα ἐνέφηνε θεράπων, οὔτε αὐτοῦ Οὐάρρωνος οὔτε Καληνοῦ.", "st": "4.47"}, {"sp": "N", "t": "Οὐεργίνιος δέ, ἀνὴρ ἡδὺς εἰπεῖν, τοὺς οἰκέτας ἐδίδασκεν, ὅτι κτείναντες μὲν αὑτὸν δι’ ὀλίγα χρήματα οὐκ ἀσφαλῆ μύσους τε πίμπλανται καὶ φόβων ἐς ὕστερον μεγάλων, περισώσαντες δὲ δόξης τε εὐσεβοῦς καὶ ἐλπίδων ἀγαθῶν καὶ χρημάτων ὕστερον πολὺ πλεόνων τε καὶ ἀσφαλεστέρων. οἱ μὲν δὴ συνέφευγον ὡς ὁμοδούλῳ καὶ γνωρισθέντος αὐτοῦ παρὰ τὴν ὁδὸν πρὸς τοὺς ὁπλίτας ἀπεμάχοντο· ὁ δὲ ληφθεὶς ὑπὸ τῶν ὁπλιτῶν ἐδίδασκε κἀκείνους, ὅτι κατὰ μὲν ἔχθραν αὑτὸν οὐκ ἀνελοῦσιν, ἀλλὰ χρημάτων οὕνεκα μόνων, χρήματα δὲ αὐτοῖς εἴη δικαιότερα καὶ πλέονα λαβεῖν ἐπὶ θάλασσαν ἐλθοῦσιν, “ἔνθα μοι τὸ γύναιον,” ἔφη, “ναῦν φέρουσα χρημάτων συνετάξατο.” καὶ αὐτῷ καὶ οἵδε πεισθέντες κατῄεσαν ἐπὶ τὴν θάλασσαν· ἡ γυνὴ δὲ ἀφῖκτο μὲν ἐπὶ τὴν ἠιόνα κατὰ τὸ συγκείμενον, βραδύνοντος δὲ τοῦ Οὐεργινίου, νομίσασα αὐτὸν ἐς Πομπήιον προπεπλευκέναι ἀνήγετο, θεράποντα ὅμως ἐπὶ τῆς ἠιόνος ἐξαγγέλλειν ὑπολιποῦσα. καὶ ὁ θεράπων τὸν Οὐεργίνιον ἰδὼν ἀνέθορέ τε ὡς ἐς δεσπότην καὶ τὴν ναῦν ἐδείκνυεν ὡς ὁρωμένην καὶ τὴν γυναῖκα ἔφραζε καὶ τὰ χρήματα καὶ αὐτὸς ἐφ’ ὅτῳ κατελείφθη. οἱ δὲ ἐπίστευον ἅπασιν ἤδη, καὶ τὸν Οὐεργίνιον ἀξιοῦντα σφᾶς περιμένειν, ἔστε μετακληθείη τὸ γύναιον, ἢ συνελθεῖν οἱ πρὸς αὐτὴν ἐπὶ τὰ χρήματα, ἐσβάντες ἐς σκάφος παρέπεμπον ἐς Σικελίαν, ἐρέσσοντες φιλοπόνως· ἐκεῖ δὲ ἔτυχόν τε τῶν ἐπαγγελιῶν καὶ οὐκ ἀπέστησαν ἔτι θεραπεύοντες αὐτὸν μέχρι τῶν σπονδῶν.", "st": "4.48"}, {"sp": "N", "t": "Ῥέβιλον δὲ ναύκληρος ἐς τὴν ναῦν ὑποδεξάμενος ὡς διοίσων ἐς Σικελίαν ᾔτει χρήματα, μηνύσειν ἀπειλῶν, εἰ μὴ λάβοι. ὁ δέ, οἷόν τι καὶ Θεμιστοκλῆς φεύγων ἐποίησεν, ἀντηπείλει μηνύσειν, ὅτι αὑτὸν ἐπὶ χρήμασιν ἄγοι, μέχρι δείσας ὁ ναύκληρος διέσωσεν ἐς Πομπήιον.", "st": "4.48"}, {"sp": "N", "t": "Μᾶρκος δὲ Βρούτῳ στρατηγῶν προεγέγραπτο μὲν καὶ ὅδε διὰ τόδε, ἡττωμένου δὲ τοῦ Βρούτου συλλαμβανόμενος ὑπεκρίνατο εἶναι θεράπων, καὶ αὐτὸν ὠνήσατο Βαρβούλας. δεξιὸν δὲ ὁρῶν ἐπέστησε τοῖς ὁμοδούλοις καὶ χρήματα διοικεῖν ἔδωκεν· δεινὸν δὲ ἐν ἅπασι καὶ συνετὸν ὄντα ὑπὲρ θεράποντος φύσιν ὑπενόει καὶ ἐπήλπιζεν, εἰ τῶν προγεγραμμένων τις εἴη, περισώσειν ὁμολογήσαντα. ἀπομαχόμενον δὲ ἰσχυρῶς καὶ γένος ἀναπλάσσοντα καὶ ὄνομα καὶ προτέρους δεσπότας ἐς Ῥώμην ἐπήγετο, ἐλπίσας ὀκνήσειν ἐς Ῥώμην ἀφικέσθαι προγεγραμμένον. ὁ δὲ εἵπετο καὶ ὥς. περὶ δὲ τὰς πύλας τῶν ὑπαντώντων τις φίλων Βαρβούλα, θεασάμενος τὸν Μᾶρκον ὡς οἰκέτην αὐτῷ παρεστῶτα, κρύφα ἐμήνυσε τῷ Βαρβούλᾳ. ὁ δὲ ἐδεήθη Καίσαρος δι’ Ἀγρίππα, καὶ ἀφείθη τῆς προγραφῆς ὁ Μᾶρκος, καὶ φίλος ἐγίγνετο Καίσαρι καὶ μετ’ οὐ πολὺ καὶ στρατηγὸς ἦν ἐπὶ Ἀντωνίῳ περὶ Ἄκτιον. ἐστρατήγει δὲ καὶ Ἀντωνίῳ Βαρβούλας, καὶ ἡ τύχη περιῆλθεν ἐς τὸ ὅμοιον ἀμφοτέροις· Βαρβούλας τε γὰρ ἡττηθέντος Ἀντωνίου λαμβανόμενος ὑπεκρίνατο οἰκέτης εἶναι, καὶ ὁ Μᾶρκος αὐτὸν ὡς ἀγνοῶν ὠνήσατο, ἐκθέμενος δὲ ἅπαντα τῷ Καίσαρι ᾔτησέ τε καὶ ἔτυχε τοῖς ὁμοίοις τὸν Βαρβούλαν ἀμείψασθαι.", "st": "4.49"}, {"sp": "N", "t": "τοῖσδε μὲν οὖν ἡ συντυχία τῶν ὁμοίων καὶ ἐς τὸ ἔπειτα παρέμεινεν· ἦρξαν γὰρ τὴν ἐπώνυμον ἀρχὴν ἐν ἄστει οἱ δύο ὁμοῦ. Βαλβίνῳ δέ, ἐκφυγόντι καὶ κατελθόντι σὺν Πομπηίῳ καὶ ὑπατεύοντι οὐ πολὺ ὕστερον, Λέπιδος ἰδιώτης ὑπὸ Καίσαρος ἐκ δυνάστου γενόμενος ὑπὸ τοιᾶσδε ἀνάγκης παρέστη. Μαικήνας ἐδίωκε τὸν Λεπίδου παῖδα βουλεύσεως ἐπὶ Καίσαρι, ἐδίωκε δὲ καὶ τὴν μητέρα τῷ παιδὶ συνεγνωκέναι· Λεπίδου γὰρ αὐτοῦ ἄρα ὡς ἀσθενοῦς ὑπερεώρα. τὸν μὲν δὴ παῖδα ὁ Μαικήνας ἐς Ἄκτιον ἔπεμπε τῷ Καίσαρι, τὴν δὲ μητέρα, ἵνα μὴ ἄγοιτο οὖσα γυνή, ἐγγύην ᾔτει παρὰ τῷ ὑπάτῳ πρὸς Καίσαρα ἀφίξεσθαι. οὐδενὸς δὲ τὴν ἐγγύην ὑφισταμένου, ὁ Λέπιδος ἀμφὶ τὰς Βαλβίνου θύρας ἐτρίβετο πολλάκις καὶ δικάζοντι παρίστατο καὶ διωθουμένων αὐτὸν ἐς πολὺ τῶν ὑπηρετῶν μόλις εἶπεν· “ἐμοὶ μὲν καὶ οἱ κατήγοροι μαρτυροῦσιν ἐπιείκειαν, οὐδὲ γυναικί με ἢ παιδὶ συγγνῶναι λέγοντες· σὲ δὲ οὐκ ἐγὼ μὲν προέγραψα, κάτω δέ εἰμι τῶν προγραφέντων. ἀλλ’ ἐς τὴν ἀνθρώπειον τύχην ἀφορῶν καὶ ἐς ἐμὲ σοὶ παρεστῶτα, χάρισαί μοι τὴν γυναῖκα ἀπαντήσειν ἐς Καίσαρα ἐγγυωμένῳ ἢ μετ’ ἐκείνης ἀπελθεῖν δεομένῳ.” ταῦτα ἔτι τοῦ Λεπίδου λέγοντος, οὐκ ἐνεγκὼν τὴν μεταβολὴν ὁ Βαλβῖνος ἀπέλυσε τῆς ἐγγύης τὴν γυναῖκα.", "st": "4.50"}, {"sp": "N", "t": "Κικέρων δὲ ὁ Κικέρωνος προαπέσταλτο μὲν ὑπὸ τοῦ πατρὸς ἐς τὴν Ἑλλάδα, τοιάδε ἔσεσθαι προσδοκῶντος· ἀπὸ δὲ τῆς Ἑλλάδος ἐς Βροῦτον καὶ μετὰ Βροῦτον ἀποθανόντα ἐς Πομπήιον ἐλθὼν τιμῆς παρ’ ἑκατέρῳ καὶ στρατηγίας ἠξιοῦτο. ἐπὶ δὲ ἐκείνοις αὐτὸν ὁ Καῖσαρ ἐς ἀπολογίαν τῆς Κικέρωνος ἐκδόσεως ἱερέα τε εὐθὺς ἀπέφηνε καὶ ὕπατον οὐ πολὺ ὕστερον καὶ Συρίας στρατηγόν· καὶ τὴν Ἀντωνίου περὶ Ἄκτιον συμφορὰν ἐπισταλεῖσαν ὑπὸ τοῦ Καίσαρος ὁ Κικέρων ὅδε ὑπατεύων ἀνέγνω τε τῷ δήμῳ καὶ προύθηκεν ἐπὶ τοῦ βήματος, ἔνθα πρότερον ἡ τοῦ πατρὸς αὐτοῦ προύκειτο κεφαλή. Ἄππιος δὲ διένειμε τοῖς θεράπουσιν τὰ ὄντα καὶ μετ’ αὐτῶν ἐς Σικελίαν ἔπλει. χειμῶνος δὲ ἐπιλαβόντος ἐπιβουλεύοντες οἱ θεράποντες τοῖς χρήμασιν ἐς σκάφος ἐνέθεντο τὸν Ἄππιον, ὡς ἐς ἀσφαλεστέραν ἐλπίδα μεταφέροντες. καὶ συνέβη τῷ μὲν ἐκ παραλόγου διαπλεῦσαι, τοῖς δὲ ἀπολέσθαι τῆς νεὼς διαλυθείσης. Πούπλιος δὲ ὁ ταμίας Βρούτου, τῶν ἀμφὶ τὸν Ἀντώνιον αὐτὸν πειθόντων προδοῦναι Βροῦτον οὐκ ἀνασχόμενος, διὰ τόδε καὶ προεγράφη. καὶ κατήχθη καὶ Καίσαρι φίλος ἐγίγνετο καὶ ἐπιόντι ποτὲ τῷ Καίσαρι προύθηκεν εἰκόνας Βρούτου καὶ ἐπῃνέθη καὶ ἐπὶ τῷδε ὑπὸ τοῦ Καίσαρος.", "st": "4.51"}, {"sp": "N", "t": "τὰ μὲν δὴ παρὰ δόξαν τισὶ τῶν προγραφέντων εἴς τε κίνδυνον καὶ σωτηρίαν γενόμενα, πολλὰ καὶ ἄλλα παραλιπόντι τοιάδε μάλιστα ἦν· γιγνομένων δὲ τούτων ἐν Ῥώμῃ, καὶ τὰ ὑπερόρια πάντα πολέμοις διὰ τήνδε τὴν στάσιν ἐδονεῖτο· καὶ τῶν πολέμων οἱ μείζους ἦσαν ἀμφί τε Λιβύην Κορνιφικίου πρὸς Σέξστιον καὶ ἐν Συρίᾳ Κασσίου πρὸς Δολοβέλλαν καὶ περὶ Σικελίαν Πομπηίου. πάθη τε πολλὰ συνηνέχθη πόλεσιν ἐκ δοριαλωσίας, ὑπεριδόντι δὲ τῶν ἐλασσόνων τὰ μέγιστα δὴ καὶ δι’ ἀξίωσιν τῶν ἄλλων περιφανέστατα Λαοδικεῦσι καὶ Ταρσεῦσι καὶ Ῥοδίοις καὶ Παταρεῦσι καὶ Ξανθίοις. καὶ αὐτῶν ἕκαστα, ὡς ἐν κεφαλαίῳ συναγαγόντι φράσαι, τοιάδε ἦν.", "st": "4.52"}, {"sp": "N", "t": "Λιβύης Ῥωμαῖοι τὴν μὲν ἔτι καλοῦσι παλαιάν, ὅσην Καρχηδονίους ἀφείλοντο· ἣν δὲ Ἰόβας εἶχεν, ὕστερόν τε ἔλαβον ἐπὶ Γαΐου Καίσαρος καὶ διὰ τοῦτο νέαν προσαγορεύουσι Λιβύην· εἴη δ’ ἂν τῆς Νομαδικῆς. Σέξστιος οὖν ὑπὸ Καίσαρι τῆς νέας ἡγούμενος ᾔτει Κορνιφίκιον ἐκστῆναί οἱ τῆς παλαιᾶς, ὡς Λιβύης ἁπάσης ἐν τῇ λήξει τῶν τριῶν ἀνδρῶν Καίσαρι νενεμημένης. ὁ δὲ οὔτε τὴν λῆξιν ἔφη γιγνώσκειν τῶν τριῶν ἐφ’ ἑαυτῶν πεποιημένων, οὔτε τὴν ἀρχὴν παρὰ τῆς βουλῆς λαβὼν ἄλλῳ μεθήσειν χωρὶς αὐτῆς· ἐκ μὲν δὴ τούτων ἀλλήλοις ἐπολέμουν, στρατὸν δὲ εἶχεν ὁ μὲν βαρύν τε καὶ πλείονα, ὁ δὲ Σέξστιος κουφότερόν τε καὶ ὀλιγώτερον, ᾧ δὴ καὶ τὰ μεσόγαια τοῦ Κορνιφικίου περιιὼν ἀφίστη καὶ Οὐεντίδιον, στρατηγὸν τοῦ Κορνιφικίου, μετὰ πλειόνων ἐπελθόντα ἀπεμάχετο πολιορκούμενος. ἐδῄου δὲ καὶ Λαίλιος, ἕτερος τοῦ Κορνιφικίου στρατηγός, τὴν Σεξστίου Λιβύην καὶ Κίρταν περικαθήμενος ἐπολιόρκει.", "st": "4.53"}, {"sp": "N", "t": "καὶ πάντες ἐπρέσβευον περὶ συμμαχίας ἔς τε Ἀραβίωνα βασιλέα καὶ τοὺς καλουμένους Σιττιανούς, οἳ ἀπὸ τοιᾶσδε συντυχίας οὕτως ὠνομάζοντο. Σίττιος ἐν Ῥώμῃ δίκην ἰδίαν οὐχ ὑποστὰς ἔφυγε καὶ στρατὸν ἀγείρας ἔκ τε αὐτῆς Ἰταλίας καὶ Ἰβηρίας ἐς Λιβύην διέπλευσε καὶ τοῖς Λιβύων βασιλεῦσι πολεμοῦσιν ἀλλήλοις ἀνὰ μέρος συνεμάχει. ἀεὶ δὲ οἷς προσθοῖτο νικώντων, ὁ Σίττιος ἐπὶ ὀνόματος ἐγίγνετο, καὶ ὁ στρατὸς αὐτῷ γεγύμναστο λαμπρῶς. Γαΐῳ τε Καίσαρι διώκοντι τοὺς Πομπηιανοὺς ἐν Λιβύῃ συνεμάχησε, καὶ Σαβόρραν, Ἰόβα στρατηγὸν διώνυμον, ἀνεῖλε καὶ γέρας τούτων ἔλαβε παρὰ Καίσαρος τὴν Μασανάσσου γῆν, οὐχ ἅπασαν, ἀλλὰ τὸ κράτιστον αὐτῆς. Μασανάσσης δ’ ἦν Ἀραβίωνος τοῦδε πατήρ, Ἰόβα σύμμαχος, καὶ αὐτοῦ τὴν χώραν ὁ Καῖσαρ τῷδε τῷ Σιττίῳ καὶ Βόκχῳ, Μαυρουσίων βασιλεῖ, δεδώρητο· καὶ τὸ μέρος ὁ Σίττιος τοῖς ὑπ’ αὐτὸν ἀνδράσιν ἐπιδιεῖλεν. Ἀραβίων δὲ τότε μὲν ἐς Ἰβηρίαν ἐξέφυγε πρὸς τοὺς παῖδας τοὺς Πομπηίου, Γαΐου δὲ Καίσαρος ἀναιρεθέντος ἐς Λιβύην ἐπανῆλθε, καὶ Λιβύων τινὰς ἀεὶ τῷ νεωτέρῳ Πομπηίῳ πέμπων ἐς Ἰβηρίαν καὶ γεγυμνασμένους ἀπολαμβάνων Βόκχον ἀφῄρητο τὴν. χώραν καὶ Σίττιον ἀνῃρήκει δόλῳ. εὔνους δὲ ὢν τοῖς Πομπηιανοῖς διὰ τάδε, κατεγίνωσκεν ἀεὶ τῆς μοίρας ὡς ἀτυχούσης ἀμειλίκτως καὶ Σεξστίῳ προσέθετο, εὐμενιζόμενος δι’ αὐτοῦ Καίσαρα. προσέθεντο δὲ καὶ οἱ Σιττιανοί, κατ’ εὔνοιαν οἵδε πατρῴαν τοῦ Καίσαρος.", "st": "4.54"}, {"sp": "N", "t": "θαρρήσας οὖν ὁ Σέξστιος ἐξῄει τῆς πολιορκίας ἐς μάχην καὶ πεσόντος τοῦ Οὐεντιδίου καὶ τοῦ στρατοῦ φεύγοντος ὑπ’ ἀναρχίας, εἵπετο κτείνων τε καὶ ζωγρῶν. καὶ τάδε μαθὼν ὁ Λαίλιος διέλυε τὴν τῆς Κίρτης πολιορκίαν καὶ ἐχώρει πρὸς τὸν Κορνιφίκιον. ὁ δὲ Σέξστιος ἐπαιρόμενος τοῖς γεγονόσιν ἐπ’ αὐτὸν ἤδη τὸν Κορνιφίκιον ἐς Ἰτύκην ᾔει καὶ ἀντεστρατοπέδευε μετὰ πλειόνων ὄντι. Λαίλιον δὲ τοῦ Κορνιφικίου μετὰ τῶν ἱππέων πέμψαντος ἔς τινα κατάσκεψιν, ὁ Σέξστιος Ἀραβίωνα ἔπεμψεν ἱππομαχεῖν τῷ Λαιλίῳ κατὰ μέτωπον καὶ αὐτὸς ᾔει μετὰ τῶν εὐζώνων ἐς τὰ πλάγια τῆς ἱππομαχίας καὶ ἐμβαλὼν ἐθορύβει, μέχρι τὸν Λαίλιον οὐχ ἡσσημένον πω δεῖσαι περὶ τῆς ἀναχωρήσεως, μὴ ἀποκλεισθείη, καὶ λόφον ἐν μέσῳ καταλαβεῖν, Ἀραβίωνα δὲ ἀρτώμενον αὐτοῦ κτεῖναί τε πολλοὺς καὶ τὸν λόφον περικυκλῶσαι. ὁρῶν δὲ ταῦτα ὁ Κορνιφίκιος ἐξῄει τῷ πλέονι στρατῷ, βοηθήσων τῷ Λαιλίῳ· καὶ τοῦδε μὲν ὁ Σέξστιος ὄπισθεν γενόμενος ἐξήπτετο συντρέχων, καὶ αὐτὸν ἐπιστρεφόμενος ὁ Κορνιφίκιος ἀπεμάχετο μάλα κακοπαθῶς.", "st": "4.55"}, {"sp": "N", "t": "ὁ δὲ Ἀραβίων ἐν τούτῳ πετροβάταις ἀνδράσιν ἀνέρπουσι διὰ κρημνῶν ἐς τὸ στρατόπεδον τοῦ Κορνιφικίου παρέδυ λαθών. καὶ Ῥώσκιος μὲν ὁ φύλαξ, τοῦ χάρακος ἁλισκομένου, τῶν ὑπασπιστῶν τινι τὴν σφαγὴν ὑπέσχε καὶ ἀνῃρέθη, ὁ δὲ Κορνιφίκιος τῇ μάχῃ κάμνων μετεπήδα πρὸς Λαίλιον ἐς τὸν κολωνόν, οὐκ εἰδώς πω περὶ τοῦ στρατοπέδου· μεταπηδῶντα δ’ αὐτὸν οἱ τοῦ Ἀραβίωνος ἱππέες ἐπιδραμόντες ἔκτειναν. καὶ γιγνόμενα ταῦτα ὁ Λαίλιος ἀπὸ τοῦ λόφου καθορῶν ἑαυτὸν διεχρήσατο. τῶν δ’ ἀρχόντων πεσόντων ὁ στρατὸς κατὰ μέρη διέφυγεν· καὶ ὅσοι τῶν προγεγραμμένων ἦσαν παρὰ τῷ Κορνιφικίῳ, οἱ μὲν ἐς Σικελίαν διέπλεον, οἱ δ’ ὅπῃ δύναιντο ἕκαστος. ὁ δὲ Σέξστιος Ἀραβίωνα μὲν καὶ τοὺς Σιττιανοὺς ἐδωρεῖτο πολλοῖς λαφύροις, τὰς δὲ πόλεις τῷ Καίσαρι καθίστατο, συγγινώσκων ἁπάσαις.", "st": "4.56"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τέλος ἦν τῷ περὶ Λιβύην Σεξστίου καὶ Κορνιφικίου πολέμῳ, βραχεῖ διὰ ταχυεργίαν δόξαντι εἶναι· τὰ δ’ ἀμφὶ Κάσσιόν τε καὶ Βροῦτον, μικρὰ καὶ τῶν εἰρημένων ἀναλαβόντι ἐς ὑπόμνημα, ἦν τοιάδε. ἐπειδὴ Γάιος Καῖσαρ ἀνῄρητο, οἱ μὲν σφαγεῖς αὐτοῦ τὸ Καπιτώλιον κατέλαβον καὶ ψηφισθείσης αὐτοῖς ἀμνηστίας κατέβησαν. ὁ δὲ δῆμος ἐπὶ τῇ ἐκκομιδῇ τοῦ σώματος ἐν οἴκτῳ Καίσαρος γενόμενος ἐζήτει τοὺς φονέας περιθέων. οἱ δὲ τότε μὲν ἠμύνοντο αὐτοὺς ἀπὸ τῶν τεγῶν, εὐθὺς δὲ ἐξῄεσαν αὐτῶν, ὅσοι στρατηγεῖν ἐθνῶν ὑπὸ Καίσαρος αὐτοῦ κεχειροτόνηντο. Κάσσιος δὲ καὶ Βροῦτος ἐστρατήγουν μὲν ἔτι τῆς πόλεως, ᾕρηντο δὲ ἐπὶ τῇ στρατηγίᾳ καὶ οἵδε ὑπὸ Γαΐου Καίσαρος ἡγεῖσθαι Συρίας μὲν ὁ Κάσσιος, Μακεδονίας δὲ ὁ Βροῦτος. οὔτε δὲ ἄρχειν πω τῶν ἐθνῶν πρὸ τοῦ χρόνου δυνάμενοι οὔτε τὸν ἐν ἄστει φόβον ὑπομένοντες ἐξῄεσαν ἔτι στρατηγοῦντες· καὶ αὐτοῖς ἐς εὐπρέπειαν ἡ βουλὴ σίτου φροντίσαι προσέταξεν, ἵνα μὴ τὸ ἐν μέσῳ διάστημα φεύγειν νομίζοιντο. οἰχομένων δὲ αὐτῶν Συρία μὲν καὶ Μακεδονία εἰς τοὺς ὑπάτους Ἀντώνιόν τε καὶ Δολοβέλλαν μετεψηφίζετο, τῆς βουλῆς πάνυ δυσχεραινούσης, ἀντεδόθη δὲ ὅμως τοῖς ἀμφὶ τὸν Κάσσιον Κυρήνη τε καὶ Κρήτη· ὧν ὑπεριδόντες ὡς βραχυτέρων ἐκεῖνοι στρατὸν καὶ χρήματα ἤγειρον ὡς ἐς Συρίαν καὶ Μακεδονίαν ἐσβαλοῦντες.", "st": "4.57"}, {"sp": "N", "t": "καὶ οἱ μὲν ἦσαν ἐν τούτοις, Τρεβώνιον δὲ ἐν Ἀσίᾳ κτείναντος Δολοβέλλα καὶ Δέκμον Ἀντωνίου πολιορκοῦντος ἐν Κελτοῖς, χαλεπαίνουσα ἡ βουλὴ Δολοβέλλαν μὲν καὶ Ἀντώνιον ἐψηφίσαντο εἶναι πολεμίους, Βροῦτον δὲ καὶ Κάσσιον ἐς τὰς προτέρας ἡγεμονίας ἐπανήγαγον καὶ Βρούτῳ τὴν Ἰλλυρίδα προσέθεσαν τοῖς τε ἄλλοις πᾶσιν ἐκέλευσαν, ὅσοι Ῥωμαίοις ἡγεμονεύουσιν ἐθνῶν ἢ στρατοπέδων ἀπὸ τοῦ Ἰονίου μέχρι Συρίας, ὑπακούειν, ἐς ὅ τι κελεύοι Κάσσιος ἢ Βροῦτος. ἐπὶ δὲ τούτοις Κάσσιος φθάνει Δολοβέλλαν ἐς τὴν Συρίαν ἐμβαλὼν καὶ σημεῖα τῆς ἡγεμονίας ἀνέσχε καὶ δυώδεκα τέλη στρατοῦ Γαΐῳ Καίσαρι ἐκ πολλοῦ στρατευόμενα καὶ γεγυμνασμένα προσέλαβεν ἀθρόως· οὗ τὸ μὲν ἓν αὐτῶν ὁ Καῖσαρ ἐν Συρίᾳ καταλελοίπει, τὰ ἐς Παρθυαίους ἤδη διανοούμενος, τὴν δὲ ἐπιμέλειαν αὐτοῦ ἐπιτέτραπτο μὲν Καικίλιος Βάσσος, τὸ δὲ ἀξίωμα εἶχε νεανίας αὐτοῦ Καίσαρος συγγενής, Σέξστος Ἰούλιος. ἐκδιαιτώμενος δὲ ὁ Ἰούλιος τὸ τέλος ἐς τρυφὴν ἐπήγετο ἀσχημόνως καὶ ἐπιμεμφομένῳ τῷ Βάσσῳ ποτὲ ἐνύβρισε· καὶ καλῶν ὕστερον, ἐπειδὴ βραδέως ὑπήκουεν, ἄγειν αὐτὸν ἐκέλευεν ἕλκοντας. θορύβου δὲ ἀσχήμονος καὶ πληγῶν ἐς τὸν Βάσσον γενομένων οὐκ ἐνεγκοῦσα τὴν ὄψιν ἡ στρατιὰ τὸν Ἰούλιον συνηκόντισε. καὶ εὐθὺς ἦν μετάνοια καὶ δέος ἐκ τοῦ Καίσαρος. συνομόσαντες οὖν ἀλλήλοις, εἰ μή τις αὑτοῖς συγγνώμη καὶ πίστις γένοιτο, διαγωνιεῖσθαι μέχρι θανάτου, τὸν Βάσσον ἐς ταῦτα συνηνάγκασαν. τέλος δὲ στρατεύσαντες ἕτερον, συνεγύμναζον ἄμφω καὶ Στάιον Μοῦρκον, ὑπὸ Καίσαρος αὐτοῖς σὺν τρισὶ τέλεσιν ἐπιπεμφθέντα, γενναίως ἀπεμάχοντο. Μούρκῳ δ’ ἧκεν ἐπίκουρος Μάρκιος Κρίσπος ἐκ Βιθυνίας μετὰ τριῶν τελῶν ἄλλων, καὶ τὸν Βάσσον ἐπολιόρκουν ὁμοῦ πάντες ἓξ τέλεσιν ἤδη.", "st": "4.58"}, {"sp": "N", "t": "Κάσσιος οὖν τήνδε τὴν πολιορκίαν σπουδῇ καταλαβὼν τόν τε τοῦ Βάσσου στρατὸν αὐτίκα παρελάμβανεν ἑκόντα καὶ ἐπ’ ἐκείνῳ τὰ Μούρκου τέλη καὶ Μαρκίου, κατά τε φιλίαν αὐτῷ παραδιδόντων καὶ κατὰ τὸ δόγμα τῆς βουλῆς ἐς πάντα ὑπακουόντων. ἄρτι δὲ καὶ Ἀλλιηνός, ὑπὸ Δολοβέλλα πεμφθεὶς ἐς Αἴγυπτον, ἐπανῆγεν ἐξ αὐτῆς τέσσαρα τέλη τῶν ἀπὸ τῆς ἥσσης Πομπηίου τε καὶ Κράσσου διαρριφέντων ἢ ὑπὸ Καίσαρος Κλεοπάτρᾳ καταλελειμμένων· καὶ αὐτὸν ὁ Κάσσιος ἐν τῇ Παλαιστίνῃ, τῶν ὄντων οὐ προπεπυσμένον, ἄφνω περιέλαβέ τε καὶ ἠνάγκασε προσθέσθαι οἱ καὶ παραδοῦναι τὸν στρατόν, δείσαντα τέσσαρσι τέλεσι μάχεσθαι πρὸς ὀκτώ. οὕτω μὲν ὁ Κάσσιος ἐκ παραδόξου δυώδεκα τελῶν ἀρίστων ἀθρόως ἐκράτει. καὶ αὐτῷ τινες καὶ Παρθυαίων ἱπποτοξόται συνεμάχουν, δόξαν ἔχοντι παρὰ τοῖς Παρθυαίοις, ἐξ οὗ Κράσσῳ ταμιεύων ἐμφρονέστερος ἔδοξε τοῦ Κράσσου γενέσθαι.", "st": "4.59"}, {"sp": "N", "t": "Δολοβέλλας δὲ διέτριψε μὲν περὶ τὴν Ἰωνίαν, κτείνων Τρεβώνιον καὶ ταῖς πόλεσιν ἐπιβάλλων ἐσφορὰς καὶ ναυτικὸν ἀγείρων ἐπὶ μισθῷ διὰ Λευκίου Φίγλου παρά τε Ῥοδίων καὶ Λυκίων καὶ Παμφύλων καὶ ἐκ Κιλικίας· ὡς δέ οἱ τάδε ἕτοιμα ἦν· ἐπῄει τῇ Συρίᾳ, κατὰ μὲν τὴν γῆν αὐτὸς μετὰ δύο τελῶν, διὰ δὲ τῆς θαλάσσης ὁ Φίγλος. πυθόμενος δὲ τῆς Κασσίου στρατιᾶς ἐς Λαοδίκειαν οἰκείως ἔχουσάν οἱ παρῆλθεν, ἐπί τε χερρονήσου συνῳκισμένην καὶ τὰ ἐκ τῆς γῆς ὠχυρωμένην καὶ ἐς τὸ πέλαγος ἔχουσαν ὅρμον, ὅθεν ἔμελλεν εὐπορήσειν τε ἀγορᾶς ἀπὸ θαλάσσης καὶ ἀδεῶς, ὅτε βούλοιτο, ἀποπλευσεῖσθαι. ὧν αἰσθανόμενος ὁ Κάσσιος καὶ δεδιώς, μὴ αὑτὸν ὁ Δολοβέλλας διαφύγοι, τόν τε ἴσθμὸν ἔχου διστάδιον ὄντα, λίθους καὶ πᾶσαν ὕλην ἐξ ἐπαύλεων καὶ προαστείων καὶ τάφων συμφέρων, καὶ ἐπὶ ναῦς περιέπεμπεν ἔς τε Φοινίκην καὶ Λυκίαν καὶ Ῥόδον.", "st": "4.60"}, {"sp": "N", "t": "Ὑπερορώμενος δὲ ὑπὸ τῶν ἄλλων πλὴν Σιδωνίων ἐπανήχθη τῷ Δολοβέλλᾳ, καὶ κατέδυσαν μὲν ἑκατέρου νῆες ἱκαναί, πέντε δὲ αὐτοῖς ἀνδράσιν εἷλεν Δολοβέλλας. καὶ ὁ Κάσσιος αὖθις ἔπεμπεν ἐς τοὺς ὑπεριδόντας αὐτοῦ καὶ ἐς Κλεοπάτραν, τὴν Αἰγύπτου βασιλίδα, καὶ ἐς Σεραπίωνα, τὸν ἐν Κύπρῳ τῇ Κλεοπάτρᾳ στρατηγοῦντα. Τύριοι μὲν δὴ καὶ Ἀράδιοι καὶ Σεραπίων, οὐδὲν τῆς Κλεοπάτρας προμαθών, ἔπεμψαν αὐτῷ ναῦς, ὅσας εἶχον· ἡ βασιλὶς δὲ Κασσίῳ μὲν προύφερε λιμὸν ὁμοῦ καὶ λοιμὸν ἐνοχλοῦντα τότε Αἰγύπτῳ, διὰ δὲ οἰκειότητα τοῦ προτέρου Καίσαρος συνέπρασσε τῷ Δολοβέλλᾳ. καὶ ἀπὸ τῆσδε τῆς γνώμης αὐτῷ καὶ τὰ τέσσαρα τέλη προπεπόμφει δι’ Ἀλλιηνοῦ καὶ στόλον ἄλλον ἕτοιμον εἶχεν ἐπαμύνειν, ἄνεμοι δὲ ἐπεῖχον. Ῥόδιοι δὲ καὶ Λύκιοι οὔτε Κασσίῳ οὔτε Βρούτῳ συμμαχήσειν ἔφασκον ἐς ἐμφύλια, ἐπεὶ καὶ Δολοβέλλᾳ δοῦναι ναῦς προπομπούς, καὶ οὐκ εἰδέναι συμμαχούσας.", "st": "4.61"}, {"sp": "N", "t": "ἑτοιμασάμενος οὖν ὁ Κάσσιος αὖθις ἐκ τῶν παρόντων ἐπανήγετο δὶς τῷ Δολοβέλλᾳ· καὶ τὸ μὲν πρῶτον ἀγχώμαλοι διεκρίθησαν ἀπ’ ἀλλήλων, τῇ δὲ ἑξῆς ναυμαχίᾳ ἡσσᾶτο ὁ Δολοβέλλας, καὶ ὁ Κάσσιος αἰρομένου τοῦ χώματος ἔκοπτεν αὐτοῦ τὸ τεῖχος ἤδη καὶ ἐσάλευεν. τόν τε νυκτοφύλακα αὐτοῦ Μάρσον οὐ δυνηθεὶς διαφθεῖραι διέφθειρε τοὺς ἡμεροφυλακοῦντας αὐτῷ λοχαγοὺς καὶ ἀναπαυομένου τοῦ Μάρσου μεθ’ ἡμέραν ἐσῆλθεν, ὑπανοιχθεισῶν αὐτῷ πυλίδων κατὰ μέρη πολλῶν. ἁλούσης δὲ τῆς πόλεως ὁ μὲν Δολοβέλλας προύτεινε τὴν κεφαλὴν τῷ σωματοφύλακι αὑτοῦ καὶ τεμόντα προσέταξε φέρειν Κασσίῳ σῶστρον ἴδιον· ὁ δὲ τεμὼν ἐπικατέσφαξεν ἑαυτόν, διεχρήσατο δὲ καὶ Μάρσος ἑαυτόν. ὁ δὲ Κάσσιος τὴν μὲν τοῦ Δολοβέλλα στρατιὰν ἐς ἑαυτὸν μεθώρκου, Λαοδικέων δὲ τά τε ἱερὰ καὶ τὰ κοινὰ ἐσύλα καὶ τοὺς ἐπιφανεῖς ἐκόλαζε καὶ τοὺς λοιποὺς ἐσφοραῖς βαρυτάταις ἐξέτρυχε, μέχρι τὴν πόλιν περιήνεγκεν ἐς ἔσχατον κακοῦ.", "st": "4.62"}, {"sp": "N", "t": "μετὰ δὲ Λαοδίκειαν ἐπ’ Αἴγυπτον ὥρμα, πυνθανόμενος μὲν Κλεοπάτραν βαρεῖ στόλῳ διαπλευσεῖσθαι πρός τε Καίσαρα καὶ πρὸς Ἀντώνιον, ἐπινοῶν δὲ κωλῦσαί τε τὸν πλοῦν καὶ τίσασθαι τῆς γνώμης τὴν βασιλίδα καὶ πρὸ τῶνδε αὐτὴν Αἴγυπτον ἐνθυμιζόμενος μάλιστα ἐν καιρῷ, τετρυμένην τε ὑπὸ λιμοῦ καὶ ξενικὸν στρατὸν οὐ πολὺν ἔχουσαν, ἄρτι τῶν Ἀλλιηνοῦ στρατιωτῶν ἀποστάντων. οὕτω δὲ αὐτὸν ὁρμῆς καὶ ἐλπίδος ἔχοντα καὶ καιροῦ ὁ Βροῦτος ἐκάλει κατὰ σπουδήν, ὡς ἤδη Καίσαρος καὶ Ἀντωνίου τὸν Ἰόνιον περώντων. ἄκων μὲν δὴ Κάσσιος Αἴγυπτον ἐκ τῶν ἐλπίδων μεθίει καὶ τοὺς Παρθυαίων ἱπποτοξότας ἀπέπεμπε τιμήσας καὶ πρέσβεις πρὸς τὸν βασιλέα αὐτῶν ἔστελλε περὶ μείζονος συμμαχίας, ἣ μετὰ τὸ ἔργον ἀφικνουμένη Συρίαν τε καὶ πολλὰ τῶν ἐγγὺς ἐθνῶν μέχρι Ἰωνίας ἐπέδραμε καὶ ἀνεχώρησεν. αὐτὸς δὲ ὁ Κάσσιος τὸν μὲν ἀδελφιδοῦν ἐν Συρίᾳ μεθ’ ἑνὸς τέλους ἀπέλιπε, τοὺς δὲ ἱππέας προύπεμψεν ἐς Καππαδοκίαν, οἳ Ἀριοβαρζάνην τε ἄφνω κατέκανον ὡς ἐπιβουλεύοντα Κασσίῳ καὶ χρήματα πολλὰ τὰ ἐκείνου καὶ τὴν ἄλλην κατασκευὴν ἐς τὸν Κάσσιον ἐπανήγαγον.", "st": "4.63"}, {"sp": "N", "t": "Ταρσέων δ’ ἐς στάσιν διῃρημένων οἱ μὲν τὸν Κάσσιον ἐστεφανώκεσαν ἐλθόντα πρότερον, οἱ δὲ τὸν Δολοβέλλαν ἐπελθόντα· ἀμφότεροι δὲ τῷ τῆς πόλεως σχήματι ταῦτα ἔπρασσον. καὶ παραλλὰξ αὐτῶν προτιμώντων ἑκάτερον, ὡς εὐμεταβόλῳ πόλει χαλεπῶς ἐχρῶντο ἑκάτεροι· Κάσσιος δὲ νικήσας Δολοβέλλαν καὶ ἐσφορὰν ἐπέθηκεν αὐτοῖς χίλια καὶ πεντακόσια τάλαντα. οἱ δὲ ἀποροῦντές τε καὶ ὑπὸ στρατιωτῶν ἐπειγόντων ἀπαιτούμενοι σὺν ὕβρει, τά τε κοινὰ ἀπεδίδοντο πάντα καὶ τὰ ἱερὰ ἐπὶ τοῖς κοινοῖς, ὅσα εἶχον ἐς πομπὰς ἢ ἀναθήματα, ἔκοπτον. οὐδενὸς δὲ μέρους οὐδ’ ὣς ἀνυομένου, ἐπώλουν αἱ ἀρχαὶ τὰ ἐλεύθερα· καὶ πρῶτα μὲν ἦν παρθένοι τε καὶ παῖδες, ἐπὶ δὲ γυναῖκές τε καὶ γέροντες ἐλεεινοί, βραχυτάτου πάμπαν ὤνιοι, μετὰ δὲ οἱ νέοι. καὶ διεχρῶντο οἱ πλέονες ἑαυτούς, ἕως ὧδε ἔχοντας ὁ Κάσσιος ἐκ Συρίας ἐπανιὼν ᾤκτειρέ τε καὶ τοῦ λοιποῦ τῶν ἐσφορῶν ἀπέλυσε.", "st": "4.64"}, {"sp": "N", "t": "Τάρσος μὲν δὴ καὶ Λαοδίκεια τοιάδε ἐπεπόνθεσαν, Κάσσιος δὲ καὶ Βροῦτος συμβολήσαντες ἀλλήλοιν, Βρούτῳ μὲν ἐδόκει τὴν στρατιὰν ἁλίσαντε χωρεῖν ἐπὶ τὸ μεῖζον ἔργον ἐς Μακεδονίαν· τέλη τε γὰρ ἤδη τοῖς πολεμίοις ἐς τεσσαράκοντα εἶναι στρατοῦ καὶ αὐτῶν διεληλυθέναι τὸν Ἰόνιον ὀκτώ· Κασσίῳ δὲ ἐδόκει τῶν μὲν πολεμίων ἔτι περιορᾶν ὡς τριφθησομένων ἐν σφίσιν ἐξ ἀπορίας διὰ τὸ πλῆθος, Ῥοδίους δὲ καὶ Λυκίους ἐξελεῖν, εὔνους τε ὄντας ἐκείνοις καὶ ναυτικὸν ἔχοντας, ἵνα μὴ κατὰ νώτου σφίσι γίγνωνται παρὰ τὸ ἔργον. ἐπεὶ δὲ ἔδοξεν ὧδε, ἐχώρουν Βροῦτος μὲν ἐπὶ Λυκίους, Κάσσιος δὲ ἐπὶ Ῥοδίους, τεθραμμένος τε ἐν αὐτῇ καὶ πεπαιδευμένος τὰ Ἑλληνικά. ὡς δὲ κρατίστοις τὰ ναυτικὰ ἀνδράσι συνοισόμενος ἐς μάχην, τὰς ἰδίας ναῦς ἐπεσκεύαζε καὶ ἀνεπλήρου καὶ ἐγύμναζεν ἐν Μύνδῳ.", "st": "4.65"}, {"sp": "N", "t": "Ῥοδίων δὲ οἱ μὲν ἐν λόγῳ μᾶλλον ὄντες ἐδεδοίκεσαν Ῥωμαίοις μέλλοντες ἐς χεῖρας ἰέναι, ὁ δὲ λεὼς ἐμεγαλοφρονεῖτο, ἐπεί οἱ καὶ παλαιῶν ἔργων πρὸς οὐχ ὁμοίους ἄνδρας ἐμνημόνευον. ναῦς τε καθεῖλκον τὰς ἀρίστας σφῶν τρεῖς καὶ τριάκοντα. καὶ τάδε πράσσοντες ἔπεμπόν τινας ἐς Μύνδον ὅμως, οἳ τὸν Κάσσιον ἠξίουν μήτε Ῥόδου καταφρονεῖν, πόλεως ἀμυναμένης ἀεὶ τοὺς καταφρονήσαντας, μήτε συνθηκῶν, αἳ Ῥοδίοις εἰσὶ καὶ Ῥωμαίοις, ὅπλα μὴ φέρειν ἐπὶ ἀλλήλους· εἰ δέ τι περὶ συμμαχίας ἐπιμέμφοιτο, ἐθέλειν παρὰ τῆς Ῥωμαίων βουλῆς πυθέσθαι, καὶ κελευούσης ἔφασαν συμμαχήσειν.", "st": "4.66"}, {"sp": "N", "t": "οἱ μὲν δὴ τοιάδε μάλιστα ἔλεγον, ὁ δὲ τὰ μὲν ἄλλα τὸν πόλεμον ἀντὶ λόγων ἔφη κρινεῖν, τὰς δὲ συνθήκας κελεύειν ὅπλα μὴ φέρειν ἐπ’ ἀλλήλους, καὶ ἐπενηνοχέναι Ῥοδίους Κασσίῳ, Δολοβέλλᾳ συμμαχοῦντας, κελεύειν δὲ ἀλλήλοις συμμαχεῖν, Κασσίῳ δὲ δεομένῳ εἰρωνεύεσθαι τὰ περὶ τῆς Ῥωμαίων βουλῆς, φευγούσης καὶ ἁλωμένης ἐν τῷ παρόντι διὰ τοὺς ἐν ἄστει τυράννους, οἳ δώσουσι μὲν αὐτοὶ δίκας, δώσουσι δὲ καὶ Ῥόδιοι τὰ ἐκείνων προτιμῶντες, ἢν μὴ θᾶσσον ἀνέχωνται τῶν κελευομένων. ὧδε μὲν ὁ Κάσσιος αὐτοὺς ἠμείψατο, καὶ οἱ εὖ φρονοῦντες Ῥοδίων μᾶλλον ἐδεδοίκεσαν· τὸ δὲ πλῆθος ἐδημαγώγουν Ἀλέξανδρός τε καὶ Μνασέας ἀναμιμνήσκοντες, ὅτι καὶ Μιθριδάτης πλέοσι ναυσὶν ἐπιπλεύσειε τῇ Ῥόδῳ καὶ Δημήτριος ἔτι πρὸ τοῦ Μιθριδάτου.", "st": "4.66"}, {"sp": "N", "t": "οἱ μὲν δὴ τὸν Ἀλέξανδρον ἐκ τούτων εἵλοντο σφίσι πρυτανεύειν, ἥπερ ἐστὶν ἀρχὴ παρ’ αὐτοῖς μάλιστα αὐτοκράτωρ, καὶ ναυαρχεῖν Μνασέαν, ἔπεμπον δ’ ὅμως ἐς τὸν Κάσσιον ἔτι πρεσβευτὴν Ἀρχέλαον, ὃς ἐν Ῥόδῳ τὰ Ἑλληνικὰ διδάσκαλος γεγένητο τῷ Κασσίῳ, δεησόμενον ἤδη τόνδε τοῦ Κασσίου λιπαρέστερον· καὶ ἐδεῖτο, τῆς δεξιᾶς λαβόμενος, ὡς γνωρίμου.", "st": "4.67"}, {"sp": "N", "t": "“μὴ πόλιν ἀναστήσῃς Ἑλληνίδα φιλέλλην ἀνήρ, μὴ Ῥόδον φιλελεύθερος ἀνήρ· μηδὲ αἰσχύνῃς ἀξίωμα Δώριον, οὐχ ἡσσημένον, ἐξ οὗ γεγόναμεν, μηδὲ ἐκλάθῃ καλῆς ἱστορίας ἧς ἔμαθες ἐν Ῥόδῳ τε καὶ ἐν Ῥώμῃ, ἐν Ῥόδῳ μέν, ὅσα Ῥόδιοι κατὰ πόλεις καὶ πρὸς βασιλέας, ἄλλους τε καὶ τοὺς μάλιστα ἀμάχους δόξαντας εἶναι, Δημήτριον καὶ Μιθριδάτην, ὑπὲρ ἐλευθερίας ἔπραξαν, ὑπὲρ ἧς δὴ καὶ σὺ φῂς τάδε κάμνειν· ἐν Ῥώμῃ δέ, ὅσα ὑμῖν αὐτοῖς καθ’ ἑτέρων καὶ κατ’ Ἀντιόχου τοῦ μεγάλου συνεμαχήσαμεν, ὧν εἰσὶν ὑπὲρ ἡμῶν ἀνάγραπτοι στῆλαι παρ’ ὑμῖν.", "st": "4.67"}, {"sp": "N", "t": "“τάδε μὲν δὴ καὶ γένους ἕνεκα καὶ ἀξιώσεως ἡμῶν καὶ τύχης ἐς τὸ νῦν ἀδουλώτου καὶ συμμαχίας καὶ προαιρέσεως ἐς ὑμᾶς, ὦ Ῥωμαῖοι, λελέχθω· πρὸς σὲ δέ, ὦ Κάσσιε, καὶ αἰδώς τις ἔστιν ἐξαίρετος ἔς τε τὴν πόλιν καὶ τὴν ἐν αὐτῇ τροφήν τέ σου καὶ παίδευσιν καὶ διατριβὴν καὶ ἑστίαν, ἣν ᾤκησας, καὶ τοὐμὸν διδασκαλεῖον αὐτὸ καὶ ἐμέ, ἐλπίσαντα μὲν ἐς ἕτερα τούτοις ποτὲ ἐναβρυνεῖσθαι, νῦν δὲ ὑπὲρ τῆς πατρίδος αὐτὰ δαπανῶντα, ἵνα μηδ’ αὐτή σοι πολεμεῖν ἀναγκάζηται πεπαιδευμένῳ τε ὑφ’ αὑτῆς καὶ τεθραμμένῳ μηδὲ γένηται δυοῖν ὑπ’ ἀνάγκης θάτερον, ἢ Ῥοδίους ἀποθανεῖν πάντως ἢ Κάσσιον ἡσσᾶσθαι. συμβουλεύω δὲ ἐπὶ τῇ παρακλήσει, τοιῶνδέ σε ὑπὲρ τῆς Ῥωμαίων πολιτείας ἁπτόμενον ἔργων θεοὺς ἡγεμόνας αἰεὶ ποιεῖσθαι παντὸς ἔργου. θεοὺς δ’ ὠμόσατε, ὅτε ἡμῖν ἔναγχος διὰ Γαΐου Καίσαρος συνετίθεσθε καὶ σπονδὰς ἐπὶ τοῖς ὅρκοις ἐσπένδετε καὶ δεξιὰς ἐτίθεσθε, αἳ καὶ παρὰ πολεμίοις ἰσχύουσιν, οὐ παρὰ φίλοις καὶ τροφεῦσιν; φείδου δὲ ἐπὶ τοῖς θεοῖς καὶ δόξης τῆς κατὰ ἀνθρώπους· ὡς οὐδέν ἐστι συνθηκῶν παραβάσεως μᾶλλον, ὃ τοὺς ἁμαρτάνοντας ἀπίστους ἐς ἅπαντα ποιεῖ καὶ φίλοις καὶ πολεμίοις.”", "st": "4.68"}, {"sp": "N", "t": "ταῦτ’ εἰπὼν ὁ πρεσβύτης οὐ μεθίετο τῆς χειρός, ἀλλ’ ἐπεδάκρυεν αὐτῇ, ὡς ἐρυθριᾶσαι μὲν ἐπὶ τῷ σχήματι τὸν Κάσσιον καὶ παθεῖν τι ὑπὸ αἰδοῦς, ὑφελόντα δὲ ὅμως εἰπεῖν·", "st": "4.69"}, {"sp": "N", "t": "“εἰ μὲν οὐ συνεβούλευσας Ῥοδίοις μὴ ἀδικεῖν με, σύ με ἠδίκεις· εἰ δὲ διδάσκων οὐκ ἔπεισας, ἀμυνῶ σοι. ἠδικούμην δὲ δή που σαφῶς τὸ μὲν πρῶτον ἀδίκημα συμμαχίαν αἰτῶν καὶ παρορώμενος ὑπὸ τῶν παιδευσάντων καὶ θρεψάντων, τὸ δὲ ἑξῆς προτιμώντων μου Δολοβέλλαν, ὃν οὐκ ἐπαίδευσαν οὐδὲ ἀνέθρεψαν, τὸ δὲ ἀνιαρότερον, ἐμοῦ μὲν καὶ Βρούτου καὶ ὅσων ὁρᾶτε ἀπὸ τῆς βουλῆς ἀρίστων ἀνδρῶν φευγόντων τυραννίδα καὶ τὴν πατρίδα ἐλευθερούντων, ὦ Ῥόδιοι φιλελεύθεροι, Δολοβέλλα δὲ αὐτὴν καταδουλοῦντος ἑτέροις, οἷς δὴ καὶ ὑμεῖς εὔνως ἔχοντες ὑποκρίνεσθε ἐξίστασθαι τοῖς ἐμφυλίοις ἡμῶν. ἔστι δὲ ἐμφύλια μέν, εἰ καὶ ἡμεῖς δυναστείας ὠρεγόμεθα, πόλεμος δὲ σαφὴς τὸ γιγνόμενόν ἐστι δημοκρατίας πρὸς μοναρχίαν. καὶ δημοκρατίαν ἀβοήθητον καταλείπετε οἱ παρακαλοῦντες ὑπὲρ αὐτονομίας· φιλίαν τε Ῥωμαίοις προφέροντες οὐκ ἐλεεῖτε ἀκρίτους ἐπὶ θανάτῳ καὶ δημεύσει προγραφομένους, ἀλλ’ ὑποκρίνεσθε πεύσεσθαι τῆς βουλῆς τῆς ταῦτα πασχούσης καὶ οὐδὲ ἀμύνειν ἑαυτῇ πω δυναμένης. ἡ δ’ ὑμῖν ἤδη προαπεκρίνατο, ἐν οἷς ἐψηφίσατο τοὺς ἀμφὶ τὴν ἕω πάντας ἀμύνειν ἐμοί τε καὶ Βρούτῳ.", "st": "4.69"}, {"sp": "N", "t": "“σὺ δέ, εἰ μέν ποτε ἡμῖν περικτωμένοις τι συνεπράξατε, ὧν εὐεργεσίας καὶ μισθοὺς ἀντικεκόμισθέ που, καταλογίζῃ, ὅτι δὲ ἡμῖν ἐς τὴν ἐλευθερίαν καὶ σωτηρίαν ἀδικουμένοις οὐ συμμαχεῖτε, ἐπιλανθάνῃ· οὓς εἰκὸς ἦν, εἰ καὶ μηδὲν ἡμῖν ἐς ἀλλήλους ὑπῆρχεν, ἀλλὰ νῦν ἄρχειν ἐθελοντὰς ὑπερμαχῆσαι τῆς Ῥωμαίων δημοκρατίας, Δωριέας ὄντας. οἳ δ’ ἀντὶ τοιούτων ἔργων καὶ λογισμῶν συνθήκας ἡμῖν προφέρετε, γενομένας μὲν ὑμῖν καὶ τάσδε πρὸς Γάιον Καίσαρα, τῆσδε τῆς μοναρχίας ἡγεμόνα· λέγουσι δ’ ὅμως αἱ συνθῆκαι Ῥωμαίους καὶ Ῥοδίους ἐν ταῖς χρείαις ἀλλήλοις ἀμύνειν. ἀμύνατε οὖν ἐς τὰ μέγιστα κινδυνεύουσι Ῥωμαίοις. Κάσσιος ὑμῖν ἐστιν ὁ τὰς συνθήκας τάσδε προφέρων καὶ ἐπὶ συμμαχίαν καλῶν, Ῥωμαῖος ἀνὴρ καὶ Ῥωμαίων στρατηγός, ὥς φησι τὸ ψήφισμα τῆς βουλῆς, ἐν ᾧ πάντας ὑπακούειν ἡμῖν ἔταξε τοὺς τοῦ Ἰονίου πέραν. τὰ δ’ αὐτὰ καὶ Βροῦτος ὑμῖν προτείνει ψηφίσματα καὶ Πομπήιος, τὴν θάλασσαν ὑπὸ τῆς βουλῆς ἐπιτετραμμένος, τὰς δ’ ἱκετείας ἐπὶ τοῖς ψηφίσμασι καὶ οἵδε πάντες, ὅσοι φεύγουσιν ἀπὸ τῆς βουλῆς, οἱ μὲν ἐς ἐμὲ καὶ Βροῦτον, οἱ δ’ ἐς Πομπήιον. ἔστι δὲ δή που τὸ συγκείμενον, Ῥωμαίοις Ῥοδίους βοηθεῖν, κἂν καθ’ ἕνα χρῄζωσιν. εἰ δὲ οὔτε στρατηγοὺς ἡμᾶς οὔτε Ῥωμαίους ἔτι, ἀλλὰ φυγάδας ἢ ξένους ἢ κατακρίτους, ὡς οἱ προγράψαντες λέγουσιν, ἡγεῖσθε, οὐ πρὸς ἡμᾶς ἐστιν ὑμῖν ἔτι, ἀλλὰ πρὸς Ῥωμαίους, ὦ Ῥόδιοι, τὰ συγκείμενα· ἡμεῖς δὲ ξένοι καὶ ἀλλότριοι τῶν συνθηκῶν ὄντες πολεμήσομεν ὑμῖν, ἢν μὴ ἐς πάντα κατακούητε.”", "st": "4.70"}, {"sp": "N", "t": "τοιαῦτα μὲν ὁ Κάσσιος ἐπειρωνευσάμενος τὸν Ἀρχέλαον ἀπέλυεν, Ἀλέξανδρος δὲ καὶ Μνασέας, οἱ Ῥοδίων ἡγούμενοι, ταῖς τριάκοντα καὶ τρισὶ ναυσὶν ἀνήγοντο ἐπὶ Κάσσιον ἐς Μύνδον ὡς προκαταπλήξοντες τῷ ἐπίπλῳ· καί τί που καὶ κούφως εἶχον ἐλπίδος, ὅτι καὶ Μιθριδάτῃ ἐς Μύνδον ἐπιπλεύσαντες ἐδόκουν ἐς τὸ τοῦ πολέμου τέλος εὐτυχῆσαι. εἰρεσίᾳ δὲ ἐς ἐπίδειξιν χρώμενοι τήν τε πρώτην ἡμέραν ηὐλίσαντο ἐν Κνίδῳ καὶ τῆς ἐπιούσης ἐπεφαίνοντο τοῖς ἀμφὶ τὸν Κάσσιον ἐκ τοῦ πελάγους. οἱ δὲ θαυμάσαντες ἀντανήγοντο, καὶ τὸ ἔργον ἦν ἑκατέρωθεν ἰσχύος τε καὶ δυνάμεως· Ῥόδιοι μὲν γὰρ ναυσὶ κούφαις διεξέπλεόν τε τοὺς πολεμίους ὀξέως καὶ περιέπλεον καὶ ἐπανόδοις ἐχρῶντο, Ῥωμαῖοι δὲ ἐπὶ νεῶν βαρυτέρων, ὅτε συμπλακεῖεν, ἀπὸ βαρυτέρας ῥύμης ἐπεβάρουν ὥσπερ ἐν πεζομαχίᾳ. τοῦ δὲ Κασσίου πλήθει νεῶν τὰς πολεμίας περιλαβόντος, οἱ μὲν Ῥόδιοι περιπλεῖν ἔτι καὶ διεκπλεῖν οὐκ ἐδύναντο, ἐμβάλλουσι δ’ αὐτοῖς μόνον ἐκ τοῦ μετώπου καὶ ἀναχωροῦσιν ἡ μὲν ἐμπειρία διέφθαρτο ὑπὸ τῆς στενοχωρίας κεκυκλευμένοις, αἱ δὲ ἐμβολαὶ καὶ ἀποσιμώσεις ἐς βαρυτέρας τὰς Ῥωμαίων ναῦς ἀσθενεῖς ἐγίγνοντο, Ῥωμαίοις δ’ ἦσαν ἐς κουφοτέρας εὔτονοι, μέχρι Ῥόδιαι μὲν τρεῖς αὐτοῖς ἀνδράσιν ἐλήφθησαν καὶ δύο ἀνερράγησάν τε καὶ κατέδυσαν καὶ αἱ λοιπαὶ βεβλαμμέναι διέφυγον ἐς τὴν Ῥόδον, αἱ δὲ Ῥωμαίων ἅπασαι μὲν ἐπανῆλθον ἐς Μύνδον, ἐπεσκευάζοντο δὲ καὶ τούτων αἱ πλέονες βλαβεῖσαι.", "st": "4.71"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τῆς ἐν Μύνδῳ Ῥωμαίων τε καὶ Ῥοδίων ναυμαχίας τέλος ἦν, καὶ αὐτὴν γιγνομένην ὁ Κάσσιος ἀπὸ ὄρους καθεώρα· ὡς δὲ ἐπεσκεύασε τὰ σκάφη, διέπλευσεν ἐς Λώρυμα, Ῥοδίων τι φρούριον ἐν τῇ περαίᾳ, καὶ τὸ πεζὸν ἐς τὴν Ῥόδον διεβίβαζεν ἐπὶ ὁλκάδων ὑπὸ Φαννίῳ τε καὶ Λέντλῳ. αὐτὸς δὲ ἐπέπλει ταῖς ὀγδοήκοντα ναυσὶν ἐσκευασμέναις ἐς τὸ φοβερώτατον καὶ περιστήσας τῇ Ῥόδῳ τὸ πεζὸν ὁμοῦ καὶ τὸ ναυτικὸν ἡσύχαζεν ὡς ἐνδωσόντων τι τῶν πολεμίων. οἱ δὲ ἐπανήχθησαν μὲν αὖθις εὐθαρσῶς, δύο δὲ καὶ τότε ναῦς ἀποβαλόντες συνεκλείσθησαν. καὶ ἀναδραμόντες ἐπὶ τὰ τείχη πάντα τε ὅπλων ἐπλήρουν καὶ ἀπεμάχοντο ὁμοῦ τοὺς περὶ τὸν Φάννιον ἀπὸ τῆς γῆς ἐνοχλοῦντας καὶ τὸν Κάσσιον τοῖς πρὸς θαλάσσῃ τείχεσι τὸ ναυτικὸν οὐκ ἀνέτοιμον ἐς τειχομαχίαν ἐπαγαγόντα· ἐλπίζων γάρ τι τοιοῦτον ἐπεφέρετο πύργους ἐπτυγμένους, οἳ τότε ἀνίσταντο. Ῥόδος μὲν δὴ δύο πείραις καμοῦσα ἔκ τε γῆς καὶ θαλάσσης ἐπολιορκεῖτο· καὶ οὐδέν, ὡς ἐν ἔργῳ ταχεῖ καὶ ἀδοκήτῳ, παρεσκεύαστο αὐτοῖς ἐς πολιορκίαν. ὅθεν ἦν εὔδηλον ἁλώσεσθαι τάχιστα τὴν πόλιν ἢ χερσὶν ἢ λιμῷ· καὶ τάδε Ῥοδίων οἱ συνετώτεροι καθεώρων, καὶ Φάννιος αὐτοῖς καὶ Λέντλος διελέγοντο.", "st": "4.72"}, {"sp": "N", "t": "γιγνομένων δ’ ἔτι τούτων ἄφνω Κάσσιος ἦν ἐν μέσῃ τῇ πόλει μετ’ ἐπιλέκτου στρατοῦ, βίας μὲν οὐδεμιᾶς φανείσης οὐδὲ κλιμάκων ἔργου. εἴκαζον δὲ οἱ πολλοί, καὶ δοκεῖ γενέσθαι, τοὺς χαρίεντας αὐτῷ τῶν πολιτῶν ὑπανοῖξαι πυλίδας ἐλέῳ τῆς πόλεως καὶ προμηθείᾳ τροφῶν.", "st": "4.73"}, {"sp": "N", "t": "ὧδε μὲν ἑαλώκει Ῥόδος, καὶ Κάσσιος ἐν αὐτῇ προυκάθητο ἐπὶ βήματος καὶ δόρυ τῷ βήματι παρεστήσατο ὡς ἐπὶ δοριαλώτῳ. ἀτρεμεῖν τε κελεύσας τὸν στρατὸν ἀκριβῶς καὶ θάνατον ἐπικηρύξας, εἴ τις ἁρπάσειεν ἢ βιάσαιτό τι, αὐτὸς ἐξ ὀνόματος ἐκάλει Ῥοδίων ἐς πεντήκοντα ἄνδρας καὶ ἀχθέντας ἐκόλαζε θανάτῳ· ἑτέροις δέ, ἀμφὶ τοὺς πέντε καὶ εἴκοσιν, οὐχ εὑρεθεῖσι φυγὴν ἐπέταττεν. χρήματα δὲ ὅσα ἦν ἢ χρυσὸς ἢ ἄργυρος ἐν ἱεροῖς τε καὶ δημοσίοις, πάντα συλήσας ἐκέλευσε καὶ τὸν ἰδιωτικὸν ἐκφέρειν τοὺς κεκτημένους εἰς ἡμέραν ῥητήν· καὶ ἐπεκήρυξε τοῖς μὲν ἐπικρύψασι θάνατον, τοῖς δὲ μηνύσασι δεκάτην, δούλοις δὲ καὶ ἐλευθερίαν. οἱ δ’ ἐν μὲν ἀρχῇ πολλοὶ συνέκρυψαν, οὐκ ἐς τέλος ἐλπίζοντες ἀφίξεσθαι τὴν ἀπειλήν· διδομένων δὲ τῶν γερῶν καὶ κολαζομένων τῶν μηνυομένων ἔδεισάν τε καὶ προσθεσμίαν ἑτέραν λαβόντες οἱ μὲν ἐκ γῆς ἀνώρυσσον, οἱ δὲ ἐκ φρεάτων ἀνίμων, οἱ δὲ ἐξέφερον ἐκ τάφων πολὺ πλέονα τῶν προτέρων.", "st": "4.73"}, {"sp": "N", "t": "αἱ μὲν δὴ Ῥοδίων συμφοραὶ τοιαίδε ἦσαν, καὶ Λεύκιος Οὐᾶρος αὐτοῖς μετὰ φρουρᾶς ὑπελέλειπτο· ὁ δὲ Κάσσιος ἡδόμενος τῇ ταχυεργίᾳ τῆς ἁλώσεως καὶ τῷ πλήθει τῶν χρημάτων ἐπέταττεν ὅμως καὶ τοῖς ἄλλοις ἔθνεσι τῆς Ἀσίας ἅπασι φόρους ἐτῶν δέκα συμφέρειν. καὶ οἱ μὲν ἐπράσσοντο συντόνως, ἐξαγγέλλεται δὲ αὐτῷ Κλεοπάτρα μέλλουσα διαπλεῖν μεγάλῳ στόλῳ καὶ παρασκευῇ βαρυτάτῃ πρὸς Καίσαρά τε καὶ Ἀντώνιον· τὰ γὰρ ἐκείνων αἱρουμένη καὶ τέως διὰ τὸν πρότερον Καίσαρα, τότε μᾶλλον ᾑρεῖτο διὰ τὸν ἐκ Κασσίου φόβον. ὁ δὲ Μοῦρκον μετά τε ὁπλιτῶν ἀρίστου τέλους καὶ τοξοτῶν τινων ἐπὶ νεῶν ἑξήκοντα καταφράκτων ἐς Πελοπόννησον ἔπεμπε ναυλοχεῖν περὶ Ταίναρον, … περισυράμενος ἐκ τῆς Πελοποννήσου λείαν, ὅσην ἔφθασε.", "st": "4.74"}, {"sp": "N", "t": "τὰ δ’ ἀμφὶ Λυκίαν καὶ Βροῦτον, μικρὰ καὶ τῶν ἀμφὶ τοῦτον ἐς ὑπόμνησιν ἀναλαβόντι ἄνωθεν, ἦν τοιάδε. ἐπειδὴ παρὰ Ἀπουληίου στρατιάν τέ τινα εἰλήφει, ὅσην Ἀπουλήιος εἶχεν, καὶ χρήματα ἐς ἑξακισχίλια καὶ μύρια τάλαντα, ὅσα ἐκ τῶν φόρων τῆς Ἀσίας συνείλεκτο, παρῆλθεν ἐς Βοιωτίαν. ψηφισαμένης δὲ αὐτῷ τῆς βουλῆς τοῖς τε χρήμασιν ἐς τὰ παρόντα χρῆσθαι καὶ Μακεδονίας ἄρχειν καὶ τῆς Ἰλλυρίδος ἐπὶ τῇ Μακεδονίᾳ, τὰ μὲν ἐν τοῖς Ἰλλυριοῖς τρία τέλη τοῦ στρατοῦ παραλαμβάνει, Οὐατινίου τοῦ πρότερον ἄρχοντος Ἰλλυριῶν παραδόντος, ἓν δὲ ἐκ Μακεδονίας ἀφείλετο Γάιον, τὸν ἀδελφὸν Ἀντωνίου. τέσσαρα δὲ ἐπὶ τούτοις ἄλλα συναγαγὼν ὀκτὼ τὰ πάντα εἶχε, Γαΐῳ Καίσαρι τὰ πολλὰ αὐτῶν ἐστρατευμένα. εἶχε δὲ καὶ ἱππέων πλῆθος καὶ ψιλοὺς καὶ τοξότας, καὶ τοὺς Μακεδόνας ἐπαινῶν ἐς τὸν Ἰταλικὸν ἤσκει τρόπον. ἀγείροντι δὲ αὐτῷ στρατὸν ἔτι καὶ χρήματα συντυχία Θρᾴκιος τοιάδε γίγνεται. Πολεμοκρατία, γυνή τινος τῶν βασιλίσκων, ἀναιρεθέντος αὐτῇ τοῦ ἀνδρὸς ὑπὸ ἐχθρῶν δείσασα περὶ τῷ παιδὶ ἔτι ὄντι μειρακίῳ, ἧκεν αὐτὸν φέρουσα καὶ ἐνεχείρισε Βρούτῳ, ἐνεχείρισε δὲ καὶ τοὺς τοῦ ἀνδρὸς θησαυρούς. ὁ δὲ τὸν μὲν παῖδα Κυζικηνοῖς ἀνατρέφειν παρέδωκε, μέχρι σχολάσειεν ἐπὶ τὴν βασιλείαν καταγαγεῖν, ἐν δὲ τοῖς θησαυροῖς εὗρε παράδοξον χρυσίου τι πλῆθος καὶ ἀργύρου.", "st": "4.75"}, {"sp": "N", "t": "καὶ τοῦτο μὲν ἔκοπτε καὶ νόμισμα ἐποίει· ὡς δὲ ἦλθέ τε ὁ Κάσσιος καὶ ἔδοξε Λυκίους καὶ Ροδίους προεξαιρεῖν, ἐτράπετο Λυκίων ἐπὶ Ξανθίους πρώτους. οἱ δὲ τά τε προάστεια σφῶν καθεῖλον, ἵνα μὴ ἐς κατάλυσιν αὐτοῖς ὁ Βροῦτος μηδ’ ἐς ὕλην ἔχῃ χρῆσθαι, καὶ τὴν πόλιν περιταφρεύσαντες ἀπεμάχοντο ἀπὸ τῆς τάφρου, τὸ μὲν βάθος οὔσης πεντήκοντα ποδῶν βαθυτέρας, τὸ δὲ πλάτος κατὰ λόγον τοῦ βάθους, ὥστε παρ’ αὐτὴν ἑστῶτες ἠκόντιζόν τε καὶ ἐτόξευον ὥσπερ ἐν μέσῳ ποταμὸν ἔχοντες ἀπέρατον. ὁ δὲ Βροῦτος αὐτὴν ἔχου βιαζόμενος καὶ σκεπαστήρια τῶν ἐργαζομένων προυτίθει καὶ τὸν στρατὸν ἐς ἡμέραν καὶ νύκτα ἐμέριζε, καὶ τὴν ὕλην μακρόθεν, ὥσπερ ἐν τοῖς ἀγῶσι, σὺν δρόμῳ καὶ βοῇ μετέφερεν, οὐδὲν ἐκλείπων σπουδῆς καὶ πόνου. ὅθεν αὐτῷ τὸ ἔργον ἐλπισθὲν ἢ οὐκ ἔσεσθαι κωλυόντων τῶν πολεμίων ἢ πολλοῖς μησὶ μόλις ἔσεσθαι, ὀλίγαις ἡμέραις ἐξείργαστο, καὶ οἱ Ξάνθιοι κατακλεισθέντες ἐπολιορκοῦντο.", "st": "4.76"}, {"sp": "N", "t": "καὶ αὐτοῖς ὁ Βροῦτος τοὺς μὲν ἐκ μηχανημάτων εἰς τὰ τείχη, τοὺς δὲ ἐκ ποδὸς ἐπῆγεν ἐπὶ τὰς πύλας καὶ πάντας ἐνήλλασσε συνεχῶς. οἱ δὲ ἀκμῆσιν αἰεὶ κεκμηκότες συμφερόμενοι καὶ τετρωμένοι πάντες, ὅμως ὑπέμενον, ἕως σφίσιν αἱ ἐπάλξεις διέμενον. ὡς δὲ καὶ αὗται κατεσύρησαν καὶ οἱ πύργοι διερρώγεσαν, ὑποτοπήσας τὸ ἐσόμενον ὁ Βροῦτος ἐκέλευσε τὰς ἐφέδρους τῶν πυλῶν τάξεις ἀποστῆναι· καὶ οἱ Ξάνθιοι νομίσαντες ἀφυλαξίαν καὶ ἀμέλειαν εἶναι νυκτὸς ἐξέδραμον μετὰ λαμπάδων ἐπὶ τὰ μηχανήματα. ταχὺ δὲ ἐκ συνθήματος αὐτοῖς τῶν Ῥωμαίων ἐπιδραμόντων, συνέφευγον αὖθις ἐς τὰς πύλας· καὶ τῶν φυλάκων αὐτὰς προαποκλεισάντων ὑπὸ δέους, μὴ συνεσπέσοιεν οἱ πολέμιοι, φθόρος ἦν Ξανθίων πολὺς ἀμφὶ ταῖς πύλαις ἀποκεκλεισμένων.", "st": "4.77"}, {"sp": "N", "t": "οὐ πολὺ δὲ ὕστερον ἐξέδραμον αὖθις οἱ λοιποὶ περὶ μεσημβρίαν, ἀναχωρούσης πάλιν τῆς τάξεως, καὶ ἐνέπρησαν τὰ μηχανήματα ἅπαντα ἀθρόως. πεπετασμένων δ’ αὐτοῖς τῶν πυλῶν διὰ τὸ πρότερον πάθος, συνεισέπεσον ἀμφὶ δισχιλίους μάλιστα Ῥωμαίων. καὶ ἑτέροις δὲ εἰσωθιζομένοις ἀμφὶ τὴν εἴσοδον ἐπέπεσον αἰφνίδιον αἱ πύλαι, εἴθ’ ὑπό του Ξανθίων εἴτε καὶ αὐτομάτως τῶν χαλαστηρίων διαρραγέντων, ὥστε τῶν ἐσβιασαμένων Ῥωμαίων τοὺς μὲν ἀπολέσθαι, τοὺς δὲ ἔνδον ἀποληφθῆναι, τὰς πύλας οὐ δυναμένους ἔτι ἀνασπάσαι, χωρὶς ἀνασπαστηρίων γενομένας. βαλλόμενοι δ’ ἐν τοῖς στενωποῖς ἄνωθεν ὑπὸ τῶν Ξανθίων, βιασάμενοί ποτε μόλις ἐς τὴν ἀγορὰν ἐγγὺς οὖσαν διέδραμον· κἀνταῦθα τῶν μὲν συμπλεκομένων σφίσι κρατοῦντες, τοξευόμενοι δὲ χαλεπῶς καὶ οὐδὲν ἔχοντες αὐτοὶ τόξον ἢ ἀκόντιον, παρὰ τὸ Σαρπηδόνειον, ἵνα μὴ κυκλωθεῖεν, διέδραμον. οἱ δ’ ἔξω τείχους Ῥωμαῖοι περὶ τῶν ἔνδον ἀγανακτοῦντές τε καὶ δεδιότες, Βρούτου περιθέοντος αὐτούς, ἐς πᾶσαν ἐμερίζοντο πεῖραν, οὔτε τὰς πύλας δυνάμενοι ῥῆξαι σιδήρῳ περιβεβλημένας, οὔτε κλιμάκων ἢ πύργων ἐμπεπρησμένων εὐποροῦντες. ἀλλ’ οἱ μὲν ἐσχεδίαζον κλίμακας, οἱ δὲ κεραίας τοῖς τείχεσι προστιθέντες ὡς διὰ κλιμάκων ἐπεχείρουν, οἱ δὲ καὶ σιδήρια ὀξέα καλωδίοις περιτιθέντες ἐσφενδόνων τὰ σιδήρια ἐς τὸ τεῖχος ἄνω καί, ὅτε καταπαγείη τινὰ αὐτῶν, ἑαυτοὺς ἀνίμων.", "st": "4.78"}, {"sp": "N", "t": "Οἰνοανδεῖς δὲ γείτονες, διὰ τὴν ἐς τοὺς Ξανθίους ἔχθραν τῷ Βρούτῳ συμμαχοῦντες, διὰ τῶν κρημνῶν ἐπετροβάτουν ἄνω· καὶ αὐτοὺς ἰδόντες οἱ Ῥωμαῖοι ἐμιμοῦντο ἐπιμόχθως. καὶ πολλοὶ μὲν ἐξέπιπτον, εἰσὶ δ’ οἳ τὸ τεῖχος ὑπερβάντες καὶ πυλίδα ἀνέῳξαν, ἣ προεσταύρωτο πυκνοτάτοις σταυροῖς, καὶ τοὺς εὐτολμοτάτους αἰωρουμένους ὑπὲρ τὰ σταυρώματα ἐσεδέχοντο. καὶ πλείους γενόμενοι τὰς πύλας ἔκοπτον, οὐ περιβεβλημένας ἔτι τῷ σιδήρῳ τὰ ἐντός, ἀντικοπτόντων αὐτοῖς ἅμα ἔξωθεν ἑτέρων ἐς τὸ αὐτὸ καὶ συνεργούντων. Ξανθίων δὲ σὺν μεγάλῃ πάνυ βοῇ τοῖς ἀμφὶ τὸ Σαρπηδόνειον οὖσι Ῥωμαίοις ἐπιθεόντων, δείσαντες ὑπὲρ αὐτῶν, ὅσοι περὶ τὰς πύλας ἔνδοθέν τε καὶ ἔξωθεν αὐτὰς ἔκοπτον, ὑπὸ μανιώδους ὁρμῆς ἐβιάζοντο καὶ διαρρήξαντες ἐσέδραμον ἀθρόοι, δύνοντος ἄρτι τοῦ θεοῦ, μετὰ ἀλαλαγῆς, ἵνα σύμβολον εἴη τοῖς ἐντὸς οὖσιν.", "st": "4.79"}, {"sp": "N", "t": "ἁλούσης δὲ τῆς πόλεως οἱ Ξάνθιοι ἐς τὰς οἰκίας συνέτρεχον καὶ τὰ φίλτατα σφῶν κατέκαινον, ἑκόντα τὴν σφαγὴν ὑπέχοντα. οἰμωγῆς δὲ γιγνομένης ὁ Βροῦτος νομίσας ἁρπαγὴν εἶναι τὸν στρατὸν ἀνεῖργε διὰ κηρύκων· ὡς δὲ ἔγνω τὸ γιγνόμενον, ᾤκτειρεν ἀνδρῶν φρόνημα φιλελεύθερον καὶ σπονδὰς περιέπεμπεν. οἱ δὲ καὶ τοὺς φέροντας ἔβαλλον καὶ τὰ σφέτερα πάντα ἀνελόντες ἐς πυρὰς προνενης μένας ἐν ταῖς οἰκίαις ἐπέθεσαν καὶ τὸ πῦρ ἅψαντες ἑαυτοὺς ἐπικατέσφαξαν. Βροῦτος δὲ τῶν ἱερῶν περισώσας ὅσα ἐδύνατο, μόνους θεράποντας εἷλε Ξανθίων καὶ ἐκ τῶν ἀνδρῶν γύναια ὀλίγα ἐλεύθερα καὶ ἄνδρας οὐδὲ ἐς ἑκατὸν καὶ πεντήκοντα πάντας.", "st": "4.80"}, {"sp": "N", "t": "Ξάνθιοι μὲν δὴ τρίτον ὑπὸ σφῶν αὐτῶν ἀπώλλυντο ἐλευθερίας οὕνεκα. καὶ γὰρ ἐπὶ Ἁρπάγου τοῦ Μήδου, Κύρῳ τῷ μεγάλῳ στρατηγοῦντος, ὧδε σφᾶς ἀντὶ δουλοσύνης διέφθειραν, καὶ τάφος Ξανθίοις ἡ πόλις ἀνειληθεῖσιν ὑπὸ Ἁρπάγου τότε ἐγένετο· καὶ ἐπὶ Ἀλεξάνδρου τοῦ Φιλίππου φασὶν ὅμοια παθεῖν, οὐχ ὑποστάντας οὐδὲ Ἀλεξάνδρῳ μετὰ τοσῆσδε γῆς ἀρχὴν ὑπακοῦσαι.", "st": "4.80"}, {"sp": "N", "t": "Βροῦτος δὲ ἐς Πάταρα ἀπὸ Ξάνθου κατῄει, πόλιν ἐοικυῖαν ἐπινείῳ Ξανθίων, καὶ περιστήσας αὐτοῖς τὸν στρατὸν ἐκέλευσεν ἐς πάντα ὑπακούειν ἢ τὰς Ξανθίων συμφορὰς προσδέχεσθαι· προσήγοντό τε αὐτοῖς οἱ Ξάνθιοι ὀδυρόμενοι τὰ σφέτερα καὶ παραινοῦντες ἀμείνονα βουλεύσασθαι. Ξανθίοις δὲ οὐδὲν ἀποκριναμένων πω τῶν Παταρέων, ἐδίδου τὸ λοιπὸν αὐτοῖς τῆς ἡμέρας ἐς σκέψιν καὶ ἀνεχώρει. ἅμα δὲ ἡμέρᾳ προσῆγεν. οἱ δὲ ἀπό τε τῶν τειχῶν ἐβόων ὑπακούειν, ἐς ὅ τι βούλοιτο, καὶ τὰς πύλας ἀνεῴγνυον. ὁ δ’ ἐσελθὼν ἔκτεινε μὲν οὐδένα οὐδ’ ἐξήλασε, χρυσὸν δὲ καὶ ἄργυρον, ὅσον ἡ πόλις εἶχε, συνενεγκὼν ἐκέλευε καὶ τὸν ἰδιωτικὸν ἑκάστους ἐσφέρειν ὑπὸ ζημίαις καὶ μηνύμασιν, οἵοις καὶ Κάσσιος ἐκήρυξεν ἐν Ῥόδῳ. καὶ οἱ μὲν ἐσέφερον, θεράπων δὲ τὸν δεσπότην ἐμήνυσε χρυσίον κρύψαι καὶ πεμφθέντι λοχαγῷ τὸ χρυσίον ἔδειξεν. ἀγομένων δὲ ἁπάντων ὁ μὲν δεσπότης ἐσιώπα, ἡ δὲ ἐκείνου μήτηρ περισῴζουσα τὸν υἱὸν εἵπετο, βοῶσα αὐτὴ τὸ χρυσίον κρύψαι. ὁ δὲ οἰκέτης, οὐδὲ ἀνερωτώμενος, τὴν μὲν ἤλεγχε ψευδομένην, τὸν δὲ κρύψαντα. καὶ ὁ Βροῦτος τὸν μὲν νεανίαν ἀπεδέξατο τῆς σιωπῆς καὶ τὴν μητέρα τοῦ πάθους καὶ μεθῆκεν ἀμφοτέρους ἀπαθεῖς ἀπιέναι τὸ χρυσίον φερομένους, τὸν δὲ οἰκέτην ὡς πέρα τοῦ προστάγματος ἐπιβουλεύσαντα τοῖς δεσπόταις ἐκρέμασε.", "st": "4.81"}, {"sp": "N", "t": "τῷ δ’ αὐτῷ χρόνῳ καὶ Λέντλος ἐπιπεμφθεὶς Ἀνδριάκῃ Μυρέων ἐπινείῳ τήν τε ἅλυσιν ἔρρηξε τοῦ λιμένος καὶ ἐς Μύρα ἀνῄει. Μυρέων δέ, ἃ προσέτασσε, δεχομένων χρηματισάμενος ὁμοίως ἐς Βροῦτον ἐπανῄει. καὶ τὸ κοινὸν τὸ Λυκίων ἐς Βροῦτον ἐπρέσβευε, συμμαχήσειν τε ὑπισχνούμενοι καὶ ἐσοίσειν, ὅσα δύναιντο. ὁ δὲ αὐτοῖς ἐσφοράς τε ἐπέβαλε καὶ Ξανθίων τοὺς ἐλευθέρους ἀπεδίδου τῇ πόλει καὶ τὸ ναυτικὸν τὸ Λυκίων ἅμα ταῖς ἄλλαῖς ναυσὶν ἐκέλευε περιπλεῖν ἐς Ἄβυδον, ἔνθα καὶ τὸ πεζὸν αὐτὸς ἦγε καὶ Κάσσιον ἐξ Ἰωνίας ἀνέμενεν, ὡς ἐς Σηστὸν ὁμοῦ διαβαλοῦντες. Μοῦρκος δὲ ἐν Πελοποννήσῳ ναυλοχῶν Κλεοπάτραν, ἐπειδὴ ἔμαθεν αὐτὴν ὑπὸ χειμῶνος ἀμφὶ τῇ Λιβύῃ βλαβεῖσαν καὶ τὰ ναυάγια εἶδε μέχρι τῆς Λακωνικῆς ἐκφερόμενα καὶ σὺν ἀρρωστίᾳ μόλις αὐτὴν ἐς τὰ ἑαυτῆς ἐπανιοῦσαν, ἵνα μὴ δι’ ἀπραξίας εἴη μετὰ τοσοῦδε στόλου, διέπλευσεν ἐπὶ Βρεντεσίου καὶ ἐς τὴν ἐπικειμένην τῷ λιμένι νῆσον ὁρμισάμενος ἐκώλυε τὴν ὑπόλοιπον τῶν πολεμίων στρατιὰν ἢ ἀγορὰν ἐς Μακεδονίαν περαιοῦσθαι. καὶ αὐτὸν ὁ Ἀντώνιος ἀπεμάχετο ναυσὶ μακραῖς, ὅσαις εἶχεν, ὀλίγαις· ἀπεμάχετο δὲ καὶ πύργοις, οὓς ἐπῆγεν ἐπὶ σχεδιῶν, ὅτε τὸν στρατὸν ὁλκάσιν ἐκπέμποι κατὰ μέρη, πνεῦμα ἀπὸ τῆς γῆς πολὺ φυλάσσων, ἵνα μὴ καταλαμβάνοιντο ὑπὸ τοῦ Μούρκου. κακοπαθῶν δὲ ἐκάλει Καίσαρα, Πομπηίῳ Σέξστῳ κατὰ Σικελίαν περὶ αὐτῆς Σικελίας ναυμαχοῦντα.", "st": "4.82"}, {"sp": "N", "t": "ὧδε δὲ εἶχε καὶ τὰ περὶ Πομπήιον. νεώτερος ὢν ὅδε τῶν Μάγνου Πομπηίου παίδων ὑπερώφθη μὲν τὰ πρῶτα ὑπὸ Γαΐου Καίσαρος περὶ Ἰβηρίαν, ὡς οὐδὲν μέγα διὰ νεότητα καὶ ἀπειρίαν ἐργασόμενος, καὶ ἠλᾶτο περὶ τὸν ὠκεανὸν λῃστεύων σὺν ὀλίγοις καὶ λανθάνων, ὅτι εἴη Πομπήιος. πλεόνων δὲ ἐς τὸ λῃστεύειν αὐτῷ συνιόντων χείρ τε ἦν ἤδη καρτερὰ καὶ ἐξεφαίνετο Πομπήιος ὤν. καὶ αὐτίκα, ὅσοι τοῦ πατρὸς ἢ τοῦ ἀδελφοῦ στρατιῶται γεγονότες ἠλῶντο, ὡς ἐς οἰκεῖον ἡγεμόνα συνέτρεχον, καὶ Ἀραβίων ἐκ Λιβύης ἀφίκετ’ αὐτῷ, ἀφῃρημένος τὰ πατρῷα, ὥς μοι προείρηται. ὧδε δὲ αὐτῷ πλήθους γενομένου, ἔργα τε ἦν ἤδη λῃστηρίου δυνατώτερα καὶ ὄνομα τοῦ Πομπηίου ἀνὰ ὅλην τὴν Ἰβηρίαν, εὐρυτάτην ἐθνῶν οὖσαν, περιθέοντός τε καὶ μεθιπταμένου καὶ ἐς χεῖρας οὐχ ὑπομένοντος ἐλθεῖν τοῖς ἡγουμένοις αὐτῆς ὑπὸ Γαΐῳ Καίσαρι. ὧν ὁ Γαίος πυνθανόμενος ἔπεμπε σὺν στρατῷ πλέονι Καρρίναν ἐκπολεμήσοντα Πομπήιον. ὁ δὲ καὶ τούτῳ, κουφότερος ὤν, ἐπεφαίνετο ἄφνω καὶ ἀφιπτάμενος ἠνώχλει καὶ πόλεις ἤδη τινὰς ᾕρει βραχυτέρας τε καὶ μείζους.", "st": "4.83"}, {"sp": "N", "t": "καὶ ὁ Γάιος ἔπεμψε τῷ Καρρίνᾳ διάδοχον Ἀσίνιον Πολλίωνα πολεμεῖν Πομπηίῳ. ὅν τινα πόλεμον αὐτῶν ὁμοίως διαφερόντων, ὅ τε Γάιος Καῖσαρ ἀνῃρέθη καὶ ἡ βουλὴ κατεκάλει Πομπήιον. ὁ δὲ ἐν Μασσαλίᾳ γενόμενος περιεσκόπει ἔτι τὰ ἐν Ῥώμῃ. αἱρεθεὶς δὲ καὶ τῆς θαλάσσης ἄρχειν, καθὰ ἦρχεν αὐτοῦ καὶ ὁ πατήρ, ἐς μὲν τὴν πόλιν οὐδ’ ὣς ἀνῆλθεν, ὅσαι δὲ νῆες ἐν τοῖς λιμέσιν ἦσαν, λαβὼν ἐξέπλευσε σὺν αἷς εἶχεν ἀπὸ τῆς Ἰβηρίας. ἐπιγενομένης δὲ τῆς τῶν τριῶν ἀρχῆς ἐς Σικελίαν διέπλευσε καὶ Βιθυνικὸν ἄρχοντα αὐτῆς, οὐ παριέντα οἱ τὴν νῆσον, ἐπολιόρκει, μέχρι προγραφέντες ἐπὶ θανάτῳ καὶ φυγόντες ἐκ Ῥώμης Ἵρτιός τε καὶ Φάννιος ἔπεισαν ἐκστῆναι Πομπηίῳ Βιθυνικὸν Σικελίας.", "st": "4.84"}, {"sp": "N", "t": "ὧδε μὲν ὁ Πομπήιος Σικελίας ἐκράτησε, καὶ ναῦς ἔχων καὶ νῆσον ἐπικειμένην τῇ Ἰταλίᾳ καὶ στρατὸν ἤδη πολύν, ὅσον τε πρότερον εἶχε καὶ ὅσον οἱ φεύγοντες ἐκ Ῥώμης ἐλεύθερον ἢ δοῦλον ἦγον ἢ αἱ πόλεις ἐξ Ἰταλίας ἔπεμπον αὐτῷ, αἱ ἐς ἐπινίκια τοῖς στρατοῖς ἐπηγγελμέναι. ταῖς γὰρ δὴ γνώμαις αἵδε μάλιστα τὴν νίκην τῶν τριῶν ἀνδρῶν ἀπεύχοντο καί, ὅσα δύναιντο, κρύφα ἀντέπρασσον· ἀποδιδράσκοντές τε τῶν πατρίδων ὡς οὐκέτι πατρίδων οἱ δυνάμενοι συνέφευγον ἐς Πομπήιον, ἀγχοτάτω τε ὄντα καὶ περιφίλητον ἅπασιν ἐν τῷ τότε. παρῆσαν δ’ αὐτῷ καὶ ναυτικοὶ ἄνδρες ἐκ Λιβύης καὶ Ἰβηρίας, ἔμπειροι θαλάσσης, ὥστε καὶ ἡγεμόσι καὶ ναυσὶ καὶ πεζῷ καὶ χρήμασιν ὁ Πομπήιος ἐπῆρτο. καὶ τούτων ὁ Καῖσαρ ἐπήκοος ὢν ἔπεμπε Σαλουιδιηνὸν ἐπὶ νεῶν στόλου, Πομπήιον ὡς εὐχερὲς ἔργον ἐξελεῖν παραπλέοντα· καὶ αὐτὸς ᾔει διὰ τῆς Ἰταλίας ὡς αὐτῷ Σαλουιδιηνῷ συμβολήσων περὶ Ῥήγιον. Σαλουιδιηνῷ δ’ ὁ Πομπήιος ἀπαντᾷ μεγάλῳ στόλῳ, καὶ πρὸ τοῦ πορθμοῦ ναυμαχίας ἀμφὶ τὸ Σκύλλαιον αὐτοῖς γενομένης αἱ μὲν τοῦ Πομπηίου νῆες, κουφότεραί τε οὖσαι καὶ ναυτικωτέρων ἀνδρῶν, ταχυτῆτι καὶ ἐμπειρίᾳ προῦχον, αἱ δὲ Ῥωμαίων ἅτε βαρύτεραι καὶ μείζους ἐμόχθουν. ὡς δ’ ὁ συνήθης τοῦ πορθμοῦ κλύδων ἐπεγίγνετο καὶ διεσπᾶτο ἡ θάλασσα ἐφ’ ἑκάτερα ὑπὸ τοῦ ῥοῦ, οἱ μὲν ἧσσον ἐμόχθουν ὑπὸ ἔθους τοῦ κλύδωνος, οἱ δ’ ἀμφὶ τὸν Σαλουιδιηνόν, οὔτε ἑστῶτες βεβαίως ὑπὸ ἀηθείας οὔτε τὰς κώπας ἔτι ἀναφέρειν δυνάμενοι οὔτε τὰ πηδάλια ἔχοντες εὐπειθῆ, συνεταράσσοντο, ὥστε κλίνοντος ἐς δείλην ἑσπέραν ἤδη τοῦ θεοῦ πρότερος ὁ Σαλουιδιηνὸς ἀνεκάλει. ὑπεχώρει δὲ καὶ ὁ Πομπήιος. νῆες δὲ ἑκατέρων ἴσαι διεφθάρατο, καὶ τὰς λοιπὰς λελωβημένας τε καὶ πεπονημένας ὁ Σαλουιδιηνὸς ἐπεσκεύαζεν, ὑποχωρήσας ἐς λιμένα πρὸ τοῦ πορθμοῦ Βαλαρόν.", "st": "4.85"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ἐπελθὼν ῥηγίνοις μὲν καὶ Ἱππωνεῦσι μεγάλας πίστεις αὐτὸς ἔδωκεν ἀναλύσειν αὐτοὺς ἐκ τῶν ἐπινικίων (ἐδεδίει γὰρ ὄντας ἐπὶ τοῦ πορθμοῦ μάλιστα), καλοῦντος δ’ αὐτὸν Ἀντωνίου κατὰ σπουδὴν διέπλει πρὸς αὐτὸν ἐς τὸ Βρεντέσιον, ἐν ἀριστερᾷ ἔχων Σικελίαν καὶ Πομπήιον καὶ Σικελίαν ὑπερθέμενος ἐν τῷ τότε. Μοῦρκος δὲ ἐπιόντος τοῦ Καίσαρος, ἵνα μὴ ἐν μέσῳ γένηται Ἀντωνίου τε καὶ Καίσαρος, μικρὸν ἀναχωρήσας τοῦ Βρεντεσίου, τὰς ὁλκάδας ἐφύλασσεν ἐν τῷ πόρῳ τὸν στρατὸν ἐς Μακεδονίαν ἐκ τοῦ Βρεντεσίου διαφερούσας. αἱ δὲ προεπέμποντο μὲν ὑπὸ τριήρων, πνεύματος δὲ πολλοῦ κατὰ θεὸν οἰκείου γενομένου διέπτησαν ἀδεῶς, οὐδὲν τῶν προπομπῶν δεηθεῖσαι. καὶ ὁ Μοῦρκος ἀχθόμενος ὅμως ἐφήδρευεν ἐπανιούσαις κεναῖς. αἱ δὲ καὶ τότε, καὶ αὖθις ἕτερον στρατὸν ἄγουσαι, διέπλεον ἱστίοις στρογγύλοις, μέχρι πᾶς ὁ στρατὸς καὶ ἐπ’ αὐτῷ Καῖσάρ τε καὶ Ἀντώνιος διέπλευσαν. καὶ ὁ Μοῦρκος ὑπό του δαιμόνων βεβλάφθαι νομίζων, ὑπέμενεν ὅμως τὰς ἐκ τῆς Ἰταλίας αὐτοῖς διαπλεούσας παρασκευὰς ἢ τροφὰς ἢ τὸν ἐπισυλλεγόμενον στρατὸν βλάπτων, ὅσα δύναιτο. καὶ αὐτῷ Δομίτιος Ἀηνόβαρβος ὑπὸ τῶν ἀμφὶ τὸν Κάσσιον ἐς τὸ αὐτὸ ἔργον, ὡς χρησιμώτατον δή, μετὰ νεῶν ἄλλων πεντήκοντα καὶ τέλους ἑτέρου καὶ τοξοτῶν ἐπέμφθη· ὡς γὰρ οὐκ ἔχουσι τοῖς ἀμφὶ τὸν Καίσαρα τροφὰς δαψιλεῖς ἑτέρωθεν ἐδόκει τὰ ἐκ τῆς Ἰταλίας διακλείσειν.", "st": "4.86"}, {"sp": "N", "t": "οἱ μὲν δὴ ναυσί τε μακραῖς ἑκατὸν καὶ τριάκοντα καὶ ὑπηρετικαῖς πλέοσι καὶ στρατῷ πολλῷ διαπλέοντες ἠνώχλουν, Δεκίδιος δὲ καὶ Νωρβανός οὓς ὁ Καῖσαρ καὶ Ἀντώνιος μετὰ ὀκτὼ τελῶν ἐς Μακεδονίαν προεπεπόμφεσαν, ἐκ Μακεδονίας ἐχώρουν ἐπὶ Θρᾴκης τῆς ὀρείου χιλίους καὶ πεντακοσίους σταδίους, μέχρι πόλιν ὑπερβάντες Φιλίππους τὰ στενὰ Κορπίλων καὶ Σαπαίων, τῆς Ῥασκουπόλιδος ὄντα ἀρχῆς, κατέλαβον, ᾗ μόνῃ διελθεῖν ἔστιν ἐς τὴν Εὐρώπην ἐκ τῆς Ἀσίας τὴν γνώριμον ὁδόν. καὶ τοῦτο τοῖς ἀμφὶ τὸν Κάσσιον, ἐς Σηστὸν ἐξ Ἀβύδου περάσασι, πρῶτον ἀντεκεκρούκει. Ῥασκούπολις δὲ καὶ Ῥάσκος ἤστην ἀδελφὼ Θρᾳκίω βασιλίσκω, μιᾶς ἄρχοντε χώρας, οἳ τότε τῇ γνώμῃ περὶ τῆς συμμαχίας διεφέροντο. καὶ Ῥάσκος μὲν τοῖς ἀμφὶ τὸν Ἀντώνιον συνεμάχει, Ῥασκούπολις δὲ τοῖς ἀμφὶ τὸν Κάσσιον, τρισχιλίους ἱππέας ἔχων ἑκάτερος. πυνθανομένοις δὲ τοῖς ἀμφὶ τὸν Κάσσιον περὶ τῶν ὁδῶν ὁ Ῥασκούπολις ἔφη τὴν μὲν δι’ Αἴνου καὶ Μαρωνείας ἐπίτομόν τε καὶ συνήθη καὶ λεωφόρον οὖσαν ἐπὶ τὰ Σαπαίων στενὰ ἄγειν, κατεχόντων δὲ αὐτὰ τῶν πολεμίων ἀμήχανα ἐς δίοδον εἶναι, τὴν δὲ περίοδον τριπλασίονά τε καὶ χαλεπήν.", "st": "4.87"}, {"sp": "N", "t": "οἱ δὲ τοὺς πολεμίους ὑπολαβόντες οὐκ ἐς κώλυσιν μὲν ὁδῶν αὑτοῖς ἀπαντᾶν, τροφῶν δὲ ἀπορίᾳ ἐς Θρᾴκην ἀντὶ Μακεδονίας ὑπερβῆναι, ἐβάδιζον ἐπὶ Λἴνου καὶ Μαρωνείας, ὅθεν ἐπὶ Λυσιμαχείας τε καὶ Καρδίας, αἳ τὸν ἰσθμὸν τῆς Θρᾳκίου χερρονήσου διαλαμβάνουσιν ὥσπερ πύλαι, μετὰ δὲ ἄλλην ἡμέραν ἐς τὸν Μέλανα κόλπον ἀφίκοντο. καὶ τὸν στρατὸν ἐξετάζουσιν αὐτοῖς ἐγένοντο πάντες ὁπλιτῶν ἐννεακαίδεκα τέλη, Βρούτου μὲν ὀκτώ, Κασσίου δὲ ἐννέα, ἐντελὲς οὐδέν, ἀλλ’ ἐς δύο που τέλη μάλιστα ἀναπληρούμενα, ὡς γίνεσθαι μυριάδας ὁπλιτῶν ἀμφὶ τὰς ὀκτώ. ἱππέες δὲ ἦσαν Βρούτῳ μὲν Κελτοὶ καὶ Λυσιτανοὶ τετρακισχίλιοι καὶ Θρᾷκες καὶ Ἰλλυριοὶ Παρθηνοὶ καὶ Θεσσαλοὶ δισχίλιοι, Κασσίῳ δὲ Ἴβηρές τε καὶ Κελτοὶ δισχίλιοι καὶ ἱπποτοξόται Ἄραβές τε καὶ Μῆδοι καὶ Παρθυαῖοι τετρακισχίλιοι. σύμμαχοι δὲ εἵποντο βασιλέες καὶ τετράρχαι Γαλατῶν τῶν ἐν Ἀσίᾳ, πεζόν τε ἄγοντες πολὺν ἄλλον καὶ ἱππέας ὑπὲρ πεντακισχιλίους.", "st": "4.88"}, {"sp": "N", "t": "τοσήδε μὲν στρατιὰ τοῖς ἀμφὶ τὸν Κάσσιον ἐπὶ τοῦ Μέλανος κόλπου διεκρίθη, καὶ τοσῇδε ἐχώρουν ἐπὶ τὸ ἔργον, τὴν λοιπὴν ἔχοντες ἐπὶ τῶν ἀλλαχόθι χρειῶν. καθήραντες δὲ αὐτὴν τοῖς νομιζομένοις ἀνεπλήρουν τὰς ἐκ τῶν ἐπηγγελμένων τισὶν ὀφειλομένας ἔτι δωρεάς, πολλῆς μὲν περιουσίας χρημάτων πεφροντικότες, οἰκειούμενοι δὲ ταῖς δόσεσιν αὐτούς, Γαΐῳ μάλιστα Καίσαρι τοὺς πλέονας ἐστρατευμένους, μή τις ἐς τὴν ὄψιν ἢ ὁμωνυμίαν τοῦ νέου Καίσαρος νεωτερίσειεν ἐλθόντος. καὶ αὖθις ἔδοξε τούτου χάριν καὶ δημηγορῆσαι. βῆμά τε οὖν ἐπήχθη μέγα, καὶ οἱ στρατηγοὶ μετὰ τῶν ἀπὸ τῆς βουλῆς μόνων ἐς αὐτὸ ἀναβάντες, ὁ δὲ στρατὸς αὐτῶν, ὅ τε ἴδιος καὶ συμμαχικός, κάτω περιστάντες, ἥδοντο εὐθὺς ἐπὶ τῇ ὄψει τοῦ πλήθους ἀλλήλων ἑκάτεροι, ἰσχυροτάτῃ σφίσι φανείσῃ· καὶ θάρσος ἦν ἀμφοτέροις αὐτίκα καὶ ἐλπὶς ἰσχυρά, τοσῶνδε στρατηγοῦσιν. αὐτά τε πρῶτα πάντων τάδε τοῖς στρατηγοῖς τὸν στρατὸν ἐς πίστιν συνῆγε· τίκτουσι γὰρ εὔνοιαν ἐλπίδες κοιναί. θροῦ δὲ ὡς ἐν τοσούτοις ὄντος οἵ τε κήρυκες καὶ οἱ σαλπιγκταὶ σιωπὴν ἐποίουν, καὶ γενομένης ποτὲ ὁ Κάσσιος (προῦχε γὰρ ἡλικίᾳ) προελθὼν μικρὸν ἐκ τῆς τάξεως ἐς τὸ μέσον ἔλεξεν ὧδε·", "st": "4.89"}, {"sp": "N", "t": "“ὁ μὲν ἀγὼν πρῶτον ἡμᾶς, ὦ συστρατιῶται, κοινὸς ὢν ἐς πίστιν ἀλλήλοις συνάγει· συνάπτει δὲ καὶ ὅσα ὑμῖν ὑποσχόμενοι πάντα ἔδομεν, ὃ μεγίστη πίστις ἐστὶ καὶ περὶ ὧν ἐς τὸ μέλλον ὑπισχνούμεθα. αἱ δὲ ἐλπίδες εἰσὶν ἐν τῇ ἀρετῇ, ὑμῶν τε τῶν στρατευομένων καὶ ἡμῶν, οὓς ἐπὶ τοῦ βήματος τοῦδε ὁρᾶτε τοσούσδε καὶ τοιούσδε ἄνδρας ἀπὸ τῆς βουλῆς. ἔστι δὲ καὶ πλῆθος παρασκευῆς, ὅσον ἴστε, σίτου τε καὶ ὅπλων καὶ χρημάτων καὶ νεῶν καὶ συμμάχων κατά τε ἔθνη καὶ βασιλέας. ὥστε τί χρὴ τῷ λόγῳ παρακαλεῖν ἐς προθυμίαν τε καὶ ὁμόνοιαν, οὓς ἥ τε παρασκευὴ καὶ τὰ ἔργα κοινὰ ὄντα συνάγει; περὶ δὲ ὧν διαβάλλουσιν ἡμᾶς δύο ἄνδρες ἐχθροί, ἴστε μὲν αὐτὰ ἀκριβέστατα, καὶ δι’ αὐτὸ συστρατεύεσθε ἡμῖν ἑτοίμως, δοκεῖ δὲ καὶ νῦν ἐπεξελθεῖν ἔτι τὴν αἰτίαν, ἣ μάλιστα ἐπιδείκνυσι τοῦ πολέμου καλλίστην τε οὖσαν ἡμῖν καὶ δικαιοτάτην τὴν πρόφασιν.", "st": "4.90"}, {"sp": "N", "t": "“ἡμεῖς γὰρ Καίσαρα ἐν μὲν τοῖς πολέμοις συστρατευόμενοί τε αὐτῷ μεθ’ ὑμῶν καὶ στρατηγοῦντες ἐπὶ μέγα ᾔρομεν καὶ φίλοι διετελοῦμεν ὄντες, ὡς μὴ δοκεῖν αὐτὸν δι’ ἔχθραν ὑφ’ ἡμῶν ἐπιβεβουλεῦσθαι. τὰ δὲ ἐς τὴν εἰρήνην ἐπίμεμπτος ἦν, οὐχ ἡμῖν τοῖς φίλοις, ἐπεὶ κἀν τούτοις προετιμώμεθα, ἀλλὰ τοῖς νόμοις καὶ τῷ κόσμῳ τῆς πολιτείας, ὧν οὐδεὶς νόμος οὔτε ἀριστοκρατικὸς κύριος οὔτε δημοτικὸς ἔτι ἦν· ἅπερ ἅπαντα οἱ πατέρες ἡμῶν ἥρμοσαν, ὅτε τοὺς βασιλέας ἐκβαλόντες ἐπώμοσαν καὶ ἐπηράσαντο οὐκ ἀνέξεσθαι βασιλέων ἐς τὸ μέλλον ἑτέρων. ᾧ τινι ὅρκῳ βοηθοῦντες οἱ τῶν ὀμωμοκότων ἔκγονοι καὶ τὰς ἀρὰς ἀπερύκοντες ἀφ’ ἑαυτῶν οὐχ ὑπεμείναμεν ἐς πολὺ περιιδεῖν ἕνα ἄνδρα, εἰ καὶ φίλος ἦν ἡμῖν καὶ χρήσιμος, τά τε κοινὰ χρήματα καὶ στρατόπεδα καὶ χειροτονίας ἀρχῶν ἀπὸ τοῦ δήμου καὶ ἡγεμονίας ἐθνῶν ἀπὸ τῆς βουλῆς ἐς ἑαυτὸν περιφέροντα καὶ νόμον ἀντὶ τῶν νόμων καὶ κύριον ἀντὶ τοῦ δήμου καὶ αὐτοκράτορα ἀντὶ τῆς βουλῆς γιγνόμενον ἐς ἅπαντα.", "st": "4.91"}, {"sp": "N", "t": "“ὧν ἴσως ὑμεῖς οὐκ ἀκριβῶς ᾐσθάνεσθε, ἀλλὰ μόνην αὐτοῦ τὴν ἐν τοῖς πολέμοις ἀρετὴν ἑωρᾶτε. νῦν δὲ ῥᾳδίως τε ἂν καὶ ἐκ μόνου τοῦ περὶ ὑμᾶς μέρους καταμάθοιτε. ὁ γὰρ δῆμος ὑμεῖς ἐν μὲν τοῖς πολέμοις ὑπακούετε ἐς πάντα ὡς κυρίοις τοῖς στρατηγοῖς, τὸ δὲ κῦρος τόδε ἐν τοῖς εἰρηνικοῖς ἐφ’ ἡμῖν ἀντιλαμβάνετε αὐτοί, προβουλευούσης μὲν τῆς βουλῆς, ἵνα μὴ σφαλείητε, κρίνοντες δὲ αὐτοὶ καὶ ψηφιζόμενοι κατὰ φυλὰς ἢ λόχους καὶ ἀποφαίνοντες ὑπάτους τε καὶ δημάρχους καὶ στρατηγούς. ἐπὶ δὲ ταῖς χειροτονίαις καὶ τὰ μέγιστα δικάζετε, κολάζοντες ἢ τιμῶντες, ὅτε κολάσεως ἢ τιμῆς ἀξίως ἄρξαιμεν ὑμῶν. ἡ δὲ ἀντίδοσις ἥδε τήν τε ἡγεμονίαν, ὦ πολῖται, ἐς εὐδαιμονίαν ἄκραν ὑπερήγαγε καὶ τοὺς ἀξίους ἐτίμησε, καὶ οἱ τετιμημένοι χάριν εἶχον ὑμῖν. ἀπὸ ταύτης τῆς ἐξουσίας ὕπατον ἐποιήσασθε Σκιπίωνα, ὅτε αὐτῷ περὶ Λιβύην ἐμαρτυρήσατε· καὶ δημάρχους ἐποιεῖσθε ἀνὰ ἔτος ἕκαστον, οὓς ἐβούλεσθε, διοισομένους ἡμῖν ὑπὲρ ὑμῶν, εἰ δέοι. καὶ τί μοι καταλέγειν τὰ πολλά, ὅσα ἴστε;", "st": "4.92"}, {"sp": "N", "t": "“ἀλλ’ οὐκ, ἀφ’ οὗ Καῖσαρ ἐδυνάστευσεν, οὐκ ἀρχήν τινα, οὐ στρατηγόν, οὐχ ὕπατον, οὐ δήμαρχον ἐχειροτονήσατε ἔτι, οὐκ ἐμαρτυρήσατε οὐδενί, οὐκ ἀμοιβὴν εἴχετε δοῦναι μαρτυροῦντες. ἐν κεφαλαίῳ δὲ εἰπεῖν, οὐδὲ εἷς ὑμῖν χάριν ὤφειλεν, οὐκ ἀρχῆς, οὐχ ἡγεμονίας, οὐκ εὐθυνῶν, οὐ δίκης. ὃ δὲ οἴκτιστον ἁπάντων ἐγένετο, οὐδ’ αὐτοῖς ἐδυνήθητε ἐπικουρῆσαι τοῖς δημάρχοις ὑμῶν ὑβριζομένοις, ἥν τινα ἀΐδιον ὑμῶν αὐτῶν ἀρχὴν ἐστήσασθε εἶναι καὶ ἱερὰν καὶ ἄσυλον ἀπεφήνατε, ἀλλὰ καὶ τοὺς ἀσύλους εἴδετε τὴν ἀρχὴν τὴν ἄσυλον καὶ τὴν ἐσθῆτα τὴν ἱερὰν ἐς ὕβριν ἀφαιρουμένους ἀκρίτους, ἀπὸ μόνου προστάγματος, ὅτι ἔδοξαν ὑπὲρ ὑμῶν χαλεπῆναι τοῖς καὶ βασιλέα αὐτὸν ἐθέλουσι προσαγορεῦσαι. ὃ καὶ μάλιστα ἐπαχθῶς ἤνεγκεν ἡ βουλὴ δι’ ὑμᾶς· ὑμετέρα γὰρ καὶ οὐ τῆς βουλῆς ἐστιν ἡ τῶν δημάρχων ἀρχή. ἐπιμέμψασθαι δὲ σαφῶς οὐ δυναμένη τὸν ἄνδρα οὐδ’ ἐς κρίσιν ἐπαγαγεῖν διὰ ἰσχὺν στρατοπέδων, ἃ καὶ αὐτά, τέως ὄντα τῆς πόλεως, ἑαυτοῦ πεποίητο ἴδια, τὸν ἔτι λοιπὸν τρόπον ἀμύνασθαι τὴν τυραννίδα ἐπενόησεν, ἐς τὸ σῶμα ἐπιβουλεύσασα.", "st": "4.93"}, {"sp": "N", "t": "“ἔδει δὲ τὴν μὲν γνώμην γενέσθαι τῶν ἀρίστων, τὸ δὲ ἔργον ὀλίγων. ἐπεὶ δὲ ἐγένετο, αὐτίκα ἡ βουλὴ τὴν κοινὴν γνώμην ἐξέφηνε, σαφῶς μὲν ὅτε καὶ γέρα τυραννοκτονικὰ ἐψηφίζοντο εἶναι· ἐπισχόντος δὲ αὐτοὺς Ἀντωνίου καθ’ ὑπόκρισιν ἀταξίας καὶ οὐδ’ ἡμῶν ἀξιούντων διὰ γέρα τῇ πόλει μᾶλλον ἢ δι’ αὐτὴν τὴν πατρίδα βοηθεῖν, τοῦδε μὲν ἀπέσχοντο, οὐκ ἐθέλοντες ἐφυβρίζειν τῷ Καίσαρι, ἀλλὰ μόνης τῆς τυραννίδος ἀπηλλάχθαι, ἀμνηστίαν δὲ ἁπάντων ἐψηφίσαντο εἶναι καὶ σαφέστερον ἔτι, φόνου μὴ εἶναι δίκας. καὶ μετὰ μικρόν, Ἀντωνίου τὸ πλῆθος ἐφ’ ἡμῖν δημοκοπήσαντος, ἡ βουλὴ καὶ ἀρχὰς ἐθνῶν τῶν μεγίστων καὶ ἡγεμονίας ἔδοσαν ἡμῖν καὶ γῆς ἀπέφηναν ἡγεῖσθαι πάσης ἀπὸ τοῦ Ἰονίου μέχρι Συρίας, πότερον ὡς ἐναγεῖς κολάζοντες ἢ ὡς ἀνδροφόνους πορφύρᾳ τε ἱερᾷ καὶ ῥάβδοις καὶ πελέκεσι περικοσμοῦντες; ᾧ λόγῳ καὶ Πομπήιον τὸν νέον, οὐδὲν μὲν ἐς ταῦτα συνειργασμένον, ὅτι δὲ μόνον Πομπηίου Μάγνου τοῦ πρώτου περὶ τῆς δημοκρατίας ἀγωνισαμένου παῖς καὶ ὅτι μικρὰ τὴν τυραννίδα ἠνώχλει λανθάνων περὶ Ἰβηρίαν, κατεκάλεσέ τε ἐκ τῆς φυγῆς καὶ τὸ τίμημα αὐτῷ τῶν πατρῴων ἐκ τῶν κοινῶν ἔκριναν ἀποδοῦναι χρημάτων καὶ θαλασσοκράτορα ἀπέφηναν, ἵνα κἀκεῖνος ἀρχήν τινα ἔχοι δημοκρατικὸς ὤν. τί δὴ πλέον ἔργον ἔτι τῆς βουλῆς ἢ σύμβολον ἐπιζητεῖτε τοῦ κατὰ γνώμην αὐτῆς πάντα πεπρᾶχθαι, πλὴν ἢ λόγῳ μόνον ὑμῖν ἔτι ὁμολογῆσαι; ὃ καὶ αὐτὸ πράξουσι καὶ ἐροῦσι καὶ λέγοντες ἅμα ὑμᾶς ἀμείψονται μεγάλαις δωρεαῖς, ὅταν εἰπεῖν καὶ ἀμείψασθαι δύνωνται.", "st": "4.94"}, {"sp": "N", "t": "“νῦν μὲν γὰρ ὡς ἔχουσιν, ἴστε. προγράφονται χωρὶς δίκης, καὶ τὰ ὄντα αὐτοῖς δημεύεται, καὶ κτείνονται χωρὶς καταδίκης ἐν οἰκίαις, ἐν στενωποῖς, ἐν ἱεροῖς, ὑπὸ στρατιωτῶν, ὑπὸ θεραπόντων, ὑπὸ ἐχθρῶν, ἐκ μυχῶν ἀνασπώμενοι καὶ διωκόμενοι πανταχῇ, τῶν νόμων τὸν ἐθέλοντα φεύγειν ἐώντων. ἐς δὲ τὴν ἀγοράν, ἐς ἣν οὐδενὸς πολεμίου κεφαλήν, ἀλλὰ ὅπλα μόνα καὶ ἔμβολα νεῶν ἐφέρομεν, ὑπάτων ἄρτι καὶ στρατηγῶν καὶ δημάρχων καὶ ἀγορανόμων καὶ ἱππέων κεφαλαὶ πρόκεινται· καὶ γέρα τούτων ἐστὶ τῶν κακῶν ὡρισμένα. τοῦτο γὰρ ἐπανάστασίς τίς ἐστι πάντων, ὅσα τέως ἦν ὕπουλα, καὶ ἀνδρολήψια αἰφνίδια καὶ μύση ποικίλα γυναικῶν τε καὶ υἱῶν καὶ ἀπελευθέρων καὶ οἰκετῶν. ἐς τοσοῦτον ἤδη καὶ τοὺς τρόπους ἡ πόλις ἐπιτέτριπται. καὶ τῶνδε τοῖς πονηροῖς ἡγεμόνες εἰσὶν οἱ τρεῖς ἄνδρες, αὐτοὶ πρὸ τῶν ἄλλων ἀδελφοὺς καὶ θείους καὶ ἐπιτρόπους προγράψαντες. λέγεταί ποτε πρὸς τῶν ἀγριωτάτων βαρβάρων ἡ πόλις ἁλῶναι· καὶ οὐδενὸς ἀπέτεμνον οἱ Κελτοὶ κεφαλὰς οὐδὲ ἐνύβριζον ἀνῃρημένοις οὐδὲ πολεμοῦσιν ἔτι λαθεῖν ἢ φυγεῖν ἐφθόνουν. οὐδ’ αὐτοί πω πόλιν οὐδεμίαν ὧν δορὶ ἐλάβομεν, τοιαῦτα διεθήκαμεν οὐδὲ ἑτέρους ἐπυθόμεθα διαθεῖναι, οἷα νῦν οὐκ ἰδιῶτις πόλις, ἀλλ’ ἡγεμονὶς ἀδικεῖται πρὸς τῶν αὐτὴν ἁρμόσαι καὶ διορθῶσαι τὰ κοινὰ κεχειροτονημένων. τί τοιοῦτον εἰργάσατο Ταρκύνιος; ὃν διὰ μιᾶς γυναικὸς ὕβριν, ἐξ ἔρωτος γενομένην, βασιλέα τε ὄντα ἐξέβαλον καὶ βασιλεύεσθαι διὰ ἓν ἔργον οὐκέτι ὑπέστησαν.", "st": "4.95"}, {"sp": "N", "t": "“καὶ τάδε, ὦ πολῖται, πράσσοντες οἱ τρεῖς ἡμᾶς ἐναγεῖς λέγουσι, καί φασι μὲν ἀμύνειν Καίσαρι, προγράφουσι δὲ τοὺς οὐδ’ ἐπιδημοῦντας, ὅτε ἀνῃρεῖτο. ὧν καὶ οἵδε εἰσὶν οἱ πλέονες, οὓς ὁρᾶτε, διὰ πλοῦτον ἢ γένος ἢ γνώμην δημοκρατικῆς διανοίας προγεγραμμένοι. ᾧ λόγῳ καὶ Πομπήιος μεθ’ ἡμῶν προεγράφη, πόρρω μὲν ὢν περὶ Ἰβηρίαν, ὅτε ἡμεῖς ἐδρῶμεν· ὅτι δέ ἐστι δημοκρατικοῦ πατρός, διὰ τὴν αὐτὴν αἰτίαν ὑπὸ μὲν τῆς βουλῆς κατεκλήθη τε καὶ θαλασσοκράτωρ ἐγένετο, ὑπὸ δὲ τῶν τριῶν προεγράφη. τί δὲ γυναῖκες ἐπὶ Καίσαρι συνέγνωσαν αἱ ἐς ἐσφορὰς προγεγραμμέναι; τί δὲ ὁ δῆμος ὁ μέχρι δέκα μυριάδων τιμᾶσθαι τὰ ὄντα κεκελευσμένος ὑπὸ μηνύμασι καὶ ζημίαις, ᾧ τέλη καινὰ καὶ ἐσφορὰς ἐπιγράφουσι; καὶ τάδε πράσσοντες οὐδ’ ὣς ἀνεπλήρωσαν τοῖς στρατευομένοις σφίσι τὰς δωρεάς. ἡμεῖς δέ, οἷς ἀσεβὲς οὐδὲν εἴργασται, καὶ τὰ ἐπηγγελμένα δεδώκαμεν καὶ ἕτερα ἕτοιμα ἔχομεν ἐς ἀμοιβὰς μείζονας. οὕτως ἡμῖν καὶ τὸ δαιμόνιον, ὡς δίκαια πράσσουσι, συνεπιλαμβάνει.", "st": "4.96"}, {"sp": "N", "t": "“ἐπὶ δέ γε τῷ δαιμονίῳ καὶ τὰ πρὸς ἀνθρώπων ὁρᾶν ἔχετε, ἐς τοὺς ὑμῶν πολίτας ἀποβλέποντες, οὓς εἴδετε μὲν στρατηγοῦντας ὑμῶν πολλάκις καὶ ὑπατεύοντας καὶ ἐπαινουμένους, ὁρᾶτε δὲ πρὸς ἡμᾶς ὡς εὐαγεῖς καὶ δημοκρατικοὺς καταπεφευγότας καὶ τὰ ἡμέτερα ᾑρημένους καὶ συνευχομένους ἡμῖν ἐς τὰ λοιπὰ καὶ συναιρομένους. πολὺ γὰρ δικαιότερα ἡμεῖς γέρα τοῖς περισώσασιν αὐτοὺς ἐκηρύξαμεν ὧν ἐκεῖνοι τοῖς ἀναιροῦσιν· οὐδὲ ὁρῶσιν ἡμᾶς Γάιον μέν, ὅτι ἠξίου μόνος ἄρχειν, ἀνῃρηκότας, τοὺς δὲ τὴν ἐκείνου περιποιουμένους ἀρχὴν ὑπερορᾶν μέλλοντας καὶ μὴ ἐς ἑαυτούς, ἀλλ’ ἐς τὸ μέσον τῷ δήμῳ προτιθέντας τὴν πολιτείαν κατὰ τὰ πάτρια. ὡς οὖν οὐκ ἀπὸ τῆς αὐτῆς γνώμης αἱρουμένων πολεμεῖν ἑκατέρων, ἀλλὰ τῶν μὲν ὑπὲρ δυναστείας καὶ τυραννίδος, ἣν ἐν ταῖς προγραφαῖς ἐπέδειξαν ἤδη, ἡμῶν δὲ οὐδέν, ἀλλ’ ἢ μόνον ἵνα τῆς πατρίδος ἐλευθερωθείσης ἰδιωτεύοιμεν ὑπὸ τοῖς νόμοις, εἰκότως οἵδε τε οἱ ἄνδρες καὶ πρὸ τούτων οἱ θεοὶ τὰ ἡμέτερα κρίνουσι. μεγίστη δὲ ἐλπὶς ἐν πολέμοις ἐστὶ τὸ δίκαιον.", "st": "4.97"}, {"sp": "N", "t": "“μηδέ τῳ, εἰ Καίσαρος ἐγένετο στρατιώτης, ἐπὶ νοῦν ἔτι ἴτω· οὐ γὰρ ἐκείνου γε ἦμεν οὐδὲ τότε, ἀλλὰ τῆς πατρίδος, οὐδ’ οἱ διδόμενοι μισθοὶ καὶ δωρεαὶ Καίσαρος ἦσαν, ἀλλὰ τοῦ κοινοῦ, ἐπεὶ οὐδὲ νῦν ἐστε Κασσίου στρατὸς οὐδὲ Βρούτου μᾶλλον ἢ Ῥωμαίων· ἡμεῖς δ’ ἐσμὲν ὑμῖν συστρατιῶται, Ῥωμαίων στρατηγοί. καὶ εἰ τόδε καὶ οἱ πολεμοῦντες ἡμῖν ἐφρόνουν, ἐνῆν ἀκινδύνως ἅπασι τὰ ὅπλα καταθέσθαι καὶ τοὺς στρατοὺς πάντας ἀποδοῦναι τῇ πόλει, κἀκείνην ἑλέσθαι τὰ συνοίσοντα· καὶ εἰ δέχονται ταῦτα, προκαλούμεθα. ἐπεὶ δὲ οὐ δέχονται, οὐδ’ ἂν δέξαιντο ἔτι διὰ τὰς προγραφὰς καὶ ὅσα ἄλλα ἔδρασαν, ἴωμεν, ὦ συστρατιῶται, μετά τε πίστεως ὑγιοῦς καὶ προθυμίας ἀδόλου στρατευσόμενοι Ῥωμαίων τῇ τε βουλῇ καὶ τῷ δήμῳ μόνοις ὑπὲρ ἐλευθερίας.”", "st": "4.98"}, {"sp": "N", "t": "ἀναβοησάντων δὲ πάντων “ἴωμεν” καὶ εὐθὺς ἄγειν ἀξιούντων, ἡσθεὶς ὁ Κάσσιος τῇ προθυμίᾳ κατεκήρυξεν αὖθις σιωπὴν καὶ αὖθις ἔλεγε·", "st": "4.99"}, {"sp": "N", "t": "“θεοὶ μέν, ὅσοι πολέμων δικαίων δεσπόται, τῆς πίστεως ὑμᾶς, ὦ συστρατιῶται, καὶ προθυμίας ἀμείβοιντο· τὰ δ’ ἐς ἀνθρωπίνην στρατηγῶν πρόνοιαν ὅτι καὶ πλέονα καὶ ἀμείνονά ἐστιν ἡμῖν ἢ τοῖς πολεμίοις, μάθετε οὕτως. τέλη μὲν ὁπλιτῶν ἴσα αὐτοῖς ἀντεπάγομεν, πολλὰ καὶ ἐπὶ τῶν χρειῶν ἄλλα πολλαχοῦ καταλιπόντες· ἱππεῦσι δὲ καὶ ναυσὶ πολὺ προύχομεν καὶ συμμάχοις βασιλεῦσί τε καὶ ἔθνεσι τοῖς μέχρι Μήδων καὶ Παρθυαίων. καὶ ἡμῖν μὲν ἐκ μετώπου μόνον εἰσὶ πολέμιοι, ἡμεῖς δ’ αὐτῶν καὶ κατὰ νώτου Πομπήιόν τε ὁμογνώμονα ἡμῖν ἔχομεν ἐν Σικελίᾳ, καὶ Μοῦρκος ἐν τῷ Ἰονίῳ καὶ Ἀηνόβαρβος στόλῳ πολλῷ καὶ ὑπηρεσίᾳ δαψιλεῖ καὶ δύο τέλεσι στρατοῦ καὶ τοξόταις αἰεὶ διαπλέοντες ἐνοχλοῦσι πολλά, καθαρευούσης πολεμίων ἡμῖν τῆς ὄπισθεν γῆς καὶ θαλάσσης. χρήματά γε μήν, ἅ τινες καλοῦσι νεῦρα πολέμου, τοῖς μὲν οὐκ ἔστιν, οὐδ’ ἀπέδωκάν πω τὰ ὑπεσχημένα τῷ στρατῷ, οὐδὲ κατὰ δόξαν ἀπήντησε τὰ τῶν προγραφῶν, οὐδενὸς τῶν ἐπιεικῶν ὠνουμένου χωρία ἐπίφθονα· οὐδ’ ἑτέρωθεν εὐποροῦσι, τετρυμένης στάσεσι καὶ ἐσφοραῖς καὶ προγραφαῖς τῆς Ἰταλίας. ἡμῖν δὲ ἐκ πολλῆς φροντίδος καὶ τὰ παρόντα ἐστὶ δαψιλῆ, ὡς αὐτίκα ὑμῖν ἄλλα χαρίσασθαι, καὶ ἕτερα πολλὰ ἐπὶ τούτοις ἀπὸ τῶν ὄπισθεν ἐθνῶν προσοδεύεται συμφερόμενα.", "st": "4.99"}, {"sp": "N", "t": "“τροφαὶ δέ, ὃ δυσπορώτατόν ἐστι στρατοῖς μεγάλοις, ἐκείνοις μὲν οὐκ εἰσί, πλὴν ἐκ μόνης Μακεδονίας, ἔθνους ὀρείου, καὶ Θεσσαλίας, χώρας βραχείας· καὶ τάδε χρὴ κατὰ γῆν αὐτοῖς φέρεσθαι κακοπαθοῦσιν. εἰ δ’ ἐκ Λιβύης ἐπάγοιντο ἢ Λευκανίας ἢ Ἰαπυγίας, διακλείσουσι πάντα Πομπήιός τε καὶ Μοῦρκος καὶ Δομίτιος. ἡμῖν δὲ καὶ εἰσὶ καὶ φέρονται καθ’ ἑκάστην ἡμέραν ἀπόνως διὰ θαλάττης ἔκ τε νήσων καὶ ἠπείρων ἁπασῶν, ὅσαι ἀπὸ Θρᾴκης ἐπὶ ποταμὸν Εὐφράτην, καὶ τάδε ἀκωλύτως, οὐδενὸς ἡμῖν ὄντος ὄπισθεν ἐχθροῦ· ὥστ’ ἐφ’ ἡμῖν ἔσται καὶ ταχύνειν τὸ ἔργον καὶ ἐπὶ σχολῆς ἐκτρύχειν τοὺς πολεμίους λιμῷ. τοσάδε μὲν ὑμῖν καὶ τοιάδε ἐστίν, ὦ συστρατιῶται, παρ’ ἀνθρωπίνης φροντίδος ἕτοιμα· τὰ δὲ λοιπὰ αὐτοῖς ἀνὰ λόγον ἀπαντήσειε παρά τε ὑμῶν καὶ παρὰ τῶν θεῶν. ἡμεῖς δ’ ὑμῖν ἐπὶ τοῖς προτέροις ἀποδόντες ἅπαντα, ὅσα ὑπεσχήμεθα, καὶ τὴν πίστιν ὑμῶν ἀμειψάμενοι πλήθει δωρεῶν, ἀμειψόμεθα καὶ τὸ μεῖζον ἔργον ἀξίως αὐτοῦ κατὰ γνώμην θεῶν. καὶ νῦν δέ, ὅσον ἐς προθυμίαν, ἰοῦσιν ἐπὶ τὸ ἔργον ἤδη, συνόδου τῆσδε καὶ λόγων τῶνδε ἕνεκα, ἐπιδώσομεν εὐθὺς ἀπὸ τοῦδε τοῦ βήματος στρατιώτῃ μὲν χιλίας καὶ πεντακοσίας δραχμὰς Ἰταλικάς, λοχαγῷ δὲ πενταπλάσιον καὶ χιλιάρχῃ δὲ τὸ ἀνάλογον.”", "st": "4.100"}, {"sp": "N", "t": "ταῦτα εἰπὼν καὶ παρασκευάσας τὸν στρατὸν ἔργῳ καὶ λόγῳ καὶ δωρεαῖς διέλυε τὴν ἐκκλησίαν. οἱ δὲ ἐπιμένοντες ἐπῄνουν ἐπὶ πλεῖστον αὐτόν τε καὶ Βροῦτον καὶ περὶ σφῶν, ὅσα εἰκὸς ἦν, ὑπισχνοῦντο. οἱ δὲ αὐτοῖς τὴν δωρεὰν αὐτίκα διηρίθμουν καὶ ἕτερα ὑπὲρ αὐτὴν κατὰ προφάσεις πολλὰς τοῖς ἀρίστοις. τοὺς δὲ λαμβάνοντας ἀεὶ κατὰ μέρη προαπέλυον, ἐς Δορίσκον, καὶ αὐτοὶ μετ’ ὀλίγον ἐφείποντο. δύο δὲ ἀετοὶ καταπτάντες ἐς τῶν σημείων δύο αἰετοὺς ἀπ’ ἀργύρου πεποιημένους, ἐκόλαπτον αὐτοὺς ἤ, ὡς ἑτέροις δοκεῖ, περιέσκεπον· καὶ παρέμενον δημοσίας τε τροφῆς ὑπὸ τῶν στρατηγῶν ἠξιοῦντο, μέχρι πρὸ μιᾶς τῆς μάχης ἡμέρας ἀπέπτησαν. δύο δ’ ἡμέραις τὸν Μέλανα κόλπον περιοδεύσαντες ἐς Αἶνον ἀφίκοντο καὶ ἐπὶ Αἴνῳ Δορίσκον τε καὶ ὅσα ἄλλα μέχρι Σερρείου ὄρους παράλια.", "st": "4.101"}, {"sp": "N", "t": "τοῦ δὲ Σερρείου προύχοντος ἐς τὸ πέλαγος, αὐτοὶ μὲν ἐς τὰ μεσόγαια ἀνεχώρουν, Τίλλιον δὲ Κίμβρον μετὰ τοῦ ναυτικοῦ καὶ τέλους ὁπλιτῶν ἑνὸς καὶ τοξοτῶν τινων τὴν ἀκτὴν περιπλεῖν ἔπεμπον, ἣ πάλαι μὲν ἦν ἐρημοτάτη, καίπερ εὔγεως οὖσα, τῶν Θρᾳκῶν οὔτε θαλάσσῃ χρωμένων οὔτε ἐς τὰ παράλια κατιόντων ὑπὸ δέους τῶν ἐπιπλεόντων· Ἑλλήνων δ’ αὐτὴν ἑτέρων τε καὶ Χαλκιδέων καταλαβόντων καὶ θαλάσσῃ χρωμένων, ἤνθει ταῖς ἐμπορίαις καὶ γεωργίαις, χαιρόντων σφίσι καὶ τῶν Θρᾳκῶν διὰ τὴν τῶν ὡραίων ἄμειψιν, μέχρι Φίλιππος ὁ Ἀμύντου τούς τε ἄλλους καὶ Χαλκιδέας ἀνέστησεν, ὡς μηδὲν ἔτι πλὴν οἰκόπεδα μόνον ἱερῶν ὁρᾶσθαι. τήνδε οὖν τὴν ἀκτὴν αὖθις ἔρημον οὖσαν ὁ Τίλλιος παραπλέων, ὥς οἱ πρὸς τῶν ἀμφὶ τὸν Βροῦτον εἴρητο, στρατοπέδοις ἐπιτήδεια χωρία ἀνεμέτρει καὶ διέγραφε καὶ ταῖς ναυσὶ κατὰ μέρη πρόσπλουν, ἵν’ οἱ περὶ τὸν Νωρβανόν, ὡς ἀχρεῖον ἔτι τὸ τηρεῖν, τὰ στενὰ ἐκλίποιεν. καὶ ἐγένετο μὲν ὡς προσεδόκησαν· ὑπὸ γὰρ τῆς φαντασίας τῶν νεῶν Νωρβανὸς ἐπὶ τῶν Σαπαίων στενῶν ἐθορυβήθη καὶ ἐκάλει Δεκίδιον ἐκ τῶν Κορπίλων κατὰ σπουδὴν ἐπικουρεῖν οἱ. καὶ ἐπεκούρει, τὰ δὲ τῶν Κορπίλων στενὰ ἐκλειφθέντα οἱ περὶ τὸν Βροῦτον διώδευον.", "st": "4.102"}, {"sp": "N", "t": "ἐκφανείσης δὲ τῆς ἐνέδρας ὁ Νωρβανὸς καὶ ὁ Δεκίδιος τὰ Σαπαίων κατεῖχον ἰσχυρῶς. καὶ πάλιν ἦν ἄπορα τοῖς ἀμφὶ τὸν Βροῦτον, ἀθυμία τε ἐνέπιπτε, μὴ δέοι σφᾶς ἧς ὑπερεωράκεσαν περιόδου νῦν ἄρχεσθαι καὶ ἀνακυκλεύειν τὰ ἠνυσμένα, ὀψὲ καὶ τοῦ χρόνου καὶ τῆς ὥρας γεγονότων. ὧδε δὲ αὐτοῖς ἔχουσιν ὁ Ῥασκούπολις ἐφη περίοδον εἶναι παρ’ αὐτὸ τὸ τῶν Σαπαίων ὄρος ἡμερῶν τριῶν, ἄβατον μὲν ἀνθρώποις ἐς τὸ νῦν ὑπό τε κρημνῶν καὶ ἀνυδρίας καὶ ὕλης πυκνῆς· ἢν δὲ ἐθέλωσιν ὕδωρ τε ἐπάγεσθαι καὶ ὁδοποιεῖν στενὴν καὶ αὐτάρκη δίοδον, οὐ γνωσθήσεσθαι μὲν διὰ τὴν συνηρέφειαν οὐδὲ οἰωνοῖς, τῇ τετάρτῃ δὲ ἐπὶ Ἁρπησσὸν ποταμὸν ἥξειν, ἐκπίπτοντα ἐς τὸν Ἕρμον, ὅθεν ἡμέρας ἔτι μιᾶς ἐν Φιλίπποις ἔσεσθαι, τοὺς πολεμίους περιλαβόντας, ὡς ἀπειλῆφθαι τέλεον αὐτοὺς καὶ οὐδὲ ἀναχώρησιν ἕξειν. τοῖς δὲ ἐδόκει τὰ λεγόμενα τῆς τε ἄλλης ἀπορίας οὕνεκα καὶ ἐλπίδι μάλιστα τοῦ περιλήψεσθαι τοσόνδε στρατὸν πολεμίων.", "st": "4.103"}, {"sp": "N", "t": "προπέμπουσιν οὖν μέρος, Λευκίῳ Βύβλῳ παραδόντες, ὁδοποιεῖν μετὰ τοῦ Ῥασκουπόλιδος. οἱ δ’ ἐπιμόχθως μέν, ὅμως δὲ ἔπραττον αὐτὸ μετὰ ὁρμῆς καὶ προθυμίας, καὶ μᾶλλον, ἐπεί τινες αὐτοῖς προπεμφθέντες ἐπανῆλθον, ἰδεῖν τὸν ποταμὸν ἐξ ἀπόπτου λέγοντες. τῇ δὲ τετάρτῃ κάμνοντες ὑπό τε κόπου καὶ δίψους, ἐπιλιπόντος ἤδη τι καὶ τοῦ ὕδατος, ὃ ἐπήγοντο, ἀνέφερον, ὅτι τριήμερόν σφισι τὸ ἄνυδρον ἐλέγετο εἶναι, καὶ ἐν φόβῳ πανικῷ περὶ ἐνέδρας ἐγίγνοντο, οὐκ ἀπιστοῦντες μὲν τοῖς προπεμφθεῖσι τὸν ποταμὸν ἰδεῖν, ἡγούμενοι δὲ ἑτέραν ἄγεσθαι. καὶ ἀθύμουν καὶ ἐβόων καὶ τὸν Ῥασκούπολιν, ὅτε ἴδοιεν περιθέοντα καὶ παρακαλοῦντα, ἐλοιδόρουν καὶ ἔβαλλον. Βύβλου δὲ αὐτοὺς ἱκετεύοντος ἐκπονῆσαι τὰ λοιπὰ μετ’ εὐφημίας, ὁ ποταμὸς περὶ ἑσπέραν ἑωρᾶτο τοῖς πρώτοις· καὶ βοῆς, ὡς εἰκός, λαμπρᾶς ἐπὶ τῇ χαρᾷ γενομένης, ἡ βοή, μεταλαμβανόντων αὐτὴν τῶν κατόπιν ἑξῆς, ἐπὶ τοὺς ὑστάτους περιῄει. Βροῦτος δὲ καὶ Κάσσιος ἐπεὶ ἔμαθον, ἵεντο αὐτίκα δρόμῳ, διὰ τῆς τετμημένης τὸν ἄλλον στρατὸν ἄγοντες. οὐ μὴν ἔλαθόν γε τοὺς πολεμίους ἐς· τέλος οὐδὲ περιέλαβον αὐτούς· ὁ γάρ τοι Ῥάσκος, ὁ ἀδελφὸς τοῦ Ῥασκουπόλιδος, ἐκ τῆς βοῆς ὑπονοήσας ἐσκέψατο καὶ τὸ γιγνόμενον ἰδὼν ἐθαύμασε μὲν ὁδὸν ἄνυδρον ἐλθόντος στρατοῦ τοσοῦδε, ἣν οὐδὲ θηρίον ᾤετο ὁδεύσειν διὰ τοιᾶσδε ὕλης, καὶ ἀνήγγειλε τοῖς ἀμφὶ τὸν Νωρβανόν· οἱ δὲ νυκτὸς ἔφευγον ἐκ τῶν Σαπαίων ἐπ’ Ἀμφιπόλεως. καὶ οἱ Θρᾷκες ἄμφω διὰ στόματος ἦσαν ἐν τοῖς στρατοῖς, ὁ μὲν ἀγνοουμένην ἀγαγών, ὁ δ’ οὐκ ἀγνοήσας.", "st": "4.104"}, {"sp": "N", "t": "οἱ δ’ ἀμφὶ τὸν Βροῦτον ἐκ παραλόγου τόλμης ἐς Φιλίππους παρῆλθον, ἔνθα αὐτοῖς καὶ ὁ Τίλλιος ἐπικατήχθη καὶ πᾶς ὁ στρατὸς συνεληλύθει. οἱ δὲ Φίλιπποι πόλις ἐστίν, ἣ Δάτος ὠνομάζετο πάλαι καὶ Κρηνίδες ἔτι πρὸ Δάτου· κρῆναι γάρ εἰσι περὶ τῷ λόφῳ ναμάτων πολλαί. Φίλιππος δὲ ὡς εὐφυὲς ἐπὶ Θρᾴκης χωρίον ὠχύρωσέ τε καὶ ἀφ’ ἑαυτοῦ Φιλίππους προσεῖπεν. ἔστι δὲ ἡ πόλις ἐπὶ λόφου περικρήμνου, τοσαύτη τὸ μέγεθος, ὅσον ἐστὶ τοῦ λόφου τὸ εὖρος. ἔχει δὲ πρὸς μὲν ἄρκτῳ δρυμούς, δι’ ὧν ὁ Ῥασκούπολις ἤγαγε τοὺς ἀμφὶ τὸν Βροῦτον· πρὸς δὲ τῇ μεσημβρίᾳ ἕλος ἔστι καὶ θάλασσα μετ’ αὐτό, κατὰ δὲ τὴν ἕω τὰ στενὰ τὰ Σαπαίων τε καὶ Κορπίλων, ἐκ δὲ τὴς δύσεως πεδίον μέχρι Μυρκίνου τε καὶ Δραβήσκου καὶ ποταμοῦ Στρυμόνος, τριακοσίων που καὶ πεντήκοντα σταδίων, εὔφορον πάνυ καὶ καλόν, ἔνθα καὶ τὸ πάθος τῇ Κόρῃ φασὶν ἀνθιζομένῃ γενέσθαι, καὶ ποταμὸς ἔστι Ζυγάκτης, ἐν ᾧ τοῦ θεοῦ περῶντος τὸ ἅρμα τὸν ζυγὸν ἄξαι λέγουσι καὶ τῷ ποταμῷ γενέσθαι τὸ ὄνομα. κατωφερὲς δ’ ἐστὶ τὸ πεδίον, ὡς ἐπιδέξιον μὲν εἶναι τοῖς ἄνωθεν ὁρμῶσιν ἐκ τῶν Φιλίππων, ἄναντες δὲ τοῖς ἐξ Ἀμφιπόλεως βιαζομένοις.", "st": "4.105"}, {"sp": "N", "t": "Φιλίππων μὲν οὖν ἐστιν ἕτερος λόφος οὐ μακράν, ὃν Διονύσου λέγουσιν, ἐν ᾧ καὶ τὰ χρυσεῖα ἔστι τὰ Ἄσυλα καλούμενα. ἀπὸ δὲ τούτου δέκα σταδίους προελθόντι δύο εἰσὶν ἄλλοι λόφοι, Φιλίππων μὲν αὐτῶν ὅσον ὀκτωκαίδεκα σταδίους ἀφεστῶτες, ἀλλήλων δὲ ὅσον ὀκτώ, ἐν οἷς ἐστρατοπέδευσαν, Κάσσιος μὲν ἐπὶ τοῦ πρὸς μεσημβρίαν, Βροῦτος δὲ ἐπὶ τοῦ βορείου. καὶ τῶν ἀμφὶ τὸν Νωρβανὸν ὑποχωρούντων οὐκέτι προῄεσαν· Ἀντώνιόν τε γὰρ ἐπυνθάνοντο πλησιάζειν, Καίσαρος ὑπολελειμμένου διὰ νόσον ἐν Ἐπιδάμνῳ, καὶ τὸ πεδίον ἦν ἐναγωνίσασθαι καλὸν καὶ οἱ κρημνοὶ στρατοπεδεῦσαι. τὰ γὰρ ἑκατέρωθεν αὐτῶν, τῇ μὲν ἦν ἕλη καὶ λίμναι μέχρι τοῦ Στρυμόνος, τῇ δὲ τὰ στενὰ καὶ ἀτριβῆ καὶ ἀνόδευτα· τὸ δὲ μέσον τῶν λόφων, τὰ ὀκτὼ στάδια, δίοδος ἦν ἐς τὴν Ἀσίαν τε καὶ Εὐρώπην καθάπερ πύλαι, καὶ αὐτὰ διετείχισαν ἀπὸ χάρακος ἐς χάρακα καὶ πύλας ἐν μέσῳ κατέλιπον, ὡς ἓν εἶναι τὰ δύο στρατόπεδα. ἦν δὲ καὶ παρ’ αὐτὸ ποταμός, ὃν Γάγγαν τινές, οἳ δὲ Γαγγίτην λέγουσι, καὶ θάλασσα ὄπισθεν, ἐν ᾗ καὶ τὰ ταμιεῖα καὶ ἐνορμίσματα ἔμελλον ἕξειν. Θάσον μὲν δὴ ταμιεῖον, ἀπὸ ἑκατὸν σταδίων οὖσαν, ἐτίθεντο, ἐνόρμισμα δὲ ταῖς τριήρεσι Νέαν πόλιν, ἀπὸ ἑβδομήκοντα σταδίων.", "st": "4.106"}, {"sp": "N", "t": "οἱ μὲν δὴ χαίροντες τῷ χωρίῳ τὰ στρατόπεδα ὠχύρουν, Ἀντώνιος δὲ ὥδευε μὲν σὺν τῷ στρατῷ μετ’ ἐπείξεως, τὴν Ἀμφίπολιν ἐθέλων ἐς τὴν ὑπηρεσίαν τῆς μάχης προλαβεῖν, ὡς δὲ αὐτὴν εὗρεν ὠχυρωμένην οἱ πρὸς τῶν ἀμφὶ τὸν Νωρβανόν, ἥσθη καὶ τὴν παρασκευὴν ἐν αὐτῇ κατέλιπε μεθ’ ἑνὸς τέλους, οὗ Πινάριος ἡγεῖτο, αὐτὸς δὲ μάλα θρασέως πολὺ προελθὼν ἐστρατοπέδευεν ἐν τῷ πεδίῳ, σταδίους ὀκτὼ μόνους ἀποσχὼν ἀπὸ τῶν πολεμίων. καὶ εὐθὺς ἦν κατάδηλος ἡ τῶν στρατοπέδων ἐλάττωσίς τε καὶ πλεονεξία. οἱ μὲν γὰρ ἦσαν ἐπὶ κολωνῷ, οἱ δὲ ἐν πεδίῳ, καὶ οἱ μὲν ἐξυλεύοντο ἀπὸ τῶν ὀρῶν, οἱ δ’ ἀπὸ τοῦ ἕλους· καὶ ὑδρεύοντο οἱ μὲν ἐκ ποταμοῦ, οἱ δὲ ἐκ φρεάτων ὧν αὐτίκα ὠρωρύχεισαν· τήν τε ἀγορὰν οἱ μὲν ἀπ’ ὀλίγων σταδίων ἐπήγοντο ἐκ Θάσου, οἱ δὲ ἀπὸ πεντήκοντα καὶ τριακοσίων ἐξ Ἀμφιπόλεως. ἐδόκει γε μὴν ἐξ ἀνάγκης ὁ Ἀντώνιος ὧδε πρᾶξαι, κολωνοῦ μὲν οὐδενὸς ὄντος ἑτέρου, τὸ δ’ ἄλλο πεδίον οἷα κοιλότερον ἐκλιμνάζοντος ἐνίοτε τοῦ ποταμοῦ· παρ’ ὃ καὶ τὰς πηγὰς τῶν ὀρυσσομένων φρεάτων γλυκείας τε καὶ δαψιλοῦς ὕδατος εὕρισκε. τό γε μὴν τόλμημα, εἰ καὶ ἐξ ἀπορίας ἐγένετο, κατέπλησσε τοὺς πολεμίους, ἐγγὺς οὕτω καὶ εὐθὺς ἐξ ἐφόδου σὺν καταφρονήσει παραστρατοπεδεύσαντος. φρούριά τε ἤγειρε πολλὰ καὶ πάντα κατὰ σπουδὴν ὠχύρου τάφροις καὶ τείχεσι καὶ χαρακώμασιν. ὠχύρουν δὲ καὶ οἱ πολέμιοι, ὅσα αὐτοῖς ἐνέλειπεν. ὁ δὲ Κάσσιος τὴν ὁρμὴν τοῦ Ἀντωνίου μανιώδη οὖσαν ὁρῶν διετείχιζεν, ὃ ἔτι μόνον αὐτοῖς ἔλειπεν ἐς τὸ ἕλος ἀπὸ τοῦ στρατόπέδου, διὰ στενότητα ὑπεροφθέν, ὡς μηδὲν ἔτι ἀτείχιστον εἶναι πλὴν κατὰ πλευρὰς Βρούτῳ μὲν τὰ ἀπόκρημνα, Κασσίῳ δὲ τὸ ἕλος καὶ τὴν θάλασσαν ἐπὶ τῷ ἕλει· τὰ δὲ ἐν μέσῳ πάντα διείληπτο τάφρῳ καὶ χάρακι καὶ τείχει καὶ πύλαις.", "st": "4.107"}, {"sp": "N", "t": "οὕτω μὲν ὠχυροῦντο αὐτῶν ἑκάτεροι καὶ ἐν τοσούτῳ μόνοις ἱππεῦσι καὶ ἀκροβολισμοῖς ἐπειρῶντο ἀλλήλων. ὡς δὲ ἐξείργαστο πάντα, ὅσα ἐπενόουν, καὶ ὁ Καῖσαρ ἀφῖκτο, οὔπω μὲν ἐρρωμένος ἐς μάχην, φορείῳ δὲ ἐπὶ τὰς συντάξεις τοῦ στρατοῦ κομιζόμενος, οἱ μὲν ἀμφὶ τὸν Καίσαρα εὐθὺς ἐξέτασσον ἐς μάχην, οἱ δ’ ἀμφὶ τὸν Βροῦτον ἀντεξέτασσον μὲν ἐπὶ τῶν ὑψηλοτέρων, οὐ κατῄεσαν δέ· οὐ γὰρ ἐγνώκεσαν ἐς τὴν μάχην ἐπείγεσθαι, ταῖς ἀγοραῖς ἐλπίζοντες ἐκτρύσειν τοὺς πολεμίους. ἦν δὲ τὰ μὲν πεζὰ ἑκατέροις ἐννεακαίδεκα ὁπλιτῶν τέλη, τοῖς μὲν ἀμφὶ τὸν Βροῦτον ἐνδέοντα τοῖς ἀριθμοῖς, τοῖς δ’ ἀμφὶ τὸν Καίσαρα καὶ ἐπλεόναζον ἑκατέρωθεν· ἱππέες δὲ ἅμα τοῖς ἑκατέρων Θρᾳκίοις ἦσαν Καίσαρι μὲν καὶ Ἀντωνίῳ μύριοι καὶ τρισχίλιοι, Βρούτῳ δὲ καὶ Κασσίῳ δισμύριοι. ὥστε πλήθει μὲν ἀνδρῶν καὶ θράσει καὶ ἀρετῇ στρατηγῶν καὶ ὅπλοις καὶ παρασκευῇ λαμπροτάτην ἑκατέρων παράταξιν ὀφθῆναι, ἄπρακτον δὲ ἐς πολλὰς ἡμέρας, οὐκ ἐθελόντων συμπλέκεσθαι τῶν ἀμφὶ τὸν Βροῦτον, ἀλλὰ ταῖς ἀγοραῖς προεκτρύχειν τοὺς πολεμίους, αὐτοὶ μὲν ἔχοντες Ἀσίαν χορηγὸν καὶ ἐξ ἐγγίονος πάντα διὰ θαλάσσης ποριζόμενοι, τοῖς δὲ πολεμίοις οὐδὲν ὂν δαψιλὲς οὐδὲ οἰκεῖον· οὔτε γάρ τι δι’ ἐμπόρων ἀπ’ Αἰγύπτου λαβεῖν εἶχον, ὑπὸ λιμοῦ τῆς χώρας δεδαπανημένης, οὔτε ἐξ Ἰβηρίας ἢ Λιβύης διὰ Πομπήιον οὔτε ἐκ τῆς Ἰταλίας διὰ Μοῦρκον καὶ Δομίτιον. οὐκ ἐς πολὺ δ’ αὐτοῖς ἔμελλον ἀρκέσειν Μακεδονία τε καὶ Θεσσαλία, μόναι σφίσιν ἐν τῷ τότε χορηγοῦσαι.", "st": "4.108"}, {"sp": "N", "t": "ὧν οἱ μὲν ἀμφὶ τὸν Βροῦτον ἐνθυμούμενοι μάλιστα διέτριβον· ὁ δὲ Ἀντώνιος αὐτὰ δεδιὼς ἔγνω βιάσασθαι τοὺς ἄνδρας ἐς μάχην καὶ ἐπενόησεν, εἰ δύναιτο βάσιμον τὸ ἕλος ἐργάσασθαι λαθών, ἵνα κατόπιν τῶν ἐχθρῶν ἔτι ἀγνοούντων γενόμενος τὴν ἀγορὰν σφᾶς ἀφέλοιτο τὴν ἀπὸ τῆς Θάσου κομιζομένην. ἐκτάσσων οὖν αὖθις ἑκάστοτε ἐς μάχην τὰ σημεῖα τοῦ στρατοῦ πάντα, ἵνα ὅλος ἐκτετάχθαι νομίζοιτο, μέρει τινὶ νυκτός τε καὶ ἡμέρας ἔκοπτεν ἐν τῷ ἕλει δίοδον στενήν, κείρων τε τὸν δόνακα καὶ χῶμα ἐπιβάλλων καὶ λίθους ἑκατέρωθεν, ἵνα μὴ τὸ χῶμα διαπίπτοι, τὰ δὲ βαθέα διεσταύρου καὶ ἐγεφύρου μετὰ σιωπῆς βαθυτάτης. ἀφῄρητο δὲ τὴν ὄψιν τοῦ ἔργου τοὺς πολεμίους ὁ πεφυκὼς ἔτι δόναξ ἀμφὶ τῇ διόδῳ. δέκα δ’ ἡμέρας ἐργασάμενος ὧδε ἐσέπεμψε λόχους ὀρθίους νυκτὸς ἄφνω καὶ τὰ ἐρυμνὰ τῶν ἐντὸς κατέλαβε καὶ ἐχαράκωσε φρούρια ὁμοῦ πολλά. ὁ δὲ Κάσσιος κατεπλάγη μὲν τοῦ ἔργου τὴν ἐπίνοιάν τε καὶ κλοπήν, ἀντεπινοῶν δὲ ἀποτεμέσθαι τὰ φρούρια τὸν Ἀντώνιον, διετείχιζε καὶ αὐτὸς ἐπικάρσιον τὸ ἕλος ἅπαν, ἀρχόμενον ἀπὸ τοῦ στρατοπέδου μέχρι τῆς θαλάσσης, κόπτων ὁμοίως καὶ γεφυρῶν καὶ τὸν χάρακα τοῖς στεριφώμασιν ἐπιτιθεὶς καὶ τὴν ὑπὸ Ἀντωνίου γεγενημένην δίοδον ἀπολαμβάνων, ἵνα μήτε ἐκδραμεῖν ἐς αὐτὸν οἱ ἔνδον ἔτι δυνηθεῖεν μήτε ἐκεῖνος αὐτοῖς ἐπιβοηθεῖν.", "st": "4.109"}, {"sp": "N", "t": "ταῦτα δὲ ὁ Ἀντώνιος ἰδὼν περὶ μεσημβρίαν, ὡς εἶχεν, αὐτίκα σὺν ὁρμῇ τε καὶ ὀργῇ τὸν στρατὸν τὸν ἴδιον, ἐπὶ θάτερα τεταγμένον, ἦγεν ἐπιστρέφων εἰς τὸ διατείχισμα τοῦ Κασσίου, μεταξὺ τοῦ ἕλους καὶ τοῦ στρατοπέδου, σιδήρια φέρων καὶ κλίμακας, ὡς ἐξελῶν αὐτὸ καὶ παροδεύσων ἐς τὸ τοῦ Κασσίου στρατόπεδον. γιγνομένου δὲ αὐτῷ τοῦ δρόμου σὺν τόλμῃ πλαγίου τε καὶ πρὸς ἄναντες, κατ’ αὐτὸ δὴ τὸ μεταίχμιον τῶν στρατιῶν ἑκατέρων, περιήλγησαν οἱ τοῦ Βρούτου στρατιῶται ἐπὶ τῇ ὕβρει, ὧδε μάλα θρασέως αὐτοὺς ὄντας ἐνόπλους ἐχθρῶν διαθεόντων, καὶ ἐπέδραμον αὐτοῖς αὐτοκέλευστοι πρό τινος ἐκ τῶν ἡγεμόνων ἐπιτάγματος καὶ ἔκτεινον οἷα πλαγίους ἀθρόως, οὓς καταλάβοιεν. ἀρξάμενοι δ’ ἅπαξ ἔργου καὶ τῷ Καίσαρος στρατῷ τεταγμένῳ μάλιστα κατὰ σφᾶς ἐπέδραμον καὶ τρέψαντες ἐδίωκον, μέχρι καὶ τὸ στρατόπεδον ἐξεῖλον, ὃ κοινὸν ἦν Ἀντωνίῳ τε καὶ Καίσαρι, Καίσαρος αὐτοῦ δι’ ἐνύπνιον ἔνδον οὐκ ὄντος, ἀλλὰ φυλαξαμένου τὴν ἡμέραν, ὡς αὐτὸς ἐν τοῖς ὑπομνήμασιν ἔγραψεν.", "st": "4.110"}, {"sp": "N", "t": "ὁ δὲ Ἀντώνιος ὁρῶν τὴν μάχην συνερρωγυῖαν ἥσθη μὲν ὡς ἀναγκάσας (πάνυ γὰρ ἐπὶ ταῖς ἀγοραῖς ἐδεδίει), ἀναστρέφειν δὲ εἰς τὸ πεδίον οὐκ ἔκρινεν, μὴ τὴν φάλαγγα ἀνελίσσων ταράξειεν, ὡς ἀρξάμενος δ’ εἶχεν ὁρμῆς, ἐχεῖτο δρόμῳ καὶ ἀνέβαινε, βαλλόμενός τε καὶ χαλεπῶς, μέχρι βιαζόμενος ἐνέκυρσε τῇ φάλαγγι τῇ Κασσίου, τὴν τάξιν τὴν δεδομένην φυλασσούσῃ καὶ τὸ γιγνόμενον ὡς ἄλογον καταπεπληγμένῃ. ῥήξας δ’ αὐτὴν ὑπὸ τόλμης ἐπὶ τὸ διατείχισμα ὥρμα, τὸ μεταξὺ τοῦ τε ἕλους καὶ τοῦ στρατοπέδου, τόν τε χάρακα ἀνασπῶν καὶ τὴν τάφρον ἐγχωννὺς καὶ τὸ οἰκοδόμημα ὑπορύσσων καὶ τοὺς ἐν ταῖς πύλαις καταφονεύων καὶ τὰ ἐπιπίπτοντα ἐκ τοῦ τείχους ὑπομένων, ἕως αὐτὸς μὲν ἐσήλατο διὰ τῶν πυλῶν ἔνδον, ἕτεροι δὲ ταῖς ὑπωρυχίαις ἐσῆλθον, οἱ δὲ καὶ τοῖς πεπτωκόσιν ἐπανέβαινον. καὶ πάντα οὕτως ἐγίγνετο ὀξέως, ὥστε τοῖς τὸ ἕλος ἐργαζομένοις ἐπιβοηθοῦσιν ὑπήντων ἑλόντες ἤδη τὸ διατείχισμα. τρεψάμενοι δὲ καὶ τούσδε σὺν ὁρμῇ βιαίῳ καὶ ἐς τὸ ἕλος κατώσαντες ἐπανῄεσαν ἐς αὐτὸ ἤδη τὸ στρατόπεδον τοῦ Κασσίου, μόνοι σὺν τῷ Ἀντωνίῳ, ὅσοι τὸ διατείχισμα ὑπερῆλθον, τοῦ ἄλλου πλήθους, ἑκατέρων ἐκτὸς ἀλλήλοις μαχομένου.", "st": "4.111"}, {"sp": "N", "t": "τὸ δὲ στρατόπεδον ὡς ἐρυμνὸν ὀλίγοι πάμπαν ἐφύλασσον· ὅθεν αὐτῶν εὐμαρῶς ἐκράτησεν ὁ Ἀντώνιος. ἤδη δὲ καὶ ἔξω τοῦ Κασσίου στρατὸς ἡσσᾶτο καὶ τὴν κατάληψιν ἰδὼν τοῦ στρατοπέδου διεσκίδνατο ἀκόσμως. καὶ τὸ ἔργον ἦν ἐντελὲς ἑκατέροις καὶ ὅμοιον· Βροῦτός τε γὰρ τὸ λαιὸν τῶν πολεμίων ἐτέτραπτο καὶ τὸ στρατοπεδον ᾑρήκει, Ἀντώνιός τε Κασσίου κρατῶν σὺν ἀμηχάνῳ τόλμῃ τὸ στρατόπεδον ἐπόρθει. φόνος τε ἦν ἑκατέρων ποικίλος· ὑπὸ δὲ μεγέθους πεδίου τε καὶ κονιορτοῦ τὰ ἀλλήλων ἠγνόουν, μέχρι ποτὲ ἐπύθοντο καὶ τοὺς λοιποὺς ἀνεκάλουν. οἱ δὲ ἐπανῄεσαν, ἀχθοφόροις ἐοικότες μᾶλλον ἢ στρατιώταις· καὶ οὐδὲ τότε ἀλλήλων ᾐσθάνοντο οὐδὲ καθεώρων, ἐπεὶ ῥίψαντές γε, ὅσα ἔφερον, οἱ ἕτεροι μέγα ἂν εἰργάσαντο κατὰ τῶν ἑτέρων, ἀσυντάκτως ὧδε ἀχθοφορούντων. τὸν δ’ ἀριθμὸν τῶν ἀποθανόντων εἰκάζουσι τῶν μὲν ἀμφὶ τὸν Κάσσιον ἐς ὀκτακισχιλίους σὺν τοῖς παρασπίζουσι θεράπουσι γενέσθαι, τῶν δ’ ἀμφὶ τὸν Καίσαρα διπλασίονα.", "st": "4.112"}, {"sp": "N", "t": "Κάσσιος δὲ ἐξ οὗ τῶν διατειχισμάτων ἐξέωστο καὶ οὐδὲ ἐσελθεῖν ἔτι εἶχεν ἐς τὸ στρατόπεδον, ἀνέδραμεν ἐς τὸν Φιλίππων λόφον καὶ τὰ γιγνόμενα ἐφεώρα. οὐκ ἀκριβῶς δὲ αὐτὰ διὰ τὸν κονιορτὸν οὐδὲ πάντα ὁρῶν, ἀλλ’ ἢ τὸ στρατόπεδον ἑαυτοῦ μόνον εἰλημμένον, ἐκέλευσε Πινδάρῳ τῷ ὑπασπιστῇ προσπεσεῖν οἱ καὶ διαφθεῖραι. διαμέλλοντος δ’ ἔτι τοῦ Πινδάρου προσέθει τις ἀγγέλλων Βροῦτον ἐπὶ θάτερα νικᾶν καὶ τὸ στρατόπεδον τῶν πολεμίων πορθεῖν. ὁ δὲ τούτῳ μὲν τοσόνδε ἀπεκρίνατο· “νικῴης, λέγε αὐτῷ, παντελῆ νίκην,” ἐς δὲ τὸν Πίνδαρον ἐπιστραφείς, “τί βραδύνεις;” ἔφη, “τί τῆς ἐμῆς αἰσχύνης με οὐκ ἀπαλλάσσεις;” Πίνδαρος μὲν δὴ δεσπότην, ὑπέχοντα τὴν σφαγήν, διεχρήσατο. καί τισιν οὕτως ἀποθανεῖν δοκεῖ Κάσσιον. ἕτεροι δὲ αὐτὸν οἴονται, προσιόντων ἐς εὐαγγέλιον ἱππέων Βρούτου, νομίσαντα εἶναι πολεμίους, πέμψαι τὸ ἀκριβὲς εἰσόμενον Τιτίνιον· τὸν δὲ τῶν ἱππέων ὡς Κασσίου φίλον περισχόντων τε σὺν ἡδονῇ καὶ ἐπὶ τῷδε καὶ ἀλαλαξάντων μέγα, τὸν Κάσσιον ἡγούμενον ἐς ἐχθροὺς ἐμπεσεῖν Τιτίνιον τοῦτο φάναι· “περιεμένομεν φίλον ἁρπαζόμενον ἰδεῖν,” καὶ ἔς τινα σκηνὴν ὑποχωρῆσαι μετὰ τοῦ Πινδάρου καὶ τὸν Πίνδαρον οὐκέτι φανῆναι. διὸ καὶ νομίζουσί τινες οὔπω κεκελευσμένον ἐργάσασθαι.", "st": "4.113"}, {"sp": "N", "t": "Κασσίῳ μὲν δὴ τέλος ἦν τοῦ βίου κατὰ τὴν αὐτοῦ Κασσίου γενέθλιον ἡμέραν, ὧδε τῆς μάχης γενέσθαι συμπεσούσης, καὶ Τιτίνιος ὡς βραδύνας ἑαυτὸν ἔκτεινε· Βροῦτος δὲ Κασσίου τὸν νέκυν περικλαίων, ἀνεκάλει τελευταῖον ἄνδρα Ῥωμαίων, ὡς οὔ τινος ἔτι τοιοῦδε ἐς ἀρετὴν ἐσομένου, ταχυεργίας τε αὐτῷ καὶ προπετείας ἐνεκάλει καὶ ἐμακάριζεν ὁμοῦ φροντίδων καὶ ἀνίας ἀπηλλαγμένον, αἳ Βροῦτον ἐς ποῖον ἄρα τέλος ὁδηγοῦσι; παραδοὺς δὲ τὸ σῶμα τοῖς φίλοις, ἔνθα λαθραίως θάψειαν, ἵνα μὴ καταδακρύσειε τὸν στρατὸν ὁρῶντα, αὐτὸς ἄσιτός τε καὶ ἀτημέλητος ἀνὰ τὴν νύκτα πᾶσαν τὸ Κασσίου στρατόπεδον καθίστατο. ἅμα δ’ ἡμέρᾳ τῶν πολεμίων τὸν στρατὸν παρατασσόντων ἐς μάχην, ἵνα μὴ δοκοῖεν ἠλασσῶσθαι, συνεὶς τοῦ ἐνθυμήματος, “ὁπλισώμεθα,” ἔφη, “καὶ ἡμεῖς καὶ ἀνθυποκριθῶμεν ἐλάσσονα παθεῖν.” ὡς δὲ παρέταξεν, οἱ μὲν ἀνεχώρουν, ὁ δὲ Βροῦτος ἐπιτωθάσας ἔφη τοῖς φίλοις· “οἱ μὲν δὴ προκαλούμενοι ἡμᾶς ὡς κεκμηκότας οὐδὲ ἀπεπείρασαν.”", "st": "4.114"}, {"sp": "N", "t": "ἧι δὲ ἡμέρᾳ τὴν μάχην ἐν Φιλίπποις συνέβαινεν εἶναι, καὶ ἐν τῷ Ἰονίῳ τοιόνδε πάθος ἄλλο ἐγίγνετο μέγα. Δομίτιος Καλουῖνος ἐπὶ ὁλκάδων ἦγεν ὁπλιτῶν δύο τέλη Καίσαρι, καὶ τὸ διώνυμον ἦν αὐτῶν, τὸ Ἄρειον, ὃ ἐπὶ τιμῇ τῆς ἀλκῆς ὠνόμαζον. ἦγε δὲ καὶ στρατηγίδα σπεῖραν, ἐς δισχιλίους ἄνδρας, ἱππέων τε ἴλας τέσσαρας καὶ ἕτερον πλῆθος ἐπειλεγμένον· καὶ τριήρεις αὐτοὺς παρέπεμπον ὀλίγαι. Μοῦρκος δ’ αὐτοῖς καὶ Ἀηνόβαρβος ἑκατὸν καὶ τριάκοντα μακραῖς ὑπήντων. καὶ αὐτοὺς αἱ ὁλκάδες ἱστίῳ μὲν αἱ πρῶται διέφυγον ὀλίγαι, αἱ λοιπαὶ δέ, χαλάσαντος ἄφνω τοῦ πνεύματος, ἐν γαλήνῃ σταθερᾷ κατὰ τὸ πέλαγος ἠλῶντο, ὑπό του θεῶν ἐκδεδομέναι τοῖς πολεμίοις. ἐνέβαλλον γὰρ ἀδεῶς ἑκάστῃ καὶ ἀνερρήγνυον· οὐδὲ αἱ παραπέμπουσαί σφας τριήρεις ἐπικουρεῖν ἐδύναντο, διὰ τὴν ὀλιγότητα κυκλούμεναι. ἔργα δ’ ἦν τῶν κινδυνευοντων πολλὰ καὶ ποικίλα, ὁτὲ μὲν τὰ πλοῖα συναγόντων ἀπὸ κάλω σπουδῇ καὶ κοντοῖς ἁρμοζόντων ἐς ἄλληλα, ἵνα μὴ διεκπλεῖν αὐτὰ ἔχοιεν οἱ πολέμιοι. ὅτε δὲ τούτου κρατήσειαν, ὁ μὲν Μοῦρκος αὐτοῖς ἐπέβαλλε τοξεύματα πυρός, οἱ δὲ τοὺς συνδέσμους ἀνέλυον ὀξέως καὶ ἀπέφευγον ἀλλήλων διὰ τὸ πῦρ αὖθίς τε ἐγίγνοντο ταῖς τριήρεσιν ἐς περίπλουν καὶ ἐμβολὴν ἕτοιμοι.", "st": "4.115"}, {"sp": "N", "t": "ἀγανακτοῦντες δὲ οἱ ἄνδρες, καὶ μάλιστα αὐτῶν οἱ Ἄρειοι, ὅτι κρείττους ὄντες ἀλκὴν δι’ ἀπραξίας ἀπώλλυντο, οἱ μὲν πρὸ τοῦ πυρὸς ἑαυτοὺς ἀνῄρουν, οἱ δὲ ἐς τὰς τριήρεις τῶν πολεμίων ἐναλλομενοι τὰ μὲν ἔδρων, τὰ δὲ ἔπασχον. νῆές τε ἡμίφλεκτοι μέχρι πολλοῦ περιέπλεον, ἄνδρας ἔχουσαι τοὺς μὲν ὑπὸ τοῦ πυρός, τοὺς δ’ ὑπὸ λιμοῦ καὶ δίψης δαπανωμένους· οἱ δὲ καὶ ἱστῶν ἢ σανίδων ἐχόμενοι ἐς πέτρας ἢ ἀκτὰς ἐξεφέροντο ἐρήμους. καὶ εἰσὶν αὐτῶν, οἳ καὶ περιεσώθησαν ἐκ παραλόγου· τινὲς δὲ καὶ ἐς πέντε διήρκεσαν ἡμέρας, λιχμώμενοι τὴν πίσσαν ἢ ἱστίων ἢ κάλων διαμασώμενοι, μέχρι σφᾶς ὁ κλύδων ἐξήνεγκεν ἐπὶ τὴν γῆν. πολὺ δ’ ἦν, ὃ καὶ τοῖς πολεμίοις ἑαυτὸ ἐπέτρεπεν, ὑπὸ τῶν συμφορῶν ἡσσώμενον. ἐπέτρεψαν δὲ καὶ τῶν τριήρων ἑπτακαίδεκα. καὶ τοὺς μὲν ἄνδρας οἱ περὶ Μοῦρκον ἐς ἑαυτοὺς μεθώρκουν, ὁ δὲ στρατηγὸς αὐτῶν Καλουῖνος ἐπὶ τῆς ἑαυτοῦ νεὼς ἐπανῆλθεν ἐς τὸ Βρεντέσιον ἡμέρᾳ πέμπτῃ, δόξας ἀπολωλέναι.", "st": "4.116"}, {"sp": "N", "t": "τοιοῦτο μὲν δὴ πάθος τῆς αὐτῆς ἡμέρας τῇ περὶ Φιλίππους μάχῃ κατὰ τὸν Ἰόνιον ἐπεγίγνετο, εἴτε ναυάγιον εἴτε ναυμαχίαν ὀνομάσαι χρή· καὶ ἐξέπλησσε τὸ συγκύρημα τῶν ἔργων ὕστερον ἐπιγνωσθέν.", "st": "4.116"}, {"sp": "N", "t": "ὁ δὲ Βροῦτος τὸν στρατὸν ἐς ἐκκλησίαν συναγαγὼν ἔλεξεν ὧδε·", "st": "4.117"}, {"sp": "N", "t": "“οὐδὲν ἔστιν, ὦ συστρατιῶται, παρὰ τὸν χθὲς ἀγῶνα, ἐν ᾧ μὴ κρείσσους ἐγένεσθε τῶν πολεμίων. τῆς τε γὰρ μάχης ἤρξατε προθύμως, εἰ καὶ χωρὶς παραγγέλματος· καὶ τὸ τέταρτον τέλος, ὃ περιώνυμον αὐτοῖς ὂν ἐπεπίστευτο τὸ κέρας, διεφθείρατε ἅπαν καὶ τοὺς ἐπιτεταγμένους αὐτῷ μέχρι τοῦ στρατοπέδου· καὶ τὸ στρατόπεδον αὐτὸ εἵλετε πρότερον καὶ διηρπάσατε· ὡς προύχειν τάδε παρὰ πολὺ τῆς ἐπὶ τοῦ λαιοῦ βλάβης ἡμῶν. δυνηθέντες δ’ ἂν ὅλον ἐργάσασθαι τὸ ἔργον, ἁρπάσαι μᾶλλον εἵλεσθε ἢ κτείνειν τοὺς ἡσσωμένους· οἱ γὰρ πλέονες ὑμῶν τοὺς πολεμίους παροδεύοντες ἐπὶ τὰ τῶν πολεμίων ὥρμων. καὶ ἐν τῷδε αὖ πάλιν οἱ μὲν διήρπασαν δύο τῶν ἡμετέρων στρατοπέδων ὄντων τὸ ἕτερον, ἡμεῖς δὲ ἐκείνων ἅπαντα ἔχομεν, ὡς καὶ τῷδε τὴν ἐπίκτησιν τῆς βλάβης διπλασίονα εἶναι. καὶ τὰ μὲν ἐν τῇ μάχῃ πλεονεκτήματα τοσαῦτα· ὅσα δὲ ἕτερα προύχομεν αὐτῶν, ἔχετε καὶ παρὰ τῶν αἰχμαλώτων μανθάνειν, περί τε ἀπορίας σίτου καὶ ἐπιτιμήσεως αὐτοῦ καὶ κομιδῆς κακοπαθοῦς καὶ παρ’ ὀλίγον ἤδη σαφοῦς ἐπιλείψεως. οὔτε γὰρ ἐκ Σικελίας ἢ Σαρδόνος ἢ Λιβύης ἢ Ἰβηρίας ἔστιν αὐτοῖς λαβεῖν διὰ Πομπήιον καὶ Μοῦρκον καὶ Ἀηνόβαρβον, ναυσὶν ἑξήκοντα καὶ διακοσίαις ἀποκλείοντας αὐτοῖς τὸ πέλαγος· Μακεδονίαν τε ἐξαναλώκασιν ἤδη καὶ ἐκ μόνης ἄρτι Θεσσαλίας ἔχουσιν, ἣ ἐς πόσον αὐτοῖς ἔτι ἀρκέσει;", "st": "4.117"}, {"sp": "N", "t": "“ὅταν οὖν αὐτοὺς ἐπειγομένους εἰς μάχην μάλιστα ἴδητε, τότε ἡγεῖσθε διωκομένους ὑπὸ λιμοῦ τὸν ἐν χερσὶ θάνατον αἱρεῖσθαι. ἡμεῖς δ’ ἀντιμηχανησώμεθα αὐτοῖς τὸν λιμὸν ἡμῶν προπολεμεῖν, ἵν’ ἀσθενεστέροις καὶ τετρυμένοις ἐντύχοιμεν, ὅτε χρή. μηδ’ ἐκφερώμεθα ταῖς προθυμίαις παρὰ καιρόν, μηδὲ βραδυτῆτά τις ἡγείσθω τὴν ἐμπειρίαν ἢ ταχυτῆτα, ἐς τὴν ὀπίσω θάλασσαν ἀφορῶν, ἣ τοσαύτας ἡμῖν ὑπηρεσίας καὶ τροφὰς ἐπιπέμπουσα δίδωσιν ἀκινδύνου νίκης ἐπιτυχεῖν, ἢν ὑπομένητε καὶ μὴ ἀδοξῆτε, εἰ προσπαίξονταί τε ἡμῖν καὶ προκαλοῦνται, οὐκ ἀμείνονες ὄντες, ὡς διέδειξε τὸ ἐχθὲς ἔργον, ἀλλὰ ἕτερον δέος ἰώμενοι. τὴν δὲ προθυμίαν, ἧς νῦν ὑμᾶς ἀξιῶ κρατεῖν, ἀθρόαν ἀπόδοτε, ὅταν αἰτῶμεν. ἐγὼ δ’ ὑμῖν τὰ νικητήρια ἐντελῆ μέν, ὅταν οἱ θεοὶ κρίνωσιν, ἐπὶ ἐντελέσι τοῖς ἔργοις διαλύσομαι· νῦν δὲ τῆς ἐχθὲς ἀρετῆς ἀνὰ χιλίας ἑκάστῳ στρατιώτῃ δραχμὰς ἐπιδίδωμι καὶ τοῖς ἡγεμόσιν ὑμῶν ἀνὰ λόγον.”", "st": "4.118"}, {"sp": "N", "t": "ὁ μὲν οὕτως εἶπεν καὶ αὐτίκα διεμέτρει τὴν δωρεὰν κατὰ τέλη· δοκεῖ δέ τισι καὶ Λακεδαίμονα καὶ Θεσσαλονίκην ἐς διαρπαγὴν αὐτοῖς δώσειν ὑποσχέσθαι.", "st": "4.118"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ καὶ ὁ Ἀντώνιος, εἰδότες οὐ μαχούμενον ἑκόντα τὸν Βροῦτον, τοὺς ἰδίους συνῆγον, καὶ ὁ Ἀντώνιος ἔλεξε·", "st": "4.119"}, {"sp": "N", "t": "“τὸ ἐχθὲς ἔργον, ὦ ἄνδρες, τοῖς μὲν λόγοις οἶδα ὅτι καὶ οἱ πολέμιοι μερίζονται, ὡς διώξαντές τινας ἡμῶν καὶ τὸ στρατόπεδον διαρπάσαντες, ἔργῳ δὲ ἐπιδείξουσιν ἅπαν ὑμέτερον· ὑπισχνοῦμαι γὰρ ὑμῖν οὔτε αὔριον οὔτε ταῖς ἐπιούσαις ἑκόντας αὐτοὺς ἐς μάχην ἥξειν. ὃ σαφεστάτη πίστις ἐστὶ τῆς ἐχθὲς ἥσσης καὶ φόβου, ὅταν ὥσπερ ἐν τοῖς γυμνικοῖς ἀφιστῶνται τοῦ ἀγῶνος οἱ ἐλάττονες· οὐ γὰρ ἐς τοῦτό ’γε στρατὸν ἤγειρον τοσόνδε, ἵνα τῶν Θρᾳκῶν ἐρημίαν οἰκῶσι διατειχίσαντες. ἀλλὰ αὐτὴν διετείχισαν μὲν ἔτι προσιόντων ὑμῶν διὰ δέος, ἐλθόντων δὲ ἐνοικοῦσι διὰ τὴν ἐχθὲς ἧσσαν· ἐφ’ ᾗ καὶ τῶν στρατηγῶν ὁ πρεσβύτερός τε καὶ ἐμπειρότερος πάντα ἀπογνοὺς ἑαυτὸν διεχρήσατο, ὃ καὶ αὐτὸ μεγίστη συμφορῶν ἐστιν ἀπόδειξις. ὅταν οὖν ἡμῶν αὐτοὺς προκαλουμένων μὴ δέχωνται μηδὲ καταβαίνωσιν ἀπὸ τῶν ὀρῶν, ἀλλὰ ἀντὶ τῶν χειρῶν πιστεύωσι τοῖς κρημνοῖς, τότε μοι θαρροῦντες ὑμεῖς, ὦ ἄνδρες Ῥωμαῖοι, συναναγκάσατε αὐτοὺς αὖθις, ὥσπερ ἐχθὲς ἠναγκάσατε, αἰσχρὸν ἡγούμενοι δεδιότων ἐλασσοῦσθαι καὶ ὀκνούντων ἀπέχεσθαι καὶ τειχῶν ἄνδρες ὄντες ἀσθενέστεροι γενέσθαι. οὐ γὰρ ἤλθομέν γε καὶ ἡμεῖς ἐν πεδίῳ βιώσοντες, οὐδ’ ἔστι βραδύνουσιν οὐδὲν αὔταρκες. ἀλλὰ δεῖ τοῖς εὖ φρονοῦσι τοὺς μὲν πολέμους ὀξεῖς, τὴν δὲ εἰρήνην ἐπὶ μήκιστον εἶναι.", "st": "4.119"}, {"sp": "N", "t": "“τοὺς μὲν οὖν καιροὺς καὶ τὰ ἐς τοῦτον ἔργα ἐπιμηχανησόμεθα ἡμεῖς, οὐ μεμπτοὶ καὶ τῆς ἐχθὲς ὁρμῆς τε καὶ μηχανῆς ὑμῖν γενόμενοι· τὴν δ’ ἀρετὴν ὑμεῖς, ὅταν αἰτῆσθε, ἀποδίδοτε τοῖς στρατηγοῖς. μηδὲ ἄχθεσθε τῆς ἐχθὲς ἁρπαγῆς μηδ’ ἐπ’ ὀλίγον· οὐ γὰρ ἐν οἷς ἔχομέν ἐστι τὸ πλουτεῖν, ἀλλ’ ἐν τῷ κρατεῖν ταῖς δυνάμεσιν, ὃ καὶ τὰ ἐχθὲς ἀφαιρεθέντα, ἔτι ὄντα παρὰ τοῖς πολεμίοις σῶα, καὶ τὰ πολέμια αὐτὰ ἐπ’ ἐκείνοις κρατοῦσιν ἡμῖν ἀποδώσει. καὶ εἰ ἐπειγόμεθα αὐτὰ λαβεῖν, ἐπειγώμεθα ἐπὶ τὴν μάχην. ἱκανὰ δὲ καὶ ἐχθὲς ἀντειλήφαμεν αὐτῶν καὶ τῶν ἡμετέρων ἴσως ἱκανώτερα· οἱ μὲν γὰρ ἐκ τῆς Ἀσίας πάνθ’, ὅσα ἐβιάσαντο καὶ ἥρπασαν, ἐπήγοντο, ὑμεῖς δ’ ὡς ἐκ πατρίδος ἰόντες τὰ μὲν δαψιλέστερα οἴκοι ὑπελίπεσθε, τὰ δ’ ἀναγκαῖα μόνα ἐπήγεσθε. εἰ δέ τι καὶ δαψιλὲς ἦν, ἡμέτερον ἦν τῶν στρατηγῶν, οἳ πάντα ἐσμὲν ὑπὲρ τῆς ὑμετέρας νίκης ἐπιδιδόναι πρόθυμοι. καὶ τῆς τοιαύτης δ’ ὅμως ζημίας ὑμῖν ἕνεκα ἐπιδώσομεν νικητήρια, δραχμὰς ἑκάστῳ στρατιώτῃ πεντακισχιλίας, λοχαγῷ δὲ πεντάκις τοσαύτας, χιλιάρχῃ δὲ τὸ διπλάσιον τοῦ λοχαγοῦ.”", "st": "4.120"}, {"sp": "N", "t": "τοιαῦτα εἰπὼν τῆς ἐπιούσης πάλιν ἐξέτασσε· καὶ οὐ κατιόντων οὐδὲ τότε τῶν πολεμίων ὁ μὲν Ἀντώνιος ἐβαρυθύμει καὶ ἐξέτασσεν αἰεί, ὁ δὲ Βροῦτος τοῦ στρατοῦ τὸ μὲν εἶχε συντεταγμένον, μὴ ἀναγκασθείη μάχεσθαι, τῷ δὲ τὰς ὁδοὺς τῆς κομιδῆς τῶν ἀναγκαίων διελάμβανε. λόφος δὲ ἦν ἀγχοτάτω τοῦ Κασσίου στρατοπέδου, δυσχερὴς μὲν ὑπὸ ἐχθρῶν καταληφθῆναι, διὰ τὴν ἐγγύτητα ἐστοξεύεσθαι δυναμένων· ὁ δὲ Κάσσιος αὐτὸν ὅμως ἐφρούρει, μὴ καὶ παρὰ δόξαν ἐπιτολμήσειέ τις. ἐκλειφθέντα δὲ ὑπὸ τοῦ Βρούτου κατέλαβον οἱ περὶ τὸν Καίσαρα νυκτὸς τέτρασι τέλεσιν, ἐπαγόμενοι γέρρα πολλὰ καὶ διφθέρας ἐς προβολὴν τοῖς τοξεύμασιν. ὡς δὲ κατέσχον, ἄλλα τέλη δέκα μετεστρατοπέδευον ὑπὲρ πέντε σταδίους ἀπιοῦσιν ἐπὶ τὴν θάλασσαν καὶ ὑπὲρ ἄλλους τέσσαρας δύο, ὡς τῷδε τῷ τρόπῳ προελευσόμενοι μέχρι θαλάσσης καὶ ἢ παρ’ αὐτὴν ἄρα τὴν θάλασσαν ἢ διὰ τῶν ἑλῶν ἢ ὅν τινα τρόπον ἄλλον ἐπενόουν, βιασόμενοι καὶ τὴν ἀγορὰν ἀποκλείσοντες τῶν πολεμίων. καὶ ὁ Βροῦτος αὐτοῖς ἀντεμηχανᾶτο, ἄλλα τε καὶ φρούρια ἀντικαθιστὰς τοῖς ἐκείνων στρατοπέδοις.", "st": "4.121"}, {"sp": "N", "t": "τὸ δὲ ἔργον ἤπειγε τοὺς ἀμφὶ τὸν Καίσαρα, καὶ λιμὸς ἦν ἤδη σαφής, ἔς τε μέγεθος καὶ δέος ἑκάστης ἡμέρας ἐπεγίνετο. οὔτε γὰρ ἐκ Θεσσαλίας αὐτοῖς ἔτι τὰ ἀρκοῦντα ἐκομίζετο, οὔτε τις ἦν ἐλπὶς ἐκ θαλάσσης, ναυκρατούντων πανταχῇ τῶν πολεμίων· τῆς τε ἔναγχος περὶ τὸν Ἰόνιον συμφορᾶς ἐξηγγελμένης ἐς ἑκατέρους ἤδη, μᾶλλον ἐδεδοίκεσαν αὐτά τε καὶ τὸν χειμῶνα προσιόντα ὡς ἐν πεδίῳ πηλώδει σταθμεύοντες. ὧν ἐνθυμούμενοι τέλος μὲν ὁπλιτῶν ἐς Ἀχαΐαν ἐξέπεμψαν, ἀγείρειν τὰ ἐντυγχάνοντα πάντα καὶ πέμπειν σφίσι κατὰ σπουδήν. οὐκ ἀνεχόμενοι δὲ κινδύνου τοσοῦδε προσιόντος οὔτε τῶν ἄλλων ἐπιτεχνήσεων οὔτε ἐν τῷ πεδίῳ λοιπὸν ἐκτάσσειν, παρὰ τὸ τείχισμα τῶν ἐχθρῶν ἀνέβαινον μετὰ βοῆς καὶ τὸν Βροῦτον ἐκάλουν ἐς μάχην, ἐπισκώπτοντες ἅμα καὶ λοιδοροῦντες καὶ ἐγνωκότες οὐ πολιορκίας τρόπῳ μᾶλλον ἢ μανιώδει φορᾷ μὴ βουλομένῳ συμπλέκεσθαι.", "st": "4.122"}, {"sp": "N", "t": "τῷ δὲ αὐτῷ μὲν ἔγνωστο τὰ ἀπ’ ἀρχῆς, καὶ μᾶλλον ἔτι πυνθανομένῳ περί τε τοῦ λιμοῦ καὶ περὶ τῇς κατὰ τὸν Ἰόνιον εὐπραξίας καὶ τῶν πολεμίων ὁρῶντι τὴν ἐκ τῆς ἀπορίας ἀπόνοιαν· καὶ ᾑρεῖτο πολιορκίας καὶ ἄλλου παντὸς ἀνέχεσθαι, μᾶλλον ἢ ἐς χεῖρας ἰέναι ἀνδράσιν ἐπειγομένοις ὑπὸ λιμοῦ, καὶ ἀπογινώσκουσιν ἐκ τῶν ἄλλων ἑαυτοὺς καὶ ἐν μόναις ταῖς χερσὶ τὴν ἐλπίδα ἔχουσιν. ὁ δὲ στρατὸς οὐχ ὁμοίως εἶχεν ὑπὸ ἀφροσύνης, ἀλλ’ ἐδυσφόρουν γυναικῶν τρόπον ἔνδον μετὰ ἀπραξίας καὶ φόβου κατακεκλεισμένοι. ἐδυσχέραινον δὲ καὶ οἱ ἡγεμόνες αὐτῶν, ἐπαινοῦντες μὲν τὸ ἐνθύμημα τοῦ Βρούτου, νομίζοντες δὲ καὶ θᾶσσον ἐπικρατήσειν τῶν πολεμίων μετὰ προθύμου στρατοῦ. αἴτιον δὲ τούτων ἦν αὐτὸ τὸ Βροῦτον ἐπιεικῆ καὶ φιλόφρονα ἐς ἅπαντας εἶναι καὶ ἀνόμοιον Κασσίῳ, αὐστηρῷ καὶ ἀρχικῷ περὶ πάντα γεγενημένῳ· ὅθεν ἐκείνῳ μὲν ἐξ ἐπιτάγματος ὑπήκουον, οὐ παραστρατηγοῦντες οὐδὲ τὰς αἰτίας μανθάνοντες οὐδὲ εὐθύνοντες, ὅτε καὶ μάθοιεν, Βρούτῳ δὲ οὐδὲν ἄλλ’ ἢ συστρατηγεῖν ἠξίουν διὰ πραΰτητα. τέλος δὲ τοῦ στρατοῦ φανερώτερον ἤδη κατὰ ἴλας καὶ κατὰ συστάσεις διαπυνθανομένου· “τί κατέγνωκεν ἡμῶν ὁ στρατηγός; τί ἔναγχος ἡμάρτομεν οἱ νικήσαντες, οἱ διώξαντες, οἱ τοὺς καθ’ ἡμᾶς πολεμίους κατακανόντες, οἱ τὸ στρατόπεδον αὐτῶν ἑλόντες;” Βροῦτος ἑκὼν ἠμέλει καὶ ἐς ἐκκλησίαν οὐ συνῆγε, μὴ ἀπρεπέστερον ὑπὸ τοῦ πλήθους ἀλογίστως ἐκβιασθείη, καὶ μάλιστα μισθοφόρων, οἷς ἐστιν αἰεί, καθὰ καὶ τοῖς εὐχερέσιν οἰκέταις ἐς ἑτέρους δεσπότας, ἐλπὶς ἐς σωτηρίαν ἡ ἐς τὸ ἀντίπαλον μεταβολή.", "st": "4.123"}, {"sp": "N", "t": "ἐνοχλούντων δὲ αὐτῷ καὶ τῶν ἡγεμόνων καὶ κελευόντων νῦν μὲν ἀποχρήσασθαι τοῦ στρατοῦ τῇ προθυμίᾳ, τάχα τι λαμπρὸν ἐργασομένου, ἢν δ’ ἀντιπίπτῃ τι παρὰ τὴν μάχην, ἐπανιέναι πάλιν ἐς τὰ τείχη καὶ προβάλλεσθαι τὰ αὐτὰ χαρακώματα, χαλεπήνας ὁ Βροῦτος τοῖσδε μάλιστα ἡγεμόσιν οὖσι καὶ περιαλγήσας, ὅτι τὸν αὐτόν οἱ κίνδυνον ἐπικείμενοι συμφέρονται τῷ στρατῷ κουφόνως, ἀμφίβολον καὶ ὀξεῖαν τύχην προτιθέντι νίκης ἀκινδύνου, εἶξεν ἐπ’ οἰκείῳ καὶ σφῶν ἐκείνων ὀλέθρῳ, τοσόνδε ἐπιμεμψάμενος αὐτοῖς· “ἐοίκαμεν ὡς Πομπήιος Μάγνος πολεμήσειν, οὐ στρατηγοῦντες ἔτι μᾶλλον ἢ στρατηγούμενοι.” καί μοι δοκεῖ τόδε μόνον ἐξειπεῖν, ἐπικρύπτων, ὃ ἐδεδοίκει μάλιστα, μὴ ὁ στρατὸς οἷα τοῦ πάλαι Καίσαρος γεγονὼς ἀγανακτήσειέ τε καὶ μεταβάλοιτο· ὅπερ ἐξ ἀρχῆς αὐτός τε καὶ Κάσσιος ὑφορώμενοι ἐς οὐδὲν ἔργον αὐτοῖς πρόφασιν ἀγανακτήσεως ἐπὶ σφίσιν ἐνεδίδουν.", "st": "4.124"}, {"sp": "N", "t": "ὧδε μὲν δὴ καὶ ὁ Βροῦτος ἐξῆγεν ἄκων καὶ ἐς τάξεις διεκόσμει πρὸ τοῦ τείχους καὶ ἐδίδασκε μὴ πολὺ προύχειν τοὺ λόφου, ἵνα αὐτοῖς ἥ τε ἀναχώρησις, εἰ δεήσειεν, εὐχερὴς εἴη καὶ τὰ ἐς τοὺς πολεμίους ἀφιέμενα ἐπιδέξια. ἦν δὲ ἑκατέρωθεν παρακέλευσίς τε πάντων ἐς ἀλλήλους καὶ φρόνημα ἐπὶ τῷ ἔργῳ μέγα καὶ θρασύτης ν̔πὲρ λόγον ἀναγκαῖον, τοῖς μὲν ὑπὸ δέους λιμοῦ, τοῖς δὲ ὑπὸ αἰδοῦς δικαίας, βιασαμένοις τὸν στρατηγὸν ἀναβαλλόμενον ἔτι, μὴ χείροσιν ὧν ὑπέσχοντο ὀφθῆναι μηδὲ ἀσθενεστέροις ὧν ἐθρασύνοντο, μηδὲ προπετείας ὑπευθύνοις μᾶλλον ἢ ἀξιεπαίνοις εὐβουλίας. ἃ καὶ ὁ Βροῦτος αὐτοῖς, ἐπὶ ἵππου περιθέων, σοβαρῷ τῷ προσώπῳ προενέφαινε καὶ δι’ ὀλίγων ὑπεμίμνησκεν, ὅσων ὁ καιρὸς ἐδίδου· “ὑμεῖς ἠθελήσατε μάχεσθαι, ὑμεῖς με ἑτέρως ἔχοντα νικᾶν ἐβιάσασθε· μὴ δὲ ψεύσησθε τῆς ἐλπίδος μήτε ἐμὲ μήτε αὑτούς. ἔχετε καὶ λόφον σύμμαχον καὶ τὰ κατὰ νώτου πάντα ἴδια. οἱ πολέμιοι δ’ εἰσὶν ἐν ἀμφιβόλῳ· μεταξὺ γάρ εἰσιν ὑμῶν τε καὶ λιμοῦ.”", "st": "4.125"}, {"sp": "N", "t": "ὁ μὲν τοιαῦτα λέγων διετρόχαζε, καὶ αὐτὸν αἱ τάξεις ἐπήλπιζον καὶ μετὰ βοῆς παρέπεμπον εὐφήμου· ὁ δὲ Καῖσαρ καὶ ὁ Ἀντώνιος τοὺς ἰδίους περιθέοντες τήν τε δεξιὰν ὤρεγον, ἐφ’ οὓς παραγένοιντο, καὶ σοβαρώτερον ἔτι οἵδε ἐπέσπερχον αὐτοὺς καὶ τὸν λιμὸν οὐκ ἐπέκρυπτον ὡς εὔκαιρον ἐς εὐτολμίαν προφέρειν. “εὕρομεν, ὦ ἄνδρες, τοὺς πολεμίους· ἔχομεν οὓς ἐζητοῦμεν ἔξω τείχους λαβεῖν. μὴ δή τις ὑμῶν τὴν ἰδίαν πρόκλησιν καταισχύνῃ μηδὲ τῆς ἀπειλῆς ἐλάττων γένηται· μηδὲ λιμόν, ὄλεθρον ἀμήχανόν τε καὶ ἐπώδυνον, ἕληται μᾶλλον ἢ πολεμίων τείχη καὶ σώματα, ἃ καὶ τόλμαις ἐνδίδωσι καὶ σιδήρῳ καὶ ἀπονοία. ἔχει δὲ ἡμῖν ἐπείξεως ὧδε τὰ παρόντα, ὡς μηδὲν ἐς τὴν ἐπιοῦσαν ἡμέραν ἀνατίθεσθαι, ἀλλὰ σήμερον περὶ ἁπάντων διακριθῆναι μέχρι νίκης ἐντελοῦς ἢ εὐγενοῦς θανάτου. νικῶσι δ’ ἔστι λαβεῖν διὰ μιᾶς ἡμέρας καὶ δι’ ἑνὸς ἔργου τροφὰς καὶ χρήματα καὶ ναῦς καὶ στρατόπεδα καὶ τὰ νικητήρια παρ’ ἡμῶν. ἔσται δὲ ταῦτα, ἢν πρῶτον μὲν ἐμβάλλοντες αὐτοῖς μνημονεύωμεν τῶν ἐπειγόντων, εἶτα παραρρήξαντες εὐθὺς ἀποκλείωμεν ἀπὸ τῶν πυλῶν, ἐς δὲ τοὺς κρημνοὺς ἢ τὰ πεδία περιωθῶμεν, ἵνα μὴ ὁ πόλεμος αὖθις ἀναφύοιτο μηδὲ ἐς τὴν ἀργίαν πάλιν οἱ ἐχθροὶ διαδιδράσκοιεν, οἳ δι’ ἀσθένειαν, μόνοι δὴ πολεμίων, οὐκ ἐν τῷ μάχεσθαι τὰς ἐλπίδας ἔχουσιν, ἀλλ’ ἐν τῷ μὴ μάχεσθαι.”", "st": "4.126"}, {"sp": "N", "t": "οὕτω μὲν ὁ Καῖσαρ καὶ ὁ Ἀντώνιος παρώτρυνον, ἐφ’ οὓς παραγένοιντο. καὶ πᾶσιν ἦν αἰδὼς ἀξίοις τε φανῆναι τῶν στρατηγῶν καὶ τὴν ἀπορίαν ἐκφυγεῖν, ὑπεραυξηθεῖσαν ἐκ παραλόγου διὰ τὰ ἐν τῷ Ἰονίῳ γενόμενα. ᾑροῦντό τε ἐν ἔργῳ καὶ ἐν ἐλπίσιν, εἰ δέοι, τί παθεῖν μᾶλλον ἢ ὑπὸ ἀμηχάνου κακοῦ δαπανώμενοι.", "st": "4.127"}, {"sp": "N", "t": "ὧδε δὲ ἐχόντων αὐτῶν καὶ πρὸς τὸν ἐγγὺς αὐτὰ ἐκφέροντος ἑκάστου, ὁ θυμὸς ἀμφοτέρων ηὔξετο μάλιστα καὶ ἐνεπίμπλαντο τόλμης ἀκαταπλήκτου· οὐδέν τε ἐν τῷ παρόντι ἀλλήλων ὅτι ἦσαν πολῖται οὐδὲ ἐπεμέμνηντο, ἀλλ’ ὡς ἐκ φύσεως καὶ γένους ἐχθροῖς ἐπηπείλουν. οὕτως ἡ παραυτίκα ὀργὴ τὸν λογισμὸν αὐτοῖς καὶ τὴν φύσιν ἔσβεσεν. ἐπεμαντεύοντο δὲ ὁμαλῶς ἑκάτεροι τήνδε τὴν ἡμέραν ἐν τῷδε τῷ ἔργῳ πάντα τὰ Ῥωμαίων πράγματα κρινεῖν. καὶ ἐκρίθη.", "st": "4.127"}, {"sp": "N", "t": "ἤδη δὲ τῆς ἡμέρας ἀμφὶ τήνδε τὴν παρασκευὴν ἐς ἐνάτην ὥραν δεδαπανημένης αἰετοὶ δύο ἐς τὸ μεταίχμιον συμπεσόντες ἀλλήλοις ἐπολέμουν· καὶ ἦν σιγὴ βαθυτάτη. φυγόντος δὲ τοῦ κατὰ Βροῦτον βοή τε παρὰ τῶν πολεμίων ὀξεῖα ἠγέρθη καὶ τὰ σημεῖα ἑκατέρωθεν ἐπῇρτο, καὶ ἔφοδος ἦν σοβαρά τε καὶ ἀπηνής. τοξευμάτων μὲν δὴ καὶ λίθων ἢ ἀκοντισμάτων ὀλίγον αὐτοῖς ἐδέησε πολέμου νόμῳ, ἐπεὶ οὐδὲ τῇ ἄλλῃ τέχνῃ καὶ τάξει τῶν ἔργων ἐχρῶντο, ἀλλὰ γυμνοῖς τοῖς ξίφεσι συμπλεκόμενοι ἔκοπτόν τε καὶ ἐκόπτοντο καὶ ἀλλήλους ἐξώθουν ἀπὸ τῆς τάξεως, οἱ μὲν περὶ σωτηρίας μᾶλλον ἢ νίκης, οἱ δὲ περὶ νίκης καὶ παρηγορίας στρατηγοῦ βεβιασμένου. φόνος δὲ ἦν καὶ στόνος πολύς, καὶ τὰ μὲν σώματα αὐτοῖς ὑπεξεφέρετο, ἕτεροι δὲ ἀντικαθίσταντο ἐκ τῶν ἐπιτεταγμένων. οἱ στρατηγοὶ δὲ σφᾶς, περιθέοντες καὶ ὁρώμενοι πανταχοῦ, ταῖς τε ὁρμαῖς ἀνέφερον καὶ παρεκάλουν πονοῦντας ἔτι προσπονῆσαι καὶ τοὺς κεκμηκότας ἐνήλλασσον, ὥστε ὁ θυμὸς αἰεὶ τοῖς ἐπὶ τοῦ μετώπου καινὸς ἦν.", "st": "4.128"}, {"sp": "N", "t": "τέλος δὲ οἱ τοῦ Καίσαρος, εἴτε διὰ δέος τοῦ λιμοῦ, εἴτε δι’ αὐτοῦ Καίσαρος εὐτυχίαν (οὐ γὰρ ἐπίμεμπτοί γε ἦσαν οὐδὲ οἱ Βρούτειοι), τὴν φάλαγγα τῶν ἐχθρῶν ἐκίνουν, ὥσπερ τι μηχάνημα τῶν βαρυτάτων ἀνατρέποντες. οἱ δ’ ἀνεωθοῦντο μὲν ἐπὶ πόδας ἐς τὸ ὀπίσω βάδην ἔτι καὶ μετὰ φρονήματος· ὡς δὲ αὐτοῖς καὶ ἡ σύνταξις ἤδη παρελέλυτο, ὀξύτερον ὑπεχώρουν καί, τῶν ἐπιτεταγμένων σφίσι δευτέρων καὶ τρίτων συνυποχωρούντων, μισγόμενοι πάντες ἀλλήλοις ἀκόσμως ἐθλίβοντο ὑπὸ σφῶν καὶ τῶν πολεμίων ἀπαύστως αὐτοῖς ἐπικειμένων, ἕως ἔφευγον ἤδη σαφῶς. καὶ οἱ τοῦ Καίσαρος τότε μάλιστα τοῦ παρηγγελμένου σφίσιν ἐγκρατῶς ἐχόμενοι τὰς πύλας προελάμβανον σφόδρα ἐπικινδύνως (ἄνωθέν τε γὰρ ἐβάλλοντο καὶ ἐκ τοῦ μετώπου), μέχρι πολλοὺς ἐσδραμεῖν ἐκώλυσαν, οἳ διέφυγον ἐπί τε τὴν θάλασσαν καὶ ἐς τὰ ὄρη διὰ τοῦ ποταμοῦ τοῦ Ζυγάκτου.", "st": "4.128"}, {"sp": "N", "t": "γενομένης δὲ τῆς τροπῆς τὸ λοιπὸν ἔργον οἱ στρατηγοὶ διῃροῦντο, Καῖσαρ μὲν αἱρεῖν τοὺς ἐκπίπτοντας ἐκ τοῦ στρατοπέδου καὶ αὐτὸ φυλάσσειν τὸ στρατόπεδον· ὁ δὲ Ἀντώνιος πάντα ἦν καὶ πᾶσιν ἐνέπιπτε, τοῖς τε φεύγουσι καὶ τοῖς ἔτι συνεστῶσι καὶ τοῖς ἄλλοις στρατοπέδοις αὐτῶν, ὁρμῇ τε ὑπερηφάνῳ πάντα ἐβιάζετο ὁμοῦ. καὶ περὶ τοῖς ἡγεμόσι δείσας, μὴ αὑτὸν διαφυγόντες αὖθις ἕτερον στρατὸν ἀγείρειαν, τοὺς ἱππέας ἐξέπεμπεν ἐπὶ τὰς ὁδούς τε καὶ ἐκβολὰς τῆς μάχης, αἱρεῖν τοὺς ἀποδιδράσκοντας· οἳ διελόμενοι τὸ ἔργον ἀνά τε τὸ ὄρος ἐφέροντο σὺν τῷ Θρᾳκίῳ Ῥάσκῳ, δι’ ἐμπειρίαν ὁδῶν συναπεσταλμένῳ, καὶ τὰ χαρακώματα καὶ κρημνοὺς περιστάντες τοὺς ἐκφεύγοντας ἐκυνηγέτουν καὶ τοὺς ἐντὸς ἐφρούρουν. οἱ δὲ Βροῦτον αὐτὸν ἐδίωκον· καὶ αὐτοὺς ἀσχέτως ἔχοντας τοῦ δρόμου Λουκίλιος ἰδὼν ὑπέστη καὶ ὡς Βροῦτος ὢν ἠξίου πρὸς Ἀντώνιον ἀντὶ τοῦ Καίσαρος ἀναχθῆναι· ᾧ δὴ καὶ μάλιστα εἶναι Βροῦτος ἐνομίσθη, τὸν ἀδιάλλακτον ἐχθρὸν ἐκκλίνων. ἀγομένου δὲ αὐτοῦ πυθόμενος ὁ Ἀντώνιος ἀπήντα σὺν ἐπιστάσει, τὴν τύχην ὁμοῦ καὶ τὸ ἀξίωμα τἀνδρὸς καὶ ἀρετὴν ἐνθυμούμενος, ὅπως Βροῦτον ὑποδέξαιτο. πλησιάσαντι δ’ ὁ Λουκίλιος ἐντυχὼν μάλα θρασέως εἶπε· “Βροῦτος μὲν οὐχ ἑάλωκεν, οὐδὲ ἁλώσεταί ποτε πρὸς κακίας ἀρετή· ἐγὼ δὲ τούσδε ἀπατήσας ὧδέ σοι πάρειμι.” καὶ ὁ Ἀντώνιος τοὺς ἱππέας ἰδὼν αἰδουμένους παρηγόρει καί, “οὐ μείονά μοι τήνδε ἄγραν,” εἶπεν, “ἀλλὰ ἀμείνονα ἧς ἐνομίζετε ἐθηρεύσατε, ὅσῳ κρείττων ἐχθροῦ φίλος.” καὶ τὸν Λουκίλιον τότε μέν τινι τῶν φίλων ἔδωκε θεραπεύειν, ὕστερον δὲ αὐτὸς ἔχων ἐχρῆτο ὡς πιστῷ.", "st": "4.129"}, {"sp": "N", "t": "ὁ δὲ Βροῦτος ἀναφεύγει μὲν ἐς τὰ ὄρη σὺν ἱκανῷ πλήθει, ὡς νυκτὸς ἐς τὸ στρατόπεδον ὑποστρέψων ἢ καταβησόμενος ἐπὶ τὴν θάλασσαν· ἐπεὶ δὲ περιείληπτο πάντα φυλακαῖς, διενυκτέρευεν ἔνοπλος μετὰ πάντων. καί φασιν αὐτὸν ἐς τοὺς ἀστέρας ἀναβλέποντα εἰπεῖν· “Ζεῦ, μὴ λάθοι σε τῶνδ’ ὃς αἴτιος κακῶν,”", "st": "4.130"}, {"sp": "N", "t": "ἐνσημαινόμενον ἄρα τὸν Ἀντώνιον. ὃ καὶ αὐτὸν Ἀντώνιόν φασιν ὕστερον ἐν τοῖς ἰδίοις κινδύνοις μεταγινώσκοντα εἰπεῖν, ὅτι συνεξετάζεσθαι Κασσίῳ καὶ Βρούτῳ δυνάμενος ὑπηρέτης γένοιτο Ὀκταουίου. τότε γε μὴν καὶ ὁ Ἀντώνιος ἔνοπλος ἐπὶ τῶν φυλακτηρίων ἀντιδιενυκτέρευε τῷ Βρούτῳ, χάρακα περιθέμενος ἐκ νεκρῶν σωμάτων καὶ λαφύρων συμφορηθέντων. ὁ δὲ Καῖσαρ ἐς μέσην νύκτα πονηθεὶς ἀνεχώρησε διὰ τὴν νόσον, Νωρβανῷ φυλάσσειν παραδοὺς τὸ στρατόπεδον.", "st": "4.130"}, {"sp": "N", "t": "Βροῦτος δὲ καὶ τῆς ἐπιούσης ὁρῶν τὰς ἐφεδρείας τῶν ἐχθρῶν ἐπιμενούσας, ἔχων οὐ πλήρη τέσσαρα τέλη συναναβάντα οἱ, αὐτὸς μὲν ἐπελθεῖν ἐπ’ αὐτοὺς ἐφυλάξατο, τοὺς δὲ ἡγουμένους αὐτῶν, αἰδουμένους τε τὸ ἁμάρτημα καὶ μετανοοῦντας, ἔπεμπεν ἀποπειράσοντας αὐτῶν, εἰ ἐθελήσουσιν ὤσασθαι διὰ τῶν ἐφεδρειῶν καὶ ἀναλαβεῖν τὰ ἴδια, ἔτι φυλασσόμενα ὑπὸ τῶν οἰκείων ὑπολελειμμένων. οἱ δὲ ἀβουλότατα μὲν ἐς τὸ ἔργον ὁρμήσαντες, εὐψυχότατοι δὲ τὸ μέχρι πλείστου γενόμενοι, τότε, βλάπτοντος ἤδη τοῦ θεοῦ, τῷ στρατηγῷ σφῶν ἀπεκρίναντο ἀναξίως βουλεύεσθαι περὶ αὑτοῦ· αὐτοὶ γάρ, τῆς τύχης πολλάκις πεπειραμένοι, οὐκ ἀνατρέψειν τὴν ἔτι λοιπὴν διαλλαγῶν ἐλπίδα. καὶ ὁ Βροῦτος ἐς τοὺς φίλους εἰπών· “οὐδὲν οὖν ἔτι εἰμὶ τῇ πατρίδι χρήσιμος, ὧδε καὶ τούτων ἐχόντων,” ἐκάλει Στράτωνα τὸν Ἠπειρώτην, ὄντα φίλον ἑαυτῷ, καὶ ἐγχειρεῖν ἐκέλευε τῷ σώματι. τούτου δὲ ἔτι βουλεύεσθαι παραινοῦντος ἐκάλει τινὰ τῶν οἰκετῶν. καὶ ὁ Στράτων, “οὐκ ἀπορήσεις,” εἶπεν, “ὦ Βροῦτε, φίλου μᾶλλον ἢ οἰκετῶν ἐς τὰ ὕστατα προστάγματα, εἰ ἤδη κέκριται.” καὶ εἰπὼν ἐνήρεισε ταῖς λαγόσι τοῦ Βρούτου τὸ ξίφος οὔτε ἀποστραφέντος οὔτε ἐνδόντος.", "st": "4.131"}, {"sp": "N", "t": "ὧδε μὲν δὴ Κάσσιος καὶ Βροῦτος ἐθνῃσκέτην, ἄνδρε Ῥωμαίων εὐγενεστάτω τε καὶ περιφανεστάτω καὶ ἐς ἀρετὴν ἀδηρίτω, χωρὶς ἄγους ἑνός, ὥ γε καὶ Γάιος Καῖσαρ, ὄντε τῆς Μάγνου Πομπηίου μοίρας, ἐκ μὲν ἐχθροῖν καὶ πολεμίοιν ἐποιήσατο φίλω, ἐκ δὲ φίλοιν ἦγεν ὡς υἱώ. καὶ ἡ βουλὴ περιποθήτω τε εἶχεν αἰεὶ καὶ ἀτυχήσαντε ἐλεεινὼ δυοῖν τε τούτοιν ἕνεκα πᾶσιν ἀμνηστίαν ἐτίθετο καὶ φυγόντοιν αὐτοῖν ἔπεμψεν ἡγεμονίας, ἵνα μὴ φυγάδες εἶεν, οὐκ ἀμελοῦσα μὲν Γαΐου Καίσαρος οὐδὲ ἐφηδομένη τοῖς γεγονόσιν, ὅπου καὶ ζῶντα τῆς ἀρετὴς καὶ τύχης ἐθαύμαζε καὶ ἀποθανόντα ἔθαπτε δημοσίᾳ καὶ ἐκύρου τὰ ἔργα ἀθάνατα εἶναι ἀρχάς τε καὶ ἡγεμονίας ἐς πολὺ ἐκ τῶν ὑπογραφῶν ἐποίει τῶν Καίσαρος, οὐδὲν ἡγουμένη κρεῖσσον εὑρήσειν ὧν ἐκεῖνος ἐνόησεν. ἀλλ’ ἡ περὶ τώδε τὼ ἄνδρε σπουδὴ καὶ δέος τὸ ὑπὲρ αὐτοῖν προήγαγεν αὐτὴν ἐς ὑπεροψίαν διαβολῆς· οὕτως ἅπασιν ἐγενέσθην τιμίω. ἐγενέσθην δὲ καὶ τῶν φυγόντων τοῖς ἀρίστοις τιμιωτέρω Πομπηίου, πλησιάζοντος καὶ οὐκ ἀδιάλλακτον ἔχοντος αἰτίαν, πορρωτέρω τε ὄντε αὐτὼ καὶ ἀδιαλλάκτω.", "st": "4.132"}, {"sp": "N", "t": "ἐπεί γε μὴν ἔργων ἐδέησε, δυοῖν οὐδὲ ὅλοιν ἐτοῖν στρατιάν τε συνέλεξαν ὑπὲρ εἴκοσιν ὁπλιτῶν τέλη καὶ ἱππέας ἀμφὶ τοὺς δισμυρίους καὶ ναῦς μακρὰς ὑπὲρ τὰς διακοσίας τήν τε ἄλλην παρασκευὴν ἀξιόλογον καὶ χρήματα ἄπειρα καὶ παρ’ ἑκόντων καὶ παρὰ ἀκόντων, πολέμους τε ἐπολέμησαν ἔθνεσι καὶ πόλεσι καὶ τῶν ἀντιστασιωτῶν πολλοῖς καὶ κατώρθουν. ἐθνῶν τε ἐκράτησαν ἀπὸ Μακεδονίας μέχρι Εὐφράτου· καὶ ὅσους ἐπολέμησαν, ἐς συμμαχίαν αὑτοῖς ἔπεισαν καὶ βεβαιοτάτοις ἐχρήσαντο. ἐχρήσαντο δὲ καὶ βασιλεῦσι καὶ δυνάσταις, καὶ Παρθυαίοις καίπερ οὖσιν ἐχθροῖς ἐς τὰ βραχύτερα· ἐπὶ δὲ τὸ μεῖζον ἔργον οὐκ ἀνέμειναν ἐρχομένους, ἵνα μὴ βάρβαρον ἢ ἀντίπαλον ἔθνος ἐθίσειαν ἐπὶ Ῥωμαίοις. ὃ δὲ δὴ μάλιστα πάντων ἀδοκητότατον ἦν, ὁ στρατὸς ὁ πλείων ὅδε Γαΐου Καίσαρος ἐγεγένητο, καὶ δαιμονίως αὐτὸν εὐνοίας καὶ σπουδῆς ἔχοντα ἐς ἐκεῖνον μετέπεισαν οἱ σφαγεῖς οἵδε τοῦ Καίσαρος, καὶ ἐπὶ τὸν τοῦ Καίσαρος υἱὸν ἕσποντο αὐτοῖς πιστότερον ἢ Ἀντωνίῳ τῷ Καίσαρος συναγωνιστῇ τε καὶ συνάρχῳ· οὐ γάρ τις αὐτῶν Βροῦτον ἢ Κάσσιον οὐδὲ ἡσσωμένους ἀπέλιπεν, οἱ Ἀντώνιον ἀμφὶ τὸ Βρεντέσιον καὶ πρὸ πείρας ἀπολιπόντες· ἦν τε πρόφασις αὐτοῖς τῶν πόνων, καὶ ἐπὶ Πομπηίου καὶ νῦν, οὐχ ὑπὲρ σφῶν αὐτῶν, ἀλλ’ ὑπὲρ δημοκρατίας, ὀνόματος εὐειδοῦς μέν, ἀλυσιτελοῦς δὲ αἰεί. σφῶν τε αὐτῶν, ὅτε μηδὲν ἐδόκουν ἔτι εἶναι χρήσιμοι τῇ πατρίδι, ἄμφω κατεφρόνησαν ὁμοίως. ἐν δὲ ταῖς φροντίσι καὶ πόνοις ὁ μὲν Κάσσιος ἀμεταστρεπτί, καθάπερ ἐς τὸν ἀγωνιστὴν οἱ μονομαχοῦντες, ἐς μόνον τὸν πόλεμον ἀφεώρα· ὁ δὲ Βροῦτος, ὅπῃ γίγνοιτο, καὶ φιλοθεάμων ἦν καὶ φιλήκοος, ἅτε καὶ φιλοσοφήσας οὐκ ἀγεννῶς.", "st": "4.133"}, {"sp": "N", "t": "ἀλλὰ καὶ τοιοῖσδε οὖσιν αὐτοῖς ἀντίθετον ἐς ἅπαντα ἦν τὸ ἄγος τὸ ἐς Καίσαρα. ὅ γε οὐδὲ ἁπλοῦν ἄγος ἦν οὐδὲ ἐν ὀλίγῳ· καὶ γὰρ ἐς φίλον ἐγίγνετο παραλόγως καὶ ἐς εὐεργέτην ἐκ πολέμου περισώσαντα ἀχαρίστως καὶ ἐς αὐτοκράτορα ἀθεμίστως καὶ ἐν βουλευτηρίῳ καὶ ἐς ἱερέα καὶ ἱερὰν ἐσθῆτα ἐπικείμενον καὶ δυνάστην μὲν οἷον οὐχ ἕτερον, χρησιμώτατον δὲ ὑπὲρ ἅπαντας τῇ τε πατρίδι καὶ τῇ ἡγεμονίᾳ γενόμενον. ἃ καὶ τὸ δαιμόνιον αὐτοῖς ἄρα ἐνεμέσησε καὶ προεσήμηνε πολλάκις. Κασσίῳ τε γὰρ τὸν στρατὸν καθαίροντι ὁ ῥαβδοῦχος ἀνεστραμμένον τὸν στέφανον ἐπέθηκε· καὶ Νίκη, χρύσεον ἀνάθημα Κασσίου, κατέπεσεν, ὄρνεά τε πολλὰ ὑπὲρ τὸ στρατόπεδον αὐτοῦ καθιέμενα κλαγγὴν οὐδεμίαν ἠφίει, καὶ μελισσῶν ἐπεκάθηντο συνεχεῖς ἑσμοί. Βροῦτον δὲ ἐν Σάμῳ γενεθλιάζοντά φασι παρὰ τὸν πότον, οὐδὲ εὐχερῆ πρὸς τὰ τοιαῦτα ὄντα, ἀλόγως τόδε τὸ ἔπος ἀναβοῆσαι· “ἀλλά με μοῖρ’ ὀλοὴ καὶ Λητοῦς ἔκτανεν υἱός.”", "st": "4.134"}, {"sp": "N", "t": "μέλλοντα δὲ περᾶν ἐκ τῆς Ἀσίας ἐς τὴν Εὐρώπην σὺν τῷ στρατῷ, νυκτὸς ἐγρηγορότα, μαραινομένου τοῦ φωτὸς ὄψιν ἰδεῖν ἑφεστῶσάν οἱ παράλογον καὶ πυθέσθαι μὲν εὐθαρσῶς, ὅς τις ἀνθρώπων ἢ θεῶν εἴη, τὸ δὲ φάσμα εἰπεῖν· “ὁ σός, ὦ Βροῦτε, δαίμων κακός· ὀφθήσομαι δέ σοι καὶ ἐν Φιλίπποις.” καὶ ὀφθῆναί φασιν αὐτῷ πρὸ τῆς τελευταίας μάχης.", "st": "4.134"}, {"sp": "N", "t": "ἐξιόντι δὲ τῷ στρατῷ πρὸ τῶν πυλῶν αἰθίοψ ὑπήντησε· καὶ τόνδε μὲν ὡς οἰώνισμα φαῦλον ὁ στρατὸς αὐτίκα συνέκοψε, δαιμόνια δ’ ἦν αὐτοῖς ἄρα καὶ τάδε, Κάσσιον μὲν ἐν ἀμφηρίστῳ νίκῃ πάντα ἀλόγως ἀπογνῶναι, Βροῦτον δὲ εὐβούλου βραδυτῆτος ἐκβιασθῆναι καὶ ἐς χεῖρας ἐλθεῖν ἀνδράσι διωκομένοις ὑπὸ λιμοῦ, δαψιλῶς αὐτὸν ἔχοντα ἀγορᾶς καὶ ναυκρατοῦντα, καὶ τόδε παθεῖν ὑπὸ τῶν οἰκείων μᾶλλον ἢ τῶν πολεμίων, καὶ μὴν πολλάκις ἀγώνων μετασχόντες ἐν μὲν ταῖς μάχαις οὐδὲν ἔπαθον, ἄμφω δ’ αὑτῶν ἐγένοντο αὐθένται καθάπερ ἐγένοντο τοῦ Καίσαρος. Κάσσιος μὲν δὴ καὶ Βροῦτος τοιάνδε δίκην ἐδεδώκεσαν.", "st": "4.134"}, {"sp": "N", "t": "καὶ Βροῦτον Ἀντώνιος ἀνευρὼν περιέβαλέ τε τῇ ἀρίστῃ φοινικίδι εὐθὺς καὶ καύσας τὰ λείψανα τῇ μητρὶ Σερουιλίᾳ ἔπεμψεν. ὁ δὲ σὺν τῷ Βρούτῳ στρατός, ὅτε ἐπύθοντο τεθνάναι Βροῦτον, πρέσβεις ἐς Καίσαρα καὶ Ἀντώνιον ἔπεμπον καὶ συγγνώμης ἔτυχον καὶ ἐς τὰ στρατεύματα αὐτῶν διῃρέθησαν· καὶ ἦσαν ἀμφὶ τοὺς μυρίους καὶ τετρακισχιλίους. παρέδοσαν δὲ ἐπὶ τοῖς αὐτοῖς ἑαυτοὺς καὶ οἱ κατὰ τὰ φρούρια, πολλὰ ὄντα. τὰ δὲ φρούρια αὐτὰ καὶ τὸ στρατόπεδον ἐδόθη τοῖς Καίσαρος καὶ Ἀντωνίου στρατοῖς διαρπάσαι. τῶν δ’ ἀμφὶ τὸν Βροῦτον ἀνδρῶν ἐπιφανῶν οἱ μὲν ἐν ταῖς μάχαις ἀπέθανον, οἱ δὲ αὑτοὺς ἐξήγαγον ὁμοίως τοῖς στρατηγοῖς, οἱ δὲ καὶ ἐξεπίτηδες ἐμαχέσαντο μέχρι θανάτου· ὧν ἦν Λεύκιός τε Κάσσιος, ὁ ἀδελφιδοῦς αὐτοῦ Κασσίου, καὶ Κάτων ὁ Κάτωνος, ἐμπίπτων ὅδε τοῖς πολεμίοις πολλάκις, εἶθ’ ὑποχωρούντων ἀναλύσας τὸ κράνος, ἵνα ἢ γνώριμος ἢ εὔβλητος ἢ ἀμφότερα εἴη. Λαβεὼν δέ, ἐπὶ σοφίᾳ γνώριμος, ὁ πατὴρ Λαβεῶνος τοῦ κατ’ ἐμπειρίαν νόμων ἔτι νῦν περιωνύμου, βόθρον ἐν τῇ σκηνῇ τὸ μέγεθος αὐτάρκη σώματι ὀρυξάμενος καὶ τὰ λοιπὰ τοῖς θεράπουσιν ἐντειλάμενος ἐπέσκηψε τῇ γυναικὶ καὶ τοῖς παισί, περὶ ὧν ἐβούλετο, καὶ τὰ γράμματα φέρειν ἔδωκε τοῖς οἰκέταις· τοῦ δὲ πιστοτάτου τῆς δεξιᾶς λαβόμενος καὶ περιστρέψας αὐτόν, ὡς ἔθος ἐστὶ Ῥωμαίοις ἐλευθεροῦν, ἐπιστρεφομένῳ ξίφος ἔδωκε καὶ τὴν σφαγὴν ὑπέσχε.", "st": "4.135"}, {"sp": "N", "t": "καὶ τῷδε μὲν ἡ σκηνὴ τάφος ἐγένετο, Ῥάσκος δὲ ὁ Θρᾷξ ἐπανήγαγεν ἐκ τῶν ὀρῶν πολλούς, καὶ γέρας ᾔτησέ τε καὶ ἔλαβε σῴζεσθαι τὸν ἀδελφὸν ἑαυτοῦ Ῥασκούπολιν· ᾧ καὶ διεδείχθη, ὅτι οὐδ’ ἀπ’ ἀρχῆς ἀλλήλοις οἵδε οἱ Θρᾷκες διεφέροντο, ἀλλὰ δύο στρατοπέδων μεγάλων τε καὶ ἀμφηρίστων περὶ τὴν ἐκείνων γῆν συμφερομένων τὸ ἄδηλον τῆς τύχης ἐμερίσαντο, ἵνα ὁ νικῶν περισῴζοι τὸν ἡσσώμενον. Πορκία δ’, ἡ Βρούτου μὲν γυνή, Κάτωνος δὲ ἀδελφὴ τοῦ νεωτέρου, ἐπείτε ἀμφοῖν ὧδε ἀποθανόντοιν ἐπύθετο, φυλασσομένη πρὸς τῶν οἰκείων πάνυ ἐγκρατῶς, ἐσχάρας πυρὸς ἐνεχθείσης ἁρπάσασα τῶν ἀνθράκων κατέπιεν. ὅσοι δ’ ἄλλοι τῶν ἐπιφανῶν ἐς Θάσον διέφυγον, οἱ μὲν αὐτῶν ἐξέπλευσαν, οἱ δὲ ἐπέτρεψαν ἑαυτοὺς ἅμα τῷ λοιπῷ στρατῷ τῶν ὁμοτίμων Μεσσάλᾳ τε Κορουίνῳ καὶ Λευκίῳ Βύβλῳ, ὅ τι βουλεύσοιντο περὶ σφῶν, ποιεῖν περὶ ἁπάντων. οἱ δὲ συνθέμενοι τοῖς περὶ τὸν Ἀντώνιον, Ἀντωνίῳ διαπλεύσαντι ἐς τὴν Θάσον παρέδοσαν, ὅσα ἦν ἐν Θάσῳ χρήματά τε καὶ ὅπλα καὶ τροφαὶ δαψιλεῖς καὶ ἄλλη παρασκευὴ πολλή.", "st": "4.136"}, {"sp": "N", "t": "οὕτω μὲν δὴ Καίσαρί τε καὶ Ἀντωνίῳ διὰ τόλμης ἐπισφαλοῦς καὶ δυοῖν πεζομαχίαιν τηλικοῦτον ἔργον ἤνυστο, οἷον οὐχ ἕτερον ἐγένετο πρὸ ἐκείνου. οὔτε γὰρ στρατὸς τοσοῦτος ἢ τοιοῦτος ἐς χεῖρας πρότερον ἦλθε Ῥωμαίων ἑκατέρωθεν, οὐχ ὑπὸ συντάξει πολιτικῇ στρατευσαμένων, ἀλλὰ ἀριστίνδην ἐπειλεγμένων οὐδ’ ἀπειροπολέμων ἔτι, ἀλλ’ ἐκ πολλοῦ γεγυμνασμένων ἐπί τε σφᾶς καὶ οὐκ ἀλλόφυλα ἢ βάρβαρα ἔθνη τρεπομένων. ἀλλὰ καὶ γλώσσης μιᾶς ὄντες καὶ τέχνης πολέμων μιᾶς καὶ ἀσκήσεως καὶ καρτερίας ὁμοίας, δυσκαταγώνιστοι παρ’ αὐτὸ ἦσαν ἀλλήλοις. οὐδὲ ὁρμῇ καὶ τόλμῃ τοσῇδέ τινες ἐχρήσαντο ἐν πολέμῳ, πολῖταί τε ὄντες ἀλλήλων καὶ οἰκεῖοι καὶ συστρατιῶται γενόμενοι. τεκμήριον δέ, ὅτι τῶν νεκρῶν ὁ ἀριθμός, ἐπανισουμένης ἑκατέρας μάχης, οὐκ ἐλάσσων ἔδοξεν οὐδὲ παρὰ τοῖς νικῶσιν εἶναι.", "st": "4.137"}, {"sp": "N", "t": "ὁ δὲ στρατὸς ὁ Ἀντωνίου καὶ Καίσαρος τὸν τῶν στρατηγῶν λόγον ἐπηλήθευσαν, διὰ μιᾶς ἡμέρας καὶ δι’ ἑνὸς ἔργου κίνδυνον ἔσχατον λιμοῦ καὶ δέος ἀπωλείας ἐς εὐπορίαν δαψιλῆ καὶ σωτηρίαν ἀσφαλῆ καὶ νίκην εὐκλεῆ μεταβαλόντες. ἀπήντησέ γε μὴν αὐτοῖς καὶ ὃ συνιόντες ἐς τὴν μάχην ἐπεμαντεύσαντο Ῥωμαίοις· ἐκρίθη γὰρ αὐτῶν ἡ πολιτεία παρ’ ἐκεῖνο τὸ ἔργον μάλιστα καὶ οὐκ ἐπανῆλθεν ἐς δημοκρατίαν ἔτι, οὐδὲ πόνων αὐτοῖς ἐς ἀλλήλους ἐδέησεν ὁμοίων, χωρίς γε τῆς μετ’ οὐ πολὺ Ἀντωνίου καὶ Καίσαρος στάσεως, ὑστάτης Ῥωμαίοις γενομένης. τὰ δ’ ἐν μέσῳ μετὰ Βροῦτον ὑπό τε Πομπηίου καὶ τῶν διαφυγόντων Κασσίου καὶ Βρούτου φίλων, λείψανα τοσῆσδε παρασκευῆς μεγάλα ἐχόντων, οὔτε ταῖς τόλμαις ὅμοια ἔτι ἐγίγνετο οὔτε ταῖς τῶν ἀνδρῶν ἢ πόλεων ἢ στρατῶν ἐς τοὺς ἡγεμόνας ὁρμαῖς· οὐ γάρ τις αὐτοῖς τῶν ἐπιφανῶν ἔτι οὐδ’ ἡ βουλὴ οὐδὲ ἡ δόξα αὕτη, ὡς ἐς Κάσσιόν τε καὶ Βροῦτον, ἀπήντα.", "st": "4.138"}, {"sp": "HDR", "t": "Ἐμφυλίων Εʹ", "st": "5"}, {"sp": "N", "t": "μετὰ δὲ τὸν Κασσίου καὶ Βρούτου θάνατον ὁ μὲν Καῖσαρ ἐπὶ τῆς Ἰταλίας ᾔει, ὁ δὲ Ἀντώνιος ἐς τὴν Ἀσίαν, ἔνθα αὐτῷ συμβάλλει Κλεοπάτρα βασιλὶς Αἰγύπτου, καὶ εὐθὺς ὀφθεῖσα ἐκράτει. ὁ δὲ ἔρως ὅδε αὐτοῖς τε ἐκείνοις ἐς ἔσχατον ἔληξε κακοῦ καὶ ἐς ὅλην Αἴγυπτον ἐπ’ ἐκείνοις. ὅθεν ἄν τι καὶ Αἰγύπτιον εἴη τῆσδε τῆς βίβλου μέρος, ὀλίγον τε καὶ οὐκ ἄξιον ἐπιγραφῆς πω, διὸ δὴ καὶ τοῖς ἐμφυλίοις πολὺ πλείοσιν οὖσιν ἐπίμικτον. ἐγίγνετο γὰρ δὴ καὶ μετὰ Κάσσιόν τε καὶ Βροῦτον ἕτερα ἐμφύλια ὅμοια, στρατηγοῦ μὲν οὐδενὸς ὄντος ἐπὶ πᾶσιν ὥσπερ ἐκείνοις, κατὰ μέρος δὲ ἑτέρων, μέχρι Πομπήιός τε Σέξστος, ὁ νεώτερος παῖς Πομπηίου Μάγνου, λοιπὸς ὢν ἔτι τῆσδε τῆς στάσεως, τοῖς ἀμφὶ τὸν Βροῦτον ἐπανῃρέθη, καὶ Λέπιδος ἐξέπεσε τοῦ μέρους τῆς ἡγεμονίας καὶ ἡ Ῥωμαίων ἀρχὴ πᾶσα περιῆλθεν ἐς δύο μόνον, Ἀντώνιόν τε καὶ Καίσαρα. ἐγίνετο δὲ αὐτῶν ἕκαστα οὕτως.", "st": "5.1"}, {"sp": "N", "t": "Κάσσιος ὁ Παρμήσιος ἐπίκλην ὑπελέλειπτο μὲν ὑπὸ Κασσίου καὶ Βρούτου περὶ τὴν Ἀσίαν ἐπὶ νεῶν καὶ στρατοῦ, χρήματα ἐκλέγειν. Κασσίου δὲ ἀποθανόντος οὐδὲν ἐλπίζων ὅμοιον ἐν Βρούτῳ, Ῥοδίων ἐπελέξατο νῆας τριάκοντα, ὅσας ἐνόμιζε πληρώσειν, καὶ τὰς λοιπὰς διέπρησε χωρὶς τῆς ἱερᾶς, ἵνα μὴ δύναιντο νεωτερίσαι. καὶ ὁ μὲν τάδε πράξας ἀνήγετο ταῖς τε ἰδίαις καὶ ταῖς τριάκοντα, Κλώδιος δὲ ἐκ Βρούτου πεμφθεὶς ἐς Ῥόδον ἐπὶ νεῶν τρισκαίδεκα, τοὺς Ῥοδίους νεωτερίζοντας εὑρών (ἐτεθνήκει γὰρ ἤδη καὶ ὁ Βροῦτος), ἐξήγαγε τὴν φρουράν, οὖσαν ὁπλιτῶν τρισχιλίων, καὶ ἐς τὸν Παρμήσιον ἐχώρει. ἀφίκετο δὲ αὐτοῖς καὶ Τουρούλιος, ἑτέρας ναῦς ἔχων πολλὰς καὶ χρήματα, ὅσα προεξείλεκτο ἀπὸ τῆς Ῥόδου. ἐς δὴ τὸ ναυτικὸν τοῦτο ὡς ἐς ἤδη τινὰ ἰσχὺν συνέθεον, ὅσοι ἦσαν κατὰ μέρη τῆς Ἀσίας ἐπὶ τῶν ὑπηρεσιῶν, καὶ αὐτὸ ὁπλίταις τε ἐξ ὧν ἐδύναντο ἀνεπλήρουν καὶ ἐρέταις ἐκ θεραπόντων ἢ δεσμωτῶν, ἐπιπλέοντες δὲ ταῖς νήσοις καὶ ἀπὸ τῶν νησιωτῶν. ἦλθον δ’ εἰς αὐτοὺς καὶ Κικέρων ὁ Κικέρωνος καὶ ὅσοι ἄλλοι τῶν ἐπιφανῶν ἐκ τῆς Θάσου διεπεφεύγεσαν. καὶ ταχὺ πλῆθος ἦν καὶ σύνταξις ἀξιόχρεως ἡγεμόνων τε καὶ στρατοῦ καὶ νεῶν. προσλαβόντες δὲ καὶ Λέπιδον μεθ’ ἑτέρας δυνάμεως, ἣ Βρούτῳ καθίστατο Κρήτην, πρὸς Μοῦρκον καὶ Δομίτιον Ἀηνόβαρβον ἐπὶ μεγάλης δυνάμεως ὄντας ἐς τὸν Ἰόνιον διέπλεον. καὶ αὐτῶν οἱ μὲν ἅμα τῷ Μούρκῳ διέπλευσαν ἐς Σικελίαν καὶ τὴν ἰσχὺν Πομπηίῳ Σέξστῳ συνῆψαν, οἱ δὲ κατέμειναν παρὰ Ἀηνοβάρβῳ καί τιν’ αἵρεσιν ἐφ’ ἑαυτῶν καθίσταντο.", "st": "5.2"}, {"sp": "N", "t": "τοιάδε μὲν ἐκ τῶν λειψάνων τῆς παρασκευῆς Κασσίου τε καὶ Βρούτου πρῶτα συνίστατο, ὁ δὲ Καῖσαρ καὶ ὁ Ἀντώνιος ἐπὶ τῇ νίκῃ τῇ περὶ Φιλίππους ἔθυόν τε λαμπρῶς καὶ τὸν στρατὸν ἐπῄνουν. καὶ ἐς τὴν δόσιν τῶν ἐπινικίων ὁ μὲν ἐς τὴν Ἰταλίαν ἐχώρει, τήν τε γῆν αὐτοῖς διανεμήσων καὶ ἐς τὰς ἀποικίας καταλέξων (ὧδε γὰρ αὐτὸς εἵλετο διὰ τὴν ἀρρωστίαν), ὁ δὲ Ἀντώνιος ἐς τὰ πέραν ἔθνη, συλλέξων τὰ χρήματα, ὅσα αὐτοῖς ὑπέσχηντο. διενείμαντο δὲ αὖθις ὅσα καὶ πρότερον ἔθνη καὶ ἐπελάμβανον τὰ Λεπίδου· τήν τε γὰρ Κελτικὴν τὴν ἐντὸς Ἄλπεων ἐδόκει Καίσαρος ἀξιοῦντος αὐτόνομον ἀφιέναι γνώμῃ τοῦ προτέρου Καίσαρος, ὅ τε Λέπιδος διεβάλλετο τὰ πράγματα Πομπηίῳ προδιδόναι· καὶ ὥριστο, εἰ Καίσαρι ψευδὴς ἡ διαβολὴ φανείη, ἕτερα ἀντιδοῦναι τῷ Λεπίδῳ. ἀφίεσαν δὲ καὶ τῆς στρατείας τοὺς ἐντελῆ χρόνον ἐστρατευμένους χωρὶς ὀκτακισχιλίων, οὓς δεηθέντας ἔτι στρατεύεσθαι σφίσιν ἀποδεξάμενοι διείλοντο καὶ συνελόχισαν ἐς στρατηγίδας τάξεις. ὁ δὲ λοιπὸς αὐτοῖς στρατὸς ἐγένετο, σὺν τοῖς μεταθεμένοις ἀπὸ Βρούτου, τέλη πεζῶν ἕνδεκα καὶ ἱππέες μύριοις καὶ τετρακισχίλιοι. καὶ ἔσχεν αὐτῶν ὁ μὲν Ἀντώνιος διὰ τὴν ἀποδημίαν ἓξ τέλη καὶ ἱππέας μυρίους, ὁ δὲ Καῖσαρ ἱππέας τετρακισχιλίους καὶ τέλη πέντε· καὶ τῶνδε δὲ αὐτῶν Ἀντωνίῳ δύο ἔδωκεν, ἀντιληψόμενος ἐκ τῶν ὑπὸ Καληνῷ τοῦ Ἀντωνίου κατὰ τὴν Ἰταλίαν ὑπολελειμμένων.", "st": "5.3"}, {"sp": "N", "t": "ὁ μὲν δὴ Καῖσαρ ἐπὶ τὸν Ἰόνιον ᾔει, ὁ δὲ Ἀντώνιος ἐν Ἐφέσῳ γενόμενος τῇ θεῷ μεγαλοπρεπῶς ἔθυε καὶ τοὺς καταφυγόντας ἐκ τῆς Βρούτου καὶ Κασσίου συμφορᾶς ἐς τὸ ἱερὸν ἱκέτας ἀπέλυε, χωρὶς Πετρωνίου, συνεγνωκότος ἐπὶ τῷ φόνῳ Καίσαρος, καὶ Κοΐντου, προδόντος ἐν Λαοδικείᾳ Κασσίῳ Δολοβέλλαν. τοὺς δὲ Ἕλληνας καὶ ὅσα ἄλλα ἔθνη τὴν ἀμφὶ τὸ Πέργαμον Ἀσίαν νέμονται, κατά τε πρεσβείας παρόντας ἐπὶ συνθέσει καὶ μετακεκλημένους συναγαγὼν ἔλεξεν ὧδε·", "st": "5.4"}, {"sp": "N", "t": "“ὑμᾶς ἡμῖν, ὦ ἄνδρες Ἕλληνες, Ἄτταλος ὁ βασιλεὺς ὑμῶν ἐν διαθήκαις ἀπέλιπε, καὶ εὐθὺς ἀμείνονες ὑμῖν ἦμεν Ἀττάλου· οὓς γὰρ ἐτελεῖτε φόρους Ἀττάλῳ, μεθήκαμεν ὑμῖν, μέχρι δημοκόπων ἀνδρῶν καὶ παρ’ ἡμῖν γενομένων ἐδέησε φόρων. ἐπεὶ δὲ ἐδέησεν, οὐ πρὸς τὰ τιμήματα ὑμῖν ἐπεθήκαμεν, ὡς ἂν ἡμεῖς ἀκίνδυνον φόρον ἐκλέγοιμεν, ἀλλὰ μέρη φέρειν τῶν ἑκάστοτε καρπῶν ἐπετάξαμεν, ἵνα καὶ τῶν ἐναντίων κοινωνῶμεν ὑμῖν. τῶν δὲ ταῦτα παρὰ τῆς βουλῆς μισθουμένων ἐνυβριζόντων ὑμῖν καὶ πολὺ πλείονα αἰτούντων, Γάιος Καῖσαρ τῶν μὲν χρημάτων τὰ τρίτα ὑμῖν ἀνῆκεν ὧν ἐκείνοις ἐφέρετε, τὰς δ’ ὕβρεις ἔπαυσεν· ὑμῖν γὰρ τοὺς φόρους ἐπέτρεψεν ἀγείρειν παρὰ τῶν γεωργούντων. καὶ τόνδε τοιόνδε ὄντα οἱ χρηστοὶ τῶν ἡμετέρων πολιτῶν τύραννον ἐκάλουν, καὶ ὑμεῖς αὐτοῖς συνετελεῖτε χρήματα πολλά, σφαγεῦσί τε οὖσι τοῦ ὑμετέρου εὐεργέτου, καὶ καθ’ ἡμῶν τῶν τιμωρούντων ἐκείνῳ.", "st": "5.4"}, {"sp": "N", "t": "“τῆς δὲ δικαίας τύχης οὐχ, ὡς ἐβούλεσθε, ἀλλ’, ὡς ἦν ἄξιον, κρινάσης τὸν πόλεμον, εἰ μὲν ὡς συναγωνισταῖς τῶν πολεμίων ἔδει χρῆσθαι, κολάσεως ὑμῖν ἔδει, ἐπεὶ δὲ ἑκόντες πιστεύομεν ὑμᾶς κατὰ ἀνάγκην τάδε πεποιηκέναι, τῶν μὲν μειζόνων ἀφίεμεν, χρημάτων δὲ ἡμῖν δεῖ καὶ γῆς καὶ πόλεων ἐς τὰ νικητήρια τοῦ στρατοῦ, τέλη δέ ἐστιν ὀκτὼ καὶ εἴκοσιν ὁπλιτῶν, ἃ μετὰ τῶν συντασσομένων εἰσὶ μυριάδες ἀνδρῶν ὑπὲρ ἑπτακαίδεκα, καὶ τούτων ἄνευθεν οἱ ἱππέες καὶ ἕτερος ὅμιλος ἑτέρου στρατοῦ. ἐκ μὲν δὴ τοῦ πλήθους τῶν ἀνδρῶν τὸ πλῆθος τῆς χρείας συνορᾶν δύνασθε. τὴν δὲ γῆν καὶ τὰς πόλεις αὐτοῖς διαδώσων ὁ Καῖσαρ ἄπεισιν ἐς τὴν Ἰταλίαν, εἰ χρὴ τῷ λόγῳ τὸ ἔργον εἰπεῖν, ἀναστήσων τὴν Ἰταλίαν. ὑμᾶς δ’, ἵνα μὴ γῆς καὶ πόλσων καὶ οἰκιῶν καὶ ἱερῶν καὶ τάφων ἀνίστησθε, ἐς τὰ χρήματα ἐλογισάμεθα, οὐδὲ ἐς ἅπαντα (οὐδὲ γὰρ ἂν δύναισθε), ἀλλὰ μέρος αὐτῶν καὶ βραχύτατον, ὃ καὶ πυθομένους ὑμᾶς ἀγαπήσειν οἴομαι. ἃ γὰρ ἔδοτε τοῖς ἡμετέροις ἐχθροῖς ἐν ἔτεσι δύο (ἔδοτε δὲ φόρους δέκα ἐτῶν), ταῦτα λαβεῖν ἀρκέσει μόνα, ἀλλ’ ἑνὶ ἔτει· ἐπείγουσι γὰρ αἱ χρεῖαι. συνεῖσι δὲ τῆς χάριτος ὑμῖν τοσοῦτον ἂν ἐπείποιμι, ὅτι μηδενὸς ἁμαρτήματος ἴσον ἐπιτίμιον ὁρίζεται.”", "st": "5.5"}, {"sp": "N", "t": "ὁ μὲν οὕτως ἐ͂πεν, ἐς ὀκτὼ καὶ εἴκοσι τέλη πεζῶν τὴν χάριν περιφέρων, ὅτι, οἶμαι, τρία καὶ τεσσαράκοντα ἦν αὐτοῖς, ὅτε ἐν Μουτίνῃ συνηλλάσσοντο ἀλλήλοις καὶ τάδε ὑπισχνοῦντο, ὁ δὲ πόλεμος αὐτὰ ἐς τοσοῦτον ὑπενηνόχει· οἱ δὲ Ἕλληνες ἔτι λέγοντος αὐτοῦ ταῦτα ἐρρίπτουν ἑαυτοὺς ἐς τὸ ἔδαφος, ἀνάγκην καὶ βίαν ἐς αὑτοὺς ἐκ Βρούτου καὶ Κασσίου γενομένας ἐπιλέγοντες οὐκ ἐπιτιμίων ἀξίας εἶναι, ἀλλ’ ἐλέου, δόντες δ’ ἂν τοῖς εὐεργέταις ἑκόντες ἀπορεῖν διὰ τοὺς πολεμίους, οἷς οὐ τὰ χρήματα μόνον, ἀλλὰ καὶ τὰ σκεύη καὶ τοὺς κόσμους ἐσενεγκεῖν ἀντὶ τῶν χρημάτων, τοὺς δὲ αὐτὰ παρὰ σφίσιν ἐς νόμισμα χαλκεῦσαι. καὶ τέλος παρακαλοῦντες ἔτυχον ἐννέα ἐτῶν φόρους ἐσενεγκεῖν ἔτεσι δύο. βασιλεῦσι δὲ καὶ δυνάσταις καὶ πόλεσιν ἐλευθέραις ἄλλα ἐς τὴν ἑκάστων δύναμιν ἐπετάχθη.", "st": "5.6"}, {"sp": "N", "t": "περιιόντι δ’ αὐτῷ τὰ ἔθνη Λεύκιός τε ὁ Κασσίου ἀδελφὸς καὶ ὅσοι ἄλλοι τῶν δεδιότων ἐπεὶ τῆς ἐν Ἐφέσῳ συγγνώμης ἐπύθοντο, ἱκέται προσῄεσαν. καὶ ἀπέλυε πάντας, πλὴν τοὺς συνεγνωκότας ἐπὶ φόνῳ Καίσαρος· τούτοις γὰρ δὴ μόνοις ἀδιάλλακτος ἦν. παρηγόρει δὲ καὶ τῶν πόλεων τὰς μάλιστα δεινὰ παθούσας, Λυκίους μὲν ἀτελεῖς φόρων ἀφιεὶς καὶ Ξάνθον οἰκίζειν παραινῶν, Ῥοδίοις δὲ διδοὺς Ἄνδρον τε καὶ Τῆνον καὶ Νάξον καὶ Μύνδον, ἃς οὐ πολὺ ὕστερον ἀφῃρέθησαν ὡς σκληρότερον ἄρχοντες. Λαοδικέας δὲ καὶ Ταρσέας ἐλευθέρους ἠφίει καὶ ἀτελεῖς φόρων· καὶ Ταρσέων τοὺς πεπραμένους ἀπέλυε τῆς δουλείας διατάγματι. Ἀθηναίοις δ’ ἐς αὐτὸν ἐλθοῦσι μετὰ Τῆνον Αἴγιναν ἔδωκε καὶ Ἴκον καὶ Κέω καὶ Σκίαθον καὶ Πεπάρηθον. ἐπιπαριὼν δὲ Φρυγίαν τε καὶ Μυσίαν καὶ Γαλάτας τοὺς ἐν Ἀσίᾳ Καππαδοκίαν τε καὶ Κιλικίαν καὶ Συρίαν τὴν κοίλην καὶ Παλαιστίνην καὶ τὴν Ἰτουραίαν καὶ ὅσα ἄλλα γένη Σύρων, ἅπασιν ἐσφορὰς ἐπέβαλλε βαρείας καὶ διῄτα πόλεσι καὶ βασιλεῦσιν, ἐν μὲν Καππαδοκίᾳ Ἀριαράθῃ τε καὶ Σισίνῃ, ὧν τῷ Σισίνῃ συνέπραξεν ἐς τὴν βασιλείαν, καλῆς οἱ φανείσης τῆς μητρὸς τοῦ Σισίνου Γλαφύρας· ἐν δὲ Συρίᾳ τοὺς κατὰ πόλεις ἐξῄρει τυράννους.", "st": "5.7"}, {"sp": "N", "t": "καὶ ἐν Κιλικίᾳ πρὸς αὐτὸν ἐλθούσης Κλεοπάτρας ἐμέμψατο μὲν ὡς οὐ μετασχούσης τῶν ἐπὶ Καίσαρι πόνων· τῆς δὲ οὐκ ἀπολογουμένης μᾶλλον ἢ καταλογιζομένης αὐτοῖς, ὅτι καὶ τὰ παρὰ οἷ τέσσαρα τέλη πρὸς Δολοβέλλαν αὐτίκα πέμψειε, καὶ στόλον ἄλλον ἕτοιμον ἔχουσα κωλυθείη ὑπό τε ἀνέμου καὶ αὐτοῦ Δολοβέλλα, ταχυτέρας ἥσσης τυχόνφος, Κασσίῳ τε δὶς ἀπειλοῦντι μὴ συμμαχήσειε καὶ σφίσιν ἐκείνοις πολεμοῦσιν ἐς τὸν Ἰόνιον αὐτὴ τὸν στόλον ἔχουσα πλεύσειε μετὰ παρασκευῆς βαρυτάτης, οὔτε δείσασα Κάσσιον οὔτε φυλαξαμένη Μοῦρκον ναυλοχοῦντα, μέχρι χειμὼν τά τε ἄλλα διελυμήνατο καὶ αὐτὴν ἐς νόσον ἐνέβαλεν, ἧς δὴ χάριν οὐδ’ ὕστερον ἐπαναχθῆναι νενικηκότων ἤδη, ὁ Ἀντώνιος ἐπὶ τῇ ὄψει τὴν σύνεσιν καταπλαγεὶς εὐθὺς αὐτῆς μειρακιωδῶς ἑαλώκει, καίπερ ἔτη τεσσαράκοντα γεγονώς, λεγόμενος μὲν ὑγρότατος ἐς ταῦτα ἀεὶ φῦναι, λεγόμενος δ’ ἐς ταύτην καὶ πάλαι, παῖδα ἔτι οὖσαν, ἐρέθισμά τι τῆς ὄψεως λαβεῖν, ὅτε ἐπὶ τὴν Ἀλεξάνδρειαν Γαβινίῳ στρατεύοντι νέος ἱππαρχῶν εἵπετο.", "st": "5.8"}, {"sp": "N", "t": "εὐθὺς οὖν Ἀντωνίῳ μὲν ἡ περὶ ἅπαντα τέως ἐπιμέλεια ἀθρόα ἠμβλύνετο, Κλεοπάτρα δ’ ὅ τι προστάξειεν, ἐγίγνετο, οὐ διακριδὸν ἔτι περὶ τῶν ὁσίων ἢ δικαίων, ἐπεὶ καὶ τὴν ἀδελφὴν αὐτῆς Ἀρσινόην, ἱκέτιν οὖσαν ἐν Μιλήτῳ τῆς Λευκοφρυηνῆς Ἀρτέμιδος, πέμψας ὁ Ἀντώνιος ἀνεῖλε, καὶ Σεραπίωνα, τὸν ἐν Κύπρῳ στρατηγὸν αὐτῆς, συμμαχήσαντα Κασσίῳ, Τυρίων ὄντα ἱκέτην, ἐκέλευσε τοὺς Τυρίους ἐκδοῦναι τῇ Κλεοπάτρᾳ, ἐκδοῦναι δὲ καὶ Ἀραδίους ἕτερον ἱκέτην, ὅν τινα, Πτολεμαίου τοῦ ἀδελφοῦ τῆς Κλεοπάτρας ἀφανοῦς ἐν τῇ πρὸς Καίσαρα κατὰ τὸν Νεῖλον ναυμαχίᾳ γενομένου, οἱ Ἀράδιοι εἶχον λέγοντα Πτολεμαῖον εἶναι. καὶ τὸν ἐν Ἐφέσῳ δὲ τῆς Ἀρτέμιδος ἱερέα, ὃν Μεγάβυζον ἡγοῦνται, ὑποδεξάμενόν ποτε τὴν Ἀρσινόην ὡς βασιλίδα ἀχθῆναι μὲν ἐκέλευσεν, Ἐφεσίων δ’ αὐτὴν Κλεοπάτραν ἱκετευσάντων μεθῆκεν. οὕτω μὲν ὁ Ἀντώνιος ἐνήλλακτο ταχέως, καὶ τὸ πάθος αὐτῷ τοῦτο ἀρχὴ καὶ τέλος τῶν ἔπειτα κακῶν ἐγένετο. ἀποπλευσάσης δὲ τῆς Κλεοπάτρας ἐς τὰ οἰκεῖα, ὁ Ἀντώνιος ἔπεμπε τοὺς ἱππέας Πάλμυρα πόλιν, οὐ μακρὰν οὖσαν ἀπὸ Εὐφράτου, διαρπάσαι, μικρὰ μὲν ἐπικαλῶν αὐτοῖς, ὅτι Ῥωμαίων καὶ Παρθυαίων ὄντες ἐφόριοι ἐς ἑκατέρους ἐπιδεξίως εἶχον (ἔμποροι γὰρ ὄντες κομίζουσι μὲν ἐκ Περσῶν τὰ Ἰνδικὰ ἢ Ἀράβια, διατίθενται δ’ ἐν τῇ Ῥωμαίων), ἔργῳ δ’ ἐπινοῶν τοὺς ἱππέας περιουσιάσαι. Παλμυρηνῶν δὲ προμαθόντων καὶ τὰ ἀναγκαῖα ἐς τὸ πέραν τοῦ ποταμοῦ μετενεγκάντων τε καὶ ἐπὶ τῆς ὄχθης, εἴ τις ἐπιχειροίη σκευασαμένων τόξοις, πρὸς ἃ πεφύκασιν ἐξαιρέτως, οἱ ἱππέες τὴν πόλιν κενὴν καταλαβόντες ὑπέστρεψαν, οὔτε ἐς χεῖρας ἐλθόντες οὔτε τι λαβόντες.", "st": "5.9"}, {"sp": "N", "t": "καὶ δοκεῖ τόδε τὸ ἔργον Ἀντωνίῳ τὸν μετ’ οὐ πολὺ Παρθυικὸν πόλεμον ἐξάψαι, πολλῶν ἐκ Συρίας τυράννων ἐς αὐτοὺς συμφυγόντων. ἡ γὰρ Συρία μέχρι μὲν ἐπ’ Ἀντίοχον τὸν Εὐσεβῆ καὶ τὸν τοῦ Εὐσεβοῦς υἱὸν Ἀντίοχον ὑπὸ τοῖς ἐκ Σελεύκου τοῦ Νικάτορος ἐβασιλεύετο, ὥς μοι περὶ Σύρων λέγοντι εἴρηται· Πομπηίου δ’ αὐτὴν Ῥωμαίοις προσλαβόντος καὶ στρατηγὸν αὐτῇ Σκαῦρον ἀποδείξαντος, ἡ βουλὴ μετὰ Σκαῦρον ἔπεμψεν ἑτέρους καὶ Γαβίνιον τὸν Ἀλεξανδρεῦσι πολεμήσαντα, ἐπὶ δὲ Γαβινίῳ Κράσσον τὸν ἐν Παρθυαίοις ἀποθανόντα καὶ Βύβλον ἐπὶ τῷ Κράσσῳ. παρὰ δὲ τὴν Γαΐου Καίσαρος ἄρα τελευτὴν καὶ στάσιν ἐπ’ αὐτῇ κατὰ πόλεις ὑπὸ τυράννων εἴχετο, συλλαμβανόντων τοῖς τυράννοις τῶν Παρθυαίων· ἐσέβαλον γὰρ δὴ καὶ ἐς τὴν Συρίαν οἱ Παρθυαῖοι μετὰ τὴν Κράσσου συμφορὰν καὶ συνέπραξαν τοῖς τυράννοις. οὓς ὁ Ἀντώνιος ἐξελαύνων ὑποφεύγοντας ἐς τὴν Παρθυηνὴν καὶ τοῖς πλήθεσιν ἐπιβάλλων ἐσφορὰς βαρυτάτας καὶ ἐς Παλμυρηνοὺς τάδε ἁμαρτών, οὐδ’ ἐπέμεινε συστῆσαι τὴν χώραν θορυβουμένην, ἀλλὰ τὸν στρατὸν ἐς τὰ ἔθνη διελὼν χειμάσοντα αὐτὸς ἐς Αἴγυπτον ᾔει πρὸς Κλεοπάτραν.", "st": "5.10"}, {"sp": "N", "t": "ἡ δὲ αὐτὸν ἐπεδέχετο λαμπρῶς. καὶ ὁ μὲν ἐχείμαζεν ἐνταῦθα, ἄνευ σημείων ἡγεμονίας, ἰδιώτου σχῆμα καὶ βίον ἔχων, εἴθ’ ὡς ἐν ἀλλοτρίᾳ τε ἀρχῇ καὶ βασιλευούσῃ πόλει, εἴτε τὴν χειμασίαν ὡς πανήγυριν ἄγων, ἐπεὶ καὶ φροντίδας ἀπετέθειτο καὶ ἡγεμόνων θεραπείαν, καὶ στολὴν εἶχε τετράγωνον Ἑλληνικὴν ἀντὶ τῆς πατρίου, καὶ ὑπόδημα ἦν αὐτῷ λευκὸν Ἀττικόν, ὃ καὶ Ἀθηναίων ἔχουσιν ἱερεῖς καὶ Ἀλεξανδρέων, καὶ καλοῦσι φαικάσιον. ἔξοδοί τε ἦσαν αὐτῷ ἐς ἱερὰ ἢ γυμνάσια ἢ φιλολόγων διατριβὰς μόναι καὶ δίαιτα μεθ’ Ἑλλήνων ὑπὸ Κλεοπάτρᾳ, ᾗ δὴ καὶ μάλιστα τὴν ἐπιδημίαν ἀνετίθει.", "st": "5.11"}, {"sp": "N", "t": "καὶ τὰ μὲν περὶ Ἀντώνιον ἦν τοιάδε· Καίσαρι δὲ ἐς τὴν Ῥώμην ἐπανιόντι ἥ τε νόσος αὖθις ἤκμαζεν ἐν Βρεντεσίῳ μάλιστα ἐπικινδύνως, καὶ φήμη διήνεγκεν αὐτὸν καὶ τεθνάναι. ῥαΐσας δ’ ἐσῆλθεν ἐς τὴν πόλιν καὶ τοῖς Ἀντωνίου τὰ γράμματα ἐδείκνυε τὰ Ἀντωνίου. οἱ δὲ Καληνόν τε προσέτασσον ἀποδοῦναι τὰ δύο τέλη τῷ Καίσαρι καὶ ἐς Λιβύην ἐπέστελλον Σεξστίῳ Λιβύης καὶ αὐτὸν Καίσαρι ἀποστῆναι. καὶ οἱ μὲν οὕτως ἐποίουν, ὁ δὲ Καῖσαρ οὐδὲν ἀνήκεστον ἁμαρτεῖν δόξαντι Λεπίδῳ Λιβύην ἀντὶ τῶν προτέρων ἐθνῶν ἐνήλλασσε καὶ τὰ λοιπὰ τῶν ἐπὶ ταῖς προγραφαῖς δεδημευμένων διεπίπρασκε. καταλέγοντι δ’ αὐτῷ τὸν στρατὸν ἐς τὰς ἀποικίας καὶ τὴν γῆν ἐπινέμοντι δυσεργὲς ἦν. οἵ τε γὰρ στρατιῶται τὰς πόλεις ᾔτουν, αἳ αὐτοῖς ἀριστίνδην ἦσαν ἐπειλεγμέναι πρὸ τοῦ πολέμου, καὶ αἱ πόλεις ἠξίουν τὴν Ἰταλίαν ἅπασαν ἐπινείμασθαι τὸ ἔργον ἢ ἐν ἀλλήλαις διαλαχεῖν τῆς τε γῆς τὴν τιμὴν τοὺς δωρουμένους ᾔτουν, καὶ ἀργύριον οὐκ ἦν, ἀλλὰ συνιόντες ἀνὰ μέρος ἐς τὴν Ῥώμην οἵ τε νέοι καὶ γέροντες ἢ αἱ γυναῖκες ἅμα τοῖς παιδίοις, ἐς τὴν ἀγορὰν ἢ τὰ ἱερά, ἐθρήνουν, οὐδὲν μὲν ἀδικῆσαι λέγοντες, Ἰταλιῶται δὲ ὄντες ἀνίστασθαι γῆς τε καὶ ἑστίας οἷα δορίληπτοι. ἐφ’ οἷς οἱ Ῥωμαῖοι συνήχθοντο καὶ ἐπεδάκρυον, καὶ μάλιστα, ὅτε ἐνθυμηθεῖεν οὐχ ὑπὲρ τῆς πόλεως, ἀλλ’ ἐπὶ σφίσιν αὐτοῖς καὶ τῇ μεταβολῇ τῆς πολιτείας τόν τε πόλεμον γεγονότα καὶ τὰ ἐπινίκια διδόμενα καὶ τὰς ἀποικίας συνισταμένας τοῦ μηδ’ αὖθις ἀνακῦψαι τὴν δημοκρατίαν, παρῳκισμένων τοῖς ἄρχουσι μισθοφόρων ἑτοίμων, ἐς ὅ τι χρῄζοιεν.", "st": "5.12"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ταῖς πόλεσιν ἐξελογεῖτο τὴν ἀνάγκην, καὶ ἐδόκουν οὐδ’ ὣς ἀρκέσειν. οὐδ’ ἤρκουν, ἀλλὰ ὁ στρατὸς καὶ τοῖς γείτοσιν ἐπέβαινε σὺν ὕβρει, πλέονά τε τῶν διδομένων σφίσι περισπώμενοι καὶ τὸ ἄμεινον ἐκλεγόμενοι. οὐδὲ ἐπιπλήσσοντος αὐτοῖς καὶ δωρουμένου πολλὰ ἄλλα τοῦ Καίσαρος ἐπαύοντο, ἐπεὶ καὶ τῶν ἀρχόντων, ὡς δεομένων σφῶν ἐς τὸ ἐγκρατὲς τῆς ἀρχῆς, κατεφρόνουν. καὶ γὰρ αὐτοῖς ἡ πενταετία παρώδευε, καὶ τὸ ἀσφαλὲς ἡ χρεία συνῆγεν ἀμφοτέροις παρ’ ἀλλήλων, τοῖς μὲν ἡγεμόσιν ἐς τὴν ἀρχὴν παρὰ τοῦ στρατοῦ, τῷ στρατῷ δὲ ἐς τὴν ἐπικράτησιν ὧν ἔλαβον, ἡ τῶν δεδωκότων ἀρχὴ παραμένουσα. ὡς γὰρ αὐτῶν οὐ βεβαίως ἐπικρατήσοντες, εἰ μὴ βεβαίως ἄρχοιεν οἱ δόντες, ὑπερεμάχουν ἀπ’ εὐνοίας ἀναγκαίου. πολλὰ δὲ καὶ ἄλλα τοῖς ἀπορουμένοις αὐτῶν ἐδωρεῖτο, δανειζόμενος ἐκ τῶν ἱερῶν, ὁ Καῖσαρ. ὅθεν τὴν γνώμην ὁ στρατὸς ἐς αὐτὸν ἐπέστρεφε, καὶ πλείων ὑπήντα χάρις ὡς γῆν ἅμα καὶ πόλεις καὶ χρήματα καὶ οἰκήματα δωρουμένῳ καὶ καταβοωμένῳ μὲν ἐπιφθόνως ὑπὸ τῶν ἀφαιρουμένων, φέροντι δὲ τὴν ὕβριν ἐς χάριν τοῦ στρατοῦ.", "st": "5.13"}, {"sp": "N", "t": "ταῦτα δὲ ὁρῶν ὅ τε ἀδελφὸς ὁ τοῦ Ἀντωνίου Λεύκιος Ἀντώνιος, ὑπατεύων τότε, καὶ ἡ γυνὴ τοῦ Ἀντωνίου Φουλβία καὶ ὁ τῆς ἀποδημίας ἐπιτροπεύων τῷ Ἀντωνίῳ Μάνιος, ἵνα μὴ Καίσαρος δόξειε τὸ ἔργον ἅπαν εἶναι μηδὲ μόνος αὐτοῦ τὴν χάριν ἀποφέροιτο μηδ’ ἔρημος ὁ Ἀντώνιος εὐνοίας στρατιωτῶν γένοιτο, τὰς κατοικίσεις ἐτέχναζον ἐς τὴν ἐπιδημίαν Ἀντωνίου διατρίβειν. οὐ δυνατοῦ δὲ φαινομένου διὰ τὸν στρατὸν ἐπείγοντα, τοὺς οἰκιστὰς τῶν Ἀντωνίου τελῶν ἠξίουν Καίσαρα παρὰ σφῶν λαβεῖν, τῆς μὲν συνθήκης Ἀντωνίου μόνῳ Καίσαρι διδούσης, ἐπιμεμφόμενοι δὲ ὡς οὐ παρόντι τῷ Ἀντωνίῳ. καὶ ἐς τὸν στρατὸν αὐτοὶ τήν τε Φουλβίαν παράγοντες καὶ τὰ παιδία τὰ Ἀντωνίου, μάλα ἐπιφθόνως ἱκέτευον μὴ περιιδεῖν Ἀντώνιον ἢ δόξης ἢ χάριτος τῆς ἐς αὐτοὺς ὑπηρεσίας ἀφαιρούμενον. ἤκμαζε δὲ ἐν τῷ τότε μάλιστα τὸ κλέος τὸ Ἀντωνίου καὶ παρὰ τῷ στρατῷ καὶ παρὰ τοῖς ἅλλοις ἅπασι· τὸ γὰρ ἔργον τὸ ἐν Φιλίπποις διὰ τὴν τότε Καίσαρος ἀρρωστίαν ἅπαν ἡγοῦντο Ἀντωνίου γεγονέναι. ὁ δὲ Καῖσαρ οὐκ ἠγνόει μὲν ἀδικούμενος ἐς τὰ συγκείμενα, εἶξε δὲ ἐς χάριν Ἀντωνίου. καὶ οἱ μὲν τοὺς οἰκιστὰς ἐπὶ τοῖς Ἀντωνίου τέλεσιν ἀπέφαινον, οἱ δὲ οἰκισταὶ τοῖς στρατιώταις, ἵνα τι καὶ δοκοῖεν εὐνούστεροι τοῦ Καίσαρος ἐς αὐτοὺς εἶναι, συνεχώρουν ἔτι πλέον ἀδικεῖν. ἄλλο δὴ πλῆθος ἦν ἑτέρων πόλεων, αἳ ταῖς νενεμημέναις γειτονεύουσαί τε καὶ πολλὰ πρὸς τῶν στρατιωτῶν ἀδικούμενοι κατεβόων τοῦ Καίσαρος, ἀδικωτέρας εἶναι τὰς ἀποικίσεις τῶν προγραφῶν· τὰς μὲν γὰρ ἐπὶ ἐχθροῖς, τὰς δὲ ἐπὶ μηδὲν ἀδικοῦσι γίγνεσθαι.", "st": "5.14"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ οὐκ ἠγνόει ἀδικουμένους. ἀμήχανα δ’ ἦν αὐτῷ· οὔτε γὰρ ἀργύριον ἦν ἐς τιμὴν τῆς γῆς δίδοσθαι τοῖς γεωργοῖς, οὔτε ἀναβάλλεσθαι τὰ ἐπινίκια διὰ τοὺς ἔτι πολέμους, Πομπηίου μὲν ἐν τῇ θαλάσσῃ κρατοῦντος καὶ τὴν πόλιν κλείοντος ἐς λιμόν, Ἀηνοβάρβου δὲ καὶ Μούρκου στρατὸν καὶ ναῦς ἄλλας ἀγειρόντων ἀθυμοτέρων δὲ ἐς τὰ ἐσόμενα ὄντων τῶν στρατιωτῶν, εἰ μὴ τὰ πρότερα ἐπινίκια λάβοιεν. πολὺ δ’ ἦν καὶ τὸ παροδεύειν σφίσιν ἤδη τὴν τῆς ἀρχῆς πενταετίαν καὶ χρῄζειν αὖθις εὐνοίας στρατοῦ· διόπερ αὐτῶν καὶ τῆς ὕβρεως ἢ καταφρονήσεως ἐν τῷ τότε ἑκὼν ὑπερεώρα. ἔν γέ τοι τῷ θεάτρῳ, παρόντος αὐτοῦ, στρατιώτης ἀπορῶν οἰκείας ἕδρας παρῆλθεν ἐς τοὺς καλουμένους ἱππέας· καὶ ὁ μὲν δῆμος ἐπεσημήνατο, καὶ ὁ Καῖσαρ τὸν στρατιώτην ἀνέστησεν, ὁ δὲ στρατὸς ἠγανάκτησε καὶ περιστάντες αὐτὸν ἀποχωροῦντα τοῦ θεάτρου τὸν στρατιώτην ἀπῄτουν, οὐχ ὁρώμενον ἡγούμενοι διεφθάρθαι. ἐπελθόντα δὲ ἐνόμιζον ἐκ τοῦ δεσμωτηρίου νῦν προαχθῆναι ἀρνούμενόν τε καὶ τὰ γεγονότα διηγούμενον ψεύδεσθαι διδαχθέντα ἔλεγον καὶ ἐλοιδόρουν ὡς τὰ κοινὰ προδιδόντα· καὶ τὸ μὲν ἐν τῷ θεάτρῳ γενόμενον τοιόνδε ἦν.", "st": "5.15"}, {"sp": "N", "t": "κεκλημένοι δ’ ἐπὶ νέμησιν τότε γῆς ἐς τὸ πεδίον τὸ Ἄρειον ὑπὸ σπουδῆς ἔτι νυκτὸς ἀφίκοντο, καὶ βραδύτερον αὐτοῖς τοῦ Καίσαρος ἐπιόντος ἠγανάκτουν. Νώνιος δὲ λοχαγὸς ἐπέπλησσεν αὐτοῖς σὺν παρρησίᾳ, τό τε πρέπον τοῖς ἀρχομένοις ἐς τὸν ἄρχοντα προφέρων καὶ τὴν Καίσαρος ἀσθένειαν, οὐχ ὑπεροψίαν. οἱ δὲ αὐτὸν τὰ μὲν πρῶτα ἔσκωπτον ὡς κόλακα, πλέονος δὲ ἑκατέρωθεν τοῦ διερεθίσματος γενομένου ἐλοιδόρουν τε καὶ ἔβαλλον καὶ φεύγοντα ἐδίωκον ἔς τε τὸν ποταμὸν ἐξαλόμενον ἐξειρύσαντες ἔκανον καὶ ἔρριψαν, ἔνθα παροδεύσειν ὁ Καῖσαρ ἔμελλεν. οἱ μὲν δὴ φίλοι τῷ Καίσαρι παρῄνουν μηδὲ ἐπελθεῖν ἐς αὐτούς, ἀλλ’ ἐκστῆναι μανιώδει φορᾷ. ὁ δ’ ἐπῄει μέν, ἀναθρέψειν ἔτι μᾶλλον αὐτῶν ἡγούμενος τὸ μανιῶδες, εἰ μὴ ἀφίκοιτο, καὶ τὸν Νώνιον ἰδὼν ἐξέκλινεν, ὡς δὲ ὀλίγων ταῦτα δρασάντων ἐπεμέμφετο καὶ ἐς τὸ μέλλον ἀλλήλων φείδεσθαι παρῄνει καὶ τὴν γῆν διένεμε, καὶ δωρεὰς αἰτεῖν τοῖς ἀξίοις ἐπέτρεπε καὶ τῶν οὐκ ἀξίων ἐνίοις ἐδίδου παρὰ γνώμην, μέχρι τὸ πλῆθος ἐκπλαγὲν αὑτοῦ τῆς βαρύτητος μετενόει καὶ ᾐδεῖτο καὶ κατεγίνωσκον αὑτῶν καὶ τοὺς ἐς τὸν Νώνιον ἁμαρτόντας ἠξίουν ἀνευρόντα κολάσαι. ὁ δὲ καὶ γινώσκειν αὐτοὺς ἔφη καὶ κολάσειν αὐτῷ τῷ συνειδότι σφῶν μόνῳ καὶ τῇ παρ’ ὑμῶν καταγνώσει. οἱ δὲ συγγνώμης τε ὁμοῦ καὶ τιμῆς καὶ δωρεῶν ἀξιωθέντες εὐθὺς αὐτὸν εὐφήμουν ἐκ μεταβολῆς.", "st": "5.16"}, {"sp": "N", "t": "καὶ δύο μὲν εἰκόνες ἐκ πλεόνων αἵδε ἔστων τῆς τότε δυσαρχίας· αἴτιον δ’ ἦν, ὅτι καὶ οἱ στρατηγοὶ ἀχειροτόνητοι ἦσαν οἱ πλείους ὡς ἐν ἐμφυλίοις καὶ οἱ στρατοὶ αὐτῶν οὐ τοῖς πατρίοις ἔθεσιν ἐκ καταλόγου συνήγοντο οὐδ’ ἐπὶ χρείᾳ τῆς πατρίδος, οὐδὲ τῷ δημοσίῳ στρατευόμενοι μᾶλλον ἢ τοῖς συνάγουσιν αὐτοὺς μόνοις, οὐδὲ τούτοις ὑπὸ ἀνάγκῃ νόμων, ἀλλ’ ὑποσχέσεσιν ἰδίαις, οὐδὲ ἐπὶ πολεμίους κοινούς, ἀλλὰ ἰδίους ἐχθρούς, οὐδὲ ἐπὶ ξένους, ἀλλὰ πολίτας καὶ ὁμοτίμους. τάδε γὰρ πάντα αὐτοῖς τὸν στρατιωτικὸν φόβον ἐξέλυεν, οὔτε στρατεύεσθαι νομίζουσι μᾶλλον ἢ βοηθεῖν οἰκείᾳ χάριτι καὶ γνώμῃ, καὶ τοὺς ἄρχοντας ἡγουμένοις ὑπὸ ἀνάγκης αὑτῶν ἐς τὰ ἴδια ἐπιδεῖσθαι. τό τε αὐτομολεῖν, πάλαι Ῥωμαίοις ἀδιάλλακτον ὄν, τότε καὶ δωρεῶν ἠξιοῦτο· καὶ ἔπρασσον αὐτὸ οἵ τε στρατοὶ κατὰ πλῆθος καὶ τῶν ἐπιφανῶν ἀνδρῶν ἔνιοι, νομίζοντες οὐκ αὐτομολίαν εἶναι τὴν ἐς τὰ ὅμοια μεταβολήν. ὅμοια γὰρ δὴ πάντα ἦν, καὶ οὐδὲ ἕτερα αὐτῶν ἐς ἔχθραν κοινὴν Ῥωμαίοις ἀπεκέκριτο· ἥ τε τῶν στρατηγῶν ὑπόκρισις μία, ὡς ἁπάντων ἐς τὰ συμφέροντα τῇ πατρίδι βοηθούντων, εὐχερεστέρους ἐποίει πρὸς τὴν μεταβολὴν ὡς πανταχοῦ τῇ πατρίδι βοηθοῦντας. ἃ καὶ οἱ στρατηγοὶ συνιέντες ἔφερον, ὡς οὐ νόμῳ μᾶλλον αὐτῶν ἄρχοντες ἢ ταῖς δωρεαῖς.", "st": "5.17"}, {"sp": "N", "t": "οὕτω μὲν ἐς στάσεις τότε πάντα, καὶ ἐς δυσαρχίαν τοῖς στασιάρχοις τὰ στρατόπεδα ἐτέτραπτο, τὴν δὲ Ῥώμην λιμὸς ἐπίεζεν, οὔτε τῆς θαλάσσης τι αὐτοῖς φερούσης διὰ Πομπήιον, οὔτε τῆς Ἰταλίας διὰ τοὺς πολέμους γεωργουμένης. ὃ δὲ καὶ γένοιτο, ἐς τοὺς στρατοὺς ἐδαπανᾶτο. ἐκλώπευόν τε οἱ πολλοὶ νυκτὸς ἐν τῇ πόλει καὶ κλοπῆς ἔτι βιαιότερον ἠνώχλουν, καὶ ἠνώχλουν ἀδεῶς, καὶ ἡ δόξα ἐς τοὺς στρατιώτας ἐφέρετο. ὁ δὲ λεὼς ἀπέκλειε τὰ ἐργαστήρια καὶ τὰς ἀρχὰς ἐξανίστη, ὡς οὔτε ἀρχῶν οὔτε τεχνῶν χρῄζοντες ἐν ἀπορούσῃ καὶ λῃστευομένῃ πόλει.", "st": "5.18"}, {"sp": "N", "t": "Λευκίῳ δὲ ὄντι δημοτικῷ καὶ δυσχεραίνοντι τῇ τῶν τριῶν ἀρχῇ, οὐδὲ ἐπὶ τῷ χρόνῳ παύσεσθαι νομιζομένῃ, προσκρούσματα ἐς τὸν Καίσαρα ἐγίγνετο καὶ διαφοραὶ μείζους· τούς τε γεωργούς, ὅσοι τῆς γῆς ἀφῃροῦντο, ἱκέτας γιγνομένους τῶν δυνατῶν ἑκάστου μόνος ὑπεδέχετο καὶ βοηθήσειν ὑπισχνεῖτο, κἀκείνων ὑπισχνουμένων ἀμυνεῖν, ἐς ὃ κελεύοι. ὅθεν αὐτὸν ὁ στρατὸς ὁ Ἀντωνίου κατεμέμφετο καὶ ὁ Καῖσαρ ὡς ἀντιπράσσοντα Ἀντωνίῳ, καὶ Φουλβία ὡς πολεμοποιοῦντα ἐν ἀκαίρῳ, μέχρι τὴν Φουλβίαν ὁ Μάνιος πανούργως μετεδίδαξεν ὡς εἰρηνευομένης μὲν τῆς Ἰταλίας ἐπιμενεῖν Ἀντώνιον Κλεοπάτρᾳ, πολεμουμένης δ’ ἀφίξεσθαι κατὰ τάχος. τότε γὰρ δὴ γυναικός τι παθοῦσα ἡ Φουλβία τὸν Λεύκιον ἐπέτριβεν ἐς τὴν διαφοράν. ἐξιόντος δὲ τοῦ Καίσαρος ἐς τὰ λοιπὰ τῶν κατοικίσεων, ἔπεμπεν ἑψομένους αὐτῷ τοὺς Ἀντωνίου παῖδας ἅμα τῷ Λευκίῳ, ὡς μηδὲν ἐκ τῆς ὄψεως ὁ Καῖσαρ ἐν τῷ στρατῷ πλέον ἔχοι. ἱππέων δὲ Καίσαρος ἐκτρεχόντων ἐπὶ τὴν Βρεττίων ἠιόνα, πορθουμένην ὑπὸ Πομπηίου, δόξας ὁ Λεύκιος ἢ ὑποκρινάμενος ἐφ’ ἑαυτὸν καὶ τοὺς Ἀντωνίου παῖδας τόδε τὸ ἱππικὸν ἀπεστάλθαι, διέδραμεν ἐς τὰς Ἀντωνίου κατοικίας, συλλεγόμενος φρουρὰν τῷ σώματι, καὶ τὸν Καίσαρα τῷ στρατῷ διέβαλλεν ἐς ἀπιστίαν πρὸς Ἀντώνιον. ὁ δὲ ἀντεδίδασκεν αὐτούς, ὅτι αὑτῷ μὲν καὶ Ἀντωνίῳ πάντα εἶναι φίλια καὶ κοινά, Λεύκιον δὲ ὑφ’ ἑτέρας γνώμης αὐτοὺς πολεμοποιεῖν ἐς ἀλλήλους ἀντιπράσσοντα τῇ τῶν τριῶν ἀρχῇ, δι’ ἣν οἱ στρατευόμενοι τὰς ἀποικίας ἔχουσι βεβαίους· καὶ τοὺς ἱππέας εἶναι καὶ νῦν ἐν Βρεττίοις τὰ ἐντεταλμένα φυλάσσοντας.", "st": "5.19"}, {"sp": "N", "t": "ὧν οἱ ἡγεμόνες τοῦ στρατοῦ πυνθανόμενοι διῄτησαν αὐτοῖς ἐν Τεανῷ καὶ συνήλλαξαν ἐπὶ τοῖσδε, τοὺς μὲν ὑπάτους τὰ πάτρια διοικεῖν μὴ κωλυομένους ὑπὸ τῶν τριῶν ἀνδρῶν, μηδενὶ δὲ γῆν ὑπὲρ τοὺς στρατευσαμένους ἐν Φιλίπποις ἐπινέμεσθαι, τά τε χρήματα τῶν δεδημευμένων καὶ τιμὰς τῶν ἔτι πιπρασκομένων καὶ τὸν στρατὸν Ἀντωνίου τὸν περὶ τὴν Ἰταλίαν ἐπ’ ἴσης διανέμεσθαι καὶ μηδέτερον αὐτῶν ἔτι καταλέγειν ἐκ τῆς Ἰταλίας, στρατεύοντι δὲ ἐπὶ Πομπήιον τῷ Καίσαρι δύο συμμαχεῖν τέλη παρὰ Ἀντωνίου, ἀνεῷχθαι δὲ τὰς Ἄλπεις τοῖς ὑπὸ Καίσαρος πεμπομένοις ἐς τὴν Ἰβηρίαν καὶ μὴ κωλύειν αὐτοὺς ἔτι Ἀσίνιον Πολλίωνα, Λεύκιον δὲ ἐπὶ τοῖσδε συνηλλαγμένον ἀποθέσθαι τὴν φρουρὰν τοῦ σώματος καὶ πολιτεύειν ἀδεῶς. τάδε μὲν ἦν, ἃ συνέθεντο ἀλλήλοις διὰ τῶν ἡγεμόνων τοῦ στρατοῦ, ἐπράχθη γε μὴν αὐτῶν δύο μόνα τὰ τελευταῖα· καὶ Σαλουιδιηνὸς ἄκων αὐτῷ συμπεριῆλθε τὰς Ἄλπεις.", "st": "5.20"}, {"sp": "N", "t": "οὐ γιγνομένων δὲ τῶν ἄλλων ἢ βραδυνόντων, ἐς Πραινεστὸν ἀνεχώρει Λεύκιος, δεδιέναι λέγων Καίσαρα διὰ τὴν ἀρχὴν δορυφορούμενον, αὐτὸς ἀφρούρητος ὤν. ἀνεχώρει δὲ καὶ Φουλβία πρὸς Λέπιδον, ἤδη λέγουσα περὶ τοῖς τέκνοις δεδιέναι· τοῦτον γὰρ ἀντὶ τοῦ Καίσαρος προυτίθει. καὶ τάδε μὲν ἐγράφετο παρ’ ἑκατέρων Ἀντωνίῳ, καὶ φίλοι μετὰ τῶν γραμμάτων ἐς αὐτὸν ἐπέμποντο, οἳ διδάξειν ἔμελλον περὶ ἑκάστων. καὶ οὐχ εὗρον ἐρευνώμενος, ὅ τι σαφῶς ἀντεγράφετο αὐτοῖς. οἱ δὲ τῶν στρατῶν ἡγεμόνες συνομόσαντες κρινεῖν τοῖς ἄρχουσιν αὖθις, ὃ δοκοίη δίκαιον εἶναι, καὶ τοὺς ἀπειθοῦντας ἐς αὐτὸ συναναγκάσειν, ἐκάλουν ἐπὶ ταῦτα τοὺς περὶ Λεύκιον. οὐ δεξαμένων δ’ ἐκείνων, ὁ Καῖσαρ ἐπιφθόνως αὐτοὺς ἔν τε τοῖς ἡγεμόσι τοῦ στρατοῦ καὶ παρὰ τοῖς Ῥωμαίων ἀρίστοις ἐπεμέμφετο. οἱ δὲ ἐξέθεον ἐς τὸν Λεύκιον καὶ παρεκάλουν οἰκτεῖραι μὲν ἐπὶ τοῖς ἐμφυλίοις τὴν πόλιν καὶ τὴν Ἰταλίαν, δέξασθαι δὲ κοινῷ νόμῳ τὴν κρίσιν ἢ ἐπὶ σφῶν ἢ ἐπὶ τῶν ἡγεμόνων γενέσθαι.", "st": "5.21"}, {"sp": "N", "t": "αἰδουμένου δὲ τοῦ Λευκίου τά τε λεγόμενα καὶ τοὺς λέγοντας, ὁ Μάνιος μάλα θρασέως ἔφη τὸν μὲν Ἀντώνιον οὐδὲν ἀλλ’ ἢ χρήματα μόνα ἀγείρειν ἐν ξένοις ἀνδράσι, τὸν δὲ Καίσαρα καὶ τὴν στρατιὰν καὶ τὰ ἐπίκαιρα τῆς Ἰταλίας ταῖς θεραπείας προκαταλαμβάνειν· τήν τε γὰρ Κελτικὴν Ἀντωνίῳ πρότερον δεδομένην ἐλευθεροῦν μετ’ ἐξαπάτης Ἀντωνίου, καὶ τὴν Ἰταλίαν σχεδὸν ἅπασαν ἀντὶ μόνων ὀκτωκαίδεκα πόλεων τοῖς ἐστρατευμένοις καταγράφειν, τέσσαρσί τε καὶ τριάκοντα τέλεσιν ἀντὶ ὀκτὼ καὶ εἴκοσι τῶν συμμαχησάντων ἐπινέμειν οὐ γῆν μόνην, ἀλλὰ καὶ τὰ ἐκ τῶν ἱερῶν χρήματα, συλλέγοντα μὲν ὡς ἐπὶ Πομπήιον, ἐφ’ ὃν οὐδέ πω παρατάττεται λιμωττούσης ὧδε τῆς πόλεως, διαιροῦντα δὲ τοῖς στρατοῖς ἐς θεραπείαν κατὰ Ἀντωνίου καὶ τὰ δεδημευμένα οὐ πιπράσκοντα μᾶλλον ἢ δωρούμενον αὐτοῖς. χρῆναι δέ, εἰ τῷ ὄντι εἰρηνεύειν ἐθέλοι, τῶν μὲν ἤδη διῳκημένων ὑποσχεῖν λόγον, ἐς δὲ τὸ μέλλον, ἃ ἂν κοινῇ βουλευομένοις δοκῇ, μόνα πράσσειν. οὕτω μὲν θρασέως ὁ Μάνιος ἠξίου μήτε τὸν Καίσαρά τινος εἶναι κύριον ἔργου μήτε τὴν Ἀντωνίου συνθήκην βέβαιον, ὡρισμένου τῶν ἐγκεχειρισμένων ἑκάτερον αὐτοκράτορα εἶναι καὶ τὸ πρασσόμενον ὑπὸ ἀλλήλων εἶναι κύριον. πανταχόθεν οὖν ὁ Καῖσαρ ἑώρα πολεμησείοντας αὐτούς, καὶ παρεσκευάζοντο αὐτῶν ἑκάτεροι.", "st": "5.22"}, {"sp": "N", "t": "δύο δὲ στρατοῦ τέλη τὰ ἐς Ἀγκῶνα πόλιν ᾠκισμένα, Καίσαρί τε ὄντα πατρῷα καὶ ἐστρατευμένα Ἀντωνίῳ, τῆς τε ἰδίας παρασκευῆς αὐτῶν πυθόμενοι καὶ τὴν εἰς ἑκάτερον σφῶν οἰκειότητα αἰδούμενοι, πρέσβεις ἔπεμψαν ἐς Ῥώμην, οἳ ἔμελλον ἑκατέρων ἐς διαλύσεις δεήσεσθαι. Καίσαρος δ’ αὐτοῖς εἰπόντος οὐκ Ἀντωνίῳ πολεμεῖν, ἀλλ’ ὑπὸ Λευκίου πολεμεῖσθαι, συμβαλόντες οἱ πρέσβεις τοῖς ἡγεμόσι τοῦδε τοῦ στρατοῦ, κοινῇ πάντες ἐς Λεύκιον ἐπρέσβευον, ἀξιοῦντες αὐτὸν ἐς δίκην Καίσαρι συνελθεῖν· δῆλοί τε ἦσαν, ὃ πράξειν ἔμελλον, εἰ μὴ τὴν κρίσιν ὑποδέχοιτο. δεξαμένων δὲ τῶν ἀμφὶ τὸν Λεύκιον, χωρίον τε ὥριστο τῇ δίκῃ Γάβιοι πόλις ἐν μέσῳ Ῥώμης τε καὶ Πραινεστοῦ, καὶ συνέδριον τοῖς κρίνουσιν ἐγίνετο καὶ βήματα ἐν μέσῳ δύο τοῖς ἐροῦσιν ὡς ἐν δίκῃ. πρότερος δ’ ὁ Καῖσαρ ἐλθὼν ἱππέας ἔπεμψεν ἐς τὴν πάροδον τοῦ Λευκίου, ἐρευνησομένους ἄρα, μή τίς ποθεν ὁρῷτο ἐνέδρα. καὶ οἱ ἱππέες οἵδε ἑτέροις ἱππεῦσι τοῦ Λευκίου, προδρόμοις ἄρα ἢ καὶ τοῖσδε κατασκόποις, συμβαλόντες ἔκτεινάν τινας αὐτῶν. καὶ ἀνεχώρησε δείσας ὁ Λεύκιος, ὡς ἔλεγεν, ἐπιβουλήν· καλούμενός τε ὑπὸ τῶν ἡγεμόνων τοῦ στρατοῦ, παραπέμψειν αὐτὸν ὑπισχνουμένων, οὐκέτι ἐπείθετο.", "st": "5.23"}, {"sp": "N", "t": "οὕτω μὲν ἦσαν αἱ διαλύσεις ἄπρακτοι, καὶ πολεμεῖν ἐγνώκεσαν καὶ διαγράμμασιν ἤδη πικροῖς κατ’ ἀλλήλων ἐχρῶντο. στρατὸς δὲ ἦν Λευκίῳ μὲν ὁπλιτῶν ἓξ τέλη, ὅσα αὐτὸς ἐς τὴν ὑπατείαν ἐλθὼν ἐστράτευσε, καὶ τὰ Ἀντωνίου ἕνδεκα ἕτερα, ὧν ἐστρατήγει Καληνός, σύμπαντα ταῦτα ἀνὰ τὴν Ἰταλίαν· Καίσαρι δὲ ἐν μὲν Καπύῃ τέσσαρα ἦν τέλη, καὶ περὶ αὐτὸν αἱ στρατηγίδες, ἓξ δὲ ἕτερα Σαλουιδιηνὸς ἦγεν ἐξ Ἰβηρίας. καὶ χρήματα ἦν Λευκίῳ μὲν ἐξ ἐθνῶν τῶν ὑπὸ τὸν Ἀντώνιον οὐ πολεμουμένων, Καίσαρι δέ, ἃ εἰλήχει, πάντα χωρὶς Σαρδοῦς ἐπολεμεῖτο, ὅθεν ἐκ τῶν ἱερῶν ἐδανείζετο, σὺν χάριτι ἀποδώσειν ὑπισχνούμενος, ἀπό τε Ῥώμης ἐκ τοῦ Καπιτωλίου καὶ ἀπὸ Ἀντίου καὶ Λανουβίου καὶ Νεμοῦς καὶ Τίβυρος, ἐν αἷς μάλιστα πόλεσι καὶ νῦν εἰσι θησαυροὶ χρημάτων ἱερῶν δαψιλεῖς.", "st": "5.24"}, {"sp": "N", "t": "Τετάρακτο δὲ αὐτῷ καὶ τὰ τῆς Ἰταλίας ἔξω. Πομπήιος γὰρ ἐκ τῶν προγραφῶν καὶ κατοικίσεων τοῦ στρατοῦ καὶ τῆσδε τῆς Λευκίου διαφορᾶς ἐπὶ μέγα δόξης καὶ δυνάμεως ἦρτο. οἱ γὰρ περὶ σφῶν δεδιότες ἢ τὰ ὄντα ἀφαιρούμενοι ἢ τὴν πολιτείαν ὅλως ἀποστρεφόμενοι ἐς αὐτὸν ἐχώρουν μάλιστα· καὶ ἡ ἄλλη νεότης ὡρμημένη στρατεύεσθαι διὰ τὰ κέρδη καὶ οὐδὲν ἡγούμενοι διαφέρειν, ὑφ’ ὅτῳ στρατεύσονται, Ῥωμαίοις πανταχοῦ συστρατευόμενοι, μᾶλλον ἐς τὸν Πομπήιον ἐχώρουν ὡς δικαιότερα αἱρούμενον. γεγένητό τε πλούσιος ἐκ τῆς θαλασσίου λείας καὶ ναῦς εἶχε πολλὰς καὶ πληρώματα ἐντελῆ. Μοῦρκός τε ἀφῖκτο αὐτῷ δύο ἄγων στρατοῦ τέλη καὶ τοξότας πεντακοσίους καὶ χρήματα πολλὰ καὶ ναῦς ὀγσοήκοντα· καὶ τὸν ἄλλον στρατὸν ἐκ Κεφαληνίας μετεπέμπετο. ὅθεν τισὶ δοκεῖ τότε ὁ Πομπήιος ἐπελθὼν εὐμαρῶς ἂν τῆς Ἰταλίας κρατῆσαι, ὑπό τε λιμοῦ καὶ στάσεως διεφθαρμένης καὶ ἐς αὐτὸν ἀφορώσης.", "st": "5.25"}, {"sp": "N", "t": "ἀλλὰ Πομπηίῳ μὲν ὑπὸ ἀφροσύνης οὐκ ἐπιχειρεῖν, ἀλλὰ ἀμύνεσθαι μόνον ἐδόκει, μέχρι καὶ τοῦδε ἥσσων ἐγένετο· ἐν δὲ Λιβύῃ Σέξστιος, ὕπαρχος Ἀντωνίου, παρεδεδώκει μὲν ἄρτι τὸν στρατόν, ὑπὸ Λευκίου κεκελευσμένος, Φάγγωνι τῷ Καίσαρος, ἐπισταλὲν αὖθις ἀναλαμβάνειν αὐτὸν οὐκ ἀποδιδόντι τῷ Φάγγωνι ἐπολέμει, συναγαγών τινας τῶν ἀπεστρατευμένων καὶ Λιβύων πλῆθος ἄλλο καὶ ἑτέρους παρὰ τῶν βασιλέων. ἡττηθέντων δὲ τῶν κερῶν ἑκατέρων καὶ ληφθέντων τῶν στρατοπέδων, ὁ Φάγγων ἡγούμενος ἐκ προδοσίας τάδε παθεῖν αὑτὸν διεχρήσατο. καὶ Λιβύης μὲν αὖθις ὁ Σέξστιος ἑκατέρας ἐκράτει· Βόκχον δὲ τὸν Μαυρουσίων βασιλέα Λεύκιος ἔπεισε πολεμεῖν Καρρίνα τῷ τὴν Ἰβηρίαν ἐπιτροπεύοντι τῷ Καίσαρι. Ἀηνόβαρβός τε ἑβδομήκοντα ναυσὶ καὶ στρατοῦ δύο τέλεσι καὶ τοξόταις καὶ σφενδονήταις τισὶ καὶ ψιλοῖς καὶ μονομάχοις περιπλέων τὸν Ἰόνιον ἐπόρθει τὰ τοῖς τρισὶν ἀνδράσιν ὑπήκοα, ἔς τε τὸ Βρεντέσιον ἐπιπλεύσας τῶν Καίσαρος τριήρων τὰς μὲν εἷλε, τὰς δὲ ἐνέπρησε, καὶ τοὺς Βρεντεσίους ἐς τὰ τείχη κατέκλεισε καὶ τὴν χώραν προυνόμευεν.", "st": "5.26"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ἐς τὸ Βρεντέσιον στρατιωτῶν τέλος ἔπεμπε καὶ Σαλουιδιηνὸν κατὰ σπουδὴν ἐκ τῆς ἐς Ἰβηρίαν ὁδοῦ μετεκάλει. τούς τε στρατολογήσοντας σφίσιν ἀνὰ τὴν Ἰταλίαν ὁ Καῖσαρ καὶ ὁ Λεύκιος περιέπεμπον· πεῖραί τε τούτων τῶν ξεναγῶν ἦσαν ἐς ἀλλήλους βραχύτεραι καὶ μείζους καὶ ἐνέδραι πολλάκις. ἡ δὲ εὔνοια τῶν Ἰταλῶν ἐς τὸν Λεύκιον παρὰ πολὺ ἐποίει, ὡς ὑπὲρ σφῶν τοῖς κληρουχουμένοις πολεμοῦντα. καὶ οὐχ αἱ καταγραφόμεναι τῷ στρατῷ πόλεις ἔτι μόναι, ἀλλ’ ἡ Ἰταλία σχεδὸν ἅπασα ἀνίστατο, φοβουμένη τὰ ὅμοια· τούς τε τῷ Καίσαρι κιχραμένους ἐκ τῶν ἱερῶν χρημάτων ἐκβάλλοντες ἐκ τῶν πόλεων ἢ ἀναιροῦντες, τὰ τείχη σφῶν διὰ χειρὸς εἶχον καὶ πρὸς τὸν Λεύκιον ἐχώρουν. ἐχώρουν δὲ καὶ οἱ κατοικιζόμενοι τῶν στρατιωτῶν ἐς τὸν Καίσαρα, ὡς ἐς οἰκεῖον ἤδη πόλεμον ὑπὲρ σφῶν ἑκάτεροι διαρούμενοι.", "st": "5.27"}, {"sp": "N", "t": "καὶ τῶνδε γιγνομένων ὁ Καῖσαρ ὅμως ἔτι τήν τε βουλὴν καὶ τοὺς καλουμένους ἱππέας συναγαγὼν ἔλεγεν ὧδε· “καταγινώσκομαι μέν, εὖ οἶδα, ὑπὸ τῶν περὶ Λεύκιον, οὐκ ἀμυνόμενος αὐτούς, εἰς ἀσθένειαν ἢ ἀτολμίαν, ἃ καὶ νῦν μου καταγνώσονται διὰ τήνδε τὴν σύνοδον ὑμῶν· ἐμοὶ δὲ ἔρρωται μὲν ὁ στρατός, ὅσος τέ μοι συναδικεῖται τὴν κληρουχίαν ἀφαιρούμενος ὑπὸ Λευκίου καὶ ὁ ἄλλος, ὃν ἔχω, ἔρρωται δὲ καὶ τὰ λοιπὰ πλὴν τῆς γνώμης μόνης. οὐ γὰρ ἡδύ μοι πολεμεῖν ἐμφυλίους πολέμους χωρὶς ἀνάγκης βαρείας, οὐδὲ καταχρῆσθαι τῶν πολιτῶν τοῖς ἔτι λοιποῖς κατ’ ἀλλήλων, καὶ μάλιστα τοῦδε τοῦ ἐμφυλίου οὐκ ἐκ Μακεδονίας ὑμῖν ἢ Θράκης ἀκουσθησομένου, ἀλλ’ ἐν αὐτῇ τῇ Ἰταλίᾳ γενησομένου, ἣν πόσα χρὴ χωρὶς τῶν ἀπολλυμένων ἀνδρῶν κακοπαθῆσαι, γιγνομένην στάδιον ἡμῖν. ἐγὼ μὲν δὴ διὰ τάδε ὀκνῶ καὶ νῦν ἔτι μαρτύρομαι μηδὲν ἀδικεῖν Ἀντώνιον μηδὲ ἀδικεῖσθαι πρὸς Ἀντωνίου· ὑμᾶς δὲ ἐλέγξαι τοὺς ἀμφὶ τὸν Λεύκιον τάδε δι’ ὑμᾶς αὐτοὺς καὶ συναλλάξαι μοι παρακαλῶ. καὶ εἰ μὴ πείθοιντο μηδὲ νῦν, ἐκείνοις μὲν αὐτίκα δείξω τὰ μέχρι νῦν εὐβουλίαν, οὐ δειλίαν οὖσαν, ὑμᾶς δὲ καὶ παρ’ ὑμῖν αὐτοῖς καὶ πρὸς Ἀντώνιον ἀξιῶ μάρτυρας εἶναί μοι καὶ συνίστασθαι διὰ τὴν ὑπεροψίαν Λευκίου.”", "st": "5.28"}, {"sp": "N", "t": "ταῦτ’ εἶπεν ὁ Καῖσαρ. καὶ τούτων οἱ μὲν δὴ πἅλιν ἐς τὸ Πραινεστὸν ἐξέτρεχον· καὶ ὁ Λεύκιος τοσόνδε εἶπεν, ὅτι καὶ τῶν ἔργων ἤδη προειλήφασιν ἀμφότεροι καὶ ὁ Καῖσαρ ὑποκρίνεται, τέλος ἄρτι πέμψας ἐς τὸ Βρεντέσιον κωλύειν Ἀντώνιον ἐπανιόντα. ὁ δὲ Μάνιος καὶ ἐπιστολὴν ἐδείκνυε τοῦ Ἀντωνίου, εἴτε πλασάμενος εἴτε ἀληθῆ, πολεμεῖν, ἐάν τις αὑτοῦ τὴν ἀξίωσιν καθαιρῇ. ἐρομένων δὲ τῶν ἀπὸ τῆς βουλῆς, εἰ καθαιροῖτό τι τῆς ἀξιώσεως Ἀντωνίου, καὶ προκαλουμένων ἐς δίκην περὶ τοῦδε, ἕτερα αὖ πολλὰ ἐσοφίζετο ὁ Μάνιος, ἕως οἱ μὲν ἀπῆλθον ἄπρακτοι, καὶ οὐ συνῆλθον ἐς τὴν ἀπόκρισιν τῷ Καίσαρι, εἴτε καθ’ ἑαυτὸν ἀπαγγείλας ἕκαστος εἴτε δι’ ἑτέραν γνώμην εἴτε ὑπὸ αἰδοῦς· ὁ δὲ πόλεμος ἀνέῳκτο, καὶ ὁ Καῖσαρ ἐπ’ αὐτὸν ἐξῄει, φύλακα τῆς Ῥώμης Λέπιδον σὺν δύο τέλεσι καταλιπών. οἱ δὲ πολλοὶ τῶν ἐπιφανῶν τότε μάλιστα ἐπεδείκνυον οὐκ ἀρέσκεσθαι τῇ τῶν τριῶν ἀρχῇ· ἐς γὰρ τὸν Λεύκιον ἐχώρουν.", "st": "5.29"}, {"sp": "N", "t": "καὶ ἦν τὰ κεφαλαια τοῦ πολέμου τοιάδε. Λευκίου μὲν δὴ δύο τέλη περὶ Ἄλβην ἐστασίασε καὶ τοὺς ἄρχοντας ἐκβαλόντα ἐς ἀπόστασιν ἐχώρει· ἐπειγομένων δὲ ἐς αὐτὰ Καίσαρός τε καὶ Λευκίου, φθάσας τὸν Καίσαρα ὁ Λεύκιος ἀνεσώσατο αὐτὰ χρήμασί τε πολλοῖς καὶ ὑποσχέσεσι μεγάλαις. Φουρνίου δ’ ἄλλον στρατὸν ἄγοντος τῷ Λευκίῳ, ὁ Καῖσαρ ἐξήπτετο τῆς οὐραγίας· ἐς δὲ λόφον ἀναδραμόντι τῷ Φουρνίῳ καὶ νυκτὸς ἐς ὁμογνώμονα πόλιν ἐπειγομένῳ Σεντίαν, νυκτὸς μὲν οὐχ ἕσπετο ὁ Καῖσαρ ἐνέδραν ὑποπτεύων, ἡμέρας δὲ τήν τε Σεντίαν ὁμοῦ καὶ τὸ τοῦ Φουρνίου στρατόπεδον ἐπολιόρκει. Λεύκιος δὲ ἐς Ῥώμην ἐπειγόμενος τρεῖς μὲν τάξεις προύπεμψεν, αἳ νυκτὸς ἔλαθον ἐς τὴν πόλιν ἐσδραμοῦσαι, αὐτὸς δὲ σὺν πολλῷ στρατῷ καὶ ἱππεῦσι καὶ μονομάχοις εἵπετο. καὶ αὐτὸν Νωνίου τοῦ φύλακος τῶν πυλῶν δεξαμένου τε καὶ τὸν ὑφ’ αὑτῷ στρατὸν ἐγχειρίσαντος, ὁ μὲν Λέπιδος ἐς Καίσαρα ἔφευγεν, ὁ δὲ Λεύκιος Ῥωμαίοις ἐδημηγόρει, Καίσαρα μὲν καὶ Λέπιδον αὐτίκα δώσειν δίκην ἀρχῆς βιαίου, τὸν δὲ ἀδελφὸν αὐτὴν ἑκόντα ἀποθήσεσθαι καὶ ὑπατείαν ἀλλάξεσθαι, νομιμωτέραν ἀρχὴν παρανόμου καὶ πάτριον ἀντὶ τῆς τυραννικῆς.", "st": "5.30"}, {"sp": "N", "t": "καὶ ὁ μὲν τάδε εἰπών, ἡδομένων ἁπάντων καὶ ἡγουμένων ἤδη λελύσθαι τὴν τῶν τριῶν ἀρχήν, αὐτοκράτωρ ὑπὸ τοῦ δήμου προσαγορευθεὶς ἐπὶ τὸν Καίσαρα ἐχώρει καὶ στρατὸν ἤθροιζεν ἄλλον ἐκ τῶν ἀποικίδων Ἀντωνίου πόλεων καὶ αὐτὰς ἐκρατύνατο. αἱ δὲ δι’ εὐνοίας μὲν ἦσαν Ἀντωνίῳ, Βαρβάτιος δὲ ὁ Ἀντωνίου ταμίας, Ἀντωνίῳ τι προσκρούσας καὶ διὰ ταῦτ’ ἐπανιών, ἔλεγε πυνθανομένοις τὸν Ἀντώνιον χαλεπαίνειν τοῖς πολεμοῦσι τῷ Καίσαρι κατὰ τῆς κοινῆς σφῶν δυναστείας. καὶ οἱ μέν, ὅσοι μὴ τῆς ἐξαπάτης ᾔσθοντο τῆς Βαρβατίου, ἐς τὸν Καίσαρα ἀπὸ τοῦ Λευκίου μετετίθεντο· ὁ δὲ Λεύκιος ὑπήντα Σαλουιδιηνῷ μετὰ στρατοὺ πολλοῦ πρὸς Καίσαρα ἐκ Κελτῶν ἐπανιόντι. καὶ εἵποντο τῷ Σαλουιδιηνῷ Ἀσίνιός τε καὶ Οὐεντίδιος, Ἀντωνίου στρατηγοὶ καὶ οἵδε, κωλύοντες αὐτὸν ἐς τὸ πρόσθεν ἰέναι. Ἀγρίππας δέ, φίλτατος Καίσαρι, δείσας ἐπὶ τῷ Σαλουιδιηνῷ μὴ κυκλωθείη, Σούτριον κατέλαβε, χωρίον τι χρήσιμον τῷ Λευκίῳ, νομίσας τὸν Λεύκιον ἀπὸ τοῦ Σαλουιδιηνοῦ περισπάσειν ἐφ’ ἑαυτὸν καὶ οἷ τὸν Σαλουιδιηνὸν βοηθήσειν, κατόπιν τοῦ Λευκίου γενόμενον. καὶ τάδε μέν, ὡς προσεδόκησεν ὁ Ἀγρίππας, ἐγίγνετο ἅπαντα· ὁ δὲ Λεύκιος ἀποτυχὼν ὧν ἐπενόει, πρὸς Ἀσίνιον καὶ Οὐεντίδιον ᾔει, ἐνοχλούντων αὐτὸν ἑκατέρωθεν Σαλουιδιηνοῦ τε καὶ Ἀγρίππου καὶ φυλασσόντων, ὅτε μάλιστα περιλάβοιεν ἐν τοῖς στενοῖς.", "st": "5.31"}, {"sp": "N", "t": "ἐκφανείσης δὲ παρ’ αὐτὰ τῆς ἐπιβουλῆς ὁ Λεύκιος οὐ θαρρῶν ἀμφοτέροις ἑκατέρωθεν οὖσιν ἐς χεῖρας ἰέναι ἐς Περνσίαν παρῆλθεν, ἐχυρὰν πόλιν, καὶ παρ’ αὐτὴν ἐστρατοπέδευσε, τοὺς περὶ τὸν Οὐεντίδιον περιμένων. ὁμοῦ δ’ αὐτόν τε καὶ τὴν Περυσίαν ὁ Ἀγρίππας καὶ ὁ Σαλουιδιηνὸς καὶ ὁ Καῖσαρ ἐπελθὼν τρισὶ στρατοπέδοις ἐκυκλώσαντο· καὶ τὸν ἄλλον στρατὸν ὁ Καῖσαρ ἐκάλει πανταχόθεν κατὰ σπουδὴν ὡς ἐπὶ τοῦτο δὴ κεφάλαιον τοῦ πολέμου, ἐν ᾧ Λεύκιον εἶχε περιειλημμένον. προύπεμπε δὲ καὶ ἑτέρους, ἐμποδὼν εἶναι τοῖς ἀμφὶ τὸν Οὐεντίδιον ἐπιοῦσιν. οἱ δὲ καὶ αὐτοὶ διὰ σφῶν ὤκνουν ἐπείγεσθαι, τόν τε πόλεμον ἀποδοκιμάζοντες ὅλως καὶ τὴν Ἀντωνίου γνώμην οὐκ ἐπιστάμενοι καὶ τὴν ἡγεμονίαν τῆς στρατιᾶς οὐ παριέντες ἀλλήλοις κατ’ ἀξίωσιν οὐδέτερος. ὁ δὲ Λεύκιος οὔτ’ ἐς μάχην ᾔει τοῖς περικαθημένοις, ἀμείνοσι καὶ πλέοσιν οὖσι καὶ γεγυμνασμένοις, νεοστράτευτον ἔχων τὸ πλέον, οὔτε ἐς ὁδοιπορίαν, ἐνοχλησόντων αὐτὸν ὁμοῦ τοσῶνδε. Μάνιον δὲ ἐς τὸν Οὐεντίδιον καὶ Ἀσίνιον ἔπεμπεν, ἐπείγειν αὐτοὺς βοηθεῖν πολιορκουμένῳ Λευκίῳ, καὶ Τισιηνὸν μετὰ τετρακισχιλίων ἱππέων, λεηλατεῖν τὰ Καίσαρος, ἵνα ἀνασταίη. αὐτὸς δὲ παρῆλθεν ἐς τὴν Περυσίαν ὡς ἐν ὀχυρᾷ πόλει χειμάσων, εἰ δέοι, μέχρι τοὺς περὶ τὸν Οὐεντίδιον ἀφικέσθαι.", "st": "5.32"}, {"sp": "N", "t": "καὶ ὁ Καῖσαρ αὐτίκα μετὰ σπουδῆς ἅπαντι τῷ στρατῷ τὴν Περυσίαν ἀπετείχιζε χάρακι καὶ τάφρῳ, πεντήκοντα καὶ ἓξ σταδίους περιιὼν διὰ τὸ τῆς πόλεως λοφῶδες καὶ σκέλη μακρὰ ἐπὶ τὸν Τίβεριν ἐκτείνων, ἵνα τι ἐς τὴν Περυσίαν μὴ ἐσφέροιτο. ἀντεπονεῖτό γε μὴν καὶ ὁ Λεύκιος, ἑτέροις ὁμοίοις χαρακώμασι καὶ τάφροις τὴν πέζαν ὀχυρούμενος τοῦ λόφου. καὶ Φουλβία Οὐεντίδιον καὶ Ἀσίνιον καὶ Ἀτήιον καὶ Καληνὸν ἐκ τῆς Κελτικὴς ἤπειγε βοηθεῖν Λευκίῳ καὶ στρατὸν ἄλλον ἀγείρασα Πλάγκον ἔπεμπεν ἄγειν Λευκίῳ. Πλάγκος μὲν δὴ τέλος τοῦ Καίσαρος ἐς Ῥώμην ὁδεῦον διέφθειρεν· Ἀσινίου δὲ καὶ Οὐεντιδίου σὺν μὲν ὄκνῳ καὶ διχονοίᾳ τῆς Ἀντωνίου γνώμης, διὰ δὲ Φουλβίαν ὅμως καὶ διὰ Μάνιον ἐς τὸν Λεύκιον ἰόντων καὶ τοὺς ἀποκλείοντας βιαζομένων, ὁ Καῖσαρ ὑπήντα σὺν Ἀγρίππᾳ, φυλακὴν τῆς Περυσίας καταλιπών. οἱ δὲ οὔτε τω συμβαλόντες ἀλλήλοις οὔτε σὺν προθυμίᾳ χωροῦντες, ὁ μὲν αὐτῶν ἐς Ῥάβενναν, ὁ δ’ ἐς Ἀρίμινον, ὁ δὲ Πλάγκος ἐς Σπωλήτιον συνέφυγον. καὶ ὁ Καῖσαρ αὐτῶν ἑκάστῳ στρατὸν ἐπιστήσας, ἵνα μὴ πρὸς ἀλλήλους συνέλθοιεν, ἐς τὴν Περυσίαν ἐπανῆλθε καὶ μετὰ σπουδῆς τὰς τάφρους προσεσταύρου καὶ ἐδιπλασίαζε τὸ βάθος καὶ πλάτος ὡς τριάκοντα πόδας ἀμφότερα εἶναι, τό τε περιτείχισμα ὕψου καὶ πύργους ἐπ’ αὐτοῦ ξυλίνους δι’ ἑξήκοντα ποδῶν ἵστη χιλίους καὶ πεντακοσίους· καὶ ἐπάλξεις τε ἦσαν αὐτῷ πυκναὶ καὶ ἡ ἄλλη παρασκευὴ πᾶσα διμέτωπος, ἔς τε τοὺς πολιορκουμένους καὶ εἴ τις ἔξωθεν ἐπίοι. ἐγίγνετο δὲ ταῦτα σὺν πείραις πολλαῖς καὶ μάχαις, ἀκοντισαι μὲν ἀμεινόνων ὄντων τῶν Καίσαρος, συμπλέκεσθαι δὲ τῶν Λευκίου μονομάχων· καὶ πολλοὺς ἔκτεινον συμπλεκόμενοι.", "st": "5.33"}, {"sp": "N", "t": "ὡς δὲ ἐξείργαστο πάντα τῷ Καίσαρι, λιμὸς ἥπτετο τοῦ Λευκίου, καὶ τὸ κακὸν ἤκμαζεν ἀγρίως ἅτε μηδὲν αὐτοῦ μηδὲ τῆς πόλεως προπαρεσκευασμένης. ὧν ὁ Καῖσαρ αἰσθόμενος ἀκριβεστέρας τὰς φυλακὰς ἐποίει. νουμηνίας δὲ ἔτους ἐς τὴν ἐπιοῦσαν ἡμέραν οὔσης, φυλάξας ὁ Λεύκιος τὴν ἑορτὴν ὡς ἀμελείας τοῖς πολεμίοις αἰτίαν ἐξέθορε νυκτὸς ἐπὶ τὰς πύλας αὐτῶν ὡς διεκπαίσων αὐτοὺς καὶ στρατιὰν ἐπαξόμενος ἑτέραν· πολλὴ γὰρ ἦν αὐτῷ πολλαχοῦ. ταχὺ δὲ τοῦ πλησίον ἐφεδρεύοντος τέλους καὶ τοῦ Καίσαρος αὐτοῦ σὺν ταῖς στρατηγίσι σπείραις ἐπιδραμόντων, ὁ Λεύκιος μάλα προθύμως ἀγωνιζόμενος ἀνεώσθη. τῶν δ’ αὐτῶν ἡμερῶν ἐν Ῥώμῃ, τοῦ σίτου τοῖς στρατευομένοις φυλασσομένου, τὸ πλῆθος τῷ πολέμῳ καὶ τῇ νίκῃ φανερῶς ἐπηρῶντο καὶ ἐς τὰς οἰκίας ἐστρέχοντες ἐπὶ ἐρεύνῃ σίτου, ὅσα εὕροιεν, ἥρπαζον.", "st": "5.34"}, {"sp": "N", "t": "οἱ δ’ ἀμφὶ τὸν Οὐεντίδιον αἰδούμενοι λιμῷ κάμνοντα Λεύκιον περιορᾶν, ἐχώρουν ἐς αὐτὸν ἅπαντες, βιαζόμενοι τοὺς Καίσαρος πανταχόθεν αὐτοὺς περικειμένους καὶ ἐνοχλοῦντας. ὑπαντώντων δ’ αὐτοῖς Ἀγρίππου τε καὶ Σαλουιδιηνοῦ μετὰ δυνάμεως ἔτι πλείονος, ἔδεισαν, μὴ κυκλωθεῖεν, καὶ ἐς Φουλκίνιόν τι χωρίον ἐξέκλιναν, ἑξήκοντα καὶ ἑκατὸν σταδίους τῆς Περυσίας διεστηκός· ἔνθα αὐτοὺς τῶν ἀμφὶ τὸν Ἀγρίππαν περικαθημένων πυρὰ πολλὰ ἤγειραν, σύμβολα τῷ Λευκίῳ. καὶ γνώμην ἐποιοῦντο Οὐεντίδιος μὲν καὶ Ἀσίνιος βαδίζειν καὶ ὣς μαχούμενοι, Πλάγκος δὲ ἔσεσθαι μέσους Καίσαρός τε καὶ Ἀγρίππου, χρῆναι δ’ ἔτι καραδοκεῖν τὰ γιγνόμενα· καὶ ἐκράτει λέγων ὁ Πλάγκος. οἱ δ’ ἐν τῇ Περυσίᾳ τὰ μὲν πυρὰ ἰδόντες ἥδοντο, τῶν δ’ ἀνδρῶν βραδυνόντων εἴκασαν καὶ τούσδε ἐνοχλεῖσθαι καὶ παυσαμένου τοῦ πυρὸς διεφθάρθαι. ὁ δὲ Λεύκιος τοῦ λιμοῦ πιέζοντος ἐνυκτομάχησεν αὖθις ἐκ πρώτης φυλακῆς ἐς ἕω περὶ ἅπαν τὸ περιτείχισμα· καὶ οὐ δυνηθεὶς ἀνέθορεν αὖθις ἐς τὴν Περυσίαν καὶ τὰς ὑπολοίπους συλλογισάμενος τροφὰς ἀπεῖπε δίδοσθαι τοῖς θεράπουσι καὶ ἐφύλασσεν αὐτοὺς μηδ’ ἐκφυγεῖν, ἵνα μὴ γνωριμώτερον γένοιτο τοῖς πολεμίοις τὸ δεινόν. ἠλῶντο οὖν οἱ θεράποντες κατὰ πλῆθος καὶ κατέπιπτον ἔν τε αὐτῇ τῇ πόλει καὶ μέχρι τοῦ σφετέρου διατειχίσματος, πόαν εἴ τινα εὕροιεν ἢ φυλλάδα χλωράν, νεμόμενοι. καὶ τοὺς ἀποψύχοντας ὁ Λεύκιος ἐς τάφρους ἐπιμήκεις κατώρυσσεν, ἵνα μήτε καιομένων ἐπίδηλον τοῖς ἐχθροῖς γένοιτο, μήτε σηπομένων ἀτμὸς καὶ νόσος.", "st": "5.35"}, {"sp": "N", "t": "ἐπεὶ δὲ οὔτε τοῦ λιμοῦ τι τέλος ἦν οὔτε τῶν θανάτων, ἀχθόμενοι τοῖς γιγνομένοις οἱ ὁπλῖται παρεκάλουν τὸν Λεύκιον αὖθις ἀποπειρᾶσαι τῶν τειχῶν, ὡς διακόψοντες αὐτὰ πάντως. ὁ δὲ τὴν ὁρμὴν ἀποδεξάμενος, “οὐκ ἀξίως,” ἔφη, “πρῴην τῆς παρούσης ἀνάγκης ἠγωνισάμεθα,” καὶ νῦν ἢ παραδιδόναι σφᾶς ἢ τοῦτο χεῖρον ἡγουμένους θανάτου μάχεσθαι μέχρι θανάτου. δεξαμένων δὲ προθύμως ἁπάντων καὶ, ἵνα μή τις ὡς ἐν νυκτὶ πρόφασις γένοιτο, κατὰ φῶς ἄγειν σφᾶς κελευόντων, ὁ Λεύκιος ἦγε πρὸ ἡμέρας. σίδηρόν τε τειχομάχον εἶχον τολὺν καὶ κλίμακας ἐς εἴδη πάντα διεσκευασμένας. ἐφέρετο δὲ καὶ τάφρων ἐγχωστήρια ὄργανα καὶ πύργοι πτυκτοί, σανίδας ἐς τὰ τείχη μεθιέντες, καὶ βέλη παντοῖα καὶ λίθοι, καὶ γέρρα τοῖς σκόλοψιν ἐπιρριπτεῖσθαι. προσπεσόντες δὲ μεθ’ ὁρμῆς βιαίου τὴν τάφρον ἐνέχωσαν καὶ τοὺς σταυροὺς ὑπερέβησαν καὶ τοῖς τείχεσι προσελθόντες οἱ μὲν ὑπώρυσσον, οἱ δὲ τὰς κλίμακας ἐπῆγον, οἱ δὲ τοὺς πύργους· ἐνεχείρουν τε ὁμοῦ καὶ ἠμύνοντο λίθοις καὶ τοξεύμασι καὶ μολυβδαίναις σὺν πολλῇ θανάτου καταφρονήσει. καὶ τάδε ἐγίγνετο κατὰ μέρη πολλά· ἐπειδὴ δέ τινας … ἐς πολλὰ διαιρουμένοις τοῖς πολεμίοις ἀσθενέστερα πάντα ἦν.", "st": "5.36"}, {"sp": "N", "t": "Ἐκταθεισῶν δέ που τῶν σανίδων ἐς τὸ τεῖχος, βία τότε μάλιστα ἐπικίνδυνος ἦν τῶν Λευκιανῶν ἐπὶ ταῖς σανίσι μαχομένων, καὶ βέλη πλάγια πάντοθεν ἦν ἐς αὐτοὺς καὶ ἀκόντια. ἐβιάσαντο δὲ ὅμως καὶ ἐς τὸ τεῖχος ἐξήλαντο ὀλίγοι, καὶ αὐτοῖς εἵποντο ἕτεροι· καὶ τάχα ἄν τι ἐξείργαστο αὐτοῖς μετὰ ἀπονοίας, εἰ μή, γνωσθέντος οὐ πολλὰ εἶναι τὰ τοιαῦτα μηχανήματα, οἱ ἄριστοι τῶν Καίσαρος ἐφεδρειῶν ἀκμῆτες ἐπήγοντο κεκμηκόσι. τότε γὰρ δὴ τῶν τειχῶν αὐτοὺς κατήρειψαν καὶ τὰ μηχανήματα συνέτριψαν καὶ ἔβαλλον ἄνωθεν ἤδη σὺν καταφρονήσει. τοῖς δὲ τὰ μὲν ὅπλα καὶ τὰ σώματα ὅλα συνεκέκοπτο, καὶ βοὴ σφᾶς ἐπελελοίπει, παρέμενον δ’ ὅμως τῇ προθυμίᾳ. ὡς δὲ καὶ τὰ νεκρὰ τῶν ἐπὶ τοῦ τείχους ἀνῃρημένων ἐσκυλευμένα κάτω διερριπτεῖτο, τὴν ὕβριν οὐκ ἔφερον, ἀλλὰ ἀνετρέποντο ὑπὸ τῆς ὄψεως, καὶ μικρὸν ἔστησαν ἀποροῦντες ὥσπερ ἐν τοῖς γυμνικοῖς ἀγῶσιν οἱ διαναπαυόμενοι. ὧδε δὲ αὐτοὺς ἔχοντας ἐλεῶν ὁ Λεύκιος ἐκάλει τῇ σάλπιγγι ἀναχωρεῖν. ἡσθέντων δὲ τῶν Καίσαρος ἐπὶ τῷδε καὶ τὰ ὅπλα παταγησάντων οἷον ἐπὶ νίκῃ, ἐρεθισθέντες οἱ τοῦ Λευκίου τὰς κλίμακας αὖθις ἁρπάσαντες (οὐ γὰρ ἔτι πύργους εἶχον) ἔφερον ἐς τὰ τείχη μετὰ ἀπονοίας, οὐδὲν ἔτι βλάπτοντες· οὐ γὰρ ἐδύναντο. περιθέων δ’ αὐτοὺς ὁ Λεύκιος ἐδεῖτο μὴ ψυχομαχεῖν ἔτι καὶ οἰμῴζοντας ἀπῆγεν ἄκοντας.", "st": "5.37"}, {"sp": "N", "t": "τὸ μὲν δὴ τέλος τῆσδε τῆς τειχομαχίας, ἐκθυμοτάτης γενομένης, ἐς τοῦτο ἐτελεύτα· ὁ δὲ Καῖσαρ, ἵνα μὴ αὖθις ἐπιτολμήσειαν οἱ πολέμιοι τοῖς τείχεσι, τὴν στρατιάν, ὅση τοῖς γιγνομένοις ἐφήδρευε, παρ’ αὐτὸ τὸ τεῖχος ἵδρυσε καὶ ἐδίδαξεν ἀναπηδᾶν ἐς τὸ τεῖχος ἄλλους ἀλλαχοῦ κατὰ σύνθημα σάλπιγγος· συνεχῶς τε ἀπεπήδων οὐδενὸς ἐπείγοντος, ἵνα διδαχή τε σφίσι καὶ φόβος εἴη τοῖς πολεμίοις. ἀθυμία δὲ ἐπεῖχε τοὺς τοῦ Λευκίου, καί, ὅπερ ἐν τοῖς τοιούτοις εἴωθε γίγνεσθαι, τῆς φυλακῆς οἱ φύλακες ἠμέλουν· ἐκ δὲ τῆς ἀμελείας αὐτομολίαι πολλῶν ἐγίγνοντο, καὶ οὐχ οἱ ἀφανέστεροι τοῦτο μόνοι, ἀλλὰ καὶ τῶν ἡγεμονικῶν τινες ἔδρων. ἐνεδίδου τε ὁ Λεύκιος ἤδη πρὸς διαλύσεις ἐλέῳ τοσοῦδε πλήθους ἀπολλυμένου, ἐχθρῶν δέ τινων Καίσαρος περὶ σφῶν δεδιότων ἔτι ἐπεῖχεν. ὡς δὲ ὁ Καῖσαρ ὤφθη τοὺς αὐτομόλους φιλανθρώπως ἐκδεχόμενος καὶ πλείων ὁρμὴ πᾶσιν ἐς τὰς διαλύσεις ἐγίγνετο, δέος ἥπτετο τοῦ Λευκίου, μὴ ἀντιλέγων ἐκδοθείη.", "st": "5.38"}, {"sp": "N", "t": "γενομένης οὖν τινος ες τοῦτο πείρας καὶ ἐλπίδος οὐκ ἀηδοῦς, τὸν στρατὸν συναγαγὼν ἔλεξεν ὧδε· “γνώμη μὲν ἦν μοι τὴν πάτριον ὑμῖν ἀποδοῦναι πολιτείαν, ὦ συστρατιῶται, τυρραννίδα τὴν τῶν τριῶν ἀνδρῶν ἀρχὴν καὶ οὐδ’, ἐφ’ ᾗ συνέστη προφάσει, Κασσίου καὶ Βρούτου τεθνεώτων διαλυθεῖσαν. Λεπίδου γὰρ τὸ μέρος τῆς ἀρχῆς ἀφῃρημένου καὶ Ἀντωνίου πορρωτάτω χρήματα συλλέγοντος, εἷς οὗτος ἅπαντα πρὸς τὴν ἑαυτοῦ γνώμην διῴκει, τὰ δὲ πάτρια Ῥωμαίοις πρόσχημα μόνον ἦν καὶ γέλως. ἅπερ ἐγὼ μεταβάλλειν ἐς τὴν ἄνωθεν ἐλευθερίαν τε καὶ δημοκρατίαν ἐπινοῶν ἠξίουν τῶν ἐπινικίων διαδοθέντων ἐκλυθῆναι τὴν μοναρχίαν. ἐπεὶ δὲ οὐκ ἔπειθον, ἐπειρώμην ἐπὶ τῆς ἐμῆς ἀρχῆς καταναγκάσαι. ὁ δέ με τῷ στρατῷ διέβαλλε, κωλύειν τὰς κληρουχίας ἐλέῳ τῶν γεωργῶν· καὶ τὴν διαβολὴν ἐγὼ τήνδε ἠγνόησα ἐπὶ πλεῖστον. ἀλλ’ οὐδὲ ἐπιγνοὺς ἐπίστευσά τινα πιστεύσειν, ὁρῶντα τοὺς οἰκιστὰς καὶ παρ’ ἐμοῦ δεδομένους, οἳ μεριεῖν ἔμελλον ὑμῖν τὰς κληρουχίας. ἀλλὰ ἐδημαγώγησε γάρ τινας ἡ διαβολή, καὶ πρὸς ἐκεῖνον ᾤχοντο πολεμήσοντες ὑμῖν, ὡς νομίζουσι, σὺν χρόνῳ δ’ εἴσονται στρατευσάμενοι καθ’ αὑτῶν. ὑμῖν δ’ ἐγὼ μαρτυρῶ μὲν ἑλομένοις τὰ ἀμείνονα καὶ ὑπὲρ δύναμιν κακοπαθήσασιν, ἡττήμεθα δὲ οὐχ ὑπὸ τῶν πολεμίων, ἀλλὰ τοῦ λιμοῦ, ᾧ δὴ καὶ πρὸς τῶν ἡμετέρων στρατηγῶν ἐγκαταλελείμμεθα. ἐμοὶ μὲν δὴ καλῶς εἶχεν ἀγωνίσασθαι μέχρι τοῦ τελευταίου δαίμονος ὑπὲρ τῆς πατρίδος· καλὸν γάρ μοι τὸν ἔπαινον ἐπὶ τῇ γνώμῃ καὶ τὸ τέλος ἐποίει· οὐχ ὑφίσταμαι δὲ δι’ ὑμᾶς, οὓς τῆς ἐμῆς προτίθημι εὐκλείας. πέμψω δὴ πρὸς τὸν κεκρατηκότα καὶ δεήσομαι ἐμοὶ μὲν ἀντὶ πάντων ὑμῶν εἰς ὃ θέλει καταχρήσασθαι μόνῳ, ὑμῖν δὲ ἀντ’ ἐμοῦ ἀμνηστίαν δοῦναι, πολίταις τε οὖσιν αὐτοῦ καὶ στρατιώταις ποτὲ γενομένοις καὶ οὐδὲ νῦν ἀδικοῦσιν οὐδὲ πολεμήσασιν ἄνευ καλῆς αἰτίας οὐδὲ ἡσσημένοις πολέμῳ μᾶλλον ἢ λιμῷ.”", "st": "5.39"}, {"sp": "N", "t": "ὁ μὲν οὕτως εἶπε καὶ εὐθὺς ἔπεμπε τρεῖς ἐπιλεξάμενος ἐκ τῶν ἀρίστων· ἡ δὲ πληθὺς ἀνῴμωζον, οἱ μὲν ἑαυτῶν χάριν, οἱ δὲ τοῦ στρατηγοῦ, γνώμῃ μὲν ὁμοῦ σφισιν ἀρίστου καὶ δημοκρατικοῦ φανέντος, ὑπὸ δ’ ἐσχάτης ἀνάγκης ἡττημένου. οἱ δὲ τρεῖς ἐντυχόντες τῷ Καίσαρι ἀνεμίμνῃσκον τοῦ γένους τῶν στρατῶν ἑνὸς ἑκατέροις ὄντος καὶ στρατειῶν ὁμοῦ γενομένων καὶ φιλίας τῶν ἐπιφανῶν καὶ ἀρετῆς προγόνων οὐκ ἐς ἀνήκεστον τὰς διαφορὰς προαγαγόντων· ὅσα τε εἰκὸς ἦν ἄλλα ἐπαγωγά, τούτοις ὅμοια, ἔλεγον. ὁ δὲ Καῖσαρ εἰδὼς τῶν πολεμίων τοὺς μὲν ἀπειροπολέμους ἔτι, τοὺς δὲ κληρούχους γεγυμνασμένους ἔφη τεχνάζων τοῖς ὑπ’ Ἀντωνίῳ στρατευσαμένοις διδόναι τὴν ἀμνηστίαν, ὡς χάριν ἐκείνῳ φέρων, τοὺς δ’ ἄλλους ἐπιτρέπειν σφᾶς ἑαυτῷ προσέτασσεν. ταῦτα μὲν εἶπεν ἅπασιν ἰδία δὲ ἕνα τῶν τριῶν ἀπολαβών, Φούρνιον, ἐς μείζονα φιλανθρωπίαν ἐπήλπισε τοὺς περὶ Λεύκιον καὶ τοὺς ἄλλους χωρὶς τῶν ἰδίων ἐχθρῶν ἑαυτοῦ.", "st": "5.40"}, {"sp": "N", "t": "οἵδε οὖν οἱ τοῦ Καίσαρος ἐχθροί, τὴν ἰδίᾳ γενομένην ἔντευξιν τοῦ Φουρνίου ὑπονοοῦντες ἐπὶ σφίσι γενέσθαι, αὐτόν τε τὸν Φούρνιον ἐλοιδόρουν ἐπανελθόντα καὶ τὸν Λεύκιον ἠξίουν ἢ σπονδὰς αὖθις αἰτεῖν ὁμοίας ἅπασιν ἢ πολεμεῖν μέχρι θανάτου· οὐ γὰρ ἴδιόν τινι τὸν πόλεμον, ἀλλὰ κοινὸν ὑπὲρ τῆς πατρίδος γεγονέναι. καὶ ὁ Λεύκιος ἐπῄνει μὲν ἐλεῶν ἄνδρας ὁμοτίμους καὶ πέμψειν ἔλεγεν ἑτέρους, οὐδένα δὲ εἰπὼν ἀμείνονα ἔχειν ἑαυτοῦ, εὐθὺς ἄνευ κήρυκος ᾔει, προθεόντων αὐτοῦ δρόμῳ τῶν ἀπαγγελούντων Καίσαρι κατιέναι Λεύκιον. ὁ δὲ αὐτίκα ὑπήντα. ἑωρῶντο οὖν ἀλλήλοις ἤδη μετὰ τῶν φίλων καὶ περιφανεῖς ἦσαν ἀπὸ τῶν σημείων καὶ τῆς στολῆς οὔσης ἑκατέρῳ στρατηγικῆς. καὶ ὁ Λεύκιος ἀποθέμενος τοὺς φίλους ᾔει σὺν δύο ῥαβδούχοις μόνοις, ἐπιδεικνὺς ἅμα τὴν γνώμην ἀπὸ τοῦ σχήματος· καὶ ὁ Καῖσαρ συνεὶς ἀντεμιμεῖτο ἐς δεῖγμα καὶ ὅδε τῆς εἰς τὸν Λεύκιον εὐνοίας ἐσομένης· ὡς δὲ καὶ σπεύδοντα εἶδε τὸν Λεύκιον παρελθεῖν ἐς τὸ Καίσαρος χαράκωμα, ἵνα καὶ τῷδε φαίνοιτο ἑαυτὸν ἐπιτρέπων ἤδη, προλαβὼν ὁ Καῖσαρ ἐξῆλθε τοῦ χαρακώμακος, ἵνα ἐλεύθερον εἴη τῷ Λευκίῳ βουλεύεσθαί τε καὶ κρίνειν ἔτι περὶ αὑτοῦ. τοιάδε ἀλλήλοις προσιόντες ἀπό τε τῆς στολῆς καὶ τῶν σχημάτων προαπεδείκνυντο.", "st": "5.41"}, {"sp": "N", "t": "ὡς δὲ ἐπὶ τὴν τάφρον ἀφίκοντο, προσηγόρευσάν τε ἀλλήλους καὶ ὁ Λεύκιος ἔφη·", "st": "5.42"}, {"sp": "N", "t": "“εἰ μὲν ξένος ὢν ἐπολέμησα, ὦ Καῖσαρ, αἰσχρὰν ἂν τὴν τοιαύτην ἧσσαν ἡγούμην καὶ αἰσχίονα ἔτι τὴν παράδοσιν· καὶ τῆσδε τῆς αἰσχύνης εἶχον ἀπαλλαγὴν εὔκολον παρ’ ἐμαυτοῦ. ἐπεὶ δὲ πολίτῃ διηνέχθην καὶ ὁμοτίμῳ καὶ ὑπὲρ τῆς πατρίδος, οὐκ αἰσχρὸν ἡγοῦμαι μετὰ τοιᾶσδε προφάσεως ὑπὸ τοιοῦδε ἡσσῆσθαι. καὶ τάδε λέγω οὐ παραιτούμενος παθεῖν, ὅ τι θέλοις (διὰ γάρ σοι τοῦτο ἐς τὸ στρατόπεδον τὸ σὸν ἄνευ σπονδῶν ἱέμην), ἀλλ’ ἵνα τοῖς ἄλλοις αἰτήσω συγγνώμην δικαίαν τε καὶ τοῖς σοῖς πράγμασι συμφέρουσαν. δεῖ δέ με τοῦτο ἐπιδεικνύντα διελεῖν τὸν λόγον ὑπὲρ τε ἐκείνων καὶ ὑπὲρ ἐμαυτοῦ, ἵνα μόνον ἐμὲ τῶν γεγονότων αἴτιον ἐπιγνοὺς εἰς ἐμὲ τὴν ὀργὴν συναγάγῃς. μὴ νομίσῃς δὲ ἐλεγχθήσεσθαι μετὰ παρρησίας (ἄκαιρον γάρ), ἀλλὰ μετὰ ἀληθείας, ἧς οὐκ ἔνι μοι χωρὶς εἰπεῖν.", "st": "5.42"}, {"sp": "N", "t": "“ἐγὼ τὸν πρὸς σὲ πόλεμον ἠράμην, οὐχ ἵνα σε καθελὼν διαδέξωμαι τὴν ἡγεμονίαν, ἀλλ’ ἵνα τὴν ἀριστοκρατίαν ἀναλάβω τῇ πατρίδι, λελυμένην ὑπὸ τῆς τῶν τριῶν ἀρχῆς, ὡς οὐδ’ ἂν αὐτὸς ἀι τείποις· καὶ γὰρ ὅτε συνίστασθε αὐτήν, ὁμολογοῦντες εἶναι παράνομον, ὡς ἀναγκαίαν καὶ πρόσκαιρον ἐτίθεσθε, Κασσίου καὶ Βρούτου περιόντων ἔτι καὶ ὑμῶν ἐκείνοις οὐ δυναμένων συναλλαγῆναι. ἀποθανόντων δὲ ἐκείνων, οἳ τὸ τῆς στάσεως κεφάλαιον ἦσαν, καὶ τῶν ὑπολοίπων εἴ τινα λείψανα ἔστιν, οὐ τῇ πολιτείᾳ πολεμούντων, ἀλλὰ ὑμᾶς δεδιότων, ἐπὶ δὲ τούτῳ καὶ τῆς πενταετίας παριούσης, ἀνακῦψαι τὰς ἀρχὰς ἐπὶ τὰ πάτρια ἠξίουν, οὐ προτιμῶν οὐδὲ τὸν ἀδελφὸν τῆς πατρίδος, ἀλλ’ ἐλπίζων μὲν ἐπανελθόντα πείσειν ἑκόντα, ἐπειγόμενος δὲ ἐπὶ τῆς ἐμῆς ἀρχῆς γενέσθαι. καὶ εἰ κατῆρξας σύ, μόνος ἂν καὶ τὴν δόξαν εἶχες. ἐπεὶ δὲ δή σε οὐκ ἔπειθον, ᾤμην ἐλθὼν ἐπὶ Ῥώμην καὶ ἀναγκάσαι, πολίτης τε ὢν καὶ γνώριμος καὶ ὕπατος. αἱ μὲν αἰτίαι, δι’ ἃς ἐπολέμησα, αὗται μόναι, καὶ οὔτε ὁ ἀδελφὸς οὔτε Μάνιος οὔτε Φουλβία, οὔτε ἡ κληρουχία τῶν ἐν Φιλίπποις πεπολεμηκότων οὔτε ἔλεος τῶν γεωργῶν τὰ κλήματα ἀφαιρουμένων, ἐπεὶ κἀγὼ τοῖς τοῦ ἀδελφοῦ τέλεσιν οἰκιστὰς ἔδωκα, οἱ τὰ τῶν γεωργῶν ἀφαιρούμενοι τοῖς στρατευσαμένοις διένεμον. ἀλλά με σὺ τήνδε τὴν διαβολὴν αὐτοῖς διέβαλλες, τὴν αἰτίαν τοῦ πολέμου μεταφέρων ἐπὶ τὴν κληρουχίαν ἀπὸ σαυτοῦ, καὶ τῷδε μάλιστα αὐτοὺς ἑλὼν ἐμοῦ κεκράτηκας· ἀνεπείσθησαν γὰρ πολεμεῖσθαί τε ὑπ’ ἐμοῦ καὶ ἀμύνεσθαί με ἀδικοῦντα. τεχνάζειν μὲν δή σε ἔδει πολεμοῦντα· νικήσαντα δέ, εἰ μὲν ἐχθρὸς εἶ τῆς πατρίδος, κἀμὲ ἡγεῖσθαι πολέμιον, ἃ ἔδοξα συνοίσειν αὐτῇ, βουληθέντα μέν, οὐ δυνηθέντα δὲ διὰ λιμόν.", "st": "5.43"}, {"sp": "N", "t": "“λέγω δὲ ταῦτα ἐγὼ ἐγχειρίζων μὲν ἐμαυτόν σοι, καθάπερ εἶπον, εἰς ὅ τι θέλοις, ὑποδεικνὺς δέ, οἷα καὶ πρότερον καὶ νῦν ἐφρόνησα περὶ σοῦ καὶ φρονῶν ἔτι μόνος ἀφικόμην. καὶ περὶ μὲν ἐμοῦ τοσαῦτα· περὶ δὲ τῶν φίλων καὶ τοῦ στρατοῦ παντός, εἰ μὲν οὐχ ὑποπτεύσεισ’ με λέγοντα, συμβουλεύσω τὰ σοὶ μάλιστα ὠφελιμώτατα, μηδὲν δεινὸν αὐτοὺς ἐργάσασθαι διὰ τὴν ἐμὴν καὶ σὴν φιλονικίαν, μηδὲ ἄνθρωπον ὄντα καὶ τύχῃ χρώμενον, οὐ βεβαίῳ πράγματι, κωλῦσαι τοὺς κινδυνεύειν ἐν τύχαις ἢ χρείαις ἐθελήσοντάς ποτε ὑπὲρ σοῦ, μαθόντας ἐκ τοῦδε τοῦ σοῦ νόμου δυσέλπιστον σῴζεσθαι μὴ κατορθοῦσιν. εἰ δὲ ὕποπτος ἢ ἄπιστος ἐχθροῦ πᾶσα συμβουλή, οὐκ ὀκνῶ καὶ παρακαλεῖν σε μὴ τοὺς φιλοὺς τίνυσθαι τῆς ἐμῆς ἁμαρτίας καὶ τύχης, ἀλλ’ εἰς ἐμὲ συναγαγεῖν πάντα, τὸν πάντων αἴτιον. ἀφ’ ἧς δὴ γνώμης αὐτοὺς ὑπελιπόμην, ἵνα μὴ δόξαιμι, σοὶ τάδε λέγων ἐκείνων ἀκουόντων, ὑπὲρ ἐμαυτοῦ τεχνάζων εἰπεῖν.”", "st": "5.44"}, {"sp": "N", "t": "τοιαῦτα δὲ εἰπόντος τοῦ Λευκίου καὶ σιωπήσαντος ὁ Καῖσαρ ἔλεξεν·", "st": "5.45"}, {"sp": "N", "t": "“ἄσπονδον μέν σε κατιόντα πρὸς ἐμὲ ὁρῶν, ὦ Λεύκιε, ὑπήντησα τῶν ἐμῶν ἐρυμάτων ἔτι ἐκτὸς ὄντι κατὰ σπουδήν, ἵνα ἔτι κύριος ὢν σεαυτοῦ βουλεύοιο καὶ λέγοις καὶ πράττοις, ἃ νομίζεις σοι συνοίσειν. ἐπεὶ δ’, ὅπερ ἐστὶ τῶν ἀδικεῖν ὁμολογούντων, σαυτὸν ἡμῖν ἐπιτρέπεις, οὐδὲν ἔτι δέομαι διελέγχειν, ὅσα σὺν τέχνῃ μου κατεψεύσω. ἐξ ἀρχῆς δέ με βλάψειν ἑλόμενος καὶ νῦν ἔβλαψας. σπονδὰς γάρ μοι τιθέμενος ἔτυχες ἂν ἠδικημένου καὶ νενικηκότος· ἄσπονδον δὲ σαυτόν τε καὶ τοὺς φίλους ἐπιτρεπων ἡμῖν καὶ τὸν στρατόν, ἀφαιρῇ μὲν πᾶσαν ὀργήν, ἀφαιρῇ δὲ καὶ τὴν ἐξουσίαν, ἣν σπενδόμενος ἂν ἔδωκας ὑπ’ ἀνάγκης. συμπέπλεκται γὰρ οἷς ἄξιον ὑμᾶς παθεῖν, τὸ προσῆκον ὧν ἐμὲ δίκαιόν ἐστι ποιεῖν· ὃ δὴ προτιμήσω διά τε τοὺς θεοὺς καὶ δι’ ἐμαυτὸν καὶ διὰ σέ, ὦ Λεύκιε, καὶ οὐ ψεύσω σε τῆς προσδοκίας, ἣν ἔχων περὶ ἐμαυτοῦ κατελήλυθας.”", "st": "5.45"}, {"sp": "N", "t": "ταῦτα μὲν ἔλεξαν ἀλλήλοις, ὡκ ἐκ τῶν ὑπομνημάτων ἦν ἐς τὸ δυνατὸν τῆσδε τῆς φωνῆς μεταβαλεῖν τεκμαιρομένῳ τῆς γνώμης τῶν λελεγμένων. καὶ διεκρίθησαν, ὁ μὲν Καῖσαρ ἐν ἐπαίνῳ καὶ θαύματι τὸν Λεύκιον ἔχων, οὐδὲν ὡς ἐν συμφοραῖς ἀγεννὲς οὐδ’ ἀσύνετον εἰπόντα, ὁ δὲ Λεύκιος τὸν Καίσαρα τοῦ τε ἤθους καὶ βραχυλογίας. οἱ λοιποὶ δ’ ἐτεκμαίροντο τῶν εἰρημένων ἐκ τῆς ὄψεως ἑκατέρων.", "st": "5.45"}, {"sp": "N", "t": "καὶ ὁ Λεύκιος ἔπεμπε τοὺς χιλάρχους τὸ σύνθημα τῷ στρατῷ ληψομένους παρὰ τοῦ Καίσαρος· οἱ δὲ ἔφερον αὐτῷ τὸν ἀριθμὸν τοῦ στρατοῦ, καθὰ καὶ νῦν ἔθος ἐστὶ τὸν αἰτοῦντα τὸ σύνθημα χιλίαρχον ἐπιδιδόναι τῷ βασιλεῖ βιβλίον ἐφήμερον τοῦ ἀριθμοῦ τοῦ παρόντος. οἱ μὲν δὴ τὸ σύνθημα λαβόντες τὰς φυλακὰς ἔτι διὰ χειρὸς εἶχον, οὕτω κελεύσαντος αὐτοῦ Καίσαρος, νυκτοφυλακεῖν ἑκατέρους τὰ ἴδια· ἅμα δὲ ἡμέρᾳ ὁ μὲν Καῖσαρ ἔθυεν, ὁ δὲ Λεύκιος αὐτῷ τὸν στρατὸν ἔπεμπε, τὰ μὲν ὅπλα φέροντα, ἐσκευα σμένον δ’ ὡς ἐν ὁδοιπορίᾳ. οἱ δὲ τὸν Καίσαρα πόρρωθεν ὡς αὐτοκράτορα ἠσπάσαντο καὶ ἔστησαν ἐν μέρει κατὰ τέλος, οὗ προσέταξεν ὁ Καῖσαρ, ἐφ’ ἑαυτῶν, οἵ τε κληροῦχοι καὶ οἱ νεοστράτευτοι κεχωρισμένοι. ὁ δὲ Καῖσαρ ἐκτελεσθείσης τῆς θυσίας στεψάμενος δάφνῃ, συμβόλῳ νίκης, προυκάθητο ἐπὶ βήματος καὶ προσέταξε μὲν ἅπασι θέσθαι τὰ ὅπλα, ἔνθα εἱστήκεσαν, θεμένων δὲ τοὺς κληρούχους, ἐκέλευσεν ἐγγυτέρω προσελθεῖν, διεγνωκὼς ἄρα ὀνειδίσαι τῆς ἀχαριστίας καὶ φοβῆσαι. προέγνωστο δὲ μέλλων ὧδε ποιήσειν, καὶ ὁ στρατὸς ὁ τοῦ Καίσαρος, εἴτε ἐξεπίτηδες, οἷα προδιδάσκονται πολλάκις, εἴτε ὑπὸ πάθους ὡς πρὸς οἰκείους ἄνδρας, ἀκρατεῖς τῆς δεδομένης σφίσι τάξεως γενόμενοι, προσιοῦσι τοῖς Λευκιανοῖς οἷα συνεστρατευμένοις ποτὲ περιχυθέντες ἠσπάζοντο καὶ συνέκλαιον καὶ τὸν Καίσαρα ὑπὲρ αὐτῶν παρεκάλουν καὶ οὔτε βοῶντες ἔτι ἐπαύοντο οὔτε συμπλεκόμενοι, κοινωνούντων ἑκατέροις τοῦ πάθους ἤδη καὶ τῶν νεοστρατεύτων· οὐδὲ ἦν τι διακεκριμένον ἔτι οὐδ’ εὔκριτον.", "st": "5.46"}, {"sp": "N", "t": "ὅθεν οὐδὲ ὁ Καῖσαρ ἔτι τῆς γνώμης ἐκράτει, ἀλλὰ μόλις τὴν βοὴν καταπαύσας εἶπε τοῖς ἰδίοις. “ὑμεῖς μέν, ὦ συστρατιῶται, οὕτως ἀεί μοι προσενήνεχθε ὡς μηδενὸς ἀτυχῆσαι παρ’ ἐμοῦ δύνασθαι· ἐγὼ δὲ τοὺς μὲν νεοστρατεύτους ὑπ’ ἀνάγκης ἐστρατεῦσθαι Λευκίῳ νομίζω, τουτωνὶ δὲ τῶν συνεστρατευμένων τε πολλάκις ὑμῖν καὶ νῦν ὑφ’ ὑμῶν σῳζομένων ἐπενόουν πυθέσθαι, τί παθόντες ἐξ ἡμῶν ἢ τίνος χάριτος οὐκ ἀξιωθέντες ἢ τί μεῖζον παρ’ ἑτέρου προσδοκῶντες ἐναντία ὅπλα ἤραντο καὶ ἐμοὶ καὶ ὑμῖν καὶ ἑαυτοῖς; ἃ γὰρ ἔκαμνον ἐγώ, πάντα ἦν ὑπὲρ τῆς κληρουχίας, ἧς τοῦ μέρους καὶ τούτοις μετῆν. καὶ εἰ συγχωρεῖτέ μοι, καὶ νῦν πεύσομαι.” οὐκ ἐπιτρεπόντων δέ, ἀλλὰ ἀπαύστως παρακαλούντων, “συγχωρῶ ὑμῖν, ὅσα βούλεσθε,” ἔφη, “καὶ ἀφείσθωσαν ἀπαθεῖς τῶν ἡμαρτημένων, ἂν ἐς τὸ μέλλον ὑμῖν ὅμοια φρονῶσιν.” ὑπισχνουμένων δ’ ἑκατέρων βοαί τε καὶ χάριτες ἦσαν ἐς τὸν Καίσαρα· καί τισιν αὐτῶν ἐπέτρεψέ τινας καὶ ὑποδέξασθαι, τὸ δὲ πλῆθος ἐκέλευε σκηνοῦν, ἔνθα περ εἱστήκεσαν, ἄπωθεν, ἕως ὁ Καῖσαρ αὐτοῖς πόλεις τε ἐς χειμασίαν καὶ τοὺς ἀπάξοντας ἐς τὰς πόλεις δοίη.", "st": "5.47"}, {"sp": "N", "t": "καθεζόμενος δ’ ἐπὶ τοῦ βήματος ἐκάλει τὸν Λεύκιον ἐκ τῆς Περυσίας μετὰ τῶν ἐν τέλει Ῥωμαίων. καὶ κατῄεσαν πολλοὶ μὲν ἀπὸ τῆς βουλῆς, πολλοὶ δὲ ἀπὸ τῶν καλουμένων ἱππέων, ἐν ὄψει πάντες οἰκτρᾷ καὶ ὀξείᾳ μεταβολῇ. ἅμα δὲ ἐξῄεσαν οὗτοι τῆς Περυσίας, καὶ φρουρὰ τὴν πόλιν περιέστη. ἐπεὶ δὲ ἀφίκοντο, Λεύκιον μὲν ὁ Καῖσαρ ἑαυτῷ παρεστήσατο, τῶν δὲ ἄλλων τοὺς μὲν οἱ φίλοι Καίσαρος, τοὺς δὲ οἱ λοχαγοὶ διέλαβον, προδεδιδαγμένοι πάντες ἐς τιμὴν ἀπάγειν ἅμα καὶ φυλακὴν ἄσημον. τοὺς δὲ Περυσίους ἀπὸ τοῦ τείχους παρακαλοῦντας ἐκέλευσεν ἥκειν, ἄνευ τῆς βουλῆς μόνης· καὶ ἐλθοῦσι συνέγνω. οἱ δὲ βουλευταὶ τότε μὲν φύλαξι παρεδόθησαν, μετ’ οὐ πολὺ δὲ ἀνῃρέθησαν, χωρὶς Αἰμιλίου Λευκίου, ὃς ἐν Ῥώμῃ δικάζων ἐπὶ τῷ φόνῳ Γαΐου Καίσαρος τὴν καταδικάζουσαν ἤνεγκε φανερῶς καὶ πάντας φέρειν ἐκέλευεν ὡς ἐκλυομένους μύσος.", "st": "5.48"}, {"sp": "N", "t": "τὴν δὲ Περυσίαν αὐτὴν ἐγνώκει μὲν ὁ Καῖσαρ ἐς διαρπαγὴν ἐπιτρέψαι τῷ στρατῷ, Κέστιος δέ τις αὐτῶν ὑπομαργότερος, ἐν Μακεδονίᾳ πεπολεμηκὼς καὶ ἐκ τοῦδε Μακεδονικὸν αὑτὸν ὀνομάζων, ἐνέπρησε τὴν οἰκίαν καὶ ἑαυτὸν ἐς τὸ πῦρ ἐνέβαλε, καὶ ἄνεμοι τὴν φλόγα ὑπολαβόντες περιήνεγκαν ἐκ ὅλην Περυσίαν, καὶ ἐνεπρήσθη χωρὶς τοῦ Ἡφαιστείου μόνου. τόδε μὲν δὴ τῇ Περυσίᾳ τέλος ἦν, δόξαν ἀρχαιότητος ἐχούσῃ καὶ ἀξιώσεως· ὑπὸ γὰρ Τυρρηνῶν πάλαι φασὶν αὐτὴν ἐν ταῖς πρώταις δυώδεκα πόλεσιν ἐν Ἰταλίᾳ γενέθαι. διὸ καὶ τὴν Ἥραν ἔσεβον, οἷα Τυρρηνοί· τότε δὲ ὅσοι τὰ λείψανα τῆς πόλεως διέλαχον, τὸν Ἥφαιστον σφίσιν ἔθεντο θεὸν εἶναι πάτριον ἀντὶ τῆς Ἥρας. τῆς δ’ ἐπιούσης ὁ μὲν Καῖσαρ ἐσπένδετο ἅπασιν, ὁ δὲ στρατὸς οὐκ ἐπαύετο ἐπί τισι θορυβῶν, ἕως ἀνῃρέθησαν· καὶ ἦσαν οἱ μάλιστα Καίσαρος ἐχθροί, Καννούτιός τε καὶ Γάιος Φλάυιος καὶ Κλώδιος ὁ Βιθυνικὸς καὶ ἕτεροι. τοῦτο μὲν δὴ τέλος ἦν τῆς ἐν Περυσίᾳ Λευκίου πολιορκίας, καὶ ὁ πόλεμος ὧδε ἐξελέλυτο, χαλεπώτατός τε καὶ χρόνιος ἐλπισθεὶς ἔσεσθαι τῇ Ἰταλίᾳ.", "st": "5.49"}, {"sp": "N", "t": "καὶ γὰρ Ἀσίνιος αὐτίκα καὶ Πλάγκος καὶ Οὐεντίδιος καὶ Κράσσος καὶ Ἀτήιος καὶ ὅσοι τῆσδε τῆς γνώμης ὄντες ἕτεροι στρατὸν εἶχον οὐκ εὐκαταφρόνητον, ἀλλ’ εἰς τρισκαίδεκα τέλη γεγυμνασμένα καὶ ἱππέας ἑξακισχιλίους ἐπὶ πεντακοσίοις, ἡγούμενοι τὸ κεφάλαιον τοῦ πολέμου Λεύκιον γενονέναι ἐπὶ θάλασσαν ᾔεσαν, ἕτερος ἑτέρας ὁδούς, οἱ μὲν ἐς Βρεντέσιον, οἱ δ’ ἐπὶ Ῥαβέννης, οἱ δ’ ἐς Τάραντα καὶ οἱ μὲν ἐς Μοῦρκον ἢ Ἀηνόβαρβον, οἱ δὲ ἐς Ἀντώνιον, διωκόντων αὐτοὺς τῶν Καίσαρος φίλων καὶ σπονδὰς προτεινόντων καὶ οὐκ ἐθέλουσιν ἐνοχλούντων τὰ πεζὰ μάλιστα· ὧν δὴ καὶ μόνων Ἀγρίππας ἔπεισε μεταθέσθαι δύο τέλη Πλάγκου, ἀποληφθέντα ἐν Καμερίᾳ. ἔφευγε δὲ καὶ Φουλβία μετὰ τῶν τέκνων ἐς Δικαιάρχειαν καὶ ἀπὸ Δικαιαρχείας ἐς τὸ Βρεντέσιον, μετὰ τρισχιλίων ἱππέων οἳ αὐτῇ παρὰ τῶν στρατηγῶν πομποὶ ἀπεστάλησαν. ἐν δὲ τῷ Βρεντεσίῳ νεῶν πέντε μακρῶν ἐκ Μακεδονίας οἱ μεταπέμπτων γενομένων ἐπιβᾶσα ἀνήγετο· καὶ αὐτῇ Πλάγκος συνέπλει, τὸν ἔτι λοιπὸν αὑτοῦ στρατὸν ἐκλιπὼν ὑπὸ δειλίας. οἱ δὲ Οὐεντίδιον σφῶν εἵλοντο ἄρχειν. Ἀσίνιος δὲ Ἀηνοβάρβῳ συνετίθετο φιλίαν εἶναι πρὸς Ἀντώνιον· καὶ ἐπέστελλον ἄμφω τάδε τῷ Ἀντωνίῳ καὶ ἀποβάσεις αὐτῷ καὶ ἀγορὰν ὡς αὐτίκα ἥξοντι εὐτρέπιζον ἀνὰ τὴν Ἰταλίαν.", "st": "5.50"}, {"sp": "N", "t": "ἄλλῳ δ’ Ἀντωνίου στρατῷ πολλῷ περὶ Ἄλπεις, οὗ Φούφιος Καληνὸς ἡγεῖτο, ὁ Καῖσαρ ἐπεβούλευεν, ἤδη μὲν τὸν Ἀντώνιον ὑπονοῶν, ἐλπίζων δὲ ἢ φίλῳ ἔτι ὄντι φυλάξειν ἢ πολεμοῦντος μεγάλην ἰσχὺν προσλήψεσθαι. διαμέλλοντος δὲ ὅμως ἔτι αὐτοῦ καὶ τὸ εὐπρεπὲς περιορωμένου, ὁ Καληνὸς ἐτελεύτησε· καὶ ὁ Καῖσαρ, ὡς ἐς ἀμφότερα πρόφασιν εὑρών, ᾔει καὶ παρελάμβανε τόν τε στρατὸν καὶ τὴν Κελτικὴν ἐπ’ αὐτῷ καὶ Ἰβηρίαν, καὶ τάσδε οὔσας ὑπὸ Ἀντωνίῳ, Φουφίου τοῦ παιδὸς Καληνοῦ καταπλαγέντος τε αὐτὸν καὶ παραδόντος ἅπαντα ἀμαχεί.", "st": "5.51"}, {"sp": "N", "t": "ὁ μὲν δὴ Καῖσαρ ἑνὶ τῷδε ἔργῳ ἕνδεκα τέλη στρατοῦ καὶ χώρας τοσάσδε λαβὼν τοὺς ἡγεμόνας αὐτῶν παρέλυε τῆς ἀρχῆς καὶ ἰδίους ἐπιστήσας ἐς Ῥώμην ἀνέστρεφεν· ὁ δὲ Ἀντώνιος χειμῶνος μὲν ἔτι τοὺς πρέσβεις κατεῖχε τοὺς ἀπὸ τῶν κληρουχιῶν πρὸς αὐτὸν ἐλθόντας, ἔτι ἐπικρύπτων, ἃ ἐφρόνει, ἦρι δ’ ἐκ μὲν Ἀλεξανδρείας ἐς Τύρον ὥδευεν, ἐκ δὲ Τύρου διαπλέων ἐπὶ Κύπρου καὶ Ῥόδου καὶ Ἀσίας ᾔσθετο τῶν ἐν τῇ Περυσίᾳ γεγονότων καὶ τὸν ἀδελφὸν ἐμέμφετο καὶ Φουλβίαν καὶ μάλιστα πάντων Μάνιον. Φουλβίαν μὲν οὖν εὗρεν ἐν Ἀθήναις, ἐκ Βρεντεσίου φυγοῦσαν· Ἰουλίαν δ’ αὐτῷ τὴν μητέρα Πομπήιος, ἐς αὐτὸν διαφυγοῦσαν, ἔπεμπεν ἐκ Σικελίας ἐπὶ νεῶν μακρῶν, καὶ παρέπεμπον αὐτὴν οἱ τῶν ἀμφὶ τὸν Πομπήιον ἄριστοι, Λεύκιός τε Λίβων, ὁ κηδεστὴς τοῦ Πομπηίου, καὶ Σατουρνῖνος καὶ ἕτεροι, ὅσοι χρῄζοντες τῆς Ἀντωνίου μεγαλοπραγίας ἠξίουν αὐτὸν συναλλαγέντα Πομπηίῳ σύμμαχον ἐπὶ Καίσαρι λαβεῖν Πομπήιον. ὁ δὲ αὐτοῖς ἀπεκρίνατο χάριν μὲν ἐπὶ τῇ μητρὶ γιγνώσκειν Πομπηίῳ καὶ ἀποτίσειν ἐν χρόνῳ, αὐτὸς δέ, εἰ μὲν πολεμοίη Καίσαρι, χρήσεσθαι Πομπηίῳ συμμάχῳ, εἰ δ’ ἐμμένοι τοῖς πρὸς αὑτὸν ὡμολογημένοις ὁ Καῖσαρ, πειράσεσθαι καὶ Πομπηίον Καίσαρι συναλλάξαι.", "st": "5.52"}, {"sp": "N", "t": "ὁ μὲν ὧδε ἀπεκρίνατο, ὁ δὲ Καῖσαρ ἐς Ῥώμην ἀπὸ Κελτῶν ἐπανιὼν ᾔσθετο μὲν τῶν ἐς Ἀθήνας διαπεπλευκότων, τὸ δὲ τῆς ἀποκρίσεως ἀκριβὲς ἄρα οὐκ εἰδὼς ἐξώτρυνε τοὺς κληρούχους ἐπὶ τὸν Ἀντώνιον ὡς κατάγοντα μετὰ τῶν γεωργῶν Πομπήιον, ὧν αὐτοὶ τὰ χωρία ἔχουσιν· ἐς γὰρ δὴ Πομπήιον οἱ πλέονες τῶν γεωργῶν ἐπεφεύγεσαν. καὶ πιθανοῦ τοῦ διερεθίσματος ὄντος, οὐδ’ ὣς οἱ κληροῦχοι προθύμως ἐπὶ τὸν Ἀντώνιον ἐστράτευον· οὕτως ἡ δόξα τῶν ἐν Φιλίπποις γεγονότων ἐδημαγώγει τὸν Ἀντώνιον. ὁ δὲ Καῖσαρ Ἀντωνίου μὲν καὶ Πομπηίου καὶ Ἀηνοβάρβου κατὰ πλῆθος ὁπλιτῶν ὑπεροίσειν ἐνόμιζεν (ἦρχε γὰρ τελῶν ἐς τότε τεσσαράκοντα πλεόνων), ναῦν δὲ οὐδεμίαν ἔχων οὐδὲ καιρὸν ἐς ναυπηγίαν ὠρρώδει, ναῦς ἐκείνων ἐχόντων πεντακοσίας, μὴ τὴν Ἰταλίαν περιπλέοντες ἐς λιμὸν περιενέγκαιεν. ὧν ἐνθυμούμενος (ἐλέλεκτο δὲ αὐτῷ περὶ πολλῶν παρθένων ἐς γάμον) ἐπέστελλε Μαικήνᾳ συνθέσθαι Σκριβωνίᾳ, τῇ Λίβωνος ἀδελφῇ, τοῦ κηδεύοντος Πομπηίῳ, ἵν’ ἔχοι καὶ τήνδε ἀφορμὴν ἐς διαλύσεις, εἰ δεήσειεν. καὶ πυθόμενος ὁ Λίβων ἐπέστελλε τοῖς οἰκείοις ἐγγυᾶν αὐτὴν τῷ Καίσαρι προθύμως. ὁ δὲ Καῖσαρ τῶν Ἀντωνίου φίλων καὶ στρατῶν ὅσους ὑπώπτευε, διέπεμπεν ἐπὶ προφάσεων ἄλλους ἀλλαχοῦ καὶ Λέπιδον ἐς τὴν ἐψηφισμένην αὐτῷ Λιβύην, ἄγοντα τῶν Ἀντωνίου τελῶν τὰ ὑποπτότατα ἕξ.", "st": "5.53"}, {"sp": "N", "t": "Λεύκιον δὲ καλέσας ἐπῄνει μὲν ἐς φιλαδελφίαν, εἰ τῇ Ἀντωνίου γνώμῃ ὑπομεμενηκὼς ἴδιον τὸ ἁμάρτημα ποιοῖτο, ὠνείδιζε δὲ ἐς ἀχαριστίαν, εἰ τοιούτου τυχὼν αὑτοῦ μηδὲ νῦν ὁμολογοίη περὶ Ἀντωνίου, σαφῶς ἤδη καὶ Πομπηίῳ συνθέσθαι λεγομένου. “ἐγὼ δέ σοι πιστεύων,” ἔφη, “Καληνοῦ τελευτήσαντος τά τε ἔθνη τὰ ὑπ’ αὐτῷ καὶ τὸν στρατόν, ἵνα μὴ ἄναρχος εἴη, διὰ τῶν ἐμαυτοῦ φίλων διῴκουν Ἀντωνίῳ. ἀλλὰ νῦν ἐκφανείσης τῆς ἐνέδρας ἐκεῖνά τε ἐμαυτοῦ πάντα ποιοῦμαι καὶ σοὶ πρὸς τὸν ἀδελφὸν ἀπιέναι θέλοντι συγχωρῶ μετὰ ἀδείας.” ὁ μὲν οὕτως εἶπεν, εἴτε πειρώμενος τοῦ Λευκίου, εἴτε τὸ λεχθὲν ἐκπεσεῖν ἐθέλων ἐς τὸν Ἀντώνιον· ὁ δὲ οἷα καὶ πρότερον εἶπε· “Φουλβίας μὲν ᾐσθόμην οὔσης μοναρχικῆς, ἐγὼ δὲ συνεχρώμην τοῖς τοῦ ἀδελφοῦ στρατοῖς ἐς τὴν ἁπάντων ὑμῶν καθαίρεσιν. καὶ νῦν, εἰ μὲν ἐπὶ καταλύσει τῆς μοναρχίας ἔρχοιτο ὁ ἀδελφός, καὶ φανερῶς καὶ λαθὼν οἰχήσομαι πρὸς αὐτόν, ἀγωνιούμενος αὖθις ὑπὲρ τῆς πατρίδος πρὸς σέ, καίπερ ἤδη μοι γενόμενον εὐεργέτην. εἰ δ’ ἐπιλέγοιτο κἀκεῖνος καὶ διακρίνοι τοὺς συμμοναρχήσοντας αὑτῷ, πολεμήσω σὺν σοὶ πρὸς αὐτόν, ἕως ἂν ἡγῶμαι μηδὲ σὲ μοναρχίαν καθίστασθαι· τὸ γὰρ τῆς πατρίδος αἰεὶ προθήσω καὶ χάριτος καὶ γένους.” ὧδε μὲν ὁ Λεύκιος εἶπεν, ὁ δὲ Καῖσαρ αὐτὸν καὶ τέως ἐν θαύματι ἄγων οὐκ ἔφη μὲν οὐδὲ βουλόμενον ἐπάξεσθαι κατὰ ἀδελφοῦ, πιστεύσειν δὲ ὡς τοιῷδε ἀνδρὶ πᾶσαν Ἰβηρίαν καὶ τὸν ἐν αὐτῇ στρατόν, ὑποστρατηγούντων αὐτῷ τῶν νῦν ἡγουμένων αὐτῆς Πεδουκαίου τε καὶ Λευκίου.", "st": "5.54"}, {"sp": "N", "t": "οὕτω μὲν δὴ καὶ Λεύκιον ὁ Καῖσαρ ἀπέπεμπε σὺν τιμῇ καὶ διὰ τῶν ὑποστρατήγων ἐφύλασσεν ἀφανῶς· Ἀντώνιος δὲ Φουλβίαν μὲν ἐν Σικυῶνι νοσηλευομένην ἀπέλιπεν, ἀπὸ δὲ Κερκύρας ἐς τὸν Ἰόνιον ἔπλει, στρατῷ μὲν οὐ πολλῷ ναυσὶ δὲ διακοσίαις, ἃς ἐν Ἀσίᾳ πεποίητο. πυθόμενος δὲ Ἀηνόβαρβον ἀπαντᾶν αὑτῷ ναυσὶ καὶ στρατῷ πολλῷ, οὐ δοκοῦντά τισιν οὐδ’ ἐπὶ ταῖς διαπεμφθείσαις σπονδαῖς εἶναι βέβαιον (ἦν γὰρ Ἀηνόβαρβος τῶν κατεγνωσμένων τε ἐκ δίκης ἐπὶ Γαΐῳ Καίσαρι φόνου καὶ προγεγραμμένων ἐπὶ τῇ καταδίκῃ καὶ ἐν Φιλίπποις Ἀντωνίῳ καὶ Καίσαρι πεπολεμηκότων), ὅμως ἔπλει, πέντε ναυσὶν ἐπιβὰς ταῖς ἀρίσταις, ἵνα φαίνοιτο πιστεύων, καὶ τὰς λοιπὰς ἐκ διαστήματος ἕπεσθαι κελεύσας. καθορωμένου δὲ ἤδη τοῦ Ἀηνοβάρβου παντί τε τῷ στρατῷ καὶ παντὶ τῷ στόλῳ μετ’ ὀξείας εἰρεσίας προσπλέοντος, ἔδεισεν ὁ Πλάγκος Ἀντωνίῳ παρεστὼς καὶ ἐπισχεῖν αὐτὸν ἠξίου τὸν πλοῦν καὶ προπέμψαι τινὰς ἐς πεῖραν ὡς πρὸς ἀμφίβολον ἄνδρα. ὁ δὲ εἰπὼν αἱρεῖσθαι παρασπονδούμενος ἀποθανεῖν μᾶλλον ἢ σῴζεσθαι δειλὸς ὀφθείς, ἔπλει. πλησίον τε ἦσαν ἀλλήλων ἤδη, καὶ αἱ ναυαρχίδες ἐκ τῶν σημείων ἐφαίνοντο καὶ ἀλλήλαις προσέπλεον· καὶ τῶν ῥαβδούχων ὁ ἡγούμενος Ἀντωνίῳ, κατὰ τὴν πρῷραν, ὥσπερ ἔθος ἐστίν, ἑστώς, εἴτ’ ἐκλαθόμενος, ὅτι ἀμφίβολος ἀνὴρ καὶ στρατοῦ κἀκεῖνος ἡγούμενος ἰδίου προσπλέοι, εἴτε ἀπὸ εὐγενεστέρου φρονήματος, ὡς ὑπηκόοις ἢ ἐλάσσοσιν ἀνδράσιν ὑπαντῶσι, προσέταξε καθελεῖν τὸ σημεῖον. οἱ δὲ καθῄρουν τε καὶ τὴν ναῦν ἐς τὰ πλάγια τῆς Ἀντωνίου νεὼς περιέστρεφον. ὡς δὲ καὶ συνιδόντες ἀλλήλους ἠσπάσαντο καὶ ὁ στρατὸς ὁ τοῦ Ἀηνοβάρβου τὸν Ἀντώνιον ἡγεμόνα προσεῖπεν, ὁ μὲν Πλάγκος ἀνεθάρρει μόλις, ὁ δὲ Ἀντώνιος ἐς τὴν ἑαυτοῦ ναῦν τὸν Ἀηνόβαρβον ἀναδεξάμενος ἐς Παλόεντα κατέπλευσεν, ἔνθα ἦν Ἀηνοβάρβῳ καὶ τὸ πεζόν. καὶ ὁ Ἀηνόβαρβος τῆς σκηνῆς ἐξίστατο Ἀντωνίῳ.", "st": "5.55"}, {"sp": "N", "t": "ἐντεῦθεν ἐπὶ Βρεντεσίου διέπλεον, φυλασσομένου πρὸς πέντε Καίσαρος τάξεων, καὶ οἱ Βρεντέσιοι τὰς πύλας ἀπέκλειον, Ἀηνοβάρβῳ μὲν ὡς ἐκ πολλοῦ πολεμίῳ, Ἀντωνίῳ δὲ ὡς πολέμιον ἐπάγοντι. ὁ δὲ ἀγανακτῶν καὶ ἡγούμενος εἶναι τάδε καλλωπίσματα, τὸ δ’ ἀληθὲς ἀποκλείεσθαι πρὸς τῶν Καίσαρος φρουρῶν γνώμῃ Καίσαρος, διετάφρευε τῆς πόλεως τὸν ἰσθμὸν καὶ ἀπετείχιζεν. ἔστι δ’ ἡ πόλις χερρόνησος ἐν μηνοειδεῖ λιμένι, καὶ οὐκ ἦν ἔτι τοῖς ἐξ ἠπείρου προσελθεῖν ἀνάντει λόφῳ, διατετμημένῳ τε καὶ διατετειχισμένῳ. ὁ δὲ Ἀντώνιος καὶ τὸν λιμένα μέγαν ὄντα φρουρίοις πυκνοῖς περιεφράξατο καὶ τὰς νήσους τὰς ἐν αὐτῷ. ἔς τε τὰ παράλια τῆς Ἰταλίας περιέπεμπεν, οἷς εἴρητο τὰ εὔκαιρα καταλαμβάνειν. ἐκέλευε δὲ καὶ Πομπήιον ἐπιπλεῖν τῇ Ἰταλίᾳ καὶ δρᾶν, ὅ τι δύναιτο. ὁ δὲ ἄσμενος αὐτίκα Μηνόδωρον σὺν ναυσὶ πολλαῖς καὶ στρατοῦ τέσσαρσι τέλεσιν ἐκπέμψας Σαρδὼ Καίσαρος οὖσαν καὶ τὰ ἐν αὐτῇ δύο τέλη περιέσπασε τὴν συμφροσύνην Ἀντωνίου καταπλαγέντας. τῆς δὲ Ἰταλίας Σιποῦντα μὲν τῆς Αὐσονίας οἱ τοῦ Ἀντωνίου κατέλαβον, Θουρίους δὲ καὶ Κωνσεντίαν Πομπήιος ἐπολιόρκει καὶ τὴν χώραν ἐπενέμετο τοῖς ἱππεῦσιν.", "st": "5.56"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ, ὀξείας καὶ πανταχοῦ τῆς ἐπιχειρήσεως γενομένης, ἐς μὲν τὴν Αὐσονίδα ἔπεμπεν Ἀγρίππαν ἐπικουρεῖν τοῖς πονουμένοις. καὶ ὁ Ἀγρίππας τοὺς ἐν ὁδῷ κληρούχους ἦγεν, ἐκ διαστήματος ἑπομένους ὡς ἐπὶ Πομπήιον ἰόντας· μαθόντες δὲ Ἀντωνίου γνώμῃ τὰ γιγνόμενα εἶναι, ἀνέστρεφον αὐτίκα διαλανθάνοντες. καὶ τοῦτο μάλιστα κατέπληξε τὸν Καίσαρα. ὁδεύων δ’ ὅμως ἐς τὸ Βρεντέσιον αὐτὸς μεθ’ ἑτέρου στρατοῦ, τοῖς κληρούχοις αὖθις ἐνετύγχανε καὶ μετεδίδασκε καὶ τοὺς ὑφ’ ἑαυτοῦ συνῳκισμένους ἦγεν, αἰδουμένους καὶ γνώμην ἐν ἀπορρήτῳ ποιουμένους Ἀντώνιον καὶ Καίσαρα συναλλάσσειν, εἰ δ’ ὁ Ἀντώνιος ἀπειθῶν πολεμοίη, Καίσαρι ἀμύνειν. ὁ δὲ Καῖσαρ ἐν μὲν Κανυσίῳ τινὰς ἡμέρας ἐνοσηλεύετο, παντὶ δὲ ὢν ἔτι κρείσσων Ἀντωνίου κατὰ τὸ πλῆθος, εὗρε τὸ Βρεντέσιον ἀποτετειχισμένον καὶ οὐδὲν ἄλλ’ ἢ παρεστρατοπέδευε καὶ τοῖς γιγνόμενοις ἐφήδρευεν.", "st": "5.57"}, {"sp": "N", "t": "ὁ δ’ Ἀντώνιος ἐκράτει μὲν τοῖς ὀχυρώμασιν ὡς πολὺ μείονας ἔχων ἀσφαλῶς ἀπομάχεσθαι, ἐκάλει δὲ τὸν στρατὸν ἐκ Μακεδονίας κατὰ σπουδὴν καὶ ἐτέχναζεν ἑσπέρας ἀφανῶς ἀνάγεσθαι ναῦς μακράς τε καὶ στρογγύλας ἰδιωτικοῦ πλήθους, οἳ μεθ’ ἡμέραν ἄλλοι μετ’ ἄλλους κατέπλεον ὡπλισμένοι καθάπερ ἐκ Μακεδονίας ἐπιόντες, ἐφορῶντος αὐτῶν τὸν ἐπίπλουν τοῦ Καίσαρος. ἤδη δ’ αὐτῷ καὶ τὰ μηχανήματα γεγένητο, καὶ ἐπιχειρήσειν ἔμελλε τοῖς Βρεντεσίοις, ἀχθομένου τοῦ Καίσαρος, ὅτι μὴ εἶχεν ἐπαμύνειν. περὶ δὲ ἑσπέραν ἑκατέροις ἀγγέλλεται Σιποῦντα μὲν Ἀγρίππας ἀναλαβών, Πομπήιος δὲ Θουρίων μὲν ἀπεωσμένος, Κωνσεντίαν δ’ ἔτι περικαθήμενος, ἐφ’ οἷς ὁ Ἀντώνιος ἐδυσχέραινεν. ὡς δὲ καὶ Σερουίλιος ἀπηγγέλθη προσιὼν τῷ Καίσαρι μετὰ χιλίων καὶ πεντακοσίων ἱππέων, οὐ κατασχὼν τῆς ὁρμῆς ὁ Ἀντώνιος εὐθὺς ἀπὸ τοῦ δείπνου, μεθ’ ὧν εὗρεν ἑτοίμων φίλων καὶ ἱππέων τετρακοσίων, μάλα θρασέως ἐπειχθεὶς ἐπέπεσε τοῖς χιλίοις καὶ πεντακοσίοις εὐναζομένοις ἔτι περὶ πόλιν Ὑρίαν καὶ ἐκπλήξας ἀμαχεὶ παρέλαβέ τε καὶ αὐτῆς ἡμέρας ἐς τὸ Βρεντέσιον ἐπανήγαγεν. οὕτω τὸν Ἀντώνιον ὡς ἄμαχον ἐκ τῆς ἐν Φιλίπποις δόξης ἔτι κατεπεπλήγεσαν.", "st": "5.58"}, {"sp": "N", "t": "αἵ τε στρατηγίδες αὐτοῦ τάξεις, ὑπὸ τῆσδε τῆς δόξης ἐπαιρόμεναι, προσεπέλαζον τῷ χάρακι τῷ Καίσαρος κατὰ μέρη καὶ τοὺς συνεστρατευμένους σφίσιν ὠνείδιζον, εἰ πολεμήσοντες ἥκοιεν Ἀντωνίῳ τῷ πάντας αὐτοὺς περισώσαντι ἐν Φιλίπποις. τῶν δὲ ἀντεπικαλούντων, ὅτι αὐτοὶ σφίσιν ἥκουσι πολεμήσοντες, λόγοι συνισταμένων ἐγίγνοντο, καὶ τὰ ἐγκλήματα ἀλλήλοις προύφερον, οἱ μὲν τὴν ἀπόκλεισιν τοῦ Βρεντεσίου καὶ τὴν ἀφαίρεσιν τοῦ Καληνοῦ στρατοῦ, οἱ δὲ τὴν ἀποτείχισιν τοῦ Βρεντεσίου καὶ πολιορκίαν καὶ τὴν τῆς Αὐσονίδος καταδρομὴν καὶ τὸ συνθέσθαι μὲν Ἀηνοβάρβῳ σφαγεῖ Γαΐου Καίσαρος, συνθέσθαι δὲ Πομπηίῳ κοινῷ πολεμίῳ. καὶ τέλος οἱ τοῦ Καίσαρος τὴν γνώμην σφῶν τοῖς ἑτέροις ἀνεκάλυπτον, ὅτι Καίσαρι συνέλθοιεν οὐκ ἀμνημονοῦντες Ἀντωνίου τῆς ἀρετῆς, ἀλλὰ διαλλαγὰς ἐπινοοῦντες ἀμφοτέροις ἢ Ἀντώνιον ἀπειθοῦντα καὶ πολεμοῦντα ἀμυνούμενοι. καὶ τάδε καὶ αὐτοὶ προσπελάζοντες τοῖς Ἀντωνίου χαρακώμασι προύλεγον.", "st": "5.59"}, {"sp": "N", "t": "γιγνομένων δὲ τούτων ἀγγέλλεται Φουλβία τεθνεῶσα, λεγομένη μὲν ἐπὶ ταῖς Ἀντωνίου μέμψεσιν ἀθυμῆσαι καὶ ἐς τὴν νόσον ἐμπεσεῖν, νομιζομένη δὲ καὶ τὴν νόσον ἑκοῦσα ἐπιτρῖψαι διὰ τὴν ὀργὴν Ἀντωνίου· νοσοῦσάν τε γὰρ αὐτὴν ἀπολελοίπει καὶ οὐδὲ ἀπολείπων ἑωράκει. ἐδόκει δ’ ἀμφοτέροις ἐς πολλὰ συνοίσειν ὁ θάνατος, γυναίου φιλοπράγμονος ἀπηλλαγμένοις, ἣ διὰ τὸν Κλεοπάτρας ζῆλον ἐξερρίπισε τοσόνδε πόλεμον. τό γε μὴν πάθος ἀσθενῶς ἤνεγκεν ὁ Ἀντώνιος, ἡγούμενός τι καὶ αἴτιος γεγονέναι.", "st": "5.59"}, {"sp": "N", "t": "Λεύκιος δὲ ἦν Κοκκήιος ἑκατέρῳ φίλος καὶ ὑπὸ Καίσαρος ἐς Φοινίκην τοῦ προτέρου θέρους πρὸς τὸν Ἀντώνιον ἀπέσταλτο μετὰ Καικίνα, ἐπανιόντος δὲ τοῦ Καικίνα παρὰ Ἀντωνίῳ κατέμενεν. οὗτος τότε ὁ Κοκκήιος, τὸν καιρὸν οὐ μεθείς, ὑπεκρίνατο μεταπεμφθῆναι πρὸς Καίσαρος ἀσπασόμενος αὐτόν. συγχωροῦντος δ’ ἀπιέναι τοῦ Ἀντωνίου πειρώμενος ἤρετο, εἴ τι καὶ αὐτὸς ὁ Ἀντώνιος ἐπιστέλλει τῷ Καίσαρι, κεκομισμένος δι’ αὐτοῦ Κοκκηίου γράμματα. καὶ ὁ Ἀντώνιος “νῦν μέν,” ἔφη, “τί ἂν ἀλλήλοις γράφοιμεν, ὄντες ἐχθροί, εἰ μὴ κακῶς ἀγορεύοιμεν ἀλλήλους; ἀντέγραψα δὲ τοῖς πάλαι διὰ Καικίνα· καὶ εἰ βούλει, λάβε τὰ ἀντίγραφα.” ὁ μὲν οὕτως ἐπεχλεύασεν, ὁ δὲ Κοκκήιος οὐκ εἴα τω τὸν Καίσαρα καλεῖν ἐχθρόν, ἔς τε Λεύκιον καὶ τοὺς ἄλλους Ἀντωνίου φίλους τοιόνδε γεγενημένον. ὁ δέ “ἐκ Βρεντεσίου με,” φησίν, “ἀποκλείων καὶ τὰ ἐμὰ ἔθνη καὶ τὸν Καληνοῦ στρατὸν ἀφαιρούμενος ἔτι τοῖς φίλοις ἐστὶν εὔνους μόνοις· οὐδὲ τοὺς φίλους ἐμοὶ περισῴζειν ἔοικεν, ἀλλὰ ταῖς εὐεργεσίαις ἐχθροποιεῖν.” καὶ ὁ Κοκκήιος, ἃ μὲν ἐπεμέμφετο μαθών, οὐδὲν δὲ ἔτι ὀξυτέραν φύσιν ἐπερεθίσας, ᾤχετο πρὸς τὸν Καίσαρα.", "st": "5.60"}, {"sp": "N", "t": "ὁ δὲ αὐτὸν ἰδὼν ἐν θαύματι ἐποιεῖτο, ὅτι μὴ θᾶσσον ἔλθοι· “οὐ γάρ,” ἔφη, “καὶ τὸν σὸν ἀδελφόν, ἵν’ ἐχθρὸς ᾖς μοι, περιέσωσα.” ὁ δέ “πῶς,” ἔφη, “τοὺς μὲν ἐχθροὺς φίλους ποιῇ, τοὺς δὲ φίλους ἐχθροὺς ἀποκαλεῖς τε καὶ τὸν στρατὸν ἀφαιρῇ καὶ τὰ ἔθνη;” καὶ ὁ Καῖσαρ “οὐ γάρ,” ἔφη, “Καληνοῦ τελευτήσαντος ἐχρῆν ἐπὶ μειρακίῳ τῷ Καληνοῦ παιδὶ γενέσθαι τοσαύτας ἀφορμάς, ἀπόντος ἔτι Ἀντωνίου· αἷς καὶ Λεύκιος ἐπαρθεὶς ἐμάνη, καὶ Ἀσίνιος καὶ Ἀηνόβαρβος γειτονεύοντες ἐχρῶντο καθ’ ἡμῶν. ἐπεὶ καὶ τὰ Πλάγκου τέλη κατὰ σπουδὴν κατέλαβον, ἵνα μὴ οἴχοιτο πρὸς Πομπήιον· οἱ γοῦν ἱππέες αὐτῶν διέπλευσαν ἐς Σικελίαν.” καὶ ὁ Κοκκήιος “ἑτέρως,” ἔφη, “τάδε λογοποιούμενα οὐδὲ Ἀντώνιος ἐπίστευεν, ἕως ἀπεκλείσθη τοῦ Βρεντεσίου καθάπερ πολέμιος.” καὶ ὁ Καῖσαρ οὐδὲν μὲν αὐτὸς ἔφη περὶ τοῦδε προστάξαι (οὐδὲ γὰρ προμαθεῖν προσπλέοντα οὐδ’ ἀφικέσθαι μετὰ πολεμίων προσδοκῆσαι), Βρεντεσίους δὲ αὐτοὺς καὶ τὸν ὑπολελειμμένον αὐτοῖς διὰ τὰς Ἀηνοβάρβου καταδρομὰς ταξίαρχον αὐτοκελεύστους ἀποκλεῖσαι τὸν Ἀντώνιον, συνθέμενον μὲν ἐχθρῷ κοινῷ Πομπηίῳ, ἐπαγαγόντα δὲ Ἀηνόβαρβον φονέα τοῦ ἐμοῦ πατρός, ψήφῳ καὶ κρίσει καὶ προγραφῇ κατεγνωσμένον καὶ πολιορκήσαντα μὲν τὸ Βρεντέσιον μετὰ Φιλίππους, πολιορκοῦντα δὲ ἔτι τὸν Ἰόνιον ἐν κύκλῳ, ἐμπρήσαντα δὲ τὰς ἐμὰς ναῦς καὶ τὴν Ἰταλίαν λεηλατήσαντα.", "st": "5.61"}, {"sp": "N", "t": "ὁ δέ “σπένδεσθαι μέν,” ἔφη, “συνεχωρήσατε ἀλλήλοις, πρὸς οὓς ἂν ἐθέλητε· καὶ οὐδενὶ τῶν ἀνδροφόνων Ἀντώνιος ἐσπείσατο, οὐδὲν ἔλασσον ἢ αὐτὸς σὺ τὸν σὸν πατέρα τιμῶν. Ἀηνόβαρβος δὲ οὐκ ἔστι τῶν ἀνδροφόνων, ἡ δὲ ψῆφος αὐτῷ κατ’ ὀργὴν ἐπῆκται· οὐδὲ γὰρ τῆς βουλῆς πω τότε μετεῖχεν. εἰ δ’ ὡς φίλῳ Βρούτου μὴ συγγνῶναι νομίζοιμεν, οὐκ ἂν φθάνοιμεν ὀλίγου δεῖν ἅπασι χαλεπαίνοντες; Πομπηίῳ δὲ οὐ συνέθετο μὲν συμμαχήσειν ὁ Ἀντώνιος, πολεμούμενος δ’ ὑπὸ σοῦ προσλήψεσθαι σύμμαχον ἢ καὶ σοὶ συναλλάξειν, οὐδὲν ἀνήκεστον οὐδ’ ἐκεῖνον εἰργασμένον. σὺ δὲ καὶ τῶνδε τὴν αἰτίαν ἔχεις· εἰ γὰρ οὐκ ἐπολεμήθη κατὰ τὴν Ἰταλίαν, οὐδ’ ἂν οὗτοι πρεσβεύεσθαι ταῦτα πρὸς τὸν Ἀντώνιον ἐθάρρουν.” καὶ ὁ Καῖσαρ ἔτι ἐπικαλῶν “τὴν μὲν Ἰταλίαν,” ἔφη, “κἀμὲ σὺν αὐτῇ, Μανιος καὶ Φουλβία καὶ Αεύκιος ἐπολέμουν· ὁ δὲ Πομπήιος οὐ πρότερον, ἀλλὰ νῦν Ἀντωνίῳ θαρρῶν ἐπιβέβηκε τῆς παραλίου.” καὶ ὁ Κοκκήιος “οὐκ Ἀντωνίῳ θαρρῶν,” εἶπεν, “ἀλλὰ ὑπ’ Ἀντωνίου πεμφθείς. οὐ γὰρ ἐπικρύψω σε, ὅτι καὶ τὴν ἄλλην Ἰταλίαν ἐπιδραμεῖται ναυτικῷ πολλῷ ναυτικὸν οὐκ ἔχουσαν, εἰ μὴ διαλύσεσθε ὑμεῖς.” ὁ δὲ Καῖσαρ (οὐ γὰρ ἀμελῶς ἤκουσε τοῦ τεχνάσματος) ἐπισχὼν ὀλίγον εἶπεν· “ἀλλ’ οὐ χαιρήσει Πομπήιος, κακὸς κακῶς καὶ νῦν ἐκ Θουρίων ἐξελαθείς.” καὶ ὁ Κοκκήιος τὰ ἀμφίλογα πάντα κατιδὼν ἐπῆγε τὸν Φουλβίας θάνατον καὶ τρόπον αὐτοῦ, ὅτι πρὸς τὴν ὀργὴν Ἀντωτίου δυσχεράνασά τε νοσήσειε καὶ τὴν νόσον ἐπιτρίψειεν ὑπὸ τῆς δυσθυμίας, οὐκ ἰδόντος αὐτὴν οὐδὲ νοσοῦσαν Ἀντωνίου, ὡς αἴτιον τῇ γυναικὶ θανάτου γενόμενον· ἐκποδὼν δὲ κἀκείνης γενομένης, οὐδενὸς ὑμῖν ἐνδεῖν ἔτι ἔφη “πρὸς ἀλλήλους πλὴν ἀληθεῦσαι, περὶ ὧν ὑπενοήσατε.”", "st": "5.62"}, {"sp": "N", "t": "οὕτω καθομιλῶν τὸν Καίσαρα ὁ Κοκκήιος ἐκείνην τε τὴν ἡμέραν ἐξενίζετο παρ’ αὐτῷ καὶ ἐδεῖτο ἐπιστεῖλαί τι τῷ Ἀντωνίῳ, νεώτερον ὄντα πρεσβυτέρῳ. ὁ δὲ πολεμοῦντι μὲν ἔτι οὐκ ἔφη γράψειν· οὐδὲ γὰρ ἐκεῖνον· μέμψεσθαι δ’ αὐτοῦ τῇ μητρί, ὅτι συγγενὴς οὖσα καὶ προτιμηθεῖσα ἐκ πάντων ὑφ’ αὑτοῦ, φύγοι τὴν Ἰταλίαν καθάπερ οὐ τευξομένη πάντων ὡς παρ’ υἱοῦ. ὧδε μὲν καὶ ὁ Καῖσαρ ἐτέχναζε καὶ ἐπέστελλε τῇ Ἰουλίᾳ. ἐξιόντι δὲ τοῦ στρατοπέδου τῷ Κοκκηίῳ πολλοὶ τῶν ταξιάρχων τὴν γνώμην ἐξέφερον τοῦ στρατοῦ. ὁ δὲ καὶ τἆλλα καὶ τόδε αὐτὸ τῷ Ἀντωνίῳ μετέφερεν, ἵνα εἰδείη πολεμήσοντας οὐ συντιθεμένῳ. συνεβούλευεν οὖν Πομπήιον μὲν ἐς Σικελίαν ἐξ ὧν ἐπόρθει μετακαλεῖν, Ἀηνόβαρβον δέ ποι πέμπειν, ἕως αἱ συνθῆκαι γένοιντο. παρακαλούσης δὲ καὶ τῆς μητρὸς ἐς ταῦτα τὸν Ἀντώνιον (γένει γὰρ ἦν ἐκ τῶν Ἰουλίων), ᾐσχύνετο Ἀντώνιος, εἰ μὴ γενομένων τῶν συμβάσεων τὸν Πομπήιον αὖθις ἐς συμμαχίαν καλοίη. τῆς δὲ μητρὸς οὐκ ἀπελπιζούσης αὐτὰς ἔσεσθαι καὶ Κοκκηίου ἰσχυριζομένου τε περὶ αὐτῶν καὶ ἐλπιζομένου τι πλέον εἰδέναι, ὁ Ἀντώνιος ἐνεδίδου καὶ τὸν Πομπήιον ἀναχωρεῖν ἐκέλευεν ἐς Σικελίαν, ὡς ἐπιμελησόμενος τῶν συγκειμένων, καὶ Ἀηνόβαρβον ἔπεμπεν ἡγεῖσθαι Βιθυνίας.", "st": "5.63"}, {"sp": "N", "t": "ὧν ὁ στρατὸς ὁ τοῦ Καίσαρος αἰσθανόμενοι πρέσβεις εἵλοντο τοὺς αὐτοὺς ἐς ἀμφοτέρους, οἳ τὰ μὲν ἐγκλήματα αὐτῶν ἐπέσχον ὡς οὐ κρῖναι σφίσιν, ἀλλὰ διαλλάξαι μόνον ᾑρημένοι, σφίσι δ’ αὐτοῖς προσελόμενοι Κοκκήιον μὲν ὡς οἰκεῖον ἀμφοῖν, ἐκ δὲ τῶν Ἀντωνίου Πολλίωνα καὶ Μαικήναν ἐκ τῶν Καίσαρος, ἔγνωσαν Καίσαρι καὶ Ἀντωνίῳ πρὸς ἀλλήλους ἀμνηστίαν εἶναι τῶν γεγονότων καὶ φιλίαν ἐς τὸ μέλλον. ὑπογύως δὲ Μαρκέλλου τεθνεῶτος, ὃς τὴν ἀδελφὴν Καίσαρος εἶχεν Ὀκταουίαν, ἐδικαίουν οἱ διαλλακταὶ τὴν Ὀκταουίαν Ἀντωνίῳ τὸν Καίσαρα ἐγγυῆσαι. καὶ ὁ μὲν αὐτίκα ἐνηγγύα, καὶ ἠσπάζοντο ἀλλήλους, καὶ βοαὶ παρὰ τοῦ στρατοῦ καὶ εὐφημίαι πρὸς ἑκάτερον αὐτῶν ἦσαν ἄπαυστοι δι’ ὅλης τε τῆς ἡμέρας καὶ ἀνὰ τὴν νύκτα πᾶσαν.", "st": "5.64"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ καὶ ὁ Ἀντώνιος τὴν Ῥωμαίων αὖθις ἀρχὴν ἐφ’ ἑαυτῶν ἐμερίσαντο ἅπασαν, ὅρον μὲν εἶναι σφίσι Σκόδραν πόλιν τῆς Ἰλλυρίδος, ἐν μέσῳ τοῦ Ἰονίου μυχοῦ μάλιστα δοκοῦσαν εἶναι, ταύτης δ’ ἔχειν τὰ μὲν πρὸς ἕω πάντα τὸν Ἀντώνιον ἔθνη τε καὶ νήσους ἕως ἐπὶ ποταμὸν Εὐφράτην ἄνω, τὰ δὲ ἐς δύσιν τὸν Καίσαρα μέχρι ὠκεανοῦ. Λιβύης δὲ Λέπιδον ἄρχειν, καθὰ Καῖσαρ ἐδεδώκει. πολεμεῖν δὲ Πομπηίῳ μὲν Καίσαρα, εἰ μή τι συμβαίνοι, Παρθυαίοις δὲ Ἀντώνιον, ἀμυνόμενον τῆς ἐς Κράσσον παρασπονδήσεως. Ἀηνοβάρβῳ δ’ εἶναι πρὸς Καίσαρα συμβάσεις τὰς πρὸς Ἀντώνιον γενομένας. στρατὸν δὲ ἐκ τῆς Ἰταλίας προσκαταλέγειν ἀκωλύτως ἴσον ἑκάτερον.", "st": "5.65"}, {"sp": "N", "t": "αἵδε μὲν ἦσαν αἱ τελευταῖαι Καίσαρί τε καὶ Ἀντωνίῳ γενόμεναι συμβάσεις. καὶ εὐθὺς ἐς τὰ ἐπείγοντα τοὺς φίλους ἑκάτερος αὐτῶν περιέπεμπεν, Οὐεντίδιον μὲν ἐς τὴν Ἀσίαν Ἀντώνιος. ἀναστέλλειν Παρθυαίους τε καὶ Λαβιηνὸν τὸν Λαβιηνοῦ, μετὰ τῶν Παρθυαίων ἐν ταῖσδε ταῖς ἀσχολίαις Συρίαν τε καὶ τὰ μέχρι τῆς Ἰωνίας ἐπιδραμόντα.", "st": "5.65"}, {"sp": "N", "t": "ἃ μὲν δὴ Λαβιηνός τε καὶ Παρθυαῖοι δράσαντες ἔπαθον, ἡ Παρθυικὴ δηλώσει γραφή· Ἕλενον δὲ στρατηγὸν Καίσαρος, σὺν ὁρμῇ κατασχόντα Σαρδοῦς, αὖθις ἐξέβαλε τῆς Σαρδοῦς Μηνόδωρος ὁ Πομπηίου, καὶ τῷδε μάλιστα χαλεπαίνων ὁ Καῖσαρ οὐκ ἐδέχετο τὰς πείρας Ἀντωνίου συνάγοντος αὐτῷ Πομπήιον. ἐς δὲ Ῥώμην παρελθόντες ἐτέλουν τοὺς γάμους. καὶ ὁ Ἀντώνιος Μάνιον μὲν ἔκτεινεν ὡς ἐρεθίσαντά τε Φουλβίαν ἐπὶ διαβολῇ Κλεοπάτρας καὶ τοσῶνδε αἴτιον γενόμενον, Καίσαρι δὲ ἐνέφηνε Σαλουιδιηνόν, τὸν ἡγούμενον τῷ Καίσαρι τοῦ περὶ Ῥοδανὸν στρατοῦ, ἀπόστασιν ἰδίᾳ βουλεῦσαι καί οἱ περὶ τοῦδε προσπέμψαι περικαθημένῳ τὸ Βρεντέσιον. καὶ ὁ μὲν τόδε ἐξεῖπεν· οὐ πρὸς πάντων ἐπαινούμενον, εὐφυὴς ὢν ἄρα καὶ ταχὺς ἐς εὔνοιαν· ὁ δὲ Καῖσαρ αὐτίκα τὸν Σαλουιδιηνὸν ἐκάλει κατὰ σπουδήν, ὡς ἐπὶ δή τι μόνου χρῄζων καὶ εὐθὺς ἐκπέμψων αὖθις ἐς τὸν στρατόν, καὶ ἐλθόντα ἔκτεινε διελέγξας καὶ τὸν ὑπ’ αὐτῷ στρατὸν ὡς ὕποπτον ὄντα ἔχειν ἔδωκεν Ἀντωνίῳ.", "st": "5.66"}, {"sp": "N", "t": "Ῥωμαίους δ’ ὁ λιμὸς ἐπίεζεν, οὔτε τῶν ἑῴων ἐμπόρων ἐπιπλεόντων δέει Πομπηίου καὶ Σικελίας, οὔτε τῶν ἐκ δύσεως διὰ Σαρδὼ καὶ Κύρνον ἐχομένας ὑπὸ τῶν Πομπηίου, οὔτ’ ἐκ τῆς περαίας Λιβύης διὰ τοὺς αὐτοὺς ἑκατέρωθεν ναυκρατοῦντας. ἐπετίμητο δὴ πάντα, καὶ τῶνδε τὴν αἰτίαν ἐς τὴν ἔριν τῶν ἡγεμόνων ἀναφέροντες ἐβλασφήμουν αὐτοὺς καὶ ἐς διαλύσεις πρὸς Πομπήιον ἐπέσπερχον. οὐκ ἐνδιδόντος δὲ τοῦ Καίσαρος οὐδ’ ὥς, ὁ Ἀντώνιος αὐτὸν ἠξίου ταχύνειν γε τὸν πόλεμον διὰ τὴν ἀπορίαν. χρημάτων δ’ ἐς αὐτὸν οὐκ ὄντων προυτέθη διάγραμμα, εἰσφέρειν ἐπὶ μὲν τοῖς θεράπουσι τοὺς κεκτημένους ὑπὲρ ἑκάστου τὸ ἥμισυ τῶν πέντε καὶ εἴκοσι δραχμῶν ὡρισμένων ἐς τὸν πόλεμον τὸν Κασσίου τε καὶ Βρούτου, ἐσφέρειν δὲ καὶ μοῖραν τοὺς ἐκ διαθήκης τι καρπουμένους. τοῦτο τὸ γράμμα σὺν ὁρμῇ μανιώδει καθεῖλεν ὁ δῆμος ἀγανακτῶν, εἰ τὰ κοινὰ ταμιεῖα κεκενωκότες καὶ τὰ ἔθνη σεσυληκότες καὶ τὴν Ἰταλίαν αὐτὴν ἐσφοραῖς καὶ τέλεσι καὶ δημεύσεσι καταβαρήσαντες οὐκ ἐς πολέμους οὐδ’ ἐς ἐπίκτητον ἀρχήν, ἀλλ’ ἐς ἰδίους ἐχθροὺς ὑπὲρ οἰκείας δυναστείας, ὑπὲρ ἧς δὴ καὶ προγραφὰς καὶ σφαγὰς καὶ λιμὸν ἐκ τῶνδε πανώδυνον γεγονέναι, ἔτι καὶ τὰ λοιπὰ περιδύοιεν αὑτούς.", "st": "5.67"}, {"sp": "N", "t": "συνιστάμενοί τε ἐβόων καὶ τοὺς οὐ συνισταμένους ἔβαλλον καὶ ἠπείλουν διαρπάσειν αὐτῶν τὰς οἰκίας καὶ καταπρήσειν, ἕως τὸ μὲν πλῆθος ἅπαν ἠρέθιστο, ὁ δὲ Καῖσαρ σὺν τοῖς φίλοις καὶ ὀλίγοις ὑπασπισταῖς ἐς μέσους ἦλθεν, ἐντυχεῖν τε βουλόμενος καὶ τὴν μέμψιν ἐκλογίσασθαι. οἱ δὲ αὐτὸν εὐθὺς ὀφθέντα ἔβαλλόν τε ἀφειδῶς πάνυ καὶ οὐδ’ ὑπομένοντα καὶ ἑαυτὸν ἐμπαρέχοντα καὶ τιτρωσκόμενον ᾐδοῦντο. πυθόμενος δ’ ὁ Ἀντώνιος ἐβοήθει κατὰ σπουδήν. οἱ δὲ καὶ τόνδε, κατιόντα τὴν ἱερὰν ὁδόν, οὐκ ἔβαλλον μὲν ὡς ἕτοιμον ἐς τὰς Πομπηίου διαλύσεις, ἀναχωρεῖν δὲ ἐκέλευον· καὶ οὐ πειθόμενον, τότε ἔβαλλον. ὁ δὲ ὁπλίτας πλέονας, οἳ ἦσαν ἔξω τοῦ τείχους, ἐκάλει. καὶ οὐ παριέντων οὐδ’ ὣς αὐτόν, οἱ μὲν ὁπλῖται διαιρεθέντες ἐς τὰ πλάγια τῆς ὁδοῦ καὶ τῆς ἀγορᾶς ἐπεχείρουν ἐκ τῶν στενωπῶν καὶ τὸν ἐντυχόντα ἀνῄρουν· οἱ δ’ οὐκέτι εὐμαρῶς οὐδὲ φυγεῖν ἐδύναντο, βεβυσμένοι τε ὑπὸ πλήθους καὶ διαδρομὴν οὐκέτι ἔχοντες, ἀλλὰ φόνος ἦν καὶ τραύματα καὶ ἀπὸ τῶν τεγῶν οἰμωγαὶ καὶ βοαί. καὶ ὁ Ἀντώνιος μόλις τε παρῆλθε, καὶ τοῦ κινδύνου τὸν Καίσαρα περιφανῶς δὴ τότε μάλιστα οὗτος ἐξείλετο καὶ ἐς τὴν οἰκίαν περιέσωσε. διαφυγόντος δέ ποτε τοῦ πλήθους τὰ νεκρά, ἵνα μὴ ἐνοχλοίη θεωρούμενα, ἐς τὸν ποταμὸν ἀπερριπτεῖτο· καὶ ἕτερον πένθος ἦν ὁρωμένων ἀνὰ τὸ ῥεῦμα, καὶ περιδυόντων αὐτὰ τῶν στρατιωτῶν καὶ ὅσοι μετ’ αὐτῶν κακοῦργοι τὰ εὐσχήμονα μάλιστα ὡς οἰκεῖα ἔφερον. ἀλλὰ ταῦτα μὲν ἐπαύετο σὺν φόβῳ τε καὶ μίσει τῶν ἡγουμένων, ὁ δὲ λιμὸς ἤκμαζε, καὶ ὁ δῆμος ἔστενε καὶ ἡσύχαζεν.", "st": "5.68"}, {"sp": "N", "t": "ὁ δ’ Ἀντώνιος ἐδίδασκε τοὺς Λίβωνος οἰκείους Λίβωνα καλεῖν ἐκ Σικελίας ἐπὶ συνησθήσει τοῦ κήδους, ἐργασόμενόν τι καὶ μεῖζον· τὸ δ’ ἀσφαλὲς τῷ Λίβωνι ἀνεδέχετο αὐτός. οἱ μὲν δὴ ταχέως ἐπέστελλον, καὶ ὁ Πομπήιος τῷ Λίβωνι συνεχώρει. ἀφικόμενος δὲ ὁ Λίβων ἐς νῆσον ὡρμίσθη τὰς Πιθηκούσας, ἣ νῦν ἐστιν Αἰναρία. καὶ μαθὼν ὁ δῆμος αὖθις ἠθροίζετο καὶ παρεκάλει σὺν ὀλοφύρσει τὸν Καίσαρα πέμψαι Λίβωνι πίστιν, πρεσβεύειν ἐθέλοντι πρὸς αὐτὸν ὑπὲρ εἰρήνης. καὶ ὁ μὲν ἄκων ἔπεμπεν, ὁ δὲ δῆμος καὶ Μουκίαν, τὴν μητέρα τοῦ Πομπηίου, καταπρήσειν ἀπειλοῦντες, ἐξέπεμπον ἐργασομένην διαλύσεις. Λίβων μὲν δὴ συνεὶς τῶν ἐχθρῶν ἐνδιδόντων ἠξίου τοὺς ἡγεμόνας αὐτοὺς συνελθεῖν ὡς ἀλλήλοις ἐνδώσοντας, ὅ τι ἂν δοκῇ· βιασαμένου δὲ καὶ ἐς τοῦτο τοῦ δήμου, ἐξῄεσαν ἐς Βαΐας ὁ Καῖσαρ καὶ ὁ Ἀντώνιος.", "st": "5.69"}, {"sp": "N", "t": "Πομπήιον δὲ οἱ μὲν ἄλλοι πάντες ὁμαλῶς ἔπειθον ἐς τὴν εἰρήνην, Μηνόδωρος δὲ ἀπὸ Σαρδοῦς ἐπέστελλεν ἢ πολεμεῖν ἐγκρατῶς ἢ βραδύνειν ἔτι, ὡς τοῦ λιμοῦ σφῶν προπολεμοῦντος καὶ τῶν συμβάσεων, εἰ καραδοκοίη, κρεισσόνων ἐσομένων· Μοῦρκόν τε τούτοις ἐνιστάμενον ὑποβλέπειν ἐκέλευεν ὡς ἀρχὴν αὑτῷ περικτώμενον. ὁ δὲ καὶ τέως τὸν Μοῦρκον διά τε ἀξίωμα καὶ γνώμην ἐγκρατῆ βαρυνόμενος ἔτι μᾶλλον ἐκ τῶνδε ἀπερρίπτει, καὶ οὐδὲν ἦν, ὅ τι Μούρκῳ προσεῖχεν, ἕως ὁ μὲν Μοῦρκος ἀχθόμενος ἐς Συρακούσας ὑπεχώρει καί τινας ἰδὼν φύλακας ἑπομένους ἐκ Πομπηίου, φανερῶς αὐτὸν ἐν τοῖς φύλαξιν ἐλοιδόρει. ὁ δὲ χιλίαρχον καὶ λοχαγὸν αὐτοῦ Μούρκου διαφθείρας ἔπεμψεν ἀνελεῖν αὐτὸν καὶ φάσκειν ὑπὸ θεραπόντων ἀνῃρῆσθαι· ἔς τε πίστιν τῆς ὑποκρίσεως τοὺς θεράποντας ἐσταύρου. οὐ μὴν ἐλάνθανε δεύτερον ἐπὶ Βιθυνικῷ τόδε μύσος ἐργασάμενος, περὶ ἄνδρα καὶ τὰ πολέμια λαμπρὸν καὶ τῆς αἱρέσεως ἐγκρατῆ φίλον ἀπ’ ἀρχῆς καὶ ἐς αὐτὸν Πομπήιον εὐεργέτην τε ἐν Ἰβηρίᾳ γενόμενον καὶ ἑκόντα ἐλθόντα ἐς Σικελίαν.", "st": "5.70"}, {"sp": "N", "t": "Μοῦρκος μὲν δὴ τεθνήκει, τῶν δ’ ἄλλων τὸν Πομπήιον ἐς τὰς διαλύσεις ἐπειγόντων καὶ τὸν Μηνόδωρον διαβαλλόντων ἐς φιλαρχίαν ὡς οὐκ εὐνοίᾳ τοῦ δεσπότου μᾶλλον ἢ ὅπως αὐτὸς ἄρχοι στρατοῦ καὶ χώρας ἐνιστάμενον, ἐνδοὺς ὁ Πομπήιος ἐς τὴν Αἰναρίαν διέπλει ναυσὶ πολλαῖς ἀρίσταις, ἑξήρους λαμπρᾶς ἐπιβεβηκώς. καὶ Δικαιάρχειαν μὲν οὕτω σοβαρῶς παρέπλευσε περὶ ἑσπέραν, ἐφορώντων τῶν πολεμίων· ἅμα δὲ ἕῳ, καταπηχθέντων σταυρῶν ἐξ ὀλίγου διαστήματος ἐν τῇ θαλάσσῃ, σανίδες τοῖς σταυροῖς ἐπετέθησαν, καὶ διὰ τῶνδε τῶν καταστρωμάτων ὁ μὲν Καῖσαρ καὶ ὁ Ἀντώνιος παρῆλθον ἐς τὸ πρὸς τῇ γῇ πεποιημένον, ὁ δὲ Πομπήιος καὶ ὁ Λίβων ἐς τὸ πελαγιώτερον, ὀλίγου ῥεύματος αὐτοὺς διείργοντος μὴ κεκραγότας ἀλλήλων ἀκούειν. ἐπεὶ δὲ ὁ μὲν Πομπήιος ἐπὶ κοινωνίᾳ τῆς ἀρχῆς ἥκειν ᾤετο ἀντὶ Λεπίδου, οἱ δὲ ὡς κάθοδον αὐτῷ δώσοντες μόνην, τότε μὲν ἐπ’ οὐδενὶ ἔργῳ διεκρίθησαν, διαπομπαὶ δὲ συχναὶ τῶν φίλων ἦσαν ἐπὶ ποικίλαις ἑκατέρων προκλήσεσιν. ᾔτει δ’ ὁ Πομπήιος τῶν προγεγραμμένων τε καὶ οἷ συνόντων τοῖς μὲν ἀνδροφόνοις Γαΐου Καίσαρος φυγὴν ἄδολον, τοῖς δὲ λοιποῖς κάθοδόν τε ἔντιμον καὶ τὰς οὐσίας, ἃς ἀναλώκεσαν. ἐπειγόμενοι δὲ ἐς τὰς συμβάσεις ὑπό τε τοῦ λιμοῦ καὶ ὑπὸ τοῦ δήμου, ἐς τὸ τέταρτον μόλις ἐνεδίδουν ὡς ὠνησόμενοι παρὰ τῶν ἐχόντων· καὶ τοῖς προγεγραμμένοις αὐτοῖς περὶ τούτων ἐπέστελλον, ἐλπίζοντες αὐτοῖς αὐτοὺς ἀγαπῆσειν. οἱ δὲ ἐδέχοντο πάντα, ἐπεὶ καὶ Πομπήιον αὐτὸν ἐδεδοίκεσαν ἤδη διὰ τὸ Μούρκου μύσος· καὶ προσιόντες τῷ Πομπηίῳ συνθέσθαι παρεκάλουν, ὅτε καὶ τὴν ἐσθῆτα κατερρήξατο ὁ Πομπήιος ὡς καὶ τῶνδε προδιδόντων αὑτόν, ὧν προμάχεται, καὶ θαμινὰ τὸν Μηνόδωρον ὡς στρατηγικὸν καὶ μόνον εὔνουν ἀνεκάλει.", "st": "5.71"}, {"sp": "N", "t": "Μουκίας δὲ αὐτὸν τῆς μητρὸς καὶ Ἰουλίας τῆς γυναικὸς ἐναγουσῶν, αὖθις οἱ τρεῖς συνῆλθον ἐς τὸ ἀμφίκλυστον Δικαιαρχέων χῶμα, περιορμουσῶν τῶν φυλακίδων νεῶν, καὶ συνέβησαν ἐπὶ τοῖσδε· λελύσθαι μὲν τὸν πόλεμον αὐτοῖς καὶ κατὰ γῆν καὶ κατὰ θάλασσαν καὶ τὰς ἐμπορίας ἀκωλύτους εἶναι πανταχοῦ, Πομπήιον δὲ τὰς φρουρὰς ἐξαγαγεῖν, ὅσαι κατὰ τὴν Ἰταλίαν εἰσί, καὶ μηκέτι τοὺς ἀποδιδράσκοντας οἰκέτας ὑποδέχεσθαι μηδ’ ἐφορμεῖν ναυσὶ τὴν ἀκτὴν τῆς Ἰταλίας, ἄρχειν δὲ Σαρδοῦς καὶ Σικελίας καὶ Κύρνου καὶ ὅσων ἄλλων εἶχεν ἐς τότε νήσων, ἐς ὅσον ἄρχοιεν τῶν ἑτέρων Ἀντώνιός τε καὶ Καῖσαρ, πέμποντα Ῥωμαίοις τὸν ἐκ πολλοῦ τεταγμένον αὐταῖς φέρειν σῖτον, ἐπιλαβεῖν δὲ καὶ Πελοπόννησον ἐπὶ ταύταις, ὑπατεῦσαι δ’ ἀπόντα, δι’ ὅτου κρίνοι τῶν φίλων, καὶ τῆς μεγίστης ἱερωσύνης ἐς τοὺς ἱερέας ἐγγραφῆναι. καὶ τάδε μὲν εἶναι Πομπηίῳ, κάθοδον δὲ τοῖς ἔτι φεύγουσι τῶν ἐπιφανῶν, πλὴν εἴ τις ἐπὶ τῷ φόνῳ Γαΐου Καίσαρος ψήφῳ καὶ κρίσει κατέγνωσται· καὶ τῆς περιουσίας τοῖς μὲν ἄλλοις, ὅσοι κατὰ φόβον ἔφευγον καὶ τὰ ὄντα αὐτοῖς ἐκ βίας ἀπωλώλει, τὸ ἐντελὲς ἀποδοθῆναι χωρὶς ἐπίπλων, τοῖς δὲ προγεγραμμένοις μοῖραν τετάρτην. καὶ τῶν ἐστρατευμένων τῷ Πομπηίῳ τοὺς μὲν οἰκέτας ἐλευθέρους εἶναι, τοῖς δ’ ἐλευθέροις, ὅτε παύσαιντο τῆς στρατείας, τὰ αὐτὰ δοθῆναι γέρα τοῖς ἐστρατευμένοις Καίσαρί τε καὶ Ἀντωνίῳ.", "st": "5.72"}, {"sp": "N", "t": "ἐς ταῦτα συνέβησαν καὶ ταῦτα συνεγράψαντο καὶ ἐσημήναντο καὶ ταῖς ἱεραῖς παρθένοις φυλάσσειν ἔπεμψαν ἐς Ῥώμην. ἐξένιζον δ’ ἀλλήλους αὐτίκα, περὶ τῆς τάξεως διαλαχόντες, πρῶτος μὲν ἐπὶ ἑξήρους Πομπήιος περιωρμις μένης ἐς τὸ χῶμα, ταῖς δὲ ἑξῆς Ἀντώνιός τε καὶ Καῖσαρ, σκηνοποιησάμενοι καὶ οἵδε ἐπὶ τοῦ χώματος, πρόφασιν μὲν ὡς ἅπαντες ἐπὶ ἀκτῆς ἑστιῷντο, τάχα δ’ ἐς ἀσφάλειαν ἀνύποπτον. οὐδὲ γὰρ οὐδ’ ὣς εἶχον ἀμελῶς, ἀλλ’ αἵ τε νῆες αὐτοῖς παρώρμουν, καὶ οἱ φύλακες περιειστήκεσαν, καὶ οἱ περὶ τὸ δεῖπνον αὐτὸ ἀφανῶς εἶχον ὑπεζωσμένα ξιφίδια. λέγεται δὲ Μηνόδωρος ἑστιωμένων ἐν τῇ νηὶ τῶν ἀνδρῶν πέμψαι Πομπηίῳ, προτρέπων αὐτὸν ἐπιθέσθαι τοῖς ἀνδράσι καὶ τίσασθαι μὲν τῆς ἐς τὸν πατέρα καὶ τὸν ἀδελφὸν ἁμαρτίας, ἀναλαβεῖν δὲ τὴν ἀρχὴν τὴν πατρῴαν δι’ ὀξυτάτης ἀφορμῆς· ἐπιμελήσεσθαι γὰρ αὐτὸς ἐν ταῖς ναυσὶν ὢν μηδένα διαφυγεῖν. ὁ δ’ ἀποκρίνασθαι τοῦ γένους ἅμα καὶ τῆς χρείας ἀξίως· “εἴθε Μηνόδωρον ἦν ἐργάσασθαι ταῦτα χωρὶς ἐμοῦ·” Μηνοδώρῳ γὰρ ἁρμόζειν ἐπιορκεῖν, οὐ Πομπηίῳ. ἥρμοσαν δ’ ἐν τῷδε τῷ δείπνῳ τὴν Πομπηίου θυγατέρα, Λίβωνος οὖσαν θυγατριδῆν, Μαρκέλλῳ τῷ προγόνῳ μὲν Ἀντωνίου, ἀδελφιδῷ δὲ Καίσαρος. ἀπέφηναν δὲ τῆς ἐπιούσης ὑπάτους ἐς τετραετὲς Ἀντώνιον μὲν καὶ Λίβωνα πρώτους, ἀντικαθιστάντος ὅμως Ἀντωνίου, ὃν ἂν βούλοιτο, ἐπὶ δ’ ἐκείνοις Καίσαρά τε καὶ Πομπήιον, εἶτα Ἀηνόβαρβον καὶ Σόσιον, εἶτ’ αὖθις Ἀντώνιόν τε καὶ Καίσαρα, τρίτον δὴ τότε μέλλοντας ὑπατεύσειν καὶ ἐλπιζομένους τότε καὶ ἀποδώσειν τῷ δήμῳ τὴν πολιτείαν.", "st": "5.73"}, {"sp": "N", "t": "τάδε μὲν ἔπραξαν, καὶ διακριθέντες ἀλλήλων ὁ μὲν ἐς Σικελίαν ἔπλει, Καῖσαρ δὲ καὶ Ἀντώνιος ὥδευον ἐς Ῥώμην. πυθόμεναι δὲ ἥ τε πόλις καὶ ἡ Ἰταλία, ἐπαιάνιζον αὐτίκα ἅπαντες ὡς ἐπὶ εἰρήνῃ, πολέμου τε ἀπαλλαγέντες ἐπιχωρίου καὶ ξεναγήσεως υἱῶν καὶ φρουρῶν ὕβρεως καὶ θεραπόντων αὐτομολίας καὶ λεηλασίας πεδίων καὶ γεωργίας ἀργίας, ὑπὲρ ἅπαντα δὲ τοῦ λιμοῦ, πιέσαντος αὐτοὺς ἐς ἔσχατον, ὥστε παροδεύουσιν αὐτοῖς οἷα σωτῆρσιν ἐγίγνοντο θυσίαι· καὶ τὸ ἄστυ ἔμελλεν ὑποδέξεσθαι περιφανῶς, εἰ μὴ νυκτός, ἐκκλίνοντες τὸ φορτικόν, ἔλαθον ἐς τὴν Ῥώμην ἐσελθόντες. μόνοι δὲ ἤχθοντο, ὅσοι τὰ τῶν ἐλευσομένων σὺν Πομπηίῳ χωρία κεκληρουχήκεσαν, ἡγούμεναι σφίσι τοὺς γεωμόρους ἀδιαλλάκτους ἐχθροὺς παροικήσειν καί, εἴ ποτε δυνηθεῖεν, ἐπιθήσεσθαι. οἱ δ’ ἀμφὶ τὸν Πομπήιον φυγάδες αὐτίκα, χωρὶς ὀλίγων, οἱ πλείους ἐν τῇ Δικαιαρχείᾳ τὸν Πομπήιον ἀσπασάμενοι κατέπλεον ἐς τὴν Ῥώμην. καὶ ἑτέρα τοῦ πλήθους ἦν ἡδονὴ καὶ βοαὶ ποικίλαι, τοσῶνδε οὕτως ἐπιφανῶν ἐξ ἀέλπτου περισεσωσμένων.", "st": "5.74"}, {"sp": "N", "t": "ἐπὶ δὲ τούτοις ὁ μὲν Καῖσαρ ἐς τὴν Κελτικὴν ἐξώρμα ταρασσομένην, ὁ δὲ Ἀντώνιος ἐπὶ τὸν πόλεμον τῶν Παρθυαίων. καὶ αὐτῷ τῆς βουλῆς ψηφισαμένης εἶναι κύρια, ὅσα ἔπραξέ τε καὶ πράξει, αὖθις στρατηγοὺς πανταχῇ περιέπεμπε καὶ τἆλλα ὡς ἐπενόει πάντα διεκόσμει. ἵστη δέ πῃ καὶ βασιλέας, οὓς δοκιμάσειεν, ἐπὶ φόροις ἄρα τεταγμένοις, Πόντου μὲν Δαρεῖον τὸν Φαρνάκους τοῦ Μιθριδάτου, Ἰδουμαίων δὲ καὶ Σαμαρέων Ἡρῴδην, Ἀμύνταν δὲ Πισιδῶν καὶ Πολέμωνα μέρους Κιλικίας καὶ ἑτέρους ἐς ἕτερα ἔθνη. τὸν δὲ στρατόν, ὅσος ἔμελλεν αὐτῷ συγχειμάσειν, περιουσιάσαι τε βουλόμενος καὶ γυμάσαι, τοὺς μὲν αὐτῶν ἐπὶ Παρθηνοὺς ἔπεμπεν, Ἰλλυρικὸν ἔθνος Ἐπιδάμνῳ πάροικον, προθυμοτάτους γενομένους Βρούτῳ, τοὺς δ’ ἐπὶ Δαρδανέας, ἕτερον Ἰλλυριῶν γένος, αἰεὶ Μακεδονίαν ἐπιτρέχοντας· τοὺς δ’ ἐν Ἠπείρῳ μένειν ἐκέλευεν, ὡς ἂν ἐν κύκλῳ πάντας ἔχῃ, μέλλων αὐτὸς ἐν Ἀθήναις χειμάσειν. ἔπεμπε δὲ καὶ Φούρνιον ἐς Λιβύην, τὰ ὑπὸ Σεξστίῳ τέλη τέσσαρα ἄξοντα ἐπὶ Παρθυαίους· οὐ γάρ πω πέπυστο αὐτὰ Λέπιδον ἀφῃρῆσθαι Σεξστίου.", "st": "5.75"}, {"sp": "N", "t": "ταῦτα διαθέμενος ἐχείμαζεν ἐν ταῖς Ἀθήναις μετὰ τῆς Ὀκταουίας, καθὰ καὶ ἐν Ἀλεξανδρείᾳ μετὰ τῆς Κλεοπάτρας, τὰ μὲν ἐκ τῶν στρατοπέδων ἐπιστελλόμενα ἐφορῶν μόνα, ἀφέλειαν δὲ ἰδιωτικὴν αὖθις ἐξ ἡγεμονίας καὶ σχῆμα τετράγωνον ἔχων καὶ ὑπόδημα Ἀττικὸν καὶ θύρας ἠρεμούσας. ἔξοδοί τε ἦσαν ὁμοίως ἄνευ σημείων αὐτῷ, σὺν δύο φίλοις καὶ σὺν ἀκολούθοις δύο, ἐς διδασκάλων διατριβὰς ἢ ἀκροάσεις. καὶ τὸ δεῖπνον ἦν Ἑλληνικὸν καὶ μεθ’ Ἑλλήνων ἡ γυμνασία πανηγύρεις τε σὺν θυμηδίᾳ μετὰ τῆς Ὀκταουίας· πολὺς γὰρ καὶ ἐς τήνδε ἐρρύη, ταχὺς ὢν ἐς ἔρωτας γυναικῶν. λήγοντος δὲ τοῦ χειμῶνος, ὥσπερ ἑτέρῳ γενομένῳ, ἥ τε ἐσθὴς αὖθις καὶ μετὰ τῆς ἐσθῆτος ἡ ὄψις ἐνηλλάσσετο, καὶ πλῆθος ἦν ἀμφὶ τὰς θύρας αὐτίκα σημείων τε καὶ ἡγεμόνων καὶ δορυφόρων, καὶ φόβου πάντα μεστὰ καὶ καταπλήξεως· πρεσβεῖαί τ’ ἐσεδέχοντο, αἳ τέως ἠρέμουν κεκελευσμέναι, καὶ δίκαι διεκρίνοντο, καὶ νῆες καθείλκοντο, καὶ ἡ ἄλλη παρασκευὴ πᾶσα συνεκινεῖτο.", "st": "5.76"}, {"sp": "N", "t": "καὶ Ἀντώνιος μὲν ἀμφὶ ταῦτα ἦν, Καίσαρι δὲ καὶ Πομπηίῳ διελύθησαν αἱ γενόμεναι σπονδαί, κατὰ μὲν αἰτίας, ὡς ὑπενοεῖτο, ἑτέρας, αἱ δὲ ἐς τὸ φανερὸν ὑπὸ τοῦ Καίσαρος ἐκφερόμεναι αἵδε ἦσαν. Πελοπόννησον Ἀντώνιος μὲν ἐδίδου Πομπηίῳ, κελεύων, ὅσα ἔτι ὤφειλον αὑτῷ Πελοποννήσιοι δόντα ἢ αὐτὸν ἀναδεξάμενον ἀποδώσειν παραλαβεῖν ἢ περιμεῖναι τὴν πρᾶξιν αὐτῶν. ὁ δὲ οὐκ ἐδέχετο μὲν ἐπὶ τοῖσδε τὴν χώραν, ἡγούμενος αὑτῷ σὺν τοῖς ὀφλήμασι δεδόσθαι· χαλεπαίνων δέ, ὡς ὁ Καῖσαρ ἔλεγεν, εἴτε ἐπὶ τούτοις εἴτε κατὰ γνώμην ἄπιστον εἴθ’ ὑπὸ ζήλου τῶν ἑτέρων μεγάλους στρατοὺς ἐχόντων εἴτε Μηνοδώρου διερεθίζοντος αὐτὸν ἀνοχὰς μᾶλλον ἢ βεβαίους σπονδὰς εἶναι νομίζειν, ναῦς ἄλλας ἐποιεῖτο καὶ ἐρέτας συνέλεγε καὶ τῷ στρατῷ ποτε ἐδημηγόρησε χρῆναι παντὸς οὕνεκα παρασκευάζεσθαι. λῃστήριά τε αὖθις ἀφανῆ τὴν θάλασσαν ἠνώχλει, καὶ μικρὸν ἢ οὐδὲν ἄκος τοῦ λιμοῦ γεγένητο Ῥωμαίοις, ὥστε ἐβόων οὐκ ἀπαλλαγὴν τῶν κακῶν, ἀλλ’ ἐπίληψιν τετάρτου τυράννου κατὰ σπονδὰς γεγονέναι. καὶ ὁ Καῖσάρ τινα λῃστήρια συλλαβὼν ἐβασάνιζεν, οἳ Πομπήιον σφᾶς ἔλεγον ἐπιπέμψαι· καὶ τάδε αὐτὰ ὁ Καῖσαρ τῷ δήμῳ προσέφερε καὶ ἐπέστελλεν αὐτῷ Πομπηίῳ. ὁ δὲ ἐξελογεῖτο μὲν ὑπὲρ τούτων, ἀντενεκάλει δὲ Πελοποννήσου χάριν.", "st": "5.77"}, {"sp": "N", "t": "ὅσοι δὲ τῶν ἐπιφανῶν ἦσαν ἔτι παρὰ τῷ Πομπηίῳ, ὁρῶντες αὐτὸν αἰεὶ πειθόμενον τοῖς ἀπελευθέροις, διέφθειραν ἐνίους τῶν ἀπελευθέρων, εἴτε ἀπὸ σφῶν αὐτῶν εἴτε ἐς χάριν Καίσαρος, ἐξοτρύνειν ἐπὶ Μηνοδώρῳ, Κύρνου καὶ Σαρδοῦς ἔτι ἄρχοντι, τὸν δεσπότην. οἱ δὲ καὶ αὐτοὶ φθόνῳ τῆς Μηνοδώρου δυνάμεως ἑκόντες ἐποίουν. καὶ Πομπήιος μὲν ἐς ἀλλοτρίωσιν ὑπήγετο τοῦ Μηνοδώρου, τῶν δ’ αὐτῶν ἡμερῶν Φιλάδελφος, ὁ Καίσαρος ἀπελεύθερος, πρὸς τὸν Μηνόδωρον διέπλευσε σίτου κομιδῆς οὕνεκα καὶ Μικυλίων ὁ πιστότατος τῷ Μηνοδώρῳ πρὸς Καίσαρα περὶ αὐτομολίας τοῦ Μηνοδώρου· ὑπισχνεῖτο δὲ ἐγχειριεῖν Σαρδὼ καὶ Κύρνον καὶ τρία τέλη στρατοῦ καὶ ψιλῶν πλῆθος ἕτερον. καὶ τόδε ὂν ἔργον εἴτε Φιλαδέλφου εἴτε τῶν ἐς Μηνόδωρον παρὰ Πομπηίου διαβολῶν, ὁ Καῖσαρ οὐκ εὐθὺς μέν, ἐδέξατο δ’ ὅμως, ἡγούμενος ἔργῳ τὴν εἰρήνην λελύσθαι. καὶ Ἀντώνιον ἐξ Ἀθηνῶν ἐς τὸ Βρεντέσιον ἐς ἡμέραν ῥητὴν παρεκάλει, συμβουλευσόμενος αὐτῷ περὶ τοῦδε τοῦ πολέμου· ναῦς τε μακρὰς ἐκ Ῥαβέννης καὶ στρατὸν ἐκ τῆς Κελτικῆς καὶ παρασκευὴν ἄλλην ἐς τὸ Βρεντέσιον καὶ ἐς Δικαιάρχειαν ὀξέως περιέπεμπεν, ὡς ἑκατέρωθεν ἐπιπλευσούμενος τῇ Σικελίᾳ, ἢν Ἀντωνίῳ συνδοκῇ.", "st": "5.78"}, {"sp": "N", "t": "ὁ δὲ ἦλθε μὲν ἐς τὴν τεταγμένην ἡμέραν σὺν ὀλίγοις, Καίσαρα δὲ οὐχ εὑρὼν οὐ περιέμεινεν, εἴτε τὴν γνώμην τοῦ πολέμου μεμψάμενος ὡς παράσπονδον εἴτε τὴν Καίσαρος παρασκευὴν ἰδὼν πολλὴν οὖσαν (οὐ γάρ ποτε αὐτοὺς ἀνέπαυε φόβων ἡ τῆς μοναρχίας ἐπιθυμία), εἴτε τι σημεῖον δειδισάμενος. τῶν γὰρ περικοιμωμένων αὐτοῦ τῇ σκηνῇ πρὸς θηρίων τις εὑρέθη δεδαπανημένος, ἄνευ τοῦ προσώπου μόνου, καθάπερ ἐς ἐπίδειξιν παραλελειμμένου, οὔτε τι βοήσας οὔτε τινὸς τῶν συναναπαυομένων ᾐσθημένου· καὶ λύκον ἔλεγον οἱ Βρεντέσιοι πρὸ ἕω φανῆναι τῶν σκηνωμάτων ἐκθέοντα. ἔγραφέ γε μὴν τῷ Καίσαρι μὴ λύειν τὰ συγκείμενα καὶ ἠπείλει Μηνόδωρον ἀπάξειν ὡς ἑαυτοῦ δραπέτην· γεγένητο γὰρ Πομπηίου Μάγνου, τὴν δὲ τοῦ Μάγνου περιουσίαν ὁ Ἀντώνιος ἐώνητο νόμῳ πιπρασκομένην ὡς πολεμίου.", "st": "5.79"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ἔπεμπεν ἐς Σαρδόνα καὶ Κύρνον τοὺς παραληψομένους, ἃ Μηνόδωρος ἐνεχείριζεν, ἐκρατύνετο δὲ τὰ παράλια τῆς Ἰταλίας φρουρίοις πολλοῖς, μὴ αὖθις αὐτὰ ὁ Πομπήιος ἐπιδράμοι. τριήρεις δὲ ἑτέρας ἐν Ῥώμῃ καὶ ἐν Ῥαβέννῃ προσέτασσε γίγνεσθαι καὶ στρατὸν πολὺν ἐκ τῆς Ἰλλυρίδος μετεπέμπετο· Μηνόδωρόν τε ἐλθόντα ἐλεύθερον εὐθὺς ἀπέφηνεν ἐξ ἀπελευθέρου καὶ ὧν αὐτὸς ἤγαγε νεῶν, ἐπέτρεπεν ἡγεῖσθαι, ὑποστρατηγοῦντα τῷ ναυάρχῳ Καλουισίῳ. ταῦτα μὲν δὴ καθιστάμενος ὁ Καῖσαρ καὶ παρασκευὴν ἔτι πλέονα συνάγων ἐβράδυνε καὶ τὸν Ἀντώνιον οὐ περιμείναντα ἐμέμφετο, τὴν δ’ οὖσαν ἤδη παρασκευὴν ἐκέλευε Κορνιφίκιον ἐκ Ῥαβέννης μεταγαγεῖν ἐς Τάραντα. Κορνιφικίῳ μὲν δὴ χειμὼν περιπλέοντι ἐπιγίγνεται, καὶ μόνη τῶν νεῶν ἡ ναυαρχὶς ἡ γενομένη Καίσαρι διεφθάρη· καὶ ἔδοξε τοῦτ’ ἐς τὰ μέλλοντα σημῆναι. ἐπιπολαζούσης δὲ ὑπονοίας ἔτι, ὡς παρασπόνδως ὁ πόλεμος ὅδε γίγνοιτο, τὴν ὑπόνοιαν ὁ Καῖσαρ ἐκλύων ἐπέστελλε τῇ πόλει καὶ τὸν στρατὸν αὐτὸς ἐδίδασκεν, ὅτι τὰς σπονδὰς ὁ Πομπήιος λῃστεύων τὴν θάλασσαν ἀναλύσειε καὶ τοῦθ’ οἱ λῃσταὶ κατείποιεν αὐτοῦ, κατείποι δὲ καὶ Μηνόδωρος τὴν ὅλην γνώμην, μάθοι δὲ καὶ Ἀντώνιος καὶ διὰ τοῦτο Πελοπόννησον οὐ δοίη.", "st": "5.80"}, {"sp": "N", "t": "ὡς δὲ αὐτῷ τὰ ἐν χερσὶν ἕτοιμα γεγένητο, ἐπέπλει τῇ Σικελίᾳ, αὐτὸς μὲν ἐκ Τάραντος, Καλουίσιος δὲ Σαβῖνος καὶ Μηνόδωρος ἀπὸ Τυρρηνίας· περιῄει δὲ καὶ τὸ πεζὸν ἐς Ῥήγιον, καὶ μετὰ σπουδῆς ἐταχύνετο ἅπαντα. ὁ δὲ Πομπήιος τῆς μὲν αὐτομολίας τοῦ Μηνοδώρου ἐπιπλέοντος ἤδη Καίσαρος ᾔσθετο, πρὸς δὲ τὸν ἑκατέρωθεν ἐπίπλουν αὐτὸς μὲν ὑπέμεινεν ἐν Μεσσήνῃ τὸν Καίσαρα, Καλουισίῳ δὲ καὶ Μηνοδώρῳ τὸν ἔχθιστον τῷ Μηνοδώρῳ μάλιστα τῶν ἐξελευθέρων ἑαυτοῦ Μενεκράτη προσετασσεν ἀπαντᾶν ἐπὶ στολου πολλοῦ. ὅδε οὖν ὁ Μενεκράτης ἐπιφαίνεται τοῖς πολεμίοις περὶ δείλην ἑσπέραν πελάγιος. καὶ οἱ μὲν ἐς τὸν κόλπον τὸν ὑπὲρ Κύμης συνέφυγον καὶ τὴν νύκτα ἀνεπαύοντο, καὶ Μενεκράτης ἐς Αἰναρίαν παρῆλθεν· ἠοῦς δὲ ἀρχομένης οἱ μὲν τὸν κόλπον ἐν χρῷ παρὰ τὴν γῆν αὐτὴν μηνοειδεῖ στόλῳ παρέπλεον, ἵνα μὴ αὐτοὺς διεκπλέοιεν οἱ πολέμιοι, ὁ δὲ Μενεκράτης αὐτοῖς αὖθις ἐπιφαίνεταί τε καὶ εὐθὺς ἐπλησίαζεν ὑπὸ ῥύμης καὶ τάχους· δρᾶν δὲ οὐκ ἀναγομένους ἐς τὸ πέλαγος οὐδὲν μέγα ἔχων, ἐς τὴν γῆν ἐγχρίμπτων ἐξεώθει. οἱ δὲ ἐξώκελλόν τε ὁμοῦ καὶ τὰς ἐμβολὰς ἀπεμάχοντο. ἦν δὲ τοῖς μὲν ἐς τὸ πέλαγος ἀναχώρησίς τε καὶ ἐφόρμησις, ὅτε βούλοιντο, καὶ σκαφῶν ἑτέρων ἀλλαγὴ παρὰ μέρος· οἱ δὲ ἔκαμνον ἔκ τε τῶν πετρῶν, ἐφ’ ἃς ἐπώκελλον, καὶ ὑπὸ τῆς ἀκινησίας τῶν νεῶν· πεζομαχεῖν γὰρ πρὸς ναυμαχοῦντας ἐῴκεσαν, οὔτε διώκειν οὔτε ἐκκλίνειν ἔχοντες.", "st": "5.81"}, {"sp": "N", "t": "ἐν δὲ τούτῳ Μηνόδωρος καὶ Μενεκράτης καθορῶσιν ἀλλήλους καὶ τὸν ἄλλον πόνον ἀφέντες αὐτίκα μετ’ ὀργῆς καὶ βοῆς ἀλλήλοις ἐπέπλεον, ἐν τῷδε τὴν νίκην καὶ τὸ κεφάλαιον τοῦ πολέμου τιθέμενοι, ἐν ᾧ τις αὐτῶν κρατήσειν ἔμελλεν. αἱ μὲν δὴ νῆες ἀλλήλαις ὑπὸ ῥύμης ἐνέπεσον καὶ συνέτριψαν ἡ μὲν τὸν ἔμβολον τῆς Μηνοδώρου νεώς, ἡ δὲ τὸν ταρσὸν τῆς Μενεκράτους· ἐπεὶ δὲ αὐταῖς ἑκατέρωθεν χεῖρες ἐπεβλήθησαν σιδηραῖ, τῶν μὲν νεῶν οὐδὲν ἔτι ἔργον ἦν, συνεστηκυίας ἑκατέρας, οἱ δὲ ἄνδρες ὥσπερ ἐν γῇ πόνου καὶ ἀρετῆς οὐδὲν ἀπέλειπον. ἀκόντιά τε γὰρ ἦν ἀθρόα καὶ λίθοι καὶ τοξεύματα ἐπ’ ἀλλήλους, καὶ ἐπὶ τὰς ναῦς καταρράκτας ἐρρίπτουν ἐς τὸ ἐπιέναι δι’ αὐτῶν. ὑψηλοτέρας δ’ οὔσης τῆς Μηνοδώρου νεώς, οἵ τε καταρράκται τοῖς τολμῶσιν ἦσαν εὐεπιβατώτεροι καὶ τὰ βαλλόμενα ὡς ἀφ’ ὑψηλοῦ βιαιότερα. τεθνεώτων δ’ ἤδη πολλῶν καὶ τῶν ὑπολοίπων κατατετρωμένων, ὁ μὲν Μηνόδωρος ὀβελῷ τὸν βραχίονα ἐτρώθη, καὶ ὁ ὀβελὸς ἐξῃρέθη, ὁ δὲ Μενεκράτης τὸν μηρὸν ἀκοντίῳ πολυγλώχινι Ἰβηρικῷ ὁλοσιδήρῳ, καὶ οὐκ ἦν ἐξελεῖν αὐτὸ σὺν ἐπείξει. ἀχρεῖος οὖν ὁ Μενεκράτης ἐς μάχην γενόμενος ἐπέμενε καὶ ὥς, τοὺς ἄλλους ἐποτρύνων, μέχρι λαμβανομένης τῆς νεὼς ἐς τὸν βυθὸν τοῦ πελάγους ἑαυτὸν ἔρριψεν. καὶ τὴν μὲν ναῦν ὁ Μηνόδωρος ἀνεδήσατο καὶ ἐς τὴν γῆν ἀπέπλευσεν, οὐδὲν ἔτι δρᾶν οὐδὲ ἐκεῖνος δυνάμενος.", "st": "5.82"}, {"sp": "N", "t": "καὶ τὸ μὲν λαιὸν τῆς ναυμαχίας οὕτως ἐπεπράχει. ἐκ δὲ τοῦ δεξιοῦ Καλουίσιος μέν, διαπλέων ἐς τὸ λαιόν, ἀπετέμετό τινας τῶν Μενεκράτους νεῶν καὶ ἐκφυγούσας εἰς τὸ πέλαγος ἐδίωκε, Δημοχάρης δ’, ὁ τοῦ Μενεκράτους συνεξελεύθερός τε καὶ ὑποστράτηγος, ταῖς λοιπαῖς τοῦ Καλουισίου συμπεσών, τὰς μὲν ἐς φυγὴν ἐτρέπετο, τὰς δὲ ἐς πέτρας συνήραξε, καὶ τῶν ἀνδρῶν ἐξαλομένων ἐνεπίμπρα τὰ σκάφη, μέχρι Καλουίσιος ἐκ τῆς διώξεως ἐπανιὼν τάς τε φευγούσας τῶν ἰδίων ἐπανήγαγε καὶ τὰς ἐμπιπραμένας ἐκώλυσε. καὶ νυκτὸς ἐπιλαβούσης ηὐλίσαντο πάντες, ἔνθα καὶ τῆς προτέρας.", "st": "5.83"}, {"sp": "N", "t": "ἡ μὲν δὴ ναυμαχία ἐς τοῦτο ἐτελεύτα, καὶ προῦχεν ἐν αὐτῇ τὰ Πομπηίου παρὰ πολύ· Δημοχάρης δὲ βαρυθυμῶν ἐπὶ τῷ θανάτῳ Μενεκράτους ὡς ἐπὶ ἥττῃ μεγίστῃ (δύο γὰρ οἵδε ἦσαν μάλιστα τῷ Πομπηίῳ θαλάσσης ἐργάται, Μενεκράτης τε καὶ Μηνόδωρος), ἅπαντα μεθεὶς ἐκ χειρῶν εὐθὺς ἐς Σικελίαν ἔπλει, καθάπερ οὐ τὸ Μενεκράτους σῶμα καὶ ναῦν μίαν, ἀλλὰ τὸν στόλον ὅλον ἀποβαλών.", "st": "5.83"}, {"sp": "N", "t": "ὁ δὲ Καλουίσιος ἕως μὲν ἐπιπλευσεῖσθαι τὸν Δημοχάρην προσεδόκα, παρέμενεν, ἔνθαπερ ὥρμιστο, ναυμαχεῖν οὐ δυνάμενος· αἵ τε γὰρ κράτισται τῶν νεῶν αὐτῷ διωλώλεσαν, καὶ αἱ ἕτεραι πρὸς ναυμαχίαν εἶχον ἀχρείως· ἐπεὶ δὲ ἔμαθεν οἰχόμενον ἐς Σικελίαν, ἐπεσκεύαζε τὰς ναῦς καὶ παρέπλει τὴν γῆν, τοὺς κόλπους ἐξελίσσων. ὁ δὲ Καῖσαρ ἐκ μὲν Τάραντος ἐς τὸ Ῥήγιον διεπεπλεύκει ναυσὶ πολλαῖς καὶ στρατῷ πολλῷ καὶ Πομπήιον περὶ Μεσσήνην κατειλήφει ναῦς ἔχοντα τεσσαράκοντα μόνας, ὥστε αὐτῷ παρῄνουν οἱ φίλοι, ὡς ἐν καιρῷ μάλιστα, ἐπιθέσθαι τῷ Πομπηίῳ μετὰ τοσοῦδε στόλου, ναῦς ἔχοντι ὀλίγας, μέχρι τὸ λοιπὸν ἐκείνῳ ναυτικὸν οὐ πάρεστιν. ὁ δ’ οὐκ ἐπείθετο, Καλουίσιον περιμένων καὶ λέγων οὐκ εὔβουλον εἶναι τὸ ῥιψοκίνδυνον, ἔνθα συμμαχίαν ἄλλην προσδοκῴη.", "st": "5.84"}, {"sp": "N", "t": "ὡς δὲ Δημοχάρης ἐς Μεσσήνην κατέπλευσεν, ὁ μὲν Πομπήιος αὐτόν τε Δημοχάρην καὶ Ἀπολλοφάνην, καὶ τόνδε ἀπελεύθερον ἑαυτοῦ, ναυάρχους ἀπέφηνεν ἀντὶ Μηνοδώρου καὶ Μενεκράτους· ὁ δὲ Καῖσαρ περὶ τῶν συμβεβηκότων ἀμφὶ τῇ Κύμῃ πυθόμενος ἐξέπλει τὸν πορθμόν, ὑπαντήσων τῷ Καλουισίῳ. ἀνύσαντι δ’ αὐτῷ τοῦ πόρου τὸ πλέον καὶ Στυλίδα ἤδη παραπλέοντι καὶ ἐς τὸ Σκύλλαιον ἐπικάμπτοντι, ἐκθορὼν ἐκ τῆς Μεσσήνης ὁ Πομπήιος ἐξήπτετο τῶν ὑστάτων καὶ τὰς πρόπλους ἐδίωκε καὶ πάσαις ἐνέβαλλε καὶ ἐς μάχην προυκαλεῖτο. αἱ δὲ καίπερ ἐνοχλούμεναι ἐς μὲν ναυμαχίαν οὐκ ἐπέστρεφον, Καίσαρος οὐκ ἐῶντος, εἴτε δείσαντος ἐν στενῷ ναυμαχεῖν εἴτ’ ἐπιμένοντος οἷς ἀπ’ ἀρχῆς διεγνώκει, μὴ ναυμαχεῖν δίχα τοῦ Καλουισίου· γνώμῃ δὲ αὐτοῦ παρά τε τὴν γῆν ὑπεχώρουν ἅπασαι καὶ ἐπ’ ἀγκυρῶν ἐσάλευον καὶ κατὰ πρῷραν ἀπεμάχοντο τοὺς ἐπιόντας. Δημοχάρους δ’ ἐπιστήσαντος δύο ναῦς περὶ ἑκάστην ἐθορυβοῦντο ἤδη, πρός τε τὰς πέτρας ἀρασσόμεναι καὶ πρὸς ἀλλήλας, θαλάσσης τε ἐνεπίμπλαντο· καὶ διεφθείροντο μετὰ ἀργίας καὶ αἵδε ὥσπερ αἱ περὶ Κύμην, ὁρμοῦσαί τε καὶ ἐμβαλλόμεναι πρὸς ἐχθρῶν ἐπιπλεόντων καὶ ἀναχωρούντων.", "st": "5.85"}, {"sp": "N", "t": "ὁ μὲν δὴ Καῖσαρ ἐξήλατο τῆς νεὼς ἐπὶ τὰς πέτρας καὶ τοὺς ἐκνέοντας ἐκ τῆς θαλάσσης ἀνελάμβανε καὶ ἐς τὸ ὄρος ἄνω παρέπεμπε· Κορνιφίκιος δὲ καὶ ὅσοι ἄλλοι στρατηγοὶ ἦσαν αὐτοῦ, παρακαλέσαντες ἀλλήλους, ἄνευ προστάγματος ἀπέρρηξαν τὰ ἀγκύρια καὶ ἀνήχθησαν ἐπὶ τοὺς πολεμίους, ὡς δέον τι δρῶντας παθεῖν μᾶλλον ἢ ἑστῶτας ἀμαχεὶ τοῖς ἐπιχειροῦσι προκεῖσθαι. τόλμῃ τε παραβόλῳ πρῶτον ὁ Κορνιφίκιος τὴν ναυαρχίδα τοῦ Δημοχάρους κατέσεισε καὶ εἷλε. καὶ Δημοχάρης μὲν ἐς ἑτέραν ἐξήλατο, τοιούτου δὲ ὄντος τοῦ πόνου καὶ τοῦ φθόρου ἐπεφαίνοντο ἐκ πόντου προσπλέοντες ἤδη Καλουίσιός τε καὶ Μηνόδωρος. καὶ αὐτοὺς οἱ μὲν τοῦ Καίσαρος οὐχ ἑώρων οὔτε ἀπὸ γῆς οὔτε ἐκ θαλάσσης, πελαγιώτεροι δὲ ὄντες οἱ τοῦ Πομπηίου κατεῖδον καὶ ἰδόντες ἀνεχώρουν· συνεσκόταζε γὰρ ἤδη, καὶ κεκμηκότες ἀκμῆσιν οὐκ ἐθάρρουν συμπλέκεσθαι.", "st": "5.86"}, {"sp": "N", "t": "τοῦτο μὲν δὴ συγκύρημα τοῖς ὑπολοίποις ἐκ τοῦ τέως ἀχρείου χρηστὸν ἐπιγίγνεται· νυκτὸς δὲ ἐπιλαβούσης οἱ μὲν ἐκ τῶν νεῶν ἐκπεσόντες ἐς τὰ ὄρη συνέφευγον καὶ πυρὰ πολλὰ ἔκαιον σύμβολα τοῖς ἔτι οὖσιν ἐν τῇ θαλάσσῃ καὶ διενυκτέρευον οὕτως ἄσιτοι καὶ ἀθεράπευτοι καὶ πάντων ἐνδεεῖς. καὶ αὐτοὺς ὁ Καῖσαρ, ὁμοίως ἔχων, παρεκάλει περιθέων ἐς τὴν ἕω κακοπαθῆσαι. ταλαιπωρουμένῳ δὲ αὐτῷ περὶ ταῦτα Καλουίσιος μὲν οὐδ’ ὣς ἐγιγνώσκετο προσπλέων, οὐδὲ ἀπὸ τῶν νεῶν τι χρηστὸν ἐγίγνετο, ἀσχολουμένων περὶ τὰ ναυάγια· ὑπὸ δὲ ἑτέρου δαίμονος ἀγαθοῦ τὸ τρισκαιδέκατον τέλος ἐπλησίαζε διὰ τῶν ὀρῶν καὶ περὶ τοῦ κακοῦ πυθόμενοι τοὺς κρημνούς, τῷ πυρὶ περὶ τῆς ὁδοῦ τεκμαιρόμενοι, διέδραμον καὶ καταλαβόντες τὸν αὐτοκράτορα σφῶν καὶ τοὺς συμφυγόντας ὧδε ἔχοντας καμάτου καὶ τροφῶν ἀπορίας ἐθεράπευον, ἄλλους ἄλλῃ διαλαβόντες, οἱ δὲ ταξίαρχοι τὸν αὐτοκράτορα ἐς αὐτοσχέδιον σκηνὴν ἐσαγαγόντες, οὐδενὸς τῶν οἰκετῶν αὐτῷ θεραπευτήρων παρόντων, ὡς ἐν νυκτὶ καὶ τοσῷδε ταράχῳ διερριμμένων. περιπέμψας δ’ εὐθὺς πανταχῇ τοὺς ἐξαγγελοῦντας, ὅτι σῴζοιτο, πυνθάνεται Καλουίσιον σὺν ταῖς πρόπλοις καταπλέοντα καὶ ὡς ἐπὶ δύο χρηστοῖς καὶ ἀδοκήτοις ἀνεπαύετο.", "st": "5.87"}, {"sp": "N", "t": "ἅμα δ’ ἡμέρᾳ τὴν θάλασσαν ἐφορῶν ἐθεᾶτο ναῦς ἐμπεπρησμένας τε καὶ ἡμιφλέκτους ἔτι καὶ ἡμικαύστους ἄλλας τε λελυμασμένας ἱστίων τε ὁμοῦ καὶ πηδαλίων καὶ σκευῶν ἔμπλεων τὸ πέλαγος καὶ τῶν ἔτι σῳζομένων τὰ πολλὰ πεπονηκότα. προστησάμενος οὖν τὸν Καλουισίου στόλον, ἐπεσκεύαζε τὰ ἐπείγοντα· τῶν σκαφῶν πλαγιάσας, ἠρεμούντων καὶ τῶν πολεμίων, εἴτε διὰ Καλουίσιον εἴτε αὖθις ἀναγομένοις ἐπιθέσθαι διεγνωκότων. ὧδε δὲ ἐχόντων ἑκατέρων, ἐκ μέσης ἡμέρας νότος ἐμπεσὼν ἤγειρε κῦμα βίαιον ἐν ῥοώδει καὶ στενῷ χωρίῳ. Πομπήιος μὲν οὖν ἐν Μεσσήνῃ λιμένων ἔνδον ἦν, αἱ δὲ τοῦ Καίσαρος νῆες αὖθις περὶ τραχεῖαν ἀκτὴν καὶ δύσορμον ἀρασσόμεναι ταῖς τε πέτραις καὶ ἀλλήλαις ἐπεφέροντο, οὐδὲ τῶν πληρωμάτων σφίσιν ὥστε διακρατεῖν ἐντελῶν ὄντων.", "st": "5.88"}, {"sp": "N", "t": "Μηνόδωρος μὲν οὖν, ἀρχόμενον τὸ δεινὸν ἐλπίσας πλεονάσειν, ἐς τὸ πελαγιώτερον ἀνήχθη καὶ ἐπ’ ἀγκυρῶν διεσάλευεν· ἀσθενέστερον δὲ ἔχων τὸ κῦμα διὰ τὸν βυθόν, εἰρεσίᾳ ὅμως καὶ πρὸς τόδε ἐνίστατο καρτερᾷ μὴ παραφέρεσθαι, καί τινες αὐτὸν ἐμιμοῦντο ἕτεροι. τὸ δὲ λοιπὸν πλῆθος, οἰόμενοι ταχέως τὸ πνεῦμα ἐνδώσειν ὡς ἐν ἔαρι, τὰς ναῦς ἑκατέρωθεν ἀγκύραις ἔκ τε τοῦ πελάγους καὶ ἀπὸ τῆς γῆς διεκράτουν καὶ κοντοῖς ἐξεώθουν ἀπ’ ἀλλήλων. τραχυτέρου δὲ τοῦ πνεύματος γενομένου συνεκέχυτο πάντα καὶ συνετρίβοντο αἱ νῆες, τὰς ἀγκύρας ἀπορρηγνύουσαι καὶ ἐς τὴν γῆν ἢ ἐπ’ ἀλλήλας τινασσόμεναι· βοή τε ἦν παμμιγὴς δεδιότων ὁμοῦ καὶ οἰμῳζόντων καὶ παρακελευόντων ἀλλήλοις ἐς ἀνήκοον· οὐ γὰρ ἐφικνοῦντο ἔτι τῶν λεγομένων, οὐδὲ κυβερνήτης ἰδιώτου διέφερεν οὔτε κατ’ ἐπιστήμην οὔτε προστάσσων. ἀλλ’ ὁ φθόρος ἦν ὅμοιος ἔν τε ταῖς ναυσὶν αὐταῖς καί, ὅτε τις αὐτῶν ἐκπέσοι κύματι καὶ κλύδωνι καὶ ξύλοις ἀρασσομένων· ἔγεμεν γὰρ ἡ θάλασσα ἱστίων καὶ ξύλων καὶ ἀνδρῶν καὶ νεκρῶν. εἰ δέ τις καὶ τάδε διαφυγὼν ἐκνήχοιτο ἐπὶ τὴν γῆν, συνηράσσοντο καὶ οἵδε ἐπὶ τὰς πέτρας ὑπὸ τοῦ κύματος. ὡς δὲ καὶ τὸ σπάσμα τὴν θάλασσαν ἐλάμβανεν, ὃ συνήθως ἐπιγίγνεται τῷδε τῷ πορθμῷ, τοὺς μὲν ἀήθεις καὶ τόδε ἐξέπλησσε, τὰ δὲ σκάφη τότε μάλιστα περιφερόμενα συνέπιπτεν ἀλλήλοις. καὶ τὸ πνεῦμα ἐς νύκτα χαλεπώτερον ἐγίγνετο, ὥστε μηδὲ κατὰ φῶς ἔτι, ἀλλ’ ἐν σκότῳ διόλλυσθαι.", "st": "5.89"}, {"sp": "N", "t": "οἰμωγαί τε ἀνὰ τὴν νύκτα πᾶσαν ἦσαν καὶ τῶν οἰκείων μετακλήσεις ἀνά τε τὴν γῆν διαθεόντων καὶ τοὺς ἐν τῇ θαλάσσῃ καλούντων ἐξ ὀνόματος καὶ θρηνούντων, ὅτε μὴ ἐπακούσειαν, ὡς ἀπολωλότας· ἔμπαλίν τε ἑτέρων ἀνὰ τὸ πέλαγος ὑπερκυπτόντων τὸ κῦμα καὶ ἐς βοήθειαν τοὺς ἐν τῇ γῇ παρακαλούντων. ἀμήχανα δὲ πάντα ἦν ἑκατέροις· καὶ οὐχ ἡ θάλασσα μόνη τοῖς ἐς αὐτὴν ἐσελθοῦσιν καὶ ὅσοι τῶν νεῶν ἐπεβεβήκεσαν ἔτι, ἀλλὰ καὶ ἡ γῆ τοῦ κλύδωνος οὐχ ἧσσον ἦν ἀπορωτέρα, μὴ σφᾶς τὸ κῦμα συναράξειεν ἐπὶ τὰς πέτρας. ἐμόχθουν τε χειμῶνι τῶν πώποτε μάλιστα καινοτρόπῳ, γῆς ὄντες ἀγχοτάτω καὶ τὴν γῆν δεδιότες καὶ οὔτε ἐκφυγεῖν αὐτὴν ἔχοντες ἐς τὸ πέλαγος οὔτε ὅσον ἀλλήλων διαστῆναι· ἡ γὰρ στενότης ἡ τοῦ χωρίου καὶ τὸ φύσει δυσέξοδον αὐτοῦ καὶ κλύδων ἐπιπεσὼν καὶ τὸ πνεῦμα, ὑπὸ τῶν περικειμένων ὀρῶν ἐς θυέλλας περικλώμενον, καὶ ὁ τοῦ βυθοῦ σπασμὸς ἐπὶ πάντα εἱλούμενος οὔτε μένειν οὔτε φεύγειν ἐπέτρεπε· τό τε σκότος ἠνώχλει νυκτὸς μάλιστα μελαίνης· ὅθεν ἔθνῃσκον οὐδὲ καθορῶντες ἀλλήλους ἔτι, οἱ μὲν θορυβούμενοι καὶ βοῶντες, οἱ δ’ ἐφ’ ἡσυχίας παριέμενοι καὶ τὸ δεινὸν ἐκδεχόμενοι καὶ συνεργοῦντες ἐς αὐτὸ ἔνιοι ὡς ἀπολούμενοι πάντως. γενόμενον γὰρ τὸ κακὸν κρεῖσσον ἐπινοίας καὶ τὴν ἐκ τῶν παραλόγων αὐτοὺς ἐλπίδα ἀφῃρεῖτο, μέχρι ποτὲ ἄφνω τὸ πνεῦμα προσιούσης ἡμέρας διελύετο καὶ μεθ’ ἡλίου ἐπιτολὴν πάμπαν ἐμαραίνετο. καὶ τὸ κῦμα ὅμως καὶ τότε, τοῦ πνεύματος ἐκλυθέντος, ἐπὶ πολὺ ἐτραχύνετο. καὶ τὸ δεινὸν οὐδ’ ὑπὸ τῶν ἐγχωρίων ποτὲ τηλικοῦτον ἐμνημονεύετο γενέσθαι· γενόμενον δὲ ἔθους τε καὶ νόμου κρεῖσσον διέφθειρε τῶν Καίσαρος νεῶν καὶ ἀνδρῶν τὸ πλέον.", "st": "5.90"}, {"sp": "N", "t": "ὁ δὲ καὶ τῆς προτεραίας ἡμέρας πολλὰ τῷ πολέμῳ βλαβεὶς καὶ δύο τοῖσδε συμπτώμασιν ὁμοῦ συνενεχθεὶς ἐπὶ τὸ Ἱππώνειον εὐθὺς ᾔει διὰ ὀρῶν τῶν νυκτὸς αὐτῆς ἐκείνης κατὰ σπουδήν, οὐχ ὑφιστάμενος τὴν συμφοράν, ἐν ᾧ μηδὲν εἶχεν ἐπικουρεῖν. καὶ φίλοις καὶ στρατηγοῖς ἐπέστελλε πᾶσι διὰ χειρὸς εἶναι, μή τις αὐτῷ καὶ ἑτέρωθεν ὡς ἐν κακοπραγίᾳ γένοιτο ἐπιβουλή. περιέπεμπε δὲ καὶ ἐς τὴν ἀκτὴν ἅπασαν τῆς Ἰταλίας τὰ παρόντα πεζά, μὴ ἐπιτολμήσειε καὶ τῇ γῇ διὰ τὴν εὐτυχίαν ὁ Πομπήιος. ὁ δὲ οὔτε περὶ τῆς γῆς ἐνενόησεν οὔτε τοῖς λειψάνοις τοῦ ναυαγίου παροῦσιν ἢ ἀπιοῦσι καταστάντος τοῦ κλύδωνος ἐπεχείρησεν, ἀλλ’ ὑπερεῖδεν ἐκ τῶν δυνατῶν διαζωννυμένους τὰ σκάφη καὶ ἀνέμῳ διαπλέοντας ἐς τὸ Ἱππώνειον, εἴτε τὴν συμφορὰν ἀρκεῖν οἱ νομίζων εἴτ’ ἄπειρος ὢν νίκην ἐπεξελθεῖν εἴθ’, ὥσπερ εἴρηταί μοι καὶ ἑτέρωθι, ἐπιχειρεῖν ὅλως μαλακὸς ὢν καὶ μόνον ἐγνωκὼς ἀμύνεσθαι τοὺς ἐπιπλέοντας.", "st": "5.91"}, {"sp": "N", "t": "Καίσαρι δὲ οὐδ’ ἐς ἥμισυ τῶν νεῶν περιεσώθη, καὶ τοῦτο σφόδρα πεπονηκός. καταλιπὼν δ’ ὅμως αὐτοῦ τινας ἐπιμελεῖσθαι, ἐπὶ Καμπανίαν ᾔει δυσφορῶν· οὔτε γὰρ ἄλλας ναῦς εἶχεν, δεόμενος πολλῶν, οὔτε χρόνον ἐς ναυπηγίαν, ἐπειγόμενος ὑπὸ τοῦ λιμοῦ καὶ τοῦ δήμου περὶ συμβάσεων αὖθις ἐνοχλήσαντος καὶ τὸν πόλεμον ἐπιτωθάσαντος ως παράσπονδον. χρημάτων τ’ ἔχρῃζε καὶ ἠπόρει, Ῥωμαίων οὔτε εἰσφερόντων οὔτε τοὺς πόρους ἐώντων, οὓς ἐπινοήσειε. δεινὸς δὲ ὢν ἀεὶ τὸ συμφέρον συνιδεῖν ἔπεμπε Μαικήναν ἐς Ἀντώνιον, μεταδιδάξοντα περὶ ὧν ἔναγχος ἐπεμέμφοντο ἀλλήλοις, καὶ ἐς συμμαχίαν ὑπαξόμενον. εἰ δὲ μὴ πείσειεν, ἐπενόει τοὺς ὁπλίτας ὁλκάσιν ἐπιβήσας ἐς Σικελίαν περαιοῦν καὶ τὴν θάλασσαν μεθεὶς κατὰ γῆν πόλεμον συνίστασθαι. οὕτω δ’ ἀθύμως ἔχοντι αὐτῷ ἀγγέλλεται ὁ Ἀντώνιος συνθέμενος συμμαχήσειν καὶ νίκη κατὰ Κελτῶν τῶν Ἀκυιτανῶν ἐπιφανής, ἣν Ἀγρίππας ἄγων ἐφάνη. οἵ τε φίλοι καὶ τῶν πόλεών τινες αὐτῷ ναῦς ὑπισχνοῦντο καὶ ἐποίουν.", "st": "5.92"}, {"sp": "N", "t": "ὁ μὲν δὴ καὶ τῆς λύπης ἀνίη καὶ λαμπροτέραν τῆς προτέρας παρασκευῆς συνεπήγνυτο· ἀρχομένου δ’ ἦρος ὁ μὲν Ἀντώνιος ἐξ Ἀθηνῶν ἐς Τάραντα διέπλει ναυσὶ τριακοσίαις, τῷ Καίσαρι συμμαχήσων, ὡς ὑπέσχητο, ὁ δ’ ἐνήλλακτο τὴν γνώμην καὶ ἐς τὰς ἔτι γινομένας αὑτῷ ναῦς ἀνεβάλλετο. καλούμενος δὲ αὖθις ὡς ἐπὶ ἕτοιμα καὶ ἀρκοῦντα τὰ Ἀντωνίου, ἑτέρας ἀσχολίας προύφερε καὶ δῆλος ἦν ἢ αὖθις ἐπιμεμφόμενός τι τῷ Ἀντωνίῳ ἢ τῆς συμμαχίας διὰ τὴν εὐπορίαν τὴν οἰκείαν ὑπερορῶν. χαλεπαίνων δ’ ὁ Ἀντώνιος ἐπέμενεν ὅμως καὶ αὖθις αὐτὸν ἐκάλει· τῇ τε γὰρ χορηγίᾳ τοῦ ναυτικοῦ κάμνων καὶ στρατοῦ χρῄζων ἐπὶ Παρθυαίους Ἰταλοῦ, Καίσαρι τὰς ναῦς ἐπενόει διαλλάξαι, εἰρημένον μὲν ἐν ταῖς συνθήκαις ἑκάτερον ξενολογεῖν ἐκ τῆς Ἰταλίας, δυσχερὲς δ’ ἐσόμενον αὐτῷ Καίσαρος τὴν Ἰταλίαν εἰληχότος. Ὀκταουία οὖν ἐχώρει πρὸς Καίσαρα διαιτήσουσα αὐτοῖς. καὶ ὁ μὲν ἐγκαταλελεῖφθαι τοῖς κινδύνοις ἔλεγε τοῖς ἐν πορθμῷ καταλαβοῦσιν, ἡ δὲ ἐκλελύσθαι τοῦτο διὰ Μαικήνα. ὁ δὲ τὸν Ἀντώνιον ἔφη καὶ Καλλίαν ἀπελεύθερον ἐς Λέπιδον ἐκπέμψαι, συντιθέμενον τῷ Λεπίδῳ κατὰ Καίσαρος, ἡ δὲ συνειδέναι Καλλίαν περὶ γάμων ἀπεσταλμένον· βουληθῆναι γὰρ Ἀντώνιον πρὸ τῶν Παρθυικῶν ἐκδεδόσθαι τὴν θυγατέρα τῷ παιδὶ Λεπίδου, καθάπερ ὡμολόγητο. καὶ τάδε μὲν ἡ Ὀκταουία, Ἀντώνιος δὲ καὶ τὸν Καλλίαν ἔπεμπεν, ἐς βάσανον τῷ Καίσαρι διδούς· ὁ δὲ οὐκ ἐδέξατο μέν, ἀφίξεσθαι δὲ ἔφη καὶ συμμίξειν Ἀντωνίῳ μεταξὺ Μεταποντίου καὶ Τάραντος, μέσον ἔχων ποταμὸν τὸν ἐπώνυμον.", "st": "5.93"}, {"sp": "N", "t": "κατὰ δαίμονα δ’ ἀμφοτέρων προσιόντων τῷ ῥεύματι, Ἀντώνιος ἐκ τῆς ἀπήνης καταθορὼν ἔς τι τῶν παρορμούντων σκαφῶν ἐσήλατο μόνος καὶ ἐπέρα πρὸς τὸν Καίσαρα, πιστεύον ὡς φίλῳ. καὶ ὁ Καῖσαρ ἰδὼν ἀντεμιμεῖτο, καὶ ξυμβάλλουσιν ἀλλήλοις κατὰ τὸ ῥεῦμα καὶ διήριζον, ἑκάτερος ἐκβῆναι βουλόμενος ἐς τὴν ὄχθην τοῦ ἑτέρου. ἐνίκα δὲ ὁ Καῖσαρ, ὡς καὶ πρὸς τὴν Ὀκταουίαν ἥξων ἐς Τάραντα, ἐπί τε τῆς ἀπήνης Ἀντωνίου συνήδρευεν αὐτῷ καὶ ἐν Τάραντι ἐς τὴν καταγωγὴν αὐτοῦ παρῆλθέ τε ἀφύλακτος καὶ τὴν νύκτα ὁμοίως ἀνεπαύετο χωρὶς δορυφόρων παρ’ αὐτῷ. τὰ δ’ ὅμοια καὶ παρ’ Ἀντωνίου τῆς ἐπιούσης ἐπεδείκνυτο. οὕτως αὐτοῖς ἦν συνεχὴς ἡ μεταβολή, πρός τε τὰς ὑπονοίας διὰ φιλαρχίαν καὶ ἐς τὰς πίστεις ὑπὸ χρείας.", "st": "5.94"}, {"sp": "N", "t": "τὸν μὲν οὖν ἐπίπλουν τὸν ἐπὶ Πομπήιον ὁ Καῖσαρ ἐς νέωτα ἀνεβάλλετο· ὁ δ’ Ἀντώνιος ἐπιμένειν διὰ Παρθυαίους οὐ δυνάμενος, ἀντέδοσαν ὅμως ἀλλήλοις, Καίσαρι μὲν ὁ Ἀντώνιος ναῦς ἑκατὸν εἴκοσιν, ἃς αὐτίκα πέμψας εἰς Τάραντα παρέδωκεν, Ἀντωνίῳ δὲ ὁ Καῖσαρ δισμυρίους Ἰταλοὺς ὁπλίτας, οὓς ἐπιπέμψειν ὑπισχνεῖτο· ἐδωρήσατο δὲ καὶ Ὀκταουία τὸν ἀδελφόν, αἰτήσασα παρ’ Ἀντωνίου, δέκα φασήλοις τριηριτικοῖς, ἐπιμίκτοις ἔκ τε φορτίδων νεῶν καὶ μακρῶν, καὶ τὴν Ὀκταουίαν ὁ Καῖσαρ χιλίοις λογάσι σωματοφύλαξιν, οὓς ἐπιλέξαιτο Ἀντώνιος. ἐπεὶ δὲ ὁ χρόνος αὐτοῖς ἔληγε τῆς ἀρχῆς, ἣ τοῖς τρισὶν ἐψήφιστο ἀνδράσιν, ἑτέραν ἑαυτοῖς ὥριζον πενταετίαν, οὐδὲν ἔτι τοῦ δήμου δεηθέντες. οὕτω μὲν οὖν διεκρίθησαν ἀπ’ ἀλλήλων, καὶ ὁ Ἀντώνιος εὐθὺς ἐς τὴν Συρίαν ἠπείγετο, τὴν Ὀκταουίαν παρὰ τῷ ἀδελφῷ καταλιπὼν μετὰ θυγατρὸς ἤδη γενομένης αὐτοῖς.", "st": "5.95"}, {"sp": "N", "t": "Μηνόδωρος δέ, εἴτε τις ὢν φύσει παλιμπροδότης εἴτε δείσας τήν ποτε ἀπειλὴν Ἀντωνίου, ἀπάξειν αὐτὸν εἰπόντος ὡς ἀνδράποδον πολεμοποιόν, εἴτε ἐλασσόνων ἀξιοῦσθαι νομίζων παρ’ ἃ προσεδόκησεν, εἴτε τῶν ἄλλων αὐτὸν ἐξελευθέρων τοῦ Πομπηίου συνεχῶς ὀνειδιζόντων ἐς ἀπιστίαν δεσπότου καὶ παρακαλούντων ἐπανελθεῖν Μενεκράτους ἀποθανόντος, πίστιν αἰτήσας καὶ λαβὼν ηὐτομόλησε πρὸς Πομπήιον σὺν ἑπτὰ ναυσί, Καλουίσιον τὸν ναύαρχον τοῦ Καίσαρος διαλαθών. ἐφ’ ᾧ τὸν Καλουίσιον ὁ Καῖσαρ ἀπέλυσε τῆς ναυαρχίας καὶ ἀντικατέστησεν Ἀγρίππαν.", "st": "5.96"}, {"sp": "N", "t": "ἐπεὶ δ’ ἕτοιμος ἦν ὁ στόλος, ἐκάθαιρεν αὐτὸν ὁ Καῖσαρ ὧδε. οἱ μὲν βωμοὶ ψαύουσι τῆς θαλάσσης, καὶ ἡ πληθὺς αὐτοὺς περιέστηκε κατὰ ναῦν μετὰ σιωπῆς βαθυτάτης· οἱ δὲ ἱερουργοὶ θύουσι μὲν ἑστῶτες ἐπὶ τῇ θαλάσσῃ καὶ τρὶς ἐπὶ σκαφῶν περιφέρουσιν ἀνὰ τὸν στόλον τὰ καθάρσια, συμπεριπλεόντων αὐτοῖς τῶν στρατηγῶν καὶ ἐπαρωμένων ἐς τάδε τὰ καθάρσια, ἀντὶ τοῦ στόλου, τὰ ἀπαίσια τραπῆναι. νείμαντες δὲ αὐτά, μέρος ἐς τὴν θάλασσαν ἀπορρίπτουσι καὶ μέρος ἐς τοὺς βωμοὺς ἐπιθέντες ἅπτουσι, καὶ ὁ λεὼς ἐπευφημεῖ. οὕτω μὲν Ῥωμαῖοι τὰ ναυτικὰ καθαίρουσιν.", "st": "5.96"}, {"sp": "N", "t": "ἔμελλε δ’ ὁ μὲν Καῖσαρ ἐκ Δικαιαρχείας, ὁ δὲ Λέπιδος ἐκ Λιβύης, Ταῦρος δ’ ἐκ Τάραντος ἐπιπλευσεῖσθαι τῇ Σικελίᾳ, ὡς ἂν αὐτὴν ἐξ ἠοῦς ὁμοῦ καὶ δύσεως καὶ μεσημβρίας περιλάβοιεν. καὶ τῆς ἀναγωγῆς τοῦ Καίσαρος ἡ ἡμέρα προείρητο πᾶσι, καὶ ἦν δεκάτη τροπῶν θερινῶν, ἥν τινα Ῥωμαῖοι νουμηνίαν ἔχουσι τοῦ μηνός, ὃν ἐπὶ τιμῇ τοῦ Καίσαρος τοῦ προτέρου Ἰούλιου ἀντὶ Κυιντιλίου καλοῦσι. τήνδε μὲν ὁ Καῖσαρ ὥρισε τὴν ἡμέραν, αἰσιούμενος ἴσως διὰ τὸν πατέρα νικηφόρον αἰεὶ γενόμενον· ὁ δὲ Πομπήιος Λεπίδῳ μὲν ἀντέταττε Πλένιον ἐι Λιλυβαίῳ, τέλος ὁπλιτῶν ἔχοντα καὶ ἄλλο πλῆθος ἐσκευασμένον κούφως, τὴν δὲ πρὸς ἕω καὶ δύσιν ἀκτὴν τῆς Σικελίας πᾶσαν ἐφρούρει, καὶ νήσους μάλιστα Λιπάραν τε καὶ Κοσσύραν, ἵνα μήτε Κοσσύρα Λεπίδῳ μήτε Λιπάρα Καίσαρι ἐνορμίσματα ἢ ναύσταθμα γένοιτο εὔκαιρα ἐπὶ τῇ Σικελίᾳ. τὸ δ’ ἄριστον τοῦ ναυτικοῦ ἐν Μεσσήνῃ συνεῖχεν ἐπεδρεῦον ὅπῃ δεήσειεν.", "st": "5.97"}, {"sp": "N", "t": "οὕτω μὲν ἑκάτεροι παρασκευῆς εἶχον, γενομένης δὲ τῆς νουμηνίας ἀνήγοντο πάντες ἅμα ἠοῖ, Λέπιδος μὲν ἐκ Λιβύης χιλίαις ὁλκάσι καὶ μακραῖς ἑβδομήκοντα καὶ τέλεσι στρατοῦ δυώδεκα καὶ ἱππεῦσι Νομάσι πεντακισχιλίοις καὶ ἑτέρᾳ παρασκευῇ πολλῇ, Ταῦρος δ’ ἐκ Τάραντος ταῖς Ἀντωνίου ναυσὶν ἐξ ἑκατὸν καὶ τριάκοντα δύο μόναις καὶ ἑκατόν, ἐπεὶ τῶν λοιπῶν οἱ ἐρέται χειμῶνος ἐτεθνήκεσαν, ὁ δὲ Καῖσαρ ἐκ Δικαιαρχείας, θύων ἅμα καὶ σπένδων ἀπὸ τῆς ναυαρχίδος νεὼς ἐς τὸ πέλαγος ἀνέμοις εὐδίοις καὶ Ἀσφαλείῳ Ποσειδῶνι καὶ ἀκύμονι θαλάσσῃ, συλλήπτορας αὑτῷ κατὰ ἐχθρῶν πατρῴων γενέσθαι. πρόπλοι δ’ αὐτῷ τινες τοὺς μυχοὺς τῆς θαλάσσης διηρεύνων, καὶ Ἄππιος μετὰ πλήθους νεῶν ὀπισθοφυλακῶν εἵπετο. τρίτῃ δὲ τῆς ἀναγωγῆς ἡμέρᾳ νότος ἐμπεσὼν Λεπίδου μὲν ὁλκάδας ἀνέτρεψε πολλάς, ὡρμίσθη δὲ ὅμως ἐς Σικελίαν καί, Πλένιον ἐν Λιλυβαίῳ πολιορκῶν, τινὰς τῶν πόλεων ὑπήγετο καὶ ἑτέρας ἐβιάζετο· ταῦρος δὲ ἀρχομένου τοῦ πνεύματος ἐς Τάραντα ἐπαλινδρόμει. Ἀππίου δ’ ἄρτι τὸ Ἀθηναῖον ἄκρον περιπλέοντος αἱ μὲν συνετρίβοντο τῶν νεῶν ἀμφὶ ταῖς πέτραις, αἱ δ’ ἐς τέλματα ἐξώκελλον ὑπὸ ῥύμης, αἱ δὲ καὶ διερρίφησαν οὐκ ἀσινεῖς. ὁ δὲ Καῖσαρ ἀρχομένου μὲν τοῦ χειμῶνος ἐς τὸν Ἐλεάτην κόλπον ἐρυμνὸν ὄντα συμπεφεύγει, χωρὶς ἑξήρους μιᾶς, ἣ περὶ τῇ ἄκρᾳ διελύθη· λιβὸς δὲ τὸν νότον μεταλαβόντος ὁ κόλπος ἐκυκᾶτο, ἐς τὴν ἑσπέραν ἀνεῳγμένος, καὶ οὔτε ἐκπλεῦσαι δυνατὸν ἦν ἔτι πρὸς ἐναντίον τοῦ κόλπου τὸ πνεῦμα, οὔτε κῶπαι κατεῖχον οὔτε ἄγκυραι, ἀλλ’ ἐς ἀλλήλας ἢ ἐς τὰς πέτρας ἐνηράσσοντο αἱ νῆες. καὶ νυκτὸς ἦν ἔτι τὸ δεινὸν ἀτοπώτερον.", "st": "5.98"}, {"sp": "N", "t": "ἐνδόντος δέ ποτε τοῦ κακοῦ τὰ νεκρὰ ἔθαπτεν ὁ Καῖσαρ, καὶ τοὺς τραυματίας ἐθεράπευε, καὶ τοὺς ἐκνέοντας ἐνέδυε, καὶ ὥπλιζεν ἑτέροις ὅπλοις, καὶ τὸν στόλον ἅπαντα ἐκ τῶν ἐνόντων ἀνελάμβανε. διεφθάρατο δ’ αὐτῷ νῆες βαρεῖαι μὲν ἕξ, κουφότεραι δὲ ἓξ καὶ εἴκοσι, λιβυρνίδες δὲ ἔτι πλείους. καὶ ἐς τάδε διορθούμενα τριάκοντα ἡμέρας ἀναλώσειν ἔμελλεν, ἤδη τοῦ θέρους προκόπτοντος· ὅθεν ἦν ἄριστον αὐτῷ τὸν πόλεμον ἐς τὸ μέλλον θέρος ἀναβαλέσθαι. ἐνοχλουμένου δὲ τοῦ δήμου ταῖς ἀπορίαις, ἐπεσκεύαζε τὰς ναῦς ἐς τὴν γῆν ἀνέλκων μετὰ ἐπείξεως καὶ τὰ πληρώματα τῶν διεφθαρμένων ἐς τὰς παρὰ Ταύρῳ ναῦς κενὰς ἐξέπεμπεν. ὡς δὲ ἐπὶ συμφορᾷ μείζονι, Μαικήναν μὲν ἐς Ῥώμην ἐξέπεμπε διὰ τοὺς ἐπτοημένους ἔτι πρὸς τὴν μνήμην Πομπηίου Μάγνου· οὐ γὰρ αὐτοὺς ἐξέλιπεν ἡ δόξα τοῦ ἀνδρὸς τούτου· τοὺς δὲ κληρούχους αὐτὸς ἀνὰ τὴν Ἰταλίαν ἐπέτρεχε καὶ ἐκ τοῦ φόβου τῶν γεγονότων ἀνελάμβανε. διέδραμε δὲ καὶ ἐς Τάραντα καὶ τὸ ναυτικὸν εἶδε τὸ ὑπὸ Ταύρῳ, καὶ ἐς Ἱππώνειον ἦλθε καὶ τὰ πεζὰ παρηγόρησε καὶ τὴν τῶν νεῶν ἐπισκευὴν ἐπέσπερχεν. καὶ πλησίον ἦν ἤδη καὶ ὁ δεύτερος ἐς Σικελίαν ἐπίπλους.", "st": "5.99"}, {"sp": "N", "t": "ὁ δὲ Πομπήιος οὐδ’ ἐπὶ τοιᾷδε εὐκαιρίᾳ τοσοῖσδε ναυαγίοις ἐπιχειρεῖν ἠξίου, ἀλλ’ ἔθυε μόνον θαλάσσῃ καὶ Ποσειδῶνι καὶ υἱὸς αὐτῶν ὑφίστατο καλεῖσθαι, πειθόμενος οὐκ ἄνευ θεοῦ δὶς οὕτω θέρους πταῖσαι τοὺς πολεμίους. φασὶ δ’ αὐτόν, ὑπὸ τῶνδε χαυνούμενον, καὶ τὴν συνήθη τοῖς αὐτοκράτορσι χλαμύδα ἐκ φοινικῆς ἐς κυανῆν μεταλλάξαι, εἰσποιούμενον ἄρα ἑαυτὸν τῷ Ποσειδῶνι. ἐλπίσας δ’ ἀναζεύξειν τὸν Καίσαρα, ὡς ἐπύθετο ναυπηγούμενόν τε καὶ ἐπιπλευσούμενον αὖθις αὐτοῦ θέρους, ἐξεπλήσσετο μὲν ὡς ἀμάχῳ γνώμῃ καὶ παρασκευῇ πολεμῶν, Μηνόδωρον δὲ μετὰ νεῶν ἑπτὰ ὧν ἤγαγεν ἔπεμπε κατασκεψόμενον τὰ νεώλκια τοῦ Καίσαρος καὶ δράσοντα, ὅ τι καὶ δύναιτο. ὁ δὲ καὶ τέως ἀχθόμενος οὐκ ἀποδοθείσης αὐτῷ τῆς ναυαρχίας καὶ τότε αἰσθόμενος, ὅτι σὺν ὑποψίᾳ μόνων ἠξίωτο ὧν ἤγαγε νεῶν, ἐπεβούλευεν αὖθις αὐτομολίαν.", "st": "5.100"}, {"sp": "N", "t": "ἐπινοῶν δὲ πρότερον, ὡς ἐς πάντα οἱ συνοῖσον, ἀνδραγαθίσασθαι, διέδωκε τοῖς συμπλέουσιν, ὅσον εἶχε χρυσίον, καὶ διέπλευσεν εἰρεσίᾳ τρισὶν ἡμέραις πεντακοσίους ἐπὶ χιλίοις σταδίους καὶ τοῖς προφύλαξι τῶν ναυπηγουμένων Καίσαρι νεῶν οἷα σκηπτὸς ἀφανῶς ἐμπίπτων καὶ ἐς ἀφανὲς ἀναχωρῶν ᾕρει κατὰ δύο καὶ τρεῖς ναῦς τῶν φυλακίδων καὶ τὰς ὁλκάδας, αἳ τὸν σῖτον ἔφερον, ὁρμούσας ἢ παραπλεούσας κατέδυεν ἢ ἀνεδεῖτο ἢ ἐνεπίμπρη. θορύβου δὲ πάντα μεστὰ διὰ Μηνόδωρον ἦν, Καίσαρος ἀπόντος ἔτι καὶ Ἀγρίππα· καὶ γὰρ οὗτος ἐπὶ ὕλην ἐπεπόρευτο. γαυρούμενος δὲ ὁ Μηνόδωρος ἐξώκειλέ ποτε τὴν ναῦν ἑκὼν ἐς ἕρμα γῆς ἁπαλὸν σὺν καταφρονήσει καὶ ὑπεκρίνετο αὐτὴν ὑπὸ τοῦ πηλοῦ κατέχεσθαι, μέχρι, τῶν πολεμίων ἐκ τῶν ὀρῶν καταθορόντων ὡς ἐπὶ Μηνοδώρου θήραν ἕτοιμον, ἀνακρουσάμενος ᾤχετο σὺν θαύματι.", "st": "5.101"}, {"sp": "N", "t": "ὡς δὲ ἱκανῶς ἐπεδέδεικτο, οἷος ἐχθρός τε καὶ φίλος εἴη, Ῥέβιλον μὲν ἑλών, ἄνδρα ἀπὸ βουλῆς, μεθῆκε, μνώμενος ἤδη τὸ μέλλον. Μινδίῳ δὲ Μαρκέλλῳ, τῶν ἑταίρων τινὶ τῶν Καίσαρος, φίλος ἐν τῇ προτέρᾳ γεγονὼς αὐτομολίᾳ, τοῖς μὲν ἀμφ’ αὑτὸν ἔφη τὸν Μίνδιον βουλεύειν αὐτομολίαν καὶ προδοσίαν, τοῖς δὲ πολεμίοις προσπελάσας ἠξίου Μίνδιον αὑτῷ συνελθεῖν ἔς τινα νησῖδα ἐπὶ λόγοις συνοίσουσι. καὶ συνελθόντι ἔλεγεν, οὐδενὸς ἀκούοντος ἑτέρου, φυγεῖν μὲν ἐς Πομπήιον ὑβριζόμενος ὑπὸ τοῦ τότε ναυάρχου Καλουισίου, τὴν δὲ ναυαρχίαν Ἀγρίππου μεταλαβόντος ἐπανελεύσεσθαι πρὸς Καίσαρα οὐδὲν ἀδικοῦντα, εἰ πίστιν αὑτῷ κομίσειεν ὁ Μίνδιος παρὰ Μεσσάλα τοῦ τὴν ἀποδημίαν Ἀγρίππᾳ διοικοῦντος. ἔφη δ’ ἐπανελθὼν μὲν ἰάσεσθαι λαμπροῖς τὸ ἁμάρτημα ἔργοις, μέχρι δὲ τῶν πίστεων λυμανεῖσθαί τινα τῶν Καίσαρος ὁμοίως ἐς τὸ ἀνύποπτον. καὶ ὁ μὲν αὖθις ἐλυμαίνετο, Μεσσάλας δ’ ἐνεδοίασε μὲν ὡς ἐπὶ αἰσχρῷ, ἐνέδωκε δ’ ὅμως, εἴτε πολέμου ταῦτ’ εἶναι νομίζων ἀνάγκας εἴτε καὶ τῆς Καίσαρος γνώμης τι προμαθὼν ἢ τεκμηράμενος. καὶ Μηνόδωρος μὲν αὖθις ηὐτομόλει καὶ τὸν Καίσαρα ἐλθόντα προσπίπτων ἠξίου συγγνῶναν μὴ λέγοντι τὰς αἰτίας τῆς φυγῆς· ὁ δὲ ἐς μὲν σωτηρίαν αὐτῷ συνεγίνως κε διὰ τὰς σπονδὰς καὶ ἀφανῶς ἐφυλάσσετο, τοῦς δὲ τριηράρχους αὐτοῦ μεθίει χωροῦντας ὅποι θέλοιεν.", "st": "5.102"}, {"sp": "N", "t": "ἑτοίμου δὲ τοῦ στόλου γενομένου, αὖθις ὁ Καῖσαρ ἀνήγετο καὶ ἐς Ἱππώνειον παραπλεύσας δύο μὲν τέλη πεζῶν Μεσσάλαν ἔχοντα περᾶν ἐκέλευσεν ἐς Σικελίαν ἐπὶ τὸ Λεπίδου στρατόπεδον καὶ σταθμεύειν ἐς τὸν κόλπον διελθόντα τὸν εὐθὺ Ταυρομενίου, τρία δ’ ἔπεμπεν ἐπὶ Στυλίδα καὶ πορθμὸν ἄκρον ἐφεδρεύειν τοῖς ἐσομένοις· ταῦρον δ’ ἐς τὸ Σκυλάκιον ὄρος, ὃ πέραν ἐστὶ Ταυρομενίου, περιπλεῖν ἐκ Τάραντος ἐκέλευε. καὶ ὁ μὲν περιέπλει διεσκευασμένος ἐς μάχην ὁμοῦ καὶ εἰρεσίαν· καὶ τὰ πεζὰ αὐτῷ παρωμάρτει, προερευνώντων τήν τε γῆν ἱππέων καὶ λιβυρνίδων τὴν θάλασσαν. καὶ ὁ Καῖσαρ ὧδε ἔχοντι ἐξ Ἱππωνείου ἐπιδραμὼν ἐπιφαίνεται κατὰ τὸ Σκυλάκιον, καὶ τὴν εὐταξίαν ἀποδεξάμενος ἐπανῆλθεν ἐς τὸ Ἱππώνειον. ὁ δὲ Πομπήιος, ὥς μοι προείρηται, τάς τε ἐς τὴν νῆσον ἀποβάσεις ἐφύλασσεν ἁπάσας καὶ τὰς ναῦς ἐν Μεσσήνῃ συνεῖχεν ὡς βοηθήσων, ὅποι δεήσειεν.", "st": "5.103"}, {"sp": "N", "t": "καὶ οἱ μὲν ἐν τούτῳ παρασκευῆς ἦσαν, Λεπίδῳ δὲ αὖθις ἐκ Λιβύης ἦγον αἱ ὁλκάδες τὰ λοιπὰ τοῦ στρατοῦ τέλη τέσσαρα. καὶ αὐταῖς ὑπήντα πελάγιος ἐκ Πομπηίου Παπίας καὶ διέφθειρεν ὡς φιλίους δεχομένας· ᾤοντο γὰρ σφίσι τὰς Λεπίδου συναντᾶν. αἱ δὲ βραδέως τε ὑπὸ τοῦ Λεπίδου καθείλκοντο, καὶ ὕστερον αὐτὰς προσιούσας αἱ ὁλκάδες ὡς καὶ τάσδε ἄλλας πολεμίας ἐξέκλιναν, ἕως αἱ μὲν ἐκαύθησαν, αἱ δ’ ἐλήφθησαν, αἱ δ’ ἀνετράπησαν, αἱ δ’ ἐς Λιβύην ἀνέπλευσαν. τοῦ δὲ στρατοῦ δύο μὲν τέλη διώλετο ἐν τῇ θαλάσσῃ, καί, εἴ τινες αὐτῶν ἐξενήχοντο, καὶ τούσδε Τισιηνὸς ὁ τοῦ Πομπηίου στρατηγὸς ἐκνέοντας ἐπὶ τὴν γῆν διέφθειρεν· οἱ δὲ λοιποὶ πρὸς Λέπιδον κατήχθησαν, οἱ μὲν αὐτίκα, οἱ δ’ ὕστερον. καὶ Παπίας ἀπέπλευσε πρὸς Πομπήιον.", "st": "5.104"}, {"sp": "N", "t": "ὁ δὲ Καῖσαρ ἐς μὲν Στρογγύλην, ἣ τῶν πέντε νήσων ἐστὶ τῶν Αἰόλου, παντὶ τῷ στόλῳ διέπλευσεν ἐξ Ἱππωνείου, προερευνωμένης αὐτῷ τῆς θαλάσσης· στρατὸν δὲ ἐπὶ μετώπου τῆς Σικελίας πλέονα ἰδὼν ἔν τε Πελωριάδι καὶ Μύλαις καὶ Τυνδαρίδι, εἴκασεν αὐτὸν παρεῖναι Πομπήιον καὶ τὰ μὲν ἐνθάδε Ἀγρίππᾳ διαστρατηγεῖν ἐπέτρεψεν. αὐτὸς δὲ εἰς τὸ Ἱππώνειον αὖθις ἀπέπλει καὶ ἐς τὸ Ταύρου στρατόπεδον ἐξ Ἱππωνείου σὺν τρισὶ τέλεσι μετὰ Μεσσάλα διετρόχαζεν, ὡς Ταυρομένιον αἱρήσων ἀπόντος ἔτι τοῦ Πομπηίου καὶ τὰς ἐμβολὰς αὐτῷ διχόθεν παρέξων. Ἀγρίππας μὲν οὖν ἀπὸ Στρογγύλης εἰς Ἱερὰν διέπλει καὶ τῶν Πομπηίου φρουρῶν αὐτὸν οὐχ ὑποστάντων εἷλε τὴν Ἱερὰν καὶ τῆς ἐπιούσης ἔμελλεν ἐπιχειρήσειν ἐς Μύλας Δημοχάρει τῷ Πομπηίου, τεσσαράκοντα ναῦς ἔχοντι· ὁ δὲ Πομπήιος, τὸ βίαιον ὑφορώμενος τοῦ Ἀγρίππα, ἔπεμπε τῷ Δημοχάρει ναῦς ἄλλας πέντε καὶ τεσσαράκοντα ἀπὸ Μεσσήνης. ἐξελεύθερον ἄγοντα Ἀπολλοφάνη, καὶ αὐτὸς ἐφείπετο ἄλλαις ἑβδομήκοντα.", "st": "5.105"}, {"sp": "N", "t": "Ἀγρίππας δ’ ἔτι νυκτὸς ἐξ Ἱερᾶς ἀνήγετο ταῖς ἡμίσεσι τῶν νεῶν ὡς Παπίᾳ μόνῳ ναυμαχήσων. ἐπεὶ δὲ καὶ τὰς Ἀπολλοφάνους εἶδε καὶ τὰς ἑβδομήκοντα ἑτέρωθι, Καίσαρι μὲν αὐτίκα ἐδήλου Πομπήιον ἐπὶ τῶν Μυλῶν εἶναι σὺν τῷ πλέονι ναυτικῷ, τὰς δὲ βαρείας αὐτὸς ἦγε κατὰ μέσον καὶ τὸν ἄλλον στόλον ἐξ Ἱερᾶς ἐκάλει κατὰ σπουδήν· ἐσκεύαστο δ’ ἀμφοτέροις πάντα λαμπρῶς, καὶ πύργους ἐπὶ τῶν νεῶν εἶχον κατά τε πρῷραν καὶ κατὰ πρύμναν. ὡς δὲ αὐτοῖς αἵ τε παρακελεύσεις, οἵας εἰκὸς ἦν, ἐγεγένηντο καὶ τὰ σημεῖα κατὰ ναῦν ἦρτο, ἐξώρμων ἐπ’ ἀλλήλους, οἱ μὲν κατὰ μέτωπον, οἱ δ’ ἐς περικύκλωσιν, σύν τε βοῇ καὶ ῥοθίῳ νεῶν καὶ καταπλήξει ποικίλῃ. ἦν δὲ καὶ τὰ σκάφη Πομπηίῳ μὲν βραχύτερα καὶ κοῦφα καὶ ὀξέα ἐς τὰς ἐφορμήσεις τε καὶ περίπλους, καίσαρι δὲ μείζω καὶ βαρύτερα καὶ παρ’ αὐτὸ καὶ βραδύτερα, βιαιότερα δὲ ὅμως ἐμπεσεῖν καὶ τρωθῆναι δυσπαθέστερα. τῶν τε ἀνδρῶν οἱ μὲν ναυτικώτεροι τῶν Καίσαρος ἦσαν, οἱ δὲ σθεναρώτεροι· καὶ κατὰ λόγον οἱ μὲν οὐκ ἐμβολαῖς, ἀλλὰ μόναις περιόδοις ἐπλεονέκτουν, καὶ ταρσοὺς τῶν μειζόνων ἢ πηδάλια ἀνέκλων ἢ κώπας ἀνέκοπτον ἢ ἀπεχώριζον ὅλως τὰ σκάφη καὶ ἔβλαπτον ἐμβολῆς οὐχ ἥσσονα· οἱ δὲ τοῦ Καίσαρος αὐτὰς ἐμβολαῖς ὡς βραχυτέρας ἀνέκοπτον ἢ κατέσειον ἢ διερρήγνυον καί, ὅτε συμπλακεῖεν, ἔβαλλόν τε ὡς ταπεινοτέρας ἀφ’ ὑψηλοῦ καὶ κόρακας ἢ χεῖρας σιδηρᾶς εὐκολώτερον ἐπερρίπτουν. οἱ δὲ ὅτε βιασθεῖεν, ἐξήλλοντο ἐς τὸ πέλαγος. καὶ τούσδε μὲν τὰ ὑπηρετικὰ τοῦ Πομπηίου περιπλέοντα ἀνελάμβανεν,", "st": "5.106"}, {"sp": "N", "t": "ὁ δὲ Ἀγρίππας ἵετο μάλιστα εὐθὺ τοῦ Παπίου καὶ αὐτῷ κατὰ τὴν ἐπωτίδα ἐμπεσὼν κατέσεισε τὴν ναῦν καὶ ἐς τὰ κοῖλα ἀνέρρηξεν· ἡ δὲ τούς τε ἐν τοῖς πύργοις ἀπεσείσατο καὶ τὴν θάλασσαν ἀθρόως ἐδέχετο, καὶ τῶν ἐρετῶν οἱ μὲν θαλαμίαι πάντες ἀπελήφθησαν, οἱ δ’ ἕτεροι τὸ κατάστρωμα ἀναρρήξαντες ἐξενήχοντο. Παπίας δὲ ἐς τὴν παρορμοῦσαν ἀναληφθεὶς αὖθις ἐπῄει τοῖς πολεμίοις. καὶ ὁ Πομπήιος ἐξ ὄρους ἐφορῶν τὰς μὲν ἰδίας μικρὰ ἐπωφελούσας καὶ ψιλουμένας τῶν ἐπιβατῶν, ὅτε συμπλακεῖεν, Ἀγρίππᾳ δὲ τὸν ἕτερον στόλον ἐξ Ἱερᾶς προσπλέοντα, ἀναχωρεῖν ἐσήμηνε σὺν κόσμῳ. καὶ ἀνεχώρουν ἐπιόντες τε καὶ ἀναστρέφοντες ἀεὶ κατ’ ὀλίγον. Ἀγρίππα δ’ ἐπιβαρήσαντος αὐτοῖς ἔφευγον, οὐκ ἐς τοὺς αἰγιαλούς, ἀλλ’ ὅσα τῆς θαλάσσης οἱ ποταμοὶ τεναγώδη πεποιήκεσαν.", "st": "5.107"}, {"sp": "N", "t": "καὶ Ἀγριππας, κωλυόντων αὐτὸν τῶν κυβερνητῶν μεγάλαις ναυσὶν ἐς ὀλίγον ὕδωρ ἐπιπλεῖν, πελάγιος ἐπ’ ἀγκυρῶν ἐσάλευεν ὡς ἐφορμιούμενος τοῖς πολεμίοις καὶ νυκτομαχήσων, εἰ δέοι. τῶν φίλων δ’ αὐτῷ παραινούντων μὴ ἀλόγῳ θυμῷ συμφέρεσθαι μηδὲ τὸν στρατὸν ἐκτρύχειν ἀγρυπνίᾳ καὶ πόνῳ μηδὲ πιστεύειν πολυχείμωνι θαλάσσῃ, μόλις ἑσπέρας ἀνεζεύγνυε. καὶ οἱ Πομπηιανοὶ ἐς τοὺς λιμένας παρέπλεον, τριάκοντα μὲν τῶν σφετέρων νεῶν ἀποβαλόντες, πέντε δὲ καταδύσαντες τῶν πολεμίων καὶ βλάψαντες ἄλλα ἱκανὰ καὶ βλαβέντες ὅμοια. καὶ αὐτοὺς ὁ Πομπήιος ἐπαινῶν, ὅτι τηλικαύταις ναυσὶν ἀντέσχον, τειχομαχῆσαι μᾶλλον ἔφασκεν ἢ ναυμαχῆσαι καὶ ὡς νενικηκότας ἐδωρεῖτο, καὶ ἐπήλπιζεν ἐν τῷ πορθμῷ διὰ τὸν ῥοῦν κουφοτέρους ὄντας περιέσεσθαι καὶ αὐτὸς ἔφη τι προσθήσειν ἐς τὸ τῶν νεῶν ὕψος.", "st": "5.108"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τῆς ναυμαχίας τέλος ἦν τῆς περὶ Μύλας Ἀγρίππα καὶ Παπίᾳ γενομένης· τὸν δὲ Καίσαρα ὁ Πομπήιος, ὥσπερ ἦν, ὑπολαβὼν ἐς τὸ Ταύρου στρατόπεδον οἴχεσθαι καὶ ἐπιχειρήσειν τῷ Ταυρομενίῳ, μετὰ δεῖπνον εὐθὺς ἐς Μεσσήνην περιέπλει, μέρος ἐν ταῖς Μύλαις ὑπολιπών, ἵνα αὐτὸν ὁ Ἀγρίππας ἔτι παρεῖναι νομίζοι. Ἀγρίππας μὲν δὴ διαναπαύσας τὸν στρατόν, ἐς ὅσον ἤπειγεν, ἐς Τυνδαρίδα ἐνδιδομένην ἔπλει· καὶ παρῆλθε μὲν εἴσω, μαχομένων δὲ λαμπρῶς τῶν φρουρῶν ἐξεώσθη. προσεχώρησαν δ’ ἕτεραι πόλεις αὐτῷ καὶ φρουρὰς ἐδέξαντο· καὶ αὐτὸς ἐπανῆλθεν ἐς Ἱεράν. ὁ δὲ Καῖσαρ ἤδη μὲν ἐς Λευκόπετραν ἐκ τοῦ Σκυλακίου διεπεπλεύκει, μαθὼν ἔτι ἀκριβέστερον, ὅτι ὁ Πομπήιος ἐκ Μεσσήνης ἐς Μύλας οἴχοιτο δι’ Ἀγρίππαν· ἐκ δὲ Λευκοπέτρας ἔμελλε νυκτὸς περᾶν ὑπὲρ τὸν πορθμὸν ἐς τὸ Ταυρομένιον. πυθόμενος δὲ περὶ τῆς ναυμαχίας μετέγνω μὴ κλέπτειν ἔτι τὸν διάπλουν νενικηκώς, ἀλλὰ κατὰ φῶς θαρροῦντι τῷ στρατῷ περαιοῦσθαι· καὶ γὰρ ἔτι πάντως ἡγεῖτο Πομπήιον Ἀγρίππᾳ παραμένειν. κατασκεψάμενος οὖν ἡμέρας τὸ πέλαγος ἐκ τῶν ὀρῶν, ἐπεὶ καθαρὸν ἔγνω πολεμίων, ἔπλει στρατὸν ἔχων, ὅσον αἱ νῆες ἐδέχοντο, Μεσσάλαν ἐπὶ τοῦ λοιποῦ καταλιπών, ἕως ἐπ’ αὐτὸν αἱ νῆες ἐπανέλθοιεν. ἐλθὼν δ’ ἐπὶ τὸ Ταυρομένιον προσέπεμψε μὲν ὡς ὑπαξόμενος αὐτό, οὐ δεξαμένων δὲ τῶν φρουρῶν παρέπλει τὸν ποταμὸν τὸν Ὀνοβάλαν καὶ τὸ ἱερὸν τὸ Ἀφροδίσιον καὶ ὡρμίσατο ἐς τὸν Ἀρχηγέτην, Ναξίων τὸν θεόν, ὡς χάρακα θησόμενος ἐνταῦθα καὶ ἀποπειράσων τοῦ Ταυρομενίου. ὁ δὲ Ἀρχηγέτης Ἀπόλλωνος ἀγαλμάτιόν ἐστιν, ὃ πρῶτον ἐστήσαντο Ναξίων οἱ εἰς Σικελίαν ἀπῳκισμένοι.", "st": "5.109"}, {"sp": "N", "t": "ἐνταῦθα τῆς νεὼς ἐκβαίνων ὁ Καῖσαρ ὤλισθε καὶ ἔπεσε καὶ ἀνέδραμε δι’ αὑτοῦ. καὶ αὐτῷ καθισταμένῳ ἔτι τὸ στρατόπεδον Πομπήιος ἐπέπλει στόλῳ πολλῷ, θαῦμα ἀδόκητον· ᾤετο γὰρ αὐτον ἐκπεπολεμῆσθαι πρὸς Ἀγρίππα. παρήλαυνε δὲ τῷ Πομπηίῳ καὶ ἡ ἵππος, ἐς τάχος διερίζουσα τῷ ναυτικῷ, καὶ τὰ πεζὰ ἑτέρωθεν ἐφαίνετο, ὥστε δεῖσαι μὲν ἅπαντας, ἐν μέσῳ τριῶν στρατῶν πολεμίων γενομένους, δεῖσαι δὲ τὸν Καίσαρα, Μεσσάλαν οὐκ ἔχοντα μεταπέμψασθαι. οἱ μὲν οὖν ἱππέες εὐθὺς ἠνώχλουν οἱ Πομπηίου χαρακοποιουμένους ἔτι τοὺς τοῦ Καίσαρος· εἰ δὲ ἐπὶ τοῖς ἱππεῦσιν οἱ πεζοὶ καὶ τὸ ναυτικὸν ἐφώρμησε, τάχα ἄν τι μεῖζον ἐξήνυστο τῷ Πομπηίῳ. νῦν δὲ ἀπείρως τε πολέμου, καὶ ὑπ’ ἀγνοίας τοῦ θορύβου τῶν Καίσαρος, καὶ ὄκνου, μὴ μάχης περὶ δείλην ἑσπέραν ἄρχειν, οἱ μὲν αὐτῶν ἐς Κόκκυνον ἄκραν ὡρμίσαντο, οἱ πεζοὶ δ’ οὐκ ἀξιοῦντες ἀγχοῦ τῶν πολεμίων στρατοπεδεύειν ἐς Φοίνικα πόλιν ἀνεχώρουν. καὶ νυκτὸς οἱ μὲν ἀνεπαύοντο, οἱ δὲ τοῦ Καίσαρος τὸν μὲν χάρακα ἐτέλουν, ὑπὸ δὲ κόπου καὶ ἀγρυπνίας ἐς τὴν μάχην ἐβλάπτοντο. τέλη δ’ ἦν αὐτῷ τρία καὶ ἱππέες χωρὶς ἵππων πεντακόσιοι καὶ κοῦφοι χίλιοι καὶ κληροῦχοι σύμμαχοι χωρὶς καταλόγου δισχίλιοι καὶ ναυτικὴ δύναμις ἐπὶ τούτοις.", "st": "5.110"}, {"sp": "N", "t": "τὰ μὲν οὖν πεζὰ πάντα Κορνιφικίῳ παραδοὺς ὁ Καῖσαρ ἐκέλευσε τοὺς κατὰ τὴν γῆν πολεμίους ἀπομάχεσθαι καὶ πράσσειν, ὅ τι ἐπείγοι· αὐτὸς δὲ ταῖς ναυσὶν ἔτι πρὸ ἡμέρας ἀνήγετο ἐς τὸ πέλαγος, μὴ καὶ τοῦδε αὐτὸν ἀποκλείσαιεν οἱ πολέμιοι. καὶ τὸ μὲν δεξιὸν ἐπέτρεπε Τιτινίῳ, τὸ δὲ λαιὸν Καρισίῳ, λιβυρνίδος δὲ αὐτὸς ἐπέβαινε καὶ περιέπλει πάντας παρακαλῶν· ἐπὶ δὲ τῇ παρακλήσει τὰ στρατηγικὰ σημεῖα, ὡς ἐν κινδύνῳ μάλιστα ὤν, ἀπέθετο. ἐπαναχθέντος δὲ τοῦ Πομπηίου δὶς μὲν ἐπεχείρησαν ἀλλήλοις, καὶ τὸ ἔργον ἐς νύκτα ἐτελεύτησεν. ἁλισκομένων δὲ καὶ πιμπραμένων τῶν Καίσαρος νεῶν, αἱ μὲν ἀράμεναι τὰ βραχέα τῶν ἱστίων ἀπέπλεον ἐς τὴν Ἰταλίαν, τῶν παραγγελμάτων καταφρονοῦσαι· καὶ αὐτὰς ἐπ’ ὀλίγον οἱ τοῦ Πομπηίου διώξαντες ἐπὶ τὰς ὑπολοίπους ἀνέστρεψαν, καὶ τῶνδε τὰς μὲν ᾕρουν ὁμοίως, τὰς δὲ ἐνεπίμπρασαν. ὅσοι δ’ ἐξ αὐτῶν ἐς τὴν γῆν ἐσενήχοντο, τοὺς μὲν οἱ ἱππέες οἱ τοῦ Πομπηίου διέφθειρον ἢ συνελάμβανον, οἱ δ’ ἐς τὸ τοῦ Κορνιφικίου στρατόπεδον ἀνεπήδων, καὶ αὐτοῖς ὁ Κορνιφίκιος ἐπιθέουσιν ἐπεχείρει, τοὺς κούφους ἐκπέμπων μόνους· οὐ γὰρ εὔκαιρον ἐδόκει κινεῖν φάλαγγα δύσθυμον ἀντικαθημένων πεζῶν μεγαλοφρονουμένων, ὡς εἰκὸς ἦν, ἐπὶ νίκῃ.", "st": "5.111"}, {"sp": "N", "t": "Καίσαρα δ’ ἐν τοῖς ὑπηρετικοῖς ἐς πολὺ τῆς νυκτὸς ἀνακωχεύοντα καὶ βουλευόμενον, εἴτε ἐς Κορνιφίκιον ἐπανέλθοι διὰ μέσων τοσῶνδε ναυαγίων εἴτε ἐς Μεσσάλαν διαφύγοι, θεὸς ἐς τὸν Ἀβάλαν λιμένα παρήνεγκε μεθ’ ἑνὸς ὁπλοφόρου, χωρὶς φίλων τε καὶ ὑπασπιστῶν καὶ θεραπόντων. καί τινες ἐκ τῶν ὀρῶν ἐς πύστιν τῶν γεγονότων καταθέοντες εὗρον αὐτὸν τό τε σῶμα καὶ τὴν ψυχὴν ἐσταλμένον, καὶ ἐς ἀκάτιον ἐξ ἀκατίου μεταφέροντες, ἵνα διαλάθοι, μετεκόμισαν ἐς Μεσσάλαν οὐ μακρὰν ὄντα. ὁ δ’ εὐθύς, ἔτι ἀθεράπευτος, ἔς τε Κορνιφίκιον ἔστελλε λιβυρνίδα καὶ πανταχοῦ διὰ τῶν ὀρῶν περιέπεμπεν, ὅτι σῴζοιτο, Κορνιφικίῳ τε πάντας ἐπικουρεῖν ἐκέλευε καὶ αὐτὸς ἔγραφεν αὐτίκα πέμψειν βοήθειαν. θεραπεύσας δὲ τὸ σῶμα καὶ ἀναπαυσάμενος ὀλίγον ἐς Στυλίδα νυκτὸς ἐξῄει, παραπεμπόμενος ὑπὸ τοῦ Μεσσάλα, πρὸς Καρρίναν τρία ἔχοντα ἐπὶ τοῦ πρόπλου τέλη· καὶ τῷδε μὲν ἐκέλευσε διαπλεῖν ἐς τὸ πέραν, ἔνθα καὶ αὐτὸς ἔμελλε διαπλευσεῖσθαι, Ἀγρίππαν δὲ γράφων ἠξίου κινδυνεύοντι Κορνιφικίῳ πέμπειν Λαρώνιον μετὰ στρατιᾶς ὀξέως. Μαικήναν δ’ αὖθις ἐς Ῥώμην ἔπεμπε διὰ τοὺς νεωτερίζοντας· καί τινες παρακινοῦντες ἐκολάσθησαν. καὶ Μεσσάλαν ἐς Δικαιάρχειαν ἔπεμπεν, ἄγειν τὸ πρῶτον καλούμενον τέλος ἐς Ἱππώνειον.", "st": "5.112"}, {"sp": "N", "t": "Μεσσάλας δὲ οὗτος ἦν, ὃν οἱ τρεῖς ἐπὶ θανάτῳ προγεγράφεσαν ἐν Ῥώμῃ, καὶ χρήματα τῷ κτείναντι καὶ ἐλευθερίαν ἐπικεκηρύχεσαν· ὁ δὲ πρὸς Κάσσιον καὶ Βροῦτον φυγών, ἀποθανόντων ἐκείνων, τὸν στόλον ἐπὶ σπονδαῖς Ἀντωνίῳ παραδεδώκει. καί μοι τοῦτο ἀναμνῆσαι νῦν ἔδοξεν ἐς ζήλωμα τῆς Ῥωμαίων ἀρετῆς, ὅπου Μεσσάλας, μόνον ἔχων ἐν τοσῇδε συμφορᾷ τὸν προγράψαντα, ἐθεράπευεν ὡς αὐτοκράτορα καὶ περιέσῳζε.", "st": "5.113"}, {"sp": "N", "t": "Κορνιφίκιος δὲ ἀποτρέψασθαι μὲν ἐκ τοῦ χάρακος εὐμαρῶς εἶχε τοὺς πολεμίους, κινδυνεύων δ’ ἐξ ἀπορίας ἐς μάχην ἐξέτασσε καὶ προυκαλεῖτο. Πομπηίου δὲ οὐ συμπλεκομένου μὲν ἀνδράσιν ἐν μόνῃ τῇ μάχῃ τὴν ἐλπίδα ἔχουσιν, παραστήσεσθαι δ’ αὐτοὺς τῷ λιμῷ προσδοκῶντος, ὥδευεν ὁ Κορνιφίκιος, ἐν μέσῳ τοὺς ἀπὸ τῶν νεῶν διαφυγόντας ἀνόπλους ἔχων βαλλόμενός τε καὶ χαλεπῶς, ἐν μὲν τοῖς πεδινοῖς ὑπὸ τῶν ἱππέων, ἐν δὲ τοῖς τραχέσιν ὑπὸ τῶν ψιλῶν τε καὶ κούφων, οἳ Νομάδες Λίβυες ὄντες ἠκόντιζόν τε ἐπὶ πλεῖστον καὶ τοὺς ἐπεκθέοντας ὑπέφευγον.", "st": "5.113"}, {"sp": "N", "t": "τετάρτῃ δ’ ἡμέρᾳ μόλις ἐπὶ τὴν ἄνυδρον γῆν ἀφίκοντο, ἣν ῥύακα πυρὸς λέγουσι, ποτὲ μέχρι θαλάσσης κατιοῦσαν, ἐπικλύσαι καὶ σβέσαι τὰ ἐν αὐτῇ νάματα. καὶ αὐτὴν οἱ μὲν ἐπιχώριοι μόνης ὁδεύουσι νυκτός, πνιγώδη τε οὖσαν ἀπ’ ἐκείνου καὶ κονιορτοῦ σποδώδους γέμουσαν, οἱ δ’ ἀμφὶ τὸν Κορνιφίκιον οὔτε νυκτὸς ἐθάρρουν, ἐν ἀσελήνῳ μάλιστα, ἰέναι διὰ ἀπειρίαν ὁδῶν καὶ ἐνέδρας, οὔτε ἡμέρας ὑπέμενον, ἀλλ’ ἀπεπνίγοντο καὶ τὰς βάσεις ὡς ἐν θέρει καὶ καύματι ὑπεκαίοντο, μάλιστα οἱ γυμνοί. βραδύνειν τε οὐ δυνάμενοι διὰ τὴν δίψαν ἐνοχλοῦσαν, οὐδένα ἔτι τῶν βαλλόντων αὐτοὺς ἐπεξῄεσαν, ἀλλ’ ἐτιτρώσκοντο ἀφυλάκτως. ἐπεὶ δὲ καὶ τὰς ἐξόδους τῆς διακεκαυμένης ἕτεροι κατεῖχον πολέμιοι, ἀμελήσαντες τῶν ἀσθενεστέρων τε καὶ γυμνῶν ἀνεπήδων ἐς τοὺς αὐχένας οἱ δυνάμενοι τόλμῃ παραβόλῳ καὶ ἐβιάζοντο τοὺς πολεμίους, ἐς ὅσον εἶχον δυνάμεως. κατεχομένων δὲ καὶ τῶν ἑξῆς αὐχένων ἀπεγίνωσκον αὑτῶν ἤδη καὶ μεθεῖντο ὑπὸ δίψης καὶ θέρους καὶ κόπου. προτρέποντος δὲ αὐτοὺς τοῦ Κορνιφικίου καὶ πηγὴν πλησίον οὖσαν ἐπιδεικνύοντος, οἱ μὲν αὖθις ἐβιάζοντο, πολλοὺς ἀπὸ σφῶν ἀπολλύντες, ἕτεροι δὲ τὴν πηγὴν κατεῖχον πολέμιοι, καὶ παντελὴς ἤδη τοὺς τοῦ Κορνιφικίου κατεῖχον ἀθυμία, καὶ παρίεντο.", "st": "5.114"}, {"sp": "N", "t": "ὧδε δὲ αὐτοῖς ἔχουσι Λαρώνιος ἐπιφαίνεται μακρόθεν, ὑπὸ Ἀγρίππου σὺν τρισὶ τέλεσι πεμφθείς, οὔπω μὲν ἔνδηλος ὤν, ὅτι φίλος εἴη· ὑπὸ δὲ ἐλπίδος ἀεὶ τοιοῦτον ἔσεσθαι προσδοκῶντες ἀνέφερον αὖθις αὑτῶν. ὡς δὲ καὶ τοὺς πολεμίους εἶδον τὸ ὕδωρ ἀπολιπόντας, ἵνα μὴ γένοιντο ἐχθρῶν ἐν μέσῳ, ἀνέκραγον μὲν ὑπὸ ἡδονῆς, ὅσον ἔσθενον, ἀντιβοήσαντος δ’ αὐτοῖς τοῦ Λαρωνίου δρόμῳ τὴν πηγὴν κατέλαβον. καὶ ὑπὸ μὲν τῶν ἡγεμόνων ἐκωλύοντο πίνειν ἀθρόως· ὅσοι δὲ ἠμέλησαν, ἔπινον ὁμοῦ καὶ ἀπέθνῃσκον.", "st": "5.115"}, {"sp": "N", "t": "οὕτω μὲν ἐξ ἀέλπτου Κορνιφίκιος καὶ τοῦ στρατοῦ τὸ φθάσαν μέρος περιεσώθη πρὸς Ἀγρίππαν ἐς Μύλας· ἄρτι δὲ ὁ Ἀγρίππας Τυνδαρίδα εἰλήφει, τροφῶν μεστὸν χωρίον καὶ εὐφυῶς ἐς πόλεμον ἐκ τῆς θαλάσσης ἔχον, καὶ ὁ Καῖσαρ ἐς αὐτὸ τὰ πεζὰ καὶ τοὺς ἱππέας διεβίβαζεν. ἐγένοντό τε αὐτῷ πάντες ἐν Σικελίᾳ ὁπλιτῶν μὲν ἐς εἴκοσι καὶ ἓν τέλος. ἱππέες δὲ δισμύριοι καὶ κοῦφοι πλείους τῶν πεντακισχιλίων. Μύλας δ’ ἔτι καὶ τὰ ἐκ Μυλῶν ἐπί τε Ναυλόχους καὶ Πελωριάδα καὶ τὰ παράλια πάντα φρουραὶ Πομπηίου κατεῖχον, αἳ φόβῳ μάλιστα Ἀγρίππου πῦρ διηνεκὲς ἔκαιον ὡς ἐμπρήσοντες τοὺς ἐπιπλέοντας. ἐκράτει δὲ καὶ τῶν στενῶν ἑκατέρων ὁ Πομπήιος. ἀμφὶ δὲ τὸ Ταυρομένιον καὶ περὶ Μύλας τὰς περιόδους τῶν ὀρῶν ἀπετείχιζε καὶ τὸν Καίσαρα ἐκ Τυνδαρίδος ἐς τὸ πρόσθεν ἰόντα ἠνώχλει, μὴ συμπλεκόμενον. Ἀγρίππου δὲ νομισθέντος ἐπελεῖν ἐς Πελωριάδα μετεπήδησεν, ἐκλιπὼν τὰ στενὰ περὶ Μύλας· καὶ ὁ Καῖσαρ αὐτῶν τε κατέσχε καὶ Μυλῶν καὶ Ἀρτεμισίου, πολίχνης βραχυτάτης, ἐν ᾗ φασι τὰς Ἡλίου βοῦς γενέσθαι καὶ τὸν ὕπνον Ὀδυσσεῖ.", "st": "5.116"}, {"sp": "N", "t": "ψευδοῦς δὲ τῆς Ἀγρίππου δόξης φανείσης, ὁ Πομπήιος ἡσθεὶς τῶν στενῶν ἀφῃρημένος καὶ Τισιηνὸν ἐκάλει μετὰ τοῦ στρατοῦ. Τισιηνῷ δ’ ὁ Καῖσαρ ὑπήντα καὶ διημάρτανε τῆς ὁδοῦ περὶ ὄρος τὸ Μυκόνιον, ἔνθα ἄσκηνος ἐνυκτέρευσεν· ὄμβρου τε πολλοῦ καταρραγέντος, οἷος ἐν φθινοπώρῳ γίγνεται, τῶν ὁπλοφόρων τινὲς τὴν νύκτα πᾶσαν ἀσπίδα Κελτικὴν ὑπερέσχον αὐτοῦ. ἐγένοντο δὲ καὶ βρόμοι τῆς Αἴτνης σκληροὶ καὶ μυκήματα μακρὰ καὶ σέλα περιλάμποντα τὴν στρατιάν, ὥστε τοὺς μὲν Γερμανοὺς ἐξ εὐνίων ἀναπηδᾶν ὑπὸ δέους, τοὺς δέ, ἀκοῇ τῶν περὶ τῆς Αἴτνης λεγομένων, οὐκ ἀπιστεῖν ἐν τοσοῖσδε παραδόξοις ἐμπεσεῖσθαι σφίσι καὶ τὸν ῥύακα. μετὰ δὲ τοῦτο τὴν Παλαιστηνῶν γῆν ἔκειρε, καὶ Λέπιδος αὐτῷ συνήντετο σιτολογῶν, καὶ Μεσσήνῃ παρεστρατοπέδευον ἀμφότεροι.", "st": "5.117"}, {"sp": "N", "t": "γιγνομένων δ’ ἀν’ ὅλην τὴν Σικελίαν ἁψιμαχιῶν πολλῶν, ἔργου δὲ μείζονος οὐδενός, Ταῦρον ὁ Καῖσαρ ἔπεμψε τὰς ἀγορὰς τοῦ Πομπηίου περικόπτειν καὶ τὰς πόλεις τὰς χορηγούσας προκαταλαμβάνειν. καὶ τῷδε μάλιστα κάμνων ὁ Πομπήιος ἔκρινε μάχῃ μείζονι κριθῆναι περὶ ἁπάντων. τὰ μὲν δὴ πεζὰ τοῦ Καίσαρος ἐδεδίει, ταῖς δὲ ναυσὶν ἐπαιρόμενος ἤρετο πέμπων, εἰ δέχοιτο ναυμαχίᾳ κριθῆναι. ὁ δὲ ὠρρώδει μὲν τὰ ἐνάλια πάντα, οὐ σὺν τύχῃ μέχρι δεῦρο κεχρημένος αὐτοῖς, αἰσχρὸν δὲ νομίσας ἀντειπεῖν ἐδέχετο. καὶ ὡρίζετο αὐτοῖς ἡμέρα, ἐς ἣν τριακόσιαι νῆες ἑκατέρων ἰδίᾳ παρεσκευάζοντο, βέλη τε παντοῖα φέρουσαι καὶ πύργους καὶ μηχανάς, ὅσας ἐπενόουν. ἐπενόει δὲ καὶ τὸν καλούμενον ἅρπαγα ὁ Ἀγρίππας, ξύλον πεντάπηχυ σιδήρῳ περιβεβλημένον, κρίκους ἔχον περὶ κεραίας ἑκατέρας· τῶν δὲ κρίκων εἴχετο τοῦ μὲν ὁ ἅρπαξ, σιδήριον καμπύλον, τοῦ δὲ καλῴδια πολλά, μηχαναῖς ἐπισπώμενα τὸν ἅρπαγα, ὅτε τῆς πολεμίας νεὼς ἐκ καταπέλτου λάβοιτο.", "st": "5.118"}, {"sp": "N", "t": "ἐλθούσης δὲ τῆς ἡμέρας πρῶτα μὲν ἦν ἐρετῶν ἅμιλλα καὶ βοή, καὶ βέλη τὰ μὲν ἐκ μηχανῆς, τὰ δ’ ἀπὸ χειρῶν, ὅσα λίθοι καὶ πυρφόρα καὶ τοξεύματα. μετὰ δὲ αἱ νῆες αὐταὶ συνερρήγνυντο ἀλλήλαις, αἱ μὲν εἰς τὰ πλάγια, αἱ δὲ κατ’ ἐπωτίδας, αἱ δὲ ἐπὶ τοὺς ἐμβόλους, ἔνθα μάλιστά εἰσιν αἱ πληγαὶ βίαιοι τινάξαι τε τοὺς ἐπιβάτας καὶ τὴν ναῦν ἀργοτέραν ἐργάσασθαι. ἄλλαι δὲ ἀλλήλας διεξέπλεον βάλλουσαί τε καὶ ἀκοντίζουσαι· καὶ τὰ ὑπηρετικὰ τοὺς ἐκπίπτοντας ἀνελάμβανεν. ἔργα τε χειρῶν ἦν καὶ βία ναυτῶν καὶ τέχνη κυβερνητῶν καὶ βοαὶ καὶ στρατηγῶν παρακελεύσεις καὶ μηχανήματα πάντα. εὐδοκίμει δὲ μάλιστα ὁ ἅρπαξ, ἔκ τε πολλοῦ ταῖς ναυσὶ διὰ κουφότητα ἐμπίπτων καὶ ἐμπηγνύμενος, ὅτε μάλιστα ὑπὸ τῶν καλῳδίων ἐφέλκοιτο ὀπίσω· κοπῆναί τε ὑπὸ τῶν βλαπτομένων οὐκ ἦν εὔπορος διὰ σίδηρον τὸν περιέχοντα, καὶ τὸ μῆκος αὐτοῦ δυσεφικτότατα τοῖς κόπτουσι τὰ καλῴδια ἐποίει· οὐδὲ τὸ μηχάνημά πω προέγνωστο, ὡς δρέπανα δόρασι περιθέσθαι· ἓν δ’ ἐπενόουν ὡς ἐν ἀδοκήτῳ, τὴν ναῦν κρούοντες ἐπὶ πρύμναν ἀντισπᾶν. τὸ δ’ αὐτὸ ποιούντων καὶ τῶν πολεμίων ἴση μὲν ἦν ἡ βία τῶν ἀνδρῶν, ὁ δὲ ἅρπαξ ἐποίει τὸ ἴδιον.", "st": "5.119"}, {"sp": "N", "t": "ὅτε μὲν οὖν προσπελάσειαν αἱ νῆες, ἐμάχοντο παντοίως καὶ ἐς ἀλλήλους μεθήλλοντο. καὶ διαγνῶναι τὸν πολέμιον οὐκ ἦν ἔτι ὁμοίως εὔπορον· ὅπλοις τε γὰρ ὡς τὰ πολλὰ τοῖς αὐτοῖς ἐχρῶντο καὶ φωνῇ σχεδὸν ἅπαντες Ἰταλῇ, τά τε συνθήματα μιγνυμένων ἐς ἀμφοτέρους ἐξενήνεκτο, καὶ ἐκ τοῦδε μάλιστα ἐνέδραι πολλαὶ καὶ ποικίλαι παρὰ ἀμφοῖν, καὶ ἀπιστία πρὸς τοὺς λέγοντας αὐτὰ ἐπεγίγνετο, ἀγνωσία τε πάντας ἀλλήλων ἐπεῖχεν ὡς ἐν πολέμῳ καὶ θαλάσσῃ γεμούσῃ φόνων τε καὶ ὅπλων καὶ ναυαγίων. οὐ γάρ τινα πεῖραν ἔλιπον, ὅτι μὴ μόνον τὸ πῦρ· τούτου δὲ μετὰ τοὺς πρώτους ἐπίπλους ἐφείσαντο διὰ τὰς συμπλοκάς. ὁ δὲ πεζὸς ἑκατέρων στρατὸς ἀπὸ τῆς γῆς μετὰ φόβου καὶ σπουδῆς ἐς τὴν θάλασσαν ἀφεώρων, ὡς ἐν τῇδε καὶ αὐτοὶ περὶ τῆς σφῶν σωτηρίας τὴν ἐλπίδα ἔχοντες. διέκρινόν γε μὴν οὐδέν, οὐδ’ ἐδύναντο, καὶ μάλιστα περισκοποῦντες, οἷα νεῶν ἑξακοσίων ἐπὶ μήκιστον ἐκτεταγμένων καὶ τῆς οἰμωγῆς ἐναλλασσομένης ἀνὰ μέρος ἑκατέρωθεν.", "st": "5.120"}, {"sp": "N", "t": "μόλις δέ ποτε ταῖς χροιαῖς τῶν πύργων, αἷς δὴ μόναις διέφερον ἀλλήλων, ὁ Ἀγρίππας συνεὶς πλέονας ἀπολωλέναι τοῦ Πομπηίου ναῦς ἐθάρρυνε τοὺς συνόντας ὡς ἤδη κατορθοῦντας· καὶ τοῖς πολεμίοις αὖθις ἐμπεσὼν ἐπέκειτο ἀπαύστως, μέχρι βιασθέντες, ὅσοι μάλιστα κατ’ αὐτὸν ἦσαν, τούς τε πύργους κατέρριψαν καὶ τὰς ναῦς ἐπιστρέψαντες ἐς τὸν πορθμὸν ἔφευγον. καὶ ἔφθασαν ἐσδραμεῖν ἑπτακαίδεκα νῆες. αἱ δὲ λοιπαί, διακλείσαντος αὐτὰς τοῦ Ἀγρίππου, αἱ μὲν ἐξώκελλον ἐς τὴν γῆν διωκόμεναι, καὶ συνεξώκελλον αὐταῖς ὑπὸ ὁρμῆς οἱ διώκοντες ἢ ὁρμιζομένας ἀπέσπων ἢ ἐνεπίμπρασαν· ὅσαι δὲ ἔτι κατὰ τὸ πέλαγος ἐμάχοντο, τὰ περὶ αὐτὰς γιγνόμενα κατιδοῦσαι παρεδίδοσαν ἑαυτὰς τοῖς πολεμίοις. καὶ ὁ τοῦ Καίσαρος στρατὸς ἐπινίκιον ἠλάλαξεν ἐν τῇ θαλάσσῃ, καὶ ὁ πεζὸς ἀντεβόησεν ἐπὶ τῆς γῆς. οἱ Πομπηίου δ’ ἀνῴμωξαν, καὶ αὐτὸς ἐκ τῶν Ναυλόχων ἀναθορὼν ἐς τὴν Μεσσήνην ἠπείγετο, οὐδὲν ὑπὸ ἐκπλήξεως περὶ τῶν πεζῶν οὐδ’ ἐπισκήψας· ὅθεν καὶ τούσδε ὁ Καῖσαρ Τισιηνοῦ παραδιδόντος ὑποσπόνδους ἐδέχετο καὶ τοὺς ἱππέας ἐπ’ αὐτοῖς, τῶν ἱππάρχων παραδιδόντων. κατέδυσαν δὲ ἐν τῷ πόνῳ νῆες Καίσαρος μὲν τρεῖς, Πομπηίου δὲ ὀκτὼ καὶ εἴκοσι, καὶ αἱ λοιπαὶ κατεφλέχθησαν ἢ ἐλήφθησαν ἢ ἐς τὴν γῆν ὀκέλλουσαι συνετρίβησαν· αἱ δὲ ἑπτακαίδεκα μόναι διέφυγον.", "st": "5.121"}, {"sp": "N", "t": "καὶ ὁ Πομπήιος ἐν ὁδῷ περὶ τῆς μεταγνώμης τοῦ πεζοῦ πυθόμενος τήν τε ἐσθῆτα ἤλλαξεν ἐς ἰδιώτην ἀπ’ αὐτοκράτορος καὶ προύπεμψεν ἐς Μεσσήνην ἐς τὰς ναῦς ἐντίθεσθαι τὰ δυνατά· παρεσκεύαστο δὲ ἅπαντα ἐκ πολλοῦ. Πλένιόν τε ἐκ Λιλυβαίου, μεθ’ ὧν εἶχεν ὀκτὼ τελῶν, ἐκάλει κατὰ σπουδὴν ὡς μετὰ τῶνδε φευξόμενος. καὶ Πλένιος μὲν ἠπείγετο πρὸς αὐτόν, αὐτομολούντων δὲ ἑτέρων, φίλων τε καὶ φρουρίων καὶ στρατῶν, καὶ τῶν πολεμίων ἐς τὸν πορθμὸν ἐσπλεόντων, οὐκ ἀναμείνας οὐδὲ Πλένιον ὁ Πομπήιος ἐν πόλει καλῶς τετειχισμένῃ, ἔφευγεν ἐκ τῆς Μεσσήνης ἐπὶ τῶν ἑπτακαίδεκα νεῶν ἐς Ἀντώνιον, ὡς ἐξ ὁμοίων αὐτῷ τὴν μητέρα περισεσωκώς. καὶ ὁ Πλένιος αὐτὸν οὐ καταλαβὼν ἐς τὴν Μεσσήνην παρῆλθε καὶ κατεῖχε τῆς πόλεως. ὁ δὲ Καῖσαρ αὐτὸς μὲν ἔμεινεν ἐν τῷ περὶ Ναυλόχους στρατοπέδῳ, Ἀγρίππαν δ’ ἐκέλευσε τῇ Μεσσήνῃ παρακαθέζεσθαι· καὶ παρεκάθητο σὺν Λεπίδῳ. Πλενίου δὲ πρεσβευομένου περὶ σπονδῶν Ἀγρίππας μὲν ἠξίου περιμένειν Καίσαρα ἐς ἕω, Λέπιδος δὲ ἐδίδου τὰς σπονδὰς καὶ τὸν τοῦ Πλενίου στρατὸν οἰκειούμενος ἑαυτῷ συνεχώρει διαρπάσαι τὴν πόλιν μετὰ τοῦ ἄλλου στρατοῦ.", "st": "5.122"}, {"sp": "N", "t": "καὶ οἱ μὲν ἐπὶ τῇ σωτηρίᾳ, περὶ ἧς δὴ καὶ μόνης παρεκάλουν, κέρδος ἀδόκητον εὑρόμενοι, τὴν Μεσσήνην ὅλῃ τῇ νυκτὶ μετὰ τῶν Λεπίδου διήρπαζον καὶ μετεστρατεύοντο τῷ Λεπίδῳ· ὁ δὲ σὺν τούτοις ἔχων δύο καὶ εἴκοσι τέλη πεζῶν καὶ ἱππέας πολλοὺς ἐπῆρτο καὶ κρατήσειν ἐδόκει Σικελίας, πρόφασιν ἔχων, ὅτι πρῶτος ἐπιβαίη τῆς νήσου καὶ πλέονας πόλεις ἐπαγάγοιτο· ἔς τε τὰ φρούρια αὐτίκα περιέπεμπε τοὺς παρὰ τοῦ Καίσαρος ἐλευσομένους μὴ προσίεσθαι καὶ τὰ στενὰ πάντα ἐκρατύνετο. ὁ δὲ Καῖσαρ ἦλθε μὲν τῆς ἐπιούσης καὶ ἐμέμφετο τῷ Λεπίδῳ διὰ τῶν φίλων, οἳ σύμμαχον αὐτὸν ἔφασκον ἐλθεῖν Καίσαρι ἐς Σικελίαν, οὐχ ἑαυτῷ κατακτησόμενον αὐτὴν· ὁ δὲ ἀντενεκάλει τῆς προτέρας τάξεως ἀφῃρῆσθαι καὶ μόνον ἔχειν αὐτὴν Καίσαρα βουλομένῳ τε νῦν ἀντιδιδόναι Λιβύην καὶ Σικελίαν ὑπὲρ ἐκείνης. χαλεπαίνων δ’ ὁ Καῖσαρ ἦλθε μὲν καὶ αὐτὸς ὑπὸ ὀργῆς, ὀνειδιῶν τὸν Λέπιδον ἐς χαριστίαν, διαπειλησάμενοι δὲ ἀλλήλοις διέστησαν, καὶ αὐτίκα αἵ τε φυλακαὶ διεκρίθησαν καὶ αἱ νῆες ὥρμουν ἐπ’ ἀγκυρῶν· ἐλέχθη γὰρ αὐτὰς ἐπινοεῖν ὁ Λέπιδος ἐμπρῆσαι.", "st": "5.123"}, {"sp": "N", "t": "ὁ δὲ στρατὸς ἤχθετο, εἰ πολεμήσουσιν αὖθις ἐμφύλιον πόλεμον ἕτερον καὶ οὔ ποτε σφᾶς ἐπιλείψουσιν αἱ στάσεις. οὐ μὴν ἐν ὁμοίῳ Καίσαρα καὶ Λέπιδον ἐτίθεντο, οὐδὲ οἱ τῷ Λεπίδῳ στρατευόμενοι, ἀλλὰ καὶ τῆς ἀρετῆς τὸν Καίσαρα ἐθαύμαζον καὶ τὴν ἀργίαν συνῄδεσαν Λεπίδῳ, καὶ τῆς ἁρπαγῆς αὐτὸν ἐπεμέμφοντο αὐτῆς, ἐς τὸ ἴσον τοῖς ἡσσημένοις καταστάντες. ὧν ὁ Καῖσαρ πυνθανόμενος περιέπεμπε τοὺς τὰ συμφέροντα παραινέσοντας κρύφα ἑκάστοις. ὡς δὲ αὐτῷ διεφθάρατο πολλοί, καὶ μάλιστα οἱ γενόμενοι τοῦ Πομπηίου διὰ δέος τοῦ μήπω τὰς σπονδὰς βεβαίους σφίσιν, εἰ μὴ συνθοῖτο ὁ Καῖσαρ, εἶναι, ἀγνοοῦντος ἔτι ταῦτα τοῦ Λεπίδου δι’ ἀπραξίαν ὁ Καῖσαρ ἐπῆλθεν ἐπὶ τὸ στρατόπεδον αὐτοῦ σὺν ἱππεῦσι πολλοῖς, οὓς πρὸ τοῦ χάρακος καταλιπὼν ἐσῄει μετ’ ὀλίγων, καὶ παριὼν ἐπεμαρτύρετο ἑκάστοις ἄκων ἐς πόλεμον καθίστασθαι. ἀσπαζομένων δὲ αὐτὸν ὡς αὐτοκράτορα τῶν ὁρώντων, οἱ Πομπηιανοὶ πρῶτοι συνέθεον, ὅσοι διεφθάρατο, καὶ συγγνῶναι σφίσι παρεκάλουν. ὁ δ’ ἔλεγε θαυμάζειν, εἰ συγγνώμην αἰτοῦντες οὐ πράσσουσιν οὔπω τὰ σφίσιν αὐτοῖς συνοίσοντα. οἱ δὲ συνέντες αὐτίκα ἥρπαζον τὰ σημεῖα καὶ ἐς τὸν Καίσαρα μετέφερον, καὶ σκηνὰς ἔλυον ἕτεροι.", "st": "5.124"}, {"sp": "N", "t": "καὶ τοῦ θορύβου Λέπιδος αἰσθόμενος ἐξέθορε τῆς σκηνῆς ἐπὶ τὰ ὅπλα. βολαί τε ἦσαν ἤδη, καὶ τῶν ὁπλοφόρων τις τῶν Καίσαρος ἔπιπτε, καὶ αὐτὸς ὁ Καῖσαρ ἐς τὸν θώρακα ἐβλήθη· τὸ δὲ βέλος οὐκ ἐξίκετο ἐπὶ τὸν χρῶτα, ἀλλὰ δρόμῳ διέφυγεν ἐπὶ τοὺς ἱππέας. Λεπίδου δέ τι φρούριον ἐπετώθασε τῷ δρόμῳ· καὶ οὐκ ἀνέσχεν ὁ Καῖσαρ ὑπὸ ὀργῆς, πρὶν ἐξελεῖν αὐτὸ σὺν τοῖς ἱππεῦσι καὶ καθελεῖν. ἑτέρων δ’ αὖ φρουρίων ἡγεμόνες, οἱ μὲν αὐτίκα, οἱ δὲ νυκτός, μετετίθεντο ἐκ Λεπίδου πρὸς Καίσαρα, οἱ μὲν ἄνευ τινὸς πείρας, οἱ δὲ καὶ ἐς ὑπόκρισιν ὑπὸ ἱππέων μικρὰ ἐνοχληθέντες. εἰσὶ δ’ οἳ τὰς προσβολὰς ἔτι ὑπέμενον καὶ ἀπεκρούοντο· καὶ γὰρ ὁ Λέπιδος περιέπεμπεν ἐς πάντα ἐπικούρους· καὶ αὐτῶν δὲ τῶν ἐπικούρων μεθισταμένων ἡ λοιπὴ τοῦ Λεπίδου στρατιά, καὶ εἴ τις εὔνους ἔτι ἦν, ἐτρέπετο τῇ γνώμῃ. καὶ πρῶτοι μὲν αὖθις οἱ Πομπηιανοί, ὅσοι ἔτι ἦσαν παρ’ αὐτῷ, μετεπήδων κατὰ μέρη· Λεπίδου δὲ ἐς κώλυσιν αὐτοῖς τοὺς ἑτέρους ἐφοπλίσαντος, οἳ ἐπὶ κώλυμα τῶν ἄλλων ὁπλισάμενοι τὰ ἑαυτῶν ἐπήγοντο σημεῖα καὶ σὺν τοῖς ἑτέροις ἐχώρουν πρὸς τὸν Καίσαρα. Λέπιδος δ’ αὐτοῖς ἀπιοῦσιν ἠπείλει καὶ ἐδεῖτο καὶ τῶν σημείων εἴχετο καὶ οὐ μεθήσειν ἔλεγε, μέχρι τῶν φερόντων αὐτά τις εἶπε μεθήσειν ἀποθανόντα καὶ δείσας μεθῆκεν.", "st": "5.125"}, {"sp": "N", "t": "οἱ δὲ ἱππέες τελευταῖοι χωροῦντες ἔπεμψάν τινα πευσόμενοι τοῦ Καίσαρος, εἰ κτείνωσι Λέπιδον, οὐκέτι ὄντα αὐτοκράτορα· ὁ δὲ ἀπεῖπεν. οὕτω Λέπιδος, ἀδοκήτῳ πάντων ἀπιστίᾳ συμπεσών, ἔρημος ἐκ τύχης τοσῆσδε καὶ στρατοῦ τοσοῦδε ἐγίγνετο ἐν βραχεῖ. καὶ τὸ σχῆμα ἀλλάξας ἔθει πρὸς τὸν Καίσαρα δρόμῳ, συντρεχόντων ὡς ἐπὶ θέᾳ τῶν ὁρώντων. ὁ δὲ Καῖσαρ ὑπανέστη τε αὐτῷ προσθέοντι καὶ προσπεσεῖν ἐθέλοντα κωλύσας ἔπεμψεν ἐς Ῥώμην, ἐφ’ οὗπερ ἦν σχήματος, ἰδιώτην ἀπ’ αὐτοκράτορος, οὐδὲν ἔτι πλὴν ἱερέα ἧς εἶχεν ἱερωσύνης.", "st": "5.126"}, {"sp": "N", "t": "ὁ μὲν δὴ καὶ αὐτοκράτωρ πολλάκις καὶ τῶν τριῶν ἀνδρῶν γενόμενος ἄρχοντάς τε ἀποφήνας καὶ προγράψας ἐπὶ θανάτῳ τοσούσδε ὁμοτίμους, ἰδιωτεύων καὶ ἐνίοις τῶν προγραφέντων ἄρχουσιν ὕστερον παριστάμενος διεβίωσε. Πομπήιον δὲ ὁ μὲν Καῖσαρ οὐκ ἐδίωκεν οὐδ’ ἑτέροις ἐπέτρεπε διώκειν, εἴτε ὡς ἐς ἀλλοτρίαν ἀρχὴν τὴν Ἀντωνίου φυλασσόμενος ἐμβαλεῖν, εἴτε καραδοκῶν τὸ μέλλον καὶ τὰ ἐς αὐτὸν ἐσόμενα ἐξ Ἀντωνίου καὶ πρόφασιν ἕξων διαφορᾶς, εἰ μὴ δίκαια γίγνοιτο (οὐ γὰρ ἀνύποπτοί γε ἦσαν ἐκ πολλοῦ διὰ φιλαρχίαν, ὅτε τοὺς ἄλλους ἐξέλοιεν, ἀλλήλοις διερίσειν), εἴθ’, ὡς αὐτὸς ἔλεγεν ὕστερον ὁ Καῖσαρ, ὅτι μὴ γένοιτο τοῦ πατρὸς ἀνδροφόνος ὁ Πομπήιος. τὴν δὲ στρατιὰν συνῆγε, καὶ ἐγένετο αὐτῷ τέλη μὲν ὁπλιτῶν πέντε καὶ τεσσαράκοντα καὶ ἱππέες δισμύριοι καὶ πεντακισχίλιοι, κοῦφοι δὲ τῶν ἱππέων ὑπὲρ ἡμιολίους μακραί τε νῆες ἑξακόσιαι· τὸ δὲ τῶν φορτίδων πλῆθος, καίπερ ὂν ἄπειρον, τοῖς δεσπόταις διέπεμπε. καὶ τὸν στρατὸν ἐπινικίοις ἐδωρεῖτο, τὰ μὲν ἤδη διδούς, τά δὲ ὑπισχνούμενος, στεφάνους τε καὶ τιμὰς ἅπασιν ἔνεμεν καὶ συγγνώμην τοῖς ἡγεμόσιν ἐδίδου τοῦ Πομπηίου.", "st": "5.127"}, {"sp": "N", "t": "ζήλου δὲ αὐτῷ γέμοντι ἐπὶ τούτοις τὸ δαιμόνιον ἐνεμέσησε τοῦ ζήλου, καὶ ὁ στρατὸς ἐστασίασεν, ὁ οἰκεῖος αὐτοῦ μάλιστα, ἀπολυθῆναί τε τῆς στρατείας ἐπειγόμενοι καὶ γέρα λαβεῖν ὅμοια τοῖς ἐν Φιλίπποις ἀγωνισαμένοις. ὁ δὲ ᾔδει μὲν οὐχ ὅμοιον ἐκείνῳ τόνδε τὸν ἀγῶνα, ὑπισχνεῖτο δ’ ὅμως τὰ ἄξια δώσειν σὺν τοῖς ὑπ’ Ἀντωνίῳ στρατευομένοις, ὅτε κἀκεῖνος ἀφίκηται. περὶ δὲ τῆς ἀστρατείας ὑπεμίμνησκε σὺν ἀπειλῇ τῶν πατρίων νόμων τε καὶ ὅρκων καὶ κολάσεων. οὐκ εὐπειθῶς δὲ ἀκροωμένων ὑφῆκε τῆς ἀπειλῆς, ἵνα μή τις ἐκ τῶν νεολήπτων στρατῶν ἐπιγένοιτο θόρυβος, καὶ ἔλεγεν ἐν καιρῷ τε ἀπολύσειν σὺν Ἀντωνίῳ, καὶ ἄξειν νῦν οὐκ ἐπ’ ἐμφύλια ἔτι, πεπαυμένα σὺν τύχῃ χρηστῇ, ἐπὶ δ’ Ἰλλυριοὺς καὶ ἕτερα ἔθνη βάρβαρα, σαλεύοντα τὴν μόλις κτηθεῖσαν εἰρήνην, ὅθεν καταπλουτιεῖν αὐτούς. οἱ δ’ οὐκ ἔφασαν αὖθις στρατεύσεσθαι, πρὶν τῶν προτέρων λαβεῖν γέρα τε καὶ τιμάς. ὁ δὲ οὐκ ἔφη τὰς τιμὰς οὐδὲ νῦν ἀνατίθεσθαι, πολλὰς δὲ δοὺς προστιθέναι στεφάνους ἔτι τοῖς τέλεσιν ἄλλους καὶ λοχαγοῖς καὶ χιλιάρχοις περιπορφύρους ἐσθῆτας καὶ βουλευτικὴν ἐν ταῖς πατρίσιν ἀξίωσιν. ἔτι δὲ αὐτοῦ τοιάδε προστιθέντος ἕτερα, ὑπεφώνησε χιλίαρχος Ὀφίλλιος στεφάνους μὲν καὶ πορφύραν εἶναι παισὶν ἀθύρματα, στρατοῦ δὲ γέρα χωρία καὶ χρήματα· καὶ τοῦ πλήθους ἐπιβοήσαντος, ὅτι ὀρθῶς λέγοι, ὁ μὲν Καῖσαρ ἀπέστη τοῦ βήματος δυσχεραίνων. οἱ δὲ ἀμφὶ τὸν χιλίαρχον ἦσαν ἐπαινοῦντές τε καὶ τοῖς οὐ συνισταμένοις αὐτῷ λοιδορούμενοι. ὁ δ’ ἔφη καὶ μόνος ἀρκέσειν ἐπὶ οὕτω δικαίοις.", "st": "5.128"}, {"sp": "N", "t": "ἀλλ’ ὁ μὲν τόδε εἰπὼν ἐς τὴν ἐπιοῦσαν ἀφανὴς ἦν, καὶ οὐδ’, ὅ τι γένοιτο, ἐγινώσκετο· ὁ δὲ στρατὸς οὐκέτι μέν, ὑπὸ δέους, οὐδεὶς καθ’ ἕνα ἐφθέγγετο, κοινῇ δ’ ἐβόων, ἀνὰ μέρη συνιστάμενοι, ἀφεθῆναι τῶν στρατειῶν. ὁ δὲ Καῖσαρ αὐτῶν τοὺς μὲν ἄρχοντας ἐξωμίλει ποικίλως, τῶν δ’ ἐν Φιλίπποις καὶ Μουτίνῃ στρατευσαμένων, ὡς χρονιωτέρων ἄρα ὄντων, ἐδίδου τοῖς θέλουσιν ἀποστρατεύεσθαι. καὶ γενομένους ἐς δισμυρίους εὐθὺς ἀπέλυε καὶ ἐξέπεμπε τῆς νήσου, μὴ διαφθείραιεν ἑτέρους, τοσόνδε τοῖς ἐκ Μουτίνης μόνοις ἐπειπών, ὅτι σφίσιν ἀποδώσει τὰ τότε ὑπεσχημένα καίπερ οὕτως ἀπολυθεῖσιν. ἐς δὲ τὸ ἄλλο πλῆθος ἐπελθὼν τοὺς μὲν ἀποστάντας ἐμαρτύρετο τῆς ἐπιορκίας, οὐ κατὰ γνώμην τοῦ αὐτοκράτορος τῆς στρατείας ἀπολυθέντας, τοὺς δὲ παρόντας ἐπῄνει καὶ ἐπήλπιζεν ἀπολύσειν μὲν ταχέως, ὅτε μηδενὶ μετανοήσει, καταπλουτιεῖν δὲ ἀπολύων καὶ νῦν ἐπιδιδόναι δραχμὰς πεντακοσίας ἑκάστῳ. τοιάδε εἰπὼν Σικελίᾳ μὲν ἐπέβαλλεν ἐσφορὰν χίλια τάλαντα καὶ ἑξακόσια, στρατηγοὺς δ’ ἀπέφαινε Λιβύης καὶ Σικελίας καὶ στρατὸν ἐς ἑκατέραν διῄρει καὶ τὰς ναῦς τὰς Ἀντωνίου διέπεμπεν ἐς Τάραντα καὶ τοῦ λοιποῦ στρατοῦ τὸν μὲν προύπεμπεν ἐς τὴν Ἰταλίαν ἐπὶ νεῶν, τὸν δ’ ἐπαγόμενος αὐτὸς ἐκ τῆς νήσου διεπέρα.", "st": "5.129"}, {"sp": "N", "t": "ἐρχομένῳ δ’ ἥ τε βουλὴ τιμὰς ἐψηφίσατο ἀμέτρους, ὧν αὐτὸν ἐποίουν κριτήν, ἢ πάσας λαβεῖν ἢ ὅσας δοκιμάσειε· καὶ ὑπήντων ὅτι πορρωτάτω καὶ αὐτοὶ καὶ ὁ δῆμος ἐστεφανωμένοι ἔς τε τὰ ἱερὰ καὶ ἐκ τῶν ἱερῶν ἐς τὴν οἰκίαν ἀπιόντα παρέπεμπον. τῆς δ’ ἐπιούσης αὐτὸς ἐβουληγόρησέ τε καὶ ἐδημηγόρησε, τὰ ἔργα καὶ τὴν πολιτείαν ἑαυτοῦ τὴν ἀπ’ ἀρχῆς ἐς τότε καταλέγων· καὶ τὰ εἰρημένα συγγράψας τὸ βιβλίον ἐξέδωκε. κατήγγελλέ τε εἰρήνην καὶ εὐθυμίαν, ἐς τέλος τῶν ἐμφυλίων ἀνῃρημένων, καὶ τῶν εἰσφορῶν τοὺς ἔτι ὀφείλοντας ἀπέλυε καὶ φόρων τελώνας τε καὶ τοὺς τὰ μισθώματα ἔχοντας ὧν ἔτι ὀφείλοιεν. ἐκ δὲ τῶν ἐψηφισμένων τιμῶν ἐδέχετο πομπήν, ἐτήσιόν τε ἱερομηνίαν εἶναι, καθ’ ἃς ἡμέρας ἐνίκα, καὶ ἐπὶ κίονος ἐν ἀγορᾷ χρύσεος ἑστάναι μετὰ σχήματος οὗπερ ἔχων εἰσῆλθε, περικειμένων τῷ κίονι νεῶν ἐμβόλων. καὶ ἕστηκεν ἡ εἰκών, ἐπιγραφὴν ἔχουσα, ὅτι “τὴν εἰρήνην ἐστασιασμένην ἐκ πολλοῦ συνέστησε κατά τε γῆν καὶ θάλασσαν”.", "st": "5.130"}, {"sp": "N", "t": "τοῦ δὲ δήμου τὴν μεγίστην ἱερωσύνην ἐς αὐτὸν ἐκ Λεπίδου μεταφέροντος, ἣν ἕνα ἔχειν νενόμισται μέχρι θανάτου, οὐκ ἐδέχετο καὶ κτείνειν τὸν Λέπιδον ὡς πολέμιον κελευόντων οὐκ ἠνείχετο. ἐς δὲ τὰ στρατόπεδα πάντα σεσημασμένας ἔπεμψεν ἐπιστολάς, ἐντελλόμενος ἡμέρᾳ μιᾷ πάντας ἀνειλήσαντας αὐτὰς ἐπιχειρεῖν τοῖς κεκελευσμένοις. καὶ ἦν τὰ ἐπεσταλμένα περὶ τῶν θεραπόντων, ὅσοι παρὰ τὴν στάσιν ἀποδράντες ἐστρατεύοντο, καὶ αὐτοῖς τὴν ἐλευθερίαν ᾐτήκει Πομπήιος, καὶ ἡ βουλὴ καὶ αἱ συνθῆκαι δεδώκεσαν. οἱ δὲ μιᾶς ἡμέρας συνελαμβάνοντο. καὶ ἀχθέντας αὐτοὺς ἐς Ῥώμην ὁ Καῖσαρ ἀπέδωκεν αὐτῶν τε Ῥωμαίων καὶ Ἰταλῶν τοῖς δεσπόταις ἢ διαδόχοις αὐτῶν, ἀπέδωκε δὲ καὶ Σικελιώταις. ὅσους δ’ οὐκ ἦν ὁ ληψόμενος, ἔκτεινε παρὰ ταῖς πόλεσιν αὐταῖς, ὧν ἀπέδρασεν.", "st": "5.131"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τῶν τότε στάσεων ἐδόκει τέλος εἶναι. καὶ ἦν ὁ Καῖσαρ ἐτῶν ἐς τότε ὀκτὼ καὶ εἴκοσι, καὶ αὐτὸν αἱ πόλεις τοῖς σφετέροις θεοῖς συνίδρυον. λῃστευομένης δὲ κατὰ συστάσεις τῆς τε Ῥώμης αὐτῆς καὶ τῆς Ἰταλίας περιφανῶς καὶ τῶν γιγνομένων ἁρπαγῇ μετὰ τόλμης ἢ λῃστείᾳ λανθανούσῃ μᾶλλον ἐοικότων, Σαβῖνος ὑπὸ Καίσαρος αἱρεθεὶς εἰς διόρθωσιν πολὺν μὲν εἰργάσατο φθόρον τῶν ἁλισκομένων, ἐνιαυτῷ δ’ ὅμως εἰς εἰρήνην ἀφύλακτον ἅπαντα περιήγαγε. καὶ ἐξ ἐκεινου φασὶ παραμεῖναι τὸ τῆς στρατιᾶς τῶν νυκτοφυλάκων ἔθος τε καὶ εἶδος. θαυμαζόμενος δὲ ὁ Καῖσαρ ἐπὶ τῷδε ὀξέως οὕτως ἐξ ἀδοκήτου διωρθωμένῳ πολλὰ τῆς πολιτείας ἐφίει τοῖς ἐτησίοις ἄρχουσι διοικεῖν κατὰ τὰ πάτρια, καὶ γραμματεῖα, ὅσα τῆς στάσεως σύμβολα, ἔκαιε, καὶ τὴν ἐντελῆ πολιτείαν ἔλεγεν ἀποδώσειν, εἰ παραγένοιτο ἐκ Παρθυαίων Ἀντώνιος· πείθεσθαι γὰρ κἀκεῖνον ἐθέλειν ἀποθέσθαι τὴν ἀρχήν, τῶν ἐμφυλίων καταπεπαυμένων. ἐφ’ οἷς αὐτον εὐφημοῦντες εἵλοντο δήμαρχον ἐς ἀεί, διηνεκεῖ ἄρα ἀρχῇ προτρέποντες τῆς προτέρας ἀποστῆναι. ὁ δὲ ἐδέξατο μὲν καὶ τήνδε, Ἀντωνίῳ δὲ ἐφ’ ἑαυτοῦ περὶ τῆς ἀρχῆς ἐπέστελλεν. ὁ δὲ καὶ Βύβλον ἀπιόντα πρὸς αὐτὸν ἐντυχεῖν ἐδίδασκεν· ἐς δὲ τὰ ἔθνη τοὺς ἡγεμόνας αὐτὸς ὁμοίως ἔπεμπε καὶ ἐς Ἰλλυριοὺς ἐπενόει συστρατεύειν.", "st": "5.132"}, {"sp": "N", "t": "Πομπήιος δ’ ἐκ μὲν Σικελίας ἄκρᾳ Λακινίᾳ προσέσχε καὶ τὸ ἱερὸν τῆς Ἥρας πλουτοῦν ἀναθήμασιν ἐσύλησε, φεύγων ἐς Ἀντώνιον· ἐς δὲ Μιτυλήνην καταχθεὶς διέτριβεν, ἔνθα αὐτὸν ἔτι παῖδα μετὰ τῆς μητρὸς ὑπεξέθετο ὁ πατήρ, Γαΐῳ Καίσαρι πολεμῶν, καὶ ἡττηθεὶς ἀνέλαβεν. Ἀντωνίου δὲ πολεμοῦντος ἐν Μηδίᾳ Μήδοις τε καὶ Παρθυαίοις, γνώμην ὁ Πομπήιος ἐποιεῖτο ἑαυτὸν ἐπανελθόντι ἐπιτρέψαι. ἐπεὶ δ’ ἐπύθετο ἡσσῆσθαι Ἀντώνιον καὶ τὸ συμβὰν ἡ φήμη μειζόνως μετέφερεν, αὖθις ἦν ἐν ἐλπίσιν ὡς ἢ διαδεξόμενος Ἀντώνιον, εἰ τέθνηκεν, ἢ μεριούμενος ἐπανελθόντι· ἐνθύμιός τέ οἱ συνεχὲς ἦν Λαβιηνὸς οὐ πρὸ πολλοῦ τὴν Ἀσίαν ἐπιδραμών. ὧδε δὲ ἔχοντι ἀγγέλλεται Ἀντώνιος εἰς Ἀλεξάνδρειαν ἐπανελθών. καὶ τεχνάζων ἔτι ἐπ’ ἀμφότερα διεπρεσβεύετο πρὸς αὐτόν, ἐπιτρέπων ἐκείνῳ καὶ φίλον εἶναι διδοὺς καὶ σύμμαχον, ἔργῳ δὲ τὰ Ἀντωνίου κατασκεπτόμενος. ἔς τε Θρᾴκην καὶ ἐς τὸν Πόντον ἔπεμπεν ἑτέρους κρύφα πρὸς τοὺς ἑκατέρων δυνάστας ἐπινοῶν, εἰ μὴ κρατεῖ τῶν ἐνθυμουμένων, διὰ τοῦ Πόντου φυγεῖν ἐς Ἀρμενίαν. ἔπεμπε δὲ καὶ ἐς Παρθυαίους, ἐλπίσας ἐς τὰ λοιπὰ τοῦ πολέμου τοῦ πρὸς Ἀντώνιον αὐτοὺς δέξεσθαι προθύμως στρατηγὸν Ῥωμαῖόν τε καὶ παῖδα Μάγνου μάλιστα. τάς τε ναῦς ἐπεσκεύαζε καὶ τὸν ἐν αὐταῖς στρατὸν ἐγύμναζεν, ὑποκρινόμενος ἢ δεδιέναι Καίσαρα ἢ Ἀντωνίῳ τάδε παρασκευάζειν.", "st": "5.133"}, {"sp": "N", "t": "ὁ δὲ Ἀντώνιος πυθόμενος μὲν εὐθὺς ἀμφὶ τοῦ Πομπηίου, στρατηγὸν ἐπ’ αὐτῷ Τίτιον ᾕρητο καὶ ναῦς καὶ στρατὸν ἐκ Συρίας λαβόντα ἐκέλευε πολεμοῦντι μὲν τῷ Πομπηίῳ πολεμεῖν κατὰ κράτος, ἐπιτρέποντα δὲ αὑτὸν Ἀντωνίῳ μετὰ τιμῆς ἄγειν. ἐλθοῦσι δὲ τοῖς πρέσβεσιν ἐχρημάτιζεν, ἀγγέλλουσιν οὕτως·", "st": "5.134"}, {"sp": "N", "t": "“ἡμᾶς Πομπήιος ἔπεμψεν οὐκ ἀπορῶν μὲν ἐς Ἰβηρίαν, εἰ πολεμεῖν ἐγνώκει, διαπλεῦσαι, φίλην οὖσαν αὐτῷ πατρόθεν καὶ συλλαβοῦσαν ἔτι ὄντι νεωτέρῳ καὶ καλοῦσαν ἐπὶ ταῦτα καὶ νῦν, αἱρούμενος δὲ εἰρηνεύειν τε σὺν σοὶ καὶ πολεμεῖν, εἰ δεήσειεν, ὑπὸ σοί. καὶ τάδε οὐ νῦν πρῶτον, ἀλλ’ ἔτι κρατῶν Σικελίας καὶ τὴν Ἰταλίαν πορθῶν, ὅτε σοι τὴν σὴν μητέρα περισώσας ἔπεμπε, προύτεινε. καὶ εἰ ἐδέξω, οὔτ’ ἂν ὁ Πομπήιος ἐξέπεσε Σικελίας (οὐ γὰρ ἂν Καίσαρι τὰς ναῦς κατ’ αὐτοῦ παρέσχες), οὔτ’ ἂν σὺ ἥττησο ἐν Παρθυαίοις, Καίσαρός σοι τὸν στρατὸν οὐ πέμψαντος, ὃν συνέθετο· ἐκράτεις δ’ ἂν ἤδη πρὸς οἷς εἶχες καὶ τῆς Ἰταλίας. οὐ δεξάμενον δέ σε ταῦτα, ἐν καιρῷ τότε μάλιστ’ ἄν σοι γενόμενα, ἀξιοῖ καὶ νῦν μὴ πολλάκις ὑπὸ Καίσαρος ἐνεδρευθῆναι λόγοις τε καὶ τῷ γενομένῳ κήδει, μνημονεύοντα, ὅτι Πομπηίῳ τε κηδεύων μετὰ συνθήκας ἐπολέμησεν ἄνευ προφάσεως, καὶ Λέπιδον κοινωνὸν ὄντα τῆς ἀρχῆς τὸ μέρος ἀφείλετο καὶ οὐδέτερα αὐτῶν ἐνείματό σοι.", "st": "5.134"}, {"sp": "N", "t": "“λοιπὸς δ’ ἐς τὴν περιπόθητον αὐτῷ μοναρχίαν σὺ νῦν ὑπολείπῃ· ἤδη γάρ σοι καὶ ἐν χερσὶν ἦν, εἰ μὴ Πομπήιος ἔτι ἦν ἐν μέσῳ. καὶ τάδε εἰκὸς μὲν καὶ σὲ προορᾶν ἐπὶ σεαυτοῦ, προφέρει δέ σοι καὶ Πομπήιος ὑπὸ εὐνοίας, αἱρούμενος ἄνδρα ἄκακον καὶ μεγαλόφρονα ἀντὶ ὑπούλου τε καὶ δολεροῦ καὶ φιλοτέχνου. οὐδὲ ἐπιμέμφεταί σοι τῆς δόσεως τῶν νεῶν, ἃς ἐπ’ αὐτὸν Καίσαρι ἔδωκας ὑπ’ ἀνάγκης, ἀντιλαβεῖν στρατὸν ἐς Παρθυαίους δεόμενος, ἀλλ’ ὑπομιμνήσκει, τὸν οὐ πεμφθέντα στρατὸν προφέρων. συνελόντι δὲ εἰπεῖν, Πομπήιος ἑαυτὸν ἐπιτρέπει σοι μετὰ τῶν νεῶν, ἃς ἔτι ἔχει, καὶ τοῦ στρατοῦ, πιστοτάτου γε ὄντος αὐτῷ καὶ οὐδ’ ἐν τῇ φυγῇ καταλιπόντος, εἰρηνεύοντι μὲν μέγα κλέος, εἰ τὸν Μάγνου παῖδα περισῴζοις, πολεμοῦντι δὲ μοῖραν ἱκανὴν ἐς τὸν ἐσόμενον πόλεμον, ὅσον οὔπω παρόντα.”", "st": "5.135"}, {"sp": "N", "t": "τοιαῦτα τῶν πρέσβεων εἰπόντων, ὁ Ἀντώνιος τὰς ἐντολὰς αὐτοῖς ἐξέφερεν, ἃς ἐντείλαιτο Τιτίὼ· καὶ εἰ τῷ ὄντι ταῦτα φρονοίη Πομπήιος, ἥξειν αὐτὸν ἔφασκεν παραπεμπόμενον ὑπὸ Τιτίου. ἅμα δὲ ταῦτα ἐγίγνετο, καὶ οἱ πεμφθέντες ἐς Παρθυαίους ὑπὸ τοῦ Πομπηίου ἐλήφθησαν ὑπὸ τῶν Ἀντωνίου στρατηγῶν καὶ ἐς Ἀλεξάνδρειαν ἤχθησαν. καὶ ὁ Ἀντώνιος ἕκαστα μαθὼν ἐκάλει τοὺς τοῦ Πομπηίου πρέσβεις καὶ τοὺς ληφθέντας αὐτοῖς ὑπεδείκνυεν. οἱ δὲ καὶ ὣς παρῃτοῦντο νέον ἄνδρα ἐν συμφοραῖς ἐσχάταις ὑπὸ δέους, εἰ ἄρα μὴ προσοῖτο φιλίως αὐτὸν ὁ Ἀντώνιος, ἀναγκασθέντα καὶ τῶν ἀεὶ Ῥωμαίοις ἐχθίστων ἀποπειρᾶσαι· δηλώσειν τ’ αὐτὸν αὐτίκα, ὅτε μάθοι τὰ Ἀντωνίου, μηδὲν ἔτι πείρας ἢ μηχανῆς δεόμενον. οἷς ὁ Ἀντώνιος ἐπίστευσεν, ὢν καὶ τὰ ἄλλα αἰεὶ τὸ φρόνημα ἁπλοῦς καὶ μέγας καὶ ἄκακος.", "st": "5.136"}, {"sp": "N", "t": "ἐν τούτῳ δὲ Φούρνιος, ὁ τῆς Ἀσίας ἡγούμενος Ἀντωνίῳ, τὸν Πομπήιον ἐλθόντα μὲν καὶ ἀτρεμοῦντα ἐδέχετο, οὔτε κωλύειν ἀξιόμαχος ὢν οὔτε πω τὴν γνώμην εἰδὼς τὴν Ἀντωνίου· γυμνάζοντα δὲ τὸν στρατὸν ὁρῶν κατέλεγέ τινας ἐκ τῶν ὑπηκόων καὶ Ἀηνόβαρβον ἄρχοντα γείτονος στρατοῦ καὶ Ἀμύνταν ἑτέρωθεν ἐκάλει κατὰ σπουδήν. συνελθόντων δ’ ὀξέως, ὁ Πομπήιος ἐμέμφετο, εἰ πολέμιον ἡγοῦνται τὸν πρέσβεις ἐς Ἀντώνιον ἀπεσταλκότα καὶ τὰ παρ’ ἐκείνου περιμένοντα. καὶ ταῦτα λέγων Ἀηνόβαρβον ὅμως ἐπενόει συλλαβεῖν ἐκ προδοσίας Κουρίου τινὸς τῶν ἀμφὶ τὸν Ἀηνόβαρβον, ἐλπίζων ἐς ἀντίδοσιν αὑτοῦ μεγάλην ἕξειν μοῖραν Ἀηνόβαρβον. γνωσθείσης δ’ οὖν τῆς προδοσίας, Κούριος μὲν ἐν τοῖς παροῦσι Ῥωμαίων ἐλεγχθεὶς ἀπέθανε, Πομπήιος δὲ Θεόδωρον ἐξελεύθερον, ὃς μόνος οἱ συνῄδει τὸ βούλευμα, ὡς ἐξειπόντα ἔκτεινεν. οὐκέτι δὲ τοὺς ἀμφὶ τὸν Φούρνιον λήσειν ἐλπίσας, Λάμψακον ἐκ προδοσίας κατέλαβεν, ἣ πολλοὺς εἶχεν Ἰταλοὺς ἐξ ἐποικίσεως Γαΐου Καίσαρος, καὶ μισθοῖς μεγάλοις εὐθὺς ἐστράτευε τοὺς Ἰταλούς. ἤδη δὲ ἔχων ἱππέας τε διακοσίους καὶ πεζοὺς τρία τέλη, ἐπεχείρησε Κυζίκῳ κατά τε γῆν καὶ διὰ θαλάσσης. οἱ δὲ αὐτὸν ἑκατέρωθεν ἀπεκρούσαντο· καὶ γάρ τις ἦν ἐν τῇ Κυζίκῳ στρατὸς οὐ πολὺς Ἀντωνίῳ, φύλακες τῶν ἐκεῖ τρεφομένων αὐτῷ μονομάχων. ἐς δὲ τὸν Ἀχαιῶν λιμένα ἐπανελθὼν ἐσιτολόγει.", "st": "5.137"}, {"sp": "N", "t": "Φουρνίου δὲ οὐκ ἄρχοντος μὲν χειρῶν, ἀεὶ δ’ αὐτῷ παραστρατοπεδεύοντος σὺν ἱππεῦσι πολλοῖς καὶ σιτολογεῖν οὐκ ἐῶντος οὐδὲ προσποιεῖσθαι τὰς πόλεις, ὁ Πομπήιος ἱππέας οὐκ ἔχων ἐπεχείρησε τῷ τοῦ Φουρνίου στρατοπέδῳ κατὰ μέτωπον καὶ κατόπιν ἐκ περιόδου λαθών. ὅθεν ὁ Φούρνιος ἐς τὸν Πομπήιον ἐπεστραμμένος ὑπὸ τῶν ὄπισθεν ἐξεβλήθη τοῦ στρατοπέδου. καὶ φεύγοντας αὐτοὺς διὰ τοῦ Σκαμανδρίου πεδίου διώκων ὁ Πομπήιος ἔκτεινε πολλούς· καὶ γὰρ ἦν τὸ πεδίον ὑγρὸν ἐξ ὄμβρων. οἱ δὲ περισωθέντες τότε μὲν ὑπεχώρουν, οὐκ ὄντες ἀξιόμαχοι. προσδεχομένων δὲ ἀπό τε Μυσίας καὶ τῆς Προποντίδος καὶ ἑτέρωθεν, οἳ πενόμενοι διὰ τὰς συνεχεῖς εἰσφορὰς ἐμισθοφόρουν ἀσμένως τῷ Πομπηίῳ κατὰ δόξαν μάλιστα τῆς ἐν Ἀχαιῶν λιμένι γενομένης νίκης, ἱππικοῦ δ’ ἀπορῶν ὁ Πομπήιος, καὶ παρ’ αὐτὸ βλαπτόμενος ἐν ταῖς προνομαῖς, ἐπύθετο ἴλην ἱππέων Ἰταλικὴν ἐς Ἀντώνιον χωρεῖν, ὑπὸ Ὀκταουίας χειμεριζούσης ἐν Ἀθήναις ἀπεσταλμένην· καὶ εὐθὺς ἔπεμπέ τινας ἐς διαφθορὰν τῆς ἴλης μετὰ χρυσίου.", "st": "5.138"}, {"sp": "N", "t": "ἀλλὰ τούσδε μὲν ὁ τῆς Μακεδονίας ἡγούμενος Ἀντωνίῳ συνέλαβε καὶ τὸ χρυσίον τοῖς ἱππεῦσι διένειμεν· ὁ δὲ Πομπήιος Νίκαιάν τε καὶ Νικομήδειαν καταλαβὼν ἐχρηματίζετο λαμπρῶς, καὶ ἐς μεγάλα ταχέως αὐτῷ πάντα ηὔξετο παρ’ ἐλπίδα. Φουρνίῳ δὲ οὐ μακρὰν παραστρατοπεδεύοντι πρῶται μὲν ἧκον ἐκ Σικελίας, ἦρος ἀρχομένου, νῆες ἑβδομήκοντα, ὅσαι περιεσώθησαν ἐξ ὧν Ἀντώνιος ἐκεχρήκει κατὰ Πομπηίου Καίσαρι (μετὰ γὰρ τὸ Σικελικὸν ἔργον αὐτὰς ὁ Καῖσαρ ἀπέλυσεν), ἧκεν δὲ καὶ ἐκ Συρίας Τίτιος ἑτέραις ἑκατὸν εἴκοσι ναυσὶ καὶ στρατῷ πολλῷ, καὶ κατῆραν ἅπαντες ἐς Προκόννησον. δείσας οὖν ὁ Πομπήιος τὰς ναῦς ἐνέπρησε καὶ τοὺς ἐρέτας ὥπλισεν, ὡς ἄμεινον ὁμοῦ πᾶσι κατὰ τὴν γῆν συνοισόμενος. Κάσσιος δὲ ὁ Παρμήσιος καὶ Νασίδιος καὶ Σατορνῖνος καὶ Θέρμος καὶ Ἀντίστιος ὅσοι τε ἄλλοι τῶν ἀξιολόγων ἔτι τῷ Πομπηίῳ παρῆσαν φίλοι, καὶ ὁ τιμιώτατος αὐτῷ Φάννιος καὶ ὁ κηδεστὴς αὐτοῦ Πομπηίου Λίβων ὡς εἶδον αὐτὸν οὐδὲ Τιτίου παρόντος, ὅτῳ τὰ περὶ αὐτὸν Ἀντώνιος ἐπέτρεπε, παυόμενον τοῦ πρὸς τὸν ἀμείνονα πολέμου, ἀπέγνωσαν αὐτοῦ καὶ πράξαντες ὑπὲρ ἑαυτῶν πίστιν ἐς Ἀντώνιον μετῆλθον.", "st": "5.139"}, {"sp": "N", "t": "ὁ δ’ ἔρημος ὢν ἤδη φίλων ἐς τὰ μεσόγαια τῆς Βιθυνίας ἀνεχώρει, λεγόμενος ἐς Ἀρμενίους ἐπείγεσθαι. καὶ αὐτόν, νυκτὸς ἀναζεύξαντα ἀφανῶς, ἐδίωκεν ὅ τε Φούρνιος καὶ ὁ Τίτιος, καὶ ἐπ’ ἐκείνοις Ἀμύντας. συντόνῳ δὲ δρόμῳ περὶ ἑσπέραν καταλαβόντες ἐστρατοπέδευσαν ἕκαστος ἐφ’ ἑαυτοῦ περὶ λόφῳ τινί, ἄνευ τάφρου καὶ χάρακος, ὡς ἐν ἑσπέρᾳ καὶ κόπῳ. ὧδε δὲ αὐτοῖς ἔχουσιν ὁ Πομπήιος νυκτὸς ἐπέθετο πελτασταῖς τρισχιλίοις καὶ πολλοὺς ἔκτεινεν εὐναζομένους ἔτι καὶ ἀναπηδῶντας· οἱ δὲ καὶ γυμνοὶ πάμπαν αἰσχρῶς ἔφευγον. καὶ δοκεῖ τότε ὁ Πομπήιος ἅπαντι τῷ στρατῷ νυκτὸς ἐπελθὼν ἢ τῆς γε τροπῆς γενομένης ἐπαγαγὼν τάχ’ ἂν αὐτῶν ἐντελῶς ἐπικρατῆσαι. νῦν δ’ ὁ μὲν καὶ ταῦτα θεοῦ βλάπτοντος ὑπερεῖδε καὶ οὐδὲν ἐπ’ ἔργῳ τοιῷδε πλέον ἢ αὖθις ἐς τὸ μεσόγαιον ἐχώρει· οἱ δ’ ἁλισθέντες εἵποντο καὶ σιτολογοῦντα ἠνώχλουν, ἕως κινδυνεύων ὑπὸ τῆς ἀπορίας ἠξίωσεν ἐς λόγους ἐλθεῖν Φουρνίῳ, φίλῳ τε Μάγνου γεγενομένῳ καὶ ἀξιώσει προύχοντι τῶν ἄλλων καὶ βεβαιοτέρῳ τὸν τρόπον.", "st": "5.140"}, {"sp": "N", "t": "ποταμὸν δ’ ἐν μέσῳ λαβὼν ἔλεγε μὲν, ὅτι πρεσβεύσαιτο πρὸς Ἀντώνιον, ἐπετίθει δ’, ὅτι τροφῶν ἐν τοσούτῳ δεόμενος καὶ ἀμελούμενος ὑπὸ αὐτῶν, τάδε ἐργάσαιτο. “ὑμεῖς δὲ εἰ μὲν Ἀντωνίου γνώμῃ πολεμεῖτέ μοι, κακῶς ὁ Ἀντώνιος ὑπὲρ ἑαυτοῦ βουλεύεται, τὸν ἐπιόντα πόλεμον οὐ προορῶν· εἰ δὲ τὴν Ἀντωνίου γνώμην φθάνετε, μαρτύρομαι καὶ παρακαλῶ περιμεῖναι τὴν πρεσβείαν μου τὴν ἐς Ἀντώνιον ἀπεσταλμένην ἢ λαβόντας ἄγειν ἤδη πρὸς αὐτόν. ἐπιτρέψω δ’ ἐμαυτὸν ἐγὼ σοὶ μόνῳ, Φούρνιε, τοσοῦτον ἐς πίστιν αἰτήσας, ὅτι με σῶον ἄξεις ἐς Ἀντώνιον·” ὁ μὲν οὕτως εἶπεν, Ἀντωνίῳ τε θαρρῶν ὡς ἀγαθῷ τὴν φύσιν καὶ μόνα τὰ ἐν μέσῳ δεδιώς· ὁ δὲ Φούρνιος αὐτὸν οὕτως ἠμείψατο·", "st": "5.141"}, {"sp": "N", "t": "“ἐπιτρέποντος μὲν ἦν ἑαυτὸν Ἀντωνίῳ χωρεῖν ἐς αὐτὸν ἐξ ἀρχῆς ἢ περιμένειν ἀτρεμοῦντα ἐν Μιτυλήνῃ τὰς ἀποκρίσεις, πολεμοῦντος δέ, ἃ πεποίηκας ἅπαντα· τί γὰρ αὐτὰ δεῖ πρὸς εἰδότα λέγειν; εἰ δὲ νῦν μετέγνωκας, μὴ συγκρούειν μὲν ἡμᾶς τοὺς στρατηγοὺς ἐς ἀλλήλους, Τιτίῳ δὲ σαυτὸν ἐπιτρέπειν· Τιτίῳ γὰρ ἐπιτέτραπται τὰ περὶ σὲ ὑπὸ Ἀντωνίου· καὶ πίστιν, ἣν αἰτεῖς παρ’ ἡμῶν, ἔνι σοι καὶ Τίτιον αἰτεῖν. κεκέλευσται δ’ ὑπὸ Ἀντωνίου πολεμοῦντα μέν σε κατακανεῖν, ἐγχειρίζοντα δὲ πέμπειν ἐς αὐτὸν ἐντίμως.”", "st": "5.141"}, {"sp": "N", "t": "ὁ δὲ Πομπήιος Τιτίῳ μὲν ἀχαριστίας ὠργίζετο, τὸν πόλεμον τόνδε ὑποδεξαμέμῳ πολεμήσειν πρὸς αὐτόν· ἁλόντα γὰρ αὐτὸν αἰχμάλωτον περισεσώκει. ἐπὶ δὲ τῇ ὀργῇ καὶ ἠδόξει, Πομπήιος ὤν, ἐπὶ Τιτίῳ γενέσθαι, οὐκ ἐπιφανεῖ πάνυ ἀνδρί, καὶ ὑπώπτευεν αὐτὸν ὡς οὐ βέβαιον ἔς τε τὸν τρόπον ὑπονοῶν καί τινα συγγινώσκων ἐς αὐτὸν ὕβριν παλαιὰν πρὸ τῆς εὐεργεσίας. Φουρνίῳ δ’ αὖθις ἑαυτὸν ἐπέτρεπε καὶ δέξασθαι παρεκάλει. ὡς δ’ οὐκ ἔπειθεν, ὁ δὲ καὶ Ἀμύντᾳ ἔλεγεν ἑαυτὸν ἐπιτρέψειν. τοῦ Φουρνίου δὲ φήσαντος οὐδ’ Ἀμύνταν ἂν δέξασθαι τόδε ὕβριν ἔχον ἐς τὸν ἐξ Ἀντωνίου τὸ πᾶν ἐπιτετραμμένον, διελύθησαν. καὶ τοῖς μὲν ἀμφὶ τὸν Φούρνιον δόξα ἦν, ὅτι ὁ Πομπήιος ἐξ ἀπορίας τῶν παρόντων ἑαυτὸν ἐς τὴν ἐπιοῦσαν ἡμέραν ἐκδώσει τῷ Τιτίῳ· ὁ δὲ νυκτὸς τὰ συνήθη πυρὰ καίεσθαι καταλιπὼν καὶ τοὺς σαλπιγκτὰς σημαίνειν τὰ διαστήματα τῆς νυκτός, ὥσπερ ἦν ἔθος, ἔλαθε μετὰ τῶν εὐζώνων ὑπεξελθὼν τοῦ στρατοπέδου, οἷς οὐδὲ αὐτοῖς προεῖπεν, οἷ χωρήσειν ἔμελλεν. ἐπενόει δ’ ἐπὶ θάλασσαν ἐλθὼν ἐμπρῆσαι τὸ τοῦ Τιτίου ναυτικόν. καὶ τάχα ἂν ἔδρασεν, εἰ μὴ Σκαῦρος αὐτομολήσας ἀπ’ αὐτοῦ τὴν μὲν ἔξοδον ἐμήνυσε καὶ τὴν ὁδόν, ἣν ἐφέρετο, τὴν δ’ ἐτίνοιαν οὐκ ᾔδει. τότε δὴ χιλίοις καὶ πεντακοσίοις ἱππεῦσιν Ἀμύντας ἐδίωκε τὸν Πομπήιον ἱππέας οὐκ ἔχοντα. καὶ ἐς τὸν Ἀμύνταν οἱ τοῦ Πομπηίου πλησιάσαντα μετεχώρουν, οἱ μὲν ἀποδιδράσκοντες, οἱ δὲ καὶ φανερῶς. μονούμενος οὖν ὁ Πομπήιος καὶ δεδιὼς ἤδη τὰ οἰκεῖα, ἑαυτὸν ἄνευ σπονδῶν ἐνεχείρισεν Ἀμύντᾳ, ὁ Τιτίῳ μετὰ σπονδῶν ἀδοξήσας.", "st": "5.142"}, {"sp": "N", "t": "οὕτω μὲν ἑάλω Πομπήιος Σέξστος, ὁ λοιπὸς ἔτι παῖς Πομπηίου Μάγνου, νεώτερος μὲν ὑπὸ τοῦ πατρὸς ἀπολειφθεὶς καὶ ὑπὸ τοῦ ἀδελφοῦ μειράκιον ἤδη, λαθὼν δ’ ἐπ’ ἐκείνοις ἐς πολὺ καὶ κρύφα λῃστεύων ἐν Ἰβηρίᾳ, μέχρι, πολλῶν συνδραμόντων ἐς αὐτὸν ἐπιγνωσθέντα εἶναι Πομπηίου παῖδα, ἐλῄστευέ τε φανερώτερον, καὶ μετὰ Γάιον Καίσαρα ἐπολέμησεν ἐγκρατῶς καὶ στρατὸν ἤγειρε πολὺν καὶ ναῦς καὶ χρήματα, καὶ νήσους εἷλε, καὶ θαλασσοκράτωρ τῆς ἀμφὶ τὰς δύσεις θαλάσσης ἐγένετο, καὶ τὴν Ἰταλίαν περιήνεγκεν ἐς λιμὸν καὶ τοὺς ἐχθροὺς ἐς συμβάσεις, ἃς ἤθελε. τὸ δὲ μέγιστον, ἐπίκουρος ἐν ταῖς προγραφαῖς τῇ πόλει πανώλεθρα πασχούσῃ γενόμενος περιέσωσεν ἄνδρας ἀρίστους τε καὶ πολλούς, οἳ τότε δι’ αὐτὸν ἦσαν ἐν τῇ πατρίδι. ὑπὸ δὲ θεοβλαβείας αὐτὸς οὔ ποτε ἐπεχείρησε τοῖς πολεμίοις, πολλὰ τῆς τύχης εὔκαιρα παρεχούσης, ἀλλ’ ἠμύνετο μόνον.", "st": "5.143"}, {"sp": "N", "t": "καὶ Πομπήιος μὲν τοιόσδε γενόμενος ἑαλώκει, Τίτιος δὲ τὸν μὲν στρατὸν αὐτοῦ μετεστράτευσεν Ἀντωνίῳ, αὐτὸν δὲ Πομπήιον, τεσσαρακοστὸν ἔτος βιοῦντα, ἐν Μιλήτῳ κατέκανεν, εἴτε δι’ αὑτοῦ, μηνίων ἄρα τῆς ποτὲ ὕβρεως καὶ ἀχάριστος ἐς τὴν ἔπειτα εὐεργεσίαν γενόμενος, εἴτε καὶ ἐπιστείλαντος Ἀντωνίου. εἰσὶ δ’ οἱ Πλάγκον, οὐκ Ἀντώνιον λέγοντες ἐπιστεῖλαι, καὶ νομίζουσιν ἄρχοντα Συρίας, καὶ ταῖς ἐπιστολαῖς ἐπιτετραμμένον ἐς τὰ ἐπείγοντα ἐπιγράφειν τὸν Ἀντώνιον καὶ τῇ σφραγῖδι χρῆσθαι. καὶ Πλάγκον δὲ γράψαι νομίζουσιν οἱ μὲν συνειδότος Ἀντωνίου καὶ αἰδουμένου γράψαι διὰ ὄνομα τοῦ Πομπηίου καὶ διὰ Κλεοπάτραν, εὔνως ἔχουσαν τῷ Πομπηίῳ διὰ τὸν πατέρα Μάγνον, οἱ δὲ αὑτὸν ἐφ’ ἑαυτοῦ Πλάγκον, τάδε αὐτὰ συνιδόντα καὶ φυλαξάμενον, μὴ τὴν αἰσίαν Ἀντωνίου καὶ Καίσαρος ἐς ἀλλήλους αἰδῶ Πομπήιος καὶ Κλεοπάτρα Πομπηίῳ συνεργοῦσα ἀνατράψαιεν.", "st": "5.144"}, {"sp": "N", "t": "ἀλλὰ Πομπήιος μὲν ἐτεθνήκει, Ἀντώνιος δὲ αὖθις ἐς Ἀρμενίαν ἐστράτευε, καὶ ὁ Καῖσαρ ἐπὶ Ἰλλυριούς, οἳ τὴν Ἰταλίαν ἐλῄστευον, οἱ μὲν οὐχ ὑπακούσαντές πω Ῥωμαίων, οἱ δ’ ἐν τοῖς ἐμφυλίοις ἀποστάντες. καί μοι ἔδοξε τὰ Ἰλλυρικά, οὔτε ἀκριβῶς γενόμενά μοι γνώριμα οὔτε συντελοῦντα μῆκος ἰδίας συγγραφῆς οὔτε χώραν ἔχοντα ἑτέρωθι λεχθῆναι, τοῦ χρόνου, καθ’ ὃν ἐλήφθησαν, συνάγοντος αὐτὰ ἐς τέλος, προαναγράψαι καὶ ὑποθεῖναι αὐτὰ τῇ ὁμόρῳ Μακεδονικῇ.", "st": "5.145"}], []);})();
